local function merge(defaults, given)
  if type(given) ~= "table" then return defaults end
  local out = {}
  for k, v in pairs(defaults) do out[k] = v end
  for k, v in pairs(given) do out[k] = v end
  return out
end

local function clock()
  if os and os.clock then return os.clock() end
  return nil
end

-- Engine DELTA convention (src/core/game3/collision.lua): up/down/left/right
-- = north/south/west/east.
local DIRS = {
  { name = "up",    dx = 0,  dy = -1 },
  { name = "down",  dx = 0,  dy = 1 },
  { name = "left",  dx = -1, dy = 0 },
  { name = "right", dx = 1,  dy = 0 },
}
local OPP = { up = "down", down = "up", left = "right", right = "left" }
local UP, DOWN = { 0, 1, 0 }, { 0, -1, 0 }

-- The face on one edge of cell (x0,z0)-(x1,z1): end points a (left) and b
-- (right) AS SEEN FROM OUTSIDE the face, and the outward normal.
local function edgeFor(dname, x0, x1, z0, z1)
  if dname == "down" then return { x0, z1 }, { x1, z1 }, { 0, 0, 1 } end
  if dname == "up" then return { x1, z0 }, { x0, z0 }, { 0, 0, -1 } end
  if dname == "left" then return { x0, z0 }, { x0, z1 }, { -1, 0, 0 } end
  return { x1, z1 }, { x1, z0 }, { 1, 0, 0 } -- right
end

local function sub3(a, b) return { a[1] - b[1], a[2] - b[2], a[3] - b[3] } end
local function cross3(a, b)
  return { a[2] * b[3] - a[3] * b[2], a[3] * b[1] - a[1] * b[3], a[1] * b[2] - a[2] * b[1] }
end
local function dot3(a, b) return a[1] * b[1] + a[2] * b[2] + a[3] * b[3] end
local function norm3(v)
  local l = math.sqrt(v[1] * v[1] + v[2] * v[2] + v[3] * v[3])
  if l < 1e-8 then return { 0, 1, 0 } end
  return { v[1] / l, v[2] / l, v[3] / l }
end
local function faceNormal3(p1, p2, p3) return norm3(cross3(sub3(p2, p1), sub3(p3, p1))) end

-- Deterministic [0,1) hash of two integers and a salt (exact integer math,
-- identical on every platform).
local function hash01(a, b, salt)
  local Mo = 16777213
  local h = (a * 7919 + b * 104729 + salt * 1299709 + 4099) % Mo
  h = (h * 48271) % Mo
  h = (h * 48271 + 12345) % Mo
  return h / Mo
end
local function lerp(a, b, t) return a + (b - a) * t end

-- r11 (USER REPORT, side walls: "the sides of Marts and Pokemon Centers
-- are still wrong"): the CLEAN PLASTER COLUMN (the idea of the Emerald 3DS
-- port's building models: side walls dressed from the facade's plain
-- plaster column and its corner posts; implemented here independently).
-- cands[i] = { u = the cell's 256 under texels (0xRRGGBB), o = its over
-- texels (-1 = transparent) or nil } -- the band's inner facade cells, the
-- preferred first; stats = every facade cell of the band's row (the same
-- records, the two corner cells with edge = true). The TARGET colour of
-- each texel row: a BAND row (one colour on >= 70% of the row's texels:
-- a stripe, trim, base) keeps that colour; any other row (windows, a
-- door, a logo) takes, among its colours on >= 10% of the row, those also
-- drawn in that row of the corner cells (the plaster beside the corners)
-- if any, the one most common over all such rows -- so glass, doors and
-- emblems never become a band. A slice = two adjacent texel columns of
-- one candidate, all from one layer, at most 4 of its 32 texels in the
-- ground palette `pal` (shared greys); its score = 4 per texel off its
-- row's target + 1 per row where the two columns differ. Returns the best
-- cand index, the pair's column closer to the targets (the wall samples
-- that one texel column) and its layer ("under" / "over"), or nil.
local function plainSlice(cands, pal, stats)
  stats = stats or cands
  local function vis(cd, i)
    local o = cd.o and cd.o[i]
    if o and o >= 0 then return o end
    return cd.u[i]
  end
  local cnt, edgeCnt = {}, {}
  for y = 0, 15 do cnt[y], edgeCnt[y] = {}, {} end
  for _, cd in ipairs(stats) do
    for y = 0, 15 do
      local row, erow = cnt[y], edgeCnt[y]
      for x = 0, 15 do
        local v = vis(cd, y * 16 + x + 1)
        row[v] = (row[v] or 0) + 1
        if cd.edge then erow[v] = (erow[v] or 0) + 1 end
      end
    end
  end
  local n = 16 * #stats
  local mode, band = {}, {}
  for y = 0, 15 do
    local best, bn
    for v, k in pairs(cnt[y]) do
      if not bn or k > bn or (k == bn and v < best) then best, bn = v, k end
    end
    mode[y] = best
    band[y] = bn and bn >= 0.7 * n
  end
  local glob = {}
  for y = 0, 15 do
    if not band[y] then
      for v, k in pairs(cnt[y]) do glob[v] = (glob[v] or 0) + k end
    end
  end
  for y = 0, 15 do
    if not band[y] then
      local best, bk, anyEdge = nil, nil, false
      for v, k in pairs(cnt[y]) do
        if k >= 0.1 * n and (edgeCnt[y][v] or 0) >= 2 then anyEdge = true end
      end
      for v, k in pairs(cnt[y]) do
        if k >= 0.1 * n and (not anyEdge or (edgeCnt[y][v] or 0) >= 2) then
          local g = glob[v] or 0
          if not bk or g > bk or (g == bk and v < best) then best, bk = v, g end
        end
      end
      if best then mode[y] = best end
    end
  end
  local bi, bx, bl, bs
  for ci, cd in ipairs(cands) do
    for x = 0, 14 do
      local layer, ok, sc, gnd = nil, true, 0, 0
      local off = { 0, 0 }
      for y = 0, 15 do
        for dx = 0, 1 do
          local i = y * 16 + x + dx + 1
          local o = cd.o and cd.o[i] or -1
          local l = o >= 0 and "over" or "under"
          if layer == nil then layer = l elseif layer ~= l then ok = false end
          local v = o >= 0 and o or cd.u[i]
          if pal and pal[v] then gnd = gnd + 1 end
          if v ~= mode[y] then sc = sc + 4; off[dx + 1] = off[dx + 1] + 1 end
        end
        if vis(cd, y * 16 + x + 1) ~= vis(cd, y * 16 + x + 2) then sc = sc + 1 end
        if not ok then break end
      end
      -- (a few texels may share a ground colour -- grey cobbles and grey
      -- plaster -- but not a run of ground)
      if gnd > 4 then ok = false end
      -- the wall samples ONE column of the pair (the closer to the
      -- targets): a two-column strip would alternate where they differ
      if ok and (not bs or sc < bs) then bi, bx, bl, bs = ci, off[2] < off[1] and x + 1 or x, layer, sc end
    end
  end
  return bi, bx, bl, bs
end

-- r12 (USER: "Marts and Pokemon centers sides are still wrong"): the
-- PLAIN WALL colour of a set of facade records ({ u, o }, as plainSlice):
-- the most common visible texel over rows r0..r1 that is not glass (W8's
-- three FRLG keys within 24, or blue-dominant: b >= r + 60, b >= g + 10),
-- an outline (luma < 100), a ground colour (pal) or in `avoid`. -> colour
-- | nil. plainTexel(recs, v) -> rec, x, y, fromOver: a texel of colour v
-- inside a 3 x 3 block of it (else a row of 3, else any), under art first.
local PLAIN_KEYS = { { 99, 165, 222 }, { 115, 189, 247 }, { 156, 214, 255 } }
local function plainVis(rec, i)
  local o = rec.o and rec.o[i]
  if o and o >= 0 then return o, true end
  return rec.u[i], false
end
local function plainColour(recs, r0, r1, pal, avoid)
  local cnt, best, bn = {}, nil, nil
  for _, rec in ipairs(recs) do
    for y = r0, r1 do
      for x = 0, 15 do
        local v = plainVis(rec, y * 16 + x + 1)
        local r, g, b = math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256
        local glass = b >= r + 60 and b >= g + 10
        for _, k in ipairs(PLAIN_KEYS) do
          if math.abs(r - k[1]) <= 24 and math.abs(g - k[2]) <= 24 and math.abs(b - k[3]) <= 24 then glass = true end
        end
        local luma = 0.299 * r + 0.587 * g + 0.114 * b
        if not glass and luma >= 100 and not (pal and pal[v]) and not (avoid and avoid[v]) then
          cnt[v] = (cnt[v] or 0) + 1
          if not bn or cnt[v] > bn or (cnt[v] == bn and v < best) then best, bn = v, cnt[v] end
        end
      end
    end
  end
  return best
end
local function plainTexel(recs, v)
  local bestRec, bx, by, bo, bq
  for _, rec in ipairs(recs) do
    for y = 0, 15 do
      for x = 0, 15 do
        local c0, ov = plainVis(rec, y * 16 + x + 1)
        if c0 == v then
          local q = 0
          if x > 0 and x < 15 and plainVis(rec, y * 16 + x) == v and plainVis(rec, y * 16 + x + 2) == v then
            q = 1
            if y > 0 and y < 15 then
              local all = true
              for dy = -1, 1 do
                for dx = -1, 1 do
                  if plainVis(rec, (y + dy) * 16 + x + dx + 1) ~= v then all = false end
                end
              end
              if all then q = 2 end
            end
          end
          q = q * 2 + (ov and 0 or 1)
          if not bq or q > bq then bestRec, bx, by, bo, bq = rec, x, y, ov, q end
        end
      end
    end
  end
  return bestRec, bx, by, bo
end

-- roofs-sides A (round 1: CONSOLIDATED groups 1-3, USER 2026-09-29: "sides
-- = plain wall with the facade's own pattern, never copied windows,
-- stripes, door jambs, frame seams or fake brick"): the SHARED WALL FILTER
-- of the side / back walls of buildings AND blocks. A colour can be a wall
-- colour (W, the trim T, a patch texel) only when it is not
--   glass    (W8's three FRLG keys within 24, or blue-dominant),
--   outline  (luma < 100; FRLG's outline greys 7b7b84 / 7b7b8c, whose luma
--             ~124 passed the old luma test; next to a known W: >= 60 luma
--             darker than W -- the Mart / PC panel seams, the gym frame),
--   ground   (the ground palette round the volume, and the grass keys),
--   leaf     (a foliage green, g >= r + 40 and g >= b + 45: the painted
--             bushes of the Safari rest houses -- not Celadon's mint 94ceb5
--             or the Sevii green 84c5a5, whose blue is high),
--   rock     (the map's cliff / rock palette: wallRockPalette) or
--   roof     (the roof tile's art)
-- -- except that a rock or roof colour the ground-floor wall itself uses
-- (pal.allow: >= WALL_OWN_MIN of the bottom band -- Lavender's purple
-- ad8cd6 is wall AND roof) is allowed. pal.any: anything but clear texels
-- (the last resort: a flat colour, never a facade crop).
local WALL_OUTLINE = { [0x7b7b84] = true, [0x7b7b8c] = true }
local WALL_GROUND_KEYS = { [0x73cea5] = true, [0x42b58c] = true, [0xa5e6c5] = true, [0xb5e6ce] = true }
local WALL_OWN_MIN = 0.15
local function wallRgb(v) return math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256 end
local function wallLuma(v)
  local r, g, b = wallRgb(v)
  return 0.299 * r + 0.587 * g + 0.114 * b
end
local function wallGlass(v)
  local r, g, b = wallRgb(v)
  for _, k in ipairs(PLAIN_KEYS) do
    if math.abs(r - k[1]) <= 24 and math.abs(g - k[2]) <= 24 and math.abs(b - k[3]) <= 24 then return true end
  end
  return b >= r + 60 and b >= g + 10
end
local function wallLeaf(v)
  local r, g, b = wallRgb(v)
  return g >= r + 40 and g >= b + 45
end
-- -> nil (the colour may be a wall colour) | the reason it may not
local function wallReject(v, pal)
  if v == nil or v < 0 then return "clear" end
  if pal.any then return nil end
  if wallGlass(v) then return "glass" end
  local l = wallLuma(v)
  if l < 100 or WALL_OUTLINE[v] or (pal.W and v ~= pal.W and l < wallLuma(pal.W) - 60) then return "outline" end
  if WALL_GROUND_KEYS[v] or (pal.ground and pal.ground[v]) then return "ground" end
  if wallLeaf(v) then return "leaf" end
  local own = pal.allow and pal.allow[v]
  if pal.rock and pal.rock[v] and not own then return "rock" end
  if pal.roof and pal.roof[v] and not own then return "roof" end
  return nil
end
-- The trim T shares W's hue family (per-channel chroma within 40, as the
-- patch colours) and is no glass, ground or leaf colour (review r1-17:
-- Viridian's leaf-green flower-box row 429c84 as a house's base trim).
local function wallTrimOk(t, W)
  if wallGlass(t) or WALL_GROUND_KEYS[t] or wallLeaf(t) then return false end
  local r, g, b = wallRgb(t)
  local wr, wg, wb = wallRgb(W)
  local m, wm = (r + g + b) / 3, (wr + wg + wb) / 3
  -- (FRLG's base line is a dark desaturated outline colour -- 7b7b84,
  -- 424a6b, 5a3a42 -- under any wall: a plinth line, not a colour band)
  if math.max(math.abs(r - m), math.abs(g - m), math.abs(b - m)) <= 30 and wallLuma(t) < 140 then return true end
  return math.abs((r - m) - (wr - wm)) <= 40 and math.abs((g - m) - (wg - wm)) <= 40
    and math.abs((b - m) - (wb - wm)) <= 40
end
local function wallVis(rec, i)
  local o = rec.o and rec.o[i]
  if o and o >= 0 then return o end
  return rec.u[i]
end
-- W of facade entries ({ rec, r0, r1 }: that record's texel rows r0..r1;
-- rec = { u, o }): the most common visible texel that wallReject passes,
-- preferring one that is no SKIRTING colour -- a colour found (almost) only
-- below the texel row 6 and mostly in full-width band rows (the painted
-- hedge / skirting board under the windows) -- when another qualifies.
-- -> W | nil, the rejected colour that would have won (a note) | nil
local function wallPick(entries, pal)
  local cnt, up, rowCnt, rowTot, solid = {}, {}, {}, {}, {}
  local topRej, topRejN, why = nil, 0, nil
  for _, e in ipairs(entries) do
    local rec, r0, r1 = e[1], e[2], e[3]
    for y = r0, r1 do
      local rc = rowCnt[y] or {}
      rowCnt[y] = rc
      for x = 0, 15 do
        local i = y * 16 + x + 1
        local o = rec.o and rec.o[i]
        local v = (o and o >= 0) and o or rec.u[i]
        if v and v >= 0 then
          rowTot[y] = (rowTot[y] or 0) + 1
          rc[v] = (rc[v] or 0) + 1
          cnt[v] = (cnt[v] or 0) + 1
          if y <= 5 then up[v] = (up[v] or 0) + 1 end
          -- (a SOLID outline-grey texel: its 4 neighbours in the cell are
          -- its colour -- only the outline greys need the count)
          if WALL_OUTLINE[v] and x > 0 and x < 15 and y > 0 and y < 15 and wallVis(rec, i - 1) == v and wallVis(rec, i + 1) == v
              and wallVis(rec, i - 16) == v and wallVis(rec, i + 16) == v then
            solid[v] = (solid[v] or 0) + 1
          end
        end
      end
    end
  end
  -- (band rows of a colour: rows it fills >= 85%; a skirting's are a low
  -- strip -- all at texel row >= 8, at most 4 of them: Saffron's purple
  -- base; a hut's brick wall under its eave fills rows 5-12: no skirting)
  local band, bandRows, bandTop = {}, {}, {}
  for y, rc in pairs(rowCnt) do
    for v, k in pairs(rc) do
      if k >= 0.85 * rowTot[y] then
        band[v] = (band[v] or 0) + k
        bandRows[v] = (bandRows[v] or 0) + 1
        if not bandTop[v] or y < bandTop[v] then bandTop[v] = y end
      end
    end
  end
  local best, bn, bestS, bnS
  for v, k in pairs(cnt) do
    local rj = wallReject(v, pal)
    -- (an outline grey that fills AREAS -- >= 30% solid texels -- is a grey
    -- wall: the Pokemon Tower's base, a gate's metal; lines are < 5%)
    if rj == "outline" and WALL_OUTLINE[v] and (solid[v] or 0) >= 0.3 * k then rj = nil end
    if rj then
      if k > topRejN then topRej, topRejN, why = v, k, rj end
    else
      local skirt = k >= 16 and (up[v] or 0) <= 0.1 * k and (band[v] or 0) >= 0.5 * k
        and (bandTop[v] or 0) >= 8 and (bandRows[v] or 0) <= 4
      if skirt then
        if not bnS or k > bnS or (k == bnS and v < bestS) then bestS, bnS = v, k end
      elseif not bn or k > bn or (k == bn and v < best) then
        best, bn = v, k
      end
    end
  end
  local W = best or bestS
  local note
  if topRej and (not W or topRejN > (cnt[W] or 0)) then note = string.format("%06x:%s", topRej, why) end
  if best and bestS and bnS > bn then note = (note and note .. " " or "") .. string.format("%06x:skirting", bestS) end
  local skirt
  -- This reviewed yellow/purple facade has a four-texel base band.
  -- Other detected skirt colours still require source-art review.
  if best == 0xd6ce21 and bestS == 0xa584ce and bandTop[bestS] == 9 and bandRows[bestS] == 4 then
    local top, rows = bandTop[bestS], bandRows[bestS]
    local contiguous = true
    for y = top, top + rows - 1 do
      if not rowCnt[y] or (rowCnt[y][bestS] or 0) < 0.85 * rowTot[y] then contiguous = false end
    end
    if contiguous then
      -- Preserve each native base row from one clean source column. A
      -- three-column agreement excludes corner/jamb texels; no new palette.
      local trim
      for _, e in ipairs(entries) do
        if not trim then
          local rec = e[1]
          for x = 1, 14 do
            local good, samples = true, {}
            for y = top, top + rows - 1 do
              if wallVis(rec, y * 16 + x + 1) ~= bestS then good = false end
            end
            for y = top + rows, 15 do
              local i = y * 16 + x + 1
              local v = wallVis(rec, i)
              if not v or v < 0 or not wallTrimOk(v, best)
                  or wallVis(rec, i - 1) ~= v or wallVis(rec, i + 1) ~= v then good = false end
              samples[#samples + 1] = { rec = rec, x = x, y = y,
                over = rec.o and rec.o[i] and rec.o[i] >= 0 or false }
            end
            if good then trim = samples break end
          end
        end
      end
      if trim then skirt = { color = bestS, lo = (16 - top - rows) / 16, hi = (16 - top) / 16, trim = trim } end
    end
  end
  return W, note, skirt
end
-- The per-build record of the wall filter (on IN: M.build is at LuaJIT's
-- local limit): sideFallback = structures whose sides still use facade
-- crops (the target is 0), tiers[k] = walls whose W came from tier k,
-- brick = brick patches, notes = walls where the filter turned a colour down
local function wallAStats(IN)
  if IN.wallA == nil then
    IN.wallA = { stats = { sideFallback = 0, tiers = { 0, 0, 0, 0, 0 }, brick = 0, notes = 0 } }
  end
  return IN.wallA.stats
end
-- The ROCK palette of a map: the main colours (>= 10% of a tile, not
-- near-black) of its free CLIFF cells (in no structure: the engine files
-- some gate walls as CLIFF too) and of its rock lumps (c.rock: pass 3r's
-- props), of the FRLG rock hue -- pink-brown, r >= g + 20 and g - b <= 40
-- (dec5a5 bd948c 946b6b 7b4a4a efd6c5), not the gates' tan brick (e6dea5
-- d6c584 c5ad6b: g - b >= 57), which the engine also files under CLIFF.
-- (atlas.isRock is no test: its "rock" texel class also takes the greys and
-- creams of pavements and plaster; nor is the BUILDING category: the gates
-- are BLOCKED / CLIFF.) (at, W, H, atlas.colors, compOf) -> set
local function wallRockPalette(at, W, H, colors, compOf)
  local pal, seen = {}, {}
  if type(colors) ~= "function" then return pal end
  for y = 0, H - 1 do
    for x = 0, W - 1 do
      local c = at(x, y)
      if c and not seen[c.mid] and ((c.category == "CLIFF" and compOf(c) == nil) or c.rock == true) then
        seen[c.mid] = true
        local l = colors(c.mid)
        if l then
          for i = 1, #l - 1, 2 do
            local k, f = l[i], l[i + 1]
            local r, g, b = wallRgb(k)
            if f >= 0.1 and math.max(r, g, b) >= 40 and r >= g + 20 and g - b <= 40 then pal[k] = true end
          end
        end
      end
    end
  end
  return pal
end
-- The share of a tile's texels in the rock palette (atlas.colors' top-8)
local function wallRockShare(colors, mid, pal)
  local l = type(colors) == "function" and colors(mid) or nil
  local t = 0
  if l then
    for i = 1, #l - 1, 2 do if pal[l[i]] then t = t + l[i + 1] end end
  end
  return t
end
-- A running-bond BRICK tile (USER 2026-09-29: "Oak's Lab is real brick:
-- its sides carry its brick tiled 1:1 from a clean brick area of its
-- facade") inside the clean rectangle x0..x1, y0..y1 of texels t: columns
-- periodic with a period px of 4..8 over the whole rectangle (>= 2
-- periods), rows periodic with a period py of 4..8 (>= 1.5 periods: a
-- 16-texel cell shows 1.6 courses of an 8-row brick), no smaller column
-- period (stripes), a MORTAR row (one colour across the tile) and the
-- vertical joints (mortar texels) STAGGERED between the courses -- a Mart
-- panel grid repeats its joints at the same columns; >= 3 colours, W among
-- them (>= 20%). -> { x0, x1, y0, y1, colors } | nil
local function brickTile(t, x0, x1, y0, y1, W)
  local w, h = x1 - x0 + 1, y1 - y0 + 1
  if w < 8 or h < 6 then return nil end
  local function colPer(q)
    for y = y0, y1 do
      for x = x0, x1 - q do if t[y * 16 + x + 1] ~= t[y * 16 + x + q + 1] then return false end end
    end
    return true
  end
  local px
  for q = 2, 8 do
    if 2 * q <= w and colPer(q) then px = q break end
  end
  if not px or px < 4 then return nil end
  local py
  for p = 4, 8 do
    if 2 * h >= 3 * p then
      local ok = true
      for y = y0, y1 - p do
        for x = x0, x1 do
          if t[y * 16 + x + 1] ~= t[(y + p) * 16 + x + 1] then ok = false break end
        end
        if not ok then break end
      end
      if ok then py = p break end
    end
  end
  if not py then return nil end
  -- (an even first row / column when it fits: mip level 1)
  local sy = y0
  if sy % 2 == 1 and sy + 1 + py - 1 <= y1 then sy = sy + 1 end
  local sx = x0
  if sx % 2 == 1 and sx + 1 + px - 1 <= x1 then sx = sx + 1 end
  local mortar
  for y = sy, sy + py - 1 do
    local v, one = t[y * 16 + sx + 1], true
    for x = sx + 1, sx + px - 1 do
      if t[y * 16 + x + 1] ~= v then one = false break end
    end
    if one then mortar = v break end
  end
  if not mortar then return nil end
  local sigs, nSig = {}, 0
  for y = sy, sy + py - 1 do
    local s, n = {}, 0
    for x = sx, sx + px - 1 do
      if t[y * 16 + x + 1] == mortar then n = n + 1; s[#s + 1] = x - sx end
    end
    if n > 0 and n < px then
      local key = table.concat(s, ",")
      if not sigs[key] then sigs[key] = true; nSig = nSig + 1 end
    end
  end
  if nSig < 2 then return nil end
  local colors, nc, nW = {}, 0, 0
  for y = sy, sy + py - 1 do
    for x = sx, sx + px - 1 do
      local v = t[y * 16 + x + 1]
      if not colors[v] then nc = nc + 1 end
      colors[v] = (colors[v] or 0) + 1
      if v == W then nW = nW + 1 end
    end
  end
  if nc < 3 or nW * 5 < px * py then return nil end
  return { x0 = sx, x1 = sx + px - 1, y0 = sy, y1 = sy + py - 1, colors = colors }
end

-- r12b (coordinator: the flat plain walls "read cheap" and lost the Pallet
-- house siding): the WALL PALETTE test for a wall colour W -- W itself, or
-- a texel of W's own hue family (chroma within PATCH_CHROMA of W's: its
-- siding lines, panel seams, highlights) that is not glass, an outline
-- (luma < 100), a ground colour (pal) or in `avoid` (the roof palette).
local PATCH_CHROMA = 40
local function plainOk(W, pal, avoid)
  local function rgb(v) return math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256 end
  local wr, wg, wb = rgb(W)
  local wm = (wr + wg + wb) / 3
  local memo = {}
  return function(v)
    local m = memo[v]
    if m ~= nil then return m end
    local r, g, b = rgb(v)
    local ok = v == W
    if not ok then
      local glass = b >= r + 60 and b >= g + 10
      for _, k in ipairs(PLAIN_KEYS) do
        if math.abs(r - k[1]) <= 24 and math.abs(g - k[2]) <= 24 and math.abs(b - k[3]) <= 24 then glass = true end
      end
      local mm = (r + g + b) / 3
      ok = not glass and 0.299 * r + 0.587 * g + 0.114 * b >= 100 and not (pal and pal[v]) and not (avoid and avoid[v])
        and math.abs((r - mm) - (wr - wm)) <= PATCH_CHROMA and math.abs((g - mm) - (wg - wm)) <= PATCH_CHROMA
        and math.abs((b - mm) - (wb - wm)) <= PATCH_CHROMA
        -- roofs-sides A (the shared wall filter): never an outline grey
        -- (7b7b84 / 7b7b8c, or >= 60 luma darker than W: the Mart / PC
        -- panel seams, the gym's frame), a grass key or a foliage green
        and not WALL_OUTLINE[v] and not WALL_GROUND_KEYS[v] and not wallLeaf(v)
        and 0.299 * r + 0.587 * g + 0.114 * b >= wallLuma(W) - 60
    end
    memo[v] = ok
    return ok
  end
end
-- The CLEAN WALL PATCH: the largest rectangle (area) of one facade cell's
-- texels, one layer, whose colours all pass `ok`, over `cands` ({ rec, r0,
-- r1 }: that record's rows r0..r1 only), reduced to a TILE that repeats
-- 1:1 in texel scale -- columns / rows that never change: one texel,
-- stretched (cu / cv); a periodic run of rows (the siding's line every 4
-- rows) or columns: whole periods placed INSIDE the run (the texels just
-- outside the tile continue the pattern: seamless, mip-safe); else the
-- whole rectangle (>= 4 texels). W must be >= half of the tile; a tile of
-- one colour is no patch (the flat W). -> { rec, over, x0, x1, y0, y1
-- (inclusive texels), cu, cv, colors = { [v] = texels } } | nil
local YSAFE = function() end -- Lab 59: M.build points this at deps.yieldSafe (module-level helpers below M.build's scope)
local function plainPatch(cands, W, ok)
  local rects = {}
  for ci, e in ipairs(cands) do
    YSAFE()
    local rec, r0, r1 = e[1], e[2], e[3]
    local mask = e[4] -- roofs-sides A: { [x] = true }, texel columns never in a patch
    for pass = 1, rec.o and 2 or 1 do
      YSAFE()
      local wantOver = pass == 2
      local t = wantOver and rec.o or rec.u
      local h, best = {}, nil
      for x = 0, 15 do h[x] = 0 end
      for y = r0, r1 do
        for x = 0, 15 do
          local i = y * 16 + x + 1
          local o = rec.o and rec.o[i]
          local isOver = o ~= nil and o >= 0
          local v = t[i]
          -- (a pattern texel belongs to a PATTERN -- its own colour again
          -- within 2 texels: seams, siding lines, a stucco dither; a lone
          -- dot / rivet would repeat as polka dots)
          local clean = isOver == wantOver and ok(v) and not (mask and mask[x])
          if clean and v ~= W then
            clean = false
            for dy = math.max(-2, -y), math.min(2, 15 - y) do
              for dx = math.max(-2, -x), math.min(2, 15 - x) do
                if (dx ~= 0 or dy ~= 0) and t[i + dy * 16 + dx] == v then clean = true end
              end
            end
          end
          if clean then h[x] = h[x] + 1 else h[x] = 0 end
        end
        -- (the largest rectangle ending on each row: candidates, largest
        -- first -- one failing the W test leaves the others)
        best = nil
        for x0 = 0, 15 do
          local mh = h[x0]
          if mh > 0 then
            for x1 = x0, 15 do
              local hx = h[x1]
              if hx == 0 then break end
              if hx < mh then mh = hx end
              local a = (x1 - x0 + 1) * mh
              if a >= 4 and (not best or a > best[5]) then best = { x0, x1, y - mh + 1, y, a } end
            end
          end
        end
        if best then rects[#rects + 1] = { rec, wantOver, best, (ci * 2 + pass) * 16 + y } end
      end
    end
  end
  table.sort(rects, function(p, q)
    if p[3][5] ~= q[3][5] then return p[3][5] > q[3][5] end
    return p[4] < q[4]
  end)
  for ri, R in ipairs(rects) do
    -- (roofs-sides A: the 48 largest rectangles of >= 8 texels -- a tile
    -- repeats >= 2 periods, so a smaller one yields none; the periodicity
    -- rule now rejects rects the old loop stopped at: a bounded scan)
    if ri > 48 or R[3][5] < 8 then break end
    local rec, over = R[1], R[2]
    local x0, x1, y0, y1 = R[3][1], R[3][2], R[3][3], R[3][4]
    local t = over and rec.o or rec.u
    -- roofs-sides A (USER: Oak's Lab is real brick): a running-bond brick
    -- tile of the whole clean rectangle (before its trim rows are cut: a
    -- brick course is not a trim), W >= 20% of it (brickTile)
    local bk = brickTile(t, x0, x1, y0, y1, W)
    if bk then
      return { rec = rec, over = over, x0 = bk.x0, x1 = bk.x1, y0 = bk.y0, y1 = bk.y1, cu = false, cv = false,
        colors = bk.colors, brick = true }
    end
    local function colEq(a, b)
      for y = y0, y1 do if t[y * 16 + a + 1] ~= t[y * 16 + b + 1] then return false end end
      return true
    end
    local function rowEq(a, b)
      for x = x0, x1 do if t[a * 16 + x + 1] ~= t[b * 16 + x + 1] then return false end end
      return true
    end
    -- (the rectangle's top / bottom rows where W is not the most common
    -- colour are trim, not wall -- the base's darker rows, a sill: a tile
    -- repeating them would read as stripes)
    local function wallRow(y)
      local cnt, nW, top = {}, 0, 0
      for x = x0, x1 do
        local v = t[y * 16 + x + 1]
        cnt[v] = (cnt[v] or 0) + 1
        if v == W then nW = cnt[v] elseif cnt[v] > top then top = cnt[v] end
      end
      return nW >= top
    end
    while y1 > y0 and not wallRow(y1) do y1 = y1 - 1 end
    while y0 < y1 and not wallRow(y0) do y0 = y0 + 1 end
    -- columns
    local w, cu = x1 - x0 + 1, true
    for x = x0 + 1, x1 do if not colEq(x0, x) then cu = false break end end
    local wx0, wx1 = x0, x1
    local perU, perV = false, false
    if cu then
      wx0 = math.floor((x0 + x1) / 2); wx1 = wx0
    elseif w <= 16 then
      -- (roofs-sides A: a full-width rectangle too -- Vermilion's dither)
      for q = 2, math.floor(w / 2) do
        local per = true
        for x = x0, x1 - q do if not colEq(x, x + q) then per = false break end end
        if per then wx1 = x0 + q * math.floor(w / q) - 1; perU = true break end
      end
    end
    -- rows
    local hgt, cv = y1 - y0 + 1, true
    for y = y0 + 1, y1 do if not rowEq(y0, y) then cv = false break end end
    local wy0, wy1 = y0, y1
    if cv then
      wy0 = math.floor((y0 + y1) / 2); wy1 = wy0
    else
      local bp, ba, bl
      for p = 2, math.min(8, math.floor(hgt / 2)) do
        local run, start = 0, y0
        for y = y0, y1 - p do
          if rowEq(y, y + p) then
            if run == 0 then start = y end
            run = run + 1
            local span = run + p
            if span >= 2 * p and span * 2 >= hgt and (not bl or span > bl) then
              local varied = false
              for k = start + 1, start + p - 1 do
                if not rowEq(start, k) then varied = true break end
              end
              if varied then bp, ba, bl = p, start, span end
            end
          else
            run = 0
          end
        end
      end
      if bp then
        perV = true
        local th = bp * math.floor(math.min(bl, 16) / bp)
        -- (inside the run, an even first row when it fits: mip level 1)
        local s = ba
        for k = ba + 1, ba + bl - 1 - th do
          if k % 2 == 0 then s = k break end
          if s == ba then s = k end
        end
        wy0, wy1 = s, s + th - 1
      end
      -- (a non-periodic tile framed by the same seam row top and bottom:
      -- the bottom one dropped, or the repeat doubles the seam)
      if not bp and wy1 - wy0 + 1 > 4 then
        local same = true
        for x = wx0, wx1 do if t[wy0 * 16 + x + 1] ~= t[wy1 * 16 + x + 1] then same = false break end end
        if same then wy1 = wy1 - 1 end
      end
    end
    -- (the same for a seam column left and right: the Mart's panel
    -- 'hefffffh' repeats as 'hefffff', one seam between panels)
    if not cu and not perU and wx1 - wx0 + 1 > 4 then
      local same = true
      for y = wy0, wy1 do if t[y * 16 + wx0 + 1] ~= t[y * 16 + wx1 + 1] then same = false break end end
      if same then wx1 = wx1 - 1 end
    end
    -- (a stretched texel stands for a run of >= 4: vertical stripes from a
    -- 2-row slice of a window frame are no wall pattern)
    local good = (cu and w >= 4 or wx1 - wx0 + 1 >= 4) and (cv and hgt >= 4 or wy1 - wy0 + 1 >= 4) and not (cu and cv)
    -- roofs-sides A (CONSOLIDATED group 1, USER: "never tile one-off seams,
    -- door jambs or frame edges"): a tile repeats only what repeats in its
    -- source -- in each direction one texel stretched (cu / cv) or >= 2 whole
    -- periods of the rectangle (perU / perV; a stretched row / column is
    -- itself periodic across: siding, corrugation). A once-per-cell seam,
    -- jamb or frame edge (Mart 65, PC 390, gym 338, Day Care 765, Mansion
    -- 676, One Island PC 745, Memorial Pillar 729) is no pattern: the flat W.
    good = good and (cu or perU) and (cv or perV)
    -- (inside the TILE -- its edges wrapping, as it repeats -- every
    -- pattern texel still has its colour within 2 texels: a line cut by
    -- the window would repeat as dots)
    if good and not cu and not cv then
      local tw, th = wx1 - wx0 + 1, wy1 - wy0 + 1
      for y = wy0, wy1 do
        for x = wx0, wx1 do
          local v = t[y * 16 + x + 1]
          if v ~= W then
            local near = false
            for dy = -2, 2 do
              for dx = -2, 2 do
                if dx ~= 0 or dy ~= 0 then
                  local xx = wx0 + (x - wx0 + dx) % tw
                  local yy = wy0 + (y - wy0 + dy) % th
                  if (xx ~= x or yy ~= y) and t[yy * 16 + xx + 1] == v then near = true end
                end
              end
            end
            if not near then good = false end
          end
        end
      end
    end
    -- (the largest clean area is plain W, >= 4 x 4: a PLAIN wall -- the
    -- flat W; the caller looks no further: a Viridian house's corner
    -- post is not its wall's pattern)
    if cu and cv and t[wy0 * 16 + wx0 + 1] == W and (x1 - x0 + 1) >= 4 and (y1 - y0 + 1) >= 4 then
      return nil, true
    end
    if good then
      local colors, nW, n = {}, 0, 0
      for y = wy0, wy1 do
        for x = wx0, wx1 do
          local v = t[y * 16 + x + 1]
          colors[v] = (colors[v] or 0) + 1
          n = n + 1
          if v == W then nW = nW + 1 end
        end
      end
      -- (a tile that is >= 90% W is a plain wall with a speck or two --
      -- Mt Ember's rock: the flat W, not 4-texel tiles for two dots)
      if (n - nW) * 10 < n then return nil, true end
      if nW * 2 >= n then
        return { rec = rec, over = over, x0 = wx0, x1 = wx1, y0 = wy0, y1 = wy1, cu = cu, cv = cv, colors = colors }
      end
    end
  end
  return nil
end

-- r11 (USER REPORT: "roofs seem to be messed up"): the ROOF SHAPE the art
-- implies. FRLG draws a roof's ends as strips beside the front slope: a
-- GABLE house (Pallet, Viridian, Sevii) shows its two gable sides shaded
-- differently (one lit, one in shade -- 'side profiles' of different
-- colours), a HIP / bevelled roof (the Pokemon Center, the Mart) shows two
-- sloping ends in the same colour. left / right = the roof's west and east
-- edge cells ({ u, o } texels), front = the inner roof cells of the row;
-- the side strip of a texel row = the texels from the outer edge (after
-- ground `pal` and transparent texels of a walkable cell) up to the first
-- texel of the front slope's colour (the inner cells' most common colour).
-- Returns "gable" (both strips >= 3 texels wide on average, different
-- dominant colours), "hip" (same colour) or nil.
local function roofEdgeShape(left, right, front, pal)
  local function vis(cd, i)
    local o = cd.o and cd.o[i]
    if o and o >= 0 then return o, false end
    return cd.u[i], (o and o < 0 and cd.walk) or false
  end
  -- the front slope's colour per texel row: that row's most common colour
  -- over the inner cells
  local fc = {}
  for y = 0, 15 do
    local cnt, best, bn = {}, nil, 0
    for _, fr in ipairs(front) do
      for x = 0, 15 do
        local v = vis(fr, y * 16 + x + 1)
        cnt[v] = (cnt[v] or 0) + 1
        if cnt[v] > bn then best, bn = v, cnt[v] end
      end
    end
    fc[y] = best
  end
  local function strip(cd, fromLeft)
    local hist, width, rows = {}, 0, 0
    for y = 0, 15 do
      local started, w, ended = false, 0, false
      local rh = {}
      for k = 0, 15 do
        local x = fromLeft and k or (15 - k)
        local v, clear = vis(cd, y * 16 + x + 1)
        if not started and not clear and not (pal and pal[v]) then started = true end
        if started then
          if v == fc[y] then ended = true break end
          rh[v] = (rh[v] or 0) + 1
          w = w + 1
        end
      end
      -- (a row where the front colour never starts tells nothing)
      if started and ended then
        rows = rows + 1
        width = width + w
        for v, n in pairs(rh) do hist[v] = (hist[v] or 0) + n end
      end
    end
    local dom, dn = nil, 0
    for v, n in pairs(hist) do
      if n > dn or (n == dn and v < dom) then dom, dn = v, n end
    end
    return dom, rows >= 4 and width / rows or 0
  end
  local l, lw = strip(left, true)
  local r, rw = strip(right, false)
  if not l or not r or lw < 3 or rw < 3 then return nil end
  if l ~= r then return "gable", (lw + rw) / 2 end
  return "hip", (lw + rw) / 2
end

-- r11 (refs 14, v15-v17): a roof row's FRONT colour per texel row (the
-- inner cells' most common colour) and one cell side's END STRIP per texel
-- row: from the outer edge (ground `pal` / transparent texels of a walkable
-- cell skipped) the texels up to the front colour -> { start, width }
local function roofFrontColours(front)
  local fc = {}
  for y = 0, 15 do
    local cnt, best, bn = {}, nil, 0
    for _, fr in ipairs(front) do
      for x = 0, 15 do
        local i = y * 16 + x + 1
        local o = fr.o and fr.o[i]
        local v = (o and o >= 0) and o or fr.u[i]
        cnt[v] = (cnt[v] or 0) + 1
        if cnt[v] > bn then best, bn = v, cnt[v] end
      end
    end
    fc[y] = best
  end
  return fc
end
local function roofStripRows(cd, fc, pal, fromLeft)
  local out = {}
  for y = 0, 15 do
    local started, w, s0 = false, 0, 0
    for k = 0, 15 do
      local x = fromLeft and k or (15 - k)
      local i = y * 16 + x + 1
      local o = cd.o and cd.o[i]
      local v, clear
      if o and o >= 0 then v, clear = o, false else v, clear = cd.u[i], (o and o < 0 and cd.walk) or false end
      if not started and not clear and not (pal and pal[v]) then started, s0 = true, k end
      if started then
        if v == fc[y] then out[y] = { s0, w } break end
        w = w + 1
      end
    end
  end
  return out
end

-- r11 (USER REPORT 2, the PC / Mart references): two facade cells are
-- MIRRORS when one's visible texels equal the other's flipped left-right
-- (at most 8 differences): the PC's two window cells, the Mart's two
-- emblem halves.
local function mirrorOf(a, b)
  local function vis(cd, i)
    local o = cd.o and cd.o[i]
    if o and o >= 0 then return o end
    return cd.u[i]
  end
  local diff = 0
  for y = 0, 15 do
    for x = 0, 15 do
      if vis(a, y * 16 + x + 1) ~= vis(b, y * 16 + (15 - x) + 1) then
        diff = diff + 1
        if diff > 8 then return false end
      end
    end
  end
  return true
end

-- r11 (refs 05-07): two CELLS whose art is a left-right mirror pair
-- (a symmetric facade's two edges: the PC's 88 and 407), from the atlas
-- texels; false without art
local function mirrorCells(texels, a, b)
  if not (texels and a and b) then return false end
  local ua, ub = texels(a.mid, "under"), texels(b.mid, "under")
  if not (ua and ub) then return false end
  return mirrorOf({ u = ua, o = a.hasOver and texels(a.mid, "over") or nil },
    { u = ub, o = b.hasOver and texels(b.mid, "over") or nil })
end

-- r11: the fraction of an over-art tile's west (col 0) or east (col 15)
-- edge column that is opaque -- over art that stops short of that edge
-- (a rope-post fence beside a PC: Three Island) does not reach a building
-- there; 1 without art
local function overEdgeFrac(o, west)
  if not o then return 1 end
  local n, x = 0, west and 0 or 15
  for y = 0, 15 do
    local v = o[y * 16 + x + 1]
    if v and v >= 0 then n = n + 1 end
  end
  return n / 16
end

-- The CORNER POST of an edge facade cell: from its outer edge inward, the
-- ground columns (more than 2 texels in the ground palette `pal`) are
-- skipped, then the next 2..POST_W texel columns that are all from one
-- layer and ground-free are the post, when it is a straight pillar (below).
-- `fromLeft` = the outer edge is texel
-- column 0 (the building's west cell). Returns c0, c1 (inclusive), layer.
local function cornerPost(u, o, pal, fromLeft, maxW)
  local function colInfo(x)
    local g, lay = 0, nil
    for y = 0, 15 do
      local i = y * 16 + x + 1
      local ov = o and o[i] or -1
      local l = ov >= 0 and "over" or "under"
      if lay == nil then lay = l elseif lay ~= l then lay = "mixed" end
      if pal and pal[ov >= 0 and ov or u[i]] then g = g + 1 end
    end
    return g > 2, lay
  end
  local step = fromLeft and 1 or -1
  local x = fromLeft and 0 or 15
  while x >= 0 and x <= 15 do
    local ground = colInfo(x)
    if not ground then break end
    x = x + step
  end
  if x < 0 or x > 15 or math.abs(x - (fromLeft and 0 or 15)) > 4 then return nil end
  local c0, layer = x, nil
  local c1 = nil
  while x >= 0 and x <= 15 and math.abs(x - c0) < maxW do
    local ground, l = colInfo(x)
    if ground or l == "mixed" or (layer and l ~= layer) then break end
    layer, c1 = l, x
    x = x + step
  end
  if not c1 or math.abs(c1 - c0) + 1 < 2 then return nil end
  if c0 > c1 then c0, c1 = c1, c0 end
  -- a post is a straight vertical pillar: its columns change colour at the
  -- same rows (horizontal trim bands cross it level); a chamfered corner's
  -- diagonal outline (the PC / Mart corners) shifts a row per column -- not
  -- a post
  local function vis(x, y)
    local i = y * 16 + x + 1
    return (o and o[i] and o[i] >= 0) and o[i] or u[i]
  end
  for x = c0, c1 - 1 do
    local inter, uni = 0, 0
    for y = 0, 14 do
      local ta = vis(x, y) ~= vis(x, y + 1)
      local tb = vis(x + 1, y) ~= vis(x + 1, y + 1)
      if ta or tb then uni = uni + 1 end
      if ta and tb then inter = inter + 1 end
    end
    if uni > 0 and inter < 0.75 * uni then return nil end
  end
  return c0, c1, layer
end
local function round(v) return math.floor(v + 0.5) end

-- Clip a convex polygon of {a, t} points to fn(p) >= 0.
local function clipPoly(poly, fn)
  local out, n = {}, #poly
  for i = 1, n do
    local P, Q = poly[i], poly[i % n + 1]
    local dp, dq = fn(P), fn(Q)
    if dp >= 0 then out[#out + 1] = P end
    if (dp >= 0) ~= (dq >= 0) then
      local t = dp / (dp - dq)
      out[#out + 1] = { P[1] + (Q[1] - P[1]) * t, P[2] + (Q[2] - P[2]) * t }
    end
  end
  return out
end
local function polyArea(poly)
  local s = 0
  for i = 1, #poly do
    local P, Q = poly[i], poly[i % #poly + 1]
    s = s + P[1] * Q[2] - Q[1] * P[2]
  end
  return math.abs(s) * 0.5
end

-- W7 (flora, w7/INTEGRATION_FLORA.md): the FrlgFlora context for one build
-- (tree crowns, tall grass, flowers, understory fill), or nil -- then the
-- r11 emitters below draw them. Source: deps.Flora, else M.Flora (tests set
-- it next to the mesher), else deps.require("mesh/FrlgFlora") (the mod's
-- loader). deps.flora == false turns it off; a load / construction error
-- also leaves nil (never fails the build).
-- interiors-team (build/core/API.md): the FrlgInteriors context for one
-- indoor build (4th wall, doors, ceiling, section fixes), or nil -- then the
-- mesher runs exactly as without it. Source: deps.Interiors, else
-- M.Interiors (tests), else deps.require("mesh/FrlgInteriors") (the mod's
-- loader). deps.interiors == false turns it off; a load / construction
-- error also leaves nil (never fails the build). Every method of the
-- context guards itself (pcall + latch), see FrlgInteriors.lua.
local function interiorsContext(deps, env)
  if deps.interiors == false then return nil end
  local I = deps.Interiors or M.Interiors
  if I == nil and type(deps.require) == "function" then
    local okI, mod = pcall(deps.require, "mesh/FrlgInteriors")
    if okI and type(mod) == "table" then I = mod end
  end
  if type(I) ~= "table" or type(I.new) ~= "function" then return nil end
  local okN, ctx = pcall(I.new, env)
  if okN and type(ctx) == "table" then return ctx end
  return nil
end

local function floraContext(deps, env)
  if deps.flora == false then return nil end
  local Flora = deps.Flora or M.Flora
  if Flora == nil and type(deps.require) == "function" then
    local okF, mod = pcall(deps.require, "mesh/FrlgFlora")
    if okF and type(mod) == "table" then Flora = mod end
  end
  if type(Flora) ~= "table" or type(Flora.new) ~= "function" then return nil end
  local okN, ctx = pcall(Flora.new, env)
  if okN and type(ctx) == "table" then return ctx end
  return nil
end

function M.voxelTreeContext(deps,input)
  if type(deps.require)~="function" then return nil end
  local ok,VoxelTree=pcall(deps.require,"mesh/FrlgVoxelTree")
  if not ok or type(VoxelTree)~="table" or not VoxelTree.enabled then return nil end
  return VoxelTree.context(input)
end

local function nativeFoliageContext(deps,env)
  local module=deps.NativeFoliage or M.NativeFoliage
  if not module and type(deps.require)=="function" then module=deps.require("mesh/FrlgNativeFoliage") end
  if not module then return nil end
  return assert(module.new(env),"native foliage context unavailable")
end

