local function nativeBuildingProfile(deps,input,comp,atlas)
  if comp.nativeSafariWest then return {name='safari-west-native',wallRows=2,nativeRowHeight=true,flatRoof=false,roofOverBacking=true,topArtVerified=true,nativeRoofSourceTop=2.5}end
  local profile=deps.BuildingProfiles or M.BuildingProfiles
  if not profile and type(deps.require)=="function" then
    local ok,p=pcall(deps.require,"mesh/FrlgBuildingProfiles")
    if ok then profile=p end
  end
  return type(profile)=="table" and type(profile.match)=="function" and profile.match(input,comp,atlas) or nil
end

function M.build(input, deps)
  local t0 = clock()
  deps = deps or {}
  -- r9 (review 11): optional cooperative yield (Scene._yieldPoint) between
  -- slices of work; absent -> no-op. Output is identical either way.
  local Y = type(deps.yield) == "function" and deps.yield or function() end
  -- Lab 59: finer, output-neutral checkpoints for the first-load precache (a build slice must stay short). deps.yieldSafe
  -- is Scene's checkpoint wrapped so it also works where a plain yield could not (it returns instead of raising);
  -- deps.ycount is a call counter kept on deps (this function is at LuaJIT's 200-locals limit). Without a host
  -- yield hook both are inert. Vertex emission, the grid accessor and every building loop count in.
  deps.ycount = 0
  if type(deps.yieldSafe) ~= "function" then deps.yieldSafe = function() end end
  YSAFE = deps.yieldSafe
  local MB = merge(DEFAULT_MB, deps.MB)
  local C = merge(DEFAULT_CONST, deps.Constants)

  local W, H = tonumber(input.width) or 0, tonumber(input.height) or 0
  local cellAt = input.cellAt
  local atlas = input.atlas or {}
  local isBorder = input.isBorder == true

  -- Contract: rect functions return FOUR values or a single nil
  -- (CONTRACT_CHANGES.md #1); normalized to {u0,v0,u1,v1} tables here.
  local rawUnderRect = atlas.underRect or function() return nil end
  local rawOverRect = atlas.overRect or function() return nil end
  -- r9 (review 13): one rect table per mid per build (a missing rect is
  -- cached as false). The returned tables are SHARED and read-only: every
  -- caller derives new rects (subRect / mirror) instead of editing them.
  local underCache, overCache = {}, {}
  local function underRect(mid)
    if mid == nil then return nil end
    local r = underCache[mid]
    if r == nil then
      local u0, v0, u1, v1 = rawUnderRect(mid)
      r = u0 ~= nil and { u0, v0, u1, v1 } or false
      underCache[mid] = r
    end
    return r or nil
  end
  local function overRect(mid)
    if mid == nil then return nil end
    local r = overCache[mid]
    if r == nil then
      local u0, v0, u1, v1 = rawOverRect(mid)
      r = u0 ~= nil and { u0, v0, u1, v1 } or false
      overCache[mid] = r
    end
    return r or nil
  end
  -- W3: over art needs a rect AND (when given) atlas.hasOver / coverage > 0.
  -- r8: void tiles (atlas.isVoid, CONTRACT_V2.md V2.1) produce no geometry.
  local atlasIsVoid = type(atlas.isVoid) == "function" and atlas.isVoid or nil
  local atlasIsRock = type(atlas.isRock) == "function" and atlas.isRock or nil -- r11 (review M2)
  local atlasIsLeafy = type(atlas.isLeafy) == "function" and atlas.isLeafy or nil
  local indoor = input.kind == "indoor"
  local cave = input.kind == "cave"
  local voidApplies = atlasIsVoid ~= nil and (indoor or cave or isBorder)
  -- r10: this tileset pair's 3-wide forest trees (MB.FOREST3_PAIRS), if any
  local forest3 = type(MB.FOREST3_PAIRS) == "table" and input.pair ~= nil and MB.FOREST3_PAIRS[input.pair] or nil
  local atlasHasOver = type(atlas.hasOver) == "function" and atlas.hasOver or nil
  local atlasCoverage = type(atlas.overCoverage) == "function" and atlas.overCoverage or nil
  local function overCoverage(mid) -- nil = unknown
    if not atlasCoverage then return nil end
    local cov = atlasCoverage(mid)
    return type(cov) == "number" and cov or nil
  end
  local midHasOverCache = {}
  local function midHasOver(mid)
    local v = midHasOverCache[mid]
    if v ~= nil then return v end
    v = overRect(mid) ~= nil
    if v and atlasHasOver then v = atlasHasOver(mid) and true or false end
    if v then
      local cov = overCoverage(mid)
      if cov ~= nil and cov <= 0 then v = false end
    end
    midHasOverCache[mid] = v
    return v
  end

  -- Sub-rectangle of a rect in 0..1 fractions of its own span (v grows
  -- downward: v0f=0 is the tile's top row).
  local function subRect(r, a, b, c, d)
    return { r[1] + (r[3] - r[1]) * a, r[2] + (r[4] - r[2]) * b,
             r[1] + (r[3] - r[1]) * c, r[2] + (r[4] - r[2]) * d }
  end
  local function subRectV(r, v0f, v1f) return subRect(r, 0, v0f, 1, v1f) end

  local opaque, cutoutUnder, cutoutOver, cutoutKeyed = {}, {}, {}, {}
  local minX, minY, minZ = math.huge, math.huge, math.huge
  local maxX, maxY, maxZ = -math.huge, -math.huge, -math.huge

  -- r8 cost: the emit helpers take plain numbers (no temporary point / UV
  -- tables per quad) -- identical vertices in identical order; with JIT
  -- off (Quest) table allocation dominated the build time.
  local function vN(list, x, y, z, u, v, nx, ny, nz)
    local yc = deps.ycount + 1
    if yc >= 1024 then yc = 0; deps.yieldSafe() end
    deps.ycount = yc
    list[#list + 1] = { x, y, z, u, v, nx, ny, nz }
    if x < minX then minX = x end
    if x > maxX then maxX = x end
    if y < minY then minY = y end
    if y > maxY then maxY = y end
    if z < minZ then minZ = z end
    if z > maxZ then maxZ = z end
  end
  -- r9 (review 12): one vertex table per distinct corner. Lists may hold
  -- the SAME table several times (a quad's diagonal, a crown ring shared
  -- by two bands); consumers treat vertices as read-only (CONTRACT_V2).
  local function newV(x, y, z, u, v, nx, ny, nz)
    local yc = deps.ycount + 1
    if yc >= 1024 then yc = 0; deps.yieldSafe() end
    deps.ycount = yc
    if x < minX then minX = x end
    if x > maxX then maxX = x end
    if y < minY then minY = y end
    if y > maxY then maxY = y end
    if z < minZ then minZ = z end
    if z > maxZ then maxZ = z end
    return { x, y, z, u, v, nx, ny, nz }
  end
  local function vtx(list, p, t, n)
    vN(list, p[1], p[2], p[3], t[1], t[2], n[1], n[2], n[3])
  end
  local function tri3(list, p1, t1, n1, p2, t2, n2, p3, t3, n3)
    vtx(list, p1, t1, n1)
    vtx(list, p2, t2, n2)
    vtx(list, p3, t3, n3)
  end
  -- corners 1..4 -> triangles (1,2,3) (1,3,4), one normal
  local function quadN(list, x1, y1, z1, u1, v1, x2, y2, z2, u2, v2, x3, y3, z3, u3, v3,
                       x4, y4, z4, u4, v4, nx, ny, nz)
    local a = newV(x1, y1, z1, u1, v1, nx, ny, nz)
    local b = newV(x2, y2, z2, u2, v2, nx, ny, nz)
    local c = newV(x3, y3, z3, u3, v3, nx, ny, nz)
    local d = newV(x4, y4, z4, u4, v4, nx, ny, nz)
    local n = #list
    list[n + 1], list[n + 2], list[n + 3] = a, b, c
    list[n + 4], list[n + 5], list[n + 6] = a, c, d
  end
  local function quad4(list, p1, t1, p2, t2, p3, t3, p4, t4, n)
    tri3(list, p1, t1, n, p2, t2, n, p3, t3, n)
    tri3(list, p1, t1, n, p3, t3, n, p4, t4, n)
  end
  -- p1..p4 get tile corners top-left, top-right, bottom-right, bottom-left.
  local function quad(list, p1, p2, p3, p4, uv, n)
    quadN(list, p1[1], p1[2], p1[3], uv[1], uv[2], p2[1], p2[2], p2[3], uv[3], uv[2],
      p3[1], p3[2], p3[3], uv[3], uv[4], p4[1], p4[2], p4[3], uv[1], uv[4], n[1], n[2], n[3])
  end
  -- Vertical quad from a (left) to b (right), y0..y1: the tile's top row at
  -- y1 (r7m fix: faces used to be upside down).
  local function wallQuad(list, ax, az, bx, bz, y0, y1, uv, n)
    quadN(list, ax, y0, az, uv[1], uv[4], bx, y0, bz, uv[3], uv[4],
      bx, y1, bz, uv[3], uv[2], ax, y1, az, uv[1], uv[2], n[1], n[2], n[3])
  end
  -- same end points / normals as edgeFor, without building tables
  local N_S, N_N, N_W, N_E = { 0, 0, 1 }, { 0, 0, -1 }, { -1, 0, 0 }, { 1, 0, 0 }
  local function faceQuad(list, dname, x0, x1, z0, z1, y0, y1, uv)
    if dname == "down" then wallQuad(list, x0, z1, x1, z1, y0, y1, uv, N_S)
    elseif dname == "up" then wallQuad(list, x1, z0, x0, z0, y0, y1, uv, N_N)
    elseif dname == "left" then wallQuad(list, x0, z0, x0, z1, y0, y1, uv, N_W)
    else wallQuad(list, x1, z1, x1, z0, y0, y1, uv, N_E) end
  end
  -- Horizontal rectangle; the tile's top-left texel at (x0, z0) (north-west).
  local function hQuad(list, x0, z0, x1, z1, y, uv, n)
    n = n or UP
    quadN(list, x0, y, z0, uv[1], uv[2], x1, y, z0, uv[3], uv[2],
      x1, y, z1, uv[3], uv[4], x0, y, z1, uv[1], uv[4], n[1], n[2], n[3])
  end
  -- Fan of a convex polygon {{p, t}, ...} with one normal; triangles are
  -- wound to agree with the normal.
  local function fanN(list, pts, n)
    for i = 2, #pts - 1 do
      local a, b, c = pts[1], pts[i], pts[i + 1]
      local gn = cross3(sub3(b[1], a[1]), sub3(c[1], a[1]))
      if dot3(gn, n) < 0 then b, c = c, b end
      tri3(list, a[1], a[2], n, b[1], b[2], n, c[1], c[2], n)
    end
  end

  local grid = {}
  -- r12b: a CLEAN WALL PATCH tiled 1:1 in texel scale over the vertical
  -- wall a -> b (axis-aligned; the tile's left edge toward a), y0..y1.
  -- P = { list, rect, tw, th, cu, cv }: tw / th = the tile's world size
  -- (texels / 16); cu / cv: one texel column / row stretched. Tiles are
  -- anchored in world space -- along the wall at multiples of tw, up from
  -- gy (the building's ground) at multiples of th -- so neighbouring
  -- segments, bands and walls continue one pattern.
  -- (on grid: M.build is at LuaJIT's local-variable limit)
  grid.tiledWall = function(P, ax, az, bx, bz, y0, y1, n, gy)
    local list, r, tw, th = P[1], P[2], P.tw, P.th
    local len = math.abs(bx - ax) + math.abs(bz - az)
    if len < 1e-6 or y1 <= y0 + 1e-6 then return end
    local ux, uz = (bx - ax) / len, (bz - az) / len
    local sa = ax * ux + az * uz
    local sb = sa + len
    local k = P.cu and 0 or math.floor(sa / tw + 1e-6)
    while true do
      local s0, s1, u0, u1
      if P.cu then
        s0, s1, u0, u1 = sa, sb, r[1], r[3]
      else
        if k * tw >= sb - 1e-6 then break end
        s0, s1 = math.max(sa, k * tw), math.min(sb, (k + 1) * tw)
        u0 = r[1] + (r[3] - r[1]) * (s0 - k * tw) / tw
        u1 = r[1] + (r[3] - r[1]) * (s1 - k * tw) / tw
      end
      if s1 > s0 + 1e-6 then
        local pax, paz = ax + ux * (s0 - sa), az + uz * (s0 - sa)
        local pbx, pbz = ax + ux * (s1 - sa), az + uz * (s1 - sa)
        if P.cv then
          wallQuad(list, pax, paz, pbx, pbz, y0, y1, { u0, r[2], u1, r[4] }, n)
        else
          local j = math.floor((y0 - gy) / th + 1e-6)
          while gy + j * th < y1 - 1e-6 do
            local top = gy + (j + 1) * th
            local ya, yb = math.max(y0, gy + j * th), math.min(y1, top)
            if yb > ya + 1e-6 then
              wallQuad(list, pax, paz, pbx, pbz, ya, yb,
                { u0, r[2] + (r[4] - r[2]) * (top - yb) / th, u1, r[2] + (r[4] - r[2]) * (top - ya) / th }, n)
            end
            j = j + 1
          end
        end
      end
      if P.cu then break end
      k = k + 1
    end
  end
  -- the same over a convex polygon on the plane x = xw (the gable ends):
  -- pts = { { z, y }, ... }; `dir` = +1 when the tile runs toward +z
  grid.tiledPoly = function(P, xw, pts, dir, n, gy)
    local list, r, tw, th = P[1], P[2], P.tw, P.th
    local function clip(poly, axis, lo, hi)
      local out = poly
      for pass = 1, 2 do
        local src = out
        out = {}
        for i = 1, #src do
          local p, q = src[i], src[i % #src + 1]
          local pv, qv = p[axis], q[axis]
          local pin = pass == 1 and pv >= lo - 1e-9 or pass == 2 and pv <= hi + 1e-9
          local qin = pass == 1 and qv >= lo - 1e-9 or pass == 2 and qv <= hi + 1e-9
          if pin then out[#out + 1] = p end
          if pin ~= qin then
            local lim = pass == 1 and lo or hi
            local f = (lim - pv) / (qv - pv)
            out[#out + 1] = { p[1] + (q[1] - p[1]) * f, p[2] + (q[2] - p[2]) * f }
          end
        end
        if #out < 3 then return out end
      end
      return out
    end
    -- the polygon in (s, y): s = z * dir
    local sp, smin, smax, ymin, ymax = {}, math.huge, -math.huge, math.huge, -math.huge
    for i, p in ipairs(pts) do
      sp[i] = { p[1] * dir, p[2] }
      smin, smax = math.min(smin, sp[i][1]), math.max(smax, sp[i][1])
      ymin, ymax = math.min(ymin, p[2]), math.max(ymax, p[2])
    end
    local k0 = P.cu and 0 or math.floor(smin / tw + 1e-6)
    local k1 = P.cu and 0 or math.ceil(smax / tw - 1e-6) - 1
    local j0 = P.cv and 0 or math.floor((ymin - gy) / th + 1e-6)
    local j1 = P.cv and 0 or math.ceil((ymax - gy) / th - 1e-6) - 1
    for k = k0, k1 do
      local col = P.cu and sp or clip(sp, 1, k * tw, (k + 1) * tw)
      if #col >= 3 then
        for j = j0, j1 do
          local cell = P.cv and col or clip(col, 2, gy + j * th, gy + (j + 1) * th)
          if #cell >= 3 then
            local poly = {}
            for i, q in ipairs(cell) do
              local u = P.cu and r[1] or r[1] + (r[3] - r[1]) * (q[1] - k * tw) / tw
              local v = P.cv and r[2] or r[2] + (r[4] - r[2]) * (gy + (j + 1) * th - q[2]) / th
              poly[i] = { { xw, q[2], q[1] * dir }, { u, v } }
            end
            fanN(list, poly, n)
          end
        end
      end
    end
  end
  local function at(x, y)
    local yc = deps.ycount + 1
    if yc >= 1024 then yc = 0; deps.yieldSafe() end
    deps.ycount = yc
    if x < 0 or y < 0 or x >= W or y >= H then return nil end
    return grid[y][x] or nil
  end

  -- ---------------------------------------------------------------
  -- Pass 1: read + classify every in-bounds cell.
  -- ---------------------------------------------------------------
  local permStr = type(MB.COLL_PERM) == "string" and #MB.COLL_PERM == 256 and MB.COLL_PERM or nil
  -- r8: void cells are ABSENT (like a nil cellAt): no ground, no props, no
  -- skirts toward them; voidSet remembers them (indoor sills, stats).
  local voidSet, voidCount, voidMid = {}, 0, nil
  for y = 0, H - 1 do
    if y % 4 == 0 then Y() end
    local row = {}
    grid[y] = row
    for x = 0, W - 1 do
      local raw = cellAt and cellAt(x, y) or nil
      -- r11: void only where it is correct -- interiors, caves and border
      -- rings (the space outside a map); an outdoor MAP never drops a tile
      if raw and voidApplies and atlasIsVoid(raw.mid or 0) then
        voidSet[y * W + x + 1] = true
        voidCount = voidCount + 1
        voidMid = voidMid or (raw.mid or 0)
        raw = nil
      end
      if raw then
        local mid = raw.mid or 0
        local coll = raw.collision
        if coll == nil then coll = raw.coll end
        coll = coll or 0
        local elev = raw.elevation
        if elev == nil then elev = raw.elev end
        elev = elev or 0
        local beh = raw.behavior
        if beh == nil then beh = raw.beh end
        local isWaterDeep = beh ~= nil and MB.WATER_DEEP[beh] or coll == MB.COLL_WATER
        local isWaterShallow = (not isWaterDeep) and beh ~= nil and MB.WATER_SHALLOW[beh] and elev == 1
        local isIce = beh ~= nil and MB.ICE[beh] or false
        local isGrass = beh ~= nil and MB.GRASS[beh] or false
        local ledgeDir = beh ~= nil and MB.LEDGE_DIR[beh] or nil
        local isDoor = beh ~= nil and MB.DOOR[beh] or false
        local isSign = beh ~= nil and MB.SIGN[beh] or false
        local hasOver = midHasOver(mid) and raw.layerType ~= 1
        local special = isWaterDeep or isWaterShallow or isIce or isGrass
          or ledgeDir ~= nil or isDoor or isSign
        local blocksForBlob = (coll ~= 0) and (not special)
        -- W3: tree art from the engine category, else the engine tree list.
        -- r8: never tree art indoors or in caves (mids 26-28 are the
        -- interior exit frame, not trees), whatever the category says.
        local isTreeArt
        if indoor or cave then
          isTreeArt = false
        elseif forest3 and (forest3.upper[mid] or forest3.lower[mid] or (forest3.base and forest3.base[mid])) then
          isTreeArt = true -- r10: the engine calls these BUILDING
        elseif raw.category ~= nil then
          isTreeArt = raw.category == "TREE"
        else
          isTreeArt = MB.GENERAL_TREE_MIDS ~= nil and MB.GENERAL_TREE_MIDS[mid] == true
        end
        -- r7m M1: walkable from the cell (WorldSource passes
        -- CollPermissions.isWalkable); fallback to the same engine table.
        local walkable = raw.walkable
        if walkable == nil then
          if permStr then
            local i = (math.floor(coll) % 256) + 1
            walkable = permStr:sub(i, i) == "L"
          else
            walkable = coll == 0
          end
        end
        -- r8: a WALKABLE cell is never solid, whatever its COLL byte (cave
        -- floor is COLL 0x2B: every Mt Moon / Diglett's floor cell was
        -- becoming rock -- the r7m sweep's cave blob fields).
        if walkable then blocksForBlob = false end
        -- A forest exit can draw blocked path tiles beyond its warp trigger.
        -- They remain collision-blocked, but must not become a building volume.
        if forest3 and forest3.ground and forest3.ground[mid] then blocksForBlob = false end
        row[x] = {
          x = x, y = y, mid = mid, coll = coll, elev = elev, beh = beh,
          walkable = walkable and true or false,
          isWater = (isWaterDeep or isWaterShallow) and true or false,
          isWaterDeep = isWaterDeep, isWaterShallow = isWaterShallow,
          isIce = isIce, isGrass = isGrass, ledgeDir = ledgeDir,
          isDoor = isDoor, isSign = isSign, hasOver = hasOver,
          isTreeArt = isTreeArt, category = raw.category,
          blocksForBlob = blocksForBlob, compId = false,
          -- r11 (review M10): a water cell the engine blocks (coll 0x07 on
          -- a water behaviour: Route 12 / Vermilion sea rocks) is a rock
          -- standing in the water
          waterRock = (isWaterDeep or isWaterShallow) and coll == 0x07 and not indoor and not cave and not frWaterShip(input,mid) or nil,
        }
      else
        row[x] = false
      end
    end
  end

  -- r8: an INDOOR border ring (the space around a room; WorldSource already
  -- drops its void cells) emits nothing at all.
  local indoorBorderCleared = 0
  if indoor and isBorder then
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        if grid[y][x] then indoorBorderCleared = indoorBorderCleared + 1 end
        grid[y][x] = false
      end
    end
  end

  -- ---------------------------------------------------------------
  -- Pass 1b (r7m M1): resolve heights. Sources = walkable, non-water cells
  -- with elevation 1..14. Other non-water cells with elevation 1..14 keep
  -- their own tag as height (border rings, tagged cliffs). Everything else
  -- (elevation 0/15: trees, buildings, doors, signs, ledges, fences) takes
  -- the height of its nearest source by 4-neighbour BFS distance, the
  -- higher one on a tie. Water: each connected water region sits
  -- WATER_DEPTH (SHALLOW_WATER_DEPTH) below its lowest bank. Cells no
  -- source reaches fall back to elevation * ELEV_UNIT ("fallback").
  -- nearMid = the tile of that nearest source (ground under props, M2).
  -- ---------------------------------------------------------------
  -- r8 (M1 gap, w3 sweep: 25 cells in 10 maps sat below a walkable
  -- neighbour that was itself tagged 0/15): TWO phases. Phase 1 resolves
  -- walkable 0/15 cells from the true sources; phase 2 then resolves every
  -- other cell from ALL walkable cells (sources + phase-1 results), so a
  -- blocked cell next to any walkable cell takes the highest adjacent one.
  Y()
  do
    -- multi-source 4-neighbour BFS; ties take the higher height
    local function bfs(seed)
      local queue, head, dist, bh, bm = {}, 1, {}, {}, {}
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if c then
            local h, m = seed(c)
            if h then
              local k = y * W + x + 1
              dist[k], bh[k], bm[k] = 0, h, m
              queue[#queue + 1] = k
            end
          end
        end
      end
      while head <= #queue do
        local k = queue[head]
        head = head + 1
        local x, y = (k - 1) % W, math.floor((k - 1) / W)
        local d = dist[k]
        for _, dd in ipairs(DIRS) do
          local nx, ny = x + dd.dx, y + dd.dy
          if at(nx, ny) then
            local nk = ny * W + nx + 1
            if dist[nk] == nil then
              dist[nk], bh[nk], bm[nk] = d + 1, bh[k], bm[k]
              queue[#queue + 1] = nk
            elseif dist[nk] == d + 1 and bh[k] > bh[nk] then
              bh[nk], bm[nk] = bh[k], bm[k]
            end
          end
        end
      end
      return bh, bm
    end
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and not c.isWater and c.elev >= 1 and c.elev <= 14 then
          c.hgt, c.hgtSource = c.elev * C.ELEV_UNIT, "own"
        end
      end
    end
    local h1, m1 = bfs(function(c)
      if c.walkable and c.hgtSource == "own" then return c.hgt, c.mid end
    end)
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.walkable and not c.isWater and c.hgt == nil and h1[y * W + x + 1] then
          c.hgt, c.hgtSource = h1[y * W + x + 1], "resolved"
        end
      end
    end
    local h2, m2 = bfs(function(c)
      if c.walkable and not c.isWater and c.hgt ~= nil then return c.hgt, c.mid end
    end)
    -- r11 (USER REPORT: "ground broken by trees"): the ground under a
    -- prop is the nearest PLAIN walkable tile -- not tall grass, a flower,
    -- over art, a ledge, a door / sign or tree art (Route 1's tree column
    -- beside the grass drew the flat tall-grass tile under its trees)
    -- (outdoors only: interior floors keep their r8 rule)
    local _, m3 = bfs(function(c)
      if not indoor and not cave and c.walkable and not c.isWater and c.hgt ~= nil and not c.isGrass and not c.hasOver and not c.ledgeDir
          and not c.isDoor and not c.isSign and not (MB.FLOWER_MIDS and MB.FLOWER_MIDS[c.mid])
          and not (MB.GENERAL_TREE_MIDS and MB.GENERAL_TREE_MIDS[c.mid]) then
        return c.hgt, c.mid
      end
    end)
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c then
          local k = y * W + x + 1
          c.nearMid = m3[k] or m1[k] or m2[k]
          if not c.isWater and c.hgt == nil then
            if h2[k] ~= nil then
              c.hgt, c.hgtSource = h2[k], "resolved"
            else
              c.hgt, c.hgtSource = c.elev * C.ELEV_UNIT, "fallback"
            end
          end
        end
      end
    end
    -- Exact native layer ownership may exclude projected roof cells from
    -- shoreline measurements without changing their raw tags or land heights.
    do local provider=deps.BuildingProfiles or M.BuildingProfiles
      if not provider and type(deps.require)=='function'then local ok,p=pcall(deps.require,'mesh/FrlgBuildingProfiles');if ok then provider=p end end
      grid.nativeSeaBankProfile=provider and provider.water and provider.water(input,nil,atlas)or nil
    end
    -- water regions
    -- r9 (review 6): the bank is the lowest walkable / resolved neighbour;
    -- blocked own-tagged neighbours (a rock in a pond) count only when the
    -- region has no other bank.
    -- r10 (review 2 "variant C", replaces the r9 own-tag rule): a region
    -- touching the input's edge continues into the next map; WorldSource
    -- floods each water body across map connections and passes
    -- input.edgeWaterBank(x, y) = the body's lowest bank (elevation tag).
    -- A map's edge region uses min(its bank, that); a border ring's region
    -- COPIES it (the map's sea height next to it). So one sea has one
    -- height across every seam while shores keep the lowest-bank level
    -- (Pallet: 0.60). Without edgeWaterBank: the lowest bank (M1); a ring
    -- region with neither bank nor edgeWaterBank: max(1, lowest tag).
    local ewbFn = type(input.edgeWaterBank) == "function" and input.edgeWaterBank or nil
    local seen = {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.isWater and not seen[c] then
          local region, stack, bank, bankOwn = {}, { c }, nil, nil
          local ewb, minElev = nil, c.elev
          seen[c] = true
          while #stack > 0 do
            local w = stack[#stack]
            stack[#stack] = nil
            region[#region + 1] = w
            if ewbFn and (isBorder or w.x == 0 or w.y == 0 or w.x == W - 1 or w.y == H - 1) then
              local ok, t = pcall(ewbFn, w.x, w.y)
              t = ok and tonumber(t) or nil
              if t and (ewb == nil or t < ewb) then ewb = t end
            end
            if w.elev < minElev then minElev = w.elev end
            for _, dd in ipairs(DIRS) do
              local nc = at(w.x + dd.dx, w.y + dd.dy)
              if nc then
                if nc.isWater then
                  if not seen[nc] then seen[nc] = true; stack[#stack + 1] = nc end
                elseif nc.hgtSource ~= "fallback" and not(grid.nativeSeaBankProfile and grid.nativeSeaBankProfile.skipBanks[nc.x..':'..nc.y])then
                  if not nc.walkable and nc.hgtSource == "own" then
                    if bankOwn == nil or nc.hgt < bankOwn then bankOwn = nc.hgt end
                  elseif bank == nil or nc.hgt < bank then
                    bank = nc.hgt
                  end
                end
              end
            end
          end
          bank = bank or bankOwn
          local base
          if ewb then
            local e = ewb * C.ELEV_UNIT
            if isBorder or not bank then base = e else base = math.min(bank, e) end
          elseif isBorder and not bank then
            base = math.max(1, minElev) * C.ELEV_UNIT
          else
            base = bank
          end
          for _, w in ipairs(region) do
            -- (r12: an interior's water is a recessed POOL, POOL_DEPTH down)
            w.hgt = (base or (w.elev * C.ELEV_UNIT)) - (indoor and C.POOL_DEPTH or (w.isWaterDeep and C.WATER_DEPTH or C.SHALLOW_WATER_DEPTH))
            w.hgtSource = base and "water" or "fallback"
          end
        end
      end
    end
  end

  -- ---------------------------------------------------------------
