            local r = ramped[c]
            if not r then r = { 0, 0, 0, 0 }; ramped[c] = r; order[#order + 1] = c end
            local cs = { { x, y }, { x + 1, y }, { x + 1, y + 1 }, { x, y + 1 } }
            local raises = false
            for k = 1, 4 do
              -- s = the corner's signed distance across the run (> 0: the
              -- upper side); the exit side of the line: a ledge cell's plane
              -- is extended to its curb below; a path cell descends to the
              -- street at the exit edge (LEDGE_DEPTH in front of the line)
              local s = (cs[k][1] - sg[1]) * sg[5] + (cs[k][2] - sg[2]) * sg[6]
              local o
              if s >= 0 or c.ledgeDir then
                o = sg[7] * math.max(0, 1 - math.abs(s) / L)
              else
                o = sg[7] * math.max(0, 1 + s / C.LEDGE_DEPTH)
              end
              if o > 0 then raises = true end
              if o > r[k] then r[k] = o end
            end
            -- (the tests' view: stats.rampInfo[y * W + x + 1] = { dir =
            -- the hop direction, or "multi" where runs of two directions
            -- meet; ext = the cell lies past a run's end }). r13b (verifier
            -- r1: Route 4 (47,5) (50,5) (65,7) (68,7), Route 7 (8,8) kept the
            -- image-20 wall): only a segment that RAISES a corner of the
            -- cell counts -- a side ledge LEDGE_RAMP or more away reaches
            -- the gap between two down runs with offset 0 and used to mark
            -- it "multi" (no bank)
            if raises then
              local dirOf = sg[6] == -1 and "down" or (sg[6] == 1 and "up" or (sg[5] == 1 and "left" or "right"))
              local info = grid.rampInfo[y * W + x + 1]
              if not info then
                info = { dir = dirOf, ext = lat > 0 }
                grid.rampInfo[y * W + x + 1] = info
              else
                if info.dir ~= dirOf then info.dir = "multi" end
                info.ext = info.ext and lat > 0
              end
            end
          end
        end
      end
    end
    -- (a cell beside a solid keeps its hill only where the hill leaves the
    -- shared edge at the ground: both corners on it unraised)
    if grid.soldEdge then
      local EC = { up = { 1, 2 }, right = { 2, 3 }, down = { 3, 4 }, left = { 4, 1 } }
      for c, se in pairs(grid.soldEdge) do
        local r = ramped[c]
        if r and not c.ledgeDir then
          local drop = false
          for nm in pairs(se) do
            if r[EC[nm][1]] > 1e-6 or r[EC[nm][2]] > 1e-6 then drop = true end
          end
          if drop then
            r[1], r[2], r[3], r[4] = 0, 0, 0, 0
            grid.rampInfo[c.y * W + c.x + 1] = nil
          end
        end
      end
      grid.soldEdge = nil
    end
    for _, c in ipairs(order) do
      local r = ramped[c]
      if r[1] + r[2] + r[3] + r[4] > 1e-4 then
        c.baseHgt = c.hgt
        c.rampH = { c.hgt + r[1], c.hgt + r[2], c.hgt + r[3], c.hgt + r[4] }
        c.hgt = c.hgt + (r[1] + r[2] + r[3] + r[4]) / 4
        if c.ledgeDir then
          -- a ledge cell's ground plane runs from its far edge up to the
          -- curb's back edge at the lip top; its exit-edge corners are that
          -- plane extended (the ground and skirts are clipped at the curb)
          local ex = EX[c.ledgeDir]
          local topH = c.baseHgt + (c.ledgeLip or Hh)
          local f = 1 - C.LEDGE_DEPTH
          for k = 1, 2 do
            local far = c.rampH[ex[k + 2]]
            c.rampH[ex[k]] = far + (topH - far) / f
          end
          c.hgt = c.baseHgt + (r[1] + r[2] + r[3] + r[4]) / 4
        end
        grid.rampCells = grid.rampCells + 1
      end
    end
    -- the HEIGHT (heightAt) follows the hill, except beside water (the
    -- bank step stays); stats.hillBase[y * W + x + 1] = a hill cell's
    -- height before the hill (the M1 checks compare solids against it: a
    -- tree beside a run's end is not "sunk" -- the hill rose next to it)
    grid.hillBase = {}
    for _, c in ipairs(order) do
      if c.rampH then
        for _, d in ipairs(DIRS) do
          local n = at(c.x + d.dx, c.y + d.dy)
          if n and n.isWater then c.hgt = c.baseHgt end
        end
        grid.hillBase[c.y * W + c.x + 1] = c.baseHgt
      end
    end
    -- r13 (USER, image 20: "smooth this out"): LEDGE-END BANKS. Where a
    -- run ends beside a hill path cell n (one hop direction, past the run's
    -- end, same base, its corners on the ledge cell's lattice, its exit
    -- corner at the street), the end ledge cell is BANKED toward the path:
    -- r13c: its rounded end sits on the path's plane and its ground's
    -- shoulder sinks to the path's edge (the curb closure / the hill bands
    -- pass) -- no side wall, no sliver. The path cells are untouched
    -- (report 1 stays fixed). c.ledgeBank[sg] = c.ledgeBank[side name] = {
    -- sg, gF = the path's rise over one cell, gD = its height at the curb's
    -- back line (above the base), hE / hF = its exit / far corner on that
    -- side }. stats.ledgeEnds[i] = { x, y, dir, sg, side, bank, why (not
    -- banked: nbr / multi / base / lattice / exit / switch), gap (banked:
    -- "bridge" = a hill cell beyond n, "open" = the hill ends at n's far
    -- side: its edge band rounds it off) }.
    local D = C.LEDGE_DEPTH
    for _, c in ipairs(order) do
      local d = c.ledgeDir
      if d and c.rampH then
        local horiz = d == "down" or d == "up"
        local ax, az = horiz and 1 or 0, horiz and 0 or 1
        local ex, b = EX[d], c.baseHgt
        for sg = -1, 1, 2 do
          local n = at(c.x + sg * ax, c.y + sg * az)
          if not (n and (n.ledgeDir or n.curbDir) == d) then
            local side = horiz and (sg > 0 and "right" or "left") or (sg > 0 and "down" or "up")
            local e = { x = c.x, y = c.y, dir = d, sg = sg, side = side, bank = false }
            local ri = grid.rampInfo[c.y * W + c.x + 1]
            local rn = n and grid.rampInfo[n.y * W + n.x + 1]
            local kc, kn = ex[sg > 0 and 4 or 3], ex[sg > 0 and 3 or 4]
            -- (r13b: the ledge cell's own info may be "multi" -- a side run's
            -- hill raising its far corners, Route 4 (65,7); the PATH cell
            -- must be one direction, past the end)
            if not n or n.ledgeDir or n.curbDir or not n.rampH then e.why = "nbr"
            elseif not ri or not rn or rn.dir ~= d or not rn.ext then e.why = "multi"
            elseif math.abs(n.baseHgt - b) >= 1e-6 then e.why = "base"
            elseif math.abs(c.rampH[kc] - n.rampH[kn]) >= 1e-6 then e.why = "lattice"
            elseif math.abs(n.rampH[ex[sg > 0 and 1 or 2]] - b) >= 1e-6 then e.why = "exit"
            elseif C.LEDGE_END_BANK == false then e.why = "switch"
            else
              local hE, hF = n.rampH[ex[sg > 0 and 1 or 2]], n.rampH[kn]
              local bk = { sg = sg, gF = hF - hE, gD = (hF - hE) * D, hE = hE, hF = hF, n = n }
              c.ledgeBank = c.ledgeBank or {}
              c.ledgeBank[sg], c.ledgeBank[side] = bk, bk
              e.bank = true
              grid.bankPath[n] = true
              local away = at(n.x + sg * ax, n.y + sg * az)
              e.gap = (away and away.rampH) and "bridge" or "open"
            end
            grid.ledgeEnds[#grid.ledgeEnds + 1] = e
          end
        end
      end
    end
  end)() end

  -- Exact native gray gate visual ownership, after the native solver.
  -- First unit only; raw input/collision/elevation/hgt are never changed.
  do
    local N=deps.NativeGrayGate or M.NativeGrayGate
    if not N and type(deps.require)=="function"then local ok,v=pcall(deps.require,"mesh/NativeGrayGate");if ok then N=v end end
    if C.DOOR_INSET==.12 and C.WALL_ROW_UNIT==1 and C.FLAT_ROOF_PARAPET==.25 and type(N)=="table"and type(N.guard)=="function"and type(N.geometry)=="function"then
      local ok,q=pcall(N.guard,input,atlas)
      if ok and type(q)=="table"then
        local claimed=0
        for y=7,11 do for x=59,64 do local c=at(x,y)
          c.blocksForBlob=false;c.hasOver=false;c.groundMid=8;c.nativeGrayGateSource=true;claimed=claimed+1
        end end
        for _,x in ipairs{58,65}do
          for y=8,9 do at(x,y).hasOver=false;at(x,y).nativeGrayGateOverSource=true end
          for y=10,11 do local c=at(x,y);c.groundMid=x==58 and 219 or 220;c.suppressDecal=true;c.nativeGrayGateFrame=true end
        end
        grid.nativeGrayGate={module=N,source=q,claimed=claimed}
      end
    end
  end

  -- One guarded visual house across Five Island's east connection. The
  -- native solver above owns collision/support; this owns only source artwork.
  do
    local H=deps.ConnectedHouseNative or M.ConnectedHouseNative
    if not H and type(deps.require)=="function"then local ok,v=pcall(deps.require,"mesh/FrlgConnectedHouseNative");if ok then H=v end end
    if type(H)=="table"and type(H.guard)=="function"and type(H.claims)=="function"and type(H.geometry)=="function"then
      local ok,q=pcall(H.guard,input,atlas,deps.yieldSafe)
      if ok and type(q)=="table"then
        local count=0
        for y=6,9 do for x=0,W-1 do if H.claims(q,input.mapId,x,y)then local c=at(x,y)
          if c then
            if y>6 or input.mapId=="FR_FIVE_ISLAND_MEADOW"then c.blocksForBlob=false
            elseif not c.walkable then c.peeledBush=true end -- preserve original641/644 UNDER crowns
            c.hasOver=false;c.nativeConnectedHouseSource=true
            if y==9 then c.groundMid=q.groundDonor.mid end
            count=count+1
          end
        end end end
        grid.nativeConnectedHouse={module=H,source=q,claimed=count}
      end
    end
  end

  -- Connected Tower visual ownership is admitted only after the ordinary
  -- native support solver. Native collision/elevation/hgt remain unchanged.
  do
    local T=deps.TowerNative or M.TowerNative
    if not T and type(deps.require)=="function"then local ok,v=pcall(deps.require,"mesh/FrlgTowerNative");if ok then T=v end end
    if type(T)=="table"and type(T.guard)=="function"and type(T.claims)=="function"and type(T.geometry)=="function"then
      local ok,q=pcall(T.guard,input,atlas,deps.yieldSafe)
      if ok and type(q)=="table"then
        local count=0
        for y=0,H-1 do for x=0,W-1 do
          if T.claims(q,input.mapId,x,y)then
            local c=at(x,y)
            if c then
              c.blocksForBlob=false;c.hasOver=false;c.isDoor=false;c.isSign=false
              c.groundMid=q.groundDonor.mid;c.nativeTowerSourceOnly=true
              count=count+1
            end
          end
        end end
        grid.nativeTower={module=T,source=q,claimed=count}
      end
    end
  end

  -- ---------------------------------------------------------------
  -- Pass 2: connected components over blocksForBlob cells (W3: tree art
  -- and non-tree cells never share a component) + mid diversity.
  -- ---------------------------------------------------------------
  Y()
  -- r11 (review M1/M2): an engine-CLIFF cell right above a door whose art is
  -- not rock art is a building facade, not a cliff (the Route 2 gate's
  -- row 45: 693..695 over the door at (18,46)); so is the CLIFF run it sits
  -- in while the art continues (metatile step <= 2). A cave mouth's cliff
  -- is rock art and stays a cliff. c.cliffCat is
  -- the cliff class the passes below use.
  for y = 0, H - 1 do
    for x = 0, W - 1 do
      local c = grid[y][x]
      if c then c.cliffCat = c.category == "CLIFF" end
    end
  end
  if atlasIsRock and not indoor and not cave then
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        local below = c and at(x, y + 1)
        if c and c.cliffCat and below and below.isDoor and not atlasIsRock(c.mid) then
          c.cliffCat = false
          for _, s in ipairs({ -1, 1 }) do
            local xx, prev = x + s, c
            while true do
              local q = at(xx, y)
              -- the run continues while the art does (metatile step <= 2)
              if not (q and q.cliffCat and math.abs(q.mid - prev.mid) <= 2) then break end
              q.cliffCat = false
              prev = q
              xx = xx + s
            end
          end
        end
      end
    end
  end
  local components, compList = {}, {}
  local nextId = 0
  for y = 0, H - 1 do
    for x = 0, W - 1 do
      local c = grid[y][x]
      if c and c.blocksForBlob and c.compId == false then
        nextId = nextId + 1
        local id = nextId
        local comp = { id = id, minX = x, maxX = x, minY = y, maxY = y, count = 0, cells = {}, mids = {} }
        components[id] = comp
        compList[#compList + 1] = comp
        local stack = { c }
        c.compId = id
        while #stack > 0 do
          local pc = stack[#stack]
          stack[#stack] = nil
          comp.count = comp.count + 1
          comp.cells[#comp.cells + 1] = pc
          comp.mids[pc.mid] = true
          if pc.x < comp.minX then comp.minX = pc.x end
          if pc.x > comp.maxX then comp.maxX = pc.x end
          if pc.y < comp.minY then comp.minY = pc.y end
          if pc.y > comp.maxY then comp.maxY = pc.y end
          for _, d in ipairs(DIRS) do
            local nc = at(pc.x + d.dx, pc.y + d.dy)
            -- r11: engine CLIFF cells and other solids never share a
            -- component either (a Pokemon Center against a cliff, Lavender's
            -- tower between cliff walls, the Power Plant on Route 10)
            if nc and nc.blocksForBlob and nc.compId == false and nc.isTreeArt == c.isTreeArt
                and nc.cliffCat == c.cliffCat then
              nc.compId = id
              stack[#stack + 1] = nc
            end
          end
        end
        comp.treeArt = c.isTreeArt and true or false
        comp.cliff = c.cliffCat
      end
    end
  end

  -- r11 (review M1): ONE BUILDING PER DOOR. A solid component (not tree
  -- art, not CLIFF) that holds several buildings -- a Pokemon Center
  -- between houses, a Mart against the Center, a house under the city
  -- wall -- is split before classification. Each front door (a door cell
  -- with the component right above it) claims its front row: the door row
  -- left and right while the cells are the component's (door / sign cells
  -- count) and of the door's metatile FAMILY (famOf: the general
  -- tileset's PC / Mart art, other primary art -- walls, fences, rock --,
  -- secondary art); then every component cell above those
  -- columns up to the first foreign-family cell without over art (the
  -- city wall behind a house; a PC's roof edge drawn in secondary art has
  -- over art and stays). Two doors whose rows meet split at the column
  -- boundary where the art stops continuing (horizontal metatile steps
  -- other than 0 / +1), nearest their midpoint on ties; a boundary with
  -- continuing art (>= 50% of rows) keeps them one building. Unclaimed
  -- cells split into their connected parts. Data only: doors, metatile
  -- ids, over art.
  -- (M.build is near LuaJIT's 200-locals limit: helpers share SQ4 and a
  -- few scoped upvalues)
  local SQ4 = { { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }
  local famOf
  do
    local PCMART = MB.PCMART_RANGES or { { 40, 99 }, { 390, 415 } }
    local SEC0 = MB.SECONDARY_MID_BASE or 640
    famOf = function(mid)
      if mid >= SEC0 then return 2 end
      for _, r in ipairs(PCMART) do
        if mid >= r[1] and mid <= r[2] then return 1 end
      end
      return 0
    end
  end
  local splitPieces = 0
  if not indoor and not cave then
    local newList = {}
    local function newComp(cells)
      nextId = nextId + 1
      local pc = { id = nextId, minX = math.huge, maxX = -math.huge, minY = math.huge, maxY = -math.huge,
        count = #cells, cells = cells, mids = {}, treeArt = false, cliff = false }
      for _, c in ipairs(cells) do
        c.compId = nextId
        pc.mids[c.mid] = true
        if c.x < pc.minX then pc.minX = c.x end
        if c.x > pc.maxX then pc.maxX = c.x end
        if c.y < pc.minY then pc.minY = c.y end
        if c.y > pc.maxY then pc.maxY = c.y end
      end
      components[nextId] = pc
      newList[#newList + 1] = pc
      return pc
    end
    for _, comp in ipairs(compList) do
      local doors = {}
      if not comp.treeArt and not comp.cliff and comp.count >= 2 then
        local seenD = {}
        for _, c in ipairs(comp.cells) do
          local d = at(c.x, c.y + 1)
          if d and d.isDoor and not d.blocksForBlob and not seenD[d] then
            seenD[d] = true
            doors[#doors + 1] = d
          end
        end
      end
      if #doors == 0 then
        newList[#newList + 1] = comp
      else
        local inC = {}
        for _, c in ipairs(comp.cells) do inC[c] = true end
        table.sort(doors, function(a, b)
          if a.y ~= b.y then return a.y < b.y end
          return a.x < b.x
        end)
        local function frontCell(x, y, fam, door)
          local c = at(x, y)
          if not c then return false end
          if c.isDoor and not c.blocksForBlob then return c == door end
          if not (inC[c] or (c.isSign and not c.blocksForBlob)) then return false end
          -- the front row is facade: strictly the door's family (a PC's
          -- over-art column beside a house is not the house's)
          return famOf(c.mid) == fam
        end
        local blds = {}
        for _, d in ipairs(doors) do
          -- the building's family: its facade beside the door (a glass
          -- door from the primary set sits in secondary facades: Celadon)
          -- (the wall right above the door first; a generic primary house
          -- in Saffron has a secondary porch beside its door)
          local fam, dfam, nfam = nil, famOf(d.mid), nil
          local above = at(d.x, d.y - 1)
          if above and inC[above] then fam = famOf(above.mid) end
          for _, s in ipairs({ -1, 1 }) do
            local n = at(d.x + s, d.y)
            if n and (inC[n] or (n.isSign and not n.blocksForBlob)) then
              local f = famOf(n.mid)
              if f == dfam and not fam then fam = f end
              nfam = nfam or f
            end
          end
          fam = fam or nfam or dfam
          -- a front-row cell has no wall of the same family south of it:
          -- the row stops where it runs over another building's wall
          -- (Pewter: the house east of the museum has its door two rows
          -- up); a bush or fence in front does not stop it. The cells
          -- right beside the door are its frame, whatever their family.
          local function goes(x, s)
            local q = at(x + s, d.y)
            if x == d.x and q and inC[q] then
              local south = at(x + s, d.y + 1)
              return not (south and inC[south] and famOf(south.mid) == fam)
            end
            if not frontCell(x + s, d.y, fam, d) then return false end
            local south = at(x + s, d.y + 1)
            return not (south and inC[south] and famOf(south.mid) == fam)
          end
          local l, r = d.x, d.x
          while goes(l, -1) do l = l - 1 end
          while goes(r, 1) do r = r + 1 end
          blds[#blds + 1] = { door = d, fam = fam, l = l, r = r, y = d.y }
        end
        -- neighbouring doors on one row whose spans meet: split or merge
        for i = 1, #blds - 1 do
          local a, b = blds[i], blds[i + 1]
          if a.y == b.y and not a.merged and a.r >= b.door.x - 1 and b.l <= a.door.x + 1 then
            local best, bestK, bestD
            for bx = a.door.x, b.door.x - 1 do
              local n, k = 0, 0
              for y = a.y - 8, a.y do
                local p, q = at(bx, y), at(bx + 1, y)
                if p and q and inC[p] and inC[q] then
                  n = n + 1
                  local s = q.mid - p.mid
                  if s == 0 or s == 1 then k = k + 1 end
                end
              end
              local kk = n > 0 and k / n or 1
              local dd = math.abs(bx + 0.5 - (a.door.x + b.door.x) / 2)
              if best == nil or kk < bestK - 1e-9 or (math.abs(kk - bestK) < 1e-9 and dd < bestD) then
                best, bestK, bestD = bx, kk, dd
              end
            end
            -- (a double door -- two door cells side by side -- is one
            -- building's opening: always merged)
            if bestK >= 0.5 or b.door.x == a.door.x + 1 then
              b.l, b.merged, b.into = a.l, true, a
              a.r = math.max(a.r, b.r)
            else
              a.r, b.l = math.min(a.r, best), math.max(b.l, best + 1)
            end
          end
        end
        local claim = {}
        local groups = {}
        for _, bd in ipairs(blds) do
          local owner = bd
          while owner.into do owner = owner.into end
          local g = groups[owner]
          if not g then
            g = {}
            groups[owner] = g
            groups[#groups + 1] = owner
          end
          if not bd.merged then
            -- row by row upward: each open column continues while its
            -- cell is claimable; a row also grows sideways while the art
            -- continues (metatile step 0..+2 from the claimed neighbour,
            -- same family): the generic primary house's front corners
            -- are walkable, its upper rows are wider
            local function claimable(c)
              return c and inC[c] and not claim[c] and not (famOf(c.mid) ~= bd.fam and not c.hasOver)
            end
            local open = {}
            for x = bd.l, bd.r do open[x] = true end
            local lo, hi = bd.l, bd.r
            for y = bd.y, bd.y - H, -1 do
              local rowL, rowR
              for x = lo, hi do
                if open[x] then
                  local c = at(x, y)
                  -- a door's frame cells are its, whatever their family
                  local dl, dr = at(x - 1, y), at(x + 1, y)
                  if claimable(c) or (y == bd.y and ((dl and dl.isDoor) or (dr and dr.isDoor))
                      and c and inC[c] and not claim[c]) then
                    claim[c] = true
                    g[#g + 1] = c
                    if not rowL then rowL = x end
                    rowR = x
                  elseif y < bd.y then
                    open[x] = false
                  elseif not (c and ((c.isDoor or c.isSign) and not c.blocksForBlob)) then
                    open[x] = false
                  end
                end
              end
              if rowL then
                for _, s in ipairs({ -1, 1 }) do
                  local x = s < 0 and rowL or rowR
                  while true do
                    local p, q = at(x, y), at(x + s, y)
                    if not (p and claimable(q)) then break end
                    local step = famOf(q.mid) == bd.fam and (q.mid - p.mid) * s or -1
                    if step < 0 or step > 2 then
                      -- r11 (refs 05-07): the mirror of the row's far end
                      -- ends a symmetric facade (Saffron's PC: its east
                      -- column 391 / 399 / 407 mirrors 72 / 80 / 88)
                      local far = s < 0 and rowR or rowL
                      if x == far or not mirrorCells(atlas.texels, q, at(far, y)) then break end
                      step = 99
                    end
                    -- not over another wall of this family (that column
                    -- belongs to the building below: Saffron (28,18))
                    local under = at(x + s, y + 1)
                    if y < bd.y and under and inC[under] and not claim[under] and famOf(under.mid) == bd.fam then break end
                    claim[q] = true
                    g[#g + 1] = q
                    x = x + s
                    open[x] = true
                    if x < lo then lo = x end
                    if x > hi then hi = x end
                    if s < 0 then rowL = x else rowR = x end
                    if step == 99 then break end
                  end
                end
              elseif y < bd.y then
                break
              end
            end
          end
        end
        -- a door whose claim has no 2x2 square (a side door in a wall
        -- column: Route 10's Power Plant) is not a building of its own:
        -- its cells go back to the rest (and join the building beside)
        do
          local kept = {}
          for _, owner in ipairs(groups) do
            local g, inG, thick = groups[owner], {}, false
            for _, c in ipairs(g) do inG[c] = true end
            for _, c in ipairs(g) do
              for _, q4 in ipairs(SQ4) do
                local a, b, e = at(c.x + q4[1], c.y), at(c.x, c.y + q4[2]), at(c.x + q4[1], c.y + q4[2])
                if a and b and e and inG[a] and inG[b] and inG[e] then thick = true break end
              end
              if thick then break end
            end
            if thick then
              kept[#kept + 1] = owner
            else
              for _, c in ipairs(g) do claim[c] = nil end
              groups[owner] = nil
            end
          end
          for i = #groups, 1, -1 do groups[i] = nil end
          for i, owner in ipairs(kept) do groups[i] = owner end
        end
        local groupOf = {}
        for _, owner in ipairs(groups) do
          for _, c in ipairs(groups[owner]) do groupOf[c] = owner end
        end
        -- the rest. Its THIN cells (in no 2x2 square of unclaimed cells)
        -- that form a single column of one building's family beside that
        -- building -- a side column the front row and the art steps did not
        -- reach (Silph Co's flanks, Route 10's Power Plant pylons) -- join
        -- it; what remains splits into connected parts, and a thin part's
        -- engine-BUILDING cells are bushes (r9 item 7: Viridian)
        local free = {}
        for _, c in ipairs(comp.cells) do
          if not claim[c] then free[c] = true end
        end
        local function isThin(p, set)
          for _, q4 in ipairs(SQ4) do
            local a, b, e = at(p.x + q4[1], p.y), at(p.x, p.y + q4[2]), at(p.x + q4[1], p.y + q4[2])
            if a and b and e and set[a] and set[b] and set[e] then return false end
          end
          return true
        end
        local thinC = {}
        for c in pairs(free) do
          if isThin(c, free) then thinC[c] = true end
        end
        local doneCol = {}
        for _, c0 in ipairs(comp.cells) do
          if thinC[c0] and not doneCol[c0] then
            -- the vertical run of thin cells through c0
            local y0, y1 = c0.y, c0.y
            while true do
              local q = at(c0.x, y0 - 1)
              if q and thinC[q] then y0 = y0 - 1 else break end
            end
            while true do
              local q = at(c0.x, y1 + 1)
              if q and thinC[q] then y1 = y1 + 1 else break end
            end
            local run = {}
            for y = y0, y1 do
              local q = at(c0.x, y)
              doneCol[q] = true
              run[#run + 1] = q
            end
            if #run == 1 then
              -- a lone nook cell held on two sides by one building (the
              -- corner of Saffron's primary house drawn in secondary art)
              local touch = {}
              for _, dd in ipairs(DIRS) do
                local q = at(c0.x + dd.dx, c0.y + dd.dy)
                local o = q and groupOf[q]
                if o then touch[o] = (touch[o] or 0) + 1 end
              end
              for o, n in pairs(touch) do
                if n >= 2 then
                  local g = groups[o]
                  g[#g + 1] = c0
                  groupOf[c0] = o
                  free[c0] = nil
                  break
                end
              end
            elseif #run >= 2 then
              local touch = {}
              for _, p in ipairs(run) do
                for _, dx in ipairs({ -1, 1 }) do
                  local q = at(p.x + dx, p.y)
                  local o = q and groupOf[q]
                  if o then touch[o] = (touch[o] or 0) + 1 end
                end
              end
              local best, bn = nil, 1
              for o, n in pairs(touch) do
                if n > bn then best, bn = o, n end
              end
              if best then
                -- only the rows the building spans; the column joins when
                -- its art is the building's family (or over art)
                local g = groups[best]
                local gy0, gy1 = math.huge, -math.huge
                for _, q in ipairs(g) do
                  if q.y < gy0 then gy0 = q.y end
                  if q.y > gy1 then gy1 = q.y end
                end
                local inRun = {}
                for _, p in ipairs(run) do
                  if p.y >= gy0 and p.y <= gy1 then inRun[#inRun + 1] = p end
                end
                local ok = #inRun >= 2
                for _, p in ipairs(inRun) do
                  -- (over art of another family joins only when it reaches
                  -- the building's side of its tile: not Three Island's
                  -- rope-post fence beside the PC)
                  if famOf(p.mid) ~= best.fam and (not p.hasOver or (atlas.texels
                      and overEdgeFrac(atlas.texels(p.mid, "over"), groupOf[at(p.x - 1, p.y)] == best) < 0.5)) then
                    ok = false
