                  end
                end
              end
            end
          end
        end
        local rest = {}
        for _, c0 in ipairs(comp.cells) do
          if free[c0] then
            local cells, stack, inP = {}, { c0 }, {}
            free[c0] = nil
            inP[c0] = true
            while #stack > 0 do
              local p = stack[#stack]
              stack[#stack] = nil
              cells[#cells + 1] = p
              for _, dd in ipairs(DIRS) do
                local q = at(p.x + dd.dx, p.y + dd.dy)
                if q and free[q] then
                  free[q] = nil
                  inP[q] = true
                  stack[#stack + 1] = q
                end
              end
            end
            local thin = true
            for _, p in ipairs(cells) do
              if not isThin(p, inP) then thin = false break end
            end
            if thin and #cells <= 3 then -- (a bush or two; longer runs: rails, walls)
              for _, p in ipairs(cells) do
                -- (not rock art: a stone wall row stays a wall -- Fuchsia 654)
                if p.category == "BUILDING" and not (atlasIsRock and atlasIsRock(p.mid)) then p.peeledBush = true end
              end
            end
            rest[#rest + 1] = cells
          end
        end
        local made = 0
        for _, owner in ipairs(groups) do
          if #groups[owner] > 0 then
            newComp(groups[owner])
            made = made + 1
          end
        end
        for _, cells in ipairs(rest) do
          newComp(cells)
          made = made + 1
        end
        components[comp.id] = nil
        splitPieces = splitPieces + made
      end
    end
    compList = newList
  end

  -- r11: the CLIFF split above also cut rock mounds (BLOCKED rock art on a
  -- CLIFF base: Route 9, Sevault Canyon) into small varied pieces that the
  -- building rule below took for houses. A solid non-cliff component stays
  -- apart only with building evidence -- a door next to it, or (towns and
  -- cities, pret mapType 1 / 2 or unknown) an engine-BUILDING majority;
  -- otherwise it rejoins the cliff components it touches, as before r11.
  local townish = tonumber(input.mapType)
  townish = townish == nil or townish == 1 or townish == 2
  if not indoor and not cave and C.CLIFF_REJOIN ~= false then
    local parent = {}
    local function find(a)
      while parent[a] ~= nil and parent[a] ~= a do a = parent[a] end
      return a
    end
    local merged = false
    for _, comp in ipairs(compList) do
      if not comp.treeArt and not comp.cliff then
        local door, nBuild, nMids = false, 0, 0
        for _, c in ipairs(comp.cells) do
          if c.category == "BUILDING" then nBuild = nBuild + 1 end
          for _, d in ipairs(DIRS) do
            local nc = at(c.x + d.dx, c.y + d.dy)
            if nc and nc.isDoor then door = true end
          end
        end
        for _ in pairs(comp.mids) do nMids = nMids + 1 end
        -- an engine-BUILDING majority also counts on routes when the art
        -- is varied (the Pokemon Tower's top drawn in Route 10's map; the
        -- rock / forest masses the engine calls BUILDING repeat their art)
        local varied = nMids >= C.BUILDING_DIVERSITY_MIN * comp.count
        if not (door or (nBuild * 2 >= comp.count and (townish or varied))) then
          for _, c in ipairs(comp.cells) do
            for _, d in ipairs(DIRS) do
              local nc = at(c.x + d.dx, c.y + d.dy)
              if nc and nc.blocksForBlob and not nc.isTreeArt and nc.cliffCat then
                local ra, rb = find(comp.id), find(nc.compId)
                if ra ~= rb then
                  if ra < rb then parent[rb] = ra else parent[ra] = rb end
                  merged = true
                end
              end
            end
          end
        end
      end
    end
    if merged then
      local kept = {}
      for _, comp in ipairs(compList) do
        local root = components[find(comp.id)]
        if root == comp then
          kept[#kept + 1] = comp
        else
          for _, c in ipairs(comp.cells) do
            c.compId = root.id
            root.cells[#root.cells + 1] = c
            root.mids[c.mid] = true
          end
          root.count = root.count + comp.count
          if comp.minX < root.minX then root.minX = comp.minX end
          if comp.maxX > root.maxX then root.maxX = comp.maxX end
          if comp.minY < root.minY then root.minY = comp.minY end
          if comp.maxY > root.maxY then root.maxY = comp.maxY end
          root.cliff = true -- rock: never a block
          components[comp.id] = nil
        end
      end
      compList = kept
    end
  end

  -- r11: BLOCK PARTS of a solid component (see BLOCKS below): the parts of
  -- its thick cells (in a 2x2 square of the component; door / sign cells
  -- count as present) that qualify as building volumes. Read-only.

  -- Verified source art takes precedence over grass-background heuristics.
  -- Profiles are build-local and fail closed when either native layer differs.
  grid.structProfiles={
      [223]={kind="metal",u=1184651643,o=0,ew=true},
      [231]={kind="metal",u=982508660,o=0,ew=true},
      [244]={kind="metal",u=1847008231,o=268868087,offset=.25},
      [245]={kind="metal",u=649016463,o=1514786615,offset=.75},
      [717]={kind="bridge",u=1618260664,o=0,lo=8,hi=16},
      [719]={kind="bridge",u=814288585,o=0,lo=0,hi=8},
      [725]={kind="bridge",u=915731086,o=0,lo=8,hi=16},
      [727]={kind="bridge",u=1139097242,o=0,lo=0,hi=8},
      [735]={kind="bridge",u=2115399394,o=0,lo=0,hi=8},
      [750]={kind="bridge",u=871892478,o=0,lo=8,hi=16},
      [751]={kind="bridge",u=796921647,o=0,lo=0,hi=8},
      [230]={kind="wood",u=75754040,o=0,ns=false,posts={1,6,1,15,9,14,2,15}},
      [232]={kind="wood",u=1144029385,o=0,ns=false,posts={1,6,2,15,9,14,2,15}},
      [233]={kind="wood",u=90438619,o=0,ns=false,posts={1,6,2,15,9,14,2,15}},
      [240]={kind="wood",u=1847008231,o=937482495,ns=true,posts={1,6,0,7,1,6,8,15}},
      [242]={kind="wood",u=260651589,o=0,ns=true,posts={9,14,0,15}},
      [243]={kind="wood",u=1608417718,o=0,ns=true,posts={1,6,0,15}},
  }
  grid.structCache={}
  grid.structProfile=function(mid)
    if indoor or cave or type(atlas.texels)~="function" then return end
    local cached=grid.structCache[mid];if cached~=nil then return cached or nil end
    grid.structCache[mid]=false
    local p=grid.structProfiles[mid];if not p then return end
    if p.kind=="wood" and input.pair~="viridian_outdoor" then return end
    if p.kind=="bridge" and input.pair~="general__rom_082d4af4" then return end
    local function hash(t)
      if not t then return 0 end;local h=0
      for i=1,256 do local v=t[i];if type(v)~="number"then return -1 end;h=(h*31+(v>=0 and v+2 or 1))%2147483647 end
      return h
    end
    if hash(atlas.texels(mid,"under"))~=p.u or hash(atlas.texels(mid,"over"))~=p.o then return end
    grid.structCache[mid]=p;return p
  end
  grid.emitNativeBridge=function(cell,x,z,gy)
    local p=cell.nativeStructure;local r=underRect(cell.mid)
    if not p or p.kind~="bridge" or not r then return end
    local nuggetFirst=#opaque+1
    -- Preserve the native ground half. Raise only the authored rail strip.
    local lo,hi=p.lo/16,p.hi/16
    if lo>0 then hQuad(opaque,x,z,x+lo,z+1,gy,subRect(r,0,0,lo,1))end
    if hi<1 then hQuad(opaque,x+hi,z,x+1,z+1,gy,subRect(r,hi,0,1,1))end
    local y1=gy+.35
    local ax,ay=math.floor(r[1]*atlas.w),math.floor(r[2]*atlas.h)
    local function crop(l,t,rr,b)return{(ax+l+.5)/atlas.w,(ay+t+.5)/atlas.h,(ax+rr+.5)/atlas.w,(ay+b+.5)/atlas.h}end
    hQuad(opaque,x+lo,z,x+hi,z+1,y1,crop(p.lo,0,p.hi-1,15))
    -- Closed low rectangular rail, at the native lateral offset. Side
    -- swatches come from the strip itself, never its grassy half.
    for _,e in ipairs({"left","right"})do
      local col=e=="left" and (p.lo==8 and 10 or 1) or (p.lo==8 and 14 or 5)
      local rr=crop(col,0,col,15);local xx=x+(e=="left" and lo or hi)
      quadN(opaque,xx,gy,z,rr[1],rr[2],xx,gy,z+1,rr[1],rr[4],
        xx,y1,z+1,rr[1],rr[4],xx,y1,z,rr[1],rr[2],e=="left" and -1 or 1,0,0)
    end
    faceQuad(opaque,"up",x+lo,x+hi,z,z+1,gy,y1,crop(p.lo,0,p.hi-1,0))
    faceQuad(opaque,"down",x+lo,x+hi,z,z+1,gy,y1,crop(p.lo,15,p.hi-1,15))
    if grid.nativeNuggetCaps and grid.nativeNuggetCaps[cell] then
      -- Close only these newly admitted caps and orient their source vertices.
      -- Existing bridge producers retain their exact numeric triangle order.
      hQuad(opaque,x+lo,z,x+hi,z+1,gy,crop(p.lo,0,p.hi-1,15),{0,-1,0})
      for i=nuggetFirst,#opaque,3 do
        local a,b,c=opaque[i],opaque[i+1],opaque[i+2]
        local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
        local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        local dot=(uy*vz-uz*vy)*a[6]+(uz*vx-ux*vz)*a[7]+(ux*vy-uy*vx)*a[8]
        if dot<0 then opaque[i+1],opaque[i+2]=opaque[i+2],opaque[i+1]end
      end
    end
  end
  -- Exact donor-specific rail masks; no global color classifier. Merge
  -- equal native texels into closed thin boxes, preserving all mask holes.
  grid.emitNativeAuditedRail=function(cell,x,z,gy)
    local mask=cell.nativeAuditedRail;local tex=atlas.texels(cell.mid,"under")
    local r=underRect(cell.mid);local rects,active={},{}
    for row=0,15 do
      local nextActive={};local col=0
      while col<16 do
        if mask[row+1]:sub(col+1,col+1)=="1"then
          local color=tex[row*16+col+1];local last=col+1
          while last<16 and mask[row+1]:sub(last+1,last+1)=="1"and tex[row*16+last+1]==color do last=last+1 end
          local key=col..":"..last..":"..color;local box=active[key]
          if box then box.y1=row+1 else box={x0=col,x1=last,y0=row,y1=row+1};rects[#rects+1]=box end
          nextActive[key]=box;col=last
        else col=col+1 end
      end
      active=nextActive
    end
    for _,b in ipairs(rects)do
      local u=r[1]+(b.x0+.5)/atlas.w;local v=r[2]+(b.y0+.5)/atlas.h
      local uv={u,v,u,v};local x0,x1=x+b.x0/16,x+b.x1/16
      local y0,y1=gy+(16-b.y1)/16*C.FENCE_H,gy+(16-b.y0)/16*C.FENCE_H
      local z0,z1=z+.5-1/64,z+.5+1/64
      for _,e in ipairs({"up","down","left","right"})do faceQuad(opaque,e,x0,x1,z0,z1,y0,y1,uv)end
      hQuad(opaque,x0,z0,x1,z1,y1,uv,UP)
      hQuad(opaque,x0,z0,x1,z1,y0,uv,{0,-1,0})
    end
  end
  grid.emitNativeSaffronThin=function(cell,x,z,gy)
    local p=cell.nativeSaffronThin
    local first=#opaque+1
    local donor=p.donor or (p.axis=="ns" and 781 or cell.mid)
    local r=underRect(donor)
    local boxes,active={},{}
    -- Merge occupied source texels vertically first. Full native UV spans
    -- keep bar highlights while using five closed boxes on a center tile.
    for col=0,15 do
      local nextActive={};local row=0
      while row<16 do
        if p.mask[row+1]:sub(col+1,col+1)=="1" then
          local last=row+1
          while last<16 and p.mask[last+1]:sub(col+1,col+1)=="1" do last=last+1 end
          local key=row..":"..last
          local b=active[key]
          if b then b.x1=col+1 else
            b={x0=col,x1=col+1,y0=row,y1=last}
            boxes[#boxes+1]=b
          end
          nextActive[key]=b;row=last
        else row=row+1 end
      end
      active=nextActive
    end
    for _,b in ipairs(boxes)do
      local x0,x1=x+b.x0/16,x+b.x1/16
      local y0,y1=gy+(16-b.y1)/16*C.FENCE_H,gy+(16-b.y0)/16*C.FENCE_H
      local z0,z1=z+.5-1/64,z+.5+1/64
      local u0,u1=r[1]+(b.x0+.5)/atlas.w,r[1]+(b.x1-.5)/atlas.w
      local v0,v1=r[2]+(b.y0+.5)/atlas.h,r[2]+(b.y1-.5)/atlas.h
      local face={u0,v0,u1,v1}
      faceQuad(opaque,"down",x0,x1,z0,z1,y0,y1,face)
      faceQuad(opaque,"up",x0,x1,z0,z1,y0,y1,face)
      faceQuad(opaque,"left",x0,x1,z0,z1,y0,y1,{u0,v0,u0,v1})
      faceQuad(opaque,"right",x0,x1,z0,z1,y0,y1,{u1,v0,u1,v1})
      hQuad(opaque,x0,z0,x1,z1,y1,{u0,v0,u1,v0},UP)
      hQuad(opaque,x0,z0,x1,z1,y0,{u0,v1,u1,v1},{0,-1,0})
    end
    -- hQuad's default vertex order looks down in this coordinate system.
    for i=first,#opaque,3 do
      local a,b,c=opaque[i],opaque[i+1],opaque[i+2]
      local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
      local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
      local dot=(uy*vz-uz*vy)*a[6]+(uz*vx-ux*vz)*a[7]+(ux*vy-uy*vx)*a[8]
      if dot<0 then opaque[i+1],opaque[i+2]=opaque[i+2],opaque[i+1] end
    end
    if p.axis=="ns" then
      -- The own OVER is a top-down projected rail strip. Stand the
      -- matching horizontal donor upright along the map column.
      for i=first,#opaque do
        local v=opaque[i]
        opaque[i]={x+1-(v[3]-z),v[2],z+(v[1]-x),v[4],v[5],
          -v[8],v[7],v[6]}
      end
    end
    if p.turnMask then
      grid.emitNativeSaffronThin({mid=p.turnDonor,nativeSaffronThin={
        axis="ns",mask=p.turnMask,donor=p.turnDonor}},x,z,gy)
    end
  end
  grid.emitNativeMetalEW=function(cell,x,z,gy,raisedOnly)
    local r=underRect(cell.mid);local ax,ay=math.floor(r[1]*atlas.w),math.floor(r[2]*atlas.h)
    local function crop(l,t,rr,b)return{(ax+l+.5)/atlas.w,(ay+t+.5)/atlas.h,(ax+rr+.5)/atlas.w,(ay+b+.5)/atlas.h}end
    local tex=atlas.texels(cell.mid,"under");local rects={};local active={}
    local function groundColor(col,row)
      local color=tex[row*16+col+1]
      if row>=2 and row<=12 and color~=0x73cea5 and color~=0x8cdebd then return 0x73cea5 end
      return color
    end
    for row=2,12 do local nextActive={};local col=0
      while col<16 do local color=groundColor(col,row);local last=col+1
        while last<16 and groundColor(last,row)==color do last=last+1 end
        local key=col..":"..last..":"..color;local box=active[key]
        if box then box.y1=row+1 else box={x0=col,x1=last,y0=row,y1=row+1,color=color};rects[#rects+1]=box end
        nextActive[key]=box;col=last
      end;active=nextActive
    end
