      hQuad(opaque,x+box.x0/16,z+box.y0/16,x+box.x1/16,z+box.y1/16,gy,uv)
    end
    end
    -- All raised samples are opaque silver art; native grass/brown remains
    -- in the original flat ground layer. The front silhouette is two posts.
    local face=crop(1,3,6,12);local side=crop(2,8,2,8);local cap=crop(2,3,5,3)
    for _,cx in ipairs({.25,.75})do
      local x0,x1,z0,z1=x+cx-3/16,x+cx+3/16,z+.5-2/16,z+.5+2/16
      for _,e in ipairs({"up","down"})do faceQuad(opaque,e,x0,x1,z0,z1,gy,gy+.6,face)end
      for _,e in ipairs({"left","right"})do faceQuad(opaque,e,x0,x1,z0,z1,gy,gy+.6,side)end
      hQuad(opaque,x0,z0,x1,z1,gy+.6,cap)
    end
    local rail=crop(7,6,7,8)
    for _,e in ipairs({"up","down"})do faceQuad(opaque,e,x,x+1,z+.48,z+.52,gy+.25,gy+.4,rail)end
    hQuad(opaque,x,z+.48,x+1,z+.52,gy+.4,crop(7,6,7,6))
  end
  -- Native north/south art is a side projection, not a vertical facade.
  -- Use the exact matching east/west metal donor for the same two solid
  -- uprights and rail, rotating geometry only. Keep the native UNDER ground.
  grid.emitNativeMetalNS=function(cell,x,z,gy)
    local p=cell.nativeStructure
    if C.FENCE_H~=.6 or not p or p.kind~="metal" or p.ew then return false end
    local donor=grid.structProfile(231)
    if not donor or donor.kind~="metal" or not donor.ew then return false end
    local r=underRect(231)
    local function finite(v)return type(v)=="number"and v==v and math.abs(v)<math.huge end
    if not finite(atlas.w)or not finite(atlas.h)or atlas.w<16 or atlas.h<16 or not r then return false end
    for i=1,4 do if not finite(r[i])or r[i]<0 or r[i]>1 then return false end end
    if r[3]<=r[1]or r[4]<=r[2]or math.abs((r[3]-r[1])*atlas.w-16)>.1
        or math.abs((r[4]-r[2])*atlas.h-16)>.1 then return false end
    -- Packed native231 donor contracts: exact pair dimensions, slot and 1/32px inset.
    -- Unknown/shifted atlas returns to the same-input original NS card path.
    local contracts={["general__rom_082d4af4"]={256,416,16,154},["general__rom_082d4b0c"]={256,464,16,156},["general__rom_082d4b24"]={256,416,16,123},["general__rom_082d4b3c"]={256,480,16,111},["general__rom_082d4b54"]={256,400,16,127},["general__rom_082d4b84"]={256,240,16,52},["general__rom_082d4b9c"]={256,336,16,80},["general__rom_082d5064"]={256,432,16,127},["general__rom_082d507c"]={256,496,16,131},["pallet_outdoor"]={256,176,16,42},["player_house"]={256,224,16,131},["sevii_outdoor"]={256,592,16,134},["viridian_outdoor"]={256,320,16,133}}
    local contract=contracts[input.pair]
    if not contract or atlas.w~=contract[1]or atlas.h~=contract[2]then return false end
    local sx=(contract[4]%contract[3])*16;local sy=math.floor(contract[4]/contract[3])*16
    local expected={(sx+1/32)/atlas.w,(sy+1/32)/atlas.h,(sx+16-1/32)/atlas.w,(sy+16-1/32)/atlas.h}
    for i=1,4 do if math.abs(r[i]-expected[i])>1e-12 then return false end end
    local u,o=atlas.texels(231,"under"),atlas.texels(231,"over")
    for i=1,256 do
      if not u or not finite(u[i])or u[i]<0 or u[i]>0xffffff then return false end
      if o and o[i]~=nil and o[i]~=-1 then return false end
    end
    if type(atlas.hasOver)~="function"or atlas.hasOver(231)or not atlas.hasOver(cell.mid)then return false end
    for _,layer in ipairs({"under","over"})do
      local t=atlas.texels(cell.mid,layer);if type(t)~="table"then return false end
      for i=1,256 do if not finite(t[i])or t[i]<-1 or t[i]>0xffffff then return false end end
    end
    local first=#opaque+1
    grid.emitNativeMetalEW({mid=231},0,0,gy,true)
    for i=first,#opaque do
      local v={};for k,value in pairs(opaque[i])do v[k]=value end;opaque[i]=v
      local a,b=v[1],v[3]
      v[1],v[3]=x+p.offset+b-.5,z+1-a
      local nx,nz=v[6],v[8];v[6],v[8]=nz,-nx
    end
    for i=first,#opaque,3 do
      local a,b,c=opaque[i],opaque[i+1],opaque[i+2]
      local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
      local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
      local dot=(uy*vz-uz*vy)*a[6]+(uz*vx-ux*vz)*a[7]+(ux*vy-uy*vx)*a[8]
      if dot<0 then opaque[i+1],opaque[i+2]=c,b end
    end
    return true
  end
  local function blockParts(comp)
    local parts = {}
    if indoor or cave or comp.treeArt or comp.cliff or comp.count < C.BLOCK_MIN_CELLS then return parts end
    local inComp = {}
    for _, c in ipairs(comp.cells) do if components[c.compId] == comp then
      local native=grid.structProfile(c.mid)
      if not native or native.kind~="wood" then inComp[c] = true end
    end end
    local function present(x, y)
      local c = at(x, y)
      -- (door / sign cells and walkable roof-overhang cells -- over art on
      -- a walkable cell, Five Island's 776 -- count as present)
      return c ~= nil and (inComp[c] or ((c.isDoor or c.isSign or (c.walkable and c.hasOver)) and not c.blocksForBlob)) and true or false
    end
    local thick = {}
    for c in pairs(inComp) do
      for _, q in ipairs(SQ4) do
        if present(c.x + q[1], c.y) and present(c.x, c.y + q[2]) and present(c.x + q[1], c.y + q[2]) then
          thick[c] = true
          break
        end
      end
    end
    local seen = {}
    for _, c0 in ipairs(comp.cells) do
      if thick[c0] and not seen[c0] then
        local cells, stack = {}, { c0 }
        seen[c0] = true
        local bx0, bx1, by0, by1 = c0.x, c0.x, c0.y, c0.y
        local nBuild, door, doorBelow = 0, false, false
        while #stack > 0 do
          local p = stack[#stack]
          stack[#stack] = nil
          cells[#cells + 1] = p
          if p.category == "BUILDING" then nBuild = nBuild + 1 end
          if p.x < bx0 then bx0 = p.x end
          if p.x > bx1 then bx1 = p.x end
          if p.y < by0 then by0 = p.y end
          if p.y > by1 then by1 = p.y end
          local below = at(p.x, p.y + 1)
          if below and below.isDoor then doorBelow = true end
          for _, d in ipairs(DIRS) do
            local nc = at(p.x + d.dx, p.y + d.dy)
            if nc then
              if nc.isDoor then door = true end
              if thick[nc] and not seen[nc] then
                seen[nc] = true
                stack[#stack + 1] = nc
              end
            end
          end
        end
        -- guards (all outdoor maps, w3 sweep): a building complex has
        -- varied art (distinct mids >= BLOCK_DIVERSITY_MIN of its cells;
        -- forests / rock fields the engine calls BUILDING: 0.01-0.09)
        -- and is at most BLOCK_MAX_DEPTH rows deep (Silph Co: 15;
        -- Safari Zone / Mt Ember masses: 36-54); an engine-BUILDING
        -- majority counts as evidence only in towns and cities (pret
        -- mapType 1 / 2, or unknown) -- on routes a door is needed
        local nMids, midSeen = 0, {}
        for _, p in ipairs(cells) do
          if not midSeen[p.mid] then midSeen[p.mid] = true; nMids = nMids + 1 end
        end
        -- (on routes an engine-BUILDING majority also counts when its art
        -- is varied: the Pokemon Tower's top drawn in Route 10's map)
        local nPc = 0
        for _, p in ipairs(cells) do
          if famOf(p.mid) == 1 then nPc = nPc + 1 end
        end
        local evidence = door or nPc * 2 >= #cells or (nBuild * 2 >= #cells
          and (townish or nMids >= C.BUILDING_DIVERSITY_MIN * #cells))
        if #cells >= C.BLOCK_MIN_CELLS and bx1 > bx0 and by1 > by0 and evidence
            and nMids >= C.BLOCK_DIVERSITY_MIN * #cells and by1 - by0 + 1 <= C.BLOCK_MAX_DEPTH then
          parts[#parts + 1] = { cells = cells, minX = bx0, maxX = bx1, minY = by0, maxY = by1,
            door = door, doorBelow = doorBelow }
        end
      end
    end
    return parts
  end

  -- a walkable cell (not a door / sign of the facade) or another
  -- component's solid cell inside the bbox
  local function walkableIn(comp, owner)
    owner = owner or comp
    for y = comp.minY, comp.maxY do
      for x = comp.minX, comp.maxX do
        local c = at(x, y)
        if c and c.walkable and not c.isDoor and not c.isSign and not c.blocksForBlob then return true end
        -- (or another component's solid cell: the box would swallow it)
        if c and c.blocksForBlob and components[c.compId] ~= owner then return true end
      end
    end
    return false
  end
  -- building evidence: a door next to it, mostly engine BUILDING cells, or
  -- mostly the general tileset's PC / Mart art (a doorless Mart-style
  -- house in Celadon's fenced garden)
  local function buildingEvidence(comp)
    local nBuild, nPc = 0, 0
    for _, c in ipairs(comp.cells) do
      if c.category == "BUILDING" then nBuild = nBuild + 1 end
      if famOf(c.mid) == 1 then nPc = nPc + 1 end
      for _, d in ipairs(DIRS) do
        local nc = at(c.x + d.dx, c.y + d.dy)
        if nc and nc.isDoor then return true end
      end
    end
    return nBuild * 2 >= comp.count or nPc * 2 >= comp.count
  end

  local buildingCount, propCount = 0, 0
  for _, comp in ipairs(compList) do
    local w = comp.maxX - comp.minX + 1
    local h = comp.maxY - comp.minY + 1
    local distinct = 0
    for _ in pairs(comp.mids) do distinct = distinct + 1 end
    comp.diversity = distinct / comp.count
    -- r8: interiors and caves never get buildings, roofs, blobs or fences:
    -- their solids are walls / furniture (pass 3i) or rock (pass 3c).
    if indoor then
      comp.kind = "indoor"
      propCount = propCount + 1
    elseif cave then
      comp.kind = "rock"
      propCount = propCount + 1
    elseif not comp.treeArt and comp.count <= C.FOUNTAIN_MAX_CELLS and w >= 2 and h >= 2 and atlas.waterFrac and (function()
          -- r11 (review M11): a small doorless solid (at least 2x2, no PC /
          -- Mart art: their roofs are blue) whose art is mostly water is a
          -- FOUNTAIN (Celadon), not a flat-roofed box
          local wsum = 0
          for _, c in ipairs(comp.cells) do
            if famOf(c.mid) == 1 then return false end
            wsum = wsum + (atlas.waterFrac(c.mid) or 0)
            for _, d in ipairs(DIRS) do
              local nc = at(c.x + d.dx, c.y + d.dy)
              if nc and nc.isDoor then return false end
            end
          end
          -- (and its spray: over art on the walkable cell above the middle)
          local sp = at(math.floor((comp.minX + comp.maxX) / 2), comp.minY - 1)
          return wsum >= C.FOUNTAIN_WATER_MIN * comp.count and sp ~= nil and sp.walkable and sp.hasOver
        end)() then
      comp.kind = "fountain"
      propCount = propCount + 1
    elseif not comp.treeArt and comp.count >= C.BUILDING_MIN_AREA and w >= C.BUILDING_MIN_DIM
        and h >= C.BUILDING_MIN_DIM and comp.diversity >= C.BUILDING_DIVERSITY_MIN
        and (function()
          -- r11 (USER REPORT, roofs): judge the footprint on the component's
          -- CORE (cells in a 2x2 square of its cells; door / sign cells
          -- count as present) -- a bush glued to a house's corner
          -- (Viridian's green houses, (23,9)) must not turn the house into
          -- per-column blocks; the thin cells split off as one-cell props
          local inC = {}
          for _, c in ipairs(comp.cells) do inC[c] = true end
          local function present(x, y)
            local c = at(x, y)
            return c ~= nil and (inC[c] or ((c.isDoor or c.isSign) and not c.blocksForBlob))
          end
          local core, thin = {}, {}
          local x0, x1, y0, y1 = math.huge, -math.huge, math.huge, -math.huge
          for _, c in ipairs(comp.cells) do
            local thick = false
            for _, q in ipairs(SQ4) do
              if present(c.x + q[1], c.y) and present(c.x, c.y + q[2]) and present(c.x + q[1], c.y + q[2]) then thick = true break end
            end
            if thick then
              core[#core + 1] = c
              if c.x < x0 then x0 = c.x end
              if c.x > x1 then x1 = c.x end
              if c.y < y0 then y0 = c.y end
              if c.y > y1 then y1 = c.y end
            else
              thin[#thin + 1] = c
            end
          end
          if #core < C.BUILDING_MIN_AREA then return false end
          local probe = { minX = x0, maxX = x1, minY = y0, maxY = y1, cells = core, count = #core }
          if not (#core >= C.BUILDING_FILL_MIN * (x1 - x0 + 1) * (y1 - y0 + 1) and not walkableIn(probe, comp)
              and buildingEvidence(probe)) then
            -- r11 (v15: Pewter's gym): a front PORCH -- the bottom row holds
            -- the door, ground each side of it and the porch walls beside
            -- the door: the rows above are the building (the door is then
            -- right below it), the porch cells stay this component's cells
            -- outside its box and are drawn as porch boxes (pass 3a)
            if y1 - y0 < 2 then return false end
            local door = false
            for xx = x0, x1 do
              local c = at(xx, y1)
              if c and c.isDoor then door = true end
            end
            if not door then return false end
            local body, porch = {}, {}
            for _, c in ipairs(core) do
              if c.y < y1 then body[#body + 1] = c else porch[#porch + 1] = c end
            end
            local p2 = { minX = x0, maxX = x1, minY = y0, maxY = y1 - 1, cells = body, count = #body }
            if not (#body >= C.BUILDING_MIN_AREA and #body >= C.BUILDING_FILL_MIN * (x1 - x0 + 1) * (y1 - y0)
                and not walkableIn(p2, comp) and buildingEvidence(p2)) then
              return false
            end
            core, y1 = body, y1 - 1
            comp.porch = porch
          end
          if #thin > 0 or comp.porch then
            for _, c in ipairs(thin) do
              nextId = nextId + 1
              local pc = { id = nextId, minX = c.x, maxX = c.x, minY = c.y, maxY = c.y, count = 1,
                cells = { c }, mids = { [c.mid] = true }, treeArt = false, cliff = false }
              components[nextId] = pc
              compList[#compList + 1] = pc
              c.compId = nextId
              if c.category == "BUILDING" and not (atlasIsRock and atlasIsRock(c.mid)) then c.peeledBush = true end
            end
            local mids = {}
            for _, c in ipairs(core) do mids[c.mid] = true end
            comp.cells, comp.count, comp.mids = core, #core, mids
            comp.minX, comp.maxX, comp.minY, comp.maxY = x0, x1, y0, y1
          end
          return true
        end)() then
      -- r11 (review M1): one box is only right for a real footprint: it
      -- fills at least BUILDING_FILL_MIN of its bbox, covers no walkable
      -- cell, and has building evidence (a door next to it, or mostly
      -- engine BUILDING cells -- a rock mound has neither). Anything else
      -- goes to BLOCKS (per-column extrusion) or stays a prop.
      comp.kind = "building"
      buildingCount = buildingCount + 1
    else
      comp.kind = "prop"
      propCount = propCount + 1
    end
  end

  local function compOf(c) return c and c.blocksForBlob and components[c.compId] or nil end
  local function isCompCell(c, comp) return c and ((c.blocksForBlob and components[c.compId] == comp) or (c.nativeSpecialVisualOwner and c.nativeSpecialVisualOwner==comp)) end
  local function touchesComp(x, y, comp)
    for _, d in ipairs(DIRS) do
      if isCompCell(at(x + d.dx, y + d.dy), comp) then return true end
    end
    return false
  end

  -- r7m (M5 support): peel stray edge lines off a building. Bushes that
  -- touch a house join its component (Viridian's green houses: bushes at
  -- (27..28,12) in front and (23,9)/(23,11) at the side), which put the
  -- front wall a row too far south and hid the door. A west/east column or
  -- the front row is dropped when fewer than 75% of its cells are this
  -- building's cells (door/sign cells count as present); never below a 3x3
  -- footprint; peeled cells become one-cell props.
  for _, comp in ipairs(compList) do
    if comp.kind == "building" then
      for _ = 1, W + H do -- r11 (review M1): no 4-pass cap; stops when nothing peels
        local peeled = false
        -- a line holding a door is the facade row: never peeled (the Gym's
        -- front row has walkable cells in its art but carries the door)
        local function frac(cells)
          local n, nComp, nOver = 0, 0, 0
          for _, p in ipairs(cells) do
            local c = at(p[1], p[2])
            if c and c.isDoor and touchesComp(p[1], p[2], comp) then return 1 end
            if isCompCell(c, comp) then
              nComp = nComp + 1
              if c.hasOver then nOver = nOver + 1 end
            end
            if isCompCell(c, comp) or (c and c.isSign and touchesComp(p[1], p[2], comp)) then n = n + 1 end
          end
          -- r11: a line whose cells are mostly over art is part of the
          -- building's drawing (roof / wall edges: One and Two Island,
          -- Celadon's Game Corner) and stays; bushes (Viridian) have none
          if nComp > 0 and nOver * 2 >= nComp then return 1 end
          return n / #cells
        end
        local lines = {}
        if comp.maxX - comp.minX >= 3 then
          local w, e = {}, {}
          for y = comp.minY, comp.maxY do w[#w + 1] = { comp.minX, y }; e[#e + 1] = { comp.maxX, y } end
          lines[#lines + 1] = w
          lines[#lines + 1] = e
        end
        if comp.maxY - comp.minY >= 3 then
          local s = {}
          for x = comp.minX, comp.maxX do s[#s + 1] = { x, comp.maxY } end
          lines[#lines + 1] = s
        end
        -- r11: a SIDE column whose building cells mostly sit in 2x2 squares
        -- of building cells (a solid edge -- Route 10's Power Plant pylon
        -- column) is part of the volume; lone cells (Viridian's side
        -- bushes) still peel. The front row keeps the r7m rule.
        local function solidSide(cells)
          local nComp, nThick = 0, 0
          for _, p in ipairs(cells) do
            local c = at(p[1], p[2])
            if isCompCell(c, comp) then
              nComp = nComp + 1
              for _, q in ipairs({ { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }) do
                if isCompCell(at(c.x + q[1], c.y), comp) and isCompCell(at(c.x, c.y + q[2]), comp)
                    and isCompCell(at(c.x + q[1], c.y + q[2]), comp) then
                  nThick = nThick + 1
                  break
                end
              end
            end
          end
          return nComp >= 3 and nThick * 2 >= nComp
        end
        for li, cells in ipairs(lines) do
          local side = li <= 2 and comp.maxX - comp.minX >= 3
          if not peeled and frac(cells) < 0.75 and not (side and solidSide(cells)) then
            for _, p in ipairs(cells) do
              local c = at(p[1], p[2])
              if isCompCell(c, comp) then
                nextId = nextId + 1
                local pc = { id = nextId, minX = c.x, maxX = c.x, minY = c.y, maxY = c.y, count = 1,
                  cells = { c }, mids = { [c.mid] = true }, kind = "prop", treeArt = false, diversity = 1 }
                components[nextId] = pc
                compList[#compList + 1] = pc
                c.compId = nextId
                -- r9 (review 7): a peeled cell the engine calls BUILDING
                -- is a bush against the house (Viridian (27..28,12)), not
                -- a fence run: it stays a round bush
                if c.category == "BUILDING" then c.peeledBush = true end
                propCount = propCount + 1
              end
            end
            peeled = true
          end
        end
        if not peeled then break end
        local keep, mids = {}, {}
        comp.minX, comp.maxX, comp.minY, comp.maxY = math.huge, -math.huge, math.huge, -math.huge
        for _, c in ipairs(comp.cells) do
          if components[c.compId] == comp then
            keep[#keep + 1] = c
            mids[c.mid] = true
            if c.x < comp.minX then comp.minX = c.x end
            if c.x > comp.maxX then comp.maxX = c.x end
            if c.y < comp.minY then comp.minY = c.y end
            if c.y > comp.maxY then comp.maxY = c.y end
          end
        end
        comp.cells, comp.mids, comp.count = keep, mids, #keep
      end
    end
  end

  -- r11: BLOCKS -- building complexes the building rule above rejects:
  -- attached houses in a row, towers whose art repeats (low diversity),
  -- buildings glued to fences / city walls. A solid (not tree art, not
  -- CLIFF) prop component loses its THIN cells (in no 2x2 square of the
  -- component; door / sign cells count as present, they belong to the
  -- facade) -- fence rails, city walls -- which stay props; the rest splits
  -- into its connected parts, and a part at least BLOCK_MIN_CELLS big and
  -- 2x2 with building evidence -- it touches a door, or most of its cells
  -- are engine BUILDING cells -- becomes a "block": one volume extruded per
  -- column (pass 3b). Data only, no per-town tables.
  local blocks = {}
  if not indoor and not cave then
    local n0 = #compList
    for ci = 1, n0 do
      local comp = compList[ci]
      if comp.kind == "prop" then
        for _, part in ipairs(blockParts(comp)) do
          nextId = nextId + 1
          local bc = { id = nextId, minX = part.minX, maxX = part.maxX, minY = part.minY, maxY = part.maxY,
            count = #part.cells, cells = part.cells, mids = {}, kind = "block", treeArt = false, diversity = 0,
            door = part.door, doorBelow = part.doorBelow }
          for _, p in ipairs(part.cells) do
            p.compId = nextId
            bc.mids[p.mid] = true
          end
          components[nextId] = bc
          compList[#compList + 1] = bc
          blocks[#blocks + 1] = bc
        end
      end
    end
    -- a door / sign cell right below a block cell is part of that block's
    -- facade (drawn in it; no floor decal, no free-standing sign board)
    for _, bc in ipairs(blocks) do
      for _, p in ipairs(bc.cells) do
        local s = at(p.x, p.y + 1)
        if s and not s.blocksForBlob and (s.isDoor or s.isSign) then
          s.blockFill = bc
          if s.isSign then s.facadeOf = bc end
        end
      end
    end
  end
  -- Route 2's south forest gate is one native architectural footprint.
  -- Door-family splitting left its outer facade columns as small props;
  -- the generic prop pass then gave that brick/window art tree crowns.
  -- Return only the exact guarded solid edge cells to their existing block.
  do
local native={cells={
{{76,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{78,7,0,0,0,0,"BLOCKED"},},
{{76,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{77,7,0,0,0,0,"BLOCKED"},{78,7,0,0,0,0,"BLOCKED"},},
{{387,7,0,0,0,0,"BLOCKED"},{388,7,0,0,0,0,"BLOCKED"},{388,7,0,0,0,0,"BLOCKED"},{388,7,0,0,0,0,"BLOCKED"},{388,7,0,0,0,0,"BLOCKED"},{388,7,0,0,0,0,"BLOCKED"},{388,7,0,0,0,0,"BLOCKED"},{389,7,0,0,0,0,"BLOCKED"},},
{{438,7,0,0,0,0,"BLOCKED"},{437,7,0,0,0,0,"BLOCKED"},{437,7,0,0,0,0,"BLOCKED"},{437,7,0,0,0,0,"BLOCKED"},{437,7,0,0,0,0,"BLOCKED"},{437,7,0,0,0,0,"BLOCKED"},{437,7,0,0,0,0,"BLOCKED"},{439,7,0,0,0,0,"BLOCKED"},},
