        for y=17,23 do for _,x in ipairs({23,30})do at(x,y).nativeBlueFence=true end end
        local cells,mids={},{}
        for y=17,18 do for x=23,30 do local q=at(x,y)
          if x==23 or x==30 then
            nextId=nextId+1
            local fence={id=nextId,kind="prop",minX=x,maxX=x,minY=y,maxY=y,count=1,
              cells={q},mids={[q.mid]=true},treeArt=false,cliff=false,diversity=1}
            components[nextId]=fence;compList[#compList+1]=fence;q.compId=nextId
            propCount=propCount+1
          else cells[#cells+1]=q;mids[q.mid]=true end
        end end
        comp.cells,comp.mids,comp.count=cells,mids,#cells
        comp.minX,comp.maxX=24,29
        local distinct=0;for _ in pairs(mids)do distinct=distinct+1 end
        comp.diversity=distinct/comp.count
        comp.nativeBlueRoof=true
      end
    end
  end
