  grid.flatRule=function()
    local specs=grid.flatSpecs[input.pair]
    if not specs or type(atlas.texels)~="function" then return end
    local function th(t)
      local h=0
      if t then for i=1,256 do local v=t[i];h=(h*31+((type(v)=="number" and v>=0) and v+2 or 1))%2147483647 end end
      return h
    end
    for _,s in ipairs(specs) do
      local kind,bx0,by0,bx1,by1=s[2],s[3],s[4],s[5],s[6]
      local comp
      if s[1]==input.mapId then
        for _,q in ipairs(compList) do
          if q.kind==(kind=="B" and "building" or "block") and q.minX==bx0 and q.minY==by0 and q.maxX==bx1 and q.maxY==by1 then comp=q end
        end
      end
      local valid=comp~=nil
      if valid then
        local mids,i,cellOf={},0,{}
        for m in s[7]:gmatch("%d+") do mids[#mids+1]=tonumber(m) end
        for y=by0-1,by1 do for x=bx0,bx1 do
          i=i+1;local c=at(x,y)
          if not c or c.mid~=mids[i] then valid=false else cellOf[c.mid]=cellOf[c.mid] or c end
        end end
        if i~=#mids then valid=false end
        for m,hu,ho in s[8]:gmatch("(%d+):(%d+):(%d+)") do
          local c=cellOf[tonumber(m)]
          -- Cerulean B1's two rear flower cells are walkable terrain,
          -- outside the building's owned roof/wall art. Their UNDER changes
          -- at runtime; retaining that hash would disable the native roof.
          -- Keep their exact locations/mids and every building-art hash.
          local rearFlower=false
          if input.mapId=="FR_CERULEAN_CITY" and input.pair=="general__rom_082d4af4"
              and kind=="B" and bx0==15 and by0==8 and bx1==20 and by1==11
              and tonumber(m)==4 and tonumber(hu)==2089625187 and tonumber(ho)==0 then
            rearFlower=true
            for _,rx in ipairs({17,19})do
              local r=at(rx,7)
              if not r or r.mid~=4 or not r.walkable or r.hasOver or r.blocksForBlob
                  or compOf(r)==comp or r.overhangOf==comp or r.facadeOf==comp or r.doorOf==comp then rearFlower=false end
            end
          end
          if not c or (not rearFlower and th(atlas.texels(c.mid,"under"))~=tonumber(hu))
              or th(c.hasOver and atlas.texels(c.mid,"over") or nil)~=tonumber(ho) then valid=false end
        end
      end
      if valid and s.nativeFuchsia then
        valid=input.mapId=="FR_FUCHSIA_CITY" and input.width==48 and input.height==40 and not input.isBorder
          and type(atlas.w)=="number" and atlas.w>0 and atlas.w<math.huge
          and type(atlas.h)=="number" and atlas.h>0 and atlas.h<math.huge
        local i=0
        for y=by0-1,by1 do for x=bx0,bx1 do
          i=i+1;local c=at(x,y);local q=s.states[i]
          if not c or not q or c.mid~=q[1] or c.coll~=q[2] or c.elev~=q[3] or c.beh~=q[4] then valid=false end
          if c then for _,ly in ipairs({"under","over"})do if ly=="under" or c.hasOver then
            local t=atlas.texels(c.mid,ly);local r=ly=="under" and underRect(c.mid) or overRect(c.mid)
            if not t or not r then valid=false else
              for n=1,256 do if type(t[n])~="number"or t[n]~=t[n]or math.abs(t[n])==math.huge then valid=false end end
              for n=1,4 do if type(r[n])~="number"or r[n]~=r[n]or math.abs(r[n])==math.huge then valid=false end end
              if r[1]>=r[3]or r[2]>=r[4]then valid=false end
            end
          end end end
        end end
      end
      if valid and kind=="K" then
        local found
        for _,b in ipairs(blocks) do if b==comp then found=true end end
        valid=found
      end
      if valid then
        local houses={}
        for hi,h in ipairs(s[9]) do
          local hx0,hx1,hy0,hy1,drip,sg=h[1],h[2],h[3],h[4],h[5],h[6]
          local Bt=(hy1-hy0+1)*16
          local D=sg[1][5]
          local spec={Bt=Bt,top=Bt-drip+2,F=Bt-drip-1-D,segs=sg,xb=s.xb}
          if spec.F<16 or spec.F%16~=0 then valid=false end
          houses[hi]={hx0,hx1,hy0,hy1,spec}
          -- (repair r2, review D1) the footprint never holds a cell the player
          -- can walk on: walkable cells in a block house's top row (Cerulean
          -- K1/K2's back-exit path, K3's corner) stay open ground. The house
          -- then stands one row shorter (Bt - 16; top and F unchanged) and the
          -- top row's own block cells extend it back (spec.ext, by column);
          -- any other walkable non-door cell above the facade row: no house.
          if kind=="K" then
            local walk=false
            for x=hx0,hx1 do local c=at(x,hy0);if c and c.walkable and not c.isDoor then walk=true end end
            for y=hy0+1,hy1-1 do for x=hx0,hx1 do
              local c=at(x,y);if c and c.walkable and not c.isDoor then valid=false end
            end end
            if walk then spec.Bt=Bt-16;spec.ext={};houses[hi]={hx0,hx1,hy0+1,hy1,spec,hy0} end
          end
        end
        if valid and kind=="B" then
          comp.flatHouse=houses[1][5];comp.k32={}
          -- Lavender's three native purple decks are boxed, not hip ends.
          -- The exact map/layout/full-art signature above must already pass.
          if input.mapId=="FR_LAVENDER_TOWN" and input.pair=="general__rom_082d4b0c"
              and not input.isBorder and input.width==24 and input.height==20
              and ((bx0==8 and by0==9 and bx1==12 and by1==11)
                or(bx0==3 and by0==14 and bx1==7 and by1==16)
                or(bx0==8 and by0==14 and bx1==12 and by1==16)) then
            local boxed=type(atlas.w)=="number"and atlas.w>0 and atlas.w<math.huge
              and type(atlas.h)=="number"and atlas.h>0 and atlas.h<math.huge
            for y=by0-1,by1 do for x=bx0,bx1 do
              local c=at(x,y)
              for _,layer in ipairs({"under","over"})do
                if layer=="under"or c.hasOver then
                  local t=atlas.texels(c.mid,layer)
                  local r=layer=="under"and underRect(c.mid)or overRect(c.mid)
                  if not t or not r then boxed=false else
                    for i=1,256 do if type(t[i])~="number"or t[i]~=t[i]or math.abs(t[i])==math.huge then boxed=false end end
                    for i=1,4 do if type(r[i])~="number"or r[i]~=r[i]or math.abs(r[i])==math.huge then boxed=false end end
                    if boxed and (r[1]>=r[3]or r[2]>=r[4])then boxed=false end
                  end
                end
              end
            end end
            comp.flatHouse.nativeLavenderBoxed=boxed or nil
          end
          comp.flatHouse.nativeFuchsiaBoxed=s.nativeFuchsia or nil
          if s.nativeFuchsia then
            comp.flatHouse.nativeRoofStart=(by1-by0+1)*16-56
            if by1-by0==2 then for x=bx0,bx1 do
              -- The blocked corner's UNDER can remain a fence/terrain
              -- producer while its OVER belongs to this roof. This private
              -- owner is consumed only by flatTopRoof, never ground/props.
              at(x,by0-1).nativeFuchsiaRoofOver=comp
            end end
          end
        elseif valid then
          local bc=comp
          local rest,mids={},{}
          for _,c in ipairs(bc.cells)do
            local mine
            for _,h in ipairs(houses)do if c.x>=h[1] and c.x<=h[2] and c.y>=(h[6] or h[3]) and c.y<=h[4] then mine=true end end
            if not mine then rest[#rest+1]=c;mids[c.mid]=true end
          end
          for _,h in ipairs(houses)do
            nextId=nextId+1
            local hc={id=nextId,kind="building",treeArt=false,cliff=false,cells={},mids={},
              minX=h[1],maxX=h[2],minY=h[3],maxY=h[4],flatHouse=h[5],k32={},fromBlock=true}
            components[nextId]=hc;compList[#compList+1]=hc
            for y=h[6] or h[3],h[4]do for x=h[1],h[2]do
              local c=at(x,y)
              if c and c.blocksForBlob and components[c.compId]==bc then
                c.compId=nextId;hc.cells[#hc.cells+1]=c;hc.mids[c.mid]=true
                if y==h[6] then h[5].ext[x]=true end
              end
            end end
            hc.count=#hc.cells
            local distinct=0;for _ in pairs(hc.mids)do distinct=distinct+1 end
            hc.diversity=distinct/hc.count
            buildingCount=buildingCount+1
            for y=h[6] or h[3],h[4]+1 do for x=h[1],h[2]do
              local c=at(x,y)
              if c and c.blockFill==bc then c.blockFill=nil end
              if c and c.facadeOf==bc then c.facadeOf=nil end
              if c and y<=h[4]-h[5].F/16 and c.walkable and c.hasOver and not c.isDoor and not c.isTreeArt
                  and not c.blocksForBlob then c.overhangOf=hc end
            end end
          end
          if #rest==0 then
            for bi,b in ipairs(blocks)do if b==bc then table.remove(blocks,bi);break end end
            for ci,q in ipairs(compList)do if q==bc then table.remove(compList,ci);break end end
            components[bc.id]=nil
          else
            bc.cells,bc.mids,bc.count=rest,mids,#rest
            bc.minX,bc.maxX,bc.minY,bc.maxY=math.huge,-math.huge,math.huge,-math.huge
            for _,c in ipairs(rest)do
              bc.minX,bc.maxX=math.min(bc.minX,c.x),math.max(bc.maxX,c.x)
              bc.minY,bc.maxY=math.min(bc.minY,c.y),math.max(bc.maxY,c.y)
            end
          end
        end
      end
    end
  end
  grid.flatRule()
  -- (r3, USER: "It's not a pointed roof but a flat roof that slants down
  -- on the sides"; "some of the front wall being drawn on the roof too")
  -- The K32 house as its art draws it, read in 2.5D (texels; row = 32 -
  -- height - depth; trim row = rows 0..15, roof row -16..-1, facade row
  -- 16..31): the big panel with the horizontal lines is a FLAT TOP 24 up;
  -- the striped strips at the ends are SLOPES -- the band's top edge and
  -- the roof's back outline both drop 1 texel per 2 columns over the outer
  -- 10 columns, to 19 at the side walls; the dark band (rows 8-10 in the
  -- middle) is the slab's 3-texel front EDGE; the rows under it (11-15:
  -- the shaded wall, the pillar tops, the door's lintel) are WALL, 21 tall
  -- in the middle and down with the band to the facade row's 16 at the
  -- sides. No ridge, no hip; flush with the walls on all four sides (no
  -- eave: OV-2 waits for the user). Faces:
  --  * front: the native art itself on the wall plane, (x, row = 32 - h);
  --  * top (flat and slopes): per texel column, the art from its first
  --    opaque row (the back outline) to the fold row runs back -> front;
  --  * side edges (16..19): the band's three rows; back: the plain wall
  --    colour up to the slab, the band's rows on its edge.
  -- Each piece is drawn in its own cell's layer (OVER where the cell has
  -- it -- the roof-row tiles' UNDER is the terrain behind them -- else
  -- UNDER). Returns the roof height function.
  -- (overhangs, Claude 2026-10-01) EAVES on the flat-top houses (K32 here,
  -- grid.flatTopRoof the others). USER 2026-10-01: depths "use your
  -- suggestion" -- 4 texels on the two-storey houses (walls F >= 32 rows),
  -- 3 on the small ones, front and back; the sides as the art draws them
  -- (SPEC_OVERHANGS OV5: K20 / K41 / K32 2, K24 1, K33 0, K42 3). ONE roof
  -- surface: the flat top and its slopes run on past the walls (the art
  -- spread over the longer plan, one scale; past a side wall the edge
  -- column clamped), the band turns down at the new edge, and a soffit in
  -- the band's colour, parallel to the top, closes it underneath. Never
  -- over another building or block; over a walkable cell the soffit stays
  -- >= EAVE_CLEAR (1.2 cells) above that cell's ground, else that texel
  -- column (a side: that whole side) has no eave. Depths in texels.
  grid.EAVE_SIDE={FR_PALLET_TOWN=2,FR_ROUTE_5=2,FR_CERULEAN_CITY=1,FR_ROUTE_25=3,FR_SAFFRON_CITY=0,FR_SAFFRON_CITY_CONNECTION=0}
  grid.EAVE_CLEAR=1.2
  grid.eaveBlocked=function(comp,c,soffit)
    if not c then return true end
    local nc=compOf(c) or c.facadeOf or c.doorOf
    if nc and nc~=comp and (nc.kind=="building" or nc.kind=="block") then return true end
    if grid.blockRunOf and grid.blockRunOf[c] then return true end
    if c.walkable then
      local g=math.max(type(c.hgt)=="number" and c.hgt or comp.groundY,comp.groundY)
      if soffit-g<grid.EAVE_CLEAR-1e-9 then return true end
    end
    return false
  end
  -- per texel column X of a roof segment: front / back eave depth (E.dF /
  -- E.dB or 0) and the two sides' (0 unless the segment's end is the
  -- house's outer end and every cell under that side's eave allows it).
  -- E = { gy, tv, hT, Wt, xs, z1, zs = the back plane of column X, dF, dB,
  -- dL, dR, left, right, noBack }
  grid.eavePlan=function(comp,E)
    local f,b,fn,bn={},{},0,0
    for X=0,E.Wt-1 do
      local s=E.gy+(math.min(E.hT(X),E.hT(X+1))-3)*E.tv
      local cx=math.floor(E.xs+(X+0.5)/16)
      f[X]=(E.dF>0 and not grid.eaveBlocked(comp,at(cx,E.z1),s)) and E.dF or 0
      b[X]=(E.dB>0 and not E.noBack and not grid.eaveBlocked(comp,at(cx,math.floor(E.zs(X)+1e-9)-1),s)) and E.dB or 0
      fn,bn=math.max(fn,f[X]),math.max(bn,b[X])
    end
    local function side(d,X,u,cx)
      if not d or d<=0 then return 0 end
      local s=E.gy+(E.hT(u)-3)*E.tv
      local za,zb=E.zs(X)-b[X]/16,E.z1+f[X]/16
      for cy=math.floor(za+1e-9),math.ceil(zb-1e-9)-1 do
        if grid.eaveBlocked(comp,at(cx,cy),s) then return 0 end
      end
      return d
    end
    return {f=f,b=b,fn=fn,bn=bn,
      dL=E.left and side(E.dL,0,-(E.dL or 0),math.floor(E.xs-1e-9)) or 0,
      dR=E.right and side(E.dR,E.Wt-1,E.Wt+(E.dR or 0),math.floor(E.xs+E.Wt/16+1e-9)) or 0}
  end
  -- the eave pieces of one roof segment besides its top and its front /
  -- back faces (drawn by the roof): EV = grid.eavePlan's result plus runs
  -- (the segment's top runs { ua, ub, f, b, zs, back, fold }), rowAt(run,
  -- z) = the art Y (map units) of the top at z, xa = { left, right } edge
  -- art columns (map units), capL / capR = { f = true / false, b = ... }:
  -- close the front / back eave at that end of the segment (false where
  -- an equal eave runs on: the next segment's, an attached house's), split
  -- = { L, R } the side edges' split z's. Xb / Yb: the band's art column
  -- and its top row (map units). face(pts, n): pts = { x, y, z, X, Y }.
  -- (eave colour, Claude 2026-10-01; USER on review item D2, choice B: "You
  -- can just match the color of the roof?") A side eave's top shows one
  -- plain colour, the roof's own, instead of the roof's edge column
  -- stretched over it: the most common colour among the roof top's texels
  -- in the given art columns beside that side ({ X, ra, rb }: an absolute
  -- texel column and its rows ra..rb-1; a texel counts in the layer the
  -- roof's face draws there: OVER where the cell has OVER, else UNDER), at
  -- the centre of one texel of that colour (the one with the most
  -- same-coloured neighbours in its tile, so the mip levels keep the
  -- colour). own(c): the roof's cells. Returns { X, Y } (map units) or nil.
  grid.eaveFill=function(own,cols)
    if type(atlas.texels)~="function" then return nil end
    local function val(X,R)
      local c=at(math.floor(X/16),math.floor(R/16))
      if not own(c) then return nil end
      local t
      if c.hasOver then t=atlas.texels(c.mid,"over") else t=atlas.texels(c.mid,"under") end
      local v=t and t[(R%16)*16+X%16+1]
      return (type(v)=="number" and v>=0) and v or nil
    end
    local cnt,seen,best,bn={},{},nil,0
    for _,cl in ipairs(cols) do
      for R=cl[2],cl[3]-1 do
        local v=val(cl[1],R)
        if v then
          cnt[v]=(cnt[v] or 0)+1
          if cnt[v]>bn then best,bn=v,cnt[v] end
          seen[#seen+1]={cl[1],R,v}
        end
      end
    end
    if not best then return nil end
    local pick,pn=nil,-1
    for _,s in ipairs(seen) do
      if s[3]==best then
        local n=0
        for dy=-1,1 do for dx=-1,1 do
          local X,R=s[1]+dx,s[2]+dy
          if math.floor(X/16)==math.floor(s[1]/16) and math.floor(R/16)==math.floor(s[2]/16) and val(X,R)==best then n=n+1 end
        end end
        if n>pn then pick,pn=s,n end
      end
    end
    return {(pick[1]+0.5)/16,(pick[2]+0.5)/16}
  end
  grid.eaveEmit=function(EV,face,P,hT,tv,gy,z1,Wt,Xb,Yb)
    local runs=EV.runs
    local function soffN(ua,ub)
      local dy=(hT(ub)-hT(ua))*tv*16/(ub-ua)
      return norm3({dy,-1,0}),norm3({-dy,1,0})
    end
    -- a vertical band piece over heights h0-3..h0 (a) / h1-3..h1 (b)
    local function band(pa,ha,pb,hb,n)
      face({{pa[1],gy+(ha-3)*tv,pa[2],Xb,Yb+3/16},{pb[1],gy+(hb-3)*tv,pb[2],Xb,Yb+3/16},
        {pb[1],gy+hb*tv,pb[2],Xb,Yb},{pa[1],gy+ha*tv,pa[2],Xb,Yb}},n)
    end
    local function X(u) return P(u,0,0)[1] end
    local Y=Yb+1.5/16
    -- front / back: the soffits under the runs with an eave
    for _,s in ipairs(runs) do
      local ua,ub=s.ua,s.ub
      local ha,hb=hT(ua),hT(ub)
      local nd=soffN(ua,ub)
      if s.f>0 then
        local zf=z1+s.f/16
        face({P(ua,ha-3,z1,Xb,Y),P(ub,hb-3,z1,Xb,Y),P(ub,hb-3,zf,Xb,Y),P(ua,ha-3,zf,Xb,Y)},nd)
      end
      if s.b>0 then
        local zb=s.zs-s.b/16
        face({P(ua,ha-3,zb,Xb,Y),P(ub,hb-3,zb,Xb,Y),P(ub,hb-3,s.zs,Xb,Y),P(ua,ha-3,s.zs,Xb,Y)},nd)
      end
    end
    -- caps: where the depth changes between two runs, and at the
    -- segment's ends without a side eave
    local function cap(u,za,zb,n)
      local x,h=X(u),hT(u)
      band({x,za},h,{x,zb},h,n)
    end
    for i=1,#runs-1 do
      local a,c=runs[i],runs[i+1]
      if a.f~=c.f then cap(a.ub,z1+math.min(a.f,c.f)/16,z1+math.max(a.f,c.f)/16,a.f>c.f and N_E or N_W) end
      if a.b~=c.b and a.zs==c.zs then cap(a.ub,a.zs-math.max(a.b,c.b)/16,a.zs-math.min(a.b,c.b)/16,a.b>c.b and N_E or N_W) end
    end
    local r0,r1=runs[1],runs[#runs]
    if EV.dL<=0 then
      if r0.f>0 and EV.capL.f then cap(0,z1,z1+r0.f/16,N_W) end
      if r0.b>0 and EV.capL.b then cap(0,r0.zs-r0.b/16,r0.zs,N_W) end
    end
    if EV.dR<=0 then
      if r1.f>0 and EV.capR.f then cap(Wt,z1,z1+r1.f/16,N_E) end
      if r1.b>0 and EV.capR.b then cap(Wt,r1.zs-r1.b/16,r1.zs,N_E) end
    end
    -- side eaves: the edge run's top plane continued d texels past the
    -- side wall (its edge art column clamped), the band on the new edge
    -- (split where the top crosses the art's rows), the soffit (split at
    -- the wall's corners), the band's two ends
    for _,sd in ipairs({{EV.dL,r0,-1,N_W,EV.xa[1],EV.split.L},{EV.dR,r1,1,N_E,EV.xa[2],EV.split.R}}) do
      local d,s,dir,n,Xa,spl=sd[1],sd[2],sd[3],sd[4],sd[5],sd[6]
      if d>0 then
        local ue=dir<0 and 0 or Wt
        local uo=ue+dir*d
        local he,ho=hT(ue),hT(uo)
        local za,zb=s.zs-s.b/16,z1+s.f/16
        local nd,up=soffN(math.min(ue,uo),math.max(ue,uo))
        local zz={za}
        for _,z in ipairs(spl or {}) do if z>za+1e-9 and z<zb-1e-9 then zz[#zz+1]=z end end
        zz[#zz+1]=zb
        table.sort(zz)
        for i=1,#zz-1 do
          local a,c=zz[i],zz[i+1]
          if c-a>1e-9 then
            local Ya,Yc=EV.rowAt(s,a),EV.rowAt(s,c)
            -- (eave colour) the roof's own colour beside this side (grid.eaveFill)
            local fl=EV.fill and EV.fill[dir<0 and 1 or 2]
            if fl then face({P(uo,ho,a,fl[1],fl[2]),P(ue,he,a,fl[1],fl[2]),P(ue,he,c,fl[1],fl[2]),P(uo,ho,c,fl[1],fl[2])},up)
            else face({P(uo,ho,a,Xa,Ya),P(ue,he,a,Xa,Ya),P(ue,he,c,Xa,Yc),P(uo,ho,c,Xa,Yc)},up) end
            band({X(uo),a},ho,{X(uo),c},ho,n)
          end
        end
        local zw={za,s.zs,z1,zb}
        for i=1,3 do
          local a,c=zw[i],zw[i+1]
          if c-a>1e-9 then face({P(uo,ho-3,a,Xb,Y),P(ue,he-3,a,Xb,Y),P(ue,he-3,c,Xb,Y),P(uo,ho-3,c,Xb,Y)},nd) end
        end
        band({X(uo),zb},ho,{X(ue),zb},he,N_S)
        band({X(uo),za},ho,{X(ue),za},he,N_N)
      end
    end
  end
  grid.k32Roof=function(comp,sideArt)
    local gy,tv=comp.groundY,C.WALL_ROW_UNIT/16
    local x0,x1,z0,z1=comp.minX,comp.maxX+1,comp.minY,comp.maxY+1
    local Wt=(x1-x0)*16
    local function hT(u) return math.min(24,19+0.5*math.min(u,Wt-u)) end
    -- one planar convex face { {x,y,z,X,Y}, ... } (X, Y: art in map units,
    -- affine on the face), split at the art's cell lines
    local function face(pts,n)
      local polys={pts}
      for k=4,5 do
        local lo,hi=math.huge,-math.huge
        for _,p in ipairs(pts) do lo,hi=math.min(lo,p[k]),math.max(hi,p[k]) end
        for cut=math.floor(lo)+1,math.ceil(hi)-1 do
          local out={}
          for _,poly in ipairs(polys) do
            for _,s in ipairs({1,-1}) do
              local q={}
              for i=1,#poly do
                local P,Q=poly[i],poly[i%#poly+1]
                local dp,dq=s*(P[k]-cut),s*(Q[k]-cut)
                if dp>=0 then q[#q+1]=P end
                if dp*dq<0 then
                  local t,v=dp/(dp-dq),{}
                  for j=1,5 do v[j]=P[j]+(Q[j]-P[j])*t end
                  v[k]=cut
                  q[#q+1]=v
                end
              end
              if #q>=3 then out[#out+1]=q end
            end
          end
          polys=out
        end
      end
      for _,poly in ipairs(polys) do
        local q={}
        for _,p in ipairs(poly) do
          local l=q[#q]
          if not l or math.abs(l[1]-p[1])+math.abs(l[2]-p[2])+math.abs(l[3]-p[3])>1e-9 then q[#q+1]=p end
        end
        if #q>1 and math.abs(q[1][1]-q[#q][1])+math.abs(q[1][2]-q[#q][2])+math.abs(q[1][3]-q[#q][3])<=1e-9 then q[#q]=nil end
        local ar,mx,my={0,0,0},0,0
        for i=1,#q do
          local c3=cross3(sub3(q[i],q[1]),sub3(q[i%#q+1],q[1]))
          ar={ar[1]+c3[1],ar[2]+c3[2],ar[3]+c3[3]}
          mx,my=mx+q[i][4],my+q[i][5]
        end
        local cx,cy=math.floor(mx/#q),math.floor(my/#q)
        local c=at(cx,cy)
        if #q>=3 and dot3(ar,ar)>1e-16 and c and (isCompCell(c,comp) or c.overhangOf==comp) then
          local list,r=opaque,underRect(c.mid)
          if c.hasOver then list,r=cutoutOver,overRect(c.mid) end
          if r then
            -- texel-exact inside the tile, the atlas inset kept at its edges:
            -- the outline's steps fall on texel lines, and an inset-scaled
            -- column would take the transparent texel beside a step
            local W,H,f=atlas.w,atlas.h,{}
            local ex=type(W)=="number" and W>0 and type(H)=="number" and H>0
            local au,av=ex and (16-(r[3]-r[1])*W)/2,ex and (16-(r[4]-r[2])*H)/2
            for i,p in ipairs(q) do
              local tx,ty=(p[4]-cx)*16,(p[5]-cy)*16
              f[i]={{p[1],p[2],p[3]},ex and {r[1]+(math.max(au,math.min(16-au,tx))-au)/W,r[2]+(math.max(av,math.min(16-av,ty))-av)/H}
                or {r[1]+tx/16*(r[3]-r[1]),r[2]+ty/16*(r[4]-r[2])}}
            end
            fanN(list,f,n)
          end
        end
      end
    end
    local function P(u,h,z,X,Y) return {x0+u/16,gy+h*tv,z,X or x0+u/16,Y} end
    -- each texel column's first opaque row (the back outline; -16 = the
    -- roof row's top row)
    local back={}
    for X=0,Wt-1 do
      local c=at(x0+math.floor(X/16),z0-1)
      local o=c and c.hasOver and atlas.texels(c.mid,"over")
      back[X]=0
      if o then for row=0,15 do
        local v=o[row*16+X%16+1]
        if type(v)=="number" and v>=0 then back[X]=row-16;break end
      end end
    end
    -- (overhangs) the eave plan: 3 texels front and back, 2 at the sides
    local EV=grid.eavePlan(comp,{gy=gy,tv=tv,hT=hT,Wt=Wt,xs=x0,z1=z1,zs=function() return z0 end,
      dF=3,dB=3,dL=2,dR=2,left=true,right=true})
    -- User-approved Celadon B6 silhouette: its sloped ends share the
    -- plateau's front/back extent. Keep actual slope heights and lateral
    -- eave eligibility; only this house uses plateau clearance for width.
    if input.mapId=="FR_CELADON_CITY" and input.pair=="general__rom_082d4b3c"
        and comp.nativeBlueRoof and comp.k32 and x0==24 and x1==30 and z0==17 and z1==19 then
      local wide=grid.eavePlan(comp,{gy=gy,tv=tv,hT=function()return 24 end,Wt=Wt,xs=x0,z1=z1,zs=function()return z0 end,
        dF=3,dB=3,dL=2,dR=2,left=true,right=true})
      EV.f,EV.b,EV.fn,EV.bn=wide.f,wide.b,wide.fn,wide.bn
      EV.dL,EV.dR=math.min(EV.dL,wide.dL),math.min(EV.dR,wide.dR)
    end
    -- the art row of a run's top at z: its outline at M0 = z0 - its back
    -- depth, its fold at M1 = z1 + its front depth (every art row shown)
    local function rowAt(s,z)
      local M0,M1=z0-s.b/16,z1+s.f/16
      if z==M1 then return s.fold end
      return s.back+(s.fold-s.back)*(z-M0)/(M1-M0)
    end
    -- the columns, merged where they share their outline row and one plane
    -- (the art's outline and band step every 2 columns over the slopes)
    -- and their eave depths
    local segs={}
    for X=0,Wt-1 do
      local part=(hT(X)==24 and hT(X+1)==24) and 0 or X<Wt/2 and -1 or 1
      local l=segs[#segs]
      if l and l.part==part and l.back==back[X] and l.f==EV.f[X] and l.b==EV.b[X] then l.ub=X+1
      else segs[#segs+1]={ua=X,ub=X+1,back=back[X],part=part,f=EV.f[X],b=EV.b[X],zs=z0} end
    end
    -- the band: rows 8..10 of the plain trim cell beside the left end
    local Xb=x0+1+8.5/16
    local plain=sideArt.plain and sideArt.plain.W
    local split={}
    for _,s in ipairs(segs) do
      local ua,ub=s.ua,s.ub
      local ha,hb=hT(ua),hT(ub)
      local fold=32-hT((ua+ub)/2)
      s.fold=fold
      local dy=(hb-ha)*tv*16/(ub-ua)
      local za,zb=z0-s.b/16,z1+s.f/16
      local r0,r1=rowAt(s,za),rowAt(s,zb)
      -- top
      face({P(ua,ha,za,nil,z0+r0/16),P(ub,hb,za,nil,z0+r0/16),P(ub,hb,zb,nil,z0+r1/16),P(ua,ha,zb,nil,z0+r1/16)},norm3({-dy,1,0}))
      if ua==0 or ub==Wt then
        local zz={}
        local M0,M1=z0-s.b/16,z1+s.f/16
        for k=math.floor(r0/16)+1,math.ceil(r1/16)-1 do zz[#zz+1]=M0+(M1-M0)*(k*16-s.back)/(fold-s.back) end
        split[ua==0 and "L" or "R"]=zz
      end
      -- front: the art itself (with an eave: the wall up to the soffit,
      -- the band on the eave's edge)
      if s.f>0 then
        face({P(ua,16,z1,nil,z1-16/16),P(ub,16,z1,nil,z1-16/16),P(ub,hb-3,z1,nil,z1-(hb-3)/16),P(ua,ha-3,z1,nil,z1-(ha-3)/16)},N_S)
        face({P(ua,ha-3,zb,nil,z1-(ha-3)/16),P(ub,hb-3,zb,nil,z1-(hb-3)/16),P(ub,hb,zb,nil,z1-hb/16),P(ua,ha,zb,nil,z1-ha/16)},N_S)
      else
        face({P(ua,16,z1,nil,z1-16/16),P(ub,16,z1,nil,z1-16/16),P(ub,hb,z1,nil,z1-hb/16),P(ua,ha,z1,nil,z1-ha/16)},N_S)
      end
      -- back: plain wall up to the slab's underside, the band on its edge
      if ha>19 or hb>19 then
        local w={{P(ub,16,z0)},{P(ua,16,z0)},{P(ua,ha-3,z0)},{P(ub,hb-3,z0)}}
        if ha==19 then table.remove(w,3) elseif hb==19 then table.remove(w,4) end
        if plain then
          local r=plain[2]
          for _,p in ipairs(w) do p[2]={(r[1]+r[3])/2,(r[2]+r[4])/2} end
          fanN(plain[1],w,N_N)
        else
          local q={}
          for i,p in ipairs(w) do q[i]=p[1];q[i][4],q[i][5]=Xb,z0+12.5/16 end
          face(q,N_N)
        end
      end
      face({P(ub,hb-3,za,Xb,z0+11/16),P(ua,ha-3,za,Xb,z0+11/16),P(ua,ha,za,Xb,z0+8/16),P(ub,hb,za,Xb,z0+8/16)},N_N)
    end
    -- side edges, split where the outer column's top crosses into the roof
    -- row (none where a side eave runs on: its band is on the eave's edge)
    for _,e in ipairs({{x0,N_W,split.L,EV.dL},{x1,N_E,split.R,EV.dR}}) do
      if e[4]<=0 then
        local zs={z0}
        for _,z in ipairs(e[3] or {}) do if z>z0+1e-9 and z<z1-1e-9 then zs[#zs+1]=z end end
        zs[#zs+1]=z1
        for i=1,#zs-1 do
          local a,b=zs[i],zs[i+1]
          face({{e[1],gy+16*tv,a,Xb,z0+11/16},{e[1],gy+16*tv,b,Xb,z0+11/16},{e[1],gy+19*tv,b,Xb,z0+8/16},{e[1],gy+19*tv,a,Xb,z0+8/16}},e[2])
        end
      end
    end
    -- (overhangs) soffits, caps and the side eaves
    EV.runs,EV.split=segs,split
    EV.capL,EV.capR={f=true,b=true},{f=true,b=true}
    EV.rowAt=function(s,z) return z0+rowAt(s,z)/16 end
    EV.xa={x0+0.5/16,x1-0.5/16}
    -- (eave colour) the side eaves' fill: the top's art in the 4 columns
    -- inside each side's outline column, back outline -> fold
    if EV.dL>0 or EV.dR>0 then
      local function own(c) return c~=nil and (isCompCell(c,comp) or c.overhangOf==comp) end
      local function cols(a,b)
        local t={}
        for X=a,b do t[#t+1]={x0*16+X,z0*16+back[X],z0*16+math.floor(32-hT(X+0.5))} end
        return t
      end
      EV.fill={EV.dL>0 and grid.eaveFill(own,cols(1,4)) or nil,EV.dR>0 and grid.eaveFill(own,cols(Wt-5,Wt-2)) or nil}
    end
    grid.eaveEmit(EV,face,P,hT,tv,gy,z1,Wt,Xb,z0+8/16)
    return function(px)
      return gy+hT(math.max(0,math.min(Wt,(px-x0)*16)))*tv
    end
  end
  -- (house flat-top rollout, Claude 2026-10-01; USER: houses in general
  -- are "flat tops with sloping sides", Bill's cottage a "flat peak") The
  -- K32 construction for the other house kinds that draw it (K33 Saffron,
  -- K24 Cerulean, K20 Pallet, K41 Day Care, K42 Sea Cottage), read from
  -- their art in 2.5D per comp.flatHouse (grid.flatRule): Bt = the house's
  -- depth in texel rows (its cell rows x 16); the centre drip row d (the
  -- band's bottom: 424a6b), the band rows d-2..d; the flat top stands
  -- top = Bt-d+2 high, the side walls F = Bt-d-1-D (D = the slopes' drop:
  -- 5 rows; 13 on the cottage). Per roof segment (one per house; two on a
  -- double house) the flat top runs from column uL to uR (from the
  -- per-column drip) and the slopes drop D rows to the segment's ends.
  -- Faces as grid.k32Roof: the front = the art itself, (x, row = Bt - h),
  -- from F up to the roof edge; the top = per texel column, the art from
  -- its first opaque row (the back outline; cells that are not the
  -- house's own -- a tree, a neighbour -- are skipped) to the fold row,
  -- back -> front; the back = the plain wall colour up to the slab and the
  -- band's rows on its edge; the outer side edges = the band's rows. A
  -- piece is drawn from OVER where its cell has OVER opaque over the
  -- piece's texels (always on the walkable row behind: its UNDER is the
  -- terrain); else from UNDER, with the OVER over it (FACADE_OVER_LIFT).
  -- No ridge; flush on all four sides (no eave: OV-2). Returns roofAt.
  -- (chimney, Claude 2026-10-01; USER: "chimney on bills house being
  -- rendered flat": the grey box with the dark opening on the Sea
  -- Cottage's right slope must stand up from the slope as a real box, its
  -- art 1:1 and the opening on top) A chimney drawn on a flat-top house's
  -- slope, read from its own pixels (texels; rows r from the house's first
  -- cell row, columns u from its west wall): its outline columns u0 and
  -- u1-1 (5a5a73), its top from its back rim row rT to the row above rF, the
  -- front's first row (the adbdce highlight), its front from rF down to its
  -- base outline (per column the last opaque OVER row, base(u)). In the
  -- art's oblique (row = depth - height) the front's west foot meets the
  -- slope at base(u0), so the box's top stands Hc = hT(u0) + base(u0) - rF;
  -- the top is rF - rT texels deep (1:1); the front plane stands where the
  -- slope's own art scale (the column beside the box) puts the foot, so the
  -- slope in front keeps its rows from the foot line to the fold at that
  -- scale. Faces (all OVER): top = art rows rT..rF-1 (a clear rim corner
  -- takes the texel below it); front = art rows from rF 1:1 down to the
  -- slope (every texel opaque: checked); sides and back = the front's plain
  -- column uS 1:1 (below its row base(uS)-1: that row). The slope under the
  -- box is not drawn; behind it run the slope's own stripes (the art's
  -- UNDER row rS under every base, where the OVER is clear). heightAt and
  -- collision are unchanged (roofAt is the slope). Keyed by map and the
  -- house's corner { minX, minY, u0, u1, uS }; fails closed (the art stays
  -- painted on the slope) on any mismatch.
  grid.CHIMNEY={FR_ROUTE_25={49,1,56,72,66}}
  grid.chimneyPlan=function(comp,A)
    local sp=grid.CHIMNEY[input.mapId]
    if not sp or comp.minX~=sp[1] or comp.minY~=sp[2] or A.u0~=0 or A.si~=1 or #A.S.segs~=1 or type(atlas.texels)~="function" then return nil end
    local u0,u1,uS=sp[3],sp[4],sp[5]
    local hT,x0,z0,z1,Bt,face,P,EV,gy,tv=A.hT,A.x0,A.z0,A.z1,A.Bt,A.face,A.P,A.EV,A.gy,A.tv
    local uL,uR=A.S.segs[1][3],A.S.segs[1][4]
    if not ((u0>=uR and u1<=A.Wt) or (u0>=0 and u1<=uL)) then return nil end
    local function tex(u,r,layer)
      local c=at(x0+math.floor(u/16),z0+math.floor(r/16))
      if not c or not isCompCell(c,comp) then return nil end
      local t
      if layer=="over" then t=c.hasOver and atlas.texels(c.mid,"over") else t=atlas.texels(c.mid,"under") end
      local v=t and t[(r%16)*16+u%16+1]
