    end
    local rT,rF
    for r=0,15 do if not rT and tex(u0+1,r,"over") then rT=r end end
    if not rT then return nil end
    for r=rT+1,rT+32 do if not rF and tex(u0+1,r,"over")==0xadbdce then rF=r end end
    if not rF or rF-rT<3 then return nil end
    for r=rT+1,rF-1 do
      if tex(u0,r,"over")~=0x5a5a73 or tex(u1-1,r,"over")~=0x5a5a73 then return nil end
      for u=u0,u1-1 do if not tex(u,r,"over") then return nil end end
