    local CH={u0=u0,u1=u1,Hc=Hc,zB=zB,zF=zF}
    -- one top run s (ua..ub) of the box's columns: the stripes behind the
    -- box, the slope's own art in front of it (rows foot line -> fold, affine)
    CH.top=function(s,za,zb,ua,ub,ha,hb,dy)
      local n=norm3({-dy,1,0})
      face({P(ua,ha,za,nil,Ys),P(ub,hb,za,nil,Ys),P(ub,hb,zB,nil,Ys),P(ua,ha,zB,nil,Ys)},n,"under")
      face({P(ua,ha,zF,nil,Yh(ha)),P(ub,hb,zF,nil,Yh(hb)),P(ub,hb,zb,nil,z0+(Bt-hb)/16),P(ua,ha,zb,nil,z0+(Bt-ha)/16)},n)
    end
    -- a wall polygon (art Y 1:1 in h) whose rows past rE-1 hold that row
    local function wall(pts,n)
