      wall({P(u0,hl,zB,XS,Yh(hl)),P(u1,hr,zB,XS,Yh(hr)),P(u1,Hc,zB,XS,Yh(Hc)),P(u0,Hc,zB,XS,Yh(Hc))},N_N)
