      and input.width==48 and input.height==40 and atlas.w==256 and atlas.h==416 and C.FENCE_H==.6 and C.WALL_ROW_UNIT==1
      and comp and comp.flatHouse and not input.isBorder and comp.minX==8 and comp.maxX==14 and comp.minY==9 and comp.maxY==11 and comp.flatHouse.ext
    if c022Rear then
      local expected={{683,7,0,0,false},{686,0,3,0,true},{687,113,3,101,true},{679,0,3,0,true},{684,7,0,0,false},{684,7,0,0,false},{685,7,0,0,false}}
      local rearPath={1,211,212,213,1,8,1}
      for i,e in ipairs(expected)do local c=at(7+i,8);local n=at(7+i,7)
        if not c or c.mid~=e[1]or c.coll~=e[2]or c.elev~=e[3]or c.beh~=e[4]or c.walkable~=e[5]or not c.hasOver
          or not n or n.mid~=rearPath[i]or n.coll~=0 or n.elev~=3 or n.beh~=0 or not n.walkable then c022Rear=false end
      end
    end
    if c022Rear then
      -- Share the complete material/atlas gate with the attached return.
      -- Otherwise that return could activate while uniformRear falls back.
      local slots={[231]=154,[656]=292,[664]=300,[679]=315,[680]=316,[681]=317,[682]=318,[683]=319,[684]=320,[685]=321,[686]=322,[687]=323,[688]=324,[689]=325,[690]=326,[694]=330,[695]=331,[696]=332,[698]=333,[705]=339,[706]=340,[707]=341,[708]=342}
      local function validRect(mid,r)
        local slot=slots[mid];if not slot or type(r)~='table'then return false end
        for i=1,4 do if type(r[i])~='number'or r[i]~=r[i]or math.abs(r[i])==math.huge then return false end end
        local x,y=slot%16*16,math.floor(slot/16)*16
        return math.abs(r[1]*atlas.w-x-1/32)<1e-7 and math.abs(r[2]*atlas.h-y-1/32)<1e-7
          and math.abs(r[3]*atlas.w-x-16+1/32)<1e-7 and math.abs(r[4]*atlas.h-y-16+1/32)<1e-7
      end
      local t=atlas.texels(231,'under');local h=0
      if not t or not validRect(231,underRect(231))then c022Rear=false else
        for i=1,256 do local v=t[i];if type(v)~='number'or v~=v or v<0 or v==math.huge then c022Rear=false;break end;h=(h*31+v+2)%2147483647 end
        if h~=982508660 then c022Rear=false end
      end
      for y=8,11 do for x=8,14 do local c=at(x,y)
        if not c then c022Rear=false else for _,ly in ipairs{'under','over'}do if ly=='under'or c.hasOver then
          local t=atlas.texels(c.mid,ly);local r=ly=='under'and underRect(c.mid)or overRect(c.mid)
          if not t or not validRect(c.mid,r)then c022Rear=false else for i=1,256 do local v=t[i];if type(v)~='number'or v~=v or math.abs(v)==math.huge then c022Rear=false end end end
        end end end
      end end
    end
    return c022Rear
  end
