  grid.bikeShopAwning=function(comp)
    local profile=comp.nativeBuildingProfile
    if not(profile and profile.nativeBikeShop)then return end
    grid.nativeBikeShop=true
    local gy=comp.groundY;local xa,xb=12+2/16,16-2/16
    local low,high=gy+8/16,gy+23/16
    local function clip(poly,key,bound,greater)
      local out={};if #poly==0 then return out end;local a=poly[#poly]
      for _,b in ipairs(poly)do local da=(a[key]-bound)*(greater and 1 or-1);local db=(b[key]-bound)*(greater and 1 or-1)
        if(da>=-1e-9)~=(db>=-1e-9)then local t=da/(da-db);local v={};for k=1,8 do v[k]=a[k]+t*(b[k]-a[k])end;out[#out+1]=v end
        if db>=-1e-9 then out[#out+1]=b end;a=b
      end;return out
    end
    local function emit(list,q)
      for j=2,#q-1 do local a,b,c=q[1],q[j],q[j+1];local cross=cross3(sub3(b,a),sub3(c,a))
        if dot3(cross,cross)>1e-20 then list[#list+1]=a;list[#list+1]=b;list[#list+1]=c end
      end
    end
    -- Remove the projected awning from both facade layers. Windows, outer
    -- corner strips and the native doorway below remain on their wall plane.
    for _,list in ipairs{opaque,cutoutOver,cutoutUnder,cutoutKeyed}do local src={};for i,v in ipairs(list)do src[i]=v end
      for i=#list,1,-1 do list[i]=nil end
      for i=1,#src,3 do local a,b,c=src[i],src[i+1],src[i+2]
        local yes=true;for _,v in ipairs{a,b,c}do if v[1]<12-1e-8 or v[1]>16+1e-8 or math.abs(v[3]-29)>.01 or v[8]<.99 then yes=false end end
        if yes then local p={a,b,c}
          emit(list,clip(p,1,xa,false));emit(list,clip(p,1,xb,true))
          p=clip(clip(p,1,xa,true),1,xb,false)
          -- The lower lateral cells contain the sprite's projected posts
          -- and foot shadows. Their supports now stand at the canopy edge;
          -- keep the native doorway between x13..15 on the facade unchanged.
          local lower=clip(p,2,low,false)
          emit(list,clip(lower,1,12.25,false))
          emit(list,clip(clip(lower,1,13,true),1,15,false))
          emit(list,clip(lower,1,15.75,true))
          emit(list,clip(p,2,high,true))
        else list[#list+1]=a;list[#list+1]=b;list[#list+1]=c end
      end
    end
    -- Remove the same projected feet from their original ground pixels.
    -- Their clean same-row background lives immediately beside each stem.
    -- Native669/671 art/state is included in the existing shop profile guard.
    for _,q in ipairs{{12,669,5},{15,671,8}}do
      local left,right=q[1]+q[3]/16,q[1]+(q[3]+3)/16
      for _,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do
        local src={};for i,v in ipairs(list)do src[i]=v end;for i=#list,1,-1 do list[i]=nil end
        for i=1,#src,3 do local a,b,c=src[i],src[i+1],src[i+2];local yes=true
          for _,v in ipairs{a,b,c}do
            if v[1]<q[1]-1e-8 or v[1]>q[1]+1+1e-8 or v[3]<29-1e-8 or v[3]>30+1e-8 or math.abs(v[2]-gy)>1e-8 or v[7]<.99 then yes=false end
          end
          if yes then local p={a,b,c}
            emit(list,clip(p,1,left,false));emit(list,clip(p,1,right,true))
            p=clip(clip(p,1,left,true),1,right,false)
            emit(list,clip(p,3,29,false));emit(list,clip(p,3,29.25,true))
          else list[#list+1]=a;list[#list+1]=b;list[#list+1]=c end
        end
      end
      local first=#opaque+1;local r=underRect(q[2])
      for y=0,3 do local uv=subRect(r,4.5/16,(y+.5)/16,4.5/16,(y+.5)/16)
        hQuad(opaque,left,29+y/16,right,29+(y+1)/16,gy,uv,UP)
      end
      for i=first,#opaque,3 do local a,b,c=opaque[i],opaque[i+1],opaque[i+2]
        if dot3(cross3(sub3(b,a),sub3(c,a)),UP)<0 then opaque[i+1],opaque[i+2]=c,b end
        for j=i,i+2 do opaque[j].nativeBikePostGroundClean=true end
      end
    end
    local marks={#opaque,#cutoutOver}
    local shade=overRect(667);local gray=subRect(shade,8.5/16,12.5/16,8.5/16,12.5/16)
    local dark=underRect(661);dark=subRect(dark,8.5/16,8.5/16,8.5/16,8.5/16)
    wallQuad(cutoutOver,xa,29,xb,29,gy+1,high,gray,N_S)
    wallQuad(opaque,xa,29,xb,29,low,gy+1,dark,N_S)
    -- Clean native wall texel replaces only the detached 2D support art.
    -- These panels stop at the existing rounded front-corner tangencies.
    local postWallStart=#opaque+1
    for _,span in ipairs{{12.25,13},{15,15.75}}do
      wallQuad(opaque,span[1],29,span[2],29,gy,low,dark,N_S)
    end
    for i=postWallStart,#opaque do opaque[i].nativeBikePostWallClean=true end
    local first=#cutoutOver+1
    local mount,lip,front=high,gy+20/16,29.75
    local slope=norm3({0,front-29,mount-lip})
    for x=12,15 do
      local mid=at(x,27).mid;local r=overRect(mid);local a=math.max(x,xa);local b=math.min(x+1,xb)
      local uv=subRect(r,(a-x),9/16,(b-x),1)
