      local c=at(x,28);local valance=c.hasOver and overRect(c.mid)or underRect(c.mid)
      local vu=subRect(valance,a-x,0,b-x,8/16)
      wallQuad(c.hasOver and cutoutOver or opaque,a,front,b,front,lip-8/16,lip,vu,N_S)
      -- Thin underside, using a clean native shadow donor.
