    for _,x in ipairs{12+3/16,16-4/16}do
      for _,e in ipairs{'up','down','left','right'}do faceQuad(opaque,e,x,x+1/16,front-1/16,front+1/16,gy,lip-.5,uv)end
      hQuad(opaque,x,front-1/16,x+1/16,front+1/16,lip-.5,uv,UP)
    end
