  end

  -- Exact-profile admission is owned by the caller, before generic producers.
  grid.emitBikeShopBikes=function()
    if not grid.nativeBikeShop then return end
    local mask={
      '................#...............',
      '...............###..............',
      '...............###..............',
      '...............###..............',
      '...............###....###.......',
      '...............#####.#####......',
      '...............###########......',
      '...............###########......',
      '..............###############...',
      '.............##################.',
      '............####################',
      '............###...##############',
      '............################.###',
      '.............#######.##.#######.',
      '...............###........###...',
      '................................',
    }
    local function kept(x,y)
      return x>=0 and x<32 and y>=0 and y<16 and mask[y+1]:sub(x+1,x+1)=='#'
    end
    local function pixel(mid,x,y)
      local r=assert(underRect(mid))
      local u=(math.floor(r[1]*atlas.w)+x+.5)/atlas.w
      local v=(math.floor(r[2]*atlas.h)+y+.5)/atlas.h
      return {u,v,u,v}
    end
    -- Own winding instead of relying on a producer's historical conventions.
    local function q(points,uv,n,tag)
      local a,b,c=points[1],points[2],points[3]
      local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
      local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
      if (uy*vz-uz*vy)*n[1]+(uz*vx-ux*vz)*n[2]+(ux*vy-uy*vx)*n[3]<0 then
        points={points[1],points[4],points[3],points[2]}
