      quad(opaque,points[1],points[2],points[3],points[4],uv,n)
      for i=first,#opaque do
        if tag then opaque[i].nativeBikeShopBike=tag else opaque[i].nativeBikeShopGround=true end
      end
    end
    local gy=.75
    -- Replace only native744's flat ground producer, not neighboring path art.
    -- The admitted profile pins atlas744; all three UVs must be inside its slot.
    local r=assert(underRect(744));local keep={}
    for i=1,#opaque,3 do
      local remove=true
      for j=i,i+2 do local v=opaque[j]
        if v[1]<10-1e-8 or v[1]>11+1e-8 or v[3]<25-1e-8 or v[3]>28+1e-8
            or math.abs(v[2]-gy)>1e-6 or v[4]<r[1]-1e-8 or v[4]>r[3]+1e-8
            or v[5]<r[2]-1e-8 or v[5]>r[4]+1e-8 then remove=false end
      end
      if not remove then keep[#keep+1]=opaque[i];keep[#keep+1]=opaque[i+1];keep[#keep+1]=opaque[i+2]end
    end
