    for i=#opaque,#keep+1,-1 do opaque[i]=nil end
    for row=25,27 do
      --744's visible background agrees exactly with native221. Hidden745
      --grass is reconstructed from17 only inside native bike/shadow pixels.
      for x=0,31 do for y=0,15 do
        local mid=x<16 and 221 or 745
        if x>=16 then
          local c=atlas.texels(745,'under')[y*16+x%16+1]
          if kept(x,y)or((y==14 or y==15)and c==0x7b7b84)then mid=17 end
        end
        local xa,xb=10+x/16,10+(x+1)/16
        local za,zb=row+y/16,row+(y+1)/16
        q({{xa,gy,za},{xb,gy,za},{xb,gy,zb},{xa,gy,zb}},pixel(mid,x%16,y),{0,1,0})
      end end
      local z0,z1=row+.5-1/16,row+.5+1/16
      for y=0,15 do for x=0,31 do if kept(x,y)then
        local xa,xb=10+x/16,10+(x+1)/16
        local lo,hi=gy+(14-y)/16,gy+(15-y)/16
        local uv=pixel(x<16 and 744 or 745,x%16,y)
        q({{xa,hi,z1},{xb,hi,z1},{xb,lo,z1},{xa,lo,z1}},uv,{0,0,1},row)
        q({{xb,hi,z0},{xa,hi,z0},{xa,lo,z0},{xb,lo,z0}},uv,{0,0,-1},row)
        if not kept(x-1,y)then q({{xa,hi,z0},{xa,hi,z1},{xa,lo,z1},{xa,lo,z0}},uv,{-1,0,0},row)end
        if not kept(x+1,y)then q({{xb,hi,z1},{xb,hi,z0},{xb,lo,z0},{xb,lo,z1}},uv,{1,0,0},row)end
        if not kept(x,y-1)then q({{xa,hi,z0},{xb,hi,z0},{xb,hi,z1},{xa,hi,z1}},uv,{0,1,0},row)end
        if not kept(x,y+1)then q({{xa,lo,z1},{xb,lo,z1},{xb,lo,z0},{xa,lo,z0}},uv,{0,-1,0},row)end
      end end end
    end
  end


  grid.bikeRoundRoof=function(comp,o0,c0)
    if not(comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeBikeShop)then return end
    local base,top=comp.wallTopY,comp.wallTopY+C.FLAT_ROOF_PARAPET
    local radius,steps=.25,6
    local corners={{12+radius,24+radius,math.pi,12,24},{16-radius,24+radius,1.5*math.pi,16,24},
      {16-radius,29-radius,0,16,29},{12+radius,29-radius,.5*math.pi,12,29}}
    local planes,arcs={},{}
    for _,corner in ipairs(corners)do local arc={}
      for i=0,steps do local angle=corner[3]+i/steps*math.pi/2;arc[#arc+1]={corner[1]+radius*math.cos(angle),corner[2]+radius*math.sin(angle)}end
      arcs[#arcs+1]=arc
      for i=1,#arc-1 do planes[#planes+1]={arc[i],arc[i+1]}end
    end
    local shade={}
    for li,list in ipairs{opaque,cutoutOver}do for i=(li==1 and o0 or c0)+1,#list,3 do local a,b,c=list[i],list[i+1],list[i+2]
      if a[2]>=base-1e-8 and b[2]>=base-1e-8 and c[2]>=base-1e-8 and math.abs(a[7])<.01 then
        local side=a[8]>.9 and 'front'or a[8]<-.9 and 'back'or a[6]>.9 and 'right'or a[6]<-.9 and 'left'
        if side and not shade[side]then shade[side]={list,(a[4]+b[4]+c[4])/3,(a[5]+b[5]+c[5])/3}end
      end
    end end
    local function clip(poly,edge)
      local out={};if #poly==0 then return out end
      local a,b=edge[1],edge[2]
      local function dist(v)return(b[1]-a[1])*(v[3]-a[2])-(b[2]-a[2])*(v[1]-a[1])end
      local v=poly[#poly];local dv=dist(v)
      for _,w in ipairs(poly)do local dw=dist(w)
        if(dv>=-1e-10)~=(dw>=-1e-10)then local t=dv/(dv-dw);local p={};for k=1,8 do p[k]=v[k]+t*(w[k]-v[k])end;out[#out+1]=p end
        if dw>=-1e-10 then out[#out+1]=w end;v,dv=w,dw
      end;return out
    end
    for li,list in ipairs{opaque,cutoutOver}do local first=(li==1 and o0 or c0)+1;local old={}
      for i=first,#list do old[#old+1]=list[i]end;for i=#list,first,-1 do list[i]=nil end
      for i=1,#old,3 do local a,b,c=old[i],old[i+1],old[i+2]
        if a[2]>=base-1e-8 and b[2]>=base-1e-8 and c[2]>=base-1e-8 then
          local poly={a,b,c};for _,edge in ipairs(planes)do poly=clip(poly,edge)end
          for j=2,#poly-1 do local x,y,z=poly[1],poly[j],poly[j+1];local cross=cross3(sub3(y,x),sub3(z,x))
            if dot3(cross,cross)>1e-20 then if dot3(cross,{a[6],a[7],a[8]})<0 then y,z=z,y end;for _,p in ipairs{x,y,z}do local v={};for k,value in pairs(a)do v[k]=value end;for k=1,8 do v[k]=p[k]end;v.nativeBikeRoundedRoof=true;list[#list+1]=v end end
          end
        else list[#list+1]=a;list[#list+1]=b;list[#list+1]=c end
      end
    end
    local function emit(q,s,n)
      local list=s[1];local a,b,c=q[1],q[2],q[3];local cross=cross3(sub3(b,a),sub3(c,a))
      if dot3(cross,n)<0 then q={q[1],q[4]or q[3],q[3]or q[2],q[2]}end
      local indices=#q==3 and{1,2,3}or{1,2,3,1,3,4}
      for _,i in ipairs(indices)do local p=q[i];vN(list,p[1],p[2],p[3],s[2],s[3],n[1],n[2],n[3]);list[#list].nativeBikeRoundedRoof=true;list[#list].nativeBikeRoundedRim=true end
    end
    for ci,arc in ipairs(arcs)do local corner=corners[ci]
      for i=1,#arc-1 do local a,b=arc[i],arc[i+1];local angle=corner[3]+(i-.5)/steps*math.pi/2
        local nx,nz=math.cos(angle),math.sin(angle)
        local s=shade[math.abs(nx)>math.abs(nz)and(nx<0 and'left'or'right')or(nz<0 and'back'or'front')]
        assert(s,'native roof rim material missing')
        emit({{a[1],base,a[2]},{b[1],base,b[2]},{b[1],top,b[2]},{a[1],top,a[2]}},s,{nx,0,nz})
        -- Close the tiny exposed wall-top shoulder below the round rim.
        local p1,p2,p3={corner[4],base,corner[5]},{a[1],base,a[2]},{b[1],base,b[2]}
        local cross=cross3(sub3(p2,p1),sub3(p3,p1));if cross[2]<0 then p2,p3=p3,p2 end
        for _,p in ipairs{p1,p2,p3}do vN(s[1],p[1],p[2],p[3],s[2],s[3],0,1,0);s[1][#s[1]].nativeBikeRoundedRoof=true;s[1][#s[1]].nativeBikeRoundedShoulder=true end
      end
    end
    comp.nativeBikeRoundedRoof={radius=radius,steps=steps}
  end


  grid.bikeRoundBody=function(comp,sideArt)
    if not(comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeBikeShop and sideArt.wallFn)then return end
    local radius,steps=.25,6
    local corners={{12+radius,24+radius,math.pi},{16-radius,24+radius,1.5*math.pi},
      {16-radius,29-radius,0},{12+radius,29-radius,.5*math.pi}}
    local planes,arcs={},{}
    for _,corner in ipairs(corners)do local arc={}
      for i=0,steps do local a=corner[3]+i/steps*math.pi/2;arc[#arc+1]={corner[1]+radius*math.cos(a),corner[2]+radius*math.sin(a)}end
      arcs[#arcs+1]=arc;for i=1,#arc-1 do planes[#planes+1]={arc[i],arc[i+1]}end
    end
    local function clip(poly,edge)
      local out={};if #poly==0 then return out end;local a,b=edge[1],edge[2]
      local function dist(v)local x=math.max(12,math.min(16,v[1]));local z=math.max(24,math.min(29,v[3]));return(b[1]-a[1])*(z-a[2])-(b[2]-a[2])*(x-a[1])end
      local v=poly[#poly];local dv=dist(v)
      for _,w in ipairs(poly)do local dw=dist(w)
        if(dv>=-1e-10)~=(dw>=-1e-10)then local t=dv/(dv-dw);local p={};for k=1,8 do p[k]=v[k]+t*(w[k]-v[k])end;out[#out+1]=p end
        if dw>=-1e-10 then out[#out+1]=w end;v,dv=w,dw
      end;return out
    end
    for _,list in ipairs{opaque,cutoutOver,cutoutUnder,cutoutKeyed}do local old={};for i,v in ipairs(list)do old[i]=v end;for i=#list,1,-1 do list[i]=nil end
      for i=1,#old,3 do local a,b,c=old[i],old[i+1],old[i+2]
        local eligible=not a.nativeBikeRoundedRoof and not a.nativeBikeShopCanopy and math.abs(a[7])<.01
        for _,v in ipairs{a,b,c}do if v[1]<12-1e-8 or v[1]>16+1e-8 or v[3]<24-1e-8 or v[3]>29.01 or v[2]<comp.groundY-1e-8 or v[2]>comp.wallTopY+1e-8 then eligible=false end end
        if a.nativeBikeRoundedShoulder then
          -- The body now closes the round perimeter; no square shoulder.
        elseif eligible then
          local poly={a,b,c};for _,edge in ipairs(planes)do poly=clip(poly,edge)end
          for j=2,#poly-1 do local x,y,z=poly[1],poly[j],poly[j+1];local cross=cross3(sub3(y,x),sub3(z,x))
            if dot3(cross,cross)>1e-20 then
              if dot3(cross,{a[6],a[7],a[8]})<0 then y,z=z,y end
              for _,p in ipairs{x,y,z}do local v={};for k,value in pairs(a)do v[k]=value end;for k=1,8 do v[k]=p[k]end;v.nativeBikeRoundedWallClip=true;list[#list+1]=v end
            end
          end
        else list[#list+1]=a;list[#list+1]=b;list[#list+1]=c end
      end
    end
    for ci,arc in ipairs(arcs)do for i=1,#arc-1 do local a,b=arc[i],arc[i+1]
      local angle=corners[ci][3]+(i-.5)/steps*math.pi/2;local n={math.cos(angle),0,math.sin(angle)}
      local starts={#opaque,#cutoutOver,#cutoutUnder,#cutoutKeyed}
      -- Reuse the established native side-wall generator, including bottom
      -- trim and material phase, on the exact arc beneath the roof rim.
      sideArt.wallFn(a[1],a[2],b[1],b[2],comp.groundY,comp.wallTopY,n,true)
      for li,list in ipairs{opaque,cutoutOver,cutoutUnder,cutoutKeyed}do for j=starts[li]+1,#list,3 do local x,y,z=list[j],list[j+1],list[j+2]
        local cross=cross3(sub3(y,x),sub3(z,x));if dot3(cross,n)<0 then list[j+1],list[j+2]=z,y end
        for k=j,j+2 do list[k].nativeBikeRoundedBody=ci;list[k].nativeBikeRoundedBodySegment=i end
      end end
    end end
    comp.nativeBikeRoundedBody={radius=radius,steps=steps,base=comp.groundY,top=comp.wallTopY}
  end


  grid.saffronSidingPatch=function(comp,sideArt)
    if input.mapId~='FR_SAFFRON_CITY' or input.pair~='general__rom_082d4b9c' or input.width~=66 or input.height~=56 or input.isBorder then return end
    if grid.saffronSidingReady==nil then
      local h=0;local valid=true
      for y=0,55 do for x=0,65 do local c=input.cellAt(x,y)
        if not c then valid=false else for _,v in ipairs{c.mid,c.collision,c.elevation,c.behavior or 0,c.layerType,c.walkable and 1 or 0}do h=(h*31+(v>=0 and v+2 or 1))%2147483647 end end
      end end
      valid=valid and h==1367463910
      for _,q in ipairs{{667,174315250,1109960938},{672,1219460179,0},{684,756779902,1246461258},{833,2027900847,578746799}}do for i,ly in ipairs{'under','over'}do local t=atlas.texels(q[1],ly);local hh=0
        if t then for k=1,256 do local v=t[k];hh=(hh*31+(type(v)=='number'and v>=0 and v+2 or 1))%2147483647 end end
        if hh~=q[i+1]then valid=false end
      end end
      grid.saffronSidingReady=valid
    end
    if not grid.saffronSidingReady then return end
    local profile=comp.nativeBuildingProfile and comp.nativeBuildingProfile.name
    local function pattern(r,u0,v0,u1,v1,tw,th,list)
      return {list or opaque,subRect(r,u0/16,v0/16,u1/16,v1/16),tw=tw,th=th,cu=u0==u1}
    end
    if comp.flatHouse then
      -- Native yellow beam course and purple base, carried over exposed
      -- sides/rear by the existing Emerald wall generator. No window crops.
      local r=overRect(667);local base=underRect(672)
      sideArt.plain={W={opaque,subRect(base,3.5/16,1.5/16,3.5/16,1.5/16)},
        P=pattern(r,1.5,7.5,1.5,11.5,1/16,1,cutoutOver),
        T={opaque,subRect(base,10.5/16,9.5/16,10.5/16,14.5/16)},tier=1,note='native Saffron wall courses'}
      sideArt.posts=nil;comp.nativeSaffronSiding=true
    elseif profile=='silph-native-core' then
      local r=underRect(684)
      sideArt.plain={W={opaque,r},P=pattern(r,.5,.5,15.5,15.5,1,1),tier=1,note='native Silph floor/window bands'}
      sideArt.posts=nil;comp.nativeSaffronSiding=true
    elseif profile=='saffron-yellow-boxed-native' then
      local r=overRect(667);local base=underRect(672)
      sideArt.plain={W={opaque,subRect(base,3.5/16,.5/16,3.5/16,.5/16)},P=pattern(r,1.5,7.5,1.5,11.5,1/16,1,cutoutOver),
        T={opaque,subRect(base,10.5/16,9.5/16,10.5/16,14.5/16)},tier=1,note='native Saffron wall courses'}
      sideArt.posts=nil;comp.nativeSaffronSiding=true
    elseif comp.minX==37 and comp.minY==8 and comp.maxX==42 and comp.maxY==11 then
      local r=overRect(833)
      sideArt.plain={W={cutoutOver,r},P=pattern(r,.5,.5,15.5,15.5,1,1,cutoutOver),tier=1,note='native Dojo masonry'}
      sideArt.posts=nil;comp.nativeSaffronSiding=true
    end
  end

  grid.saffronSideFinish=function(comp,sideArt,info)
    if not grid.saffronSidingReady or C.WALL_ROW_UNIT~=1 then return end
    local dojo=comp.minX==37 and comp.minY==8 and comp.maxX==42 and comp.maxY==11
    local gym=comp.minX==43 and comp.minY==8 and comp.maxX==49 and comp.maxY==11
    if not dojo and not gym then return end
    if grid.saffronSideFinishReady==nil then
      local ok=true
      for _,q in ipairs({{821,139013144,0},{829,1917750492,0},{773,886080871,0},{784,1314990607,0},{833,2027900847,578746799},{837,859486658,215487112},{839,579956415,0},{745,859486658,0}})do for j,ly in ipairs{'under','over'}do local tx=atlas.texels(q[1],ly);local h=0
        if tx then for i=1,256 do local v=tx[i];h=(h*31+(type(v)=='number'and v>=0 and v+2 or 1))%2147483647 end end
        if h~=q[j+1]then ok=false end
      end end
      grid.saffronSideFinishReady=ok
    end
    if not grid.saffronSideFinishReady then return end
    local x0,x1,z0,z1=comp.minX,comp.maxX+1,comp.minY,comp.maxY+1
    local y0,y1=comp.groundY,comp.wallTopY
    -- Replace only exposed vertical side/rear planes. Native fronts, entrance
    -- fixtures and the authored roof keep their existing emitters.
    for _,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do local keep={}
      for i=1,#list,3 do local replace=true
        for j=i,i+2 do local v=list[j]
          local plane=(math.abs(v[1]-x0)<1e-7 and (v[6]<-.99 or gym and v[6]>.99))or(math.abs(v[1]-x1)<1e-7 and v[6]>.99)or(math.abs(v[3]-z0)<1e-7 and v[8]<-.99)
          if not plane or v.dojoSpinePart or v[1]<x0-1e-8 or v[1]>x1+1e-8 or v[3]<z0-1e-8 or v[3]>z1+1e-8 or v[2]<y0-1e-8 or v[2]>y1+1e-8 then replace=false end
        end
        if not replace then for j=i,i+2 do keep[#keep+1]=list[j]end end
      end
      for i=#list,1,-1 do list[i]=nil end;for _,v in ipairs(keep)do list[#list+1]=v end
    end
    local starts={#opaque+1,#cutoutUnder+1,#cutoutOver+1,#cutoutKeyed+1}
    if gym then
      local r=underRect(784)
      sideArt.plain={W={opaque,subRect(r,10.5/16,.5/16,10.5/16,.5/16)},
        P={opaque,subRect(r,10.5/16,.5/16,14.5/16,5.5/16),tw=.25,th=.375},tier=1}
    end
    local post=dojo and subRect(underRect(821),.5/16,4.5/16,3.5/16,15.5/16)or subRect(underRect(773),.5/16,.5/16,3.5/16,15.5/16)
    local function wall(ax,az,bx,bz,n)
      local dx,dz=bx-ax,bz-az;local len=math.sqrt(dx*dx+dz*dz);local t=.1875/len
      sideArt.wallFn(ax+dx*t,az+dz*t,bx-dx*t,bz-dz*t,y0,y1,n,true)
      wallQuad(opaque,ax,az,ax+dx*t,az+dz*t,y0,y1,post,n)
      wallQuad(opaque,bx-dx*t,bz-dz*t,bx,bz,y0,y1,post,n)
    end
    wall(x1,z0,x0,z0,N_N)
    wall(x0,z0,x0,z1,N_W)
    if not dojo then wall(x1,z1,x1,z0,N_E)end
    local count=0
    for li,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do
      for i=starts[li],#list,3 do local a,b,c=list[i],list[i+1],list[i+2]
        if dot3(cross3(sub3(b,a),sub3(c,a)),{a[6],a[7],a[8]})<0 then list[i+1],list[i+2]=c,b end
        for j=i,i+2 do list[j].nativeSaffronSideFinish=dojo and 'dojo'or'gym'end;count=count+1
      end
    end
    info.sideSrc='native-emerald-panel-post';info.nativeSaffronSideFinish=count
  end

  grid.saffronHouseSides=function(comp,sideArt,ceiling,knots)
    if not grid.saffronSidingReady or C.WALL_ROW_UNIT~=1 then return end
    local yellow=comp.nativeBuildingProfile and comp.nativeBuildingProfile.name=='saffron-yellow-boxed-native'
    if not comp.flatHouse and not yellow then return end
    if grid.saffronHouseReady==nil then local ok=true
      for _,q in ipairs({{644,185255843,0},{652,1720696334,0},{655,174315250,1762294835},{661,859486658,1655087609},{662,859486658,1672288104},{663,859486658,1365793596},{667,174315250,1109960938},{668,174315250,1639167296},{669,174315250,1396078708},{670,174315250,1844978365},{671,174315250,12833585},{672,1219460179,0},{676,292762785,0},{677,174315250,174428148},{678,174315250,1894204863},{679,174315250,2144404997},{686,1475267695,0},{687,174315250,1288524703},{702,174315250,107079174},{703,174315250,987947310},{745,859486658,0}})do for j,ly in ipairs{'under','over'}do local tx=atlas.texels(q[1],ly);local h=0
        if tx then for i=1,256 do local v=tx[i];h=(h*31+(type(v)=='number'and v>=0 and v+2 or 1))%2147483647 end end
        if h~=q[j+1]then ok=false end
      end end
      -- Three visible columns are exactly the complete eastern native house.
      for z=17,21 do for x=26,28 do local a,b=input.cellAt(x,z),input.cellAt(x+20,z)
        if not a or not b or a.mid~=b.mid then ok=false end
      end end
      grid.saffronHouseReady=ok
    end
    if not grid.saffronHouseReady then return end
    local x0,x1,z0,z1=comp.minX,comp.maxX+1,comp.minY,comp.maxY+1
    local gy=comp.groundY;ceiling=ceiling or function()return comp.wallTopY end;knots=knots or{x0,x1}
    local function clip(poly,fn,greater)
      local out={};if #poly==0 then return out end;local a=poly[#poly]
      for _,b in ipairs(poly)do local da,db=fn(a),fn(b);if not greater then da,db=-da,-db end
        if(da>=-1e-9)~=(db>=-1e-9)then local t=da/(da-db);local v={};for k,val in pairs(a)do v[k]=val end;for k=1,8 do v[k]=a[k]+(b[k]-a[k])*t end;out[#out+1]=v end
        if db>=-1e-9 then out[#out+1]=b end;a=b
      end;return out
    end
    local function append(list,poly,tag)
      for j=2,#poly-1 do local a,b,c=poly[1],poly[j],poly[j+1];local n=cross3(sub3(b,a),sub3(c,a))
        if dot3(n,n)>1e-20 then
          if dot3(n,{a[6],a[7],a[8]})<0 then b,c=c,b end
          for _,v in ipairs{a,b,c}do local q={};for k,val in pairs(v)do q[k]=val end;if tag then q.nativeSaffronHouseSide=comp.minX..','..comp.minY end;list[#list+1]=q end
        end
      end
    end
    local lists={opaque,cutoutUnder,cutoutOver,cutoutKeyed}
    -- Preserve roof/eave faces above the actual profile; replace the body
    -- below it. The ceiling comes from the existing roof, never a color run.
    for _,list in ipairs(lists)do local keep={}
      for i=1,#list,3 do local t={list[i],list[i+1],list[i+2]};local side
        for _,v in ipairs(t)do local k=math.abs(v[1]-x0)<.005 and v[6]<-.99 and'W'or math.abs(v[1]-x1)<.005 and v[6]>.99 and'E'or math.abs(v[3]-z0)<.005 and v[8]<-.99 and'N'
          if not k or side and side~=k or v[1]<x0-1e-8 or v[1]>x1+1e-8 or v[3]<z0-1e-8 or v[3]>z1+1e-8 then side=false;break end;side=k
        end
        if not side then for _,v in ipairs(t)do keep[#keep+1]=v end
        else
          for k=1,#knots-1 do local a,b=knots[k],knots[k+1];local aa,bb=ceiling(a),ceiling(b)
            local poly=clip(clip(t,function(v)return v[1]-a end,true),function(v)return v[1]-b end,false)
            -- End planes fall on adjacent knot boundaries; only one interval owns them.
            if side=='N'or side=='W'and k==1 or side=='E'and k==#knots-1 then
              append(keep,clip(poly,function(v)return v[2]-gy end,false))
              append(keep,clip(poly,function(v)return v[2]-(aa+(bb-aa)*(v[1]-a)/(b-a)) end,true))
            end
          end
        end
      end
      for i=#list,1,-1 do list[i]=nil end;for _,v in ipairs(keep)do list[#list+1]=v end
    end
    local post=subRect(underRect(672),.5/16,.5/16,2.5/16,14.5/16)
    local function emit(ax,az,bx,bz,n)
      local lo,hi=math.min(ax,bx),math.max(ax,bx);local maxY=gy
      for _,x in ipairs(knots)do maxY=math.max(maxY,ceiling(x))end
      local starts={};for i,list in ipairs(lists)do starts[i]=#list end
      local dx,dz=bx-ax,bz-az;local len=math.abs(dx)+math.abs(dz);local t=2/16/len
      sideArt.wallFn(ax+dx*t,az+dz*t,bx-dx*t,bz-dz*t,gy,maxY,n,true)
      wallQuad(opaque,ax,az,ax+dx*t,az+dz*t,gy,maxY,post,n)
      wallQuad(opaque,bx-dx*t,bz-dz*t,bx,bz,gy,maxY,post,n)
      for li,list in ipairs(lists)do local old={};for i=starts[li]+1,#list do old[#old+1]=list[i]end;for i=#list,starts[li]+1,-1 do list[i]=nil end
