      local ceiling=comp.nativeSaffronHouseCeiling;local x0,x1,z0,z1=comp.minX,comp.maxX+1,comp.minY,comp.maxY+1
      -- Deferred neighbor-facing producers run after each roof. Close their
      -- native three-pixel side returns here, after every deferred emission.
      for _,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do local keep={}
        for i=1,#list,3 do local t={list[i],list[i+1],list[i+2]};local yes=true;local edge
          for _,v in ipairs(t)do local x=math.abs(v[1]-x0)<.009 and v[6]<-.99 and x0 or math.abs(v[1]-x1)<.009 and v[6]>.99 and x1 or nil
