      for li,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do local out={};grid.saffronHiddenTemplate.lists[li]=out
        for _,v in ipairs(list)do if v.nativeSaffronHouseOwner=='46,18'then local q={};for k,val in pairs(v)do q[k]=val end;out[#out+1]=q end end
      end
    end
  end
  grid.saffronHouseCapture=function(comp,info)
