  grid.dojoSpineRoof=function(comp,ro0,rc0)
    if not grid.saffronSidingReady or comp.minX~=37 or comp.maxX~=42 or comp.minY~=8 or comp.maxY~=11
      or C.WALL_ROW_UNIT~=1 or not deps.BuildingProfiles or not deps.BuildingProfiles.seviiRoofTemplate then return end
    for _,q in ipairs{{817,1049955294},{824,196452708},{825,1763378380},{826,877793716},{832,468227840},{833,578746799},{834,1661556021}}do local t=atlas.texels(q[1],'over');local h=0
      if not t then return end;for i=1,256 do local v=t[i];h=(h*31+(type(v)=='number'and v>=0 and v+2 or 1))%2147483647 end
      if h~=q[2]then return end
    end
    -- Replace just this building's roof producer range. Native walls,
    -- doorway, entrance and all other producers are outside these ranges.
    for i=#opaque,ro0+1,-1 do opaque[i]=nil end
    for i=#cutoutOver,rc0+1,-1 do cutoutOver[i]=nil end
    local function clip(poly,k,bound,greater)
      if #poly==0 then return poly end;local out={};local a=poly[#poly]
      for _,b in ipairs(poly)do local da=(a[k]-bound)*(greater and 1 or-1);local db=(b[k]-bound)*(greater and 1 or-1)
        if(da>=-1e-9)~=(db>=-1e-9)then local t=da/(da-db);local v={};for j=1,5 do v[j]=a[j]+(b[j]-a[j])*t end;out[#out+1]=v end
        if db>=-1e-9 then out[#out+1]=b end;a=b
      end;return out
    end
    local count=0
    local function emit(poly,uv,tag)
      if #poly<3 then return end
      local vs={};for _,v in ipairs(poly)do
        local x=v[1]<0 and v[1]or v[1]>80 and 96+v[1]-80 or v[1]*96/80
        vs[#vs+1]={37+x/16,comp.wallTopY+(v[2]-21)/16,8+v[3]/16,
          uv[1]+(uv[3]-uv[1])*v[4],uv[2]+(uv[4]-uv[2])*v[5]}
      end
      for j=2,#vs-1 do local a,b,c=vs[1],vs[j],vs[j+1]
        local nx=(b[2]-a[2])*(c[3]-a[3])-(b[3]-a[3])*(c[2]-a[2]);local ny=(b[3]-a[3])*(c[1]-a[1])-(b[1]-a[1])*(c[3]-a[3]);local nz=(b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1]);local len=math.sqrt(nx*nx+ny*ny+nz*nz)
        if len>1e-10 then for _,v in ipairs{a,b,c}do vN(cutoutOver,v[1],v[2],v[3],v[4],v[5],nx/len,ny/len,nz/len);cutoutOver[#cutoutOver].dojoSpinePart=tag end;count=count+1 end
      end
    end
    for _,t in ipairs(deps.BuildingProfiles.seviiRoofTemplate)do
      if t.tag:find('slope')or t.tag:find('hip')then
        local p={};for _,v in ipairs(t.p)do p[#p+1]={v[1],v[2],v[3],8+(v[4]-8)*80/64,152+(v[5]-20)*24/22}end
        local minU,maxU,minV,maxV=999,-999,999,-999
        for _,v in ipairs(p)do minU=math.min(minU,v[4]);maxU=math.max(maxU,v[4]);minV=math.min(minV,v[5]);maxV=math.max(maxV,v[5])end
        for cy=math.floor((minV+1e-8)/16),math.floor((maxV-1e-8)/16)do for cx=math.floor((minU+1e-8)/16),math.floor((maxU-1e-8)/16)do
          local q=p;for _,b in ipairs{{4,cx*16,true},{4,(cx+1)*16,false},{5,cy*16,true},{5,(cy+1)*16,false}}do q=clip(q,b[1],b[2],b[3])end
          if #q>=3 then local cell=at(37+cx,cy);local r=cell and overRect(cell.mid);assert(r,'native Dojo roof donor')
            local z={};for _,v in ipairs(q)do z[#z+1]={v[1],v[2],v[3],(v[4]-cx*16)/16,(v[5]-cy*16)/16}end;emit(z,r,t.tag)
          end
        end end
      else
        local fascia=t.tag:find('fascia');local r=overRect(fascia and 825 or 817)
        local uv=subRect(r,8.5/16,(fascia and 3.5 or 10.5)/16,8.5/16,(fascia and 7.5 or 15.5)/16)
        local p={};for _,v in ipairs(t.p)do p[#p+1]={v[1],v[2],v[3],0,fascia and(45-v[5])/3 or t.tag=='roof.cap'and 0 or (45.332865452560171-v[2])/8}end
        emit(p,uv,t.tag)
      end
    end
    -- Close the underside of the modest two-pixel projection using native
    -- gray rim, through the existing horizontal-quad construction.
    local uv=subRect(overRect(825),8.5/16,5.5/16,8.5/16,5.5/16)
    for _,r in ipairs{{36.875,43.125,7.875,8},{36.875,43.125,12,12.125},{36.875,37,8,12},{43,43.125,8,12}}do
      quad(cutoutOver,{r[1],comp.wallTopY,r[3]},{r[1],comp.wallTopY,r[4]},{r[2],comp.wallTopY,r[4]},{r[2],comp.wallTopY,r[3]},uv,DOWN)
      for i=#cutoutOver-5,#cutoutOver do cutoutOver[i].dojoSpinePart='roof.soffit'end;count=count+2
    end
    comp.nativeDojoSpine={triangles=count,ridgeY=comp.wallTopY+(45.332865452560171-21)/16,ridgeZ=10,source='shared Sevii spined-hip roof template; native Dojo art'}
    return count
  end
  grid.saffronGateFinish=function()
