            for _,mid in ipairs(gateMids)do local r=(mid~=120 and mid~=121 and mid~=231 or q.id=='E'or q.id=='W')and(li==3 and overRect(mid)or underRect(mid))
              if r and v[4]>=r[1]-1e-8 and v[4]<=r[3]+1e-8 and v[5]>=r[2]-1e-8 and v[5]<=r[4]+1e-8 then owned=true;break end
            end
            if not owned or v[1]<(q.id=='W'and 1 or q.id=='E'and 53 or q.x0)-.03 or v[1]>(q.id=='W'and 13 or q.id=='E'and 66 or q.x1)+.03 or v[3]<q.z0-1.03 or v[3]>q.z1+(q.ns and .03 or 2.03) or v[2]<gy-.021 then mine=false end
            if v[2]>gy+.021 then raised=true end
