            local plane=true;local visible=false
            for j=i,i+2 do local v=list[j]
              if(math.abs(v[1]-q.x0)>.03 and math.abs(v[1]-q.x1)>.03)or math.abs(v[6])<.99 or v[3]<q.z0-.021 or v[3]>q.z1+.021 or v[2]<gy-.021 or v[2]>4.8 then plane=false end
              if v[2]>gy+.021 then visible=true end
            end
            if plane and visible then mine=true;raised=true end
          end
          if not(mine and raised)then for j=i,i+2 do keep[#keep+1]=list[j]end end
        end
        for i=#list,1,-1 do list[i]=nil end;for _,v in ipairs(keep)do list[#list+1]=v end;starts[li]=#list
      end
      local function native(mid,ly,u0,v0,u1,v1)return subRect(ly=='over'and overRect(mid)or underRect(mid),u0,v0,u1,v1)end
      local P={opaque,native(437,'under',0,12/16,1,1),tw=1,th=.25}
