          for _,pp in ipairs{{0,.5,438,0,.5},{4.5,5,439,.5,1}}do for _,ly in ipairs{'under','over'}do face(pp[1],pp[2],top,top-1,pp[3],ly,pp[4],0,pp[5],1)end end
          for i=0,3 do for _,ly in ipairs{'under','over'}do face(.5+i,1.5+i,top,top-1,437,ly,0,0,1,1)end end
          local center=west and 3.5 or 1.5
