            for _,pp in ipairs{{center-1,center-.5,mids[1],.5,1},{center-.5,center+.5,mids[2],0,1},{center+.5,center+1,mids[3],0,.5}}do
              for _,ly in ipairs{'under','over'}do if ly=='under'or overRect(pp[3])then
                local list=ly=='over'and cutoutOver or opaque;local first=#list
