        for i=starts[li]+1,#list,3 do local a,b,c=list[i],list[i+1],list[i+2]
          local nx=(b[2]-a[2])*(c[3]-a[3])-(b[3]-a[3])*(c[2]-a[2]);local ny=(b[3]-a[3])*(c[1]-a[1])-(b[1]-a[1])*(c[3]-a[3]);local nz=(b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1])
