    for _,q in ipairs{{748,1277037198,0},{781,441763278,0},{797,1800042468,0},{798,1029680589,0},{811,1277037198,1445816783},{812,361366172,0},{819,502985360,0},{820,1256490381,0},{821,139013144,0},{822,569412893,0},{823,1394147615,0},{827,618257793,0},{829,1917750492,0},{830,1104187019,0},{831,821030527,0},{835,386990023,0}}do for i,ly in ipairs{'under','over'}do local t=atlas.texels(q[1],ly);local h=0
      if t then for k=1,256 do local v=t[k];h=(h*31+(type(v)=='number'and v>=0 and v+2 or 1))%2147483647 end end
      if h~=q[i+1]then return end
    end end
