        for j=i,i+2 do local v=list[j]
          if v.dojoSpinePart or v[1]<37-1e-8 or v[1]>43+1e-8 or v[3]<11.99 or v[3]>13.021 or v[2]<.75-1e-8 or v[2]>2.001 then mine=false end
