      local zA=physicalRearZ or(S.ext and not uniformRear and z0-1 or z0)
      local function ext(X) return pairedHouse and comp.minX==8 or not uniformRear and S.ext and S.ext[x0+math.floor((u0+X)/16)] or false end
      local function zst(X) return ext(X) and zA or z0 end
