      -- remain unchanged; the existing native flatHouse guard precedes this.
      if input.mapId=="FR_CERULEAN_CITY" and input.pair=="general__rom_082d4af4"
          and (smoothCerulean or pairedHouse or(comp.minX==15 and comp.maxX==20 and comp.minY==8 and comp.maxY==11)) then
        local wide=grid.eavePlan(comp,{gy=gy,tv=tv,hT=function()return top end,Wt=Wt,xs=xs,z1=z1,zs=zst,
