      -- a plain wall polygon { {pos}, ... } facing n
      local function plainQuad(pts,n,skipExit)
        if rearExit and n==N_N and not skipExit then
          local onRear=true;for _,p in ipairs(pts)do if math.abs(p[1][3]-rearExit.z)>1e-8 then onRear=false end end
          if onRear then
            local poly={};for _,p in ipairs(pts)do poly[#poly+1]=p[1]end
            local function clip(poly,key,bound,greater)
