              for _,b in ipairs(poly)do local da=(a[key]-bound)*(greater and 1 or-1);local db=(b[key]-bound)*(greater and 1 or-1)
                if(da>=-1e-9)~=(db>=-1e-9)then local t=da/(da-db);local v={};for j=1,3 do v[j]=a[j]+(b[j]-a[j])*t end;out[#out+1]=v end
                if db>=-1e-9 then out[#out+1]=b end;a=b
