            for _,piece in ipairs(pieces)do
              local q={};for _,p in ipairs(piece)do local last=q[#q]and q[#q][1]
                if not last or math.abs(last[1]-p[1])+math.abs(last[2]-p[2])+math.abs(last[3]-p[3])>1e-9 then q[#q+1]={p}end
              end
              if #q>1 then local a,b=q[1][1],q[#q][1];if math.abs(a[1]-b[1])+math.abs(a[2]-b[2])+math.abs(a[3]-b[3])<1e-9 then q[#q]=nil end end
              if #q>=3 then local area=0;for j=2,#q-1 do local cross=cross3(sub3(q[j][1],q[1][1]),sub3(q[j+1][1],q[1][1]));area=area+dot3(cross,n)end
                if math.abs(area)>1e-12 then local first=#opaque+1;plainQuad(q,n,true);for i=first,#opaque do opaque[i].nativeC022PairedBody=true end end
              end
            end
