          for i,p in ipairs(pts)do local a,b=p[1],pts[i%#pts+1][1]
            poly[#poly+1]=a;xmin=math.min(xmin,a[axis]);xmax=math.max(xmax,a[axis]);ymin=math.min(ymin,a[2]);ymax=math.max(ymax,a[2])
