                if math.abs(dot)>1e-12 then if dot<0 then b,c=c,b end
                  for _,v in ipairs{a,b,c}do if n==N_N then v.nativeCeruleanRearSiding=comp.minX elseif n==N_S then v.nativeCeruleanFrontReveal=comp.minX else v.nativeCeruleanSideSiding=comp.minX end;list[#list+1]=v end
                end
