            if c then
              for i = 1, 256 do
                local v = vis(c, i)
                if v >= 0 then pal[v] = (pal[v] or 0) + 1; tot = tot + 1 end
              end
            end
          end
        end
        local rows = wallRows
        for yy = comp.maxY - wallRows, comp.minY, -1 do
          if rows >= C.MAX_WALL_ROWS_TALL then break end
          local rc, rt, best, bn, inP = {}, 0, nil, 0, 0
          for x = comp.minX + 1, comp.maxX - 1 do
            local c = at(x, yy)
            if c and isCompCell(c, comp) then
              for i = 1, 256 do
                local v = vis(c, i)
                if v >= 0 then
                  rt = rt + 1
                  rc[v] = (rc[v] or 0) + 1
                  if rc[v] > bn then best, bn = v, rc[v] end
                  if (pal[v] or 0) >= 8 then inP = inP + 1 end
                end
              end
            end
          end
          if rt == 0 or inP / rt < C.TALL_ROW_MATCH or (pal[best] or 0) < 0.1 * tot then break end
          rows = rows + 1
        end
        if rows > wallRows and (comp.maxY - rows) - comp.minY + 1 >= 2 then
          comp.tall = true
          return rows
        end
        return wallRows
      end)()
    end
    -- Celadon Dept Store: the yellow caps and repeated glass are six
    -- facade rows, not roof. Keep the three native roof rows. Match both
    -- halves of the original art/layout; this is not a general glass rule.
    if input.mapId == "FR_CELADON_CITY" and input.pair == "general__rom_082d4b3c"
      and comp.minY == 6 and comp.maxY == 14
      and ((comp.minX == 9 and comp.maxX == 12) or (comp.minX == 13 and comp.maxX == 17))
      and type(atlas.texels) == "function" then
      local native = {
        {649,650,653,654,654,654,655,650,651},
        {649,650,661,662,662,662,663,650,651},
        {657,658,669,670,670,670,671,658,659},
        {665,666,656,667,648,666,656,667,668},
        {673,674,664,675,644,674,664,675,676},
        {673,674,664,675,644,674,664,675,676},
        {673,674,672,675,644,674,672,675,676},
        {673,674,652,675,644,674,652,675,676},
        {681,682,660,683,644,682,660,683,684},
      }
      local matches, checked = true, {}
      for ry, row in ipairs(native) do
        for rx, mid in ipairs(row) do
          local c = at(rx + 8, ry + 5)
          if not c or c.mid ~= mid then matches = false; break end
          if not checked[mid] then
            local u = atlas.texels(mid, "under")
            local o = c.hasOver and atlas.texels(mid, "over") or nil
            for i = 1, 256 do
              if not u or type(u[i]) ~= "number" or (c.hasOver and (not o or type(o[i]) ~= "number")) then
                matches = false; break
              end
            end
            checked[mid] = true
          end
          if not matches then break end
        end
        if not matches then break end
      end
      if matches then
        wallRows = 6; comp.tall = true
        -- Bay feet use native art just south of the solid footprint.
        local south = {677,678,366,679,686,678,366,679,680}
        for i,mid in ipairs(south) do
          local c=at(i+8,15)
          local u=c and c.mid==mid and atlas.texels(mid,"under")
          if not c or not c.walkable or not u then matches=false;break end
          for j=1,256 do if type(u[j])~="number" then matches=false;break end end
          if not matches then break end
        end
        comp.deptBays = matches and C.FOLD_25D ~= false and C.WALL_ROW_UNIT == 1 or nil
      end
    end
    -- Prize Room row 19 is the native brick wall below its cream roof;
    -- its opaque OVER is not evidence of another roof row.
    if comp.nativeFlatRoof and comp.minX == 38 and comp.minY == 17 then wallRows = 2 end
    if comp.nativeBlueRoof then wallRows=1 end
    -- (flat-top rollout) the side walls are F texels: whole facade rows
    if comp.flatHouse then wallRows=comp.flatHouse.F/16;comp.tall=false end
    comp.nativeBuildingProfile=nativeBuildingProfile(deps,input,comp,atlas)
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeSeviiPurple and not(C.WALL_ROW_UNIT==1 and C.WALL_HEIGHT_MIN==1.25 and C.EAVE_OVERHANG==.2 and C.ROOF_OVERHANG_PUSH==.6 and C.DOOR_INSET==.12 and C.FACADE_OVER_LIFT==.004 and C.FOLD_25D~=false) then comp.nativeBuildingProfile=comp.nativeBuildingProfile.nativeSeviiFallback end
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeThreeIsland
        and not(C.WALL_ROW_UNIT==1 and C.EAVE_OVERHANG==.2 and C.ROOF_OVERHANG_PUSH==.6)then comp.nativeBuildingProfile=nil end
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeSafariNorth
        and not(C.WALL_ROW_UNIT==1 and C.WALL_HEIGHT_MIN==1.25 and C.EAVE_OVERHANG==.2 and C.ROOF_OVERHANG_PUSH==.6 and C.FLAT_ROOF_PARAPET==.25)then comp.nativeBuildingProfile=nil end
    if comp.nativeBuildingProfile then
      wallRows=comp.nativeBuildingProfile.wallRows
      comp.tall=comp.nativeBuildingProfile.fullFacade==true or comp.nativeBuildingProfile.tall==true or wallRows>C.MAX_WALL_ROWS
      if comp.nativeBuildingProfile.fullFacade or comp.nativeBuildingProfile.flatRoof==true then comp.nativeFlatRoof=true end
    end
    comp.wallRows = wallRows
    comp.wallHeight = math.max(C.WALL_HEIGHT_MIN, math.min(comp.tall and wallRows * C.WALL_ROW_UNIT or C.WALL_HEIGHT_MAX, wallRows * C.WALL_ROW_UNIT))
    -- (K32 r3) the walls stand as tall as the facade row; grid.k32Roof
    -- raises the front and back to the slab and puts the slab on top
    if comp.k32 then comp.wallHeight=wallRows*C.WALL_ROW_UNIT end
    -- Exact native profile: partial facade follows the authored whole rows.
    -- Generic minimum height would otherwise leave a gap before its strip.
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeRowHeight==true then
      comp.wallHeight=wallRows*C.WALL_ROW_UNIT
    end
    comp.roofTop, comp.roofBottom = comp.minY, comp.maxY - wallRows
    -- Celadon's native green slab/facade boundary is inside one tile:
    -- roof/rim rows 0..11, facade/window tops 12..15. Keep full wall rows
    -- unchanged and append only a quarter-row after their normal emitters.
    comp.partialFacade = nil
    if input.mapId == "FR_CELADON_CITY" and input.pair == "general__rom_082d4b3c"
        and type(atlas.texels) == "function" and type(atlas.h) == "number" and atlas.h > 0
        and type(atlas.w) == "number" and atlas.w > 0 then
      local signature
      if comp.minX == 4 and comp.maxX == 8 and comp.minY == 5 and comp.maxY == 11 and wallRows == 4 then
        signature = {744,745,746,747,748}
      elseif comp.minX == 18 and comp.maxX == 24 and comp.minY == 5 and comp.maxY == 11 and wallRows == 4 then
        signature = {744,768,769,746,770,771,748}
      elseif comp.minX == 44 and comp.maxX == 51 and comp.minY == 18 and comp.maxY == 21 and wallRows == 2 then
        signature = {744,745,747,748,744,745,747,748}
      elseif comp.minX == 4 and comp.maxX == 7 and comp.minY == 25 and comp.maxY == 29 and wallRows == 2 then
        signature = {744,745,747,748}
      elseif (comp.minX == 32 and comp.maxX == 39 or comp.minX == 44 and comp.maxX == 51)
          and comp.minY == 26 and comp.maxY == 29 and wallRows == 2 then
        signature = {744,745,747,748,744,745,747,748}
      elseif comp.minX == 40 and comp.maxX == 43 and comp.minY == 26 and comp.maxY == 29 and wallRows == 2 then
        signature = {744,745,747,748}
      end
      if signature then
        local valid = true
        for i, mid in ipairs(signature) do
          local c = at(comp.minX + i - 1, comp.roofBottom)
          if not isCompCell(c, comp) or c.mid ~= mid or not c.hasOver then valid = false
          else
            local u, o = atlas.texels(mid, "under"), atlas.texels(mid, "over")
            if not u or not o then valid = false
            else for pixel = 193, 256 do
              if type(u[pixel]) ~= "number" or type(o[pixel]) ~= "number" then valid = false end
            end end
          end
        end
        if valid then
          comp.partialFacade = { row = comp.roofBottom, v0 = 12/16, height = C.WALL_ROW_UNIT * 4/16 }
          comp.wallHeight = comp.wallHeight + comp.partialFacade.height
        end
      end
    end

    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.partialFacadePixels then
      local pixels=comp.nativeBuildingProfile.partialFacadePixels
      assert(type(pixels)=="number"and pixels==math.floor(pixels)and pixels>=1 and pixels<=15,"invalid native facade pixels")
      comp.partialFacade={row=comp.roofBottom,v0=(16-pixels)/16,height=C.WALL_ROW_UNIT*pixels/16}
      comp.wallHeight=comp.wallHeight+comp.partialFacade.height
    end

    if comp.nativeDoorless and type(atlas.texels)=="function" and type(atlas.h)=="number" and atlas.h>0
        and type(atlas.w)=="number" and atlas.w>0 then
      local row=comp.nativeDoorless==2 and comp.maxY or comp.roofBottom
      local valid=true
      for x=comp.minX,comp.maxX do
        local c=at(x,row);local u=c and atlas.texels(c.mid,"under");local o=c and c.hasOver and atlas.texels(c.mid,"over")
        if not u or not o then valid=false else
          for pixel=193,256 do if type(u[pixel])~="number" or type(o[pixel])~="number" then valid=false end end
        end
      end
      if valid then
        comp.partialFacade={row=row,v0=12/16,height=C.WALL_ROW_UNIT*4/16}
        if comp.nativeDoorless==2 then
          -- Only the rear house's window tops survive the foreground
          -- occlusion in native art. Preserve its default enclosure height;
          -- infer no extra storey from the hidden lower facade.
          comp.roofBottom=row
          comp.partialFacade.height=C.WALL_ROW_UNIT*12/16
          comp.partialFacade.lowerRow=row+1
        else comp.wallHeight=comp.wallHeight+comp.partialFacade.height end
      end
    end

    -- M13: the roof art's top row lying on the walkable row behind the house.
    local oy = comp.minY - 1
    for x = comp.minX, comp.maxX do
      local c = at(x, oy)
      if c and c.walkable and c.hasOver and not c.isTreeArt then
        c.overhangOf = comp
        comp.overhang = true
      end
    end

    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeThreeIsland then
      -- Two walkable OVER courses belong to this exact native roof, never its body.
      comp.nativeRoofStart=comp.minY-2
      for x=comp.minX,comp.maxX do at(x,comp.nativeRoofStart).overhangOf=comp end
    end
    -- M5: signs / doors in the front row.
    for x = comp.minX, comp.maxX do
      local c = at(x, comp.maxY)
      if c and c.isSign and touchesComp(x, comp.maxY, comp) then c.facadeOf = comp end
      if c and c.isDoor and touchesComp(x, comp.maxY, comp) then c.doorOf = comp end
    end

    -- Roof tile (hip roofs and the 9-slice interior). Candidates: building
    -- cells in the roof rows. Rank: solid art (over coverage >= ROOF_SOLID
    -- _MIN, unknown coverage, or no over art) > votes > M12 interior score
    -- (roof neighbours on all 4 sides, the walkable roof-top row counting)
    -- > coverage > lowest mid.
    local function inRoofRows(x, yy)
      return yy >= comp.roofTop and yy <= comp.roofBottom and isCompCell(at(x, yy), comp)
    end
    local function score(x, yy)
      local s = 0
      for _, d in ipairs(DIRS) do
        local nx, ny = x + d.dx, yy + d.dy
        local nc = at(nx, ny)
        if inRoofRows(nx, ny) or (nc and nc.overhangOf == comp) then s = s + 1 end
      end
      return s
    end
    local votes, best, cellOf = {}, {}, {}
    for yy = comp.roofTop, comp.roofBottom do
      for x = comp.minX, comp.maxX do
        local c = at(x, yy)
        if isCompCell(c, comp) then
          votes[c.mid] = (votes[c.mid] or 0) + 1
          local s = score(x, yy)
          if best[c.mid] == nil or s > best[c.mid] then best[c.mid] = s end
          cellOf[c.mid] = cellOf[c.mid] or c
        end
      end
    end
    local function solidKey(c)
      if not c.hasOver then return 1 end
      local cov = overCoverage(c.mid)
      if cov == nil or cov >= C.ROOF_SOLID_MIN then return 1 end
      return 0
    end
    local function covKey(c)
      if not c.hasOver then return 1 end
      return overCoverage(c.mid) or 1
    end
    local roofCell
    for mid, c in pairs(cellOf) do
      local better
      if roofCell == nil then better = true
      else
        local b = roofCell
        local s1, s2 = solidKey(c), solidKey(b)
        if s1 ~= s2 then better = s1 > s2
        elseif votes[mid] ~= votes[b.mid] then better = votes[mid] > votes[b.mid]
        elseif best[mid] ~= best[b.mid] then better = best[mid] > best[b.mid]
        elseif covKey(c) ~= covKey(b) then better = covKey(c) > covKey(b)
        else better = mid < b.mid end
      end
      if better then roofCell = c end
    end
    comp.roofCell = roofCell
    comp.roofMid = roofCell and roofCell.mid or nil
    comp.roofCoverage = roofCell and roofCell.hasOver and overCoverage(roofCell.mid) or nil

    -- r11 (review M13): the walkable row carrying the roof's top art (the
    -- overhang) is part of the roof's depth: a standard 5x3 Sevii house
    -- (5x4 with it) gets a hip roof, not a flat slab
    local fw, fh = comp.maxX - comp.minX + 1, comp.maxY - comp.minY + 1 + (comp.nativeRoofStart and 2 or comp.overhang and 1 or 0)
    local aspect = math.max(fw, fh) / math.max(1, math.min(fw, fh))
    comp.flatRoof = aspect >= C.FLAT_ROOF_ASPECT_MIN or comp.tall or comp.nativeFlatRoof
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.flatRoof==false then comp.flatRoof=false end
    if comp.flatHouse then comp.flatRoof = false end -- (flat-top rollout: grid.flatTopRoof)

    -- 9-slice sources (flat roofs): per roof row, the most common interior
    -- (non-edge-column) building mid, lowest id on a tie.
    comp.nineInterior = {}
    for yy = comp.roofTop, comp.roofBottom do
      local v, rep = {}, {}
      for x = comp.minX + 1, comp.maxX - 1 do
        local c = at(x, yy)
        if isCompCell(c, comp) then
          v[c.mid] = (v[c.mid] or 0) + 1
          rep[c.mid] = rep[c.mid] or c
        end
      end
      local bm
      for mid in pairs(v) do
        if bm == nil or v[mid] > v[bm] or (v[mid] == v[bm] and mid < bm) then bm = mid end
      end
      comp.nineInterior[yy] = bm and rep[bm] or nil
    end
    -- (r11 review M13: with only two roof rows there is no middle row --
    -- the interior uses the bottom row, not the top row's ridge again)
    comp.nineMidRow = (comp.roofBottom - comp.roofTop >= 2) and (comp.roofTop + 1) or comp.roofBottom

    -- r7m M1: the building stands on the street in front of it (most
    -- common height of walkable cells in row maxY+1; higher on a tie).
    do
      local hv = {}
      for x = comp.minX, comp.maxX do
        local c = at(x, comp.maxY + 1)
        if c and c.walkable and not c.isWater then
          local k = math.floor(c.hgt * 1000 + 0.5)
          hv[k] = (hv[k] or 0) + 1
        end
      end
      local bk
      for k, n in pairs(hv) do
        if bk == nil or n > hv[bk] or (n == hv[bk] and k > bk) then bk = k end
      end
      if bk then
        comp.groundY = bk / 1000
      else
        local g = -math.huge
        for _, c in ipairs(comp.cells) do if c.hgt > g then g = c.hgt end end
        comp.groundY = g
      end
    end
    comp.wallTopY = comp.groundY + comp.wallHeight
  end

  -- (gym flat, Claude 2026-10-01; USER on the overhang sheet: "the gyms are
  -- flat roofed and you put the door on the walkway overhang") The nine gyms
  -- (C.FOLD_POSTS' corner-post art: the eight towns and the Saffron
  -- Connection copy) read from their art in 2.5D. Rows count from the facade
  -- row's top (C = maxY): roof top row T = C - 3 (the walkable row behind, or
  -- the box's first row), A, B, C, the porch row P = C + 1. The art draws a
  -- FLAT top (the louvred panel; back outline T row 1) with SLOPED side strips
  -- (columns 1-5: light stripes on the left, dark on the right; the outline
  -- drops 3 rows over them), a 6-row eave band (B rows 10-15: 5a5a73 7b7b84
  -- 5a5a73 7b7b84 7b7b84 424a6b) and a 23-row wall (C rows 0-15, P rows 0-6;
  -- the ground outline P row 6). The entrance block (the door's columns -7 ..
  -- +22) holds the door (the porch-row tile framed 424a6b), the jambs and the
  -- emblem panel. A gym whose art differs keeps the old build. grid.gymRule
  -- marks comp.gymFlat and gives the porch row's own walkable cells (their
  -- tiles draw the wall's foot and the door -- both now on the wall) the plain
  -- ground of the cell below; grid.gymBuild builds the gym.
  grid.gymRule=function()
    local FP=C.FOLD_POSTS
    if C.FOLD_25D==false or type(atlas.texels)~="function" or type(FP)~="table" or type(FP.L)~="table" or type(FP.R)~="table" then return end
    local function hit(t,c) return c~=nil and (t[c.mid] or (input.pair~=nil and t[input.pair..":"..c.mid])) and true or false end
    -- the composite texel (OVER where opaque, else UNDER) and its layer
    local function tex(c,tx,ty)
      if not c then return nil end
      local i=ty*16+tx+1
      local o=c.hasOver and atlas.texels(c.mid,"over")
      if o and type(o[i])=="number" and o[i]>=0 then return o[i],"over" end
      local u=atlas.texels(c.mid,"under")
      local v=u and u[i]
      if type(v)=="number" and v>=0 then return v,"under" end
      return nil
    end
    local BAND={[9]=0xad944a,[10]=0x5a5a73,[11]=0x7b7b84,[12]=0x5a5a73,[13]=0x7b7b84,[14]=0x7b7b84,[15]=0x424a6b}
    for _,comp in ipairs(buildings) do
      deps.yieldSafe()
      local x0,x1,cy=comp.minX,comp.maxX,comp.maxY
      local T,py=cy-3,cy+1
      local ok=hit(FP.L,at(x0,cy)) and hit(FP.R,at(x1,cy)) and x1-x0>=4 and (comp.minY==T or comp.minY==T+1)
      -- the roof's back outline (T row 1 of its OVER; a T cell is this gym's,
      -- its walkable roof row, or a blocked cell no building or block owns --
      -- Cerulean's back corner prop, Cinnabar's back row) and the band (B
      -- rows 9-15)
      local tOwn={}
      for x=x0,x1 do
        if not ok then break end
        local t=at(x,T)
        local q=t and compOf(t)
        if not (t and t.hasOver and (isCompCell(t,comp) or t.overhangOf==comp
            or not t.walkable and (q==nil or q.kind=="prop"))) then ok=false break end
        tOwn[t]=true
        local o=atlas.texels(t.mid,"over")
        for tx=4,11 do if not o or o[16+tx+1]~=0x5a5a73 then ok=false end end
        if ok and x>x0 and x<x1 then
          local b=at(x,cy-1)
          if not isCompCell(b,comp) then ok=false break end
          for ty,v in pairs(BAND) do for tx=0,15 do if tex(b,tx,ty)~=v then ok=false end end end
        end
      end
      -- the door: the porch-row tile framed 424a6b in its rows 0 and 13; the
      -- entrance panel's outline beside it (x - 1 column 9, x + 1 column 6)
      local xd
      if ok then
        for x=x0+2,x1-2 do
          local d,f=at(x,py),true
          for tx=0,15 do if tex(d,tx,0)~=0x424a6b or tex(d,tx,13)~=0x424a6b then f=false end end
          for ty=0,14 do if tex(at(x-1,cy),9,ty)~=0x424a6b or tex(at(x+1,cy),6,ty)~=0x424a6b then f=false end end
          if f then if xd then ok=false else xd=x end end
        end
        if not xd then ok=false end
      end
      -- the wall's ground outline (P row 6) under the plain wall columns
      if ok then
        for x=x0,x1 do
          if x<xd-1 or x>xd+1 then
            for tx=6,9 do if tex(at(x,py),tx,6)~=0x424a6b then ok=false end end
          end
        end
      end
      local hv,hl
      if ok then hv,hl=tex(at(xd,cy),8,0) end
      if ok and hv==0x7b7b84 then
        local _,bl=tex(at(x0+1,cy-1),8,11)
        local G={xd=xd,T=T,tOwn=tOwn,hid={at(xd,cy),hl,8,0},bandL=bl,donor={}}
        comp.gymFlat=G
        for x=x0,x1 do
          local c,g=at(x,py),at(x,py+1)
          if g and g.walkable and not g.isWater and not g.isGrass and not g.isDoor and not g.isSign and not g.hasOver
              and not g.ledgeDir and not compOf(g) then
            G.donor[x]=g.mid
            if c and not isCompCell(c,comp) and not c.hasOver then c.groundMid=g.mid end
          end
        end
      end
    end
  end
  grid.gymRule()

  -- ---------------------------------------------------------------
  -- Pass 2c: prop shapes (W3 rule): tree art -> tree; otherwise fence
  -- unless real 2D bulk among non-tree props; isolated -> legacy blob.
  -- ---------------------------------------------------------------
  Y()
  local function isPropNeighbor(nc)
    if not (nc and nc.blocksForBlob) then return false end
    local ncomp = components[nc.compId]
    return not (ncomp and (ncomp.kind == "building" or ncomp.kind == "block"))
  end
  local function runAt(x, y)
    local nc = at(x, y)
    return isPropNeighbor(nc) and not nc.isTreeArt
  end
  -- Exact native silver fence art owns rails even beside a cliff component.
  -- Match the complete UNDER/OVER artwork before overriding generic blob/run guesses.
  do
    if type(atlas.texels)=="function" then
      local u,o=atlas.texels(231,"under"),atlas.texels(231,"over")
      local palette={a=5921395,b=7589541,c=8092548,d=9232061,e=9741749,f=11386318,g=13557487,h=16250879}
      local signature="bbbbbbbbbbbbbbbbbbbbbbbbbbdbbbbbbbccccbdbbccccbbbcfhhfcbdcfhhfcbbchhhhcbbchhhhcbbcgeegcbbcgeegcbcaeeeeaccaeeeeachaeeeeahhaeeeeahcaeeeeaccaeeeeacaaeeeeaaaaeeeeaabaeeeeabbaeeeeabbaeeeeabbaeeeeabbaaaaaabbaaaaaabbcccccccbcccccccbbbcccccbbbcccccbbbbbcccbbbbbccc"
      local valid=u~=nil
      for pixel=1,256 do
        if not valid or u[pixel]~=palette[signature:sub(pixel,pixel)] or o and o[pixel]~=nil and o[pixel]~=-1 then valid=false;break end
      end
      if valid then
        for y=0,H-1 do for x=0,W-1 do
          local c=at(x,y);local comp=c and compOf(c)
          if c and c.mid==231 and not c.hasOver and not c.walkable and not c.isTreeArt
              and c.blocksForBlob and comp and comp.kind=="prop" then c.nativeCeladonFence=true end
        end end
      end
    end
  end

  -- Exact Route24 north bridge caps. Mixed native grass/rail art is not foliage.
  -- This changes only the two source producers at existing ground/rail heights.
  grid.nativeNuggetCaps={}
  do
    local valid=not indoor and not cave and not input.isBorder
      and input.mapId=='FR_ROUTE_24' and input.pair=='general__rom_082d4af4'
      and W==24 and H==40 and atlas.w==256 and atlas.h==416
