                if n and n.walkable and n.beh~=0x2A and (not ringArt or n.elev==c.elev) and not owner[n]then owner[n]=r;queue[#queue+1]=n end
              end
            end
          end
        end end
        if ringArt then for _,r in ipairs(regions)do
          if #r.cells==156 and r.cells[1].elev==4 then
            local rim,edges,valid=nil,0,true
            for _,c in ipairs(r.cells)do
              if c.elev~=4 or c.hgt~=1 then valid=false end
              for _,d in ipairs(DIRS)do local n=at(c.x+d.dx,c.y+d.dy)
                if n and not n.walkable and not n.isWater then
                  edges=edges+1
                  if rim and math.abs(rim-n.hgt)>1e-6 then valid=false end
                  rim=rim or n.hgt
                end
              end
            end
            if valid and rim==1 and edges==86 then
              r.rimGround=rim;r.target=rim+C.CAVE_WALL_H
            end
          end
        end end
        for _,stair in ipairs(stairs)do local n,z=at(stair.x,stair.y-1),at(stair.x,stair.y+1);local r=n and owner[n]
          if r and z and z.isWater then r.target=z.hgt+.15+C.CAVE_WALL_H end
          -- Exact native inner island: the south landing is ground, not water.
          -- Its seven walk cells are isolated by the surrounding moss wall.
          if r and z and stair.x==24 and stair.y==13 and #r.cells==7 and
            n.mid==641 and z.mid==641 and n.hgt==.75 and z.hgt==.75 then
            r.target=z.hgt+C.CAVE_WALL_H
          end
        end
        for _,r in ipairs(regions)do if r.target then
          r.valid=true
          for _,c in ipairs(r.cells)do if c.hgt~=(r.rimGround or .75) then r.valid=false end end
          for _,stair in ipairs(stairs)do local n,z=at(stair.x,stair.y-1),at(stair.x,stair.y+1);local rn,rz=n and owner[n],z and owner[z]
            if rn==r then
              if rz==r or not z or (not z.isWater and not rz) then r.valid=false
              elseif r.rimGround then
                if not rz or z.hgt~=.75 or not ((stair.x==19 and stair.y==11) or (stair.x==14 and stair.y==18)) then r.valid=false end
              elseif rz and math.abs(r.target-z.hgt-C.CAVE_WALL_H)>1e-6 then r.valid=false end
            elseif rz==r then r.valid=false end
          end
        end end
        for _,r in ipairs(regions)do if r.valid then
          grid.cavePlatforms=true
          for _,c in ipairs(r.cells)do c.hgt=r.target;c.cavePlatformSupport=true;c.caveRingSupport=r.rimGround~=nil end
        end end
        local ramps={}
        for _,stair in ipairs(stairs)do local n,z=at(stair.x,stair.y-1),at(stair.x,stair.y+1);local r=n and owner[n]
          if r and r.valid then local ramp={x=stair.x,z=stair.y,north=r.target,south=z.hgt};ramps[#ramps+1]=ramp
            stair.hgt=(ramp.north+ramp.south)*.5;stair.rampH={ramp.north,ramp.north,ramp.south,ramp.south};stair.cavePlatformSupport=true
          end
        end
        if #ramps>0 then grid.caveRamps=ramps;grid.caveIsland=ramps[1] end
        -- Native shoreline cells have water UNDER and land OVER. Keep the
        -- exact pixel ownership, including the tiny walkable corner cutouts.
        local ringOwner=owner[at(25,4)]
        if ringArt and ringOwner and ringOwner.valid and ringOwner.rimGround then
          for yy=0,H-1 do for xx=0,W-1 do local c=at(xx,yy)
            if c.mid==755 or c.mid==757 or c.mid==766 or c.mid==767 then
              local touches=owner[c]==ringOwner;local water,valid=nil,true
              for _,d in ipairs(DIRS)do local n=at(xx+d.dx,yy+d.dy)
                if n and owner[n]==ringOwner then touches=true end
                if n and n.isWater then
                  if water and water~=n.hgt then valid=false end
                  water=n.hgt
                end
              end
              local pixels=atlas.texels(c.mid,"over")
              if touches and valid and water==.6 and pixels then
                local mask={};for i=1,256 do mask[i]=pixels[i] and pixels[i]>=0 and "1" or "0" end
                local desc={x=xx,z=yy,north=ringOwner.target,south=water,shore16=table.concat(mask)}
                c.caveShore=desc
                if c.walkable then grid.caveRamps[#grid.caveRamps+1]=desc end
              end
            end
          end end
        end
        -- Native loose boulders standing wholly within a solved platform.
        for yy=0,H-1 do for xx=0,W-1 do local c=at(xx,yy);local sh=MB.TILE_SHAPES and MB.TILE_SHAPES[input.pair] and MB.TILE_SHAPES[input.pair][c.mid]
          if sh and sh.boulder and sh.sw then local target,valid=nil,true
            for _,d in ipairs(DIRS)do local n=at(xx+d.dx,yy+d.dy)
              if n and n.walkable then if not n.cavePlatformSupport then valid=false else target=n.hgt end end
            end
            if valid and target then c.hgt=target;c.cavePlatformSupport=true;c.caveRingProp=ringArt and target==2.25 and xx==30 and yy==9 end
          end
          if c.caveCleanMid==641 then local below=at(xx,yy+1);local right=at(xx+1,yy)
            if below and below.cavePlatformSupport and right and right.mid==694 then right.cavePlateauRock=true;right.caveCleanMid=641 end
          end
        end end
      end
    end
  end

  -- ---------------------------------------------------------------
  -- Pass 2e (r8 interiors; r12 review M4 / M14): a role per present cell.
  --   plant     : a solid cell under a walkable over-art cell (the pot below
  --               its leaves), nothing solid south, not walled in on both W
  --               and E by non-pot solids -> keyed cards
  --   statue    : a sign cell under a walkable over-art cell (gym statues:
  --               MB 0x84 under the figure's over art) -> plinth + upright
  --               over-art card, never a sign board
  --   wall      : solid, non-furniture cells in COLUMN RUNS (the solid cells
  --               of one column between non-solid ones) that touch the
  --               room's outer ring (solid cells 4-connected to void /
  --               off-map) or are >= 3 long in a component drawn mostly with
  --               the ring's own mids. Walkable pockets walled in on every
  --               side (Pewter Gym's window row) and doors / signs set in
  --               wall row 2 (a wall cell above, one beside) join the runs.
  --               A run's bottom 2 rows are its south face (INDOOR_WALL_H),
  --               the rows behind are its cap (their art on top at the wall
  --               height). A wall cell with void / off-map to its W or E is a
  --               side wall: its own art on the inward face, a dark cap.
  --   flat      : exit frames (a solid cell with void to the south and the
  --               exit mat -- a door -- above it), invisible walls (MB.
  --               TILE_SHAPES inv: drawn exactly like a floor tile) and stair
  --               art (a solid cell next
  --               to a stair warp below the back wall's face rows, or a
  --               furniture group touching one) -> floor decals
  --   boulder   : a solid cell whose mid is a boulder in MB.TILE_SHAPES[pair]
  --               with <= CAVE_BOULDER_MAX_ROCK solid non-boulder neighbours
  --               -> floor + a low rock
  --   furniture : everything else; 4-connected groups -> one box each,
  --               FURNITURE_H[behaviour] / MB.INDOOR_PROPS[pair][mid].h tall
  --               (FURNITURE_H_DEFAULT).
  -- A one-row furniture group standing against the wall borrows the
  -- walkable tile in front of it (FRLG draws the furniture front there) for
  -- its front face; that tile is then drawn with the room's floor tile.
  -- ---------------------------------------------------------------
  Y()
  local floorMid
  local indoorStats = { walls = 0, furniture = 0, plants = 0, flat = 0, sills = 0, sideWalls = 0,
    synthWalls = 0, southWalls = 0, doorGaps = 0, inWall = 0, pockets = 0, statues = 0, boulders = 0,
    diagonals = 0, slots = 0, bins = 0 }
  local furnitureGroups = {}
  -- r12: interior context shared with pass 3i (one table: M.build is near
  -- LuaJIT's local-variable limit)
  local IN = {
    shapes = (type(MB.TILE_SHAPES) == "table" and input.pair ~= nil) and MB.TILE_SHAPES[input.pair] or nil,
    props = (type(MB.INDOOR_PROPS) == "table" and input.pair ~= nil) and MB.INDOOR_PROPS[input.pair] or nil,
    southWalls = {}, -- r12 (R6): the synthetic south walls (geom.southWalls)
    caveStats = { boulders = 0, chamfers = 0, quarterCells = 0, faceBottoms = 0 }, -- r12 (M5)
  }
  -- W7: the flora context rides on IN too (M.build is at the local limit)
  IN.flora = floraContext(deps, { C = C, MB = MB, atlas = atlas, underRect = underRect, newV = newV,
    opaque = opaque, keyed = cutoutKeyed, isBorder = isBorder, pair = input.pair, forest3 = forest3,
    at = at, W = W, H = H, isForestCell = isForestCell, borderDist = borderDist }) -- W7 F12: tree rows
  IN.nativeFoliage = not MB.EMERALD and not indoor and not cave and nativeFoliageContext(deps,{
    C=C,MB=MB,atlas=atlas,underRect=underRect,overRect=overRect,newV=newV,
    opaque=opaque,keyed=cutoutKeyed,cutoutKeyed=cutoutKeyed,over=cutoutOver,cutoutOver=cutoutOver,
    isBorder=isBorder,pair=input.pair,forest3=forest3,at=at,W=W,H=H,
    isForestCell=isForestCell,borderDist=borderDist}) or nil
  IN.voxelTrees = IN.nativeFoliage and M.voxelTreeContext(deps,input) or nil
  -- Complete the two exact mixed UNDER tree units, using all original
  -- source layers. Cliff UNDER and building OVER retain independent owners.
  if IN.nativeFoliage then
    for _,comp in ipairs(compList)do if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeMixedTreeRoof then
      local removed={}
      for x=7,10 do local c=at(x,7);removed[c.unit]=true end
      local kept={};for _,u in ipairs(units)do if not removed[u]then kept[#kept+1]=u end end;units=kept;singleCount=singleCount-4
      for _,x in ipairs({7,9})do
        local u={x=x,y=7,w=2,h=2,cells={at(x,7),at(x+1,7),at(x,8),at(x+1,8)},nativeMixedSource=true}
        local desc={w=32,h=48,foot=48,shadow=48,crownEnd=48,neckEnd=48,height=3,scale=1/16,sources={}}
        for row=0,2 do for col=0,1 do
          local c=at(x+col,6+row);local layer=row==0 and 'over'or'under'
          local a,b,d,e=(row==0 and atlas.overRect or atlas.underRect)(c.mid)
          desc.sources[#desc.sources+1]={mid=c.mid,layer=layer,t=atlas.texels(c.mid,layer),r={a,b,d,e},x=col*16,y=row*16}
        end end
        for col=0,1 do at(x+col,6).suppressDecal=true;at(x+col,6).nativeMixedTipOwned=true;at(x+col,7).unit=u end
        IN.nativeFoliage.unitCache[u]=desc;units[#units+1]=u
      end
    end end
  end
  -- Native paired rows prove ownership: row0 vs row2 UNDER differs only
  -- in the foreground crown tips. Keep the common northern fragment clipped.
  -- The teal native forest background belongs at ground height, not on cards.
  if IN.nativeFoliage and grid.nativeSafariWest then
    local bg=0x3aad9c
    local donor=at(10,0);local tex=atlas.texels(donor.mid,'under');local r={atlas.underRect(donor.mid)}
    local index;for i=1,256 do if tex[i]==bg then index=i;break end end
    assert(index,'guarded native forest background missing')
    local tx,ty=(index-1)%16+.5,math.floor((index-1)/16)+.5
    local gu,gv=r[1]+tx/16*(r[3]-r[1]),r[2]+ty/16*(r[4]-r[2])
    local groundRect={gu,gv,gu,gv}
    for _,x in ipairs{10,13}do
      local front={x=x,y=1,w=3,h=2,cells={},nativeMixedSource=true}
      local rear={x=x,y=0,w=3,h=1,cells={},nativeMixedSource=true}
      local fd={w=48,h=32,foot=32,shadow=32,crownEnd=32,neckEnd=32,height=37/16,scale=1/16,az=1.5,sources={},baseCells={}}
      local rd={w=48,h=16,foot=16,shadow=16,crownEnd=16,neckEnd=16,height=1,scale=1/16,az=.25,sources={}}
      for row=0,2 do for col=0,2 do
        local c=at(x+col,row);front.cells[#front.cells+1]=c;c.nativeSafariWestForest=true
        fd.baseCells[#fd.baseCells+1]={cell=c,rect=groundRect}
        local t=atlas.texels(c.mid,'under');local a,b,d,e=atlas.underRect(c.mid)
        local source={mid=c.mid,layer='under',t=t,r={a,b,d,e},x=col*16,y=(row-1)*16,mask={}}
        if row==0 then
          rear.cells[#rear.cells+1]=c
          local paired=atlas.texels(at(x+col,2).mid,'under')
          local old={mid=c.mid,layer='under',t=t,r={a,b,d,e},x=col*16,y=0,mask={}}
          for i=1,256 do source.mask[i]=(t[i]~=paired[i]and t[i]~=bg)and 1 or -1;old.mask[i]=(t[i]==paired[i]and t[i]~=bg)and 1 or -1 end
          rd.sources[#rd.sources+1]=old
        else for i=1,256 do source.mask[i]=t[i]~=bg and 1 or -1 end end
        fd.sources[#fd.sources+1]=source
      end end
      IN.nativeFoliage.unitCache[front]=fd;units[#units+1]=front
      IN.nativeFoliage.unitCache[rear]=rd;units[#units+1]=rear
    end
  end
  if IN.nativeFoliage and nativeSafariNorthForest(input,atlas)then (function()
    -- Keep original cell.unit and solver roles: only exact native source producers change.
    for y=0,4 do for x=39,47 do local c=at(x,y)
      if not c or c.unit or c.isTreeArt or c.propShape~="tree" or c.hasOver or c.hgt~=.75 then return end
    end end
    local bg=0x3aad9c;local donor=at(39,4)
    local tex=atlas.texels(donor.mid,"under");local r={atlas.underRect(donor.mid)}
    local index;for i=1,256 do if tex[i]==bg then index=i;break end end
    if not index then return end
    local gu=r[1]+((index-1)%16+.5)/16*(r[3]-r[1])
    local gv=r[2]+(math.floor((index-1)/16)+.5)/16*(r[4]-r[2])
    local groundRect={gu,gv,gu,gv}
    grid.nativeSafariNorthForest=true
    for _,x in ipairs{39,42,45}do
      local front={x=x,y=1,w=3,h=4,cells={},nativeNorthSource=true,nativeNorthShadow=true}
      local rear={x=x,y=0,w=3,h=2,cells={},nativeNorthSource=true}
      local fd={w=48,h=64,foot=54,shadow=54,crownEnd=54,neckEnd=54,height=43/16,scale=1/16,az=4+6/16,sources={},baseCells={}}
      local rd={w=48,h=32,foot=32,shadow=32,crownEnd=32,neckEnd=32,height=2,scale=1/16,az=.5,sources={}}
      for row=0,4 do for col=0,2 do
        local c=at(x+col,row);front.cells[#front.cells+1]=c;c.nativeSafariNorthForest=true
        fd.baseCells[#fd.baseCells+1]={cell=c,rect=groundRect}
        local t=atlas.texels(c.mid,"under");local rect={atlas.underRect(c.mid)}
        local source={mid=c.mid,layer="under",t=t,r=rect,x=col*16,y=(row-1)*16,mask={}}
        if row<=1 then
          rear.cells[#rear.cells+1]=c
          local back={mid=c.mid,layer="under",t=t,r=rect,x=col*16,y=row*16,mask={}}
          local paired=row==1 and atlas.texels(at(x+col,3).mid,"under")or nil
          for i=1,256 do
            local tip=paired and t[i]~=paired[i]
            source.mask[i]=tip and t[i]~=bg and 1 or -1
            back.mask[i]=not tip and t[i]~=bg and 1 or -1
          end
          rd.sources[#rd.sources+1]=back
        else
          for i=1,256 do source.mask[i]=t[i]~=bg and 1 or -1 end
        end
        if row>=1 then fd.sources[#fd.sources+1]=source end
      end end
      IN.nativeFoliage.unitCache[front]=fd;units[#units+1]=front
      IN.nativeFoliage.unitCache[rear]=rd;units[#units+1]=rear
    end
  end)() end
  grid.frNativeUnit=function(c)
    return IN.nativeFoliage and c and c.unit and IN.nativeFoliage:canUnit(c.unit)
  end
  if grid.nativeElevationProfile=='bond-west-native-forest-terrace' and IN.nativeFoliage then (function()
    -- MID180/181 UNDER is the native brown cliff, but its 87 OVER pixels
    -- are exactly the complete southern C88 tree's reconstructed tip.
    local accepted={}
    for x=7,14 do
      local c,below=at(x,11),at(x,12);local u=below and below.unit
      if not c or not c.nativeElevationRim or not u or u.w~=2 or(u.h or u.w)~=2 or u.y~=12 or x<u.x or x>=u.x+2
        or not IN.nativeFoliage:canUnit(u)then return end
      local d=IN.nativeFoliage.unitCache[u];local tip=d and d.sources[x-u.x+1]
      local t=atlas.texels(c.mid,'over')
      if not t or not tip or tip.layer~='over' then return end
      for i=1,256 do if t[i]~=tip.t[i]then return end end
      accepted[#accepted+1]=c
    end
    for _,c in ipairs(accepted)do c.nativeMixedTipOwned=true end
  end)()end

  -- interiors-team (build/core/API.md): the interiors context rides on IN
  IN.interiors = indoor and interiorsContext(deps, { C = C, MB = MB, atlas = atlas, underRect = underRect,
    overRect = overRect, subRect = subRect, newV = newV, wallQuad = wallQuad, faceQuad = faceQuad, hQuad = hQuad,
    at = at, grid = grid, W = W, H = H, IN = IN, mapId = input.mapId, pair = input.pair, opaque = opaque,
    under = cutoutUnder, over = cutoutOver, keyed = cutoutKeyed, stats = indoorStats, groups = furnitureGroups,
    require = deps.require, Y = Y, isBorder = isBorder, midHasOver = midHasOver, voidMid = voidMid }) or nil
  if indoor then
    local fv = {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.walkable then fv[c.mid] = (fv[c.mid] or 0) + 1 end
      end
    end
    for mid, n in pairs(fv) do
      if floorMid == nil or n > fv[floorMid] or (n == fv[floorMid] and mid < floorMid) then floorMid = mid end
    end
    -- r12 (pre-lab-7 tour: black strips on Silph's floors): a walkable
    -- cell whose OVER art is mostly the void colour (>= 32 texels and >= 40%
    -- of its opaque over texels -- FRLG's 2D wall top overlapping the floor
    -- row in front of it, e.g. Silph's 817 / 818) draws no over decal: in 3D
    -- that wall stands in its own cell
    if voidMid and type(atlas.texels) == "function" then
      local vu = atlas.texels(voidMid, "under")
      local voidC = vu and vu[1]
      local vd = {}
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if voidC and c and c.walkable and c.hasOver then
            local e = vd[c.mid]
            if e == nil then
              e = false
              local o = atlas.texels(c.mid, "over")
              if o then
                local op, nv = 0, 0
                for i = 1, 256 do
                  if o[i] and o[i] >= 0 then
                    op = op + 1
                    if o[i] == voidC then nv = nv + 1 end
                  end
                end
                e = nv >= 32 and nv >= 0.4 * op
              end
              vd[c.mid] = e
            end
            if e then
              c.suppressDecal = true
              indoorStats.voidDecals = (indoorStats.voidDecals or 0) + 1
            end
          end
          -- (its under art void there too -- Silph's 825 under a partition's
          -- top: the ground is the room's floor tile)
          if voidC and c and c.walkable and floorMid and not c.groundMid then
            local k = "u" .. c.mid
            local e = vd[k]
            if e == nil then
              local u = atlas.texels(c.mid, "under")
              local nv = 0
              if u then for i = 1, 256 do if u[i] == voidC then nv = nv + 1 end end end
              e = nv >= 32
              vd[k] = e
            end
            if e then c.groundMid = floorMid end
          end
        end
      end
    end
    -- r12 (refs 10: "the recessed pool with stilts"): a walkable cell beside
    -- the pool whose art is not the deck's (its most common colour at least
    -- 60 away from the floor tile's, summed over RGB -- Cerulean's cream
    -- walkways on the blue-grey deck) is a PLANK: a board PLANK_T thick on
    -- stilts, the water running under it (pass 3). cell.poolH = the water's
    -- height beside it.
    do
      local tex = type(atlas.texels) == "function" and atlas.texels or nil
      local domC = {}
      local function dom(mid)
        local d = domC[mid]
        if d ~= nil then return d end
        d = false
        local u = tex and tex(mid, "under")
        if u then
          local o = midHasOver(mid) and tex(mid, "over") or nil
          local cnt, best, bn = {}, nil, 0
          for i = 1, 256 do
            local v = (o and o[i] and o[i] >= 0) and o[i] or u[i]
            cnt[v] = (cnt[v] or 0) + 1
            if cnt[v] > bn then best, bn = v, cnt[v] end
          end
          d = best
        end
        domC[mid] = d
        return d
      end
      local function far(a, b)
        if not (a and b) then return false end
        local dr = math.abs(math.floor(a / 65536) - math.floor(b / 65536))
        local dg = math.abs(math.floor(a / 256) % 256 - math.floor(b / 256) % 256)
        return dr + dg + math.abs(a % 256 - b % 256) >= 60
      end
      local fd = floorMid and dom(floorMid)
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if c and c.walkable and not c.isWater then
            local wh
            for _, d in ipairs(DIRS) do
              local n = at(x + d.dx, y + d.dy)
              if n and n.isWater and n.hgt and (not wh or n.hgt < wh) then wh = n.hgt; c.poolMid = n.mid end
            end
            if wh and fd and far(dom(c.mid), fd) then
              c.plank, c.poolH = true, wh
              indoorStats.planks = (indoorStats.planks or 0) + 1
            end
          end
        end
      end
    end
    local function solid(c) return c and compOf(c) ~= nil end
    local function propOf(c) return IN.props and IN.props[c.mid] or nil end
    local function furnH(c)
      local h = c.beh and MB.FURNITURE_H[c.beh]
      if h then return h end
      local p = propOf(c)
      return p and p.h or nil
    end
    local function isWb(c) return c and c.wb == true end
    -- 1. plants (before anything can claim the pot as a wall cell): a
    -- candidate walled in W and E by solids that are not candidates too
    -- (a row of pots is fine) is not a plant
    -- (r12 pre-lab-7 tour: the leaves must be LEAVES -- >= 15% of the over
    -- art green-dominant (g > r + 20, g > b + 10); Silph's white tables under
    -- their over-art tops were drawn as crossed plant cards. No texels: as
    -- before)
    local leafyC = {}
    local function leafyOver(mid)
      local e = leafyC[mid]
      if e ~= nil then return e end
      e = true
      local o = type(atlas.texels) == "function" and atlas.texels(mid, "over") or nil
      if o then
        local g = 0
        for i = 1, 256 do
          local v = o[i]
          if v and v >= 0 then
            local r, gg, b = math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256
            if gg > r + 20 and gg > b + 10 then g = g + 1 end
          end
        end
        e = g >= 0.15 * 256
      end
      leafyC[mid] = e
      return e
    end
    local function plantCand(c)
      if not (solid(c) and not furnH(c)) then return false end
      local n = at(c.x, c.y - 1)
      return n and n.walkable and n.hasOver and not solid(at(c.x, c.y + 1)) and leafyOver(n.mid) or false
    end
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and plantCand(c) then
          local w, e = at(x - 1, y), at(x + 1, y)
          if not (solid(w) and not plantCand(w) and solid(e) and not plantCand(e)) then
            c.role = "plant"
            c.plantTop = at(x, y - 1)
            c.plantTop.suppressDecal = true
          end
        end
      end
    end
    -- 2. statues: a sign under a walkable over-art cell (not in a wall)
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.isSign and not solid(c) then
          local n = at(x, y - 1)
          if n and n.walkable and n.hasOver then
            c.role, c.statueFig, c.signKind = "statue", n, nil
            c.groundMid = c.nearMid or floorMid
            n.suppressDecal = true
            indoorStats.statues = indoorStats.statues + 1
          end
        end
      end
    end
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        -- a solid tile drawn exactly like a walkable one (MB.TILE_SHAPES inv:
        -- Fuchsia Gym's invisible walls) stays floor
        local sh = c and IN.shapes and IN.shapes[c.mid]
        if sh and sh.inv and solid(c) and not c.role then c.role, c.invisible = "flat", true end
        if c then c.wb = solid(c) and not c.role and not furnH(c) end
      end
    end
    -- 3. exit frames: solid, void beyond it to the south (west / east),
    -- the exit mat (a door) on the room side of it or diagonally so (a gate
    -- house's side exits too)
    local function isMat(n) return n and n.isDoor and not solid(n) and not (n.beh and MB.STAIR_WARP[n.beh]) end
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if solid(c) and not c.role then
          local door = false
          for k = -1, 1 do
            if not at(x, y + 1) and isMat(at(x + k, y - 1)) then door = true end
            if not at(x - 1, y) and isMat(at(x + 1, y + k)) then door = true end
            if not at(x + 1, y) and isMat(at(x - 1, y + k)) then door = true end
          end
          if door then c.role, c.exitFrame, c.wb = "flat", true, false end
        end
      end
    end
    -- 3b. r12 (ref 09: "beams"): GATES -- solid cells whose art is the floor
    -- (>= 45% of its texels in the floor tile's colours) crossed by full-
    -- width BANDS (2-7 rows with >= 14 of 16 texels off the floor palette:
    -- Vermilion's electric barrier), in a W-E run of >= 2 such cells. No
    -- wall: the floor, with each band a glowing bar (pass 3i).
    -- c.gateBands = { { row0, row1 }, ... } (texel rows of this cell)
    if floorMid and type(atlas.texels) == "function" then
      local fu = atlas.texels(floorMid, "under")
      local fpal = {}
      if fu then for i = 1, 256 do fpal[fu[i]] = true end end
      local function scanBands(c)
        local u = atlas.texels(c.mid, "under")
        if not u then return nil end
        local o = c.hasOver and atlas.texels(c.mid, "over") or nil
        local nf, rows = 0, {}
        for row = 0, 15 do
          local off = 0
          for col = 1, 16 do
            local i = row * 16 + col
            local v = (o and o[i] and o[i] >= 0) and o[i] or u[i]
            if fpal[v] then nf = nf + 1 else off = off + 1 end
          end
          rows[row] = off >= 14
        end
        if nf < 0.45 * 256 then return nil end
        local bands, r = {}, 0
        while r <= 15 do
          if rows[r] then
            local r1 = r
            while r1 + 1 <= 15 and rows[r1 + 1] do r1 = r1 + 1 end
            if r1 - r + 1 >= 2 and r1 - r + 1 <= 7 then bands[#bands + 1] = { r, r1 } end
            r = r1 + 1
          else r = r + 1 end
        end
        return #bands > 0 and bands or nil
      end
      -- Art and the floor palette are fixed during this classification pass.
      -- Keep results local to the build, including misses; a later tile swap
      -- or map build always rescans. Separate over-art states for the same mid.
      local plainBands, overBands = {}, {}
      local function bandsOf(c)
        if c.mid == nil then return scanBands(c) end
        local cache = c.hasOver and overBands or plainBands
        local bands = cache[c.mid]
        if bands == nil then bands = scanBands(c) or false; cache[c.mid] = bands end
        if not bands then return nil end
        -- Preserve each cell's independent band tables, even though current
        -- consumers only read them when constructing gate geometry.
        local out = {}
        for i = 1, #bands do out[i] = { bands[i][1], bands[i][2] } end
        return out
      end
      local cand = {}
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if solid(c) and not c.role then cand[c] = bandsOf(c) end
        end
      end
      for c, b in pairs(cand) do
        local wn, en = at(c.x - 1, c.y), at(c.x + 1, c.y)
        if (wn and cand[wn]) or (en and cand[en]) then
          c.role, c.wb, c.gateBands, c.groundMid = "gate", false, b, floorMid
          indoorStats.gates = (indoorStats.gates or 0) + 1
        end
      end
    end
    -- boulders: MB.TILE_SHAPES boulders with at most CAVE_BOULDER_MAX_ROCK
    -- solid non-boulder neighbours (before the runs can take them)
    local function isBoulderMid(c) local sh = c and IN.shapes and IN.shapes[c.mid]; return sh and sh.boulder and sh.sw end
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        local sh = c and IN.shapes and IN.shapes[c.mid]
        local nr = 0
        for _, d in ipairs(DIRS) do
          local nb = at(x + d.dx, y + d.dy)
          if solid(nb) and not isBoulderMid(nb) then nr = nr + 1 end
        end
        if sh and sh.boulder and sh.sw and c.wb and nr <= C.CAVE_BOULDER_MAX_ROCK then
          c.role, c.boulder, c.wb = "boulder", sh, false
          c.groundMid = c.nearMid or floorMid
          c.suppressDecal = true
          indoorStats.boulders = indoorStats.boulders + 1
        end
      end
    end
    -- 4. walkable pockets walled in on every side (no door / sign / warp)
    do
      local seen = {}
      local function pocketable(c) return c and c.walkable and not c.isDoor and not c.isSign and not c.role end
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if pocketable(c) and not seen[c] then
            local comp, stack, ok = {}, { c }, true
            seen[c] = true
            while #stack > 0 do
              local p = stack[#stack]
              stack[#stack] = nil
              comp[#comp + 1] = p
              for _, d in ipairs(DIRS) do
                local nb = at(p.x + d.dx, p.y + d.dy)
                if nb then
                  if pocketable(nb) then
                    if not seen[nb] then
                      seen[nb] = true
                      stack[#stack + 1] = nb
                    end
                  elseif not nb.wb then
                    ok = false
                  end
                end
              end
            end
            if ok and #comp <= C.INDOOR_POCKET_MAX then
              for _, p in ipairs(comp) do
                p.wb, p.pocket = true, true
                indoorStats.pockets = indoorStats.pockets + 1
              end
            end
          end
        end
      end
    end
    -- 5. doors / signs set in wall row 2: a wall cell above, one beside
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and (c.isDoor or c.isSign) and not c.role and not solid(c) and isWb(at(x, y - 1))
            and not (c.beh and MB.STAIR_WARP[c.beh])
            and (isWb(at(x - 1, y)) or isWb(at(x + 1, y))) then
          c.wb, c.inWall, c.signKind = true, c.isDoor and "door" or "sign", nil
          indoorStats.inWall = indoorStats.inWall + 1
        end
      end
    end
    -- 6. stair art: next to a stair warp (8-neighbourhood), below the back
    -- wall's face rows (a cell whose north, or north-north, is void stays)
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.wb and not c.inWall and not c.pocket then
          local near = false
          for dy = -1, 1 do
            for dx = -1, 1 do
              local nb = at(x + dx, y + dy)
              if nb and nb.beh and MB.STAIR_WARP[nb.beh] then near = true end
            end
          end
          if near then
            local n1 = at(x, y - 1)
            local backRow = (not n1) or (n1.wb and not at(x, y - 2))
            if not backRow then c.role, c.stair, c.wb = "flat", true, false end
          end
        end
      end
    end
    -- 7. the outer ring: wall-able cells 4-connected to void / off-map
    local ringMids = {}
    do
      local stack = {}
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if c and c.wb then
            for _, d in ipairs(DIRS) do
              if not at(x + d.dx, y + d.dy) and not c.ring then
                c.ring = true
                stack[#stack + 1] = c
              end
            end
          end
        end
      end
      while #stack > 0 do
        local p = stack[#stack]
        stack[#stack] = nil
        ringMids[p.mid] = true
        for _, d in ipairs(DIRS) do
          local nb = at(p.x + d.dx, p.y + d.dy)
          if nb and nb.wb and not nb.ring then
            nb.ring = true
            stack[#stack + 1] = nb
          end
        end
      end
    end
    -- 8. column runs -> walls. A run is a wall when a cell of it touches
    -- void / off-map, or it is ring-connected and >= 2 long (a one-row
    -- counter leaning on a side wall is furniture), or it is free-standing,
    -- >= 3 long, in a component where >= INDOOR_FREE_WALL_SHARE of the
    -- cells use ring mids.
    local compShare = {}
    local function freeShare(c)
      if compShare[c] then return compShare[c] end
      local comp, stack, n, hit = {}, { c }, 0, 0
      local seen = { [c] = true }
      while #stack > 0 do
        local p = stack[#stack]
        stack[#stack] = nil
        comp[#comp + 1] = p
        n = n + 1
        if ringMids[p.mid] then hit = hit + 1 end
        for _, d in ipairs(DIRS) do
          local nb = at(p.x + d.dx, p.y + d.dy)
          if nb and nb.wb and not nb.ring and not seen[nb] then
            seen[nb] = true
            stack[#stack + 1] = nb
          end
        end
      end
      local s = hit / math.max(1, n)
      for _, p in ipairs(comp) do compShare[p] = s end
      return s
    end
    for x = 0, W - 1 do
      local y = 0
      while y < H do
        local c = grid[y][x]
        if c and c.wb then
          local a, b = y, y
          while b + 1 < H and isWb(grid[b + 1][x]) do b = b + 1 end
          local isWall, ring = false, false
          for yy = a, b do
            local p = grid[yy][x]
            if p.ring then ring = true end
            for _, d in ipairs(DIRS) do
              if not at(x + d.dx, yy + d.dy) then isWall = true end
            end
          end
          if not isWall and ring and b - a + 1 >= 2 then isWall = true end
          if not isWall and not ring and b - a + 1 >= 3 and freeShare(c) >= C.INDOOR_FREE_WALL_SHARE then isWall = true end
          if isWall then
            for yy = a, b do
              local p = grid[yy][x]
              p.role, p.runA, p.runB = "wall", a, b
              if not at(x - 1, yy) or not at(x + 1, yy) then p.side = true end
            end
          else
            for yy = a, b do
              local p = grid[yy][x]
              if p.pocket or p.inWall then p.wb = false end -- not a wall after all: back to floor / door
              if p.inWall then p.inWall = nil end
            end
          end
          y = b + 1
        else
          y = y + 1
        end
      end
    end
    -- the room's plain back-wall art: the most common (upper, lower) face
    -- pair of back-wall runs (top on void) ending on the floor
    do
      local cnt, best, bestN = {}, nil, 0
      for x = 0, W - 1 do
        for y = 0, H - 1 do
          local c = grid[y][x]
          if c and c.role == "wall" and c.runB == y and not c.inWall and not at(x, c.runA - 1) then
            local s = at(x, y + 1)
            if s and s.walkable then
              local up = (y - 1 >= c.runA) and grid[y - 1][x] or c
              local k = up.mid * 65536 + c.mid
              cnt[k] = (cnt[k] or 0) + 1
              if cnt[k] > bestN or (cnt[k] == bestN and k < best) then best, bestN = k, cnt[k] end
            end
          end
        end
      end
      if best then IN.wallUpper, IN.wallLower = math.floor(best / 65536), best % 65536 end
    end
    -- 9. furniture groups
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if solid(c) and not c.role then
          local g = { cells = {}, minY = y, maxY = y, h = nil, stairs = false }
          local stack = { c }
          c.role = "furniture"
          while #stack > 0 do
            local p = stack[#stack]
            stack[#stack] = nil
            g.cells[#g.cells + 1] = p
            p.group = g
            if p.y < g.minY then g.minY = p.y end
            if p.y > g.maxY then g.maxY = p.y end
            local fh = furnH(p)
            if fh and (g.h == nil or fh > g.h) then g.h = fh end
            local pr = propOf(p)
            if pr and pr.kind == "slot" then g.slot = true end
            for _, d in ipairs(DIRS) do
              local nc = at(p.x + d.dx, p.y + d.dy)
              if nc and nc.beh and MB.STAIR_WARP[nc.beh] then g.stairs = true end
              if solid(nc) and not nc.role then
                nc.role = "furniture"
                stack[#stack + 1] = nc
              end
            end
          end
          g.h = g.h or C.FURNITURE_H_DEFAULT
          if g.stairs then
            for _, p in ipairs(g.cells) do p.role, p.group = "flat", nil end
          else
            furnitureGroups[#furnitureGroups + 1] = g
            if g.slot then indoorStats.slots = indoorStats.slots + 1 end
            -- column extents inside the group (M14: multi-row art split)
            local inG = {}
            for _, p in ipairs(g.cells) do inG[p] = true end
            for _, p in ipairs(g.cells) do
              local y0, y1 = p.y, p.y
              while inG[at(p.x, y0 - 1) or false] do y0 = y0 - 1 end
              while inG[at(p.x, y1 + 1) or false] do y1 = y1 + 1 end
              p.fy0, p.fy1 = y0, y1
            end
            -- r12 (refs 08-11: "pillars"): a group one cell wide, >= 2 rows,
            -- not touching a wall or other furniture W / E, whose top is
            -- drawn in the over art of the walkable cell above (the capital)
            -- is a PILLAR: a column on its bottom cell PILLAR_ROW_H a row
            -- tall (capital included, at most INDOOR_WALL_H), its rows' art
            -- stacked up its faces; the capital's flat decal is not drawn
            do
              local x0c = g.cells[1].x
              local one = g.maxY - g.minY + 1 >= 2
              for _, p in ipairs(g.cells) do
                if p.x ~= x0c then one = false break end
                for _, dx in ipairs({ -1, 1 }) do
                  local q = at(p.x + dx, p.y)
                  if q and solid(q) then one = false end
                end
              end
              local cap = at(x0c, g.minY - 1)
              if one and cap and cap.walkable and cap.hasOver and not g.slot then
                g.pillar = { x = x0c, cap = cap }
                cap.suppressDecal = true
                indoorStats.pillars = (indoorStats.pillars or 0) + 1
              end
            end
            -- one-row group against the wall: borrow the front tile
            if g.minY == g.maxY then
              for _, p in ipairs(g.cells) do
                local nb, sb = at(p.x, p.y - 1), at(p.x, p.y + 1)
                if nb and nb.role == "wall" and sb and sb.walkable and floorMid and sb.mid ~= floorMid then
                  p.frontMid = sb.mid
                  sb.groundMid = floorMid
                end
              end
            end
            -- slots: the over-art machine tops on the floor row north of
            -- the box are not drawn as floor decals
            if g.slot then
              for _, p in ipairs(g.cells) do
                local nb = at(p.x, p.y - 1)
                if nb and nb.walkable and nb.hasOver then nb.suppressDecal = true end
              end
            end
          end
        end
      end
    end
    -- Exact PC stair-mouth elevation tags must not extrude floor blocks.
    -- Correct the render grid before interior group/wall leveling; raw map
    -- collision/elevation and warp cells remain untouched.
    do
      local stairs=deps.Stairs or M.Stairs
      if not stairs and type(deps.require)=="function" then stairs=deps.require("mesh/FrlgStairs") end
      indoorStats.nativeLanding={}
      if stairs and stairs.landingPlan then
        for _,a in ipairs(stairs.find(input.pair,W,H,at))do
          local plan=stairs.landingPlan(a,at,input.mapId,C.ELEV_UNIT)
          if plan then
            local report={profile=plan.profile,from=plan.from,to=plan.to,cells={},groups={}}
            local seenGroups={}
            for _,cell in ipairs(plan.cells)do
              report.cells[#report.cells+1]={x=cell.x,y=cell.y,mid=cell.mid}
              -- One Island's adjoining counter may have inherited the same
              -- high base; inventory its original group for scoped audits.
              local group=plan.island and cell.group
              if group and not seenGroups[group]then
                seenGroups[group]=true
                for _,q in ipairs(group.cells or {})do report.groups[#report.groups+1]={x=q.x,y=q.y,mid=q.mid} end
              end
              cell.hgt=plan.to
            end
            indoorStats.nativeLanding[#indoorStats.nativeLanding+1]=report
          end
        end
      end
    end
    if IN.interiors then IN.interiors:classify(floorMid) end -- interiors-team
    -- Exact native stair footprints supersede the old flat-art fallback.
    -- Raw source collision/warp/elevation stay intact; the exact landing
    -- correction above also aligns renderer height queries with its floor.
    do
      local stairs = deps.Stairs or M.Stairs
      if not stairs and type(deps.require) == "function" then stairs = deps.require("mesh/FrlgStairs") end
      if stairs then
        IN.stairs, IN.stairModule = stairs.find(input.pair, W, H, at), stairs
        local function claim(ctx)
          local function set(c,k,v)
            if ctx then ctx:set(c,k,v) else c[k]=v end
          end
          for _, assembly in ipairs(IN.stairs) do
            -- The native house's projected upper stair row replaces the lower
            -- wallpaper row. Keep the retained wall on its neighbours' face
            -- plane, rather than letting the shortened run step behind them.
            if assembly.profile.name == "house_up" and input.pair == "player_house" then
              local valid = true
              for dx=0,assembly.profile.w-1 do
                local rear=at(assembly.x+dx,assembly.y-1)
                local beside=at(assembly.x-1,assembly.y)
                if not rear or rear.mid~=32 or rear.role~="wall"
                    or rear.runB~=assembly.y+dx or (dx==1 and not rear.side)
                    or not beside or beside.mid~=40 or beside.role~="wall" or beside.runB~=assembly.y then valid=false end
              end
              if valid then
                for dx=0,assembly.profile.w-1 do
                  set(at(assembly.x+dx,assembly.y-1),"nativeStairRearPlane",assembly.y+1)
                end
              end
            end
            for _, cell in ipairs(assembly.cells) do
              if ctx then
                if cell.role == "wall" then ctx:unwall(cell.x,cell.y,cell.y,{as="floor"}) end
                if cell.group then ctx:leaveGroup(cell) end
              end
              for _,key in ipairs({"runA","runB","group","side"}) do set(cell,key,nil) end
              set(cell,"wb",false)
              set(cell,"role","nativeStair")
              set(cell,"stairAssembly",assembly)
            end
          end
        end
        if IN.interiors then
          if not IN.interiors:step("native stairs",claim) then IN.stairs={} end
        else claim(nil) end
        -- Also keep the pure mesher fallback's wall runs valid without a shell.
        if not IN.interiors and #IN.stairs>0 then
          for x=0,W-1 do
            local y=0
            while y<H do
              local c=at(x,y)
              if c and c.role=="wall" then
                local last=y
                while at(x,last+1) and at(x,last+1).role=="wall" do last=last+1 end
                for yy=y,last do at(x,yy).runA,at(x,yy).runB=y,last end
                y=last+1
              else y=y+1 end
            end
          end
        end
      end
    end
    if deps.debugRoles then
      local roles = {}
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if c and c.role then
            local r = c.role
            if r == "wall" then
              r = (c.side and "S" or "W") .. (c.inWall and "d" or (c.pocket and "p" or ""))
                .. tostring(math.min(9, c.runB - y + 1))
            elseif r == "furniture" then r = c.group and c.group.slot and "Fs" or "F"
            elseif r == "flat" then r = c.exitFrame and "fx" or (c.stair and "fs" or "f")
            elseif r == "plant" then r = "p"
            elseif r == "statue" then r = "st"
            elseif r == "boulder" then r = "b"
            elseif r == "gate" then r = "g" end
            if c.group and c.group.pillar then r = "P" end
            if c.plank then r = "k" end
            roles[y * W + x + 1] = r
          end
        end
      end
      indoorStats.roles = roles
    end
  end

  local sw -- M4 leaf swatch (under atlas)
  local darkSw, barkSw, shadeSw -- r9 Part B: MB.DARK_SWATCH / BARK_SWATCH / SHADE_SWATCH
  do
    local function swatchOf(ls)
      local r = ls and underRect(ls.mid)
      if r then return subRect(r, ls.u0, ls.v0, ls.u1, ls.v1) end
      return nil
    end
    sw = swatchOf(MB.LEAF_SWATCH)
    darkSw = swatchOf(MB.DARK_SWATCH)
    barkSw = swatchOf(MB.BARK_SWATCH)
    shadeSw = swatchOf(MB.SHADE_SWATCH)
  end
  -- r10: the forest tileset's own swatches for its 3-wide trees
  local f3 = forest3 and {} or nil
  if forest3 then
    local function sof(ls)
      local r = ls and underRect(ls.mid)
      if r then return subRect(r, ls.u0, ls.v0, ls.u1, ls.v1) end
      return nil
    end
    f3.leaf, f3.dark, f3.bark, f3.shade = sof(forest3.leaf), sof(forest3.dark), sof(forest3.bark), sof(forest3.shade)
  end
  local function isForest3Mid(mid)
    return forest3 ~= nil and (forest3.upper[mid] or forest3.lower[mid] or (forest3.base and forest3.base[mid])) ~= nil
  end

  -- Crown: stacked tiers of rings. tiers = { { {rf, yf}, ... }, ... } with
  -- rf = radius fraction of R, yf = height fraction of `top`; bands join
  -- consecutive rings inside a tier; an apex fan closes the last ring at
  -- `top`, a downward fan closes the first ring. M4 UVs: every ring vertex
  -- i gets u = swatch left (i even) or right (i odd) -- sides is even, so
  -- every shared edge samples the same texel column; v runs bottom->top
  -- of the swatch per band; caps are planar x/z projections.
  -- r8 cost: same vertices as the r7m crown, built from plain numbers (ring
  -- points are {x,y,z,nx,ny,nz,u}; cos/sin once per side; no UV tables).
  local function crown(list, cx, gy, cz, R, top, sides, tiers, closeBottom, swatch, rot, seed)
    local ccy = gy + top * 0.5
    local su0, sv0, su1, sv1 = swatch[1], swatch[2], swatch[3], swatch[4]
    local wob, ca, sa = {}, {}, {}
    for i = 0, sides - 1 do
      wob[i] = 1 + (hash01(seed, i, 7) - 0.5) * 2 * C.TREE_WOBBLE
      local a = rot + (i / sides) * 2 * math.pi
      ca[i], sa[i] = math.cos(a), math.sin(a)
    end
    local function ring(rg)
      local pts = { r = R * rg[1], y = gy + top * rg[2] }
      for i = 0, sides - 1 do
        local r = R * rg[1] * wob[i]
        local px, py, pz = cx + r * ca[i], gy + top * rg[2], cz + r * sa[i]
        local dx, dy, dz = px - cx, py - ccy, pz - cz
        local l = math.sqrt(dx * dx + dy * dy + dz * dz)
        if l < 1e-8 then
          pts[i] = { px, py, pz, 0, 1, 0, (i % 2 == 0) and su0 or su1 }
        else
          pts[i] = { px, py, pz, dx / l, dy / l, dz / l, (i % 2 == 0) and su0 or su1 }
        end
      end
      return pts
    end
    -- planar cap UV, clamped: the rim wobble pushes vertices past rr.
    local function planar(px, pz, rr)
      local fu = math.max(0, math.min(1, (px - cx) / (2 * rr) + 0.5))
      local fv = math.max(0, math.min(1, (pz - cz) / (2 * rr) + 0.5))
      return su0 + fu * (su1 - su0), sv0 + fv * (sv1 - sv0)
    end
    local firstRing, lastRing
    for ti, tier in ipairs(tiers) do
      local prev
      for ri, rg in ipairs(tier) do
        local cur = ring(rg)
        if ti == 1 and ri == 1 then firstRing = cur end
        if prev then
          local lo, hi = {}, {}
          for i = 0, sides - 1 do
            local p, q = prev[i], cur[i]
            lo[i] = newV(p[1], p[2], p[3], p[7], sv1, p[4], p[5], p[6])
            hi[i] = newV(q[1], q[2], q[3], q[7], sv0, q[4], q[5], q[6])
          end
          local n = #list
          for i = 0, sides - 1 do
            local j = (i + 1) % sides
            list[n + 1], list[n + 2], list[n + 3] = lo[i], lo[j], hi[j]
            list[n + 4], list[n + 5], list[n + 6] = lo[i], hi[j], hi[i]
            n = n + 6
          end
        end
        prev = cur
      end
      lastRing = prev
    end
