    local ay = gy + top
    local ady = ay - ccy
    local anx, any, anz = 0, 1, 0
    if math.abs(ady) >= 1e-8 then any = ady / math.abs(ady) end
    local rr = lastRing.r
    local au, av = planar(cx, cz, rr)
    local rim = {}
    for i = 0, sides - 1 do
      local a = lastRing[i]
      local u1, v1 = planar(a[1], a[3], rr)
      rim[i] = newV(a[1], a[2], a[3], u1, v1, a[4], a[5], a[6])
    end
    local apex = newV(cx, ay, cz, au, av, anx, any, anz)
    local n = #list
    for i = 0, sides - 1 do
      list[n + 1], list[n + 2], list[n + 3] = rim[i], rim[(i + 1) % sides], apex
      n = n + 3
    end
    if closeBottom then
      local fr, by = firstRing.r, firstRing.y
      local bu, bv = planar(cx, cz, fr)
      local low = {}
      for i = 0, sides - 1 do
        local a = firstRing[i]
        local ua, va = planar(a[1], a[3], fr)
        low[i] = newV(a[1], a[2], a[3], ua, va, 0, -1, 0)
      end
      local ctr = newV(cx, by, cz, bu, bv, 0, -1, 0)
      n = #list
      for i = 0, sides - 1 do
        list[n + 1], list[n + 2], list[n + 3] = ctr, low[(i + 1) % sides], low[i]
        n = n + 3
      end
    end
  end

  -- r9 Part B: ellipsoid dome (tree crowns and their lobes). Centre
  -- (cx, yc, cz), horizontal radius a, vertical semi-axis b; rings at the
  -- latitudes lats[1..n] (radians, ascending, never +-90 deg); band k joins
  -- rings k and k+1 with swatch bandSw[k]; the top pole closes with a fan
  -- (planar topSw UVs), the bottom pole with a fan when botSw is given.
  -- Seam-safe UVs: ring vertex i takes the swatch's left (i even) or right
  -- (i odd) column, sides is even, so every shared edge samples one texel
  -- column; v runs bottom -> top of the swatch per band. Normals are the
  -- ellipsoid's own (smooth shading, the underside faces down -> darker);
  -- per-side rim wobble from `seed`. Returns the lowest ring's height.
  local function dome(list, cx, yc, cz, a, b, sides, lats, bandSw, topSw, botSw, rot, seed)
    local ca, sa, wob = {}, {}, {}
    for i = 0, sides - 1 do
      local ang = rot + (i / sides) * 2 * math.pi
      ca[i], sa[i] = math.cos(ang), math.sin(ang)
      wob[i] = 1 + (hash01(seed, i, 7) - 0.5) * 2 * C.TREE_WOBBLE
    end
    local ia2, ib2 = 1 / (a * a), 1 / (b * b)
    local rings = {}
    for k = 1, #lats do
      local cl, sl = math.cos(lats[k]), math.sin(lats[k])
      local py = yc + b * sl
      local pts = {}
      for i = 0, sides - 1 do
        local r = a * cl * wob[i]
