      end
    end
    -- pole fans: planar x/z UVs over the ring's own radius, clamped
    local function fan(ring, poleY, s, ny)
      local rr = 0
      for i = 0, sides - 1 do
        local dx, dz = ring[i][1] - cx, ring[i][3] - cz
