        local fv = math.max(0, math.min(1, (pz - cz) / (2 * rr) + 0.5))
        return s[1] + fu * (s[3] - s[1]), s[2] + fv * (s[4] - s[2])
      end
      local rim = {}
      for i = 0, sides - 1 do
        local p = ring[i]
        local u, v = pl(p[1], p[3])
        rim[i] = newV(p[1], p[2], p[3], u, v, p[4], p[5], p[6])
      end
      local pu, pv = pl(cx, cz)
      local pole = newV(cx, poleY, cz, pu, pv, 0, ny, 0)
      n = #list
      for i = 0, sides - 1 do
        local j = (i + 1) % sides
        if ny > 0 then
          list[n + 1], list[n + 2], list[n + 3] = rim[i], rim[j], pole
        else
          list[n + 1], list[n + 2], list[n + 3] = pole, rim[j], rim[i]
        end
        n = n + 3
      end
    end
    fan(rings[#lats], yc + b, topSw, 1)
    if botSw then fan(rings[1], yc - b, botSw, -1) end
    return rings[1][0][2]
  end

