              quad(point(e[1],e[2],ta),point(e[3],e[4],ta),point(e[3],e[4],tb),point(e[1],e[2],tb),side=='west'and-1 or 0,1,side=='south'and 1 or 0)
            end
          end
        end
        -- Rounded common southwest corner, one shell (not two overlapping strips).
        local h=edges.west[#edges.west][4];assert(math.abs(h-edges.south[1][2])<1e-9)
        for j=0,3 do for k=0,3 do
          local function point(a,t)local y=height(h,t);return{-.5*t*math.cos(a),y,20+.5*t*math.sin(a),a/math.pi,h-y}end
          local a,b=j*math.pi/8,(j+1)*math.pi/8;quad(point(a,k/4),point(b,k/4),point(b,(k+1)/4),point(a,(k+1)/4),-1,1,1)
        end end
        -- Exposed termination caps meet the accepted north wall and eastern shore.
        for _,side in ipairs{'west','south'}do local e=side=='west'and edges.west[1]or edges.south[#edges.south];local s,h=side=='west'and e[1]or e[3],side=='west'and e[2]or e[4]
          for k=0,3 do
            local function p(t,low)local y=low and.6 or height(h,t);return{side=='west'and-.5*t or s,y,side=='west'and s or 20+.5*t,t*.5,h-y}end
            quad(p(k/4,true),p((k+1)/4,true),p((k+1)/4,false),p(k/4,false),side=='south'and 1 or 0,0,side=='west'and-1 or 0)
          end
        end
