      end
    end
  end

  grid.bondWestCoastCells=nil
  if grid.nativeBondWestCoast then
    grid.bondWestCoastCells={};grid.bondWestCoastGround={}
    grid.bondWestMountainEdges={west={},north={}}
    grid.recordBondMountain=function(first)
      for i=first+1,#opaque,3 do for j=0,2 do
        local a,b=opaque[i+j],opaque[i+(j+1)%3]
        local side,k
        if math.abs(a[1])<1e-10 and math.abs(b[1])<1e-10 then side,k='west',3
        elseif math.abs(a[3]-13)<1e-10 and math.abs(b[3]-13)<1e-10 then side,k='north',1 end
        if side and math.abs(a[k]-b[k])>1e-10 then
          if a[k]>b[k]then a,b=b,a end
