      end end
    end
    for _,e in ipairs(grid.nativeBondWestCoast)do local c=at(e[1],e[2])
      if c and not c.rock and c.isTreeArt then
        local r=grid.bondWestCoastCells[c]or{};r[e[3]]=true;grid.bondWestCoastCells[c]=r
      end
    end
    grid.bondWestCoastFinish=function()
      local donor=underRect(124)
      local function tri(a,b,c)
        local n=faceNormal3(a,b,c);if n[2]<0 then b,c=c,b;n={-n[1],-n[2],-n[3]}end
        for _,v in ipairs{a,b,c}do local q=newV(v[1],v[2],v[3],v[4],v[5],n[1],n[2],n[3]);q.nativeBondCoast=true;opaque[#opaque+1]=q end
      end
      for _,item in ipairs(grid.bondWestCoastGround)do
        local cell,uv=item[1],item[2];local sides=grid.bondWestCoastCells[cell]
        local xs=sides.left and{0,.125,.25,.375,.5,1}or{0,1}
        local zs=sides.up and{0,.125,.25,.375,.5,1}or{0,1}
        -- Terminal edge shares all existing refined mountain cut stations.
        if sides.left and cell.y==12 then xs={0,.125,.15,.25,.375,.5,.75,1}end
        local function height(u,v)
          local d=1
          if sides.left then d=math.min(d,u/.5)end
          if sides.up then d=math.min(d,v/.5)end
          if sides.left and sides.up and u<.5 and v<.5 then d=math.max(0,1-math.sqrt((.5-u)^2+(.5-v)^2)/.5)end
