            if brown then U=donor[1]+(donor[3]-donor[1])*(sides.up and u or v);V=donor[2]+(donor[4]-donor[2])*(1.1-h)
            else U=uv[1]+(uv[3]-uv[1])*u;V=uv[2]+(uv[4]-uv[2])*v end
            return{cell.x+u,h,cell.y+v,U,V}
          end
          local a,b,c,d=point(x0,z0),point(x1,z0),point(x1,z1),point(x0,z1)
          tri(a,c,b);tri(a,d,c)
        end end
      end
      -- The mountain keeps its original top heightfield. Close only the
      -- selected west return and the height-changing north terminal using
      -- breakpoints from the actual emitted mountain edge, not an analytic
      -- approximation of a differently tessellated surface.
      local edges=grid.bondWestMountainEdges
      local function point(x,y,z,u,top)
        return{x,y,z,donor[1]+(donor[3]-donor[1])*u,donor[2]+(donor[4]-donor[2])*((top or 1.1)-y)}
      end
      local function face(a,b,c,d,nx,nz)
        local function emit(a,b,c)
          local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3];local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
          local nx0,ny0,nz0=uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx
          if nx0*nx0+ny0*ny0+nz0*nz0<1e-20 then return end
          local n=faceNormal3(a,b,c);if n[1]*nx+n[3]*nz<0 then b,c=c,b end
          for _,v in ipairs{a,b,c}do local q=newV(v[1],v[2],v[3],v[4],v[5],nx,0,nz);q.nativeBondMountainReturn=true;opaque[#opaque+1]=q end
        end
        if math.max(a[2],b[2],c[2],d[2])-math.min(a[2],b[2],c[2],d[2])>1e-10 then emit(a,b,c);emit(a,c,d)end
      end
      for _,e in ipairs(edges.west)do
        -- One native pixel remains1/16tile. Repeat the bottom.15 rows
        -- below the full-height upper band, as the existing cliff emitter.
        face(point(0,.6,e[1],0,1.6),point(0,.6,e[3],e[3]-e[1],1.6),point(0,.75,e[3],e[3]-e[1],1.6),point(0,.75,e[1],0,1.6),-1,0)
        face(point(0,.75,e[1],0,1.75),point(0,.75,e[3],e[3]-e[1],1.75),point(0,e[4],e[3],e[3]-e[1],1.75),point(0,e[2],e[1],0,1.75),-1,0)
      end
      local function atEdge(x)
        for _,e in ipairs(edges.north)do if x>=e[1]-1e-10 and x<=e[3]+1e-10 then return e[2]+(e[4]-e[2])*(x-e[1])/(e[3]-e[1])end end
        error('missing admitted Bond mountain north terminal')
      end
      local cuts={0,.125,.25,.375,.5,1}
      for _,e in ipairs(edges.north)do for _,x in ipairs{e[1],e[3]}do
        local found=false;for _,v in ipairs(cuts)do if math.abs(v-x)<1e-10 then found=true end end
        if not found then cuts[#cuts+1]=x end
      end end;table.sort(cuts)
      for i=1,#cuts-1 do local a,b=cuts[i],cuts[i+1]
        local ha,hb=.6+.5*math.sin(math.min(1,a/.5)*math.pi*.5),.6+.5*math.sin(math.min(1,b/.5)*math.pi*.5)
        local ta,tb=atEdge(a),atEdge(b)
