    end
  end

  -- Scoped native forest shoulders. Geometry uses the accepted four cosine
  -- facets, native brown124 paint, and the unchanged semantic tree ground.
  if grid.nativeBondEastCoast then
    grid.bondEastCoastCells={};grid.bondEastCoastGround={}
    for _,e in ipairs(grid.nativeBondEastCoast)do local c=at(e[1],e[2])
      if c and not c.rock and(c.isTreeArt or(e[6]==.25 and c.walkable))then grid.bondEastCoastCells[c]=e end
    end
    grid.bondEastCoastFinish=function()
      local donor=underRect(124)
      local function tri(a,b,c)
        local n=faceNormal3(a,b,c);if n[2]<0 then b,c=c,b;n={-n[1],-n[2],-n[3]}end
        for _,v in ipairs{a,b,c}do local q=newV(v[1],v[2],v[3],v[4],v[5],n[1],n[2],n[3]);q.nativeBondEastCoast=true;opaque[#opaque+1]=q end
      end
      for _,item in ipairs(grid.bondEastCoastGround)do
        local cell,uv=item[1],item[2];local e=grid.bondEastCoastCells[cell]
        local width=e[6]or .5;local cuts=e[3]=='up'and{0,width/4,width/2,width*3/4,width,1}or{0,1-width,1-width*3/4,1-width/2,1-width/4,1}
        for i=1,#cuts-1 do
          local va,vb=cuts[i],cuts[i+1];local brown=e[3]=='up'and va<width or e[3]=='down'and vb>1-width
          -- Split only at material-course boundaries so donor UV never escapes.
          local function h(v)local d=e[3]=='up'and v/width or(1-v)/width;return e[5]+(e[4]-e[5])*math.sin(math.min(1,d)*math.pi*.5)end
          local ya,yb=h(va),h(vb);local zs={va,vb}
          if brown then for band=1,math.floor(e[4]-e[5])do local yy=e[4]-band
            if yy>math.min(ya,yb)+1e-10 and yy<math.max(ya,yb)-1e-10 then zs[#zs+1]=va+(vb-va)*(yy-ya)/(yb-ya)end
          end end;table.sort(zs)
          for j=1,#zs-1 do local a,b=zs[j],zs[j+1];local ha=ya+(yb-ya)*(a-va)/(vb-va);local hb=ya+(yb-ya)*(b-va)/(vb-va)
            local band=brown and math.floor(e[4]-(ha+hb)*.5)or 0
            local function point(u,v,y)
              local U,V
              if brown then U=donor[1]+(donor[3]-donor[1])*u;V=donor[2]+(donor[4]-donor[2])*(e[4]-y-band)
              else U=uv[1]+(uv[3]-uv[1])*u;V=uv[2]+(uv[4]-uv[2])*v end
              return{cell.x+u,y,cell.y+v,U,V}
            end
            local aa,bb,cc,dd=point(0,a,ha),point(1,a,ha),point(1,b,hb),point(0,b,hb);tri(aa,cc,bb);tri(aa,dd,cc)
          end
        end
      end
    end
  end

  -- Pass 3: per-cell geometry.
  -- ---------------------------------------------------------------
  local EPS = 1e-4
  grid.indigoRailCells={}
  if nativeIndigoRails(input,atlas)and C.FENCE_H==.6 then
    local valid=true
    for yy=13,19 do for _,xx in ipairs{9,13}do local c=at(xx,yy);local comp=compOf(c)
      if not c or not comp or comp.kind~='prop'or c.propShape~='tree'or not c.blobTree or c.isTreeArt or c.unit or c.rock or c.hgt~=.75 or not c.hasOver then valid=false end
    end end
    if valid then for yy=13,19 do for _,xx in ipairs{9,13}do grid.indigoRailCells[at(xx,yy)]=true end end end
  end
  -- Two source-projected ceremonial arches, not floor balustrades.
  -- Physical height is authored from three facade rows, independently of
  -- the ROM elevation code. U=X, V=Z-(Y-groundY) preserves native artwork.
  grid.indigoArchCells={}
  if next(grid.indigoRailCells)then
    for yy=13,19 do for xx=9,13 do local c=at(xx,yy)
      if c and c.hasOver then grid.indigoArchCells[c]=true end
    end end
  end
  grid.emitIndigoRail=function(cell,x,z,gy)
    if grid.indigoArchesEmitted then return end
    grid.indigoArchesEmitted=true
    local function tile(xx,yy)local c=at(xx,yy);return c and c.hasOver and atlas.texels(c.mid,'over'),c end
    local function solid(px,py,start)
      if px<0 or px>=80 or py<0 or py>=48 then return false end
      local t=tile(9+math.floor(px/16),start+math.floor(py/16))
      return t and t[(py%16)*16+px%16+1]>=0
    end
    local function color(px,py,start)
      if not solid(px,py,start)then return nil end
      local t=tile(9+math.floor(px/16),start+math.floor(py/16))
      return t[(py%16)*16+px%16+1]
    end
    local function uv(c,px,py)
      local r=overRect(c.mid);local ax,ay=math.floor(r[1]*atlas.w),math.floor(r[2]*atlas.h)
      return (ax+px+.5)/atlas.w,(ay+py+.5)/atlas.h
    end
    local function q(a,b,c,d,nx,ny,nz,part)
      local first=#cutoutOver+1
      quadN(cutoutOver,a[1],a[2],a[3],a[4],a[5],b[1],b[2],b[3],b[4],b[5],c[1],c[2],c[3],c[4],c[5],d[1],d[2],d[3],d[4],d[5],nx,ny,nz)
      for j=first,#cutoutOver do cutoutOver[j].indigoArchPart=part or 'return' end
    end
    for _,start in ipairs{13,17}do
      local front=start+3;local back=front-(start==17 and 1 or .375)
      local covered={}
      for py=0,47 do for px=0,79 do if solid(px,py,start)then
        local _,c=tile(9+math.floor(px/16),start+math.floor(py/16))
        local u,v=uv(c,px%16,py%16)
        local x0,x1=9+px/16,9+(px+1)/16
        local y0,y1=gy+3-(py+1)/16,gy+3-py/16
        local function p(xx,yy,zz)return{xx,yy,zz,u,v}end
        -- Coalesce equal-color native runs. Point sampling preserves every
        -- original pixel while avoiding thousands of coplanar pixel faces.
        if not covered[py*80+px]then
          local finish=px+1;while finish<80 and not covered[py*80+finish]and color(finish,py,start)==color(px,py,start)do finish=finish+1 end
          local bottom=py+1
          while bottom<48 do local same=true;for xx=px,finish-1 do if covered[bottom*80+xx]or color(xx,bottom,start)~=color(px,py,start)then same=false;break end end;if not same then break end;bottom=bottom+1 end
          for yy=py,bottom-1 do for xx=px,finish-1 do covered[yy*80+xx]=true end end
          local xe=9+finish/16
          local bottomY=gy+3-bottom/16
          q(p(x0,bottomY,front),p(xe,bottomY,front),p(xe,y1,front),p(x0,y1,front),0,0,1,'facade')
          q(p(xe,bottomY,back),p(x0,bottomY,back),p(x0,y1,back),p(xe,y1,back),0,0,-1,'rear')
        end
        if not solid(px-1,py,start)then q(p(x0,y0,back),p(x0,y0,front),p(x0,y1,front),p(x0,y1,back),-1,0,0)end
        if not solid(px+1,py,start)then q(p(x1,y0,front),p(x1,y0,back),p(x1,y1,back),p(x1,y1,front),1,0,0)end
        if not solid(px,py-1,start)and not(start==17 and py==0 and(px<16 or px>=64))then q(p(x0,y1,front),p(x1,y1,front),p(x1,y1,back),p(x0,y1,back),0,1,0)end
        if not solid(px,py+1,start)then q(p(x0,y0,back),p(x1,y0,back),p(x1,y0,front),p(x0,y0,front),0,-1,0)end
      end end;if py%4==0 then Y()end end
    end
    -- The intervening side-strip is the visible cap of the second pair
    -- of supports. At Y=3, Z=sourceV+3 it continues into the arch front.
    for _,xx in ipairs{9,13}do local t,c=tile(xx,16)
      for py=0,15 do local px=0;while px<16 do if t[py*16+px+1]>=0 then
        local begin=px;local color=t[py*16+px+1];repeat px=px+1 until px==16 or t[py*16+px+1]~=color
        local u,v=uv(c,begin,py);local yy=gy+3
        local function p(a,b)return{a,yy,b,u,v}end
        q(p(xx+begin/16,19+py/16),p(xx+begin/16,19+(py+1)/16),p(xx+px/16,19+(py+1)/16),p(xx+px/16,19+py/16),0,1,0,'cap')
      else px=px+1 end end end
    end
    grid.nativeIndigoArches={count=2,authoredHeight=3,minX=9,maxX=14,minZ=15.625,maxZ=20,groundY=gy,topY=gy+3,centerClearance=1.5,sourceProjection='U=X,V=Z-(Y-groundY)'}
  end

  local keyedGrass, fenceCells, signCount, blobTrunks, fencePosts, flowerCells = 0, 0, 0, 0, 0, 0
  do
  -- r9 Part B helpers for the understory closure (see the M2 block below)
  local DIR_BY = {}
  for _, d in ipairs(DIRS) do DIR_BY[d.name] = d end
  local BLOB_LAT_DENSE = { 0, 50 * math.pi / 180 }
  local BLOB_LAT_EDGE = { -40 * math.pi / 180, 25 * math.pi / 180 }

  -- open sides of a forest cell's unit (tree art) or of the blob cell itself
  local function forestOpen(c)
    if c.unit then return c.unit.open or {} end
    local o = c.blobOpen
    if not o then
      o = {}
      for _, d in ipairs(DIRS) do
        local nc = at(c.x + d.dx, c.y + d.dy)
        if nc and not isForestCell(nc) then o[d.name] = true end
      end
      c.blobOpen = o
    end
    return o
  end
  local function underInset(c)
    if IN.flora then return IN.flora:underInset(c) end -- W7
    if not c.unit then return C.FOREST_UNDER_INSET_BLOB end
    return (c.unit.w >= 2) and C.FOREST_UNDER_INSET or C.FOREST_UNDER_INSET_1
  end
  local function underHeight(c)
    if IN.flora then return IN.flora:underHeight(c) end -- W7
    if not c.unit then return C.FOREST_UNDER_H_BLOB end
    if c.unit.forest3 then return C.FOREST3_UNDER_H end
    return (c.unit.w >= 2) and C.FOREST_UNDER_H or C.FOREST_UNDER_H_1
  end
  local function underSidesOf(c)
    local open = c.underSides
    if open then return open end
    open = {}
    -- a unit / blob open on both sides of either axis is part of a tree
    -- line you can see under: no closure (its end walls read as slabs)
    local uo = forestOpen(c)
    local thin = (uo.up and uo.down) or (uo.left and uo.right)
    for _, d in ipairs(DIRS) do
      local nx, ny = c.x + d.dx, c.y + d.dy
      if nx < 0 or ny < 0 or nx >= W or ny >= H then
        if isBorder then open[d.name] = "in" end
      else
        local nc = at(nx, ny)
        if nc and not isForestCell(nc) and not thin then
          open[d.name] = "out"
        elseif not nc and isBorder and not thin then
          -- r11 (review M12): the ring's hole is the map -- facing it the
          -- forest edge is "out" (closed), not open to the sky
          open[d.name] = "out"
        end
      end
    end
    c.underSides = open
    return open
  end

  -- r11 (USER REPORT 13: "grass ... only rendering a shell"): a TALL-GRASS
  -- cell's base is one texel of its art's main BLADE colour (the most
  -- common texel outside the keyed ground greens, not near-black) -- the
  -- flat grass tile never shows under the blades; false without art
  local grassBaseUv
  do
    local cache = {}
    local KEY = { [0x73cea5] = true, [0x42b58c] = true, [0xa5e6c5] = true }
    grassBaseUv = function(mid, uv)
      local r = cache[mid]
      if r ~= nil then return r end
      r = false
      local t = type(atlas.texels) == "function" and atlas.texels(mid, "under") or nil
      if t then
        local cnt, first, bi, bn = {}, {}, nil, 0
        for i = 1, 256 do
          local v = t[i]
          if v and v >= 0 and not KEY[v] and math.max(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256) >= 100 then
            cnt[v] = (cnt[v] or 0) + 1
            first[v] = first[v] or i
            if cnt[v] > bn then bi, bn = first[v], cnt[v] end
          end
        end
        if bi then
          local tx, ty = (bi - 1) % 16 + 0.5, math.floor((bi - 1) / 16) + 0.5
          r = subRect(uv, tx / 16, ty / 16, tx / 16, ty / 16)
        end
      end
      cache[mid] = r
      return r
    end
  end

  -- =================================================================
  -- r13c (verifier r2 on r13b; USER, image 20: "smooth this out"): HILL
  -- BANDS and SMOOTH LEDGE ENDS (replaces the r13b bank zone and fades).
  -- The hill never ends in a vertical step: wherever a raised hill cell
  -- (pass 1c's rampH, ledge cells' ground plane included) meets ground that
  -- is not raised -- flat walkable ground, grass, trees, fences, buildings,
  -- rocks, water (a target: not raised, not a ledge / curb, its height at or
  -- below the hill's base) -- its last LEDGE_DEPTH rounds down to the base
  -- (a BAND: h = base + (Q - base) x S(distance / LEDGE_DEPTH), S the
  -- smoothstep, flat at both ends), and a corner that only touches such
  -- ground diagonally dips the same way round the corner point (a DIP, the
  -- distance to that corner). Every hill cell round a vertex that touches
  -- a target dips there, so shared edges agree (one height function; the
  -- band's cut positions are the same everywhere). Water keeps its bank
  -- step below the base; rocks lower their side to the base (pass 3r).
  -- A ledge run's ROUNDED END beside a target or a banked hill path (pass
  -- 1c) MORPHS, over its quarter turn, from the curb's profile to the band's
  -- (its foot on the floor -- the street, or at a banked end the path's
  -- plane), so the roll sinks into the ground and the ground behind it (the
  -- side band / the banked SHOULDER, sinking to the path's edge) continues
  -- it: no notch, no side wall, no sliver, the roll's art never squeezed.
  -- Hill cells without bands, the bridge paths of 1-2-cell gaps (report 1)
  -- included, are unchanged. Visual only: heights (heightAt) and hops are
  -- unchanged. Each banded cell is a grid (cell.hg: its cut positions,
  -- points and normals; the height function hg.hf) built here before the
  -- ground pass; its boundary points are WELDED into the neighbour across
  -- each edge (grid.edgeSplits: that neighbour's quads are split there when
  -- its own surface passes through them) -- no T-junctions, no cracks.
  -- (fields on grid: M.build's locals limit)
  -- =================================================================
  grid.edgeSplits = {}
  do
    local NB = C.LEDGE_ROUND_SEGS + 1
    local BX = {}
    for k = 0, NB do BX[k] = 0.5 * (k / NB) + 0.25 * (1 - math.cos(math.pi * k / NB)) end
    BX[0], BX[NB] = 0, 1
    grid.BX, grid.NB = BX, NB
  end
  grid.bandS = function(x)
    if x <= 0 then return 0 elseif x >= 1 then return 1 end
    return x * x * (3 - 2 * x)
  end
  -- a triangle T = { V1, V2, V3 } (V = { point, uv, normal }) of a ground
  -- surface, its edges split at the points of `splits` lying strictly on
  -- them (in plan) at the edge's own height (within tol): a fan from the
  -- opposite corner (points on one edge) or round the centroid (on more).
  -- Wound so the geometric normal points up. uvOf / nOf (point) -> uv /
  -- normal of an inserted point. Returns the number of points rejected
  -- (off the edge's height: a step, not a seam).
  grid.fanTri = function(list, T, splits, uvOf, nOf, tol)
    local function emit(a, b, c)
      local g = cross3(sub3(b[1], a[1]), sub3(c[1], a[1]))
      if g[1] * g[1] + g[2] * g[2] + g[3] * g[3] < 1e-24 then return end
      if g[2] < 0 then b, c = c, b end
      tri3(list, a[1], a[2], a[3], b[1], b[2], b[3], c[1], c[2], c[3])
    end
    if not splits then emit(T[1], T[2], T[3]) return 0 end
    local ring, corner, nEdges, splitE, miss = {}, {}, 0, nil, 0
    for e = 1, 3 do
      local ca, cb = T[e], T[e % 3 + 1]
      corner[e] = #ring + 1
      ring[#ring + 1] = ca
      local pa, pb = ca[1], cb[1]
      local ex, ez = pb[1] - pa[1], pb[3] - pa[3]
      local l2 = ex * ex + ez * ez
      if l2 > 1e-18 then
        local len = math.sqrt(l2)
        local on = {}
        for _, q in ipairs(splits) do
          local qx, qz = q[1] - pa[1], q[3] - pa[3]
          local f = (qx * ex + qz * ez) / l2
          if f * len > 1e-7 and (1 - f) * len > 1e-7 and math.abs(qx * ez - qz * ex) <= 1e-7 * len then
            if math.abs(q[2] - (pa[2] + (pb[2] - pa[2]) * f)) <= tol then on[#on + 1] = { f, q } else miss = miss + 1 end
          end
        end
        if #on > 0 then
          nEdges, splitE = nEdges + 1, e
          table.sort(on, function(p1, p2) return p1[1] < p2[1] end)
          local lastF
          for _, o in ipairs(on) do
            if not lastF or (o[1] - lastF) * len > 1e-7 then
              ring[#ring + 1] = { o[2], uvOf(o[2]), nOf(o[2]) }
              lastF = o[1]
            end
          end
        end
      end
    end
    local m = #ring
    if nEdges == 0 then emit(T[1], T[2], T[3])
    elseif nEdges == 1 then
      local o = corner[(splitE + 1) % 3 + 1]
      for i = 1, m - 2 do emit(ring[o], ring[(o + i - 1) % m + 1], ring[(o + i) % m + 1]) end
    else
      local c1, c2, c3 = T[1][1], T[2][1], T[3][1]
      local cp = { (c1[1] + c2[1] + c3[1]) / 3, (c1[2] + c2[2] + c3[2]) / 3, (c1[3] + c2[3] + c3[3]) / 3 }
      local ct = { cp, uvOf(cp), nOf(cp) }
      for i = 1, m do emit(ct, ring[i], ring[i % m + 1]) end
    end
    return miss
  end
  -- a plain ground quad (corners P[i] = { point, uv }, one normal; the
  -- triangles (1, 2, 3) (1, 3, 4) as quadN) split at welded points
  -- (ledgefinal2: N4 = per-corner normals (grid.quadVN): a point put in
  -- takes the hill ground's normal there (grid.vnAt: a welded point's
  -- banded grid), else the corners' by its place in the triangle)
  grid.splitQuad = function(list, P, uvOf, n, splits, N4)
    local function uvp(q) local u, v = uvOf(q[1], q[3]); return { u, v } end
    for _, tri in ipairs({ { 1, 2, 3 }, { 1, 3, 4 } }) do
      local T = {}
      for i = 1, 3 do T[i] = { P[tri[i]][1], P[tri[i]][2], N4 and N4[tri[i]] or n } end
      local nn = function() return n end
      if N4 then
        nn = function(q)
          local v = grid.vnAt(q[1], q[3], q[2])
          if v then return v end
          local a, b, c = T[1][1], T[2][1], T[3][1]
          local det = (b[3] - c[3]) * (a[1] - c[1]) + (c[1] - b[1]) * (a[3] - c[3])
          if math.abs(det) < 1e-14 then return n end
          local l1 = ((b[3] - c[3]) * (q[1] - c[1]) + (c[1] - b[1]) * (q[3] - c[3])) / det
          local l2 = ((c[3] - a[3]) * (q[1] - c[1]) + (a[1] - c[1]) * (q[3] - c[3])) / det
          local l3 = 1 - l1 - l2
          local na, nb, nc = T[1][3], T[2][3], T[3][3]
          return norm3({ l1 * na[1] + l2 * nb[1] + l3 * nc[1], l1 * na[2] + l2 * nb[2] + l3 * nc[2], l1 * na[3] + l2 * nb[3] + l3 * nc[3] })
        end
      end
      grid.weldMiss = (grid.weldMiss or 0) + grid.fanTri(list, T, splits, uvp, nn, 1e-6)
    end
  end
  -- r12 (ledge hills): a hill cell's ground at its four corner heights
  -- (r13c: split at the welded points of a banded neighbour)
  grid.rampQuad = function(cell, x0, z0, x1, z1, guv)
    if cell.nativeFiveStair or cell.nativeElevationStair then
      -- Native137/145 repeat four courses: two light tread rows followed
      -- by two dark riser rows. Keep their own cell/layer UVs, and retain
      -- rampH/supportRamps for smooth movement independently of this mesh.
      local start=#opaque
      local north,south=cell.rampH[1],cell.rampH[4]
      for step=0,3 do
        local za,zb=z0+step/4,z0+(step+1)/4
        local hi=north+(south-north)*(step+.5)/4
        local lo=step==3 and south or north+(south-north)*(step+1.5)/4
        local tr=subRect(guv,0,step/4,1,step/4+2/16)
        local rr=subRect(guv,0,step/4+2/16,1,(step+1)/4)
        if step==0 then
          -- Half-rise at the upper landing centers the four treads around
          -- the unchanged support incline (maximum discrepancy .04375).
          local cap=subRect(guv,.5,2.5/16,.5,2.5/16)
          quadN(opaque,x0,hi,za,cap[1],cap[2],x1,hi,za,cap[1],cap[2],
            x1,north,za,cap[1],cap[2],x0,north,za,cap[1],cap[2],0,0,1)
        end
        quadN(opaque,x0,hi,za,tr[1],tr[2],x0,hi,zb,tr[1],tr[4],
          x1,hi,zb,tr[3],tr[4],x1,hi,za,tr[3],tr[2],0,1,0)
        quadN(opaque,x0,lo,zb,rr[1],rr[4],x1,lo,zb,rr[3],rr[4],
          x1,hi,zb,rr[3],rr[2],x0,hi,zb,rr[1],rr[2],0,0,1)
        -- Only exterior sides of each contiguous native stair group.
        -- No coplanar returns between neighboring stair cells.
        for _,side in ipairs{-1,1}do local nb=at(cell.x+side,cell.y)
          if not (nb and (nb.nativeFiveStair or nb.nativeElevationStair) and nb.rampH and nb.rampH[1]==north and nb.rampH[4]==south)then
            local x=side<0 and x0 or x1
            local sr=subRect(guv,.5,step/4+2.5/16,.5,step/4+2.5/16)
            if side<0 then
              quadN(opaque,x,south,za,sr[1],sr[2],x,south,zb,sr[1],sr[2],x,hi,zb,sr[1],sr[2],x,hi,za,sr[1],sr[2],-1,0,0)
            else
              quadN(opaque,x,south,zb,sr[1],sr[2],x,south,za,sr[1],sr[2],x,hi,za,sr[1],sr[2],x,hi,zb,sr[1],sr[2],1,0,0)
            end
          end
        end
      end
      for i=start+1,#opaque do if cell.nativeFiveStair then opaque[i].nativeFiveStep=true else opaque[i].nativeElevationStep=true end end
      return
    end
    local rh = cell.rampH
    local nrm = grid.rampFaceN(cell)
    local sp = grid.edgeSplits[cell]
    local P = { { { x0, rh[1], z0 }, { guv[1], guv[2] } }, { { x1, rh[2], z0 }, { guv[3], guv[2] } },
      { { x1, rh[3], z1 }, { guv[3], guv[4] } }, { { x0, rh[4], z1 }, { guv[1], guv[4] } } }
    -- (ledgefinal2: smooth vertex normals where hill faces meet)
    local N4 = grid.quadVN(P, nrm)
    if sp then
      local du, dv = guv[3] - guv[1], guv[4] - guv[2]
      grid.splitQuad(opaque, P, function(px, pz) return guv[1] + (px - x0) * du, guv[2] + (pz - z0) * dv end, nrm, sp, N4)
    elseif N4 then
      grid.quadV4(opaque, P, N4)
    else
      quadN(opaque, x0, rh[1], z0, guv[1], guv[2], x1, rh[2], z0, guv[3], guv[2],
        x1, rh[3], z1, guv[3], guv[4], x0, rh[4], z1, guv[1], guv[4], nrm[1], nrm[2], nrm[3])
    end
  end
  -- (a quad with a normal per corner: quadN's triangles)
  grid.quadV4 = function(list, P, N4)
    local V = {}
    for i = 1, 4 do
      local p, t, n = P[i][1], P[i][2], N4[i]
      V[i] = newV(p[1], p[2], p[3], t[1], t[2], n[1], n[2], n[3])
    end
    local n = #list
    list[n + 1], list[n + 2], list[n + 3] = V[1], V[2], V[3]
    list[n + 4], list[n + 5], list[n + 6] = V[1], V[3], V[4]
  end
  -- a flat cell's ground whose edge carries welded points: the flat quad,
  -- split there
  grid.flatQuad = function(cell, x0, z0, x1, z1, y, guv)
    local du, dv = guv[3] - guv[1], guv[4] - guv[2]
    grid.splitQuad(opaque, { { { x0, y, z0 }, { guv[1], guv[2] } }, { { x1, y, z0 }, { guv[3], guv[2] } },
      { { x1, y, z1 }, { guv[3], guv[4] } }, { { x0, y, z1 }, { guv[1], guv[4] } } },
      function(px, pz) return guv[1] + (px - x0) * du, guv[2] + (pz - z0) * dv end, UP, grid.edgeSplits[cell])
  end
  -- the ground height of a cell at a plan point on / in it (its grid's
  -- function, its hill corners, or its flat height)
  grid.groundAt = function(Z, px, pz)
    local ld = Z.ledgeDir
    if ld and Z.rampH then
      -- (a ledge cell in front of its curb's back line: the strip under the
      -- curb -- the street level, a banked end's floor on the path's plane)
      local t = ld == "down" and (Z.y + 1 - pz) or (ld == "up" and (pz - Z.y) or (ld == "left" and (px - Z.x) or (Z.x + 1 - px)))
      if t < C.LEDGE_DEPTH - 1e-9 then
        local hz = ld == "down" or ld == "up"
        local a = hz and (px - Z.x) or (pz - Z.y)
        for sg = -1, 1, 2 do
          local bk = Z.ledgeBank and Z.ledgeBank[sg]
          if bk and (sg > 0 and a > 1 - C.LEDGE_DEPTH + 1e-9 or sg < 0 and a < C.LEDGE_DEPTH - 1e-9) then
            return bk.hE + (bk.hF - bk.hE) * t
          end
        end
        return Z.baseHgt
      end
    end
    if Z.hg then return Z.hg.hf(px, pz) end
    local r = Z.rampH
    if r then
      local fx, fz = px - Z.x, pz - Z.y
      return (r[1] * (1 - fx) + r[2] * fx) * (1 - fz) + (r[4] * (1 - fx) + r[3] * fx) * fz
    end
    return Z.hgt
  end

  -- ledgefinal2 (verifier final-r1 F1: Route 22's gutter (28..33,15), where
  -- the ledges' back bands met a rock row at the base, read as a narrow V
  -- trench): a hill edge toward a ROCK whose height is level along the edge
  -- FILLS -- the band's target there is the hill's own edge height (no dip)
  -- and the rock's side comes down to it (pass 3r: its soft foot), so the
  -- hill meets the rock's foot with no trench. Toward a cell along the edge
  -- that does not fill alike, the target ramps down to the base over the
  -- whole cell (linear -- a tent peaking mid-cell where neither side goes
  -- on: both sides draw the same polyline, its breaks on the rock's
  -- lattice). grid.rockFillOK: a heightfield rock (not lone: a
  -- boulder has its own ground) tall enough to keep a face over the fill.
  grid.rockFillOK = function(Y, fe)
    if not (Y and Y.rock and Y.hgt and underRect(Y.mid)) then return false end
    local function rk(dx, dy) local q = at(Y.x + dx, Y.y + dy); return q and q.rock == true end
    if not (rk(-1, 0) or rk(1, 0) or rk(0, -1) or rk(0, 1)) then return false end
    local thick = false
    for _, q in ipairs({ { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }) do
      if rk(q[1], 0) and rk(0, q[2]) and rk(q[1], q[2]) then thick = true break end
    end
    return fe <= Y.hgt + (thick and C.ROCK_H0 or C.ROCK_KERB_H) - 0.2
  end
  grid.rkCont = function(X, nm, sg)
    local hz = nm == "up" or nm == "down"
    local Y = at(X.x + (hz and sg or 0), X.y + (hz and 0 or sg))
    return Y and Y.rkFill and Y.rkFill[nm] and math.abs(Y.rkFill[nm] - X.rkFill[nm]) < 1e-6 or false
  end
  grid.rkFillAt = function(X, nm, a)
    local fe, hT = X.rkFill[nm], X.hb.hT
    local hz = nm == "up" or nm == "down"
    local A0 = hz and X.x or X.y
    local RW = 1
    local w = 1
    if not grid.rkCont(X, nm, -1) then w = math.min(w, (a - A0) / RW) end
    if not grid.rkCont(X, nm, 1) then w = math.min(w, (A0 + 1 - a) / RW) end
    if w <= 0 then return hT end
    if w >= 1 then return fe end
    return hT + (fe - hT) * w
  end
  -- the band pass: targets, dips, grids, welds
  grid.hillBands = function()
    grid.bandCells, grid.bandEnds, grid.bandStat = 0, 0, {}
    if C.LEDGE_END_BANK == false or indoor or cave then return end
    local D, BX, NB, S = C.LEDGE_DEPTH, grid.BX, grid.NB, grid.bandS
    local EXI = { down = { 4, 3, 1, 2 }, up = { 1, 2, 4, 3 }, left = { 1, 4, 2, 3 }, right = { 2, 3, 1, 4 } }
    local CO = { { 0, 0 }, { 1, 0 }, { 1, 1 }, { 0, 1 } }
    local EC = { up = { 1, 2 }, right = { 2, 3 }, down = { 3, 4 }, left = { 4, 1 } }
    local KE = { { "up", "left" }, { "up", "right" }, { "down", "right" }, { "down", "left" } }
    local function target(X, Y)
      if not Y or Y.rampH or Y.ledgeDir or Y.curbDir then return false end
      if Y.hgtSource == "fallback" or Y.hgt == nil then return false end
      return Y.hgt <= X.baseHgt + 1e-6
    end
    -- r13c (verifier r2: Route 4's U corners -- a lip-top slab hanging
    -- over the street, two domes, a gap under it): a CORNER CURB C (a curb
    -- cell, no hill) whose rounded end turns toward the exit of the ledge P
    -- right behind it is the corner of two runs: C.cornerTo = P, C.cornerSg
    -- = that end. The curb closure draws C's run's rounded end (turning onto
    -- P's exit), a straight piece of P's curb from there to P, and the
    -- ground behind both curbs; P's run continues into C (no dome).
    local OUTC = { down = { 0, 1 }, up = { 0, -1 }, left = { -1, 0 }, right = { 1, 0 } }
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local Cc = grid[y][x]
        if Cc and Cc.curbDir and not Cc.rampH then
          local d = Cc.curbDir
          local o = OUTC[d]
          local P = at(x - o[1], y - o[2])
          if P and P.ledgeDir and P.rampH and P.ledgeDir ~= d then
            local hz = d == "down" or d == "up"
            for sg = -1, 1, 2 do
              local ax, az = hz and sg or 0, hz and 0 or sg
              local nb = at(x + ax, y + az)
              local po = OUTC[P.ledgeDir]
              if not (nb and (nb.ledgeDir or nb.curbDir) == d) and po[1] == ax and po[2] == az then
                Cc.cornerTo, Cc.cornerSg = P, sg
              end
            end
          end
        end
      end
    end
    local list = {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local X = grid[y][x]
        if X and X.rampH and X.baseHgt then
          local b, rh, ld = X.baseHgt, X.rampH, X.ledgeDir
          local real = { true, true, true, true }
          if ld then real[EXI[ld][1]], real[EXI[ld][2]] = false, false end
          local e, v, any = {}, {}, false
          local rocks
          for _, d in ipairs(DIRS) do
            if d.name ~= ld then
              local Y = at(x + d.dx, y + d.dy)
              local c1, c2 = EC[d.name][1], EC[d.name][2]
              if target(X, Y) and math.max(rh[c1], rh[c2]) > b + 1e-6 then
                e[d.name], any = true, true
                if Y.rock then rocks = rocks or {}; rocks[Y] = true; rocks[d.name] = true end
              end
            end
          end
          for k = 1, 4 do
            if real[k] and rh[k] > b + 1e-6 and not e[KE[k][1]] and not e[KE[k][2]] then
              local vx, vz = x + CO[k][1], y + CO[k][2]
              for qx = vx - 1, vx do
                for qz = vz - 1, vz do
                  local Z = at(qx, qz)
                  if Z ~= X and target(X, Z) then
                    v[k], any = true, true
                    if Z.rock then rocks = rocks or {}; rocks[Z] = true end
                  end
                end
              end
            end
          end
          if any then
            X.hb = { hT = b, e = e, v = v }; X.hbRock = rocks
            grid.bandStat[y * W + x + 1] = X.hb
            -- ledgefinal2: a rock-facing edge whose hill edge is level along
            -- it FILLS (phase A): X.rkFill[side] = that height
            -- (stats.hillBands[i].rockE: the rock-facing sides -- debug)
            if rocks then
              for _, d in ipairs(DIRS) do if rocks[d.name] and e[d.name] then X.hb.rockE = X.hb.rockE or {}; X.hb.rockE[d.name] = true end end
            end
            if rocks and not X.ledgeBank and not isBorder then
              for _, d in ipairs(DIRS) do
                if rocks[d.name] then
                  local c1, c2 = EC[d.name][1], EC[d.name][2]
                  if math.abs(rh[c1] - rh[c2]) < 1e-6 and grid.rockFillOK(at(x + d.dx, y + d.dy), rh[c1]) then
                    X.rkFill = X.rkFill or {}
                    X.rkFill[d.name] = rh[c1]
                    X.hb.fill = X.rkFill -- (stats.hillBands: debug)
                  end
                end
              end
            end
          end
          if any or X.ledgeBank then list[#list + 1] = X end
        end
      end
    end
    -- (stats.ledgeEnds[i].smooth = "bank" / "band": a smooth end; .corner
    -- = its neighbour is a corner curb turning onto this run, .curb = the
    -- run's own curb cell: neither is an end)
    for _, e in ipairs(grid.ledgeEnds or {}) do
      local c = at(e.x, e.y)
      local hz = e.dir == "down" or e.dir == "up"
      local n = at(e.x + (hz and e.sg or 0), e.y + (hz and 0 or e.sg))
      if e.bank then e.smooth = "bank" elseif c and c.hb and c.hb.e[e.side] then e.smooth = "band" end
      if n and n.cornerTo == c then e.corner = true end
      if n and n.curbDir == e.dir then e.curb = true end -- (the run goes on into its curb cell)
    end
    -- (ledgefinal2: a rock edge fills only as part of a run of two or more
    -- cells -- a lone one keeps its trough, round-bottomed: a one-cell
    -- fill would peak mid-cell against the rock)
    do
      local drop = {}
      for _, X in ipairs(list) do
        for nm in pairs(X.rkFill or {}) do
          if not grid.rkCont(X, nm, -1) and not grid.rkCont(X, nm, 1) then drop[#drop + 1] = { X, nm } end
        end
      end
      for _, q in ipairs(drop) do
        local X = q[1]
        X.rkFill[q[2]] = nil
        if next(X.rkFill) == nil then X.rkFill = nil; X.hb.fill = nil end
      end
    end
    -- the grids (phase A: every banded cell's function first, so the welds
    -- below can test each neighbour's own surface)
    for _, X in ipairs(list) do
      local x0, z0 = X.x + 0.0, X.y + 0.0
      local x1, z1 = x0 + 1.0, z0 + 1.0
      local ld, hb, bks, rh = X.ledgeDir, X.hb, X.ledgeBank, X.rampH
      local horiz = ld == "down" or ld == "up"
      -- the region: a ledge cell's ground plane (behind the curb's back
      -- line; the curb closure's arithmetic: exit edge - out x D)
      local gx0, gx1, gz0, gz1 = x0, x1, z0, z1
      if ld == "down" then gz1 = z1 - D elseif ld == "up" then gz0 = z0 + D
      elseif ld == "left" then gx0 = x0 + D elseif ld == "right" then gx1 = x1 - D end
      local hT = hb and hb.hT or X.baseHgt
      local e, v = hb and hb.e or {}, hb and hb.v or {}
      local function tIn(px, pz) -- a ledge cell: the distance in from its exit edge
        if ld == "down" then return z1 - pz elseif ld == "up" then return pz - z0
        elseif ld == "left" then return px - x0 end
        return x1 - px
      end
      -- the height: a CHAIN of modifiers, each subtracting the EXCESS of
      -- the surface so far over the target at its edge / corner, fading
      -- inward: f_k(p) = f_{k-1}(p) - (f_{k-1}(p on the edge) - base) (1 -
      -- S(d / D)) -- zero change where that edge already lies at the base, so
      -- a neighbour across a perpendicular edge (its own band, or a dip at
      -- the shared corner) gets the very same values there. First a banked
      -- end's SHOULDER (the excess over the path's edge hp(t))
      local mods = {}
      local function Q0(px, pz)
        local fx, fz = px - x0, pz - z0
        return (rh[1] * (1 - fx) + rh[2] * fx) * (1 - fz) + (rh[4] * (1 - fx) + rh[3] * fx) * fz
      end
      if bks then
        for sg = -1, 1, 2 do
          local bk = bks[sg]
          if bk then
            local ae = sg > 0 and (horiz and x1 or z1) or (horiz and x0 or z0)
            mods[#mods + 1] = function(f, px, pz)
              local dd = math.abs((horiz and px or pz) - ae)
              if dd >= D then return f(px, pz) end
              local hp = bk.hE + (bk.hF - bk.hE) * tIn(px, pz)
              local ex = horiz and f(ae, pz) or f(px, ae)
              return f(px, pz) - (ex - hp) * (1 - S(dd / D))
            end
          end
        end
      end
      if hb then
        -- (ledgefinal2: a filling rock edge's target -- grid.rkFillAt)
        local fl = X.rkFill or {}
        local function tU(a) return fl.up and grid.rkFillAt(X, "up", a) or hT end
        local function tD(a) return fl.down and grid.rkFillAt(X, "down", a) or hT end
        local function tL(a) return fl.left and grid.rkFillAt(X, "left", a) or hT end
        local function tR(a) return fl.right and grid.rkFillAt(X, "right", a) or hT end
        if e.up then mods[#mods + 1] = function(f, px, pz)
          local dd = pz - z0
          if dd >= D then return f(px, pz) end
          return f(px, pz) - (f(px, z0) - tU(px)) * (1 - S(dd / D))
        end end
        if e.down then mods[#mods + 1] = function(f, px, pz)
          local dd = z1 - pz
          if dd >= D then return f(px, pz) end
          return f(px, pz) - (f(px, z1) - tD(px)) * (1 - S(dd / D))
        end end
        if e.left then mods[#mods + 1] = function(f, px, pz)
          local dd = px - x0
          if dd >= D then return f(px, pz) end
          return f(px, pz) - (f(x0, pz) - tL(pz)) * (1 - S(dd / D))
        end end
        if e.right then mods[#mods + 1] = function(f, px, pz)
          local dd = x1 - px
          if dd >= D then return f(px, pz) end
          return f(px, pz) - (f(x1, pz) - tR(pz)) * (1 - S(dd / D))
        end end
        for k = 1, 4 do
          if v[k] then
            local cx, cz = x0 + CO[k][1], z0 + CO[k][2]
            mods[#mods + 1] = function(f, px, pz)
              local rr = math.sqrt((px - cx) * (px - cx) + (pz - cz) * (pz - cz))
              if rr >= D then return f(px, pz) end
              return f(px, pz) - (f(cx, cz) - hT) * (1 - S(rr / D))
            end
          end
        end
      end
      local chain = Q0
      for _, md in ipairs(mods) do
        local prev = chain
        chain = function(px, pz) return md(prev, px, pz) end
      end
      local hf = chain
      -- ledgefinal2 (verifier final-r1 F1: Route 22's gutter (28..33,15),
      -- where the ledges' back bands meet a rock row, stayed a geometric V
      -- -- the band left its edge at the ramp's own slope, the rock's soft
      -- foot rose in one 32 deg lattice facet: 64 deg between them): a band
      -- edge toward a ROCK gets a FLAT FOOT -- the band's slope across the
      -- edge, s, is cancelled there (h - w s D u (1 - u)^2, u = d / D:
      -- level at the edge, no change from D on, C1 at both; never below the
      -- base) with more cuts near the edge (a filling edge three, a trough
      -- one), and the rock's soft side rounds wider, fine cuts at its foot
      -- (pass 3r): the hill meets the rock round-bottomed. w fades the cancel
      -- out over D (a filling edge: the whole cell, as its fill ramps)
      -- toward a cell along the edge whose own edge there is not
      -- rock-banded (its surface is the plain band's there: no crack)
      -- (not a ledge cell's side toward its run's end: the rounded end
      -- morphs into the band there, cut for cut -- it keeps the band)
      local rkE
      if X.hbRock then
        for _, nm in ipairs({ "up", "down", "left", "right" }) do
          local side = ld and (((ld == "down" or ld == "up") and (nm == "left" or nm == "right")) or ((ld == "left" or ld == "right") and (nm == "up" or nm == "down")))
          if X.hbRock[nm] and e[nm] and not side then rkE = rkE or {}; rkE[#rkE + 1] = nm end
        end
      end
      for _, nm in ipairs(rkE or {}) do
        local prev = hf
        local hzE = nm == "up" or nm == "down" -- (the edge runs along x)
        local e0 = nm == "up" and z0 or (nm == "down" and z1 or (nm == "left" and x0 or x1))
        local sgn = (nm == "up" or nm == "left") and 1 or -1 -- (inward)
        local function cont(dx, dy)
          local Y = at(X.x + dx, X.y + dy)
          return Y and Y.hbRock and Y.hbRock[nm] and Y.hb and Y.hb.e[nm] and true or false
        end
        local cL = hzE and cont(-1, 0) or cont(0, -1)
        local cR = hzE and cont(1, 0) or cont(0, 1)
        local A0, A1 = hzE and x0 or z0, hzE and x1 or z1
        -- (a filling edge fades over the whole cell, as its fill ramps)
        local FL = (X.rkFill and X.rkFill[nm]) and 1 or D
        local sc = {}
        hf = function(px, pz)
          local h = prev(px, pz)
          local d = ((hzE and pz or px) - e0) * sgn
          if d >= D or d <= 0 then return h end
          local a = hzE and px or pz
          local w = (cL and 1 or S((a - A0) / FL)) * (cR and 1 or S((A1 - a) / FL))
          if w <= 0 then return h end
          -- (s per 1/2048 along the edge, taken at that step's own point:
          -- the same value wherever it is asked -- a shared edge's too)
          local ka = math.floor(a * 2048 + 0.5)
          local s = sc[ka]
          if not s then
            local aq = ka / 2048
            if hzE then s = (prev(aq, e0 + sgn * 1e-5) - prev(aq, e0)) * 1e5
            else s = (prev(e0 + sgn * 1e-5, aq) - prev(e0, aq)) * 1e5 end
            sc[ka] = s
          end
          local u = d / D
          return h - w * s * D * u * (1 - u) * (1 - u)
        end
      end
      -- cuts: the band's at every banded / banked side and dipped corner,
      -- rows (soft) where the band's height varies along its edge
      local xs, zs, softX, softZ = { gx0, gx1 }, { gz0, gz1 }, {}, {}
      local function band(t, from, sgn)
        for k = 1, NB do t[#t + 1] = from + sgn * D * BX[k] end
      end
      local bL = e.left or v[1] or v[4] or (bks and horiz and bks[-1])
      local bR = e.right or v[2] or v[3] or (bks and horiz and bks[1])
      local bU = e.up or v[1] or v[2] or (bks and not horiz and ld and bks[-1])
      local bD = e.down or v[3] or v[4] or (bks and not horiz and ld and bks[1])
      if bL then band(xs, x0, 1) end
      if bR then band(xs, x1, -1) end
      if bU then band(zs, z0, 1) end
      if bD then band(zs, z1, -1) end
      for _, nm in ipairs(rkE or {}) do
        -- (a filling edge: three rows by the edge; a trough: one -- budget)
        for _, f in ipairs((X.rkFill and X.rkFill[nm]) and { 0.035, 0.075, 0.25 } or { 0.05 }) do
          if nm == "up" then zs[#zs + 1] = z0 + D * f elseif nm == "down" then zs[#zs + 1] = z1 - D * f
          elseif nm == "left" then xs[#xs + 1] = x0 + D * f else xs[#xs + 1] = x1 - D * f end
        end
        -- (a filling edge's ramp across an end cell: grid lines on the
        -- rock's lattice -- its tent peak mid-cell among them)
        if X.rkFill and X.rkFill[nm] and not (grid.rkCont(X, nm, -1) and grid.rkCont(X, nm, 1)) then
          for _, f in ipairs({ 0.25, 0.5, 0.75 }) do
            if nm == "up" or nm == "down" then xs[#xs + 1] = x0 + f else zs[#zs + 1] = z0 + f end
          end
        end
      end
      local function soft(t, a0, a1, n) for j = 1, n - 1 do t[#t + 1] = a0 + (a1 - a0) * j / n end end
      local NR = C.LEDGE_BANK_ROWS or 4
      if ld then
        -- (the side band / shoulder: rows across the run, over the plane)
        local sides = horiz and (e.left or e.right or (bks and (bks[-1] or bks[1]))) or ((not horiz) and (e.up or e.down or (bks and (bks[-1] or bks[1]))))
        if sides then
          if horiz then soft(softZ, gz0, gz1, NR) else soft(softX, gx0, gx1, NR) end
        end
      else
        if (e.left and math.abs(rh[1] - rh[4]) > 1e-6) or (e.right and math.abs(rh[2] - rh[3]) > 1e-6) then soft(softZ, gz0, gz1, NR) end
        if (e.up and math.abs(rh[1] - rh[2]) > 1e-6) or (e.down and math.abs(rh[4] - rh[3]) > 1e-6) then soft(softX, gx0, gx1, NR) end
      end
      local function finish(t, sf, a0, a1)
        local out = {}
        for _, c in ipairs(t) do if c >= a0 - 1e-12 and c <= a1 + 1e-12 then out[#out + 1] = math.max(a0, math.min(a1, c)) end end
        for _, c in ipairs(sf) do
          local near = false
          for _, q in ipairs(out) do if math.abs(q - c) < 0.03 then near = true break end end
          if not near then out[#out + 1] = c end
        end
        table.sort(out)
        local r = {}
        for _, c in ipairs(out) do if #r == 0 or c - r[#r] > 1e-9 then r[#r + 1] = c end end
        r[1], r[#r] = a0, a1
        return r
      end
      xs, zs = finish(xs, softX, gx0, gx1), finish(zs, softZ, gz0, gz1)
      local ee = 1e-4
      local function nrm(px, pz)
        local xa, xb = math.max(gx0, px - ee), math.min(gx1, px + ee)
        local za, zb = math.max(gz0, pz - ee), math.min(gz1, pz + ee)
        local dx = (hf(xb, pz) - hf(xa, pz)) / (xb - xa)
        local dz = (hf(px, zb) - hf(px, za)) / (zb - za)
        return norm3({ -dx, 1, -dz })
      end
      local P = {}
      for i, px in ipairs(xs) do
        P[i] = {}
        for j, pz in ipairs(zs) do
          local n = nrm(px, pz)
          -- ledgefinal1 (verifier r3: the 90 deg V gutter where a ledge's
          -- back band meets a rock, Route 22 (29..33,15)): on an edge banded
          -- toward a rock the foot's normal loses its across-edge tilt -- the
          -- rock's soft foot (pass 3r) is level there too, so the trough
          -- shades as one round surface
          local rk = X.hbRock
          if rk and ((rk.up and pz == z0) or (rk.down and pz == z1) or (rk.left and px == x0) or (rk.right and px == x1)) then
            local horizE = (rk.up and pz == z0) or (rk.down and pz == z1)
            n = norm3({ horizE and n[1] or 0, n[2], horizE and 0 or n[3] })
          end
          P[i][j] = { { px, hf(px, pz), pz }, n }
        end
      end
      X.hg = { xs = xs, zs = zs, P = P, hf = hf, nrm = nrm, x0 = x0, z0 = z0, x1 = x1, z1 = z1 }
      if ld then
        -- ledgefinal1 (C): beside a smooth end the ground's art slides one
        -- texel back at the back line (faded in from the crown over 0.15 D,
        -- out toward the far edge -- the art never leaves the tile): the
        -- art's edge row at the crest (often a line) does not run down the
        -- back line beside the end, and the end's top art (the same slide,
        -- mirrored about the back line) meets it texel for texel.
        -- hg.uvp(px, pz) = the plan point whose art a point shows
        local shL, shR
        for sg = -1, 1, 2 do
          local side = horiz and (sg > 0 and "right" or "left") or (sg > 0 and "down" or "up")
          if (bks and bks[sg]) or (hb and hb.e[side]) then
            if sg < 0 then shL = true else shR = true end
          end
        end
        if shL or shR then
          local A0, A1, o = horiz and x0 or z0, horiz and x1 or z1, OUTC[ld]
          X.hg.uvp = function(px, pz)
            local a = horiz and px or pz
            local w = 0
            if shL then w = math.max(w, S((A0 + D - a) / (0.15 * D))) end
            if shR then w = math.max(w, S((a - (A1 - D)) / (0.15 * D))) end
            w = w * (1 - S((tIn(px, pz) - D) / (1 - D))) / 16
            return px - o[1] * w, pz - o[2] * w
          end
        end
      end
      grid.bandCells = grid.bandCells + 1
    end
    -- phase B: the welds. A boundary point strictly inside one of the
    -- cell's edges goes to the neighbour across it when that neighbour's
    -- own ground passes through it (a seam, not a step); a banked end's
    -- floor corner on the street edge too.
    local function reg(Z, p)
      if not Z then return end
      local h = grid.groundAt(Z, p[1], p[3])
      if h == nil or math.abs(h - p[2]) > 1e-6 then return end
      local l = grid.edgeSplits[Z]
      if not l then l = {}; grid.edgeSplits[Z] = l end
      l[#l + 1] = p
    end
    for _, X in ipairs(list) do
      local G = X.hg
      local x0, z0, x1, z1 = G.x0, G.z0, G.x1, G.z1
      for i, px in ipairs(G.xs) do
        for j, pz in ipairs(G.zs) do
          local onX = px == x0 and -1 or (px == x1 and 1 or 0)
          local onZ = pz == z0 and -1 or (pz == z1 and 1 or 0)
          if (onX ~= 0) ~= (onZ ~= 0) then
            reg(at(X.x + onX, X.y + onZ), G.P[i][j][1])
          end
        end
      end
      local ld = X.ledgeDir
      if ld then
        -- a smooth end's floor corner on the street edge (the rounded end's
        -- foot at the straight part's last station)
        local horiz = ld == "down" or ld == "up"
        local out = ({ down = { 0, 1 }, up = { 0, -1 }, left = { -1, 0 }, right = { 1, 0 } })[ld]
        local exitC = ({ down = z1, up = z0, left = x0, right = x1 })[ld]
        -- the straight curb's face foot at the grid's cuts along the run (the
        -- curb closure splits its straight part there): on the street's
        -- edge and the strip's
        do
          local A0, A1 = horiz and x0 or z0, horiz and x1 or z1
          local function run(sg)
            local q = at(X.x + (horiz and sg or 0), X.y + (horiz and 0 or sg))
            return q and ((q.ledgeDir or q.curbDir) == ld or q.cornerTo == X)
          end
          local s0, s1 = A0 + (run(-1) and 0 or D), A1 - (run(1) and 0 or D)
          local st = at(X.x + out[1], X.y + out[2])
          for _, c in ipairs(horiz and G.xs or G.zs) do
            if c > s0 + 1e-9 and c < s1 - 1e-9 then
              local p = { horiz and c or exitC, X.baseHgt, horiz and exitC or c }
              reg(st, p)
              local l = grid.edgeSplits[X]
              if not l then l = {}; grid.edgeSplits[X] = l end
              l[#l + 1] = p
            end
          end
        end
        for sg = -1, 1, 2 do
          local bk = X.ledgeBank and X.ledgeBank[sg]
          local side = horiz and (sg > 0 and "right" or "left") or (sg > 0 and "down" or "up")
          if bk or (X.hb and X.hb.e[side]) then
            local s = sg > 0 and ((horiz and x1 or z1) - D) or ((horiz and x0 or z0) + D)
            local px, pz = horiz and s or exitC, horiz and exitC or s
            reg(at(X.x + out[1], X.y + out[2]), { px, bk and bk.hE or X.baseHgt, pz })
            grid.bandEnds = grid.bandEnds + 1
          end
        end
      end
    end
  end
  grid.hillBands()
  -- ledgefinal2 (verifier final-r1 F2: Route 4's U corners read as folds --
  -- each plain hill cell's ground (a ramp quad, a ledge cell's plane, a
  -- corner curb's ground) was lit with ONE normal, so neighbouring hill
  -- faces of different slopes met in hard light steps, ~8 %): SMOOTH VERTEX
  -- NORMALS for that ground. grid.rampFaceN(Z) = the one normal a plain
  -- hill cell's ground had (the ground pass uses it); grid.vnAt(px, pz, h)
  -- = the normal the hill ground has at a point on it: where a banded
  -- neighbour's grid passes through it, that grid's normal (the banded
  -- side already shades smoothly: both sides now agree; where banded grids
  -- meet with different normals, their mean, on both); else the mean of
  -- the plain hill faces meeting there; nil where they all agree (nothing
  -- changes there) or the switch is off. Flat ground keeps its own normal,
  -- UP, and a hill's foot on it takes that normal (grid.isFlatAt). A
  -- banked end's cell and its hill path keep theirs (their floors and the
  -- rounded end's foot share the path's plane normal). No geometry
  -- changes. Cached per point.
  grid.rampFaceN = function(Z)
    local n = Z.rampFN
    if n then return n end
    local rh, x0, z0 = Z.rampH, Z.x + 0.0, Z.y + 0.0
    local x1, z1 = x0 + 1.0, z0 + 1.0
    local ld = Z.ledgeDir
    if ld then
      -- (the ledge cell's plane: the far edge's corners and the back line's
      -- points, as the ground pass builds them)
      local ex = ({ down = { 4, 3, 1, 2 }, up = { 1, 2, 4, 3 }, left = { 1, 4, 2, 3 }, right = { 2, 3, 1, 4 } })[ld]
      local P4 = { { x0, z0 }, { x1, z0 }, { x1, z1 }, { x0, z1 } }
      local Q, Hq = {}, {}
      for k = 1, 4 do Q[k], Hq[k] = { P4[k][1], P4[k][2] }, rh[k] end
      for k = 1, 2 do
        local e, fa = ex[k], ex[k + 2]
        local f = 1 - C.LEDGE_DEPTH
        Q[e] = { P4[fa][1] + (P4[e][1] - P4[fa][1]) * f, P4[fa][2] + (P4[e][2] - P4[fa][2]) * f }
        Hq[e] = rh[fa] + (rh[e] - rh[fa]) * f
      end
      n = faceNormal3({ Q[1][1], Hq[1], Q[1][2] }, { Q[4][1], Hq[4], Q[4][2] }, { Q[3][1], Hq[3], Q[3][2] })
    else
      n = faceNormal3({ x0, rh[1], z0 }, { x0, rh[4], z1 }, { x1, rh[3], z1 })
    end
    if n[2] < 0 then n = { -n[1], -n[2], -n[3] } end
    Z.rampFN = n
    return n
  end
  -- A hill's FOOT on flat ground (a plain walkable cell at the point's
  -- height touches it: grid.isFlatAt) takes the flat ground's normal, UP --
  -- the hill's light fades into the ground's, no step at the foot.
  grid.isFlatAt = function(Z, hv)
    return not Z.rampH and not Z.ledgeDir and not Z.curbDir and Z.walkable and not Z.isWater and not Z.isGrass
      and not Z.rock and Z.hgtSource ~= "fallback" and Z.hgt and math.abs(Z.hgt - hv) < 1e-6 or false
  end
  -- (a banded grid's own point: its stored normal -- else its function's)
  grid.hgNormalAt = function(G, px, pz, hv)
    local ax, bx, az, bz = G.xs[1], G.xs[#G.xs], G.zs[1], G.zs[#G.zs]
    local E = 1e-7
    if px < ax - E or px > bx + E or pz < az - E or pz > bz + E then return nil end
    -- (the grid's cut positions by value, built once)
    local XI, ZI = G.xi, G.zi
    if not XI then
      XI, ZI = {}, {}
      for i, c in ipairs(G.xs) do XI[c] = i end
      for j, c in ipairs(G.zs) do ZI[c] = j end
      G.xi, G.zi = XI, ZI
    end
    local ii, jj = XI[px], ZI[pz]
    if not (ii and jj) then
      ii, jj = nil, nil
      for i, c in ipairs(G.xs) do if math.abs(c - px) < 1e-9 then ii = i break end end
      if ii then for j, c in ipairs(G.zs) do if math.abs(c - pz) < 1e-9 then jj = j break end end end
    end
    if ii and jj then
      local P = G.P[ii][jj]
      if math.abs(P[1][2] - hv) < 1e-6 then return P[2] end
      return nil
    end
    local qx, qz = math.max(ax, math.min(bx, px)), math.max(az, math.min(bz, pz))
    if math.abs(G.hf(qx, qz) - hv) < 1e-6 then return G.nrm(qx, qz) end
    return nil
  end
  -- (mode nil: a plain face's corner -- nil where nothing changes; "loose":
  -- always a normal where any hill ground meets the point; "hg": a banded
  -- grid's own edge point -- the mean of the banded grids through it where
  -- they differ, else nil)
  grid.vnCache = {}
  grid.vnAt = function(px, pz, hv, mode)
    if C.LEDGE_END_BANK == false or indoor or cave then return nil end
    local key = (math.floor(px * 1e5 + 0.5) * 1e8 + math.floor(pz * 1e5 + 0.5)) * 3 + (mode == "loose" and 1 or (mode == "hg" and 2 or 0))
    local r = grid.vnCache[key]
    if r ~= nil then return r or nil end
    local E = 1e-7
    local hx, hy, hz, nh, h1, hsame = 0, 0, 0, 0, nil, true
    local fx, fy, fz, nf, same = 0, 0, 0, 0, true
    local f1
    local cx0, cx1, cz0, cz1 = math.floor(px - E), math.floor(px + E), math.floor(pz - E), math.floor(pz + E)
    -- (a banked end's cell or its hill path: kept as they are -- the
    -- rounded end's foot, its floor and the path share the path's plane
    -- normal, T13)
    for cx = cx0, cx1 do
      for cz = cz0, cz1 do
        local Z = at(cx, cz)
        if Z and (Z.ledgeBank or grid.bankPath[Z]) then
          grid.vnCache[key] = false
          return nil
        end
      end
    end
    -- (a hill's foot on flat ground: UP)
    for cx = cx0, cx1 do
      for cz = cz0, cz1 do
        local Z = at(cx, cz)
        if Z and grid.isFlatAt(Z, hv) then
          grid.vnCache[key] = UP
          return UP
        end
      end
    end
    for cx = cx0, cx1 do
      for cz = cz0, cz1 do
        local Z = at(cx, cz)
        if Z and Z.rampH and Z.baseHgt then
          local G = Z.hg
          if G then
            local n = grid.hgNormalAt(G, px, pz, hv)
            if n then
              if h1 and (math.abs(n[1] - h1[1]) > 1e-9 or math.abs(n[2] - h1[2]) > 1e-9 or math.abs(n[3] - h1[3]) > 1e-9) then hsame = false end
              h1 = h1 or n
              hx, hy, hz, nh = hx + n[1], hy + n[2], hz + n[3], nh + 1
            end
          else
            local ld, inside = Z.ledgeDir, true
            if ld then
              local t = ld == "down" and (cz + 1 - pz) or (ld == "up" and (pz - cz) or (ld == "left" and (px - cx) or (cx + 1 - px)))
              inside = t >= C.LEDGE_DEPTH - E
            end
            if inside then
              local rh = Z.rampH
              local ux, uz = math.max(0, math.min(1, px - cx)), math.max(0, math.min(1, pz - cz))
              local h = (rh[1] * (1 - ux) + rh[2] * ux) * (1 - uz) + (rh[4] * (1 - ux) + rh[3] * ux) * uz
              if math.abs(h - hv) < 1e-6 then
                local n = grid.rampFaceN(Z)
                if f1 and (n[1] ~= f1[1] or n[2] ~= f1[2] or n[3] ~= f1[3]) then same = false end
                f1 = f1 or n
                fx, fy, fz, nf = fx + n[1], fy + n[2], fz + n[3], nf + 1
              end
            end
          end
        end
      end
    end
    if nh > 0 then
      if not hsame then r = norm3({ hx, hy, hz })
      elseif mode == "hg" then r = false
      else r = h1 end
    elseif mode == "hg" then r = false
    elseif nf > 1 and not same then r = norm3({ fx, fy, fz })
    elseif mode == "loose" and nf > 0 then r = f1
    else r = false end
    grid.vnCache[key] = r
    return r or nil
  end
  -- a quad's four corner normals (P[i] = { point, uv }; n = the face's
  -- own): nil when none changes (the caller keeps its one-normal quad)
  grid.quadVN = function(P, n)
    local N, any = {}, false
    for i = 1, 4 do
      local p = P[i][1]
      local v = grid.vnAt(p[1], p[3], p[2])
      if v then any = true end
      N[i] = v or n
    end
    return any and N or nil
  end
  -- a banded cell's ground: its grid, each quad split on the diagonal
  -- closer to the surface, the boundary quads fanned at welded points
  grid.drawGrid = function(X, guv)
    local G = X.hg
    local xs, zs, P = G.xs, G.zs, G.P
    local x0, z0 = G.x0, G.z0
    local u0, v0, du, dv = guv[1], guv[2], guv[3] - guv[1], guv[4] - guv[2]
    local sp = grid.edgeSplits[X]
    local nx, nz = #xs, #zs
    -- one shared vertex table per grid point (CONTRACT_V2: lists may hold
    -- the same table several times) -- JIT-off, allocation is the cost
    local V = {}
    -- (ledgefinal2: a point on the cell's own edge where the hill's foot
    -- meets flat ground: the ground's normal, UP -- grid.vnAt)
    -- (and where banded grids meet with different normals, their mean:
    -- both sides agree)
    local ex0, ez0 = X.x, X.y
    local fixedX = X.ledgeBank or grid.bankPath[X]
    local function edgeN(p)
      if C.LEDGE_END_BANK == false or indoor or cave or fixedX then return nil end
      local onX = p[1] == ex0 and -1 or (p[1] == ex0 + 1 and 1 or 0)
      local onZ = p[3] == ez0 and -1 or (p[3] == ez0 + 1 and 1 or 0)
      if onX == 0 and onZ == 0 then return nil end
      if onX == 0 or onZ == 0 then
        -- (inside an edge: only the cell across it can change the point)
        local A = at(X.x + onX, X.y + onZ)
        if not A or A.ledgeBank or grid.bankPath[A] then return nil end
        if grid.isFlatAt(A, p[2]) then return UP end
        if not A.hg then return nil end
      end
      return grid.vnAt(p[1], p[3], p[2], "hg")
    end
    for i = 1, nx do
      local row, Pi = {}, P[i]
      for j = 1, nz do
        local p, n = Pi[j][1], Pi[j][2]
        if i == 1 or i == nx or j == 1 or j == nz then n = edgeN(p) or n end
        local qx, qz = p[1], p[3]
        if G.uvp then qx, qz = G.uvp(qx, qz) end
        row[j] = newV(p[1], p[2], p[3], u0 + (qx - x0) * du, v0 + (qz - z0) * dv, n[1], n[2], n[3])
      end
      V[i] = row
    end
    local function uvOf(q)
      local qx, qz = q[1], q[3]
      if G.uvp then qx, qz = G.uvp(qx, qz) end
      return { u0 + (qx - x0) * du, v0 + (qz - z0) * dv }
    end
    local function nOf(q) return edgeN(q) or G.nrm(q[1], q[3]) end
    local function wrap(v) return { { v[1], v[2], v[3] }, { v[4], v[5] }, { v[6], v[7], v[8] } } end
    local function put(a, b, c) -- wound so the geometric normal points up
      local e1x, e1z = b[1] - a[1], b[3] - a[3]
      local e2x, e2z = c[1] - a[1], c[3] - a[3]
      local n = #opaque
      if e1z * e2x - e1x * e2z < 0 then opaque[n + 1], opaque[n + 2], opaque[n + 3] = a, c, b
      else opaque[n + 1], opaque[n + 2], opaque[n + 3] = a, b, c end
    end
    -- the welded points that are not grid points of this cell, each on the
    -- boundary quad whose outer edge holds it (most quads get none)
    local extra
    if sp then
      local x1, z1 = G.x1, G.z1
      local function slot(cuts, v)
        for k = 1, #cuts - 1 do
          if math.abs(cuts[k] - v) < 1e-7 or math.abs(cuts[k + 1] - v) < 1e-7 then return nil end
          if v > cuts[k] and v < cuts[k + 1] then return k end
        end
        return nil
      end
      for _, q in ipairs(sp) do
        local qi, qj
        if q[1] == xs[1] or q[1] == xs[nx] then
          qj = slot(zs, q[3]); if qj then qi = q[1] == xs[1] and 1 or nx - 1 end
        elseif q[3] == zs[1] or q[3] == zs[nz] then
          qi = slot(xs, q[1]); if qi then qj = q[3] == zs[1] and 1 or nz - 1 end
        elseif math.abs(q[1] - xs[1]) < 1e-9 or math.abs(q[1] - xs[nx]) < 1e-9 or math.abs(q[3] - zs[1]) < 1e-9 or math.abs(q[3] - zs[nz]) < 1e-9 then
          -- (float-near a region edge: take it the slow way)
          qi, qj = 1, 1
          for k = 1, nx - 1 do if q[1] >= xs[k] - 1e-9 and q[1] <= xs[k + 1] + 1e-9 then qi = k end end
          for k = 1, nz - 1 do if q[3] >= zs[k] - 1e-9 and q[3] <= zs[k + 1] + 1e-9 then qj = k end end
        end
        if qi and qj then
          extra = extra or {}
          local kq = qi * 4096 + qj
          local l = extra[kq]
          if not l then l = {}; extra[kq] = l end
          l[#l + 1] = q
        end
      end
    end
    local miss = 0
    for i = 1, nx - 1 do
      local Vi, Vj = V[i], V[i + 1]
      for j = 1, nz - 1 do
        local a, b, c, d = Vi[j], Vj[j], Vj[j + 1], Vi[j + 1]
        -- the diagonal closer to the surface (a planar quad: either)
        local s1, s2 = a[2] + c[2], b[2] + d[2]
        local diagAC = true
        if math.abs(s1 - s2) > 1e-9 then
          local hc = G.hf((xs[i] + xs[i + 1]) * 0.5, (zs[j] + zs[j + 1]) * 0.5)
          diagAC = math.abs(s1 * 0.5 - hc) <= math.abs(s2 * 0.5 - hc)
        end
        local ex = extra and extra[i * 4096 + j]
        if ex then
          local A, B, Cc, Dd = wrap(a), wrap(b), wrap(c), wrap(d)
          if diagAC then
            miss = miss + grid.fanTri(opaque, { A, B, Cc }, ex, uvOf, nOf, 0.05) + grid.fanTri(opaque, { A, Cc, Dd }, ex, uvOf, nOf, 0.05)
          else
            miss = miss + grid.fanTri(opaque, { A, B, Dd }, ex, uvOf, nOf, 0.05) + grid.fanTri(opaque, { B, Cc, Dd }, ex, uvOf, nOf, 0.05)
          end
        elseif diagAC then put(a, b, c); put(a, c, d)
        else put(a, b, d); put(b, c, d) end
      end
    end
    grid.weldMiss = (grid.weldMiss or 0) + miss
  end
  -- the ground's polyline along one edge of a cell (plan points a -> b):
  -- { f (0..1 from a), height } -- a grid's points on that edge, else the
  -- corners (a ledge plane's edge only over its region: points outside
  -- are not listed)
  grid.edgePoly = function(Z, ax, az, bx, bz)
    local l2 = (bx - ax) * (bx - ax) + (bz - az) * (bz - az)
    local out = {}
    if Z.hg then
      local G = Z.hg
      for i, px in ipairs(G.xs) do
        for j, pz in ipairs(G.zs) do
          local qx, qz = px - ax, pz - az
          if math.abs(qx * (bz - az) - qz * (bx - ax)) < 1e-9 then
            local f = (qx * (bx - ax) + qz * (bz - az)) / l2
            if f > -1e-9 and f < 1 + 1e-9 then out[#out + 1] = { f, G.P[i][j][1][2] } end
          end
        end
      end
      -- (the neighbours' welded points on this edge: the drawn edge has them)
      for _, q in ipairs(grid.edgeSplits[Z] or {}) do
        local qx, qz = q[1] - ax, q[3] - az
        if math.abs(qx * (bz - az) - qz * (bx - ax)) < 1e-7 then
          local f = (qx * (bx - ax) + qz * (bz - az)) / l2
          if f > 1e-9 and f < 1 - 1e-9 then out[#out + 1] = { f, q[2] } end
        end
      end
      table.sort(out, function(p, q) return p[1] < q[1] end)
    end
    return out
  end
  -- r13c: the M1 skirt on one edge of a cell where it or its neighbour is a
  -- grid -- per piece between both sides' polyline points, where this side
  -- is higher (the r12 rules: nothing on a ledge cell's exit edge; its side
  -- edges only behind the curb's back line -- the whole edge at a banded
  -- free end, whose strip under the curb lies at the base)
  grid.polySkirt = function(cell, nc, dname, x0, z0, x1, z1, uv)
    local ld = cell.ledgeDir
    if ld == dname then return end
    local ax, az, bx, bz
    if dname == "down" then ax, az, bx, bz = x0, z1, x1, z1
    elseif dname == "up" then ax, az, bx, bz = x1, z0, x0, z0
    elseif dname == "left" then ax, az, bx, bz = x0, z0, x0, z1
    else ax, az, bx, bz = x1, z1, x1, z0 end
    local D = C.LEDGE_DEPTH
    local f0, f1, fD, stripB = 0, 1, nil, nil
    if ld and OPP[ld] ~= dname then
      local o = ({ down = { 0, 1 }, up = { 0, -1 }, left = { -1, 0 }, right = { 1, 0 } })[ld]
      local bExit = (bx - (x0 + 0.5)) * o[1] + (bz - (z0 + 0.5)) * o[2] > 0
      if cell.hb and cell.hb.e[dname] then
        fD, stripB = bExit and 1 - D or D, bExit
      elseif bExit then f1 = 1 - D else f0 = D end
    end
    local polyC = grid.edgePoly(cell, ax, az, bx, bz)
    local polyN = nc.hg and grid.edgePoly(nc, ax, az, bx, bz) or nil
    local fs = { f0, f1 }
    if fD then fs[#fs + 1] = fD end
    for _, pl in ipairs({ polyC, polyN or {} }) do
      for _, q in ipairs(pl) do if q[1] > f0 + 1e-9 and q[1] < f1 - 1e-9 then fs[#fs + 1] = q[1] end end
    end
    table.sort(fs)
    local function interp(pl, f)
      if #pl == 0 then return nil end
      if f <= pl[1][1] then return f >= pl[1][1] - 1e-7 and pl[1][2] or nil end
      for i = 1, #pl - 1 do
        if f <= pl[i + 1][1] then
          local a, b = pl[i], pl[i + 1]
          local w = b[1] - a[1]
          return w > 1e-12 and a[2] + (b[2] - a[2]) * (f - a[1]) / w or b[2]
        end
      end
      return f <= pl[#pl][1] + 1e-7 and pl[#pl][2] or nil
    end
    local function hC(f)
      if stripB ~= nil and ((stripB and f > fD + 1e-9) or (not stripB and f < fD - 1e-9)) then return cell.baseHgt end
      return interp(polyC, f) or grid.groundAt(cell, ax + (bx - ax) * f, az + (bz - az) * f)
    end
    local function hN(f)
      local h = polyN and interp(polyN, f)
      if h then return h end
      if nc.ledgeDir then
        -- (a ledge neighbour's strip part lies at its base)
        local px, pz = ax + (bx - ax) * f, az + (bz - az) * f
        local o = ({ down = { 0, 1 }, up = { 0, -1 }, left = { -1, 0 }, right = { 1, 0 } })[nc.ledgeDir]
        local t = -((px - (nc.x + 0.5)) * o[1] + (pz - (nc.y + 0.5)) * o[2]) + 0.5
        if t < D - 1e-9 then return nc.baseHgt end
      end
      return grid.groundAt(nc, ax + (bx - ax) * f, az + (bz - az) * f)
    end
    local n = dname == "down" and { 0, 0, 1 } or (dname == "up" and { 0, 0, -1 } or (dname == "left" and { -1, 0, 0 } or { 1, 0, 0 }))
    local suv = nc.isWater and not cell.caveRingSupport and subRectV(uv, C.WATER_BANK_V0, 1) or uv
    local lastF
    for i = 1, #fs - 1 do
      local fa, fb = fs[i], fs[i + 1]
      if fb - fa > 1e-9 then
        local ta, tb, ba, bb = hC(fa), hC(fb), hN(fa), hN(fb)
        if ta and tb and ba and bb and (ta > ba + EPS or tb > bb + EPS) then
          ta, tb = math.max(ta, ba), math.max(tb, bb)
          local pax, paz = ax + (bx - ax) * fa, az + (bz - az) * fa
          local pbx, pbz = ax + (bx - ax) * fb, az + (bz - az) * fb
          local ua, ub = suv[1] + (suv[3] - suv[1]) * fa, suv[1] + (suv[3] - suv[1]) * fb
          quadN(opaque, pax, ba, paz, ua, suv[4], pbx, bb, pbz, ub, suv[4],
            pbx, tb, pbz, ub, suv[2], pax, ta, paz, ua, suv[2], n[1], n[2], n[3])
        end
      end
    end
  end

  -- Native657 is plain moss top;665 is projected vertical moss face.
  -- Gate this exact island cap-role correction independently of support.
  if grid.caveNativeArt and input.mapId=="FR_CERULEAN_CAVE_1F" and input.pair=="general__rom_082d4e54" and grid.cavePlatforms and W==40 and H==24 then
    local h=0
    for _,layer in ipairs({'under','over'})do local t=atlas.texels(657,layer)
      for i=1,256 do h=(h*33+((t and t[i])or -1)+2)%4294967291 end
    end
    grid.cavePlainMossCap=h==2617043223
  end

  -- Isolated native shoreline-base interpretation. No support or collision
  -- changes: native visible bank pixels anchor the foot; projection-hidden
  -- north banks are reconstructed with oriented native straight/corner art.
  if grid.caveNativeArt and input.mapId=="FR_CERULEAN_CAVE_1F" and input.pair=="general__rom_082d4e54" and W==40 and H==24 then
    local active=false
    for yy=0,H-1 do for xx=0,W-1 do if at(xx,yy).caveRingSupport then active=true end end end
    if active then
    local guards={[288]=1456845720,[289]=3975647857,[291]=2433546994,[296]=3806195955,[297]=2928761683,[298]=3509549977,[300]=283304114,[304]=181785145,[305]=1573530370}
    for mid,need in pairs(guards)do
      local h=0
      for _,layer in ipairs({'under','over'})do local t=atlas.texels and atlas.texels(mid,layer)
        for i=1,256 do h=(h*33+((t and t[i])or -1)+2)%4294967291 end
      end
      if h~=need then active=false end
    end
    local water
    for yy=0,H-1 do for xx=0,W-1 do local c=at(xx,yy);if c.caveShore then if water and water~=c.caveShore.south then active=false end;water=c.caveShore.south end end end
    if water~=.6 then active=false end
    if active then
      local brown={[12424332]=true,[14599589]=true,[5913154]=true,[9726827]=true,[8079946]=true}
      local landCells={}
      for yy=0,H-1 do for xx=0,W-1 do local c=at(xx,yy)
        local yes=c.caveRingSupport or c.caveShore
        if not yes and not c.walkable and not c.isWater and c.hgt==1 and compOf(c) then
          for _,d in ipairs(DIRS)do local n=at(xx+d.dx,yy+d.dy);if n and n.caveRingSupport then yes=true end end
        end
        if yes then landCells[yy*W+xx]=c end
      end end
      local function land(px,pz)
        local x,z=math.floor(px/16),math.floor(pz/16)
        if x<0 or z<0 or x>=W or z>=H then return false end
        local c=landCells[z*W+x];if not c then return false end
        if c.caveShore then local i=(pz-z*16)*16+px-x*16+1;return c.caveShore.shore16:sub(i,i)=='1' end
        return true
      end
      local tex={};for mid in pairs(guards)do tex[mid]=atlas.texels(mid,'under')end
      local pixels={};local function key(x,z)return z*W*16+x end
      local function put(px,pz,mid,u,v,native)
        local rgb=tex[mid] and tex[mid][v*16+u+1]
        if brown[rgb] then pixels[key(px,pz)]={x=px,z=pz,mid=mid,u=u,v=v,native=native};return true end
      end
      for z=0,H*16-1 do if z%16==0 then Y()end;for x=0,W*16-1 do
        if not land(x,z)then
          local c=at(math.floor(x/16),math.floor(z/16))
          if c and (c.isWater or c.caveShore)then
            local own=tex[c.mid];local u,v=x%16,z%16
            local distance,dir
            for n=1,5 do
              if land(x,z-n)then distance,dir=n,'N';break
              elseif land(x+n,z)then distance,dir=n,'E';break
              elseif land(x,z+n)then distance,dir=n,'S';break
              elseif land(x-n,z)then distance,dir=n,'W';break end
            end
            if distance then
              if own and brown[own[v*16+u+1]]then put(x,z,c.mid,u,v,true)
              elseif dir=='N'then put(x,z,291,u,distance-1,false)
              elseif dir=='S'then put(x,z,291,15-u,distance-1,false)
              elseif dir=='W'then put(x,z,298,distance-1,v,false)
              elseif dir=='E'then put(x,z,300,16-distance,v,false)end
            else
              -- Original small corner caps join exposed cardinal bank runs.
              for dz=1,4 do for dx=1,4 do
                if land(x-dx,z-dz)then put(x,z,305,dx-1,dz-1,false)
                elseif land(x+dx,z-dz)then put(x,z,304,16-dx,dz-1,false)
                elseif land(x-dx,z+dz)then put(x,z,304,16-dx,dz-1,false)
                elseif land(x+dx,z+dz)then put(x,z,305,dx-1,dz-1,false)end
              end end
            end
          end
        end
      end end
      if deps.debugGrid then grid.caveFootAudit=pixels end
      grid.caveFootPixels=0;grid.caveFootNative=0;grid.caveFootWater=water
      for _,p in pairs(pixels)do
        grid.caveFootPixels=grid.caveFootPixels+1;if p.native then grid.caveFootNative=grid.caveFootNative+1 end
      end
      -- Replace only the existing water-height surface, rather than placing
      -- a raised overlay across the exact lower-water support in mixed tiles.
      -- This horizontal base ledge joins the primary wall at its .6 foot.
      local plain=hQuad
      hQuad=function(list,x0,z0,x1,z1,y,uv,n)
        if list~=opaque or y~=water then return plain(list,x0,z0,x1,z1,y,uv,n)end
        local a,b,c,d=math.floor(x0*16+.5),math.floor(z0*16+.5),math.floor(x1*16+.5),math.floor(z1*16+.5)
        if math.abs(a/16-x0)>1e-8 or math.abs(b/16-z0)>1e-8 or math.abs(c/16-x1)>1e-8 or math.abs(d/16-z1)>1e-8 then return plain(list,x0,z0,x1,z1,y,uv,n)end
        local found=false
        for pz=b,d-1 do for px=a,c-1 do if pixels[key(px,pz)]then found=true;break end end;if found then break end end
        if not found then return plain(list,x0,z0,x1,z1,y,uv,n)end
        for pz=b,d-1 do local px=a
          while px<c do local p=pixels[key(px,pz)];local stop=px+1;local rr
            if p then rr=subRect(underRect(p.mid),p.u/16,p.v/16,(p.u+1)/16,(p.v+1)/16)
            else
              while stop<c and not pixels[key(stop,pz)]do stop=stop+1 end
              rr=subRect(uv,(px-a)/(c-a),(pz-b)/(d-b),(stop-a)/(c-a),(pz+1-b)/(d-b))
            end
            plain(list,px/16,pz/16,stop/16,(pz+1)/16,y,rr,n);px=stop
          end
        end
      end
    end
    end
  end

  function grid.drawCaveShore(c)
    if c.caveShoreDrawn then return end;c.caveShoreDrawn=true
    local sh=c.caveShore;local ur,ov=underRect(c.mid),overRect(c.mid);local wall=underRect(665)
    local function land(px,pz)
      local nx,nz=math.floor(px/16),math.floor(pz/16)
      local n=at(nx,nz);if not n then return false end
      if n.caveShore then local i=(pz-nz*16)*16+(px-nx*16)+1;return n.caveShore.shore16:sub(i,i)=="1" end
      return (n.caveRingSupport or (not n.walkable and not n.isWater and compOf(n) and n.hgt==1)) and true or false
    end
    for py=0,15 do
      local px=0
      while px<16 do
        local yes=land(c.x*16+px,c.y*16+py);local stop=px+1
        while stop<16 and land(c.x*16+stop,c.y*16+py)==yes do stop=stop+1 end
        local rr=subRect(yes and ov or ur,px/16,py/16,stop/16,(py+1)/16)
        hQuad(yes and cutoutOver or opaque,c.x+px/16,c.y+py/16,c.x+stop/16,c.y+(py+1)/16,yes and sh.north or sh.south,rr)
        px=stop
      end
      for px=0,15 do if land(c.x*16+px,c.y*16+py)then
        for _,d in ipairs(DIRS)do if not land(c.x*16+px+d.dx,c.y*16+py+d.dy)then
          local x0,z0=c.x+px/16,c.y+py/16;local x1,z1=x0+1/16,z0+1/16
          local a=(d.dx==0 and px or py)/16
          faceQuad(opaque,d.name,x0,x1,z0,z1,sh.south,sh.north,subRect(wall,a,0,a+1/16,1))
        end end
      end end
    end
  end

  -- Exact Route12 art belongs to one architectural unit. Physics stays native.
  grid.route12Prepare=function()
    for _,comp in ipairs(compList)do
      if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeRoute12Exterior
          and comp.minX==13 and comp.maxX==15 and comp.minY==16 and comp.maxY==21
          and comp.groundY==.75 and comp.wallTopY==3.75 and comp.wallRows==3
          and C.WALL_ROW_UNIT==1 and C.FLAT_ROOF_PARAPET==.25 then
        local expected={'statue','fence','fence','rock','fence'};local valid=true
        for _,x in ipairs{12,16}do for y=17,21 do local c=at(x,y)
          if not c or c.propShape~=expected[y-16]or c.isTreeArt or c.isDoor then valid=false end
        end end
        if valid then
          grid.route12Owner=comp
          for _,x in ipairs{12,16}do for y=17,21 do at(x,y).nativeRoute12Exterior=comp end end
        end
      end
    end
  end
  grid.route12Prepare()
  grid.route12Begin=function(comp)
    if comp~=grid.route12Owner then return end
    comp.route12Saved={minX=comp.minX,maxX=comp.maxX,overhang=comp.overhang,endArt=comp.endArt,cells={},marks={#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed}}
    for _,x in ipairs{12,16}do for y=16,21 do local c=at(x,y)
      comp.route12Saved.cells[#comp.route12Saved.cells+1]={c,c.compId,c.overhangOf}
      c.compId=comp.id;c.overhangOf=nil
    end end
    comp.minX=12;comp.maxX=16;comp.overhang=false;comp.endArt=nil
  end
  grid.route12End=function(comp,info)
    local s=comp.route12Saved;if not s then return end
    grid.route12Door(comp)
    grid.route12Repeat(comp,info)
    for _,r in ipairs(s.cells)do r[1].compId=r[2];r[1].overhangOf=r[3]end
    comp.minX=s.minX;comp.maxX=s.maxX;comp.overhang=s.overhang;comp.endArt=s.endArt;comp.route12Saved=nil
  end

  -- The native opening spans two cells, while only its central cell is a warp.
  -- Move its continuous opening/stair art, preserving UVs and the canopy.
  -- Authored reverse entrance: approved south art with flush outer corners.
  grid.route12Repeat=function(comp,info)
    if C.DOOR_INSET~=.12 or C.FACADE_OVER_LIFT~=.004 then return end
    local marks=comp.route12Saved.marks
    local lo,hi=.75,3.75
    local function clip(poly,k,bound,positive)
      local out={}
      for i,a in ipairs(poly)do local b=poly[i%#poly+1]
        local da=(a[k]-bound)*(positive and 1 or -1);local db=(b[k]-bound)*(positive and 1 or -1)
        if da>=-1e-10 then out[#out+1]=a end
        if da*db<0 then local t=da/(da-db);local v={};for key,value in pairs(a)do v[key]=value end;for j=1,8 do v[j]=a[j]+(b[j]-a[j])*t end;out[#out+1]=v end
      end;return out
    end
    local function append(out,p)
      for i=2,#p-1 do local a,b,c=p[1],p[i],p[i+1]
        local x,y,z=b[1]-a[1],b[2]-a[2],b[3]-a[3];local u,v,w=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        local dot=(y*w-z*v)*a[6]+(z*u-x*w)*a[7]+(x*v-y*u)*a[8]
        if math.abs(dot)>1e-12 then if dot<0 then b,c=c,b end;out[#out+1]=a;out[#out+1]=b;out[#out+1]=c end
      end
    end
    local function inBounds(p,x0,x1,z0,z1)
      for _,v in ipairs(p)do if v[1]<x0-1e-8 or v[1]>x1+1e-8 or v[2]<lo-1e-8 or v[2]>hi+1e-8 or v[3]<z0-1e-8 or v[3]>z1+1e-8 then return false end end;return true
    end
    local total={removed=0,added=0,southCopied=0,sideExtensions=0}
    for k,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do
      local donors,kept,sides={},{},{}
      for i=marks[k]+1,#list,3 do local p={list[i],list[i+1],list[i+2]};local a=p[1]
        local front=a[8]>.99 and inBounds(p,12,17,21.88,22.01)
        local join=(math.abs(a[6])>.99 or math.abs(a[7])>.99)and inBounds(p,13.5,15.5,21.88,22.001)and a[2]<=1.9375+1e-8
        if front or join then donors[#donors+1]=p;total.southCopied=total.southCopied+1 end
        local rear=a[8]<-.99 and ((inBounds(p,13,16,16,16))or inBounds(p,12,13,17,17)or inBounds(p,16,17,17,17))
        -- The old one-cell returns become internal when the entrance is flush.
        local fold=math.abs(a[6])>.99 and (inBounds(p,13,13,16,17)or inBounds(p,16,16,16,17))
        if rear or fold then total.removed=total.removed+1 else kept[#kept+1]=p end
        -- Extend each existing outer masonry wall by one unchanged source course.
        if math.abs(a[6])>.99 and (inBounds(p,12,12,17,22)or inBounds(p,17,17,17,22))then
          local q=clip(clip(p,3,17,true),3,18,false)
          local moved={};for _,v in ipairs(q)do local a={};for key,value in pairs(v)do a[key]=value end;a[3]=v[3]-1;moved[#moved+1]=a end
          sides[#sides+1]=moved
        end
      end
      local out={};for _,p in ipairs(kept)do for _,v in ipairs(p)do out[#out+1]=v end end
      -- Keep approved donor proportions and original split vertices on one front plane.
      for _,p in ipairs(donors)do for _,interval in ipairs{{12,13},{13,16},{16,17}}do
        local q=clip(clip(p,1,interval[1],true),1,interval[2],false)
        local plane=16
        local transformed={}
        for _,v in ipairs(q)do local a={};for key,value in pairs(v)do a[key]=value end
          a[1]=29-v[1]
          a[3]=plane+22-v[3];a[6]=-v[6];a[8]=-v[8];transformed[#transformed+1]=a
        end
        local before=#out;append(out,transformed);total.added=total.added+(#out-before)/3
      end end
      for _,p in ipairs(sides)do local before=#out;append(out,p);total.sideExtensions=total.sideExtensions+(#out-before)/3 end
      for i=#list,marks[k]+1,-1 do list[i]=nil end;for _,v in ipairs(out)do list[#list+1]=v end
    end
    grid.route12RepeatStats=total
    assert(info and info.nativeRoute12Exterior,'reverse entrance metadata owner')
    local south=assert(info.doors and info.doors[1]);local north={};for k,v in pairs(south)do north[k]=v end
    north.x=14;north.z=15;north.wx=14.5;north.wz=38-south.wz;north.face='north';north.nativePortal=true
    info.doors[#info.doors+1]=north
    info.rearReconstruction='approved south entrance artwork repeated on flush rear face; native outer masonry extended to entrance'
  end

  grid.route12Door=function(comp)
    local marks=comp.route12Saved.marks
    if C.DOOR_INSET~=.12 then return end
    local lo,hi,zf,zr=.75,1.9375,22,21.88
    local function clip(poly,k,bound,positive)
      local out={}
      for i,a in ipairs(poly)do
        local b=poly[i%#poly+1];local da=(a[k]-bound)*(positive and 1 or -1);local db=(b[k]-bound)*(positive and 1 or -1)
        if da>=0 then out[#out+1]=a end
        if (da<0 and db>0)or(da>0 and db<0)then
          local t=da/(da-db);local v={};for key,value in pairs(a)do v[key]=value end
          for j=1,8 do v[j]=a[j]+(b[j]-a[j])*t end;out[#out+1]=v
        end
      end
      return out
    end
    local function append(out,p)
      for i=2,#p-1 do
        local a,b,c=p[1],p[i],p[i+1]
        local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
        local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        if (uy*vz-uz*vy)^2+(uz*vx-ux*vz)^2+(ux*vy-uy*vx)^2>1e-18 then out[#out+1]=a;out[#out+1]=b;out[#out+1]=c end
      end
    end
    for k,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do
      local out={}
      for i=marks[k]+1,#list,3 do
        local p={list[i],list[i+1],list[i+2]};local a=p[1]
        local front=a[8]>.99;local oldJoin=(math.abs(a[6])>.99 or a[7]<-.99)
        local valid=front or oldJoin
        for _,v in ipairs(p)do
          valid=valid and v[1]>=13-1e-8 and v[1]<=16+1e-8 and v[3]>=zr-1e-8 and v[3]<=zf+C.FACADE_OVER_LIFT+1e-8
          if front then valid=valid and v[3]>=zf-1e-8 end
          if oldJoin then valid=valid and v[1]>=14-1e-8 and v[1]<=15+1e-8 and v[2]<=1.75+1e-8 end
        end
        local minX,maxX,minY,maxY=math.huge,-math.huge,math.huge,-math.huge
        for _,v in ipairs(p)do minX=math.min(minX,v[1]);maxX=math.max(maxX,v[1]);minY=math.min(minY,v[2]);maxY=math.max(maxY,v[2])end
        valid=valid and maxX>13.5 and minX<15.5 and maxY>lo and minY<hi
        if valid then
          for _,edge in ipairs{{1,13.5,true},{1,15.5,false},{2,lo,true},{2,hi,false}}do
            local outside=false;for _,v in ipairs(p)do if (v[edge[1]]-edge[2])*(edge[3] and 1 or -1)<-1e-10 then outside=true end end
            if outside then append(out,clip(p,edge[1],edge[2],not edge[3]))end;p=clip(p,edge[1],edge[2],edge[3])
          end
          if front then
            local moved={};for _,v in ipairs(p)do local n={};for key,value in pairs(v)do n[key]=value end;n[3]=v[3]-.12;moved[#moved+1]=n end
            append(out,moved)
          end
        else append(out,p)end
      end
      for i=#list,marks[k]+1,-1 do list[i]=nil end
      for _,v in ipairs(out)do list[#list+1]=v end
    end
    -- Returns sample the genuine gray boundary of the native opening.
    local r=subRect(underRect(400),7.5/16,4.5/16,7.5/16,4.5/16)
    local function face(points,n)
      local p={};for _,v in ipairs(points)do p[#p+1]={v,{r[1],r[2]}}end;fanN(opaque,p,n)
    end
    face({{13.5,lo,zr},{13.5,lo,zf},{13.5,hi,zf},{13.5,hi,zr}},{1,0,0})
    face({{15.5,lo,zf},{15.5,lo,zr},{15.5,hi,zr},{15.5,hi,zf}},{-1,0,0})
    face({{13.5,hi,zr},{13.5,hi,zf},{15.5,hi,zf},{15.5,hi,zr}},DOWN)
    -- Preserve the old central stair plane; close its newly joined half-cell feet.
    face({{13.5,lo,zr},{14,lo,zr},{14,lo,zf},{13.5,lo,zf}},UP)
    face({{15,lo,zr},{15.5,lo,zr},{15.5,lo,zf},{15,lo,zf}},UP)
  end

