              else
                -- r12 (ledge hills): this cell's edge vs the neighbour's edge,
                -- corner by corner (a trapezoid where this side is higher)
                local ia, ib, ja, jb -- corner indices: this cell's a / b, the neighbour's a / b
                local ax, az, bx, bz
                if d.name == "down" then ia, ib, ja, jb, ax, az, bx, bz = 4, 3, 1, 2, x0, z1, x1, z1
                elseif d.name == "up" then ia, ib, ja, jb, ax, az, bx, bz = 2, 1, 3, 4, x1, z0, x0, z0
                elseif d.name == "left" then ia, ib, ja, jb, ax, az, bx, bz = 1, 4, 2, 3, x0, z0, x0, z1
                else ia, ib, ja, jb, ax, az, bx, bz = 3, 2, 4, 1, x1, z1, x1, z0 end
                local ta = cell.rampH and cell.rampH[ia] or groundY
                local tb = cell.rampH and cell.rampH[ib] or groundY
                local ba = nc.rampH and nc.rampH[ja] or nc.hgt
                local bb = nc.rampH and nc.rampH[jb] or nc.hgt
                -- (a ledge cell: its curb closes the exit edge and the curb's
                -- ends the last LEDGE_DEPTH of the side edges -- the skirt
                -- stops there)
                local ld = cell.ledgeDir
                local skip = ld == d.name
                if ld and not skip and OPP[ld] ~= d.name then
                  local ex = ld == "down" and { 0, 1 } or (ld == "up" and { 0, -1 } or (ld == "left" and { -1, 0 } or { 1, 0 }))
                  -- which end of this edge lies at the exit side: move it back by D
                  local function atExit(px, pz) return (px - (x0 + 0.5)) * ex[1] + (pz - (z0 + 0.5)) * ex[2] > 0 end
                  local f = 1 - C.LEDGE_DEPTH
                  if atExit(bx, bz) then
                    bx, bz = ax + (bx - ax) * f, az + (bz - az) * f
                    tb, bb = ta + (tb - ta) * f, ba + (bb - ba) * f
                  elseif atExit(ax, az) then
                    ax, az = bx + (ax - bx) * f, bz + (az - bz) * f
                    ta, ba = tb + (ta - tb) * f, bb + (ba - bb) * f
                  end
                end
                if not skip and (ta > ba + EPS or tb > bb + EPS) then
                  ta, tb = math.max(ta, ba), math.max(tb, bb)
                  local n = d.name == "down" and N_S or (d.name == "up" and N_N or (d.name == "left" and N_W or N_E))
                  local suv = nc.isWater and not cell.caveRingSupport and subRectV(uv, C.WATER_BANK_V0, 1) or uv
                  quadN(opaque, ax, ba, az, suv[1], suv[4], bx, bb, bz, suv[3], suv[4],
                    bx, tb, bz, suv[3], suv[2], ax, ta, az, suv[1], suv[2], n[1], n[2], n[3])
                end
              end
              end
            elseif cell.plank and nc and nc.isWater then
              -- r12 (pool): the plank's edge -- PLANK_T of its art's bottom
              -- rows -- and a stilt STILT_INSET in from the middle of this edge
              local T = C.PLANK_T
              faceQuad(opaque, d.name, x0, x1, z0, z1, groundY - T, groundY, subRectV(uv, 1 - T, 1))
              local sw, si = C.STILT_W * 0.5, C.STILT_INSET
              local sx = x0 + 0.5 + d.dx * (0.5 - si)
              local sz = z0 + 0.5 + d.dy * (0.5 - si)
              local sr = subRect(uv, 0.45, 1 - T, 0.55, 1)
              for _, sd in ipairs(DIRS) do
                faceQuad(opaque, sd.name, sx - sw, sx + sw, sz - sw, sz + sw, nc.hgt, groundY - T, sr)
              end
            elseif indoor and nc and nc.plank and not cell.plank and nc.poolH and nc.poolH < groundY - EPS then
              -- (pool: the deck's wall under a plank's end, down to the water)
              faceQuad(opaque, d.name, x0, x1, z0, z1, nc.poolH, groundY, subRectV(uv, math.max(0, 1 - (groundY - nc.poolH)), 1))
            elseif nc and nc.hgtSource ~= "fallback" and nc.hgt < groundY - EPS and not nc.rock
              and not(cell.nativeElevationNorthEdge and d.name=="up")
              and not(grid.bondEastCoastCells and grid.bondEastCoastCells[cell] and grid.bondEastCoastCells[cell][3]==d.name)
              and not (grid.caveFootWater and cell.cavePlatformSupport and not cell.rampH and compOf(nc)
                and not nc.nativeLooseRock and not nc.caveShore and not nc.walkable and not nc.isWater
                and ({[656]=true,[658]=true,[664]=true,[665]=true,[666]=true,[667]=true,[668]=true})[nc.mid]
                and math.abs(nc.hgt+C.CAVE_WALL_H-groundY)<EPS) then
              -- A same-top native rim volume owns this internal boundary;
              -- its outer wall stays in the cave pass. Do not emit floor art here.
              local suv = nc.isWater and not cell.caveRingSupport and subRectV(uv, C.WATER_BANK_V0, 1) or uv
              -- (r12: a pool's wall shows its deck tile 1:1 down to the water)
              if indoor and nc.isWater then suv = subRectV(uv, math.max(0, 1 - (groundY - nc.hgt)), 1) end
              -- Exact profile-owned hidden terrain side material; preserve the
              -- existing face geometry and use native texels at one cell per16px.
              local own=grid.nativeElevationSideMaterials and grid.nativeElevationSideMaterials[x..":"..y]
              local side=own and own[d.name]
              if side and groundY==side[2] and nc.hgt==side[3] and nc.mid==side[4] then
                local donor=underRect(side[1]);if donor then suv=subRectV(donor,0,groundY-nc.hgt) end
              end
              local material=grid.nativeNuggetBankProfile and grid.nativeNuggetBankProfile.sideByCell[x..":"..y]
              local exact=material and material[d.name]
              if exact and groundY==exact[5] and nc.hgt==exact[6] and nc.mid==exact[7] then
                grid.emitNativeNuggetSide(exact,x0,z0,x1,z1,nc.hgt,groundY)
              else
                faceQuad(opaque, d.name, x0, x1, z0, z1, nc.hgt, groundY, suv)
              end
            end
          end
        end

        -- Flat over decal (M13: none for building cells, tree art, walkable
        -- tree tips, roof-top rows behind houses, fences, sign tops).
        local skip = isBuildingCell or cell.isTreeArt or cell.suppressDecal or cell.overhangOf
          or isFence or cell.signKind ~= nil
          or (cell.walkable and MB.GENERAL_TREE_MIDS[cell.mid])
          or hidden or cell.role == "plant" or cell.blockFill ~= nil
          or (isBlob and not cell.bush) -- r11 (review M3): no leaf decals under blob trees
        if cell.hasOver and not skip and not cell.caveShore and not grid.indigoArchCells[cell] then
          local ov = overRect(cell.mid)
          if ov then
            local keep=cell.nativeSignKeepOverTop
            if keep then hQuad(cutoutOver,x0,z0,x1,z0+(z1-z0)*keep,groundY+C.OVER_LIFT,subRect(ov,0,0,1,keep))
            else hQuad(cutoutOver,x0,z0,x1,z1,groundY+C.OVER_LIFT,ov) end
          end
        end

        if grid.indigoRailCells[cell]then grid.emitIndigoRail(cell,x0,z0,groundY)end

        -- M3 tall grass. r11 (USER REPORT 13): a dense knee-high patch --
        -- GRASS_CARDS keyed blade cards in a hashed star (spokes 180 / n
        -- degrees apart, jittered), GRASS_CARD_H_MIN..MAX tall, sampling the
        -- whole tile (its denser lower rows at the ground, sparse tips on
        -- top), reaching at most GRASS_SPILL into the neighbours so a field
        -- reads continuous; border rings (far) GRASS_CARDS_FAR
        if cell.isGrass and uv and IN.flora then
          -- W7: opaque leaf kites cut from the tile's own leaf sections
          IN.flora:grass(x, y, groundY, uv, cell.mid)
          keyedGrass = keyedGrass + 1
        elseif cell.isGrass and uv then
          local nCards = isBorder and C.GRASS_CARDS_FAR or C.GRASS_CARDS
          for k = 0, nCards - 1 do
            local yaw = math.rad(k * 180 / nCards + 22.5 + (hash01(x, y, 11 + k) - 0.5) * 2 * C.GRASS_YAW_JITTER)
            local w = lerp(C.GRASS_CARD_W_MIN, C.GRASS_CARD_W_MAX, hash01(x, y, 21 + k))
            local h = lerp(C.GRASS_CARD_H_MIN, C.GRASS_CARD_H_MAX, hash01(x, y, 31 + k))
            local dx, dz = math.cos(yaw) * w * 0.5, math.sin(yaw) * w * 0.5
            local cx = x0 + 0.5 + (hash01(x, y, 41 + k) - 0.5) * 2 * C.GRASS_OFFSET
            local cz = z0 + 0.5 + (hash01(x, y, 51 + k) - 0.5) * 2 * C.GRASS_OFFSET
            local mx, mz = math.abs(dx) - C.GRASS_SPILL, math.abs(dz) - C.GRASS_SPILL
            cx = math.max(x0 + mx, math.min(x1 - mx, cx))
            cz = math.max(z0 + mz, math.min(z1 - mz, cz))
            wallQuad(cutoutKeyed, cx - dx, cz - dz, cx + dx, cz + dz, groundY, groundY + h, uv, UP)
          end
          keyedGrass = keyedGrass + 1
        end

        -- Native flowers: one fixed sheet, including the no-flora fallback.
        if cell.flower and uv and IN.flora then
          IN.flora:flower(x, y, groundY, uv, cell.mid) -- W7: an upright clump of the tile's blooms
          flowerCells = flowerCells + 1
        elseif cell.flower and uv then
          local cuv = subRectV(uv, 0, C.FLOWER_V1)
          do
            local k = 0
            local yaw = 0 -- fixed east-west sheet, matching the flora path
            -- (card width : height about the art's 16 : 12 -- not squashed)
            local w = lerp(C.FLOWER_W_MIN, C.FLOWER_W_MAX, hash01(x, y, 93 + k))
            local h = lerp(C.FLOWER_H_MIN, C.FLOWER_H_MAX, hash01(x, y, 95 + k))
            local dx, dz = math.cos(yaw) * w * 0.5, math.sin(yaw) * w * 0.5
            local cx = x0 + 0.5 + (hash01(x, y, 97 + k) - 0.5) * 2 * C.GRASS_OFFSET
            local cz = z0 + 0.5 + (hash01(x, y, 99 + k) - 0.5) * 2 * C.GRASS_OFFSET
            local mx, mz = math.abs(dx) + 0.02, math.abs(dz) + 0.02
            cx = math.max(x0 + mx, math.min(x1 - mx, cx))
            cz = math.max(z0 + mz, math.min(z1 - mz, cz))
            wallQuad(cutoutKeyed, cx - dx, cz - dz, cx + dx, cz + dz, groundY, groundY + h, cuv, UP)
          end
          flowerCells = flowerCells + 1
        end

        -- M6 ledge: a curb LEDGE_LIP tall, LEDGE_DEPTH deep on the exit edge.
        -- r12 (USER: "round the corners and smooth the angles"): the curb is
        -- a swept PROFILE -- a flat top, a quarter-round lip of LEDGE_ROUND
        -- in LEDGE_ROUND_SEGS segments with smooth normals, the front face
        -- down to the street -- and a run's ends are ROUNDED in plan (a
        -- quarter turn of radius LEDGE_DEPTH: the art's curved end tiles).
        -- The lip strip art runs down the profile by arc length (no smear);
        -- the top shows the tile's top rows. A hill cell's ground meets the
        -- top flush at the curb's back edge (pass 1c); a curb without a hill
        -- keeps a back face. (inner function: locals limit)
        local ledgeD = cell.ledgeDir or cell.curbDir
        if ledgeD and uv then (function()
          local d = ledgeD
          -- (triangles wound so their geometric normal agrees with the
          -- vertex normals: the curb's winding matches wallQuad's)
          local function otri(p1, t1, n1, p2, t2, n2, p3, t3, n3)
            local g = cross3(sub3(p2, p1), sub3(p3, p1))
            if g[1] * (n1[1] + n2[1] + n3[1]) + g[2] * (n1[2] + n2[2] + n3[2]) + g[3] * (n1[3] + n2[3] + n3[3]) < 0 then
              p2, t2, n2, p3, t3, n3 = p3, t3, n3, p2, t2, n2
            end
            tri3(opaque, p1, t1, n1, p2, t2, n2, p3, t3, n3)
          end
          local function oquad(p1, t1, p2, t2, p3, t3, p4, t4, n)
            otri(p1, t1, n, p2, t2, n, p3, t3, n)
            otri(p1, t1, n, p3, t3, n, p4, t4, n)
          end
          local gY = cell.baseHgt or groundY
          -- r12 (census): the lip is the art's face height; the round starts
          -- at the art's CAP line on the curb's back edge (where the hill
          -- meets it) and sweeps an elliptic quarter -- LEDGE_DEPTH across,
          -- the census rv down -- then the face drops to the street
          local cz = grid.censusOf(cell.mid, d)
          local D, SEG = C.LEDGE_DEPTH, C.LEDGE_ROUND_SEGS
          local Rh, Rv = D, cz.rv
          local top = gY + cz.lip
          -- the lip strip: the art's lines from the cap line to the exit
          -- edge, laid down the profile by arc length (down = rows, up =
          -- rows flipped, left / right = columns turned upright):
          -- lipUV(along 0..1, down-the-profile 0..1)
          local c0 = (cz.cap + 0.25) / 16
          local lip, rot = subRect(uv, 0, c0, 1, 1), false
          if d == "up" then lip = subRect(uv, 0, 1 - c0, 1, 0)
          elseif d == "left" then lip, rot = subRect(uv, 1 - c0, 0, 0, 1), true
          elseif d == "right" then lip, rot = subRect(uv, c0, 0, 1, 1), true end
          local function lipUV(af, sf)
            if rot then return { lip[1] + sf * (lip[3] - lip[1]), lip[2] + af * (lip[4] - lip[2]) } end
            return { lip[1] + af * (lip[3] - lip[1]), lip[2] + sf * (lip[4] - lip[2]) }
          end
          local topR = rot and subRect(uv, 0.4, 0, 0.6, 1) or subRectV(uv, 0, 0.45)
          -- the frame: a = along the run (world x for down / up, z for left
          -- / right), t = inward from the exit edge
          local horiz = d == "down" or d == "up"
          local A0, A1 = horiz and x0 or z0, horiz and x1 or z1
          local out = ({ down = { 0, 1 }, up = { 0, -1 }, left = { -1, 0 }, right = { 1, 0 } })[d]
          local alongV = horiz and { 1, 0 } or { 0, 1 }
          local exitC = ({ down = z1, up = z0, left = x0, right = x1 })[d]
          local function W(av, t) -- plan point
            if horiz then return av, exitC - out[2] * t end
            return exitC - out[1] * t, av
          end
          local function topUV(av, t)
            local af = (av - A0)
            if rot then return { topR[1] + (1 - t / D) * (topR[3] - topR[1]), topR[2] + af * (topR[4] - topR[2]) } end
            return { topR[1] + af * (topR[3] - topR[1]), topR[2] + (t / D) * (topR[4] - topR[2]) }
          end
          -- the profile: { inward t, height, outward-normal, up-normal, arc length }
          -- (an elliptic quarter: Rh across, Rv down; its normals are the
          -- ellipse's, so the round shades smoothly)
          local Rr = Rh
          local prof, len = {}, 0
          prof[1] = { Rh, top, 0, 1, 0 }
          for k = 1, SEG do
            local an = k / SEG * math.pi * 0.5
            local sn, cs = math.sin(an), math.cos(an)
            local enx, eny = sn / Rh, cs / Rv
            local el = math.sqrt(enx * enx + eny * eny)
            local p = { Rh - Rh * sn, top - Rv + Rv * cs, enx / el, eny / el }
            local q = prof[#prof]
            len = len + math.sqrt((p[1] - q[1]) ^ 2 + (p[2] - q[2]) ^ 2)
            p[5] = len
            prof[#prof + 1] = p
          end
          if top - Rv - gY > 1e-4 then
            len = len + (top - Rv - gY)
            prof[#prof + 1] = { 0, gY, 1, 0, len }
          end
          local function sameRun(dx, dy)
            local nc = at(x + dx, y + dy)
            -- (r13c: a corner curb turning onto this run continues it)
            return nc and ((nc.ledgeDir or nc.curbDir) == d or nc.cornerTo == cell)
          end
          local roundS = not sameRun(-alongV[1], -alongV[2])
          local roundE = not sameRun(alongV[1], alongV[2])
          local s0 = A0 + (roundS and D or 0)
          local s1 = A1 - (roundE and D or 0)
          -- a profile point q (inward t, height, ...) at a station whose
          -- outline point is pt and outward plan direction dir
          local function profPt(pt, dir, q) return { pt[1] - dir[1] * q[1], q[2], pt[2] - dir[2] * q[1] } end
          local function area2(p1, p2, p3)
            local g = cross3(sub3(p2, p1), sub3(p3, p1))
            return math.sqrt(g[1] * g[1] + g[2] * g[2] + g[3] * g[3])
          end
          local function emitBand(pa, na, pb, nb, ua, ub, k)
            -- pa / pb: plan points of the profile's outline at two stations,
            -- na / nb: their outward plan directions
            local a1, a2 = prof[k], prof[k + 1]
            local A1p, B1p = profPt(pa, na, a1), profPt(pb, nb, a1)
            local A2p, B2p = profPt(pa, na, a2), profPt(pb, nb, a2)
            local nA1 = { na[1] * a1[3], a1[4], na[2] * a1[3] }
            local nB1 = { nb[1] * a1[3], a1[4], nb[2] * a1[3] }
            local nA2 = { na[1] * a2[3], a2[4], na[2] * a2[3] }
            local nB2 = { nb[1] * a2[3], a2[4], nb[2] * a2[3] }
            local sa, sb = a1[5] / len, a2[5] / len
            otri(A1p, lipUV(ua, sa), nA1, B1p, lipUV(ub, sa), nB1, B2p, lipUV(ub, sb), nB2)
            otri(A1p, lipUV(ua, sa), nA1, B2p, lipUV(ub, sb), nB2, A2p, lipUV(ua, sb), nA2)
          end
          -- straight part: flat top (none when the round spans the curb) +
          -- profile bands
          if s1 > s0 + 1e-6 then
            if D - Rr > 1e-4 then
              local ax, az = W(s0, D)
              local bx2, bz2 = W(s1, D)
              local cx2, cz2 = W(s1, Rr)
              local dx2, dz2 = W(s0, Rr)
              local T1, T2, T3, T4 = topUV(s0, D), topUV(s1, D), topUV(s1, Rr), topUV(s0, Rr)
              oquad({ ax, top, az }, T1, { bx2, top, bz2 }, T2, { cx2, top, cz2 }, T3, { dx2, top, dz2 }, T4, UP)
            end
            -- (r13c: split at the ground grid's cuts along the run -- its
            -- points on the back line are the top ring's: no T-junctions)
            local cuts = { s0 }
            local G = cell.hg and guv and not hidden and cell.hg
            if G then
              for _, c in ipairs(horiz and G.xs or G.zs) do
                if c > s0 + 1e-9 and c < s1 - 1e-9 then cuts[#cuts + 1] = c end
              end
            end
            cuts[#cuts + 1] = s1
            for i = 1, #cuts - 1 do
              local pa = { W(cuts[i], 0) }
              local pb = { W(cuts[i + 1], 0) }
              for k = 1, #prof - 1 do emitBand(pa, out, pb, out, cuts[i] - A0, cuts[i + 1] - A0, k) end
            end
          end
          -- rounded ends: a quarter turn about the curb's back-edge point
          for _, en in ipairs({ { roundS, s0, -1 }, { roundE, s1, 1 } }) do
            -- r13c (verifier r2: the r13b bank zone squeezed the roll's art
            -- into teeth; free ends kept a notch under the ground's cut
            -- edge): a SMOOTH END -- beside a banked hill path, or where the
            -- hill bands this side down to the base -- is the same quarter
            -- turn, its profile MORPHING by m = sin^2 of the turn from the
            -- curb's (the straight part's: welded) to the band's (h = hS +
            -- (top - hS) S(x) at the band's cuts: the ground behind carries
            -- it on, no notch), the foot on the floor (the street; a banked
            -- end: the path's plane), the lip art by arc length per station
            -- (never squeezed), normals blended the same way
            local sideName = horiz and (en[3] > 0 and "right" or "left") or (en[3] > 0 and "down" or "up")
            local bk = cell.ledgeBank and cell.ledgeBank[en[3]]
            local smooth = en[1] and cell.rampH and guv and not hidden and (bk or (cell.hb and cell.hb.e[sideName]))
            if smooth then
              local sg = en[3]
              local ev = { alongV[1] * sg, alongV[2] * sg }
              local cxp, czp = W(en[2], D)
              local K = SEG + 1
              local hS, gF, hE = nil, 0, gY
              if bk then gF, hE = bk.hF - bk.hE, bk.hE; hS = hE + gF * D else hS = cell.hb.hT end
              local BX, Sf = grid.BX, grid.bandS
              local NP = SEG + 2
              local pc = {}
              for k = 1, NP do pc[k] = prof[math.min(k, #prof)] end
              -- ledgefinal1 (verifier r3 on r13c): (1) the FOOT stays on the
              -- floor at its own plan point (the morph lifted it by m cos(turn)
              -- gF D over a banked end's sloped floor: a slit under every
              -- banked end, up to 0.046) and no ring point dips under the
              -- floor; (A) the lip art WRAPS the band round the end -- its
              -- columns run on from the straight part's last one back over the
              -- band (mirrored, linear in the turn), never the tile's own
              -- rounded end (grass in its cap rows: a light-green streak at
              -- the crown); (C) the TOP ART comes down over the end: station q
              -- shows the ground's art by plan (the shoulder's own mapping,
              -- mirrored about the back line) on the first (q / K)^2 of its
              -- arc from the crown and the lip art below it (cut by arc
              -- length, never squeezed) -- the band's top edge sweeps round the
              -- nose to the foot, no straight sand / lip seam from the crown
              -- down the back line (it read as a fold); the cut runs through
              -- the stations' own quads (points past it collapse onto it: no
              -- twisted quads); (B) the foot takes the floor's normal where the
              -- end meets the floor at a shallow crease, and the last station
              -- the ground's normals (no shading crease where the end meets the
              -- floor or the ground behind).
              local fN = bk and norm3({ gF * out[1], 1, gF * out[2] }) or UP
              local gu0, gv0, gdu, gdv = guv[1], guv[2], guv[3] - guv[1], guv[4] - guv[2]
              local af0, G = en[2] - A0, cell.hg
              local st = {}
              for q = 0, K do
                local ph = q / K * math.pi * 0.5
                local sph, cph = math.sin(ph), math.cos(ph)
                local m = sph * sph
                if q == 0 then m = 0 elseif q == K then m = 1 end
                local dir = { out[1] * cph + ev[1] * sph, out[2] * cph + ev[2] * sph }
                local pt = { cxp + dir[1] * D, czp + dir[2] * D }
                local to = D * (1 - cph)
                local Pq, Hq = {}, {}
                for k = 1, NP do
                  local xb = BX[NP - k]
                  local q1c, hc = pc[k][1], pc[k][2]
                  if k == NP then q1c, hc = 0, hE + gF * to end
                  Pq[k] = (1 - m) * q1c + m * D * xb
                  Hq[k] = (1 - m) * hc + m * (hS + (top - hS) * Sf(xb))
                end
                if q > 0 then
                  Hq[NP] = hE + gF * to
                  for k = 1, NP - 1 do
                    local fl = hE + gF * (to + cph * Pq[k])
                    if Hq[k] < fl then Hq[k] = fl end
                  end
                end
                local arc = { 0 }
                for k = 2, NP do arc[k] = arc[k - 1] + math.sqrt((Pq[k] - Pq[k - 1]) ^ 2 + (Hq[k] - Hq[k - 1]) ^ 2) end
                local ln = arc[NP] > 1e-12 and arc[NP] or 1
                local R = { arc = arc, ln = ln, af = math.max(0, math.min(1, af0 - sg * D * q / K)) }
                for k = 1, NP do
                  local ka, kb = math.max(1, k - 1), math.min(NP, k + 1)
                  local no, nu = -(Hq[kb] - Hq[ka]), Pq[ka] - Pq[kb]
                  local nl = math.sqrt(no * no + nu * nu)
                  if k == 1 or nl < 1e-9 then no, nu, nl = 0, 1, 1 end
                  local co, cu = pc[k][3], pc[k][4]
                  local bo, bu = (1 - m) * co + m * no / nl, (1 - m) * cu + m * nu / nl
                  local bl = math.sqrt(bo * bo + bu * bu)
                  if bl < 1e-9 then bo, bu, bl = 0, 1, 1 end
                  R[k] = { { pt[1] - dir[1] * Pq[k], Hq[k], pt[2] - dir[2] * Pq[k] }, nil, { dir[1] * bo / bl, bu / bl, dir[2] * bo / bl } }
                end
                st[q] = R
              end
              -- (past the first station the normals come from the surface --
              -- the profile's tangent x the turn's -- so the lit side is the
              -- side that faces the light; the first station keeps the curb's)
              for q = 1, K do
                local A, B, Cn = st[q - 1], st[q], st[math.min(K, q + 1)]
                for k = 2, NP do
                  local ka, kb = k - 1, math.min(NP, k + 1)
                  local T1 = sub3(B[kb][1], B[ka][1])
                  local T2 = sub3(Cn[k][1], A[k][1])
                  local nn = cross3(T2, T1)
                  local l = math.sqrt(nn[1] * nn[1] + nn[2] * nn[2] + nn[3] * nn[3])
                  if l > 1e-12 then
                    nn = { nn[1] / l, nn[2] / l, nn[3] / l }
                    local ref = B[k][3]
                    if nn[1] * ref[1] + nn[2] * ref[2] + nn[3] * ref[3] < 0 then nn = { -nn[1], -nn[2], -nn[3] } end
                    B[k][4] = nn
                  end
                end
              end
              for q = 1, K do
                local R = st[q]
                for k = 2, NP do if R[k][4] then R[k][3] = R[k][4] end end
                -- (B) the foot takes the floor's normal where the end meets
                -- the floor at a shallow crease (<= 60 deg: fully; a face
                -- over 80 deg keeps its hard edge, like the straight curb's;
                -- between: smoothstep)
                local n = R[NP][3]
                local w = Sf(((n[1] * fN[1] + n[2] * fN[2] + n[3] * fN[3]) - 0.17365) / (0.5 - 0.17365))
                if q == K then w = 1 end
                R[NP][3] = norm3({ (1 - w) * n[1] + w * fN[1], (1 - w) * n[2] + w * fN[2], (1 - w) * n[3] + w * fN[3] })
                if q == K and G then for k = 1, NP - 1 do R[k][3] = G.nrm(R[k][1][1], R[k][1][3]) end end
              end
              -- (C) the top / lip split: the stations' own triangles (the
              -- geometry unchanged), each CLIPPED by the boundary u = fb(q)
              -- (u = the arc fraction at a station, fb = (q / K)^2 -- the band
              -- stays broad round the nose and tapers to the foot at the last
              -- station), linear in q between stations: the top side takes
              -- the ground's art by plan mirrored about the back line (in front
              -- of it the tile shows its own border rows, never meant to be
              -- seen) and slid like the ground's beside it (hg.uvp: one texel
              -- back, faded in from the crown -- the art's edge row at the
              -- crest does not run down the end), the lip side the lip art by
              -- arc length. A cut point on an edge is computed from the edge's
              -- ends in one order, so both triangles of the edge share it.
              for q = 0, K do
                local R, fb = st[q], (q / K) ^ 2
                for k = 1, NP do
                  local p = R[k][1]
                  local tp = horiz and (exitC - p[3]) * out[2] or (exitC - p[1]) * out[1]
                  local rf = 2 * math.max(0, D - tp)
                  local qx, qz = p[1] - out[1] * rf, p[3] - out[2] * rf
                  if G and G.uvp then qx, qz = G.uvp(qx, qz) end
                  local u = R.arc[k] / R.ln
                  -- { point, normal, g = u - fb, top uv, lip uv }
                  R[k] = { p, R[k][3], u - fb, { gu0 + (qx - x0) * gdu, gv0 + (qz - z0) * gdv }, lipUV(R.af, u), fb = fb }
                end
                R[1].crown = true
              end
              local function cutP(a, b, ga, gb)
                if a[1][1] > b[1][1] or (a[1][1] == b[1][1] and (a[1][3] > b[1][3] or (a[1][3] == b[1][3] and a[1][2] > b[1][2]))) then a, b, ga, gb = b, a, gb, ga end
                local f = ga / (ga - gb)
                local function L(i, j) return a[i][j] + (b[i][j] - a[i][j]) * f end
                return { { L(1, 1), L(1, 2), L(1, 3) }, norm3({ L(2, 1), L(2, 2), L(2, 3) }), 0, { L(4, 1), L(4, 2) }, { L(5, 1), L(5, 2) } }
              end
              local function emitPoly(P, ui)
                -- (a fan from an apex that makes no degenerate triangle: a cut
                -- point on an edge stays a vertex of both sides)
                local n, o = #P, 0
                for s0 = 0, n - 1 do
                  local ok = true
                  for i = 1, n - 2 do
                    if area2(P[s0 + 1][1], P[(s0 + i) % n + 1][1], P[(s0 + i + 1) % n + 1][1]) < 1e-12 then ok = false break end
                  end
                  if ok then o = s0 break end
                end
                for i = 1, n - 2 do
                  local a, b, c = P[o + 1], P[(o + i) % n + 1], P[(o + i + 1) % n + 1]
                  if area2(a[1], b[1], c[1]) >= 1e-12 then otri(a[1], a[ui], a[2], b[1], b[ui], b[2], c[1], c[ui], c[2]) end
                end
              end
              local function clipTri(v1, v2, v3)
                if area2(v1[1], v2[1], v3[1]) < 1e-12 then return end
                -- (most triangles lie on one side: emitted as they are)
                if not (v1.crown or v2.crown or v3.crown) then
                  local g1, g2, g3 = v1[3], v2[3], v3[3]
                  local ui = (g1 <= 0 and g2 <= 0 and g3 <= 0) and 4 or ((g1 >= 0 and g2 >= 0 and g3 >= 0) and 5 or nil)
                  if ui then otri(v1[1], v1[ui], v1[2], v2[1], v2[ui], v2[2], v3[1], v3[ui], v3[2]) return end
                end
                local V = { v1, v2, v3 }
                local topP, lipP = {}, {}
                for i = 1, 3 do
                  local a, b, c = V[i], V[i % 3 + 1], V[(i + 1) % 3 + 1]
                  -- (the crown is every station's first point: its g on an
                  -- edge is the g the edge's other end's station gives it,
                  -- so an edge from the crown is cut alike in both its
                  -- triangles)
                  local ga, gb, gT, gL = a[3], b[3], a[3], a[3]
                  if a.crown then ga, gT, gL = -b.fb, math.min(-b.fb, -c.fb), math.max(-b.fb, -c.fb) end
                  if b.crown then gb = -a.fb end
                  if gT <= 0 then topP[#topP + 1] = a end
                  if gL >= 0 then lipP[#lipP + 1] = a end
                  if (ga < 0 and gb > 0) or (ga > 0 and gb < 0) then
                    local cp = cutP(a, b, ga, gb)
                    topP[#topP + 1] = cp
                    lipP[#lipP + 1] = cp
                  end
                end
                if #topP >= 3 then emitPoly(topP, 4) end
                if #lipP >= 3 then emitPoly(lipP, 5) end
              end
              for q = 0, K - 1 do
                local A, B = st[q], st[q + 1]
                -- (g of station q's points relative to this pair's line: its
                -- own fb at the station -- the line is linear in q)
                for k = 1, NP - 1 do
                  clipTri(A[k], B[k], B[k + 1])
                  clipTri(A[k], B[k + 1], A[k + 1])
                end
              end
            elseif en[1] then
              local cxp, czp = W(en[2], D)
              local ev = { alongV[1] * en[3], alongV[2] * en[3] }
              local K = C.LEDGE_ROUND_SEGS + 1
              local prev
              for q = 0, K do
                local ph = q / K * math.pi * 0.5
                local dir = { out[1] * math.cos(ph) + ev[1] * math.sin(ph), out[2] * math.cos(ph) + ev[2] * math.sin(ph) }
                local pt = { cxp + dir[1] * D, czp + dir[2] * D }
                local af = math.max(0, math.min(1, (horiz and pt[1] or pt[2]) - A0))
                -- (ledgefinal1 (A), smooth ends' switch on: the lip wraps the
                -- band round, never the tile's own rounded end -- see above.
                -- ledgefinal2 (verifier final-r1 F3: a pale tan fan at the
                -- Route 4 corner-dome crowns -- the wrap mirrored the corner
                -- tile's cap highlight round the turn): a CORNER dome (this
                -- end turns onto the exit of the ledge behind, cornerTo) keeps
                -- its tile's own corner art -- the corner curb's tile draws the
                -- ledge turning there, its shadow line at the foot)
                if C.LEDGE_END_BANK ~= false and not (cell.cornerTo and cell.cornerSg == en[3]) then af = math.max(0, math.min(1, en[2] - A0 - en[3] * D * q / K)) end
                if prev then
                  -- the flat top sector
                  local ra = D - Rr
                  local t1 = { cxp + prev.dir[1] * ra, czp + prev.dir[2] * ra }
                  local t2 = { cxp + dir[1] * ra, czp + dir[2] * ra }
                  local function tuv(p2)
                    local av = horiz and p2[1] or p2[2]
                    local tv = horiz and (out[2] * (exitC - p2[2])) or (out[1] * (exitC - p2[1]))
                    return topUV(av, tv)
                  end
                  if ra > 1e-4 then
                    otri({ cxp, top, czp }, tuv({ cxp, czp }), UP, { t1[1], top, t1[2] }, tuv(t1), UP, { t2[1], top, t2[2] }, tuv(t2), UP)
                  end
                  for k = 1, #prof - 1 do emitBand(prev.pt, prev.dir, pt, dir, prev.af, af, k) end
                end
                prev = { pt = pt, dir = dir, af = af }
              end
              -- r13c: a CORNER (the band pass: this end turns onto the exit
              -- of the ledge P behind) -- a straight piece of P's curb from
              -- the turn's last station to P (the profile going over from
              -- this tile's census to P's, P's lip art), and the ground behind
              -- both curbs: two triangles, the higher of the two hills
              local Pc = cell.cornerTo and cell.cornerSg == en[3] and guv and cell.cornerTo or nil
              if Pc then (function()
                local czP = grid.censusOf(Pc.mid, Pc.ledgeDir)
                local gP, topP = Pc.baseHgt or gY, (Pc.baseHgt or gY) + czP.lip
                local RvP = czP.rv
                local profP, lnP = { { D, topP, 0, 1, 0 } }, 0
                for k = 1, SEG do
                  local an = k / SEG * math.pi * 0.5
                  local sn, cs = math.sin(an), math.cos(an)
                  local enx, eny = sn / D, cs / RvP
                  local el = math.sqrt(enx * enx + eny * eny)
                  local p = { D - D * sn, topP - RvP + RvP * cs, enx / el, eny / el }
                  local q = profP[#profP]
                  lnP = lnP + math.sqrt((p[1] - q[1]) ^ 2 + (p[2] - q[2]) ^ 2)
                  p[5] = lnP
                  profP[#profP + 1] = p
                end
                if topP - RvP - gP > 1e-4 then
                  lnP = lnP + (topP - RvP - gP)
                  profP[#profP + 1] = { 0, gP, 1, 0, lnP }
                end
                local NP = math.max(#prof, #profP)
                local function pk(pr, k) return pr[math.min(k, #pr)] end
                -- P's lip art (its own tile, cap line, orientation)
                local uvP = underRect(Pc.mid) or uv
                local c0P = (czP.cap + 0.25) / 16
                local dP = Pc.ledgeDir
                local lipP, rotP = subRect(uvP, 0, c0P, 1, 1), false
                if dP == "up" then lipP = subRect(uvP, 0, 1 - c0P, 1, 0)
                elseif dP == "left" then lipP, rotP = subRect(uvP, 1 - c0P, 0, 0, 1), true
                elseif dP == "right" then lipP, rotP = subRect(uvP, c0P, 0, 1, 1), true end
                local function lipUVP(af, sf)
                  if rotP then return { lipP[1] + sf * (lipP[3] - lipP[1]), lipP[2] + af * (lipP[4] - lipP[2]) } end
                  return { lipP[1] + af * (lipP[3] - lipP[1]), lipP[2] + sf * (lipP[4] - lipP[2]) }
                end
                local ev = { alongV[1] * en[3], alongV[2] * en[3] }
                local cxp, czp = W(en[2], D)
                -- station A: the turn's last station (this tile's profile);
                -- station B: this cell's back edge (P's profile)
                local oA = { cxp + ev[1] * D, czp + ev[2] * D }
                local oB = { oA[1] - out[1] * (1 - D), oA[2] - out[2] * (1 - D) }
                local hzP = dP == "down" or dP == "up"
                local function afOf(pt) local a = hzP and pt[1] or pt[2]; return a - math.floor(a + 1e-9) + ((a - math.floor(a + 1e-9)) < 1e-9 and 1 or 0) end
                local afA, afB = afOf(oA), afOf(oB)
                for k = 1, NP - 1 do
                  local a1, a2 = pk(prof, k), pk(prof, k + 1)
                  local b1, b2 = pk(profP, k), pk(profP, k + 1)
                  local A1p, A2p = profPt(oA, ev, a1), profPt(oA, ev, a2)
                  local B1p, B2p = profPt(oB, ev, b1), profPt(oB, ev, b2)
                  local nA1, nA2 = { ev[1] * a1[3], a1[4], ev[2] * a1[3] }, { ev[1] * a2[3], a2[4], ev[2] * a2[3] }
                  local nB1, nB2 = { ev[1] * b1[3], b1[4], ev[2] * b1[3] }, { ev[1] * b2[3], b2[4], ev[2] * b2[3] }
                  local sa1, sa2 = a1[5] / len, a2[5] / len
                  local sb1, sb2 = b1[5] / lnP, b2[5] / lnP
                  if area2(A1p, B1p, B2p) >= 1e-12 then otri(A1p, lipUVP(afA, sa1), nA1, B1p, lipUVP(afB, sb1), nB1, B2p, lipUVP(afB, sb2), nB2) end
                  if area2(A1p, B2p, A2p) >= 1e-12 then otri(A1p, lipUVP(afA, sa1), nA1, B2p, lipUVP(afB, sb2), nB2, A2p, lipUVP(afA, sa2), nA2) end
                end
                -- the ground behind both curbs (this cell, t = D..1 before the
                -- turn): the turn's centre at this top, P's back line at its
                -- top, P's far corner, the run's plane at the other end
                local sOther = en[3] > 0 and A0 or A1
                local ex0, ez0 = W(en[2], D)
                local ex1, ez1 = W(en[2], 1)
                local ex2, ez2 = W(sOther, 1)
                local ex3, ez3 = W(sOther, D)
                local function hillAt(Z, px, pz)
                  if not (Z and Z.rampH) then return nil end
                  local fx, fz = math.max(0, math.min(1, px - Z.x)), math.max(0, math.min(1, pz - Z.y))
                  local r = Z.rampH
                  return (r[1] * (1 - fx) + r[2] * fx) * (1 - fz) + (r[4] * (1 - fx) + r[3] * fx) * fz
                end
                local h1 = hillAt(Pc, ex1, ez1) or topP
                local h2 = hillAt(Pc, ex2, ez2) or topP
                local on = at(x - ev[1], y - ev[2])
                local h3 = (on and (on.ledgeDir or on.curbDir) == d and hillAt(on, ex3, ez3)) or top
                local gu, gv = guv[3] - guv[1], guv[4] - guv[2]
                local function gUV(px, pz) return { guv[1] + (px - x0) * gu, guv[2] + (pz - z0) * gv } end
                local p0, p1, p2, p3 = { ex0, top, ez0 }, { ex1, h1, ez1 }, { ex2, h2, ez2 }, { ex3, h3, ez3 }
                -- (ledgefinal2 (verifier final-r1 F2: the corner's two flat
                -- triangles read as a dark diagonal facet from the crown):
                -- smooth vertex normals -- each corner the hill ground's
                -- normal there (the ledge planes it meets), the turn's centre
                -- the mean of its two neighbours on the back lines)
                local VN
                if C.LEDGE_END_BANK ~= false then
                  local n1 = grid.vnAt(p1[1], p1[3], p1[2], "loose")
                  local n2 = grid.vnAt(p2[1], p2[3], p2[2], "loose")
                  local n3 = grid.vnAt(p3[1], p3[3], p3[2], "loose")
                  if n1 and n2 and n3 then
                    VN = { [p0] = norm3({ n1[1] + n3[1], n1[2] + n3[2], n1[3] + n3[3] }), [p1] = n1, [p2] = n2, [p3] = n3 }
                  end
                end
                local function up3(a, b, c)
                  local g = cross3(sub3(b, a), sub3(c, a))
                  if g[2] < 0 then b, c = c, b; g = { -g[1], -g[2], -g[3] } end
                  local n = norm3(g)
                  if g[1] * g[1] + g[2] * g[2] + g[3] * g[3] > 1e-24 then
                    if VN then tri3(opaque, a, gUV(a[1], a[3]), VN[a], b, gUV(b[1], b[3]), VN[b], c, gUV(c[1], c[3]), VN[c])
                    else tri3(opaque, a, gUV(a[1], a[3]), n, b, gUV(b[1], b[3]), n, c, gUV(c[1], c[3]), n) end
                  end
                end
                -- (ledgefinal1: split on the HIGHER diagonal -- the lower one
                -- folded the corner ground into a 0.037 saddle; the switch
                -- off keeps r12b's split)
                if C.LEDGE_END_BANK ~= false and p1[2] + p3[2] > p0[2] + p2[2] + 1e-9 then
                  up3(p0, p1, p3); up3(p1, p2, p3)
                else
                  up3(p0, p1, p2); up3(p0, p2, p3)
                end
              end)() end
              -- (without a hill: close the nose behind, on the back edge --
              -- not on a corner curb: filled to the lip top below)
              local nbc = at(x - out[1], y - out[2])
              if not cell.rampH and not Pc and not (nbc and (nbc.rampH or nbc.ledgeDir)) then
                local e1x, e1z = W(en[2], D)
                local e2x, e2z = W(en[2] + ev[1] * D + ev[2] * D, D)
                local bn = { -out[1], 0, -out[2] }
                oquad({ e1x, top, e1z }, { lip[1], lip[2] }, { e2x, top, e2z }, { lip[3], lip[2] },
                  { e2x, gY, e2z }, { lip[3], lip[4] }, { e1x, gY, e1z }, { lip[1], lip[4] }, bn)
              end
            end
          end
          local nbF = at(x - out[1], y - out[2])
          -- (r13c: a corner (cell.cornerTo) has its ground behind the curbs
          -- already -- no slab, no back face)
          if cell.cornerTo and guv then s1 = s0 end
          if not cell.rampH and not cell.cornerTo and nbF and (nbF.rampH or nbF.ledgeDir) then
            -- (a corner curb: see below -- the whole run length A0..A1)
            s0, s1 = A0, A1
          end
          if not cell.rampH and s1 > s0 + 1e-6 then
            local bn = { -out[1], 0, -out[2] }
            -- r12 (pre-lab-7 tour, Route 4 (55,9)): a CORNER curb -- the cell
            -- behind it is a ledge or a hill cell -- is filled to the lip
            -- top over the rest of the cell (flush with the hill), with a
            -- face at the cell's back edge only down to that neighbour's
            -- edge (no free-standing 0.5 wall behind the lip)
            local nb = at(x - out[1], y - out[2])
            if nb and (nb.rampH or nb.ledgeDir) then
              local ax, az = W(s0, D)
              local bx2, bz2 = W(s1, D)
              local cx2, cz2 = W(s1, 1)
              local dx2, dz2 = W(s0, 1)
              local tu = { topR[1], topR[2] }
              oquad({ ax, top, az }, tu, { bx2, top, bz2 }, tu, { cx2, top, cz2 }, tu, { dx2, top, dz2 }, tu, UP)
              -- the neighbour's heights along the shared edge (its corners)
              local function nbH(px, pz)
                if not nb.rampH then return nb.hgt or gY end
                local nx0, nz0 = nb.x + 0.0, nb.y + 0.0
                local fx, fz = math.max(0, math.min(1, px - nx0)), math.max(0, math.min(1, pz - nz0))
                local r = nb.rampH
                return (r[1] * (1 - fx) + r[2] * fx) * (1 - fz) + (r[4] * (1 - fx) + r[3] * fx) * fz
              end
              local ha, hb = nbH(dx2, dz2), nbH(cx2, cz2)
              if ha < top - 1e-4 or hb < top - 1e-4 then
                oquad({ dx2, top, dz2 }, { lip[1], lip[2] }, { cx2, top, cz2 }, { lip[3], lip[2] },
                  { cx2, math.min(top, hb), cz2 }, { lip[3], lip[4] }, { dx2, math.min(top, ha), dz2 }, { lip[1], lip[4] }, bn)
              end
            else
              -- a curb with no hill behind it: its back face
              local ax, az = W(s0, D)
              local bx2, bz2 = W(s1, D)
              oquad({ ax, top, az }, { lip[1], lip[2] }, { bx2, top, bz2 }, { lip[3], lip[2] },
                { bx2, gY, bz2 }, { lip[3], lip[4] }, { ax, gY, az }, { lip[1], lip[4] }, bn)
            end
          end
        end)() end

        -- r11 (review M10): a sea rock: a lump WATER_ROCK_H above the water
        -- with the tile's own art on top and faces (none between two rock
        -- cells of one mass)
        if cell.waterRock and uv and not frFlatWaterRock(input,cell.mid) then
          local wy, ty = groundY, groundY + C.WATER_ROCK_H
          local ins = C.WATER_ROCK_INSET
          local function rockN(d) local n = at(x + d.dx, y + d.dy); return n and n.waterRock end
          local lx0, lx1, lz0, lz1 = x0 + ins, x1 - ins, z0 + ins, z1 - ins
          for _, d in ipairs(DIRS) do
            if rockN(d) then
              if d.dx < 0 then lx0 = x0 elseif d.dx > 0 then lx1 = x1 elseif d.dy < 0 then lz0 = z0 else lz1 = z1 end
            end
          end
          -- (the top shows the tile's art under the lump's footprint only --
          -- the rock sits in the middle of its group; the faces show the
          -- tile's middle, the rock, not the water round it)
          hQuad(opaque, lx0, lz0, lx1, lz1, ty, subRect(uv, lx0 - x0, lz0 - z0, lx1 - x0, lz1 - z0))
          for _, d in ipairs(DIRS) do
            if not rockN(d) then
              faceQuad(opaque, d.name, lx0, lx1, lz0, lz1, wy - 0.05, ty, subRect(uv, 0.3, 0.3, 0.7, 0.7))
            end
          end
        end

        -- r11 (review M8): a statue / bollard: a box one row tall with the
        -- cell's own art on its faces, the top art (the north cell's over
        -- art) standing on it as a card
        if cell.statueTop and uv then
          local ins = C.STATUE_INSET
          local sx0, sx1, sz0, sz1 = x0 + ins, x1 - ins, z0 + ins, z1 - ins
          local top = groundY + C.WALL_ROW_UNIT
          for _, e in ipairs({ "down", "up", "left", "right" }) do
            faceQuad(opaque, e, sx0, sx1, sz0, sz1, groundY, top, uv)
          end
          hQuad(opaque, sx0, sz0, sx1, sz1, top, subRectV(uv, 0, 0.2))
          local tov = overRect(cell.statueTop.mid)
          if tov then
            local cz = (z0 + z1) * 0.5
            wallQuad(cutoutOver, x0, cz, x1, cz, top, top + C.WALL_ROW_UNIT, tov, { 0, 0, 1 })
          end
        end

        -- M10 signs and mailboxes (keyed faces).
        if input.signCompat==true and (cell.signKind=="board" or cell.signKind=="mailbox") and uv
            and tostring(input.mapId or ""):match("^FR_") and cell.beh==0x84
            and (cell.mid==361 or cell.mid==685 and input.pair=="pallet_outdoor" or cell.mid==815 and input.pair=="general__rom_082d4b9c") then
          -- Lab 57 SIGNS v2: the native mailbox art (MID 361 / Pallet 685 / Saffron 815) as a real 3D mailbox: one post (the art's
          -- dark stub, cols 6-9 rows 12-14), a body with an arched top, a mail slot and a name panel on the front. The baked
          -- shadow band of the art (grey, rows 12-15 outside the stub) is never meshed. Same cell footprint as before.
          local cxm, czm = x0 + 0.5, z0 + 0.5
          local W, D, RH, RISE, POSTH = 0.56, 0.34, 0.32, 0.14, 0.26 -- keep equal to SignProfiles.MAILBOX
          local bx0, bx1, zn, zs = cxm - W/2, cxm + W/2, czm - D/2, czm + D/2
          local yb = groundY + POSTH
          local ytop = yb + RH + RISE
          local R = (W*W/4 + RISE*RISE) / (2*RISE)
          local yc = ytop - R
          local th0 = math.asin((W/2) / R)
          local NSEG = 8
          local dark = subRect(uv, 2.5/16, 3.5/16, 2.5/16, 3.5/16)
          local bodyc = subRect(uv, 5.5/16, 7.5/16, 5.5/16, 7.5/16)
          local hi = subRect(uv, 6.5/16, .5/16, 6.5/16, .5/16)
          local postTex = subRect(uv, 6/16, 12/16, 10/16, 14/16)
          local pw = 0.06
          for _, dir in ipairs({"down","up"}) do faceQuad(opaque, dir, cxm-pw, cxm+pw, czm-pw, czm+pw, groundY, yb, postTex) end
          for _, dir in ipairs({"left","right"}) do faceQuad(opaque, dir, cxm-pw, cxm+pw, czm-pw, czm+pw, groundY, yb, dark) end
          hQuad(opaque, cxm-pw, czm-pw, cxm+pw, czm+pw, groundY, dark, {0,-1,0})
          faceQuad(opaque, "left", bx0, bx1, zn, zs, yb, yb+RH, bodyc)
          faceQuad(opaque, "right", bx0, bx1, zn, zs, yb, yb+RH, bodyc)
          hQuad(opaque, bx0, zn, bx1, zs, yb, dark, {0,-1,0})
          local function arc(i)
            local th = -th0 + 2*th0*i/NSEG
            return cxm + R*math.sin(th), yc + R*math.cos(th), math.sin(th), math.cos(th)
          end
          for i = 0, NSEG-1 do
            local xa, ya, na, ca = arc(i)
            local xb, yb2, nb, cb = arc(i+1)
            local t = (i == 3 or i == 4) and hi or bodyc
            local tt = {t[1], t[2]}
            tri3(opaque, {xa,ya,zn}, tt, {na,ca,0}, {xa,ya,zs}, tt, {na,ca,0}, {xb,yb2,zs}, tt, {nb,cb,0})
            tri3(opaque, {xa,ya,zn}, tt, {na,ca,0}, {xb,yb2,zs}, tt, {nb,cb,0}, {xb,yb2,zn}, tt, {nb,cb,0})
          end
          -- front / back profile: bottom-left, bottom-right, then the arc from the right end to the left end
          local prof = { {bx0, yb}, {bx1, yb} }
          for i = NSEG, 0, -1 do local xa, ya = arc(i); prof[#prof+1] = {xa, ya} end
          local faceH = ytop - yb
          local ready = input.signLabelsReady and input.signLabelsReady[tostring(x)..","..tostring(y)]
          local crop = subRect(uv, 2/16, 0, 14/16, 12/16)
          local cv = 210/256 -- SignProfiles.MAILBOX.CANVAS_H / 256
          local function fuv(px, py, canvas)
            local u, v = (px - bx0) / W, (ytop - py) / faceH
            if canvas then return {u, v * cv} end
            return {crop[1] + u*(crop[3]-crop[1]), crop[2] + v*(crop[4]-crop[2])}
          end
          local fv = ready and {} or nil
          for k = 3, #prof do
            local A, B, C = prof[1], prof[k-1], prof[k]
            if ready then
              fv[#fv+1] = {A[1], A[2], zs, fuv(A[1],A[2],true)[1], fuv(A[1],A[2],true)[2], 0, 0, 1}
              fv[#fv+1] = {B[1], B[2], zs, fuv(B[1],B[2],true)[1], fuv(B[1],B[2],true)[2], 0, 0, 1}
              fv[#fv+1] = {C[1], C[2], zs, fuv(C[1],C[2],true)[1], fuv(C[1],C[2],true)[2], 0, 0, 1}
            else
              tri3(opaque, {A[1],A[2],zs}, fuv(A[1],A[2]), {0,0,1}, {B[1],B[2],zs}, fuv(B[1],B[2]), {0,0,1}, {C[1],C[2],zs}, fuv(C[1],C[2]), {0,0,1})
            end
            tri3(opaque, {A[1],A[2],zn}, {bodyc[1],bodyc[2]}, {0,0,-1}, {C[1],C[2],zn}, {bodyc[1],bodyc[2]}, {0,0,-1}, {B[1],B[2],zn}, {bodyc[1],bodyc[2]}, {0,0,-1})
          end
          if ready then
            IN.signFaces = IN.signFaces or {}
            IN.signFaces[#IN.signFaces+1] = {x=x, y=y, mid=cell.mid, style="fr-mailbox", verts=fv}
          end
          signCount = signCount + 1
        elseif cell.signKind == "board" and uv then
          -- Prepared text owns the native board planes, never offset decals.
          local function labelled(style,l,r,bot,top,z,ua,va,ub,vb)
            local key=tostring(x)..","..tostring(y)
            if not (input.signLabelsReady and input.signLabelsReady[key]) then return false end
            IN.signFaces=IN.signFaces or {}
            IN.signFaces[#IN.signFaces+1]={x=x,y=y,mid=cell.mid,style=style,x0=l,x1=r,y0=bot,y1=top,z=z,
              u0=ua,v0=va,u1=ub,v1=vb,normal={0,0,1}}
            return true
          end
          local function labelledPart(style,part,l,r,bot,top,z,ua,va,ub,vb,normal)
            local key=tostring(x)..","..tostring(y)
            if not (input.signLabelsReady and input.signLabelsReady[key.."#"..part]) then return false end
            IN.signFaces=IN.signFaces or {}
            IN.signFaces[#IN.signFaces+1]={x=x,y=y,part=part,mid=cell.mid,style=style,x0=l,x1=r,y0=bot,y1=top,z=z,
              u0=ua,v0=va,u1=ub,v1=vb,normal=normal or {0,0,1}}
            return true
          end
          local function labelledRear(style,l,r,bot,top,z,ua,va,ub,vb)
            return labelledPart(style,"back",l,r,bot,top,z,1-ub,va,1-ua,vb,{0,0,-1})
          end
          -- Outline bands exclude authored ground and shadows from thickness.
          local function shapedBoard(rect,spans,originY,step,zn,zs,edge,body,skip,frontLayer,openTop,openBottom,skipRear)
            local function cap(a,b,h,up)
              if b<=a then return end
              local l,r=x0+.1+a*.05,x0+.1+b*.05
              if up then quadN(opaque,l,h,zn,edge[1],edge[2],l,h,zs,edge[1],edge[4],r,h,zs,edge[3],edge[4],r,h,zn,edge[3],edge[2],0,1,0)
              else hQuad(opaque,l,zn,r,zs,h,edge,{0,-1,0}) end
            end
            local function uncovered(span,other,h,up)
              if not other then cap(span[1],span[2],h,up); return end
              cap(span[1],math.min(span[2],other[1]),h,up)
              cap(math.max(span[1],other[2]),span[2],h,up)
            end
            for i,s in ipairs(spans) do
              local l,r=x0+.1+s[1]*.05,x0+.1+s[2]*.05
              local top,bot=originY-s[3]*step,originY-s[4]*step
              if not (skip==true or (skip and skip[1]==s[3] and skip[2]==s[4])) then
                faceQuad(frontLayer or opaque,"down",l,r,zn,zs,bot,top,subRect(rect,s[1]/16,s[3]/16,s[2]/16,s[4]/16))
              end
              if not (skipRear==true or (skipRear and skipRear[1]==s[3] and skipRear[2]==s[4])) then
                faceQuad(opaque,"up",l,r,zn,zs,bot,top,body)
              end
              faceQuad(opaque,"left",l,r,zn,zs,bot,top,edge)
              faceQuad(opaque,"right",l,r,zn,zs,bot,top,edge)
              if not (openTop and i==1) then uncovered(s,spans[i-1],top,true) end
              if not (openBottom and i==#spans) then uncovered(s,spans[i+1],bot,false) end
            end
          end
          local frSign=input.signCompat==true and tostring(input.mapId or ""):match("^FR_") and cell.beh==0x84
          local pair=tostring(input.pair or "")
          local frWood=cell.mid==3 or cell.mid==717 and (pair=="general__rom_082d4bfc" or pair=="general__rom_082d4df4" or pair=="general__rom_082d4e24")
            or (cell.mid==807 or cell.mid==853) and pair=="general__rom_082d4b3c" or cell.mid==828 and pair=="general__rom_082d4b9c"
          if frSign and (cell.mid==360 or cell.mid==780) and cell.nativeGymTop then
            local edge=subRect(uv,.5/16,1.5/16,.5/16,1.5/16)
            local body=subRect(uv,1.5/16,.5/16,1.5/16,.5/16)
            local ready=labelled("fr-gym",x0+.1,x0+.85,groundY+.25,groundY+.8,z0+.55,0,0,15/16,11/16)
            local back=labelledRear("fr-gym",x0+.1,x0+.85,groundY+.25,groundY+.8,z0+.45,0,0,15/16,11/16)
            shapedBoard(uv,{{0,15,0,11}},groundY+.8,.05,z0+.45,z0+.55,edge,body,ready and {0,11},nil,true,nil,back and {0,11})
            -- the crest (dome): when prepared, one smooth card in front and a dark silhouette card just behind it
            local crestReady=labelledPart("fr-gym-crest","crest",x0+.1,x0+.85,groundY+.8,groundY+1.15,z0+.51,0,9/16,15/16,1)
            if crestReady then
              local f=IN.signFaces[#IN.signFaces]; local b={}
              for k,v in pairs(f) do b[k]=v end
              b.z=z0+.49; b.part="crestback"; b.normal={0,0,-1}
              b.u0,b.u1=f.u1,f.u0 -- retain the original crest silhouette in world coordinates
              IN.signFaces[#IN.signFaces+1]=b
            else
              shapedBoard(overRect(cell.nativeGymTop.mid),{{5,10,9,10},{3,12,10,11},{2,13,11,12},{1,14,12,14},{0,15,14,16}},groundY+1.6,.05,z0+.45,z0+.55,edge,body,nil,cutoutOver,false,true)
            end
            for _,col in ipairs({1,10}) do
              shapedBoard(uv,{{col,col+4,11,13},{col+1,col+3,13,14}},groundY+14/12,1/12,z0+.4625,z0+.5375,edge,body)
            end
          elseif frSign and frWood then
            local edge=subRect(uv,14.5/16,2.5/16,14.5/16,2.5/16)
            local body=subRect(uv,3.5/16,5.5/16,3.5/16,5.5/16)
            local ready=labelled("fr-wood",x0+.15,x0+.85,groundY+.25,groundY+.7,z0+.55,1/16,2/16,15/16,11/16)
            local back=labelledRear("fr-wood",x0+.15,x0+.85,groundY+.25,groundY+.7,z0+.45,1/16,2/16,15/16,11/16)
            shapedBoard(uv,{{7,9,0,1},{2,14,1,2},{1,15,2,11},{2,14,11,12}},groundY+.8,.05,z0+.45,z0+.55,edge,body,ready and {2,11},nil,nil,nil,back and {2,11})
            local post=subRect(uv,6/16,12/16,10/16,14/16)
            for _,dir in ipairs({"down","up"}) do faceQuad(opaque,dir,x0+.4,x0+.6,z0+.4625,z0+.5375,groundY,groundY+.2,post) end
            for _,dir in ipairs({"left","right"}) do faceQuad(opaque,dir,x0+.4,x0+.6,z0+.4625,z0+.5375,groundY,groundY+.2,edge) end
            hQuad(opaque,x0+.4,z0+.4625,x0+.6,z0+.5375,groundY,edge,{0,-1,0})
          else

          -- Native FireRed ordinary sign: complete 16x12 board and two feet.
          -- Restrict to the audited shared General MID2 raster. Keep all other
          -- generations, facade plaques, mailboxes and sign art on their path.
          if input.signCompat==true and tostring(input.mapId or ""):match("^FR_") and cell.mid == 2 and cell.beh == 0x84 then
            local l, r, top = x0 + 0.1, x0 + 0.9, groundY + 0.8
            local bot, zn, zs = groundY + 0.2, z0 + 0.45, z0 + 0.55
            -- Row0 is the top return. Front rows1..12 include both side rails
            -- (columns0/15) and bottom rail12; never key these opaque pixels.
            local dark = subRect(uv,.5/16,6.5/16,.5/16,6.5/16)
            -- Continuous dark top rail requested by user. Split the front at
            -- the native row boundary; no overlapping decal or texture edit.
            if not labelled("fr-metal",l,r,bot,top,zs,0,1/16,1,13/16) then
            faceQuad(opaque, "down", l,r,zn,zs,bot,top-.05,subRect(uv,0,2/16,1,13/16))
            faceQuad(opaque, "down", l,r,zn,zs,top-.05,top,dark)
            end
            local body = subRect(uv,7.5/16,4.5/16,7.5/16,4.5/16)
            if not labelledRear("fr-metal",l,r,bot,top,zn,0,1/16,1,13/16) then
              faceQuad(opaque, "up", l,r,zn,zs,bot,top,body)
            end
            faceQuad(opaque, "left", l,r,zn,zs,bot,top,dark)
            faceQuad(opaque, "right", l,r,zn,zs,bot,top,dark)
            local cap = dark -- Continuous dark top return, matching the front rail.
            quadN(opaque,l,top,zn,cap[1],cap[2], l,top,zs,cap[1],cap[4], r,top,zs,cap[3],cap[4], r,top,zn,cap[3],cap[2], 0,1,0)
            hQuad(opaque,l,zn,r,zs,bot,dark,{0,-1,0})
            for _, col in ipairs({2,11}) do
              local pl,pr=x0+.1+col*.05,x0+.1+(col+3)*.05
              local pn,ps=z0+.4625,z0+.5375
              local post=subRect(uv,col/16,13/16,(col+3)/16,15/16)
              for _,dir in ipairs({"down","up"}) do faceQuad(opaque,dir,pl,pr,pn,ps,groundY,bot,post) end
              for _,dir in ipairs({"left","right"}) do faceQuad(opaque,dir,pl,pr,pn,ps,groundY,bot,dark) end
              hQuad(opaque,pl,pn,pr,ps,groundY,dark,{0,-1,0})
            end
          else
          local cxm, czm = x0 + 0.5, z0 + 0.5
          local bw, bd = C.SIGN_BOARD_W, C.SIGN_BOARD_D
          local top = groundY + C.SIGN_BOARD_TOP
          local bot = top - C.SIGN_BOARD_H
          local bx0, bx1, bz0, bz1 = cxm - bw / 2, cxm + bw / 2, czm - bd / 2, czm + bd / 2
          -- r9 (review 8): every board rect cropped to the board art (the
          -- tile's outer texel ring is keyed ground: the old edge / top
          -- rects sampled only keyed texels and drew nothing)
          local face = subRect(uv, 1 / 16, 1 / 16, 15 / 16, C.SIGN_BOARD_V1)
          if not (tostring(input.mapId or ""):match("^FR_") and cell.beh==0x84
              and (cell.mid==361 or cell.mid==685 and input.pair=="pallet_outdoor" or cell.mid==815 and input.pair=="general__rom_082d4b9c")
              and labelled("fr-mailbox",bx0,bx1,bot,top,bz1,1/16,1/16,15/16,C.SIGN_BOARD_V1)) then
          faceQuad(cutoutKeyed, "down", bx0, bx1, bz0, bz1, bot, top, face)
          end
          faceQuad(cutoutKeyed, "up", bx0, bx1, bz0, bz1, bot, top, face)
          local edge = subRect(uv, 2 / 16, 2 / 16, 3 / 16, 10 / 16)
          faceQuad(cutoutKeyed, "left", bx0, bx1, bz0, bz1, bot, top, edge)
          faceQuad(cutoutKeyed, "right", bx0, bx1, bz0, bz1, bot, top, edge)
          hQuad(cutoutKeyed, bx0, bz0, bx1, bz1, top, subRect(uv, 2 / 16, 1 / 16, 14 / 16, 2 / 16))
          local pw = C.SIGN_POST_W
          local post = subRect(uv, 0.44, C.SIGN_BOARD_V1, 0.56, 1)
          wallQuad(cutoutKeyed, cxm - pw, czm, cxm + pw, czm, groundY, bot, post, { 0, 0, 1 })
          wallQuad(cutoutKeyed, cxm, czm - pw, cxm, czm + pw, groundY, bot, post, { 1, 0, 0 })
          end
          end
          signCount = signCount + 1
        elseif cell.signKind == "mailbox" and uv then
          local cxm, czm = x0 + 0.5, z0 + 0.5
          local mw, md = C.MAILBOX_W, C.MAILBOX_D
          local top = groundY + C.MAILBOX_H
          local bx0, bx1, bz0, bz1 = cxm - mw / 2, cxm + mw / 2, czm - md / 2, czm + md / 2
          local body = subRect(uv, 2 / 16, 0, 14 / 16, 1)
          for _, e in ipairs({ "down", "up", "left", "right" }) do
            if e=="down" and input.signLabelsReady and input.signLabelsReady[tostring(x)..","..tostring(y)]
                and tostring(input.mapId or ""):match("^FR_") and cell.beh==0x84
                and (cell.mid==361 or cell.mid==685 and input.pair=="pallet_outdoor" or cell.mid==815 and input.pair=="general__rom_082d4b9c") then
              IN.signFaces=IN.signFaces or {}
              IN.signFaces[#IN.signFaces+1]={x=x,y=y,mid=cell.mid,style="fr-mailbox",
                x0=bx0,x1=bx1,y0=groundY,y1=top,z=bz1,u0=2/16,v0=0,u1=14/16,v1=1,normal={0,0,1}}
            else faceQuad(cutoutKeyed,e,bx0,bx1,bz0,bz1,groundY,top,body) end
          end
          hQuad(opaque, bx0, bz0, bx1, bz1, top - 0.002, subRect(uv, 2 / 16, 0, 14 / 16, 2 / 16))
          local tov = cell.mailboxTop and overRect(cell.mailboxTop.mid)
          if tov then
            hQuad(cutoutOver, bx0 - 0.03, bz0 - 0.03, bx1 + 0.03, bz1 + 0.03, top + 0.004, subRect(tov, 0, 10 / 16, 1, 1))
          end
          signCount = signCount + 1
        end

        -- M9 fence: one keyed card on the run's centre line, posts at run
        -- ends and corners; north-south runs use the east-west side-view art.
        -- r11 (USER REPORT: log posts were flat cards): a fence cell whose
        -- art holds distinct upright objects (atlas.posts: log stumps,
        -- bollards) gets one real post per object -- a hexagonal log
        -- POST_H tall, as wide as the object in the art (POST_R_MIN..MAX
        -- radius), the object's lower texels band-tiled round it and its
        -- upper texels on the cap: 16 tris per post, no card (r12: round, 28)
        -- Verified silver rails are connected fence art, not the palette
        -- detector's round timber posts. Keep their native run and endpoints.
        local gameFenceStart
        if input.mapId=='FR_CELADON_CITY' and isFence
            and (x==30 and y>=17 and y<=23 and cell.nativeBlueFence or y==23 and x>=31 and x<=40 and cell.mid==231)then
          gameFenceStart={#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed}
        end
        local postArt = not cell.nativeBlueFence and isFence and uv and atlas.posts and atlas.posts(cell.mid)
        if cell.nativeStructure and cell.nativeStructure.kind=="wood" then
          postArt=cell.nativeStructure.posts
          uv=cell.hasOver and overRect(cell.mid) or uv
        end
        if grid.emitNativeMetalCorner(cell,x0,z0,groundY)then
          -- Source-owned corner silver and preserved native mixed ground.
          fenceCells=fenceCells+1
        elseif cell.nativeSaffronThin then
          grid.emitNativeSaffronThin(cell,x0,z0,groundY)
        elseif cell.nativeAuditedRail then
          grid.emitNativeAuditedRail(cell,x0,z0,groundY)
        elseif cell.nativeStructure and cell.nativeStructure.kind=="bridge" then
          grid.emitNativeBridge(cell,x0,z0,groundY)
        elseif cell.nativeStructure and cell.nativeStructure.ew then
          grid.emitNativeMetalEW(cell,x0,z0,groundY)
        elseif cell.nativeStructure and cell.nativeStructure.kind=="metal"
            and grid.emitNativeMetalNS(cell,x0,z0,groundY) then
          -- Shared solid metal run; native flat ground already emitted.
          fenceCells=fenceCells+1
        elseif postArt then
          (function()
            local postList=cell.nativeStructure and cell.nativeStructure.kind=="wood" and cell.hasOver and cutoutOver or opaque
            for i = 1, #postArt - 3, 4 do
              local px0, px1, py0, py1 = postArt[i], postArt[i + 1], postArt[i + 2], postArt[i + 3]
              local cxp, czp = x0 + (px0 + px1 + 1) / 32, z0 + 0.5
              if cell.nativeStructure and cell.nativeStructure.ns then czp=z0+(py0+py1+1)/32 end
              local r = math.max(C.POST_R_MIN, math.min(C.POST_R_MAX, (px1 - px0 + 1) / 32))
              local ySplit = py0 + (py1 - py0 + 1) * 0.4
              local capR = subRect(uv, px0 / 16, py0 / 16, (px1 + 1) / 16, ySplit / 16)
              local bark = subRect(uv, px0 / 16, ySplit / 16, (px1 + 1) / 16, (py1 + 1) / 16)
              local y0p, y1p = groundY, groundY + C.POST_H
              -- r12 (v15: round logs): a POST_SIDES-sided cylinder with
              -- smooth normals, the bark wrapped once round it (a triangle
              -- wave: no seam), the art's top texels on the cap; the same
              -- radius / footprint as before
              local NS = C.POST_SIDES
              local pts = {}
              for k = 0, NS - 1 do
                local a = (k + 0.5) * 2 * math.pi / NS
                pts[k] = { cxp + r * math.cos(a), czp + r * math.sin(a), math.cos(a), math.sin(a) }
              end
              local function bu(k) return bark[1] + (bark[3] - bark[1]) * (1 - math.abs(2 * k / NS - 1)) end
              for k = 0, NS - 1 do
                local p1, p2 = pts[k], pts[(k + 1) % NS]
                local n1, n2 = { p1[3], 0, p1[4] }, { p2[3], 0, p2[4] }
                local ua, ub = bu(k), bu(k + 1)
                tri3(postList, { p1[1], y1p, p1[2] }, { ua, bark[2] }, n1, { p2[1], y1p, p2[2] }, { ub, bark[2] }, n2,
                  { p2[1], y0p, p2[2] }, { ub, bark[4] }, n2)
                tri3(postList, { p1[1], y1p, p1[2] }, { ua, bark[2] }, n1, { p2[1], y0p, p2[2] }, { ub, bark[4] }, n2,
                  { p1[1], y0p, p1[2] }, { ua, bark[4] }, n1)
              end
              local function cuv(q)
                return { capR[1] + (q[1] - (cxp - r)) / (2 * r) * (capR[3] - capR[1]),
                  capR[2] + (q[2] - (czp - r)) / (2 * r) * (capR[4] - capR[2]) }
              end
              for k = 1, NS - 2 do
                local a, b, c = pts[0], pts[k], pts[k + 1]
                tri3(postList, { a[1], y1p, a[2] }, cuv(a), UP, { c[1], y1p, c[2] }, cuv(c), UP, { b[1], y1p, b[2] }, cuv(b), UP)
              end
              fencePosts = fencePosts + 1
            end
          end)()
        elseif isFence and uv then
          local L, R = fenceLink(at(x - 1, y)), fenceLink(at(x + 1, y))
          local U, D = fenceLink(at(x, y - 1)), fenceLink(at(x, y + 1))
          local hasEW, hasNS = L or R, U or D
          local fy0, fy1 = groundY, groundY + C.FENCE_H
          local nativeRail,nativePost,nativeCap,nativeList
          if cell.nativeBlueFence and type(atlas.w)=="number" and atlas.w>0
              and type(atlas.h)=="number" and atlas.h>0 then
            local middle=cell.mid==244 or cell.mid==245
            local right=cell.mid==237 or cell.mid==245 or cell.mid==852
            local r=middle and overRect(cell.mid) or underRect(cell.mid)
            local left=right and 10 or 2
            local function crop(x0,y0,x1,y1)
              local ax,ay=math.floor(r[1]*atlas.w),math.floor(r[2]*atlas.h)
              return {(ax+x0+.5)/atlas.w,(ay+y0+.5)/atlas.h,
                (ax+x1+.5)/atlas.w,(ay+y1+.5)/atlas.h}
            end
            if r then
              local top=cell.mid==236 or cell.mid==237
              nativeRail=crop(left, middle and 0 or top and 13 or 0,left+3,middle and 15 or top and 15 or 1)
              nativePost=crop(left,middle and 0 or 3,left+3,middle and 15 or 11)
              nativeCap=crop(left+1,middle and 2 or 3,left+2,middle and 3 or 4)
              nativeList=middle and cutoutOver or opaque
            end
          end
          local own = subRectV(uv, C.FENCE_V0, 1)
          local ewR = fenceEWMid and underRect(fenceEWMid) or uv
          -- r11 (review M9): a north-south run shows its own art, never
          -- the map-wide east-west fence tile (Route 8's pen)
          local ns = subRectV(uv, C.FENCE_V0, 1)
          local cxm, czm = x0 + 0.5, z0 + 0.5
          if cell.nativeStructure and cell.nativeStructure.kind=="metal" then cxm=x0+cell.nativeStructure.offset end
          local nEW, nNS = norm3({ 0, 1, 1 }), norm3({ 1, 1, 0 })
          local function rail(xa,za,xb,zb,y0,y1,r,n)
            if not nativeRail then return wallQuad(cutoutKeyed,xa,za,xb,zb,y0,y1,r,n) end
            -- Native NS pipe runs along the source row axis. Rotate that
            -- axis into the world run; its four-column width is 1/4 cell.
            local P={{xa,y1-.25,za},{xb,y1-.25,zb},{xb,y1,zb},{xa,y1,za}}
            local T={{nativeRail[3],nativeRail[2]},{nativeRail[3],nativeRail[4]},
              {nativeRail[1],nativeRail[4]},{nativeRail[1],nativeRail[2]}}
            tri3(nativeList,P[1],T[1],n,P[2],T[2],n,P[3],T[3],n)
            tri3(nativeList,P[1],T[1],n,P[3],T[3],n,P[4],T[4],n)
          end
          if not hasEW and not hasNS then
            rail( x0, czm, x1, czm, fy0, fy1, own, nEW)
          else
            if L and R then rail( x0, czm, x1, czm, fy0, fy1, own, nEW)
            elseif L then rail( x0, czm, cxm, czm, fy0, fy1, subRect(own, 0, 0, 0.5, 1), nEW)
            elseif R then rail( cxm, czm, x1, czm, fy0, fy1, subRect(own, 0.5, 0, 1, 1), nEW) end
            if U and D then rail( cxm, z0, cxm, z1, fy0, fy1, ns, nNS)
            elseif U then rail( cxm, z0, cxm, czm, fy0, fy1, subRect(ns, 0, 0, 0.5, 1), nNS)
            elseif D then rail( cxm, czm, cxm, z1, fy0, fy1, subRect(ns, 0.5, 0, 1, 1), nNS) end
          end
          local nl = (L and 1 or 0) + (R and 1 or 0) + (U and 1 or 0) + (D and 1 or 0)
          if nl <= 1 or (hasEW and hasNS) then
            -- r11 (review M9): a post is a box FENCE_POST_BOX thick with a
            -- top cap (was two crossed cards), its faces off the rail
            -- planes by the box half width
            local pw = C.FENCE_POST_BOX * 0.5
            local post = subRect(uv, 6 / 16, C.FENCE_V0, 10 / 16, 1)
            local py1 = fy1 + 0.06
            for _, e in ipairs({ "down", "up", "left", "right" }) do
              faceQuad(nativeList or opaque, e, cxm - pw, cxm + pw, czm - pw, czm + pw, fy0, py1, nativePost or post)
            end
            hQuad(nativeList or opaque, cxm - pw, czm - pw, cxm + pw, czm + pw, py1, nativeCap or subRect(uv, 6 / 16, C.FENCE_V0, 10 / 16, C.FENCE_V0 + 0.1))
          end
          fenceCells = fenceCells + 1
        end
        if gameFenceStart then
          grid.gameFenceRanges=grid.gameFenceRanges or {}
          grid.gameFenceRanges[#grid.gameFenceRanges+1]={gameFenceStart,{#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed}}
        end

        -- M2 forest base, r9 Part B: the understory closure. Each tree-cell
        -- edge facing an in-grid non-tree cell ("out") gets a wall of deep
        -- shade (MB.SHADE_SWATCH) FOREST_UNDER_INSET inside the edge -- behind the edge
        -- unit's trunk, under its crown -- FOREST_UNDER_H tall, with a
        -- downward normal (ambient only: shadowed understory, not a lit wall). Skipped
        -- when the unit is open on both sides of either axis (a one-unit
        -- tree line: you see under it to the ground beyond). Convex corners are
        -- trimmed, concave corners extended until the two walls meet, so
        -- the closure has no slits. The ring's outer edge ("in") keeps the
        -- M2 wall (inset 0.25, 1.35 tall, facing inward).
        -- r11 (review M3): the wall is DARK LEAF (not the black shade
        -- swatch), lit with outward normals, deeper (inset FOREST_UNDER_
        -- INSET*) and lower (FOREST_UNDER_H*); a blob tree open on 3 or 4
        -- sides (a lone tree, a tree-line end) gets none.
        local nOpenOut = 0
        if cell.blobTree and not cell.bush and not farBlob then
          for _, m in pairs(underSidesOf(cell)) do if m == "out" then nOpenOut = nOpenOut + 1 end end
        end
        if not grid.isCompiledShrub(cell) and not grid.indigoRailCells[cell] and not cell.nativeSafariWestOverlay and not cell.nativeSafariWestForest and not cell.nativeSafariNorthForest and not grid.frNativeUnit(cell) and (isTreeUnit or (cell.blobTree and not cell.bush and not farBlob and nOpenOut < 3)) and uv then
          local base = darkSw or shadeSw or (sw and subRect(sw, 0, C.FOREST_BASE_V0, 1, 1)) or subRectV(uv, C.FOREST_BASE_V0, 1)
          if f3 and isForest3Mid(cell.mid) then base = f3.dark or f3.shade or base end
          if IN.flora then base = IN.flora:underUv(f3 ~= nil and isForest3Mid(cell.mid)) or base end -- W7
          local open = underSidesOf(cell)
          local ins = underInset(cell)
          local function sideIns(side) return open[side] == "in" and C.FOREST_BASE_INSET or ins end
          -- along-wall extent at the end toward `e`: convex corner -> trim
          -- by that side's inset; concave corner -> extend to the diagonal
          -- cell's wall; else the cell edge
          local function endAt(d, e, edgeCoord, sign)
            if open[e] then return edgeCoord - sign * sideIns(e) end
            if open[d] ~= "out" then return edgeCoord end
            local q = DIR_BY[e]
            local nb = at(x + q.dx, y + q.dy)
            -- r10: the wall continues on the neighbour at another depth
            -- (a single / 2x2 / blob tree next to each other): overlap the
            -- two by that depth difference, so no diagonal slips between
            if isForestCell(nb) and underSidesOf(nb)[d] == "out" then
              local dIns = math.abs(underInset(nb) - sideIns(d))
              return edgeCoord + sign * dIns
            end
            if isForestCell(nb) and not underSidesOf(nb)[d] then
              local dd = DIR_BY[d]
              local dc = at(nb.x + dd.dx, nb.y + dd.dy)
              if isForestCell(dc) and underSidesOf(dc)[OPP[e]] == "out" then
                return edgeCoord + sign * underInset(dc)
              end
              -- r10: dc is forest but unwalled (a see-through tree line,
              -- e.g. a 3-wide Viridian Forest column, leaves this forest
              -- edge): carry the wall under that line to its unit's middle,
              -- where the wall from the line's other side meets it
              if isForestCell(dc) and nb.unit and nb.unit ~= cell.unit then
                local u2 = nb.unit
                if d == "up" or d == "down" then return u2.x + u2.w * 0.5 end
                return u2.y + (u2.h or u2.w) * 0.5
              end
            end
            return edgeCoord
          end
          for _, d in ipairs(DIRS) do
            local mode = open[d.name]
            if mode then
              local i = sideIns(d.name)
              local a1, a2, b1, b2, n
              if d.name == "down" or d.name == "up" then
                local lo, hi = endAt(d.name, "left", x0, -1), endAt(d.name, "right", x1, 1)
                if d.name == "down" then a1, a2, b1, b2, n = lo, z1 - i, hi, z1 - i, N_S
                else a1, a2, b1, b2, n = hi, z0 + i, lo, z0 + i, N_N end
              else
                local lo, hi = endAt(d.name, "up", z0, -1), endAt(d.name, "down", z1, 1)
                if d.name == "left" then a1, a2, b1, b2, n = x0 + i, lo, x0 + i, hi, N_W
                else a1, a2, b1, b2, n = x1 - i, hi, x1 - i, lo, N_E end
              end
              local y1
              if mode == "in" then
                n = { -n[1], -n[2], -n[3] }
                y1 = groundY + C.FOREST_BASE_H
              else
                -- r11 (review M3): outward normal (lit foliage, not a
                -- black band); n is already the side's outward normal
                y1 = groundY + underHeight(cell)
                if IN.flora then n = IN.flora.UNDER_NORMAL end -- W7: shade, not a lit wall
              end
              wallQuad(opaque, a1, a2, b1, b2, groundY, y1, base, n)
            end
          end
        end

        -- Non-tree solid blobs (rocks, cliffs, bushes): small per-cell crown
        -- with the cell's own tile (legacy shape; W3 density rule).
        if grid.isCompiledShrub(cell) and uv then
          grid.compiledShrubs.crown(cell,uv,opaque)
        elseif farBlob and uv then
          -- r8 cost: a blob cell deep in a border ring (>= BORDER_FAR_CELLS
          -- from where the player can be) is a flat canopy top at the dense
          -- crown's height -- the near crowns hide its edge.
          hQuad(opaque, x0, z0, x1, z1, groundY + C.BLOB_TOP * 0.8, subRect(uv, 0, 0, 1, 0.75))
          -- r11 (review M12): a dark skirt from the ground to the plate on
          -- every side not facing another far plate: no sky / sea band
          -- under the border canopy, no plate underside from eye height
          local skirt = darkSw or subRect(uv, 0, 0.5, 1, 1)
          for _, d in ipairs(DIRS) do
            local nx, ny = x + d.dx, y + d.dy
            local nc = at(nx, ny)
            local nIsFar = nc and nc.blobTree and farBorderCell(nx, ny)
            if not nIsFar and nx >= 0 and ny >= 0 and nx < W and ny < H then
              faceQuad(opaque, d.name, x0, x1, z0, z1, groundY, groundY + C.BLOB_TOP * 0.8, skirt)
            end
          end
          farTrees = farTrees + 1
        elseif isBlob and uv and grid.isNativeShrub(cell) then
          grid.shrub5Crown(cell,uv)
        elseif isBlob and uv and not grid.indigoRailCells[cell] and not cell.nativeSafariWestOverlay and not cell.nativeSafariWestForest and not cell.nativeSafariNorthForest then
          local n = cell.blobN or 0
          local dense = n >= 3
          local tiers = dense and { { { 1.0, 0.55 }, { 0.64, 0.92 } } }
            or { { { 0.36, 0.25 }, { 1.0, 0.55 }, { 0.64, 0.92 } } }
          -- r11 (review M8): a bush sits on the ground -- its first ring is
          -- at y = 0 (0.65 R), no gap between the ball and its shadow
          if cell.bush then tiers = { { { 0.65, 0.0 }, { 1.0, 0.45 }, { 0.64, 0.92 } } } end
          -- an isolated blob cell is a bush, not a tree (r7m: Viridian's
          -- round bushes and the bushes peeled off the green houses)
          local r, top = C.BLOB_R, C.BLOB_TOP
          local bush = cell.bush
          if bush then r, top = C.BUSH_R, C.BUSH_TOP end
          local bsw = subRect(uv, 0, 0, 1, 0.75)
          -- r11: a tile whose art is (almost) all over art has a black /
          -- empty under layer: texture the blob from the over layer
          local blist = opaque
          local bov = cell.hasOver and overRect(cell.mid) or nil
          if bov and (overCoverage(cell.mid) or 1) >= 0.9 then blist, bsw = cutoutOver, subRect(bov, 0, 0, 1, 0.75) end
          if bush then
            crown(blist, x0 + 0.5, groundY, z0 + 0.5, r, top, C.BLOB_SIDES, tiers, false,
              bsw, hash01(x, y, 61) * math.pi, x * 131 + y)
          else
            -- r9 Part B: blob trees (secondary-tileset forests: Viridian
            -- Forest, Route 23, Saffron) are round domes, no pointed apex.
            -- On the forest EDGE (any in-grid non-forest neighbour): -40/25
            -- deg, closed underneath (24 tris), the understory closure
            -- behind it (M2 block above). Inside: 0/50 deg, no bottom (18
            -- tris, the r8 dense cost).
            local edge = next(forestOpen(cell)) ~= nil
            local b = top * (edge and 0.325 or 0.4)
            dome(blist, x0 + 0.5, groundY + top - b, z0 + 0.5, r, b, C.BLOB_SIDES,
              edge and BLOB_LAT_EDGE or BLOB_LAT_DENSE, { bsw }, bsw, edge and bsw or nil,
              hash01(x, y, 61) * math.pi, x * 131 + y)
            -- r11 (review M3): an edge blob tree has a trunk, pushed toward
            -- its open sides so it stands in front of the understory wall
            if edge then
              local o = forestOpen(cell)
              local tx = x0 + 0.5 + ((o.right and 1 or 0) - (o.left and 1 or 0)) * 0.2
              local tz = z0 + 0.5 + ((o.down and 1 or 0) - (o.up and 1 or 0)) * 0.2
              local bark = barkSw or subRectV(uv, 0.55, 1.0)
              local tw = C.TREE_TRUNK_W * 0.8
              local tTop = groundY + top - b - 0.5 * b
              for _, d in ipairs(DIRS) do
                faceQuad(opaque, d.name, tx - tw, tx + tw, tz - tw, tz + tw, groundY, tTop, bark)
              end
              blobTrunks = blobTrunks + 1
            end
          end
        end
      end
    end
  end
  end -- Route12 exact prop-emitter suppression
  end -- (pass 3 helpers scoped: M.build is near the 200-locals limit)

  -- ---------------------------------------------------------------
  -- Pass 3i (r8 interiors; r12 review M4 / M14 / M15): walls, synthetic
  -- walls, furniture boxes, statues, boulders, plants.
  --   wall runs : south face = the run's bottom 2 rows (lower band 0-1 =
  --               bottom row, upper band 1-INDOOR_WALL_H = the row above);
  --               a door in wall row 2 is inset DOOR_INSET under a flush
  --               header; cap = the rows behind the face stretched over
  --               the run (shorter runs: the top cell's top edge rows; side
  --               walls: dark); W / E faces = a WALL_STRIP_TEXELS strip
  --               WALL_STRIP_SKIP texels in from that edge of the column's
  --               face art
  --               (M15 interim), a side wall's inward face its own tile
  --               turned (outer edge up: the edge strip becomes a top band);
  --               north faces = the column's face art.
  --   M15       : a back wall stepping 1-2 columns per row for >= 2 steps
  --               is one slanted wall through the steps' inner corners
  --               (each column's face art on its stretch of the slope); the
  --               wall cells' front triangles become floor, caps clipped.
  --   synthetic : a floor-level cell with void / off-map / an exit frame
  --               to its W, E or N gets a wall SYNTH_WALL_INSET inside that
  --               edge (the room's plain back-wall art as a strip, dark cap);
  --               to its S the same wall goes to geom.southWalls; a door
  --               cell (the exit mat) there gets none (the doorway gap).
  --   furniture : top = the column's north rows' art stretched over the
  --               column (single rows: own art), front = its south row (or
  --               the borrowed front tile), W / E / N faces = plain edge
  --               strips; Game Corner slots (MB.INDOOR_PROPS kind "slot"):
  --               the reel strip turned onto the W / E faces.
  --   statue    : plinth (the sign tile's art) + two crossed upright cards
  --               of the figure's over art (cutoutOver).
  --   boulder   : floor + a tapered rock BOULDER_H_MIN..MAX high, every
  --               face from the tile's floor-free rect (TILE_SHAPES sw).
  -- ---------------------------------------------------------------
  -- r12 (refs 09 / 10, review: "cylinder bins"): a one-cell piece of
  -- furniture whose art is a ROUND object on the floor -- its four corner
  -- texels one colour, its top and bottom rows narrower than its middle
  -- (the gyms' cans) -- is a CYLINDER BIN_SEGS around, as wide as its widest
  -- drawn row, its group's height tall: the upper half of the art's rows
  -- (the lid, seen from above) laid on the top disc by plan position, the
  -- lower half down the side by height; the floor under it is the nearest
  -- floor tile. (on IN: M.build is at LuaJIT's locals limit) -> true if
  -- drawn.
  -- r12 (ref 09): a GATE cell's bands become glowing bars standing in
  -- one plane at the centre of the gate's bottom row: the lowest band the
  -- lowest bar (GATE_BAR_H0 up, then GATE_BAR_STEP apart), each as tall
  -- as its rows (x 0.6) and GATE_BAR_T deep, its art the band's rows; the
  -- floor under it is the room's floor (pass 3 ground).
  IN.gate = function(c, x, y, g)
    local r = underRect(c.mid)
    if not r then return end
    -- the gate's column: its bottom row, and the bands of every gate cell
    -- of this column from the top down (absolute rows, lowest last)
    local yb = y
    while at(x, yb + 1) and at(x, yb + 1).role == "gate" do yb = yb + 1 end
    local ya = y
    while at(x, ya - 1) and at(x, ya - 1).role == "gate" do ya = ya - 1 end
    local all = {}
    for yy = ya, yb do
      for _, b in ipairs(at(x, yy).gateBands) do all[#all + 1] = { yy, b[1], b[2] } end
    end
    local zc = yb + 0.5
    local T = C.GATE_BAR_T * 0.5
    for k, b in ipairs(all) do
      if b[1] == y then
        local fromBottom = #all - k
        local th = (b[3] - b[2] + 1) / 16 * 0.6
        local yc = g + C.GATE_BAR_H0 + C.GATE_BAR_STEP * fromBottom
        local br = subRect(r, 0, b[2] / 16, 1, (b[3] + 1) / 16)
        local x0, x1 = x + 0.0, x + 1.0
        faceQuad(opaque, "down", x0, x1, zc - T, zc + T, yc - th * 0.5, yc + th * 0.5, br)
        faceQuad(opaque, "up", x0, x1, zc - T, zc + T, yc - th * 0.5, yc + th * 0.5, br)
        hQuad(opaque, x0, zc - T, x1, zc + T, yc + th * 0.5, br)
        hQuad(opaque, x0, zc - T, x1, zc + T, yc - th * 0.5, br, DOWN)
        for _, e in ipairs({ { "left", -1 }, { "right", 1 } }) do
          local n = at(x + e[2], y)
          if not (n and n.role == "gate") then
            faceQuad(opaque, e[1], x0, x1, zc - T, zc + T, yc - th * 0.5, yc + th * 0.5, br)
          end
        end
      end
    end
  end
  -- r12 (refs 08-11): a PILLAR: drawn once, on its group's bottom cell --
  -- a column PILLAR_INSET in from the cell's edges; the group's other
  -- cells show the floor
  IN.pillar = function(c, x, y, g)
    local ST = C.WALL_STRIP_TEXELS / 16
    local grp = c.group
    local fl = underRect(floorMid)
    if y ~= grp.maxY then
      if fl then hQuad(opaque, x + 0.0, y + 0.0, x + 1.0, y + 1.0, g, fl) end
      return
    end
    local cells = {}
    for yy = grp.minY - 1, grp.maxY do cells[#cells + 1] = at(x, yy) end
    local n = #cells
    local Ht = math.min(C.INDOOR_WALL_H, n * C.PILLAR_ROW_H)
    local ins = C.PILLAR_INSET
    local x0, x1, z0, z1 = x + ins, x + 1 - ins, y + ins, y + 1 - ins
    if fl then hQuad(opaque, x + 0.0, y + 0.0, x + 1.0, y + 1.0, g, fl) end
    -- slices bottom -> top: cells[n] is the base, cells[1] the capital
    for k = 1, n do
      local q = cells[n - k + 1]
      local ya, yb = g + Ht * (k - 1) / n, g + Ht * k / n
      local list, rr = opaque, underRect(q.mid)
      if q == grp.pillar.cap then
        -- the capital: its over art (drawn on the floor tile above)
        local ov = overRect(q.mid)
        if ov then list, rr = cutoutOver, ov end
        if list == cutoutOver then
          -- (its under is the floor: the column's own top slice underneath)
          local r2 = underRect(cells[2].mid)
          if r2 then
            for _, dn in ipairs({ "down", "left", "right", "up" }) do
              faceQuad(opaque, dn, x0, x1, z0, z1, ya, yb, subRect(r2, 0, 0, 1, 0.1))
            end
          end
        end
      end
      if rr then
        local lift = list == cutoutOver and C.FACADE_OVER_LIFT or 0
        faceQuad(list, "down", x0, x1, z0, z1 + lift, ya, yb, rr)
        faceQuad(list, "left", x0 - lift, x1, z0, z1, ya, yb, subRect(rr, 0, 0, ST, 1))
        faceQuad(list, "right", x0, x1 + lift, z0, z1, ya, yb, subRect(rr, 1 - ST, 0, 1, 1))
        faceQuad(list, "up", x0, x1, z0 - lift, z1, ya, yb, subRect(rr, 0, 0, 1, ST))
      end
    end
    local tr = underRect(cells[math.min(2, n)].mid)
    if tr then hQuad(opaque, x0, z0, x1, z1, g + Ht, subRect(tr, 0, 0, 1, ST)) end
    indoorStats.pillarsDrawn = (indoorStats.pillarsDrawn or 0) + 1
  end
  -- r12 (ref 11): extrude a wall face's pilasters PILASTER_D proud of it:
  -- front = the pilaster's texel columns (lower / upper face tile), sides =
  -- its edge column, top = its capital rows' colour (the upper tile's row 3)
  IN.pilasters = function(c, up, x0, x1, z1, g)
    local pl = IN.pilasterOf(up.mid, c.mid)
    if not pl then return end
    local WHh = C.INDOOR_WALL_H
    local D = C.PILASTER_D
    for _, side in ipairs({ "left", "right" }) do
      local w = pl[side]
      if w then
        local over = pl[side == "left" and "overL" or "overR"]
        local list = over and cutoutOver or opaque
        local rL = over and overRect(c.mid) or underRect(c.mid)
        local rU = over and overRect(up.mid) or underRect(up.mid)
        if rL and rU then
          local f = w / 16
          local ua, ub = 0, f
          local px0, px1 = x0, x0 + f
          if side == "right" then ua, ub, px0, px1 = 1 - f, 1, x1 - f, x1 end
          local zf = z1 + D
          wallQuad(list, px0, zf, px1, zf, g, g + 1.0, subRect(rL, ua, 0, ub, 1), N_S)
          wallQuad(list, px0, zf, px1, zf, g + 1.0, g + WHh, subRect(rU, ua, 0, ub, 1), N_S)
          -- sides: the outer / inner edge columns
          local eo = side == "left" and 0.5 / 16 or 15.5 / 16
          local ei = side == "left" and (w - 0.5) / 16 or (16 - w + 0.5) / 16
          wallQuad(list, px0, z1, px0, zf, g, g + 1.0, subRect(rL, side == "left" and eo or ei, 0, side == "left" and eo or ei, 1), N_W)
          wallQuad(list, px0, z1, px0, zf, g + 1.0, g + WHh, subRect(rU, side == "left" and eo or ei, 0, side == "left" and eo or ei, 1), N_W)
          wallQuad(list, px1, zf, px1, z1, g, g + 1.0, subRect(rL, side == "left" and ei or eo, 0, side == "left" and ei or eo, 1), N_E)
          wallQuad(list, px1, zf, px1, z1, g + 1.0, g + WHh, subRect(rU, side == "left" and ei or eo, 0, side == "left" and ei or eo, 1), N_E)
          local mu = (ua + ub) * 0.5
          hQuad(list, px0, z1, px1, zf, g + WHh, subRect(rU, mu, 3.5 / 16, mu, 3.5 / 16))
          indoorStats.pilasters = (indoorStats.pilasters or 0) + 1
        end
      end
    end
  end
  IN.bin = function(c, x, y, g)
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    local u = tex and not c.hasOver and tex(c.mid, "under")
    if not u then return false end
    local gcol = u[1]
    if u[16] ~= gcol or u[241] ~= gcol or u[256] ~= gcol then return false end
    local lo16, hi16, t0, b0, wmax = {}, {}, nil, nil, 0
    for row = 0, 15 do
      local lo, hi
      for col = 0, 15 do
        if u[row * 16 + col + 1] ~= gcol then lo = lo or col; hi = col end
      end
      lo16[row], hi16[row] = lo or 7, (hi or 8) + 1
      if lo then
        t0 = t0 or row
        b0 = row
        wmax = mmax(wmax, (hi - lo + 1) / 16)
      end
    end
    if not t0 or b0 - t0 < 10 then return false end
    local wt, wb = (hi16[t0] - lo16[t0]) / 16, (hi16[b0] - lo16[b0]) / 16
    if wt > wmax - 0.2 or wb > wmax - 0.2 or wmax < 0.6 then return false end
    local fl
    for _, d in ipairs(DIRS) do
      local n = at(x + d.dx, y + d.dy)
      if n and n.walkable and not n.isWater and n.role ~= "wall" then fl = underRect(n.mid) if fl then break end end
    end
    local r = underRect(c.mid)
    if not (fl and r) then return false end
    local R = mmin(0.46, wmax * 0.5)
    local Ht = c.group.h
    local cx, cz = x + 0.5, y + 0.5
    local mid = (t0 + b0 + 1) * 0.5 -- the lid's rows above, the side's below
    local ur, vr = r[3] - r[1], r[4] - r[2]
    local function uvAt(row, f)
      if row < t0 + 0.5 then row = t0 + 0.5 elseif row > b0 + 0.5 then row = b0 + 0.5 end
      local ri = mfloor(row)
      local col = lo16[ri] + (hi16[ri] - lo16[ri]) * mmax(0.02, mmin(0.98, f))
      return r[1] + col / 16 * ur, r[2] + row / 16 * vr
    end
    hQuad(opaque, x + 0.0, y + 0.0, x + 1.0, y + 1.0, g, fl)
    local SEG = C.BIN_SEGS
    local ctu, ctv = uvAt((t0 + mid) * 0.5, 0.5)
    local centre = newV(cx, g + Ht, cz, ctu, ctv, 0, 1, 0)
    for j = 0, SEG - 1 do
      local p1 = j / SEG * math.pi * 2
      local p2 = (j + 1) / SEG * math.pi * 2
      local c1, s1, c2, s2 = math.cos(p1), math.sin(p1), math.cos(p2), math.sin(p2)
      -- side: the lower rows by height (front view)
      local ua1, va1 = uvAt(b0 + 0.5, 0.5 + 0.5 * c1)
      local ua2 = uvAt(b0 + 0.5, 0.5 + 0.5 * c2)
      local ub1, vb1 = uvAt(mid, 0.5 + 0.5 * c1)
      local ub2 = uvAt(mid, 0.5 + 0.5 * c2)
      local A = newV(cx + c1 * R, g, cz + s1 * R, ua1, va1, c1, 0, s1)
      local B = newV(cx + c2 * R, g, cz + s2 * R, ua2, va1, c2, 0, s2)
      local Cc = newV(cx + c2 * R, g + Ht, cz + s2 * R, ub2, vb1, c2, 0, s2)
      local D = newV(cx + c1 * R, g + Ht, cz + s1 * R, ub1, vb1, c1, 0, s1)
      local m = #opaque
      opaque[m + 1], opaque[m + 2], opaque[m + 3], opaque[m + 4], opaque[m + 5], opaque[m + 6] = A, Cc, B, A, D, Cc
      -- lid: the upper rows by plan position (north -> the top row)
      local l1u, l1v = uvAt(t0 + (mid - t0) * (0.5 + 0.5 * s1), 0.5 + 0.5 * c1)
      local l2u, l2v = uvAt(t0 + (mid - t0) * (0.5 + 0.5 * s2), 0.5 + 0.5 * c2)
      local E = newV(cx + c1 * R, g + Ht, cz + s1 * R, l1u, l1v, 0, 1, 0)
      local F = newV(cx + c2 * R, g + Ht, cz + s2 * R, l2u, l2v, 0, 1, 0)
      m = #opaque
      opaque[m + 1], opaque[m + 2], opaque[m + 3] = E, centre, F
    end
    indoorStats.bins = indoorStats.bins + 1
    return true
  end
  local darkUv = underRect(voidMid or 0)
  if darkUv then darkUv = subRect(darkUv, 0.25, 0.25, 0.75, 0.75) end
  -- r12 (interiors round, "dim and grey with a black surround"): WALL-TOP
  -- RIMS. FRLG draws a wall seen from above as the void colour bounded by a
  -- light strip (its rim: Vermilion's side columns = 10 black texels + a
  -- 6-texel white strip; Silph's partitions = strip | black | black | strip).
  -- A tile whose visible art is >= 25% void colour and holds a strip (a
  -- contiguous run of 3-12 non-void columns across its middle row, else
  -- rows down its middle column) caps its wall with that strip stretched
  -- over the cap -- a light cap, not a black hole; IN.rimUv (the first rim's
  -- centre texel) caps void-only wall tops and synthetic walls.
  -- IN.rimOf(mid) -> { rect, vertical } | false (cached).
  IN.rimCache = {}
  -- r12 (pre-lab-7 desktop capture: over-art caps were HOLES -- a rim
  -- strip 6-8 texels wide in the OVER atlas, stretched over a cell, is
  -- mip-averaged with the transparent texels around it and falls under the
  -- cutout threshold): an over-art rim is capped instead with ONE texel of
  -- its main colour found in the room's UNDER art (the plain wall tiles, the
  -- floor), in the opaque list -- the centre of a 3 x 3 block of that colour
  -- (mip-safe); none: the plain upper wall's top row. -> rect | nil
  IN.solidC = {}
  IN.solidUnder = function(col)
    local e = IN.solidC[col]
    if e ~= nil then return e or nil end
    e = false
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    for _, m in ipairs({ IN.wallUpper, IN.wallLower, floorMid }) do
      local u = m and tex and tex(m, "under")
      local r = m and underRect(m)
      if u and r and not e then
        for row = 1, 14 do
          for cc = 1, 14 do
            local ok = true
            for dy = -1, 1 do
              for dx = -1, 1 do
                if u[(row + dy) * 16 + cc + dx + 1] ~= col then ok = false end
              end
            end
            if ok then
              e = subRect(r, (cc + 0.5) / 16, (row + 0.5) / 16, (cc + 0.5) / 16, (row + 0.5) / 16)
              break
            end
          end
          if e then break end
        end
      end
    end
    IN.solidC[col] = e
    return e or nil
  end
  IN.overRimCap = function(mid, c0, c1, r0, r1)
    -- the strip's most common over colour
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    local o = tex and tex(mid, "over")
    local cnt, best, bn = {}, nil, 0
    if o then
      for row = r0, r1 do
        for cc = c0, c1 do
          local v = o[row * 16 + cc + 1]
          if v and v >= 0 then
            cnt[v] = (cnt[v] or 0) + 1
            if cnt[v] > bn then best, bn = v, cnt[v] end
          end
        end
      end
    end
    local q = best and IN.solidUnder(best)
    if q then return q end
    if IN.wallUpper then return IN.topRows(IN.wallUpper, 1 / 16) end
    return nil
  end
  IN.rimOf = function(mid)
    local e = IN.rimCache[mid]
    if e ~= nil then return e end
    e = false
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    local u = tex and tex(mid, "under")
    local vu = tex and voidMid and tex(voidMid, "under")
    if u and vu then
      local voidC = vu[1]
      local o = midHasOver(mid) and tex(mid, "over") or nil
      local function vis(i)
        local v = o and o[i] or -1
        if v >= 0 then return v, true end
        return u[i], false
      end
      local nv = 0
      for i = 1, 256 do if vis(i) == voidC then nv = nv + 1 end end
      if nv >= 0.25 * 256 then -- (r12 pre-lab-7: 25% -- Silph's card-key door tops, 964 / 965, carry the partition top in a quarter)
        local function run(idx)
          local a, b, gap = nil, nil, false
          for k = 0, 15 do
            if vis(idx(k)) ~= voidC then
              if b and b < k - 1 then gap = true end
              a = a or k
              b = k
            end
          end
          if a and not gap and b - a + 1 >= 3 and b - a + 1 <= 12 then return a, b end
          return nil
        end
        -- (r12 pre-lab-7: first the BOUNDING BOX of the non-void texels,
        -- when >= 75% of it is non-void -- a corner tile's strip is one
        -- quarter of it (Silph's 664); else the middle row's / column's run)
        local c0, c1, r0, r1, nn = 16, -1, 16, -1, 0
        for i = 1, 256 do
          if vis(i) ~= voidC then
            local cc, rr0 = (i - 1) % 16, math.floor((i - 1) / 16)
            nn = nn + 1
            if cc < c0 then c0 = cc end
            if cc > c1 then c1 = cc end
            if rr0 < r0 then r0 = rr0 end
            if rr0 > r1 then r1 = rr0 end
          end
        end
        if nn >= 12 and nn >= 0.75 * (c1 - c0 + 1) * (r1 - r0 + 1) and (c1 - c0 < 15 or r1 - r0 < 15) then
          local mi = math.floor((r0 + r1) / 2) * 16 + math.floor((c0 + c1) / 2) + 1
          local fromOver = u[mi] == voidC
          local rr = underRect(mid)
          if rr then
            e = { rect = subRect(rr, c0 / 16, r0 / 16, (c1 + 1) / 16, (r1 + 1) / 16), vertical = (r1 - r0) >= (c1 - c0) }
            if fromOver then
              local q = IN.overRimCap(mid, c0, c1, r0, r1)
              if q then e.rect = q end
            end
            if not IN.rimUv then
              IN.rimUv = subRect(e.rect, 0.5, 0.5, 0.5, 0.5)
              IN.rimUv.over = e.rect.over
            end
            IN.rimCache[mid] = e
            return e
          end
        end
        local a, b = run(function(k) return 8 * 16 + k + 1 end)
        local vertical = a ~= nil
        if not a then a, b = run(function(k) return k * 16 + 8 + 1 end) end
        if a then
          local mi = vertical and (8 * 16 + math.floor((a + b) / 2) + 1) or (math.floor((a + b) / 2) * 16 + 8 + 1)
          -- (r12 pre-lab-7 tour: the under art where it draws the strip
          -- too, else the OVER art -- drawn in cutoutOver: the over atlas
          -- shares the under atlas's UV layout, so an over rect in the
          -- opaque list samples the under art -- Silph's black caps)
          local fromOver = u[mi] == voidC
          local rr = underRect(mid)
          if rr then
            if vertical then e = { rect = subRect(rr, a / 16, 0, (b + 1) / 16, 1), vertical = true }
            else e = { rect = subRect(rr, 0, a / 16, 1, (b + 1) / 16), vertical = false } end
            if fromOver then
              local q = vertical and IN.overRimCap(mid, a, b, 0, 15) or IN.overRimCap(mid, 0, 15, a, b)
              if q then e.rect = q end
            end
            if not IN.rimUv then
              IN.rimUv = subRect(e.rect, 0.5, 0.5, 0.5, 0.5)
              IN.rimUv.over = e.rect.over
            end
          end
        else
          e = "void"
        end
      end
    end
    IN.rimCache[mid] = e
    return e
  end
  -- a cap quad from a void-dominated tile: its rim, else the room's rim
  -- colour; nil when the tile is not void-dominated (draw its own art)
  IN.rimCap = function(mid)
    local e = IN.rimOf(mid)
    if e == false then return nil end
    if e ~= "void" then return e.rect end
    return IN.rimUv or darkUv
  end
  if deps.debugRoles then indoorStats.rimOf = IN.rimOf end -- (debug: the rim finder)
  -- r12 (pre-lab-7 tour): a short run's cap = its top cell's first texel
  -- rows that are NOT the void colour (the League rooms' 643 draws 5 void
  -- rows above its band), in the layer that draws them (rect.over)
  IN.topRows = function(mid, ST)
    local r = underRect(mid)
    if not r then return nil end
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    local u = tex and tex(mid, "under")
    local vu = tex and voidMid and tex(voidMid, "under")
    if not (u and vu) then return subRect(r, 0, 0, 1, ST) end
    local voidC = vu[1]
    local o = midHasOver(mid) and tex(mid, "over") or nil
    for row = 0, 15 do
      local nv, no = 0, 0
      for col = 1, 16 do
        local i = row * 16 + col
        local ov = o and o[i] and o[i] >= 0
        if (ov and o[i] or u[i]) ~= voidC then nv = nv + 1 end
        if ov then no = no + 1 end
      end
      if nv >= 12 then
        if row == 0 then return subRect(r, 0, 0, 1, ST) end
        local useOver = no >= 12 and u[row * 16 + 8] == voidC
        local rr = useOver and overRect(mid) or r
        if not rr then return subRect(r, 0, 0, 1, ST) end
        local q = subRect(rr, 0, row / 16, 1, math.min(1, row / 16 + ST))
        q.over = useOver or nil
        return q
      end
    end
    return subRect(r, 0, 0, 1, ST)
  end
  -- the first texel row of a tile that is not the void colour (0: none /
  -- no texels) -- a cap stretched from it skips its void rows
  IN.firstRowC = {}
  IN.firstRow = function(mid)
    local e = IN.firstRowC[mid]
    if e then return e end
    e = 0
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    local u = tex and tex(mid, "under")
    local vu = tex and voidMid and tex(voidMid, "under")
    if u and vu then
      local voidC = vu[1]
      local o = midHasOver(mid) and tex(mid, "over") or nil
      for row = 0, 15 do
        local nv = 0
        for col = 1, 16 do
          local i = row * 16 + col
          if ((o and o[i] and o[i] >= 0) and o[i] or u[i]) ~= voidC then nv = nv + 1 end
        end
        if nv >= 12 then e = row break end
      end
    end
    IN.firstRowC[mid] = e
    return e
  end
  -- r12 (ref 11, pre-lab-7: "Silph wall pilasters and partition ends"): a
  -- wall face's PILASTERS -- the upper + lower face tiles (32 texel rows)
  -- with a block of 4-8 texel columns at a tile edge, each column one colour
  -- over >= 90% of the rows below the top 6 (its capital) and the column
  -- next to it BANDED (>= 3 colour changes): Silph's partition ends 830 / 831 /
  -- 838 / 839, door posts. -> { left = w, right = w, overL, overR } | false
  IN.pilC = {}
  IN.pilasterOf = function(upMid, botMid)
    local key = upMid * 65536 + botMid
    local e = IN.pilC[key]
    if e ~= nil then return e end
    e = false
    local tex = type(atlas.texels) == "function" and atlas.texels or nil
    if tex then
      local under, over = {}, {}
      local okAll = true
      for k, m in ipairs({ upMid, botMid }) do
        local u = tex(m, "under")
        if not u then okAll = false break end
        local o = midHasOver(m) and tex(m, "over") or nil
        under[k], over[k] = u, o or false
      end
      if okAll then
        -- Most faces reject a pilaster at the first edge column. Composite
        -- only columns actually inspected, retaining them within this pair.
        local columns, overlays = {}, {}
        local function column(col)
          if columns[col] then return columns[col], overlays[col] end
          local values, flags, n = {}, {}, 0
          for k = 1, 2 do
            local u, o = under[k], over[k]
            for r = 0, 15 do
              local i = r * 16 + col
              local ov = o and o[i] and o[i] >= 0
              n = n + 1
              values[n], flags[n] = ov and o[i] or u[i], ov and true or false
            end
          end
          columns[col], overlays[col] = values, flags
          return values, flags
        end
        local function uniform(col)
          local values = column(col)
          local cnt, best = {}, 0
          for r = 7, 32 do
            local v = values[r]
            cnt[v] = (cnt[v] or 0) + 1
            if cnt[v] > best then best = cnt[v] end
          end
          return best >= 0.9 * 26
        end
        local res = {}
        for _, side in ipairs({ "left", "right" }) do
          local w = 0
          for k = 0, 15 do
            local col = side == "left" and (k + 1) or (16 - k)
            if uniform(col) then w = w + 1 else break end
          end
          -- (the wall beside it is BANDED: >= 3 colour changes down its
          -- next column -- a plain vertical pipe / post tile is not)
          local nc = side == "left" and (w + 1) or (16 - w)
          local changes = 0
          if w < 16 then
            local values = column(nc)
            for r = 8, 32 do if values[r] ~= values[r - 1] then changes = changes + 1 end end
          end
          if w >= 4 and w <= 8 and changes >= 3 then
            res[side] = w
            -- (drawn in the layer that draws its middle column)
            local mc = side == "left" and math.floor(w / 2) + 1 or 16 - math.floor(w / 2)
            local _, flags = column(mc)
            local no = 0
            for r = 7, 32 do if flags[r] then no = no + 1 end end
            res[side == "left" and "overL" or "overR"] = no >= 13
          end
        end
        if res.left or res.right then e = res end
      end
    end
    IN.pilC[key] = e
    return e
  end
  -- a cap quad in the rect's own layer (rect.over: the over atlas)
  IN.capQuad = function(x0, z0, x1, z1, y, rc)
    hQuad(rc.over and cutoutOver or opaque, x0, z0, x1, z1, y, rc)
  end
  local function artFaces(list, c, fn)
    -- base = the cell's under art; over art (if any) drawn in cutoutOver
    -- FACADE_OVER_LIFT in front (M14 pattern)
    local base = underRect(c.mid)
    if base then fn(opaque, base, 0) end
    local ov = c.hasOver and overRect(c.mid) or nil
    if ov then fn(cutoutOver, ov, C.FACADE_OVER_LIFT) end
  end
  if indoor then
    local southWalls = IN.southWalls
    local WH = C.INDOOR_WALL_H
    local ST = C.WALL_STRIP_TEXELS / 16
    local ins = C.SYNTH_WALL_INSET
    local plainU = IN.wallUpper and underRect(IN.wallUpper)
    local plainL = IN.wallLower and underRect(IN.wallLower)
    plainU = plainU and subRect(plainU, 0.5 - ST / 2, 0, 0.5 + ST / 2, 1) or darkUv
    plainL = plainL and subRect(plainL, 0.5 - ST / 2, 0, 0.5 + ST / 2, 1) or darkUv
    if IN.interiors then plainU, plainL = IN.interiors:bind(plainU, plainL, { floorMid = floorMid, voidMid = voidMid, darkUv = darkUv }) end -- interiors-team
    -- two bands on a wall from a to b: lower [g, g+1], upper [g+1, g+WH]
    local function bands(list, ax, az, bx, bz, g, rU, rL, n)
      if rL then wallQuad(list, ax, az, bx, bz, g, g + 1.0, rL, n) end
      if rU then wallQuad(list, ax, az, bx, bz, g + 1.0, g + WH, rU, n) end
    end
    local function faceBands(list, dname, x0, x1, z0, z1, g, rU, rL)
      local ax, az, bx, bz, n
      if dname == "down" then ax, az, bx, bz, n = x0, z1, x1, z1, N_S
      elseif dname == "up" then ax, az, bx, bz, n = x1, z0, x0, z0, N_N
      elseif dname == "left" then ax, az, bx, bz, n = x0, z0, x0, z1, N_W
      else ax, az, bx, bz, n = x1, z1, x1, z0, N_E end
      bands(list, ax, az, bx, bz, g, rU, rL, n)
    end
    -- the column face art of a wall cell: upper / lower cells of its run
    local function colFace(c)
      local x = c.x
      local bot = grid[c.runB][x]
      local up = (c.runB - 1 >= c.runA) and grid[c.runB - 1][x] or bot
      return up, bot
    end
    -- a synthetic wall on side d of cell c (strip SYNTH_WALL_INSET deep); a
    -- north / south strip stops at the cell's own west / east strips (no
    -- overlapping corner caps)
    local function synthWall(list, c, dname)
      local x0, z0, x1, z1 = c.x + 0.0, c.y + 0.0, c.x + 1.0, c.y + 1.0
      local bx0, bx1, bz0, bz1 = x0, x1, z0, z1
      if dname == "left" then bx1 = x0 + ins
      elseif dname == "right" then bx0 = x1 - ins
      else
        if dname == "up" then bz1 = z0 + ins else bz0 = z1 - ins end
        local wn, en = at(c.x - 1, c.y), at(c.x + 1, c.y)
        if not wn or wn.exitFrame then bx0 = x0 + ins end
        if not en or en.exitFrame then bx1 = x1 - ins end
      end
      faceBands(list, OPP[dname], bx0, bx1, bz0, bz1, c.hgt, plainU, plainL)
      local capR = IN.rimUv or darkUv -- (r12: the room's rim colour)
      -- (a south synthetic wall lives in geom.southWalls, hidden with it in
      -- the 3/4 view: its cap stays in that list -- an over-art rim cannot
      -- be drawn there, so it keeps the dark cap)
      if list == IN.southWalls and capR and capR.over then capR = darkUv end
      if capR then hQuad(capR.over and cutoutOver or list, bx0, bz0, bx1, bz1, c.hgt + WH, capR) end
      return bx0, bx1, bz0, bz1
    end

    -- r12 (pre-lab-7 tour: black synthetic-wall caps): the room's rim colour
    -- is found BEFORE any wall is drawn -- the first wall cell whose tile has
    -- a rim; no rim anywhere: the plain upper wall tile's top texel row
    if not IN.rimUv then
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if c and c.role == "wall" and not IN.rimUv then IN.rimOf(c.mid) end
        end
        if IN.rimUv then break end
      end
      if not IN.rimUv and IN.wallUpper then
        local r = underRect(IN.wallUpper)
        if r then IN.rimUv = subRect(r, 0.5, 0.5 / 16, 0.5, 0.5 / 16) end
      end
    end
    -- M15: staircase back walls -> slanted walls. Face segments = maximal
    -- horizontal runs of wall-run bottoms with a floor cell south.
    local diagOf = {} -- wall cell -> { wx, wz, ex, ez, nx, nz } (its slope stretch)
    do
      local segs, byL, byR = {}, {}, {}
      for y = 0, H - 1 do
        local x = 0
        while x < W do
          local c = grid[y][x]
          local s = at(x, y + 1)
          local function isFront(q, sq) return q and q.role == "wall" and q.runB == q.y and sq and sq.role ~= "wall" end
          if isFront(c, s) then
            local x0 = x
            while x + 1 < W and isFront(grid[y][x + 1], at(x + 1, y + 1)) do x = x + 1 end
            local sg = { L = x0, R = x + 1, z = y + 1 }
            segs[#segs + 1] = sg
            byL[sg.z * 4096 + sg.L] = sg
            byR[sg.z * 4096 + sg.R] = sg
          end
          x = x + 1
        end
      end
      local function chainOk(sg)
        for x = sg.L, sg.R - 1 do
          if grid[sg.z - 1][x].inWall then return false end
        end
        return true
      end
      -- dir -1: descending to the west (next = byR[z+1, L]); +1: to the east
      for _, dir in ipairs({ -1, 1 }) do
        local function nextOf(sg)
          if dir < 0 then return byR[(sg.z + 1) * 4096 + sg.L] end
          return byL[(sg.z + 1) * 4096 + sg.R]
        end
        local isNext = {}
        for _, sg in ipairs(segs) do
          local n = nextOf(sg)
          if n then isNext[n] = true end
        end
        for _, head in ipairs(segs) do
          if not isNext[head] and nextOf(head) then
            local seq = { head }
            while nextOf(seq[#seq]) do seq[#seq + 1] = nextOf(seq[#seq]) end
            local i = 2
            while i <= #seq do
              local w = seq[i].R - seq[i].L
              local j = i
              while j + 1 <= #seq and seq[j + 1].R - seq[j + 1].L == w do j = j + 1 end
              local ok = w <= C.DIAG_WALL_MAX_STEP and j - i + 1 >= 2
              for k = i, j do if ok and not chainOk(seq[k]) then ok = false end end
              if ok then
                -- inner corners: P at the anchor's end, Q at the last step's end
                local anc, last = seq[i - 1], seq[j]
                local px, pz, qx, qz
                if dir < 0 then px, pz, qx, qz = anc.L, anc.z, last.L, last.z
                else px, pz, qx, qz = anc.R, anc.z, last.R, last.z end
                local function zAt(xx) return pz + (xx - px) * (qz - pz) / (qx - px) end
                -- normal (-dz, 0, dx) of the west -> east direction
                local wx, wz, ex, ez = math.min(px, qx), 0, math.max(px, qx), 0
                wz, ez = zAt(wx), zAt(ex)
                local nn = norm3({ -(ez - wz), 0, ex - wx })
                for k = i, j do
                  local sg = seq[k]
                  for x = sg.L, sg.R - 1 do
                    diagOf[grid[sg.z - 1][x]] = { x, zAt(x), x + 1, zAt(x + 1), nn, px, pz, qx, qz, dir }
                  end
                end
                indoorStats.diagonals = indoorStats.diagonals + 1
              end
              i = j + 1
            end
          end
        end
      end
    end

    -- cap: a run >= 3 long shows its rows behind the face (a .. b-2)
    -- stretched over its whole footprint (a .. b); a shorter run its top
    -- cell's top edge rows; side walls a dark cap. Cell y draws its slice
    -- of the stretched art.
    local function capArt(c, x0, z0, x1, z1, y)
      local a, b = c.runA, c.runB
      local n = b - a + 1
      if c.side then
        -- (r12: the side column's rim strip, not a dark cap)
        local rc = IN.rimCap(c.mid) or IN.rimUv or darkUv
        if rc then IN.capQuad(x0, z0, x1, z1, y, rc) end
        return
      end
      if n < 3 then
        -- no rows behind the face: the top cell's top edge rows, stretched
        -- (a void-dominated top cell: its rim)
        local rc = IN.rimCap(grid[a][c.x].mid)
        if rc then IN.capQuad(x0, z0, x1, z1, y, rc) return end
        local tq = IN.topRows(grid[a][c.x].mid, ST)
        if tq then IN.capQuad(x0, z0, x1, z1, y, tq) end
        return
      end
      local k = (n - 2) / n
      local p0, p1 = (c.y - a) * k, (c.y + 1 - a) * k
      local r = math.floor(p0)
      while r < p1 - 1e-9 do
        local q0, q1 = math.max(p0, r), math.min(p1, r + 1)
        local src = grid[a + r][c.x]
        local za, zb = a + q0 / k, a + q1 / k
        local rc = IN.rimCap(src.mid)
        if rc then
          IN.capQuad(x0, za, x1, zb, y, rc)
        else
          -- (its void top rows skipped: the stretch starts at its first
          -- drawn row)
          local f0 = IN.firstRow(src.mid) / 16
          artFaces(opaque, src, function(list, rr, lift)
            hQuad(list, x0, za, x1, zb, y + lift, subRect(rr, 0, f0 + (q0 - r) * (1 - f0), 1, f0 + (q1 - r) * (1 - f0)))
          end)
        end
        r = r + 1
      end
    end
    local function fanPoly(list, poly, y, r, cx0, cz0, n)
      -- poly {{x, z}, ...} (convex); UVs planar over the cell's tile rect
      if #poly < 3 or not r then return end
      local pts = {}
      for i = 1, #poly do
        local p = poly[i]
        local fu, fv = p[1] - cx0, p[2] - cz0
        pts[i] = { { p[1], y, p[2] }, { r[1] + (r[3] - r[1]) * fu, r[2] + (r[4] - r[2]) * fv } }
      end
      fanN(list, pts, n or UP)
    end

    for y = 0, H - 1 do
      if y % 4 == 0 then Y() end
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c then
          local g = c.hgt
          local x0, z0, x1, z1 = x + 0.0, y + 0.0, x + 1.0, y + 1.0
          if c.nativeStairRearPlane then z1=c.nativeStairRearPlane end
          if c.role == "wall" then
            indoorStats.walls = indoorStats.walls + 1
            if c.side then indoorStats.sideWalls = indoorStats.sideWalls + 1 end
            local up, bot = colFace(c)
            local dg = diagOf[c]
            -- south face (the run's bottom row)
            local s = at(x, y + 1)
            if dg then
              local ax, az, bx, bz, nn = dg[1], dg[2], dg[3], dg[4], dg[5]
              artFaces(opaque, c, function(list, r, lift)
                wallQuad(list, ax + nn[1] * lift, az + nn[3] * lift, bx + nn[1] * lift, bz + nn[3] * lift, g, g + 1.0, r, nn)
              end)
              artFaces(opaque, up, function(list, r, lift)
                wallQuad(list, ax + nn[1] * lift, az + nn[3] * lift, bx + nn[1] * lift, bz + nn[3] * lift, g + 1.0, g + WH, r, nn)
              end)
              -- front part of the cell -> floor; cap clipped behind
              local px, pz, qx, qz = dg[6], dg[7], dg[8], dg[9]
              local sq = { { x0, z0 }, { x1, z0 }, { x1, z1 }, { x0, z1 } }
              local function side(p) return (p[1] - px) * nn[1] + (p[2] - pz) * nn[3] end
              local front = clipPoly(sq, side)
              local back = clipPoly(sq, function(p) return -side(p) end)
              fanPoly(opaque, front, g, underRect(s and (s.groundMid or s.mid) or floorMid) or underRect(floorMid), x0, z0)
              -- (r12: the slanted wall's cap in the room's rim colour)
              local capR = IN.rimUv or darkUv
              if capR then fanPoly(capR.over and cutoutOver or opaque, back, g + WH, capR, x0, z0) end
            else
              if y == c.runB and s and s.role ~= "wall" then
                if c.inWall == "door" then
                  local zi = z1 - C.DOOR_INSET
                  artFaces(opaque, up, function(list, r, lift)
                    wallQuad(list, x0, z1 + lift, x1, z1 + lift, g + 1.0, g + WH, r, N_S)
                  end)
                  artFaces(opaque, c, function(list, r, lift)
                    wallQuad(list, x0, zi + lift, x1, zi + lift, g, g + 1.0, r, N_S)
                  end)
                  local jr = underRect(up.mid)
                  if jr then
                    local jamb = subRect(jr, 0, 0.8, ST, 1)
                    wallQuad(opaque, x0, zi, x0, z1, g, g + 1.0, jamb, N_E)
                    wallQuad(opaque, x1, z1, x1, zi, g, g + 1.0, jamb, N_W)
                    hQuad(opaque, x0, zi, x1, z1, g + 1.0, subRect(jr, 0, 1 - ST, 1, 1), DOWN)
                  end
                  local fr = underRect(s.groundMid or s.mid)
                  if fr then hQuad(opaque, x0, zi, x1, z1, g, subRect(fr, 0, 0, 1, C.DOOR_INSET)) end
                elseif c.nativeStairRearPlane or c.side or IN.rimOf(c.mid) or IN.rimOf(up.mid) then
                  -- (r12: a side wall's end -- or a run whose face tiles are
                  -- wall tops -- shows the room's wall bands)
                  faceBands(opaque, "down", x0, x1, z0, z1, g, plainU, plainL)
                else
                  artFaces(opaque, c, function(list, r, lift)
                    wallQuad(list, x0, z1 + lift, x1, z1 + lift, g, g + 1.0, r, N_S)
                  end)
                  artFaces(opaque, up, function(list, r, lift)
                    wallQuad(list, x0, z1 + lift, x1, z1 + lift, g + 1.0, g + WH, r, N_S)
                  end)
                  IN.pilasters(c, up, x0, x1, z1, g)
                end
              end
              capArt(c, x0, z0, x1, z1, g + WH)
            end
            -- north face: the column's face art (a door / sign column: plain)
            local n = at(x, y - 1)
            if n and n.role ~= "wall" then
              local rU, rL = underRect(up.mid), underRect(bot.mid)
              -- (r12 pre-lab-7: face tiles that are a wall's TOP -- void with a
              -- rim -- show the room's wall bands: a partition stub running
              -- off the map has no face art of its own)
              if bot.inWall or c.side or IN.rimOf(bot.mid) or IN.rimOf(up.mid) then rU, rL = plainU, plainL end
              faceBands(opaque, "up", x0, x1, z0, z1, g, rU, rL)
            end
            -- west / east faces
            for _, e in ipairs({ { "left", -1 }, { "right", 1 } }) do
              local nc = at(x + e[2], y)
              local skip = dg and ((dg[10] < 0 and e[2] > 0 and x + 1 == dg[3]) or (dg[10] > 0 and e[2] < 0 and x == dg[1]))
              if nc and nc.role ~= "wall" and not skip then
                if c.side then
                  -- r12 (interiors round: the dark side panels read as a black
                  -- surround): a side wall's inward face shows the room's
                  -- plain wall bands, like the synthetic walls; its rim caps it
                  faceBands(opaque, e[1], x0, x1, z0, z1, g, plainU, plainL)
                else
                  -- the strip starts WALL_STRIP_SKIP texels in (past the outline)
                  local sk = C.WALL_STRIP_SKIP / 16
                  -- (r12: past a pilaster at that edge -- a partition's
                  -- sides show its bands, not its end posts)
                  local pl = IN.pilasterOf(up.mid, bot.mid)
                  local pw = pl and (e[2] > 0 and pl.right or pl.left) or nil
                  if pw then sk = pw / 16 + 0.5 / 16 end
                  local u0, u1 = sk, sk + ST
                  if e[2] > 0 then u0, u1 = 1 - sk - ST, 1 - sk end
                  local rU, rL = underRect(up.mid), underRect(bot.mid)
                  if bot.inWall then rU, rL = underRect(IN.wallUpper or c.mid), underRect(IN.wallLower or c.mid) end
                  if IN.rimOf(bot.mid) or IN.rimOf(up.mid) then
                    faceBands(opaque, e[1], x0, x1, z0, z1, g, plainU, plainL)
                  else
                    faceBands(opaque, e[1], x0, x1, z0, z1, g, rU and subRect(rU, u0, 0, u1, 1), rL and subRect(rL, u0, 0, u1, 1))
                  end
                end
              end
            end
          elseif c.role == "gate" then
            IN.gate(c, x, y, g)
          elseif c.role == "furniture" and c.group.pillar then
            IN.pillar(c, x, y, g)
          elseif c.role == "furniture" and #c.group.cells == 1 and IN.bin(c, x, y, g) then
            -- r12 (refs 09 / 10: "cylinder bins"): drawn by IN.bin
          elseif c.role == "furniture" then
            local grp = c.group
            local top = g + grp.h
            local r = underRect(c.mid)
            -- slots: reel strips turned onto the W / E faces (cropped off the top)
            local stripW, stripE = false, false
            if grp.slot then
              local wn, en = at(x - 1, y), at(x + 1, y)
              stripW = wn ~= nil and wn.group ~= grp and wn.role ~= "wall"
              stripE = en ~= nil and en.group ~= grp and en.role ~= "wall"
            end
            local SW = C.SLOT_STRIP_TEXELS / 16
            local function topR(rr)
              if not rr then return nil end
              if stripW or stripE then return subRect(rr, stripW and SW or 0, 0, stripE and (1 - SW) or 1, 1) end
              return rr
            end
            if c.fy0 == c.fy1 then
              if r then hQuad(opaque, x0, z0, x1, z1, top, topR(r)) end
              local ov = c.hasOver and overRect(c.mid) or nil
              if ov then hQuad(cutoutOver, x0, z0, x1, z1, top + C.FACADE_OVER_LIFT, topR(ov)) end
            elseif y == c.fy0 then
              -- M14: the column's north rows on top, stretched over it
              local nrow = c.fy1 - c.fy0 + 1
              local sc = nrow / (nrow - 1)
              for ry = c.fy0, c.fy1 - 1 do
                local rc = grid[ry][x]
                local za, zb = c.fy0 + (ry - c.fy0) * sc, c.fy0 + (ry - c.fy0 + 1) * sc
                local rr = underRect(rc.mid)
                if rr then hQuad(opaque, x0, za, x1, zb, top, topR(rr)) end
                local ov = rc.hasOver and overRect(rc.mid) or nil
                if ov then hQuad(cutoutOver, x0, za, x1, zb, top + C.FACADE_OVER_LIFT, topR(ov)) end
              end
            end
            for _, d in ipairs(DIRS) do
              local nc = at(x + d.dx, y + d.dy)
              if nc and nc.group ~= grp and nc.role ~= "wall" and r then
                local low = nc.hgt and math.min(nc.hgt, g) or g
                if d.name == "down" then
                  local fr = r
                  if c.frontMid then fr = underRect(c.frontMid) or r end
                  faceQuad(opaque, "down", x0, x1, z0, z1, low, top, fr)
                elseif d.name == "up" then
                  faceQuad(opaque, "up", x0, x1, z0, z1, low, top, subRect(r, 0, 0, 1, ST))
                elseif (d.name == "left" and stripW) or (d.name == "right" and stripE) then
                  -- the reel strip (u across the strip -> height, v -> along the face)
                  local ua, ub = r[1], r[1] + (r[3] - r[1]) * SW
                  if d.name == "right" then ua, ub = r[3], r[3] - (r[3] - r[1]) * SW end
                  if d.name == "left" then
                    quadN(opaque, x0, low, z0, ub, r[2], x0, low, z1, ub, r[4], x0, top, z1, ua, r[4],
                      x0, top, z0, ua, r[2], -1, 0, 0)
                  else
                    quadN(opaque, x1, low, z1, ub, r[4], x1, low, z0, ub, r[2], x1, top, z0, ua, r[2],
                      x1, top, z1, ua, r[4], 1, 0, 0)
                  end
                else
                  local u0, u1 = 0, ST
                  if d.name == "right" then u0, u1 = 1 - ST, 1 end
                  faceQuad(opaque, d.name, x0, x1, z0, z1, low, top, subRect(r, u0, 0, u1, 1))
                end
              end
            end
          elseif c.role == "plant" then
            indoorStats.plants = indoorStats.plants + 1
            local cx, cz = x0 + 0.5, z0 + 0.5
            local hw = C.PLANT_CARD_W * 0.5
            local pot = underRect(c.mid)
            if pot then
              wallQuad(cutoutKeyed, cx - hw, cz, cx + hw, cz, g, g + C.PLANT_POT_H, pot, UP)
              wallQuad(cutoutKeyed, cx, cz - hw, cx, cz + hw, g, g + C.PLANT_POT_H, pot, UP)
            end
            local leaves = c.plantTop and overRect(c.plantTop.mid)
            if leaves then
              -- r12 (R3): the leaf cards sit PLANT_LEAF_OFFSET off the pot
              -- cards' planes (they overlap in height: no coplanar pair)
              local ly0, lo = g + C.PLANT_POT_H * 0.7, C.PLANT_LEAF_OFFSET
              wallQuad(cutoutOver, cx - hw, cz + lo, cx + hw, cz + lo, ly0, g + C.PLANT_TOP_H, leaves, UP)
              wallQuad(cutoutOver, cx + lo, cz - hw, cx + lo, cz + hw, ly0, g + C.PLANT_TOP_H, leaves, UP)
            end
          elseif c.role == "statue" then
            local r = underRect(c.mid)
            local pi = C.STATUE_PLINTH_INSET
            local px0, px1, pz0, pz1 = x0 + pi, x1 - pi, z0 + pi, z1 - pi
            local ph = g + C.STATUE_PLINTH_H
            if r then
              faceQuad(opaque, "down", px0, px1, pz0, pz1, g, ph, subRect(r, 0, 0.35, 1, 1))
              faceQuad(opaque, "up", px0, px1, pz0, pz1, g, ph, subRect(r, 0, 0.35, 1, 0.35 + ST))
              faceQuad(opaque, "left", px0, px1, pz0, pz1, g, ph, subRect(r, 0, 0.35, ST, 1))
              faceQuad(opaque, "right", px0, px1, pz0, pz1, g, ph, subRect(r, 1 - ST, 0.35, 1, 1))
              hQuad(opaque, px0, pz0, px1, pz1, ph, subRect(r, 0, 0, 1, 0.35))
            end
            local fig = c.statueFig and overRect(c.statueFig.mid)
            if fig then
              local cx, cz, hw = x0 + 0.5, z0 + 0.5, C.STATUE_CARD_W * 0.5
              wallQuad(cutoutOver, cx - hw, cz, cx + hw, cz, ph, ph + C.STATUE_CARD_H, fig, UP)
              wallQuad(cutoutOver, cx, cz - hw, cx, cz + hw, ph, ph + C.STATUE_CARD_H, fig, UP)
            end
          elseif c.role == "boulder" then
            local r = underRect(c.mid)
            local swr = c.boulder.sw
            if r and swr then
              local rr = subRect(r, swr[1] / 16, swr[2] / 16, swr[3] / 16, swr[4] / 16)
              local h = lerp(C.BOULDER_H_MIN, C.BOULDER_H_MAX, hash01(x, y, 71))
              local bi, ti = C.BOULDER_INSET, C.BOULDER_TOP_INSET
              local b = { { x0 + bi, z0 + bi }, { x1 - bi, z0 + bi }, { x1 - bi, z1 - bi }, { x0 + bi, z1 - bi } }
              local t = { { x0 + ti, z0 + ti }, { x1 - ti, z0 + ti }, { x1 - ti, z1 - ti }, { x0 + ti, z1 - ti } }
              local yt = g + h
              -- sides: S (b4->b3), E (b3->b2), N (b2->b1), W (b1->b4), each left -> right from outside
              for _, e in ipairs({ { 4, 3 }, { 3, 2 }, { 2, 1 }, { 1, 4 } }) do
                local A, B, TA, TB = b[e[1]], b[e[2]], t[e[1]], t[e[2]]
                local nn = faceNormal3({ A[1], g, A[2] }, { B[1], g, B[2] }, { TB[1], yt, TB[2] })
                quadN(opaque, A[1], g, A[2], rr[1], rr[4], B[1], g, B[2], rr[3], rr[4],
                  TB[1], yt, TB[2], rr[3], rr[2], TA[1], yt, TA[2], rr[1], rr[2], nn[1], nn[2], nn[3])
              end
              hQuad(opaque, t[1][1], t[1][2], t[3][1], t[3][2], yt, rr)
            end
          end
          -- synthetic walls: a floor-level cell's edge on void, off-map or
          -- an exit frame gets a wall (W / E / N in opaque, S in
          -- geom.southWalls), except a door cell there (the exit mat): a gap
          if c.role ~= "wall" and not c.exitFrame then
            for _, d in ipairs(DIRS) do
              local nb = at(x + d.dx, y + d.dy)
              if not nb or nb.exitFrame then
                if c.isDoor then
                  indoorStats.doorGaps = indoorStats.doorGaps + 1
                  if IN.interiors then IN.interiors:gap(c, x, y, g, d.name) end -- interiors-team
                elseif d.name == "down" and IN.interiors and IN.interiors:south(c, x, y, g) then
                  indoorStats.southWalls = indoorStats.southWalls + 1 -- interiors-team: the core's 4th wall
                elseif d.name == "down" then
                  local bx0, bx1, bz0, bz1 = synthWall(southWalls, c, "down")
                  indoorStats.southWalls = indoorStats.southWalls + 1
                  -- jambs where the wall ends at a doorway gap
                  for _, e in ipairs({ { "left", -1 }, { "right", 1 } }) do
                    local sd = at(x + e[2], y)
                    local sdS = sd and at(x + e[2], y + 1)
                    if sd and sd.isDoor and (not sdS or sdS.exitFrame) and darkUv then
                      faceQuad(southWalls, e[1], bx0, bx1, bz0, bz1, g, g + WH, darkUv)
                    end
                  end
                else
                  if not (IN.interiors and IN.interiors:side(c, x, y, g, d.name)) then synthWall(opaque, c, d.name) end -- interiors-team
                  indoorStats.synthWalls = indoorStats.synthWalls + 1
                end
              end
            end
          end
          if c.role == "flat" then indoorStats.flat = indoorStats.flat + 1 end
        end
      end
    end
    -- A single lateral flight replaces the native projected art footprint.
    for _, assembly in ipairs(IN.stairs or {}) do
      local ground = assembly.anchor.hgt
      local p = assembly.profile
      local bounds = IN.stairModule.bounds(assembly)
      local z0,z1 = bounds.openingZ0,bounds.openingZ1
      local floor = underRect(floorMid)
      if floor then
        for _, cell in ipairs(assembly.cells) do
          if not p.down then
            hQuad(opaque, cell.x, cell.y, cell.x+1, cell.y+1, ground, floor)
          else
            -- Keep the descending opening clear, but floor the surrounding art.
            if cell.y < z0 then hQuad(opaque,cell.x,cell.y,cell.x+1,math.min(cell.y+1,z0),ground,floor) end
            if cell.y+1 > z1 then hQuad(opaque,cell.x,math.max(cell.y,z1),cell.x+1,cell.y+1,ground,floor) end
          end
        end
      end
      IN.stairModule.emit(assembly, {ground=ground, emitQuad=function(points,mid,layer,uv,n)
        local r
        if layer == "over" then r=overRect(mid) else r=underRect(mid) end
        assert(r,"native stair atlas rect missing")
        local list = layer == "over" and cutoutOver or opaque
        quad(list,points[1],points[2],points[3],points[4],subRect(r,uv[1],uv[2],uv[3],uv[4]),n)
      end})
    end
    indoorStats.nativeStairs = #(IN.stairs or {})
    indoorStats.furniture = #furnitureGroups
    if IN.interiors then IN.interiors:finish(diagOf) end -- interiors-team
  end

  -- r11 (review M6, USER REPORT): the GROUND-PALETTE test. The palette of
  -- the ground round a volume = the main colours (>= 10% of a tile, not
  -- near-black) of the walkable tiles touching its bbox (atlas.colors: a
  -- tile's top-8 colours); a tile's taint = the share of its texels in
  -- that palette. Side / back walls only take tiles with taint <=
  -- SIDE_GROUND_MAX (no grass triangles, no path under a chamfer). nil
  -- without colour data (then atlas.leafFrac is the test).
  local function groundTaint(minX, minY, maxX, maxY)
    local colors = atlas.colors
    if type(colors) ~= "function" then return nil end
    local pal, seen = {}, {}
    local function add(c)
      -- (plain ground only: a walkable cell with over art carries a roof
      -- or canopy edge; doors / signs are facade)
      if c and c.walkable and not c.hasOver and not c.isDoor and not c.isSign and not seen[c.mid] then
        seen[c.mid] = true
        local l = colors(c.mid)
        if l then
          for i = 1, #l - 1, 2 do
            local k, f = l[i], l[i + 1]
            local r, g, b = math.floor(k / 65536), math.floor(k / 256) % 256, k % 256
            if f >= 0.1 and math.max(r, g, b) >= 40 then pal[k] = true end
          end
        end
      end
    end
    for x = minX - 1, maxX + 1 do
      add(at(x, minY - 1))
      add(at(x, maxY + 1))
    end
    for y = minY, maxY do
      add(at(minX - 1, y))
      add(at(maxX + 1, y))
    end
    return function(mid)
      local l = colors(mid)
      if not l then return 0 end
      local t = 0
      for i = 1, #l - 1, 2 do
        if pal[l[i]] then t = t + l[i + 1] end
      end
      return t
    end, pal
  end

  -- r11 (review M1): the block column runs (pass 3b) are measured first
  -- so walls between split parts can be skipped: a building wall facing a
  -- block column at least as tall, a block side facing a taller or equal
  -- neighbour (block run or building wall top) is never seen.
  local blockRunOf = {}
  grid.blockRunOf = blockRunOf -- (flat-top rollout: grid.flatTopRoof reads it)
  do
    local function isBlockCell(c, bc) return not bc.nativeBikeShop and not bc.nativeRail and not bc.nativeDecorativeRest and c and not c.nativeSaffronThin and ((c.blocksForBlob and components[c.compId] == bc) or c.nativeRoute2GateOwner==bc) end
    for _, bc in ipairs(blocks) do
      local runs, maxRows = {}, 0
      for x = bc.minX, bc.maxX do
        local y = bc.minY
        while y <= bc.maxY do
          if isBlockCell(at(x, y), bc) then
            local yT = y
            while y + 1 <= bc.maxY and isBlockCell(at(x, y + 1), bc) do y = y + 1 end
            local fill = at(x, y + 1)
            if not (fill and fill.blockFill == bc) then fill = nil end
            local yB = fill and (y + 1) or y
            local R = yB - yT + 1
            local nonOver = 0
            for yy = yB, yT, -1 do
              local c = at(x, yy)
              if c.hasOver and c ~= fill then break end
              nonOver = nonOver + 1
            end
            -- (r11 review: at most half the run (rounded up) is facade when
            -- the roof is drawn in the under layer -- the primary-tileset
            -- house (313..350) has no over art; a tall tower with over-art
            -- upper floors still gets BLOCK_FACADE_FRAC of its rows)
            local nf = math.max(math.min(nonOver, math.ceil(R / 2)), math.floor(R * C.BLOCK_FACADE_FRAC), 1)
            if nf > R then nf = R end
            local front = at(x, yB + 1)
            local gy
            if front and front.walkable and not front.isWater then
              gy = front.hgt
            else
              gy = -math.huge
              for yy = yT, yB do
                local c = at(x, yy)
                if c.hgt > gy then gy = c.hgt end
              end
            end
            local h = math.min(nf, C.BLOCK_MAX_ROWS) * C.WALL_ROW_UNIT
            -- r11 (review M11): a doorless block at most 2 columns wide is
            -- a small structure (a market stall's crates and pots on Two
            -- Island): a low box, its bottom row on the front, the rest on top
            if not bc.door and bc.maxX - bc.minX <= 1 then nf, h = 1, C.BLOCK_SMALL_H end
            -- (+ BLOCK_TOP_BIAS: a block top never lies in a building's
            -- eave / roof plane on the WALL_ROW_UNIT grid -- review R3)
            local run = { x = x, yT = yT, yB = yB, fill = fill, gy = gy, top = gy + h + C.BLOCK_TOP_BIAS, nf = nf, R = R, bh = h / nf }
            runs[#runs + 1] = run
            for yy = yT, yB do blockRunOf[at(x, yy)] = run end
            if nf > maxRows then maxRows = nf end
          end
          y = y + 1
        end
      end
      bc.runs, bc.maxRows = runs, maxRows
    end
  end

  -- the top of whatever volume stands on cell n: a block run, a building's
  -- wall (its door / sign facade cells included), a rock column; else nil
  local function volTop(n)
    if not n then return nil end
    -- A connected native model still occludes terrain beside its actual
    -- Lavender footprint. Projected Route10 roof cells are only source art.
    if n.nativeConnectedHouseSource and n.y>=7 and n.y<=9 then
      local anchor=at(input.mapId=="FR_FIVE_ISLAND"and 22 or 0,9)
      return (anchor and anchor.hgt or n.hgt)+1.25
    end
    if n.nativeTowerSourceOnly and input.mapId=="FR_LAVENDER_TOWN"then
      local base=at(18,6)
      return (base and base.hgt or n.hgt)+9.25
    end
    local nrun = blockRunOf[n]
    if nrun then return nrun.top end
    if n.rockTop then return n.rockTop end
    local nb = compOf(n) or n.facadeOf or n.doorOf
    if nb and nb.kind == "building" and nb.wallTopY then return nb.wallTopY end
    return nil
  end

  -- ---------------------------------------------------------------
  grid.boundaryMark(true)
  -- Pass 3r (r11, review M2): outdoor ROCK TERRAIN. Each rock cell is a
  -- column on its ground height: a lone rock (no rock 4-neighbour) is a
  -- lump ROCK_LUMP_H high, a thin run (in no 2x2 square of rock -- the
  -- 1-wide cliff line between two terrace levels) a kerb ROCK_KERB_H high,
  -- anything else a plateau stepped by its distance from the rock's edge
  -- (ROCK_H0 at the edge, + ROCK_STEP per cell inward, at most ROCK_MAX_H).
  -- r12 (v18): each cell's ground is ROUNDED down toward its lower
  -- neighbours (a heightfield, see the cell loop) -- terraces, not boxes.
  -- Top: the tile's own art (the under layer unless the over art is solid,
  -- then the over art on top of it, like block roofs). Faces toward every
  -- lower neighbour (ground or a lower rock step): the tile's bottom rows
  -- under the top edge, then the bottom rows again for the rest -- the
  -- cave rule (pass 3c). No dome, no understory.
  -- ---------------------------------------------------------------
  local rockOut = 0
  if rockCount > 0 then
    local depth, queue, head = {}, {}, 1
    local function isRock(c) return c and c.rock == true or false end -- (grid holes are false)
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if isRock(c) then
          for _, d in ipairs(DIRS) do
            local nx, ny = x + d.dx, y + d.dy
            if nx >= 0 and ny >= 0 and nx < W and ny < H and not isRock(at(nx, ny)) then
              depth[c] = 1
              queue[#queue + 1] = c
              break
            end
          end
        end
      end
    end
    while head <= #queue do
      local c = queue[head]
      head = head + 1
      for _, d in ipairs(DIRS) do
        local n = at(c.x + d.dx, c.y + d.dy)
        if isRock(n) and not depth[n] then
          depth[n] = depth[c] + 1
          queue[#queue + 1] = n
        end
      end
    end
    local function rockTop(c)
      local t = c.rockTop
      if t then return t end
      local lone, thick = true, false
      for _, d in ipairs(DIRS) do
        if isRock(at(c.x + d.dx, c.y + d.dy)) then lone = false break end
      end
      if not lone then
        for _, q in ipairs({ { -1, -1 }, { 1, -1 }, { -1, 1 }, { 1, 1 } }) do
          if isRock(at(c.x + q[1], c.y)) and isRock(at(c.x, c.y + q[2])) and isRock(at(c.x + q[1], c.y + q[2])) then
            thick = true
            break
          end
        end
      end
      local h
      if lone then h = C.ROCK_LUMP_H
      elseif not thick then h = C.ROCK_KERB_H
      else h = math.min(C.ROCK_MAX_H, C.ROCK_H0 + C.ROCK_STEP * ((depth[c] or 1) - 1)) end
      t = c.hgt + h
      c.rockTop = t
      return t
    end
    -- r12 (v18; USER: "round the corners and smooth the angles"): outdoor
    -- rock is ROUNDED TERRACES. Each rock cell is a heightfield pulled down
    -- toward every lower neighbour: over a bevel of ROCK_BEVEL (at most
    -- ROCK_BEVEL_K x the drop -- a whole cell for a full step) the ground
    -- rises as sin(s * pi / 2): a steep foot and a convex SHOULDER onto the
    -- plateau. Two adjacent lowered sides to one height make a ROUND corner
    -- in plan (a quarter dome about the corner point one bevel in); a lower
    -- diagonal alone dips its corner. One height function -- the lowest of
    -- the rock cells touching a point -- and neighbours' cut positions along
    -- shared edges: no cracks between cells with different lower
    -- neighbours. The tile's art is laid by ARC LENGTH along a lowered
    -- side, so its highlight rows wrap over the shoulder and its face rows
    -- run down the steep part (no smear). Caves / border rings keep the
    -- r11 boxes. Settings per cell are cached; scratch tables reused.
    local HALF_PI = math.pi * 0.5
    local SIDE_D = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } }
    local DIAG_D = { { -1, -1, 0, 0 }, { 1, -1, 1, 0 }, { 1, 1, 1, 1 }, { -1, 1, 0, 1 } }
    local ADJ_D = { { 1, 3 }, { 2, 3 }, { 2, 4 }, { 1, 4 } }
    -- Scoped exact bevel sampling: original full native map/art guard
    -- admits the map, and each declared rock component must remain closed.
    grid.nativeFiveRidgeCells={}
    do
      local specs={FR_FIVE_ISLAND={{14,9,121},{15,9,179},{15,10,160},{15,11,168},{16,11,121},{17,11,121},{18,11,121},{19,11,121},{20,11,121},{21,11,121},{22,11,121},{23,11,170},{23,10,178}},FR_FIVE_ISLAND_MEADOW={{4,10,121},{5,10,121},{6,10,179},{6,11,160},{6,12,160},{17,20,178},{17,21,114},{17,22,114},{17,23,114},{17,24,114},{17,25,114},{17,26,114},{17,27,114},{17,28,122},{16,28,178},{16,29,114},{16,30,122},{15,30,121},{14,30,121}}}
      local cells=specs[input.mapId]
      local cuts=C.ROCK_CUTS
      local valid=grid.nativeFiveTerrace and cells and C.ROCK_BEVEL==1 and C.ROCK_BEVEL_K==1
        and C.ROCK_LATTICE==4 and type(cuts)=='table' and #cuts==4
        and cuts[1]==.15 and cuts[2]==.4 and cuts[3]==.7 and cuts[4]==1
      local owned={}
      if valid then
        for _,p in ipairs(cells)do local c=at(p[1],p[2])
          if not isRock(c) or c.mid~=p[3] or c.hgt~=.75 or math.abs(rockTop(c)-1.1)>1e-10 then valid=false;break end
          owned[c]=true
        end
      end
      if valid then for c in pairs(owned)do for _,d in ipairs(DIRS)do local n=at(c.x+d.dx,c.y+d.dy)
        if isRock(n) and not owned[n]then valid=false end
      end end end
      if valid then grid.nativeFiveRidgeCells=owned end
    end
    -- Exact profile-owned rims reuse welded endpoint sampling; no global lattice change.
    for y=0,H-1 do for x=0,W-1 do local c=at(x,y);if c and c.nativeElevationRidge and isRock(c)then grid.nativeFiveRidgeCells[c]=true end end end
    if grid.nativeBondWestCoast then for _,e in ipairs(grid.nativeBondWestCoast)do local c=at(e[1],e[2]);if e[4]==1.1 and isRock(c)then grid.nativeFiveRidgeCells[c]=true end end end
    if grid.nativeBondEastCoast then for _,e in ipairs(grid.nativeBondEastCoast)do local c=at(e[1],e[2]);if isRock(c)then grid.nativeFiveRidgeCells[c]=true end end end
    local hfSet = {}
    local function hfLow(x, y, dx, dy, top)
      local nc = at(x + dx, y + dy)
      if not nc then
        if grid.nativeBondEastCoast then for _,e in ipairs(grid.nativeBondEastCoast)do
          if e[1]==x and e[2]==y and ((e[3]=='up'and dy==-1 and dx==0)or(e[3]=='down'and dy==1 and dx==0))then return e[5],false,nil end
        end end
        if grid.nativeBondWestCoast then for _,e in ipairs(grid.nativeBondWestCoast)do
          if e[4]==1.1 and e[1]==x and e[2]==y and ((e[3]=='up'and dy==-1 and dx==0)or(e[3]=='left'and dx==-1 and dy==0))then return .6,false,nil end
        end end
        return nil
      end
      local low = isRock(nc) and rockTop(nc) or volTop(nc) or nc.hgt
      -- (r13c: a hill cell banded / dipped down to its base toward this rock
      -- -- the rock's side comes down to that base too: no gap)
      -- (ledgefinal1: such a side is SOFT -- its foot rises as a smoothstep,
      -- flat where it meets the band's flat foot: a round trough, not the
      -- 90 deg V the steep sin foot made against it)
      local soft, fn = false, nil
      if nc.hbRock and nc.hbRock[at(x, y)] and not isRock(nc) then
        low, soft = nc.hb.hT, true
        -- (ledgefinal2: a hill edge that FILLS toward this rock -- its
        -- height along the edge, grid.rkFillAt; the side's low is its level)
        local nm = (dx == 0 and dy > 0 and "up") or (dx == 0 and dy < 0 and "down") or (dy == 0 and dx > 0 and "left") or (dy == 0 and dx < 0 and "right") or nil
        if nm and nc.rkFill and nc.rkFill[nm] then
          low = nc.rkFill[nm]
          fn = function(a) return grid.rkFillAt(nc, nm, a) end
        end
      end
      if low and low < top - EPS then return low, soft, fn end
      return nil
    end
    local function hfOf(c)
      local S = hfSet[c]
      if S then return S end
      local x, y, top = c.x, c.y, rockTop(c)
      S = { top = top, has = {}, low = {}, bev = {}, dhas = {}, dlow = {}, dbev = {}, xs = { 0, 1 }, zs = { 0, 1 }, any = false, soft = {}, dsoft = {}, cx = x, cz = y }
      for k = 1, 4 do
        local lw, sf, fn = hfLow(x, y, SIDE_D[k][1], SIDE_D[k][2], top)
        if lw then
          -- (ledgefinal2: a SOFT side rounds over twice the width -- a low
          -- rock's short bevel rose from the band's flat foot in one steep
          -- lattice facet, Route 22 (42,3): 55 deg)
          S.has[k], S.low[k], S.bev[k], S.any, S.soft[k] = true, lw, math.min(C.ROCK_BEVEL, (sf and 2 or 1) * C.ROCK_BEVEL_K * (top - lw)), true, sf
          if fn then S.lowFn = S.lowFn or {}; S.lowFn[k] = fn end
        end
      end
      for k = 1, 4 do
        local dl, sf
        if not (S.has[ADJ_D[k][1]] or S.has[ADJ_D[k][2]]) then dl, sf = hfLow(x, y, DIAG_D[k][1], DIAG_D[k][2], top) end
        if dl then
          S.dhas[k], S.dlow[k], S.dbev[k], S.any, S.dsoft[k] = true, dl, math.min(C.ROCK_BEVEL, C.ROCK_BEVEL_K * (top - dl)), true, sf
        end
      end
      -- (budget: cuts snap to a 1 / ROCK_LATTICE lattice -- a run's union of
      -- cuts stays bounded, whatever its cells' bevel widths)
      local LAT = C.ROCK_LATTICE or 8
      local function add(t, v)
        v = math.max(1, math.min(LAT - 1, math.floor(v * LAT + 0.5))) / LAT
        for i = 1, #t do if math.abs(t[i] - v) < 1e-3 then return end end
        t[#t + 1] = v
      end
      -- ledgefinal2 (verifier final-r1 F1: the Route 22 gutter's rock side
      -- met the band in one 32 deg lattice facet): a SOFT side's foot gets
      -- fine cuts (1/16, 1/8, 3/16 of its bevel, on a 1/32 lattice) -- the
      -- hill's round foot against the rock -- S.fine[k]; they join the
      -- run's cuts only where every cell of the run has that soft side
      -- (hfRunCuts: other rocks keep their lattice)
      if C.LEDGE_END_BANK ~= false then
        for k = 1, 4 do
          -- (a filling side's tent peak along it: a lattice cut)
          if S.lowFn and S.lowFn[k] then add(k <= 2 and S.zs or S.xs, 0.5) end
          if S.has[k] and S.soft[k] then
            S.fine = S.fine or {}
            local t = {}
            for _, f in ipairs({ 0.0625, 0.125, 0.1875 }) do
              local v = math.max(1, math.floor(f * S.bev[k] * 32 + 0.5)) / 32
              if k == 2 or k == 4 then v = 1 - v end
              t[#t + 1] = v
            end
            S.fine[k] = t
          end
        end
      end
      for _, f in ipairs(C.ROCK_CUTS) do
        if S.has[1] then add(S.xs, f * S.bev[1]) end
        if S.has[2] then add(S.xs, 1 - f * S.bev[2]) end
        if S.has[3] then add(S.zs, f * S.bev[3]) end
        if S.has[4] then add(S.zs, 1 - f * S.bev[4]) end
        for k = 1, 4 do
          if S.dhas[k] then
            local bb = f * S.dbev[k]
            add(S.xs, DIAG_D[k][3] == 0 and bb or 1 - bb)
            add(S.zs, DIAG_D[k][4] == 0 and bb or 1 - bb)
          end
        end
      end
      if grid.nativeFiveRidgeCells[c]then
        -- Four intervals per bevel, including its exact flat-crest boundary.
        local function exact(t,v)
          if v<=0 or v>=1 then return end
          for _,q in ipairs(t)do if math.abs(q-v)<1e-10 then return end end
          t[#t+1]=v
        end
        for _,f in ipairs{.25,.5,.75,1}do
          if S.has[1]then exact(S.xs,f*S.bev[1])end
          if S.has[2]then exact(S.xs,1-f*S.bev[2])end
          if S.has[3]then exact(S.zs,f*S.bev[3])end
          if S.has[4]then exact(S.zs,1-f*S.bev[4])end
          for k=1,4 do if S.dhas[k]then local d=f*S.dbev[k]
            exact(S.xs,DIAG_D[k][3]==0 and d or 1-d)
            exact(S.zs,DIAG_D[k][4]==0 and d or 1-d)
          end end
        end
      end
      hfSet[c] = S
      return S
    end
    -- (ledgefinal1: is side k of the rock cell at (cx, cz) SOFT -- lowered
    -- to a hill band's base? on grid: M.build's locals limit)
    grid.rockSoftSide = function(cx, cz, k)
      local q = at(cx, cz)
      return q and isRock(q) and underRect(q.mid) and hfOf(q).soft[k] or false
    end
    local function prof(sv, soft) -- 0 at the foot .. 1 on the plateau
      if sv <= 0 then return 0 end
      if sv >= 1 then return 1 end
      if soft then return sv * sv * (3 - 2 * sv) end
      return math.sin(sv * HALF_PI)
    end
    -- one cell's height at local (u, v)
    local dd = { 0, 0, 0, 0 } -- (scratch)
    local function hfCell(S, u, v)
      local drop = 0
      dd[1], dd[2], dd[3], dd[4] = u, 1 - u, v, 1 - v
      -- round plan corners: two adjacent lowered sides to one height
      for k = 1, 4 do
        local kx, kz = ADJ_D[k][1], ADJ_D[k][2]
        if S.has[kx] and S.has[kz] and math.abs(S.low[kx] - S.low[kz]) < 1e-4 and not (S.lowFn and (S.lowFn[kx] or S.lowFn[kz])) then
          local B = math.min(S.bev[kx], S.bev[kz])
          local ax, az = B - dd[kx], B - dd[kz]
          if ax > 0 and az > 0 then
            local d = (S.top - S.low[kx]) * (1 - prof((B - math.sqrt(ax * ax + az * az)) / B, S.soft[kx] or S.soft[kz]))
            if d > drop then drop = d end
          end
        end
      end
      for k = 1, 4 do
        if S.has[k] then
          local lk = S.low[k]
          local fn = S.lowFn and S.lowFn[k]
          if fn then lk = fn(k <= 2 and (S.cz + v) or (S.cx + u)) end
          local d = (S.top - lk) * (1 - prof(dd[k] / S.bev[k], S.soft[k]))
          if d > drop then drop = d end
        end
      end
      for k = 1, 4 do
        if S.dhas[k] then
          local ex, ez = u - DIAG_D[k][3], v - DIAG_D[k][4]
          local d = (S.top - S.dlow[k]) * (1 - prof(math.sqrt(ex * ex + ez * ez) / S.dbev[k], S.dsoft[k]))
          if d > drop then drop = d end
        end
      end
      return S.top - drop
    end
    -- the shared height at a world point: the lowest of the rock cells
    -- (outdoor, not caves / rings) touching it
    local function hfPoint(px, pz, own, ou, ov2)
      -- (inside the cell: its own height; on an edge: the lowest of the
      -- rock cells sharing it)
      if ou > 1e-6 and ou < 1 - 1e-6 and ov2 > 1e-6 and ov2 < 1 - 1e-6 then return hfCell(own, ou, ov2) end
      local best
      local fx, fz = math.floor(px + 1e-7), math.floor(pz + 1e-7)
      for qx = -1, 0 do
        for qz = -1, 0 do
          local cx, cz = fx + qx, fz + qz
          if px >= cx - 1e-7 and px <= cx + 1 + 1e-7 and pz >= cz - 1e-7 and pz <= cz + 1 + 1e-7 then
            local c = at(cx, cz)
            if isRock(c) and underRect(c.mid) then
              local h = hfCell(hfOf(c), px - cx, pz - cz)
              if not best or h < best then best = h end
            end
          end
        end
      end
      return best
    end
    if grid.nativeBondWestCoast then grid.bondWestRockPoint=function(x,z)return hfPoint(x,z,nil,0,0)end end
    -- arc-length remap of a coordinate along a lowered side
    local function arcMap(S, k, t)
      -- t: 0..1 distance from side k's edge; returns 0..1 by arc length over
      -- the whole cell width (a 16-sample table cached per cell side)
      S.arc = S.arc or {}
      local tab = S.arc[k]
      if not tab then
        tab = { 0 }
        local prevH, prevT, tot = S.low[k], 0, 0
        for i = 1, 16 do
          local ti = i / 16
          local hi = S.top - (S.top - S.low[k]) * (1 - prof(ti / S.bev[k], S.soft[k]))
          tot = tot + math.sqrt((ti - prevT) ^ 2 + (hi - prevH) ^ 2)
          tab[i + 1] = tot
          prevH, prevT = hi, ti
        end
        for i = 1, 17 do tab[i] = tab[i] / tot end
        S.arc[k] = tab
      end
      local f = t * 16
      local i = math.floor(f)
      if i >= 16 then return 1 end
      if i < 0 then return 0 end
      return tab[i + 1] + (tab[i + 2] - tab[i + 1]) * (f - i)
    end
    local HF_LAT = C.ROCK_LATTICE or 8
    -- (ledgefinal2: points are keyed on a lattice HF_K = 8 x finer -- a soft
    -- foot's fine cuts have their own points; the normals keep one coarse
    -- step, HF_ST key units, except across a fine cut's own line)
    local HF_K = HF_LAT * 8
    local HF_ST = 8
    local hfHC, hfNC = {}, {} -- (height / normal caches by lattice point)
    -- the height at a lattice point (ix, iz) / HF_LAT: an edge point =
    -- the lowest of the rock cells touching it, an inside point = its
    -- cell's; nil off rock. Cached: every cell's vertices and the smooth
    -- normals' neighbours come from here, so both cells of an edge agree.
    local function hfLat(ix, iz)
      local key = iz * 1e6 + ix
      local h = hfHC[key]
      if h ~= nil then return h or nil end
      local px, pz = ix / HF_K, iz / HF_K
      if ix % HF_K == 0 or iz % HF_K == 0 then
        h = hfPoint(px, pz, nil, 0, 0)
      else
        local cx, cz = mfloor(px), mfloor(pz)
        local c = at(cx, cz)
        h = (isRock(c) and underRect(c.mid)) and hfCell(hfOf(c), px - cx, pz - cz) or nil
      end
      hfHC[key] = h or false
      return h
    end
    -- the over art's opaque texels per mid (a 17 x 17 summed-area table):
    -- an over quad over transparent texels only is not emitted
    local ovSAT = {}
    local atlasTex = type(atlas.texels) == "function" and atlas.texels or nil
    local function ovAny(mid, ua, ub, va, vb)
      if not atlasTex then return true end
      local T = ovSAT[mid]
      if T == nil then
        local o = atlasTex(mid, "over")
        if not o then T = false else
          T = {}
          for q = 0, 16 * 17 + 16 do T[q] = 0 end
          for ty = 1, 16 do
            for tx = 1, 16 do
              local op = (o[(ty - 1) * 16 + tx] or -1) >= 0 and 1 or 0
              T[ty * 17 + tx] = op + T[(ty - 1) * 17 + tx] + T[ty * 17 + tx - 1] - T[(ty - 1) * 17 + tx - 1]
            end
          end
        end
        ovSAT[mid] = T
      end
      if not T then return true end
      local a, b = math.max(0, math.floor(math.min(ua, ub) * 16)), math.min(16, math.ceil(math.max(ua, ub) * 16))
      local c2, d2 = math.max(0, math.floor(math.min(va, vb) * 16)), math.min(16, math.ceil(math.max(va, vb) * 16))
      if b <= a or d2 <= c2 then return true end
      return T[d2 * 17 + b] - T[c2 * 17 + b] - T[d2 * 17 + a] + T[c2 * 17 + a] > 0
    end
    local runCache = { xs = {}, zs = {} }
    local function hfRunCuts(c, dx, dy, key)
      local t = runCache[key][c]
      if t then return t end
      local function ok(q) return isRock(q) and underRect(q.mid) end
      local sx, sy = c.x, c.y
      while ok(at(sx - dx, sy - dy)) do sx, sy = sx - dx, sy - dy end
      local run, u = {}, {}
      local qx, qy = sx, sy
      while ok(at(qx, qy)) do
        local q = at(qx, qy)
        run[#run + 1] = q
        for _, v in ipairs(hfOf(q)[key]) do
          local dup = false
          for i = 1, #u do if math.abs(u[i] - v) < 1e-3 then dup = true break end end
          if not dup then u[#u + 1] = v end
        end
        qx, qy = qx + dx, qy + dy
      end
      -- (ledgefinal2: a soft side's fine cuts, where the whole run has it)
      for _, k in ipairs(key == "xs" and { 1, 2 } or { 3, 4 }) do
        local all = true
        for _, q in ipairs(run) do
          local F = hfOf(q).fine
          if not (F and F[k]) then all = false break end
        end
        if all then
          for _, q in ipairs(run) do
            for _, v in ipairs(hfOf(q).fine[k]) do
              local dup = false
              for i = 1, #u do if math.abs(u[i] - v) < 1e-3 then dup = true break end end
              if not dup then u[#u + 1] = v end
            end
          end
        end
      end
      table.sort(u)
      for _, q in ipairs(run) do runCache[key][q] = u end
      return u
    end
    -- one heightfield quad: corners (ax, az) (bx, az) (bx, bz) (ax, bz),
    -- heights h1..h4, UV fractions ua / ub x va / vb of the rect (u1, v1,
    -- width uw, height vh), vertex normals n1..n4, lifted lf off the face
    local function hfEmit(L, u1, v1, uw, vh, lf, nnx, nny, nnz, ax, bx, az, bz, h1, h2, h3, h4, ua, ub, va, vb, n1, n2, n3, n4)
      local ox, oy, oz = nnx * lf, nny * lf, nnz * lf
      if nny > 0.3 then ox, oy, oz = 0, lf, 0 end -- (upward quads: straight up, no seam slivers)
      local p1 = newV(ax + ox, h1 + oy, az + oz, u1 + ua * uw, v1 + va * vh, n1[1], n1[2], n1[3])
      local p2 = newV(bx + ox, h2 + oy, az + oz, u1 + ub * uw, v1 + va * vh, n2[1], n2[2], n2[3])
      local p3 = newV(bx + ox, h3 + oy, bz + oz, u1 + ub * uw, v1 + vb * vh, n3[1], n3[2], n3[3])
      local p4 = newV(ax + ox, h4 + oy, bz + oz, u1 + ua * uw, v1 + vb * vh, n4[1], n4[2], n4[3])
      local m = #L
      if grid.nativeFiveRidgeCells[at(mfloor((ax+bx)*.5),mfloor((az+bz)*.5))]then
        L[m+1],L[m+2],L[m+3],L[m+4],L[m+5],L[m+6]=p1,p3,p2,p1,p4,p3
      else
        L[m + 1], L[m + 2], L[m + 3], L[m + 4], L[m + 5], L[m + 6] = p1, p2, p3, p1, p3, p4
      end
    end
    -- Only exact profile-owned mixed native cap cells enter this adapter.
    -- Clip original producer triangles in source space, preserving their cap
    -- interpolation; native green is lower ground, not part of the cap.
    grid.splitNativeElevationCorner=function(L,first,c,r)
      local cornerMid,foot=c.mid,c.hgt
      local rows=c.nativeElevationCorner
      if not rows then return end
      local old={};for i=first+1,#L do old[#old+1]=L[i]end
      for i=#L,first+1,-1 do L[i]=nil end
      local du,dv=r[3]-r[1],r[4]-r[2]
      local function brown(x,y)
        if x<0 or x>15 or y<0 or y>15 then return nil end
        return x>=rows[y+1][1] and x<rows[y+1][2]
      end
      local function mix(a,b,t)
        local v={};for k,w in pairs(a)do v[k]=w end
        for k=1,8 do v[k]=a[k]+(b[k]-a[k])*t end
        return v
      end
      local function clip(poly,k,bound,greater)
        local out={};local a=poly[#poly]
        for _,b in ipairs(poly)do
          local da,db=a[k]-bound,b[k]-bound
          local ia,ib=greater and da>=-1e-12 or not greater and da<=1e-12,greater and db>=-1e-12 or not greater and db<=1e-12
          if ia~=ib then out[#out+1]=mix(a,b,da/(da-db))end
          if ib then out[#out+1]=b end;a=b
        end
        return out
      end
      local function tri(a,b,c,wall)
        local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
        local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        local nx,ny,nz=uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx
        local len=math.sqrt(nx*nx+ny*ny+nz*nz);if len<1e-12 then return end
        if not wall and ny<0 then b,c=c,b;nx,ny,nz=-nx,-ny,-nz end
        for _,v in ipairs{a,b,c}do
          local q={};for k,w in pairs(v)do q[k]=w end
          q[6],q[7],q[8]=nx/len,ny/len,nz/len;q.nativeElevationCorner=cornerMid
          L[#L+1]=q
        end
      end
      for i=1,#old,3 do
        local own=true
        for j=i,i+2 do local v=old[j];if v[4]<r[1]-1e-10 or v[4]>r[3]+1e-10 or v[5]<r[2]-1e-10 or v[5]>r[4]+1e-10 then own=false end end
        if not own then
          -- The existing cliff emitter can borrow its adjacent native brown
          -- side donor. It is a different atlas rectangle, not disposable art.
          for j=i,i+2 do L[#L+1]=old[j]end
        else
        -- A native mask interior has no material boundary. Preserve the
        -- original affine triangle there instead of subdividing each texel.
        local minU,maxU,minV,maxV=16,0,16,0
        for j=i,i+2 do local v=old[j];local u,z=(v[4]-r[1])/du*16,(v[5]-r[2])/dv*16
          minU,maxU,minV,maxV=math.min(minU,u),math.max(maxU,u),math.min(minV,z),math.max(maxV,z)
        end
        local allBrown,allGreen=true,true
        for y=math.max(0,math.floor(minV+1e-8)),math.min(15,math.ceil(maxV-1e-8)-1)do
          for x=math.max(0,math.floor(minU+1e-8)),math.min(15,math.ceil(maxU-1e-8)-1)do
            if brown(x,y)then allGreen=false else allBrown=false end
          end
        end
        local whole=allBrown or allGreen
        if whole then local a,b,c=mix(old[i],old[i],0),mix(old[i+1],old[i+1],0),mix(old[i+2],old[i+2],0)
          if allGreen then a[2],b[2],c[2]=foot,foot,foot end
          tri(a,b,c,false)
        end
        for py=0,15 do for px=0,15 do
          local poly={old[i],old[i+1],old[i+2]}
          for _,cut in ipairs{{4,r[1]+du*px/16,true},{4,r[1]+du*(px+1)/16,false},{5,r[2]+dv*py/16,true},{5,r[2]+dv*(py+1)/16,false}}do
            if #poly>0 then poly=clip(poly,cut[1],cut[2],cut[3])end
          end
            -- Surface uses each contiguous native row role, not every texel.
            if not whole and(px==0 or px==rows[py+1][1]or px==rows[py+1][2])then
              local stop=16;for _,q in ipairs(rows[py+1])do if q>px and q<stop then stop=q end end
              local surf={old[i],old[i+1],old[i+2]}
              for _,cut in ipairs{{4,r[1]+du*px/16,true},{4,r[1]+du*stop/16,false},{5,r[2]+dv*py/16,true},{5,r[2]+dv*(py+1)/16,false}}do
                if #surf>0 then surf=clip(surf,cut[1],cut[2],cut[3])end
              end
              if not brown(px,py)then for j,v in ipairs(surf)do local q=mix(v,v,0);q[2]=foot;surf[j]=q end end
              for j=2,#surf-1 do tri(surf[1],surf[j],surf[j+1],false)end
            end
          local sourceArea=0;for j,a in ipairs(poly)do local b=poly[j%#poly+1];sourceArea=sourceArea+a[4]*b[5]-b[4]*a[5]end
          if #poly>=3 and math.abs(sourceArea)>1e-18 then
            local isBrown=brown(px,py);local top=poly
            if not isBrown then poly={};for _,v in ipairs(top)do local q=mix(v,v,0);q[2]=c.hgt;poly[#poly+1]=q end end

            for j,a in ipairs(top)do local b=top[j%#top+1];local neighbor
              local ax,bx=(a[4]-r[1])/du*16,(b[4]-r[1])/du*16
              local ay,by=(a[5]-r[2])/dv*16,(b[5]-r[2])/dv*16
              if math.abs(ax-bx)<1e-7 and math.abs(ax-px)<1e-7 then neighbor=brown(px-1,py)
              elseif math.abs(ax-bx)<1e-7 and math.abs(ax-px-1)<1e-7 then neighbor=brown(px+1,py)
              elseif math.abs(ay-by)<1e-7 and math.abs(ay-py)<1e-7 then neighbor=brown(px,py-1)
              elseif math.abs(ay-by)<1e-7 and math.abs(ay-py-1)<1e-7 then neighbor=brown(px,py+1)
              else neighbor=isBrown end
              if (isBrown and neighbor==false)or(not isBrown and neighbor==nil)then
                local aa,bb=mix(a,a,0),mix(b,b,0);aa[2],bb[2]=c.hgt,c.hgt
                -- Return material is an exact opaque brown cap texel; never grass.
                local tx=isBrown and px or math.min(15,math.max(rows[py+1][1],0));local ty=py
                if rows[ty+1][1]==rows[ty+1][2]then ty=1;tx=rows[2][1]end
                local quad={mix(a,a,0),mix(b,b,0),bb,aa}
                for _,v in ipairs(quad)do v[4],v[5]=r[1]+du*(tx+.5)/16,r[2]+dv*(ty+.5)/16 end
                tri(quad[1],quad[2],quad[3],true);tri(quad[1],quad[3],quad[4],true)
              end
            end
          end
        end end
        end
      end
    end

    local function rockHF(x, y, top, r, ov, solidOver, fr, flist)
      local c = at(x, y)
      local cornerStart=#opaque
      if c.nativeElevationCorner then fr=r;flist=opaque end
      local S = hfOf(c)
      local x0, z0 = x + 0.0, y + 0.0
      if not S.any then
        if not solidOver then
          hQuad(opaque, x0, z0, x0 + 1, z0 + 1, top, r)
          if grid.nativeFiveRidgeCells[c]then local n=#opaque
            opaque[n-4],opaque[n-3]=opaque[n-3],opaque[n-4]
            opaque[n-1],opaque[n]=opaque[n],opaque[n-1]
          end
        end
        if ov then hQuad(cutoutOver, x0, z0, x0 + 1, z0 + 1, top + (solidOver and 0 or C.ROOF_OVER_LIFT), ov) end
        return
      end
      -- cuts: the union over this cell's column run (x cuts) and row run
      -- (z cuts) of rock cells -- every cell of a run cuts the shared edges
      -- at the same positions: no T-junctions, no cracks
      local xs, zs = hfRunCuts(c, 0, 1, "xs"), hfRunCuts(c, 1, 0, "zs")
      local nx, nz = #xs, #zs
      local hv, ixs, izs = {}, {}, {}
      for i = 1, nx do local q=(x0+xs[i])*HF_K;ixs[i]=grid.nativeFiveRidgeCells[c] and q or mfloor(q+.5) end
      for j = 1, nz do local q=(z0+zs[j])*HF_K;izs[j]=grid.nativeFiveRidgeCells[c] and q or mfloor(q+.5) end
      for j = 1, nz do
        local iz, o = izs[j], (j - 1) * nx
        for i = 1, nx do
          local h = hfHC[iz * 1e6 + ixs[i]]
          if h == nil then h = hfLat(ixs[i], iz) end
          hv[o + i] = h or top
        end
      end
      -- UVs: along x / z, by arc length toward a lowered side (the deeper
      -- of the two on an axis)
      local us, vs = {}, {}
      do
        local lo = S.has[1] and (S.top - S.low[1]) or 0
        local hi = S.has[2] and (S.top - S.low[2]) or 0
        for i = 1, nx do
          local t = xs[i]
          if lo == 0 and hi == 0 then us[i] = t elseif lo >= hi then us[i] = arcMap(S, 1, t) else us[i] = 1 - arcMap(S, 2, 1 - t) end
        end
        lo = S.has[3] and (S.top - S.low[3]) or 0
        hi = S.has[4] and (S.top - S.low[4]) or 0
        for j = 1, nz do
          local t = zs[j]
          if lo == 0 and hi == 0 then vs[j] = t elseif lo >= hi then vs[j] = arcMap(S, 3, t) else vs[j] = 1 - arcMap(S, 4, 1 - t) end
        end
      end
      -- (budget: drop a cut where the surface and its UVs are linear across
      -- it on every line -- the shared-run cuts only matter where the
      -- height bends; an edge vertex left out lies on the kept segment, so
      -- the neighbour's vertex there meets it: a T-junction, not a crack)
      -- KI: kept columns (tested on every row), KJ: kept rows (on KI)
      local TOL = 2e-4
      local KI, KJ = { 1 }, { 1 }
      for i = 2, nx - 1 do
        local k, e = KI[#KI], i + 1
        local span = xs[e] - xs[k]
        local lin = true
        for q = k + 1, i do
          local f = (xs[q] - xs[k]) / span
          if mabs(us[q] - (us[k] + (us[e] - us[k]) * f)) > TOL then lin = false break end
          for j = 0, (nz - 1) * nx, nx do
            local hk = hv[j + k]
            if mabs(hv[j + q] - (hk + (hv[j + e] - hk) * f)) > TOL then lin = false break end
          end
          if not lin then break end
        end
        if not lin then KI[#KI + 1] = i end
      end
      KI[#KI + 1] = nx
      local nk = #KI
      for j = 2, nz - 1 do
        local k, e = KJ[#KJ], j + 1
        local span = zs[e] - zs[k]
        local lin = true
        for q = k + 1, j do
          local f = (zs[q] - zs[k]) / span
          if mabs(vs[q] - (vs[k] + (vs[e] - vs[k]) * f)) > TOL then lin = false break end
          local ok, oq, oe = (k - 1) * nx, (q - 1) * nx, (e - 1) * nx
          for l = 1, nk do
            local i = KI[l]
            local hk = hv[ok + i]
            if mabs(hv[oq + i] - (hk + (hv[oe + i] - hk) * f)) > TOL then lin = false break end
          end
          if not lin then break end
        end
        if not lin then KJ[#KJ + 1] = j end
      end
      KJ[#KJ + 1] = nz
      if nk < nx or #KJ < nz then
        local xs2, zs2, us2, vs2, hv2, ix2, iz2 = {}, {}, {}, {}, {}, {}, {}
        for a = 1, nk do local i = KI[a]; xs2[a], us2[a], ix2[a] = xs[i], us[i], ixs[i] end
        for b = 1, #KJ do
          local j = KJ[b]
          zs2[b], vs2[b], iz2[b] = zs[j], vs[j], izs[j]
          local o2, o1 = (b - 1) * nk, (j - 1) * nx
          for a = 1, nk do hv2[o2 + a] = hv[o1 + KI[a]] end
        end
        xs, zs, us, vs, hv, nx, nz, ixs, izs = xs2, zs2, us2, vs2, hv2, nk, #KJ, ix2, iz2
      end
      -- SMOOTH vertex normals from the one height function (central
      -- differences on the lattice, one-sided at a foot): the few cuts read
      -- as a round shoulder, not facets; both cells of an edge share them
      local nv = {}
      local e2 = 2 / HF_LAT
      for j = 1, nz do
        local iz = izs[j]
        for i = 1, nx do
          local ix = ixs[i]
          local key = iz * 1e6 + ix
          local cn = hfNC[key]
          if not cn then
            local hc = hv[(j - 1) * nx + i]
            local sx, sz = ix % HF_ST == 0 and HF_ST or 1, iz % HF_ST == 0 and HF_ST or 1
            local hl, hr, hu, hd = hfLat(ix - sx, iz), hfLat(ix + sx, iz), hfLat(ix, iz - sz), hfLat(ix, iz + sz)
            local gx, gz
            if sx == HF_ST then gx = (hl and hr) and (hr - hl) / e2 or hr and (hr - hc) * HF_LAT or hl and (hc - hl) * HF_LAT or 0
            else gx = (hl and hr) and (hr - hl) * HF_K * 0.5 or hr and (hr - hc) * HF_K or hl and (hc - hl) * HF_K or 0 end
            if sz == HF_ST then gz = (hu and hd) and (hd - hu) / e2 or hd and (hd - hc) * HF_LAT or hu and (hc - hu) * HF_LAT or 0
            else gz = (hu and hd) and (hd - hu) * HF_K * 0.5 or hd and (hd - hc) * HF_K or hu and (hc - hu) * HF_K or 0 end
            -- (ledgefinal1: at the foot of a SOFT side -- lowered to a hill
            -- band's base, a smoothstep foot -- the slope across the side is
            -- 0: level, like the band's foot beside it)
            if not (hl and hr and hu and hd) then
              local softSide = grid.rockSoftSide
              local fx, fz = mfloor(ix / HF_K), mfloor(iz / HF_K)
              if iz % HF_K == 0 then
                if not hd and (softSide(fx, fz - 1, 4) or (ix % HF_K == 0 and softSide(fx - 1, fz - 1, 4))) then gz = 0 end
                if not hu and (softSide(fx, fz, 3) or (ix % HF_K == 0 and softSide(fx - 1, fz, 3))) then gz = 0 end
              end
              if ix % HF_K == 0 then
                if not hr and (softSide(fx - 1, fz, 2) or (iz % HF_K == 0 and softSide(fx - 1, fz - 1, 2))) then gx = 0 end
                if not hl and (softSide(fx, fz, 1) or (iz % HF_K == 0 and softSide(fx, fz - 1, 1))) then gx = 0 end
              end
            end
            local l = msqrt(gx * gx + 1 + gz * gz)
            cn = { -gx / l, 1 / l, -gz / l }
            hfNC[key] = cn
          end
          nv[(j - 1) * nx + i] = cn
        end
      end
      local lift = solidOver and 0 or C.ROOF_OVER_LIFT
      local steepFace = flist == opaque and fr ~= r
      local r1, r2, rw, rh = r[1], r[2], r[3] - r[1], r[4] - r[2]
      local o1, o2, ow, oh
      if ov then o1, o2, ow, oh = ov[1], ov[2], ov[3] - ov[1], ov[4] - ov[2] end
      local f1, f2, fw, fh = fr[1], fr[2], fr[3] - fr[1], fr[4] - fr[2]
      for j = 1, nz - 1 do
        local az, bz, va, vb = z0 + zs[j], z0 + zs[j + 1], vs[j], vs[j + 1]
        local oa, ob = (j - 1) * nx, j * nx
        for i = 1, nx - 1 do
          local ax, bx = x0 + xs[i], x0 + xs[i + 1]
          local h1, h2, h3, h4 = hv[oa + i], hv[oa + i + 1], hv[ob + i + 1], hv[ob + i]
          local ex1, ey1, ez1 = bx - ax, h3 - h1, bz - az
          local ex2, ey2, ez2 = ax - bx, h4 - h2, bz - az
          local nnx = ey1 * ez2 - ez1 * ey2
          local nny = ez1 * ex2 - ex1 * ez2
          local nnz = ex1 * ey2 - ey1 * ex2
          if nny < 0 then nnx, nny, nnz = -nnx, -nny, -nnz end
          local nl = msqrt(nnx * nnx + nny * nny + nnz * nnz)
          nnx, nny, nnz = nnx / nl, nny / nl, nnz / nl
          local ua, ub = us[i], us[i + 1]
          local n1, n2, n3, n4 = nv[oa + i], nv[oa + i + 1], nv[ob + i + 1], nv[ob + i]
          local hmax, hmin = mmax(h1, h2, h3, h4), mmin(h1, h2, h3, h4)
          if steepFace and hmax - hmin > 1.2 * mmax(bx - ax, bz - az) then
            hfEmit(opaque, f1, f2, fw, fh, 0, nnx, nny, nnz, ax, bx, az, bz, h1, h2, h3, h4, ua, ub, va, vb, n1, n2, n3, n4)
          else
            if not solidOver then hfEmit(opaque, r1, r2, rw, rh, 0, nnx, nny, nnz, ax, bx, az, bz, h1, h2, h3, h4, ua, ub, va, vb, n1, n2, n3, n4) end
            -- (the over layer lifted along the quad's normal: straight up
            -- would keep a steep quad in its under layer's plane; none
            -- over transparent texels only)
            if ov and ovAny(c.mid, ua, ub, va, vb) then
              hfEmit(cutoutOver, o1, o2, ow, oh, lift, nnx, nny, nnz, ax, bx, az, bz, h1, h2, h3, h4, ua, ub, va, vb, n1, n2, n3, n4)
            end
          end
        end
      end
      if c.nativeElevationCorner then grid.splitNativeElevationCorner(opaque,cornerStart,c,r)end
    end
    -- r12 (DS-hook report 2c: "lathe boulders for lone rocks"): a LONE rock
    -- cell (no rock beside it) whose art is a boulder on ground -- its four
    -- corner texels one ground colour -- is a solid of revolution sized from
    -- its own silhouette: as wide as the art's widest row, tucked at the
    -- foot as its bottom row, a dome to an apex at the rock's height.
    -- BOULDER_SEGS around (~74 triangles), smooth normals; the art laid on
    -- as the 3/4 view draws it (a point's texel row from how far south and
    -- how high it is, its column within that row's drawn span -- rock
    -- texels only); the ground under it is the nearest plain tile. false ->
    -- not a boulder (the heightfield).
    local function rockLathe(c, x, y, top, r)
      if not atlasTex or c.hasOver then return false end
      for _, d in ipairs(DIRS) do
        if isRock(at(x + d.dx, y + d.dy)) then return false end
      end
      local u = atlasTex(c.mid, "under")
      if not u then return false end
      local gcol = u[1]
      if u[16] ~= gcol or u[241] ~= gcol or u[256] ~= gcol then return false end
      local gm = c.nearMid
      if not gm then
        for _, d in ipairs(DIRS) do
          local n = at(x + d.dx, y + d.dy)
          if n and n.walkable and not n.isWater then gm = n.mid break end
        end
      end
      local guv = gm and underRect(gm)
      if not guv then return false end
      -- silhouette: per row the drawn span (texels other than the ground
      -- colour)
      local w, t0, b0 = {}, nil, nil
      for row = 0, 15 do
        local lo, hi = nil, nil
        for col = 0, 15 do
          if u[row * 16 + col + 1] ~= gcol then
            lo = lo or col
            hi = col
          end
        end
        w[row] = lo and (hi - lo + 1) / 16 or 0
        if lo then t0 = t0 or row; b0 = row end
      end
      if not t0 or b0 - t0 < 8 then return false end
      -- a boulder is narrow at its top and bottom rows, full in the middle
      if w[t0] > 0.8 or w[b0] > 0.8 then return false end
      local g0 = c.hgt
      local Ht = top - g0
      -- the profile: a boulder, not a barrel -- tucked at the foot, widest
      -- low down, then a dome to the apex; its widest radius the art's
      -- widest row, the foot's the art's bottom row (relative)
      local wmax, lo16, hi16 = 0, {}, {}
      for row = t0, b0 do wmax = mmax(wmax, w[row]) end
      local R = mmin(C.BOULDER_R_MAX, wmax * 0.5)
      local foot = mmax(0.6, mmin(0.9, w[b0] / wmax))
      local rings = { { 0, foot }, { 0.18, 0.93 }, { 0.42, 1.0 }, { 0.66, 0.86 }, { 0.86, 0.55 } }
      for _, rg in ipairs(rings) do rg[1], rg[2] = rg[1] * Ht, rg[2] * R end
      local nR = #rings
      -- ring normals from the profile (radial, up)
      for k = 1, nR do
        local pa = rings[mmax(1, k - 1)]
        local pb = rings[k + 1] or { Ht, 0 }
        local dr, dh = pb[2] - pa[2], pb[1] - pa[1]
        local nr, nh = dh, -dr
        local l = msqrt(nr * nr + nh * nh)
        if l < 1e-9 then nr, nh = 1, 0 else nr, nh = nr / l, nh / l end
        rings[k][3], rings[k][4] = nr, nh
      end
      -- the art as the 3/4 view draws it: a point dz south of the centre, h
      -- up, shows on texel row 16 (0.5 + dz) - k h, k so the apex lands on
      -- the top row; across, the row's own drawn span (rock texels only)
      local kk = (8 - t0) / Ht
      for row = 0, 15 do
        local lo, hi
        for col = 0, 15 do
          if u[row * 16 + col + 1] ~= gcol then lo = lo or col; hi = col end
        end
        lo16[row], hi16[row] = lo or 6, (hi or 9) + 1
      end
      local ur, vr = r[3] - r[1], r[4] - r[2]
      local function uvAt(dx, dz, h, rad)
        local row = 16 * (0.5 + dz) - kk * h
        if row < t0 + 0.5 then row = t0 + 0.5 elseif row > b0 + 0.5 then row = b0 + 0.5 end
        local ri = mfloor(row)
        local f = rad > 1e-6 and (0.5 + 0.5 * dx / rad) or 0.5
        local col = lo16[ri] + (hi16[ri] - lo16[ri]) * mmax(0.02, mmin(0.98, f))
        return r[1] + col / 16 * ur, r[2] + row / 16 * vr
      end
      local cx, cz = x + 0.5, y + 0.5
      local SEG = C.BOULDER_SEGS
      local function V(k, j)
        local rg = rings[k]
        local ph = (j % SEG) / SEG * math.pi * 2
        local co, si = math.cos(ph), math.sin(ph)
        local uu, vv = uvAt(co * rg[2], si * rg[2], rg[1], rg[2])
        return newV(cx + co * rg[2], g0 + rg[1], cz + si * rg[2], uu, vv, co * rg[3], rg[4], si * rg[3])
      end
      hQuad(opaque, x + 0.0, y + 0.0, x + 1.0, y + 1.0, g0, guv)
      local m
      for k = 1, nR - 1 do
        for j = 0, SEG - 1 do
          local va, vb, vc, vd = V(k, j), V(k, j + 1), V(k + 1, j + 1), V(k + 1, j)
          m = #opaque
          -- (wound so the geometric normal faces out, like the vertex normals)
          opaque[m + 1], opaque[m + 2], opaque[m + 3], opaque[m + 4], opaque[m + 5], opaque[m + 6] = va, vc, vb, va, vd, vc
        end
      end
      local au, av = uvAt(0, 0, Ht, 0)
      local apex = newV(cx, g0 + Ht, cz, au, av, 0, 1, 0)
      for j = 0, SEG - 1 do
        m = #opaque
        opaque[m + 1], opaque[m + 2], opaque[m + 3] = V(nR, j), apex, V(nR, j + 1)
      end
      grid.boulders = (grid.boulders or 0) + 1
      return true
    end
    -- A guarded terrace can border a separate native boulder. Preserve that
    -- boulder's original height-field context only while its own emitter runs.
    -- Candidate caches are never populated from this temporary context.
    local isolatedRockHF = rockHF
    local elevationInterface={}
    local function recordElevationEdge(x,y,first)
      if not grid.nativeElevationRockContext or (x~=27 and x~=28)or(y~=12 and y~=13)then return end
      local t=elevationInterface[y]or{};elevationInterface[y]=t
      for i=first+1,#opaque,3 do
        for j=0,2 do local a,b=opaque[i+j],opaque[i+(j+1)%3]
          if math.abs(a[3]-13)<1e-10 and math.abs(b[3]-13)<1e-10 and math.abs(a[1]-b[1])>1e-10 then
            if a[1]>b[1]then a,b=b,a end
