            for _,f in ipairs(fields)do old[f]=c[f]end
            saved[#saved+1]=old
            c.hgt=p[3];c.rockTop=p[4]or nil;c.rampH=nil
            c.nativeElevationRidge=nil;c.nativeElevationCorner=nil
          end
