          hfSet,hfHC,hfNC=legacySet,legacyHC,legacyNC;runCache=legacyRuns
          grid.nativeFiveRidgeCells={}
          local ok,err=pcall(rockHF,x,y,top,r,ov,solidOver,fr,flist)
          legacySet,legacyHC,legacyNC=hfSet,hfHC,hfNC;legacyRuns=runCache
          hfSet,hfHC,hfNC=set,hc,nc;grid.nativeFiveRidgeCells=refined;runCache=runs
          for _,old in ipairs(saved)do for _,f in ipairs(fields)do old.cell[f]=old[f]end end
          if not ok then error(err,0)end
          recordElevationEdge(x,y,first)
        end
      end
    end
    local function closeElevationInterface()
      if not grid.nativeElevationRockContext then return end
      local north,south=elevationInterface[12],elevationInterface[13]
      assert(north and south,'missing guarded terrace/boulder interface')
      local function height(t,x)
        for _,e in ipairs(t)do if x>=e[1]-1e-10 and x<=e[3]+1e-10 then return e[2]+(e[4]-e[2])*(x-e[1])/(e[3]-e[1])end end
        error('uncovered guarded interface')
      end
      local cuts={}
      local function add(x)for _,v in ipairs(cuts)do if math.abs(v-x)<1e-10 then return end end;cuts[#cuts+1]=x end
      for _,t in ipairs{north,south}do for _,e in ipairs(t)do add(e[1]);add(e[3])end end
      table.sort(cuts)
      local roots={}
      for i=1,#cuts-1 do local a,b=cuts[i],cuts[i+1]
        local da,db=height(south,a)-height(north,a),height(south,b)-height(north,b)
        if da*db<0 then roots[#roots+1]=a+(b-a)*da/(da-db)end
      end
      for _,x in ipairs(roots)do add(x)end;table.sort(cuts)
      local r=underRect(121)
      for i=1,#cuts-1 do local a,b=cuts[i],cuts[i+1]
        local an,bn,as,bs=height(north,a),height(north,b),height(south,a),height(south,b)
        if math.max(math.abs(as-an),math.abs(bs-bn))>1e-10 then
          local nz=(as+bs>an+bn)and -1 or 1
          local lowa,higha=math.min(an,as),math.max(an,as)
          local lowb,highb=math.min(bn,bs),math.max(bn,bs)
          local function v(x,y,high)
            local q=newV(x,y,13,r[1]+(r[3]-r[1])*(x-math.floor((a+b)*.5)),r[2]+(r[4]-r[2])*(high and 0 or 6/16),0,0,nz)
            q.nativeElevationInterface='rock:27:12';return q
          end
          local q={v(a,lowa,false),v(b,lowb,false),v(b,highb,true),v(a,higha,true)}
          for _,idx in ipairs{{1,2,3},{1,3,4}}do local u,vv,w=q[idx[1]],q[idx[2]],q[idx[3]]
            local cross=(vv[1]-u[1])*(w[2]-u[2])-(vv[2]-u[2])*(w[1]-u[1])
            if math.abs(cross)>1e-12 then if cross*nz<0 then vv,w=w,vv end
              opaque[#opaque+1]=u;opaque[#opaque+1]=vv;opaque[#opaque+1]=w
            end
          end
        end
      end
    end

    for y = 0, H - 1 do
      if y % 4 == 0 then Y() end
      for x = 0, W - 1 do
        local c = grid[y][x]
        if (c.nativeSaffronThin or grid.isCompiledShrub(c)) and isRock(c) then rockTop(c) end
        if isRock(c) and not c.nativeSaffronThin and not grid.isCompiledShrub(c) then
          if c.nativeRoute12Exterior then c.route12Marks={#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed} end
          local mountainStart=grid.recordBondMountainCoast and ((x==0 and y>=14)or(y==19 and x<=24)) and #opaque
          local bondStart=grid.nativeBondWestCoast and x==0 and y==13 and #opaque
