            local x0, z0, x1, z1 = x + 0.0, y + 0.0, x + 1.0, y + 1.0
            local top = rockTop(c)
            local ov = c.hasOver and not c.nativeMixedTipOwned and not c.nativeSafariWestOverlay and overRect(c.mid) or nil
            local solidOver = ov and (overCoverage(c.mid) or 0) >= C.ROOF_SOLID_MIN
            local fr = r
            if solidOver then fr = ov end
            local flist = solidOver and cutoutOver or opaque
