                    end
                  end
                end
              end
            elseif not rockLathe(c, x, y, top, r) then isolatedRockHF(x, y, top, r, ov, solidOver, fr, flist) end
          end
          if bondStart then grid.recordBondMountain(bondStart)end
          if mountainStart then grid.recordBondMountainCoast(mountainStart,x,y)end
          if c.route12Marks then for k,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do for i=#list,c.route12Marks[k]+1,-1 do list[i]=nil end end;c.route12Marks=nil end
        end
      end
    end
    closeElevationInterface()
  end

  grid.boundaryMark(false)
  -- Native closed rock borders: root owns only the exposed height difference.
  -- Root rounded terrain and sparse border boxes otherwise both omit the seam.
  do
    local atlasTex=type(atlas.texels)=="function" and atlas.texels or nil
    local sigs={FR_LAVENDER_TOWN=4027198861,FR_ROUTE_8=3193047770}
    local expected=sigs[input.mapId]
    if expected and type(input.boundaryBorderAt)=="function" and not isBorder and not cave and input.pair=="general__rom_082d4b0c" and H==20 and W==(input.mapId=="FR_LAVENDER_TOWN" and 24 or 72) then
      local hash=0
      for yy=0,H-1 do for xx=0,W-1 do local c=input.cellAt(xx,yy)
        hash=(hash*33+((c and c.mid)or -2)+1)%4294967291
        hash=(hash*33+((c and c.elevation)or -2)+1)%4294967291
      end end
      local art=0
      for _,layer in ipairs({'under','over'})do local t=atlasTex and atlasTex(113,layer)
        for i=1,256 do art=(art*33+((t and t[i])or -1)+2)%4294967291 end
      end
      if hash==expected and art==369165754 then
        local borders=input.mapId=="FR_LAVENDER_TOWN" and {{axis=1,p=W,n=H,nx=1,nz=0}} or {{axis=3,p=0,n=W,nx=0,nz=-1},{axis=3,p=H,n=W,nx=0,nz=1}}
        -- Exact native border rows are blocked113 at elevation3. Their dense
        -- inner rock-box row is ROCK_H0 above that ground (native fixture guard).
        local bt=3*C.ELEV_UNIT+C.ROCK_H0
        local r=underRect(113)
        local first=#opaque;local faces=0;local bridgeVertices={};local maxSegments=0
        for _,edge in ipairs(borders)do
          Y()
          local native=true
          for k=0,edge.n-1 do
            local x=edge.axis==1 and W or k
            local y=edge.axis==3 and (edge.p==0 and -1 or H) or k
            local mid,elev=input.boundaryBorderAt(x,y)
            if mid~=113 or elev~=3 then native=false;break end
          end
          if native then
          local along=edge.axis==1 and 3 or 1
          local segments,cuts={},{}
          for i=0,edge.n do cuts[#cuts+1]=i end
          for _,range in ipairs(grid.boundaryTerrain or {})do
            local list=range[1]
            for i=range[2],range[3],3 do local a,b,c=list[i],list[i+1],list[i+2]
              local area=(b[1]-a[1])*(c[3]-a[3])-(b[3]-a[3])*(c[1]-a[1])
              if math.abs(area)>EPS then
                local hit={};for _,v in ipairs({a,b,c})do if math.abs(v[edge.axis]-edge.p)<EPS then hit[#hit+1]=v end end
                if #hit==2 then local a,b=hit[1],hit[2];if a[along]>b[along]then a,b=b,a end
                  if b[along]-a[along]>EPS then
                    local s={a[along],b[along],a[2],b[2]};segments[#segments+1]=s
                    cuts[#cuts+1],cuts[#cuts+2]=s[1],s[2]
                    if (s[3]-bt)*(s[4]-bt)<0 then cuts[#cuts+1]=s[1]+(s[2]-s[1])*(bt-s[3])/(s[4]-s[3])end
                  end
                end
              end
            end
          end
          maxSegments=math.max(maxSegments,#segments)
          if #segments<=edge.n*32 then
          local function atHeight(s,t)return s[3]+(s[4]-s[3])*(t-s[1])/(s[2]-s[1])end
          -- Split crossings so an upper-envelope owner never changes mid-face.
          for i=1,#segments do local a=segments[i];if i%16==0 then Y()end
            for j=i+1,#segments do local b=segments[j];local l,h=math.max(a[1],b[1]),math.min(a[2],b[2])
              if h-l>EPS then local dl,dh=atHeight(a,l)-atHeight(b,l),atHeight(a,h)-atHeight(b,h)
                if dl*dh<0 then cuts[#cuts+1]=l+(h-l)*dl/(dl-dh)end
              end
            end
          end
          table.sort(cuts);local unique={}
          for _,t in ipairs(cuts)do if #unique==0 or t-unique[#unique]>EPS then unique[#unique+1]=t end end
          for k=1,#unique-1 do local a,b=unique[k],unique[k+1];local mid=(a+b)*.5;local chosen,top
            if a>=-EPS and b<=edge.n+EPS then
              for _,s in ipairs(segments)do if mid>=s[1]-EPS and mid<=s[2]+EPS then local h=atHeight(s,mid);if not top or h>top then chosen,top=s,h end end end
              if chosen and math.abs(top-bt)>EPS then
                local ha,hb=atHeight(chosen,a),atHeight(chosen,b)
                local la,lb,ua,ub=math.min(ha,bt),math.min(hb,bt),math.max(ha,bt),math.max(hb,bt)
                local ax,az=edge.axis==1 and edge.p or a,edge.axis==3 and edge.p or a
                local bx,bz=edge.axis==1 and edge.p or b,edge.axis==3 and edge.p or b
                local u0,u1=a-math.floor(mid),b-math.floor(mid)
                local U0,U1=r[1]+(r[3]-r[1])*u0,r[1]+(r[3]-r[1])*u1
                local sign=top>bt and 1 or -1
                local cx=edge.axis==1 and W-1 or math.floor(mid)
                local cz=edge.axis==3 and (edge.p==0 and 0 or H-1) or math.floor(mid)
                local owner=at(cx,cz)
                local anchor=top>bt and (owner.rockTop or (owner.hgt+C.ROCK_H0)) or bt
                local function V(h)return r[2]+(r[4]-r[2])*math.max(0,math.min(1,(anchor-h)/C.ROCK_H0))end
                if top<=bt or (owner and owner.rock)then
                quadN(bridgeVertices,ax,la,az,U0,V(la),bx,lb,bz,U1,V(lb),bx,ub,bz,U1,V(ub),ax,ua,az,U0,V(ua),edge.nx*sign,0,edge.nz*sign)
                faces=faces+1
                end -- root-winning closure requires the native rock owner
              end
            end
          end
          end -- bounded edge-local segmentation
          end -- validated actual native border cells
        end
        grid.boundaryFinish=function()
          local start=#opaque+1
          for _,v in ipairs(bridgeVertices)do opaque[#opaque+1]=v end
          grid.nativeBoundaryBridge={faces=faces,maxSegments=maxSegments,base=3*C.ELEV_UNIT,borderTop=bt,firstVertex=start,lastVertex=#opaque}
        end
      end
    end
  end

  grid.boundaryTerrain=nil
  grid.boundaryStart=nil
  grid.boundaryMark=nil
  -- ---------------------------------------------------------------
  -- Pass 3c (r8 caves; r12 review M5 / M14): every solid cell is rock,
  -- extruded CAVE_WALL_H above its ground. Per column run of rock (the rock
  -- cells of one column between non-rock ones) whose south neighbour is
  -- open (present, not rock):
  --   south face = the column drawing's face rows stacked into CAVE_WALL_H:
  --               the bottom row's tile, under the row above's bottom face
  --               texel rows (MB.TILE_SHAPES fb: the tiles of a two-row
  --               cliff; none -> the bottom tile stretched); below a lower
  --               floor, the bottom row's tile again.
  --   tops      = each cell's own art, except: the row above the bottom
  --               loses its face rows; the bottom row shows the row above's
  --               remaining art (a component's plain top when that row is
  --               the rock's north rim).
  --   W / E / N faces = the component's face tile (its most common bottom-
  --               row tile with rock both sides), never a top tile.
  -- MB.TILE_SHAPES[pair][mid] (generated from the atlas: floor-coloured
  -- texels) shapes a top: ch = a chamfer (the floor triangle at that corner
  -- sits at floor height, a slanted face along the diagonal) when both
  -- open-corner neighbours are open; q = 8x8 quarters at floor height;
  -- t / b / l / r = floor texel lines cropped off the top's edges;
  -- boulder = a loose rock (floor + a low tapered rock, faces from its
  -- floor-free rect).
  -- ---------------------------------------------------------------
  local rockCells = 0
  if cave then
    local RH = C.CAVE_WALL_H
    local shapes = IN.shapes
    -- the bottom rows of a tile that still belong to the cliff face below
    -- it (TILE_SHAPES fb, texels; stacked tiles of a two-row cliff)
    local function fbOf(c)
      local sh = c and shapes and shapes[c.mid]
      return sh and sh.fb and sh.fb / 16 or 0
    end
    local ST = C.WALL_STRIP_TEXELS / 16
    local function isRock(c) return c and compOf(c) ~= nil and not c.boulderC and not c.nativeLooseRock end
    -- RockTunnel-only rounded upper shoulders stay inside blocked footprints.
    -- The support query and every plateau height remain unchanged.
    local function shoulderEligible(c)
      if not (grid.caveNativeArt and (input.mapId=="FR_ROCK_TUNNEL_1F" or input.mapId=="FR_ROCK_TUNNEL_B1F") and isRock(c)) then return false end
      local sh=shapes and shapes[c.mid]
      return not(c.hasOver or c.chm or c.qm or c.caveCleanMid or c.mid==712 or c.mid==713 or c.mid==714
        )
    end
    local function shoulderHeight(wx,wz,top)
      local open,protect=1,1
      local ix,iz=math.floor(wx),math.floor(wz)
      for yy=iz-1,iz+1 do for xx=ix-1,ix+1 do local n=at(xx,yy)
        if n then
          local dx=math.max(xx-wx,0,wx-(xx+1));local dz=math.max(yy-wz,0,wz-(yy+1));local dist=math.sqrt(dx*dx+dz*dz)
          if not isRock(n) then open=math.min(open,dist)
          elseif not shoulderEligible(n) or math.abs(n.hgt+RH-top)>EPS then protect=math.min(protect,dist) end
        end
      end end
      local radius=.15
      local t=math.min(1,open/radius)
      return top-radius*(1-math.sin(t*math.pi*.5))*math.min(1,protect/radius)
    end
    local function shoulderTop(c,x0,z0,x1,z1,top,r,fr)
      if not shoulderEligible(c) then return false end
      local shaped=false
      for _,q in ipairs({{0,0},{.5,0},{1,0},{0,.5},{1,.5},{0,1},{.5,1},{1,1}})do
        if shoulderHeight(x0+q[1],z0+q[2],top)<top-EPS then shaped=true;break end
      end
      if not shaped then return false end
      local cuts={0,.075,.15,.85,.925,1}
      local varyX,varyZ=false,false
      for _,t in ipairs(cuts)do
        local hx=shoulderHeight(x0+.5,z0+t,top);local hz=shoulderHeight(x0+t,z0+.5,top)
        if math.abs(shoulderHeight(x0,z0+t,top)-hx)>EPS or math.abs(shoulderHeight(x1,z0+t,top)-hx)>EPS then varyX=true end
        if math.abs(shoulderHeight(x0+t,z0,top)-hz)>EPS or math.abs(shoulderHeight(x0+t,z1,top)-hz)>EPS then varyZ=true end
      end
      local xs=varyX and cuts or {0,1};local zs=varyZ and cuts or {0,1}
      local function point(u,v)
        local px,pz=x0+u,z0+v;local h=shoulderHeight(px,pz,top);local e=.001
        local gx=(shoulderHeight(px+e,pz,top)-shoulderHeight(px-e,pz,top))/(2*e)
        local gz=(shoulderHeight(px,pz+e,top)-shoulderHeight(px,pz-e,top))/(2*e)
        return {{px,h,pz},{r[1]+(r[3]-r[1])*u,r[2]+(r[4]-r[2])*v}},norm3({-gx,1,-gz})
      end
      for iz=1,#zs-1 do for ix=1,#xs-1 do
        local a,na=point(xs[ix],zs[iz]);local b,nb=point(xs[ix+1],zs[iz]);local cc,nc=point(xs[ix+1],zs[iz+1]);local dd,nd=point(xs[ix],zs[iz+1])
        grid.quadV4(opaque,{a,b,cc,dd},{na,nb,nc,nd})
      end end
      -- Close the upper band to the retained wall below, including its
      -- transition beside a protected native corner/portal/ladder backing.
      for _,d in ipairs(DIRS)do local nb=at(c.x+d.dx,c.y+d.dy)
        if nb and not isRock(nb) and fr then
          local A,B
          if d.name=="up"then A,B={x1,z0},{x0,z0}
          elseif d.name=="down"then A,B={x0,z1},{x1,z1}
          elseif d.name=="left"then A,B={x0,z0},{x0,z1}
          else A,B={x1,z1},{x1,z0}end
          for i=1,#cuts-1 do local u,v=cuts[i],cuts[i+1]
            local ax,az=A[1]+(B[1]-A[1])*u,A[2]+(B[2]-A[2])*u
            local bx,bz=A[1]+(B[1]-A[1])*v,A[2]+(B[2]-A[2])*v
            local ah,bh=shoulderHeight(ax,az,top),shoulderHeight(bx,bz,top);local low=top-.15
            if ah>low+EPS or bh>low+EPS then
              local rr=subRect(subRect(fr,.25,.25,.75,.75),u,0,v,.15);local n={d.dx,0,d.dy}
              quadN(opaque,ax,low,az,rr[1],rr[4],bx,low,bz,rr[3],rr[4],bx,bh,bz,rr[3],rr[2],ax,ah,az,rr[1],rr[2],n[1],n[2],n[3])
            end
          end
        end
      end
      IN.caveStats.shoulderCells=(IN.caveStats.shoulderCells or 0)+1
      return true
    end
    -- Connected painted rock tiles remain separate props; infer their common
    -- floor from adjacent walktops, never changing actor/warp support heights.
    do
      local seen={}
      for yy=0,H-1 do for xx=0,W-1 do local c=at(xx,yy)
        if c and c.nativeLooseRock and not seen[c] then
          local queue={c};seen[c]=true;local head=1;local base=c.hgt
          while queue[head] do local p=queue[head];head=head+1
            if p.nativeLadderCell then base=math.max(base,p.nativeLadderCell.hgt) end
            for _,d in ipairs(DIRS)do local n=at(p.x+d.dx,p.y+d.dy)
              if n and n.nativeLooseRock and not seen[n]then seen[n]=true;queue[#queue+1]=n
              elseif n and n.walkable and not n.isWater and n.beh~=0x2A then base=math.max(base,n.hgt) end
            end
          end
          for _,p in ipairs(queue)do p.nativeRockBase=base end
        end
      end end
    end
    function grid.drawNativeLooseRock(c)
      local base=c.nativeRockBase;local floor=underRect(641)
      hQuad(opaque,c.x,c.y,c.x+1,c.y+1,base,floor)
      -- A loose prop can sit on a small native floor above water. Close only
      -- that floor's exposed low bank, without restoring a tall cliff body.
      for _,d in ipairs(DIRS)do local n=at(c.x+d.dx,c.y+d.dy);local low
        if n and n.nativeLooseRock then low=n.nativeRockBase
        elseif n and (n.walkable or n.isWater)then low=n.hgt end
        if low and low<base-EPS then
          local rr=n.isWater and subRectV(underRect(291),0,3/16) or floor
          faceQuad(opaque,d.name,c.x,c.x+1,c.y,c.y+1,low,base,rr)
        end
      end
      local r=underRect(c.nativeLooseMid or c.mid)
      for _,p in ipairs(c.nativeLooseRock)do
        local rr=subRect(r,p[1]/16,p[2]/16,p[3]/16,p[4]/16)
        local cx,cz=c.x+p[5],c.y+p[6];local rad,h=p[7],p[8]
        local profile={{0,.72},{.22,1},{.68,.86},{.92,.49}}
        for j=1,#profile-1 do local low,high=profile[j],profile[j+1]
          for i=0,7 do local a,b=i*math.pi/4,(i+1)*math.pi/4
            local ax,az=cx+math.cos(a)*rad*low[2],cz+math.sin(a)*rad*low[2]
            local bx,bz=cx+math.cos(b)*rad*low[2],cz+math.sin(b)*rad*low[2]
            local tx,tz=cx+math.cos(a)*rad*high[2],cz+math.sin(a)*rad*high[2]
            local ux,uz=cx+math.cos(b)*rad*high[2],cz+math.sin(b)*rad*high[2]
            local nn=faceNormal3({bx,base+low[1]*h,bz},{ax,base+low[1]*h,az},{tx,base+high[1]*h,tz})
            local v0=rr[4]-(rr[4]-rr[2])*low[1];local v1=rr[4]-(rr[4]-rr[2])*high[1]
            local useX=math.abs(nn[3])>=math.abs(nn[1])
            local function texu(x,z)return rr[1]+(rr[3]-rr[1])*(.5+((useX and x-cx or z-cz)/(2*rad)))end
            quadN(opaque,bx,base+low[1]*h,bz,texu(bx,bz),v0,ax,base+low[1]*h,az,texu(ax,az),v0,tx,base+high[1]*h,tz,texu(tx,tz),v1,ux,base+high[1]*h,uz,texu(ux,uz),v1,nn[1],nn[2],nn[3])
          end
        end
        for i=0,7 do local a,b=i*math.pi/4,(i+1)*math.pi/4
          local ax,az=cx+math.cos(a)*rad*.49,cz+math.sin(a)*rad*.49
          local bx,bz=cx+math.cos(b)*rad*.49,cz+math.sin(b)*rad*.49
          local function uv(x,z)return {rr[1]+(rr[3]-rr[1])*(.5+(x-cx)/(2*rad)),rr[2]+(rr[4]-rr[2])*(.24+(z-cz)/(4*rad))}end
          local nn=faceNormal3({bx,base+h*.92,bz},{ax,base+h*.92,az},{cx,base+h,cz})
          tri3(opaque,{bx,base+h*.92,bz},uv(bx,bz),nn,{ax,base+h*.92,az},uv(ax,az),nn,{cx,base+h,cz},uv(cx,cz),nn)
        end
      end
    end
    -- boulders first: they are not rock for their neighbours
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        local sh = c and shapes and shapes[c.mid]
        if sh and sh.boulder and sh.sw and compOf(c) and not c.nativeLooseRock then
          local nr = 0
          for _, d in ipairs(DIRS) do
            local nb = at(x + d.dx, y + d.dy)
            if nb and compOf(nb) and not (shapes[nb.mid] and shapes[nb.mid].boulder) then nr = nr + 1 end
          end
          if nr <= C.CAVE_BOULDER_MAX_ROCK then
            c.boulderC = sh
            IN.caveStats.boulders = IN.caveStats.boulders + 1
          end
        end
      end
    end
    local function rockTop(c) return c.hgt + RH end
    -- column runs: runA / runB per rock cell; face rows
    for x = 0, W - 1 do
      local y = 0
      while y < H do
        if isRock(grid[y][x]) then
          local a, b = y, y
          while b + 1 < H and isRock(grid[b + 1][x]) do b = b + 1 end
          local s = at(x, b + 1)
          local face = s ~= nil
          for yy = a, b do
            local p = grid[yy][x]
            p.runA, p.runB, p.runFace = a, b, face
          end
          y = b + 1
        else
          y = y + 1
        end
      end
    end
    -- per component: face tile and plain top tile
    local faceOf, plainOf = {}, {}
    do
      local fc, fcAny, pc = {}, {}, {}
      for y = 0, H - 1 do
        for x = 0, W - 1 do
          local c = grid[y][x]
          if isRock(c) then
            local comp = compOf(c)
            if c.runFace and c.runB == y then
              fcAny[comp] = fcAny[comp] or {}
              fcAny[comp][c.caveCleanMid or c.mid] = (fcAny[comp][c.caveCleanMid or c.mid] or 0) + 1
              if isRock(at(x - 1, y)) and isRock(at(x + 1, y)) then
                fc[comp] = fc[comp] or {}
                fc[comp][c.caveCleanMid or c.mid] = (fc[comp][c.caveCleanMid or c.mid] or 0) + 1
              end
            end
            local inner = true
            for _, d in ipairs(DIRS) do if not isRock(at(x + d.dx, y + d.dy)) then inner = false end end
            if inner and not (shapes and shapes[c.mid]) then
              pc[comp] = pc[comp] or {}
              pc[comp][c.mid] = (pc[comp][c.mid] or 0) + 1
            end
          end
        end
      end
      local function best(t)
        local bm, bn
        for m, n in pairs(t) do if bn == nil or n > bn or (n == bn and m < bm) then bm, bn = m, n end end
        return bm
      end
      for comp, t in pairs(fcAny) do faceOf[comp] = best(fc[comp] or t) end
      for comp, t in pairs(pc) do plainOf[comp] = best(t) end
      -- a component with no cliff face row of its own: the map's most
      -- common middle face tile
      local all = {}
      for _, t in pairs(fc) do for m, n in pairs(t) do all[m] = (all[m] or 0) + n end end
      if next(all) == nil then for _, t in pairs(fcAny) do for m, n in pairs(t) do all[m] = (all[m] or 0) + n end end end
      faceOf.map = best(all)
    end
    -- faces: [low, top] with a tile r: stretched up to CAVE_WALL_H; a
    -- taller face gets the full tile under the top edge, the tile's bottom
    -- rows below (band tiling)
    local function bandFace(dname, x0, x1, z0, z1, low, top, r)
      if top - low <= RH + EPS then
        -- up to one wall height: the tile stretched (no repeated band)
        faceQuad(opaque, dname, x0, x1, z0, z1, low, top, r)
        return
      end
      local mid = math.max(low, top - 1.0)
      faceQuad(opaque, dname, x0, x1, z0, z1, mid, top, subRectV(r, 1 - (top - mid), 1))
      if mid > low + EPS then
        faceQuad(opaque, dname, x0, x1, z0, z1, low, mid, subRectV(r, math.max(0, 1 - (mid - low)), 1))
      end
    end
    -- the stacked south face of a column (cell c = its bottom row)
    local function southFace(c, x0, x1, z0, z1, low, top, u0, u1)
      -- Exact native Cerulean moss surfaces: the original projected bottom
      -- rows describe a face, not horizontal bands to stretch across its height.
      -- Keep gray rocks, ladders and exits on their separate rendering paths.
      if grid.caveFootWater and ({[648]=true,[649]=true,[650]=true,[656]=true,[658]=true,[664]=true,[665]=true,[666]=true,[667]=true,[668]=true})[c.mid] then
        faceQuad(opaque,"down",x0,x1,z0,z1,low,top,subRect(underRect(665),u0,0,u1,1))
        return
      end
      local r = underRect(c.caveCleanMid or c.mid)
      if not r then return end
      r = subRect(r, u0, 0, u1, 1)
      local x = c.x
      local above = (c.runB - 1 >= c.runA) and grid[c.runB - 1][x] or nil
      local exb = fbOf(above)
      local ra = exb > 0 and underRect(above.caveCleanMid or above.mid) or nil
      if ra then ra = subRect(ra, u0, 0, u1, 1) end
      if not ra then
        -- the face row's tile alone, stretched over the face
        faceQuad(opaque, "down", x0, x1, z0, z1, math.max(low, top - RH), top, r)
      else
        -- the tile above's face rows on top, the face row's tile below,
        -- both fitted into CAVE_WALL_H
        IN.caveStats.faceBottoms = IN.caveStats.faceBottoms + 1
        local split = math.max(low, top - RH * exb / (1 + exb))
        faceQuad(opaque, "down", x0, x1, z0, z1, split, top, subRectV(ra, 1 - exb, 1))
        faceQuad(opaque, "down", x0, x1, z0, z1, math.max(low, top - RH), split, r)
      end
      if top - RH > low + EPS then
        local rest = top - RH - low
        faceQuad(opaque, "down", x0, x1, z0, z1, low, top - RH, subRectV(r, math.max(0, 1 - rest), 1))
      end
    end
    local opposite = { nw = "se", ne = "sw", sw = "ne", se = "nw" }
    -- shapes first (a dropped quarter needs its neighbour's quarters)
    local chamfers = {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        local r = isRock(c) and underRect(c.caveCleanMid or c.mid) or nil
        if r then
          local comp = compOf(c)
          -- which art goes on top
          local topR, sh = r, shapes and shapes[c.mid] or nil
          local hasFace = c.runFace
          local ownTop = true
          local keep = 1 -- the share of an own tile left for the top
          if hasFace and y == c.runB then
            -- the face row: the art of the row behind (its part that is not
            -- face), or the component's plain top behind a rim row
            ownTop = false
            local above = (y - 1 >= c.runA) and grid[y - 1][x] or nil
            local ka = 1 - fbOf(above)
            local rim = above and not isRock(at(x, y - 2))
            local pm = plainOf[comp]
            if above and above.caveShore then
              -- The predecessor UNDER is water, not a land cap donor.
              -- Retain this wall tile's own native moss instead.
              topR=r;ownTop=true
            elseif above and ka >= 0.25 and not (rim and pm) then
              topR = subRectV(underRect(above.caveCleanMid or above.mid) or r, 0, ka)
            elseif pm then
              topR = underRect(pm) or r
            elseif above then
              topR = subRectV(underRect(above.caveCleanMid or above.mid) or r, 0, math.max(0.125, ka))
            else
              topR = subRectV(r, 0, 0.25)
            end
          elseif hasFace and y == c.runB - 1 then
            keep = 1 - fbOf(c)
            if keep < 0.125 then
              ownTop = false
              topR = underRect(plainOf[comp] or c.mid) or r
            elseif keep < 1 then
              topR = subRectV(r, 0, keep)
            end
          end
          -- shape of an own-art top (chamfer / floor quarters / crops)
          local ch, qm
          if ownTop and sh then
            if sh.ch then
              -- tentative: both floor-side neighbours present; validated
              -- below (open, or a chamfer whose floor meets this one)
              local c1, c2 = sh.ch:sub(1, 1), sh.ch:sub(2, 2)
              local n1 = at(x, y + (c1 == "n" and -1 or 1))
              local n2 = at(x + (c2 == "w" and -1 or 1), y)
              if n1 and n2 then ch = sh.ch end
            elseif sh.q then
              qm = 0
              local Q = { { 1, -1, -1 }, { 2, 1, -1 }, { 4, -1, 1 }, { 8, 1, 1 } }
              for _, q in ipairs(Q) do
                if sh.q % (q[1] * 2) >= q[1] then
                  local nv, nh = at(x, y + q[3]), at(x + q[2], y)
                  if (nv and not isRock(nv)) or (nh and not isRock(nh)) then qm = qm + q[1] end
                end
              end
              if qm == 0 or qm == 15 then qm = nil end
            end
            local l, t, rr, bb = (sh.l or 0) / 16, (sh.t or 0) / 16, (sh.r or 0) / 16, (sh.b or 0) / 16
            if l + t + rr + bb > 0 and not qm then
              if keep < 1 then t, bb = t / keep, 0 end
              topR = subRect(topR, l, math.min(t, 0.5), 1 - rr, 1 - bb)
            end
          end
          if grid.cavePlainMossCap and c.mid==665 and ((y==9 and x>=22 and x<=25) or (y==13 and (x==23 or x==25))) then
            topR=underRect(657) -- horizontal cap only;665 stays on vertical faces
          end
          c.topR, c.ownTop, c.chm, c.qm = topR, ownTop, ch, qm
          if ch then chamfers[#chamfers + 1] = c end
        end
      end
    end
    -- chamfers: each floor-side neighbour must be open, or a chamfer whose
    -- own floor side faces back (two rounded rocks touching: a notch)
    do
      local FS = { nw = { "up", "left" }, ne = { "up", "right" }, sw = { "down", "left" }, se = { "down", "right" } }
      local DIRN = {}
      for _, d in ipairs(DIRS) do DIRN[d.name] = d end
      local function hasSide(ch, side) local f = FS[ch]; return f[1] == side or f[2] == side end
      local changed = true
      while changed do
        changed = false
        for _, c in ipairs(chamfers) do
          if c.chm then
            for _, side in ipairs(FS[c.chm]) do
              local d = DIRN[side]
              local nb = at(c.x + d.dx, c.y + d.dy)
              if isRock(nb) and not (nb.chm and hasSide(nb.chm, OPP[side])) then
                c.chm, changed = nil, true
                break
              end
            end
          end
        end
      end
    end
    for y = 0, H - 1 do
      if y % 4 == 0 then Y() end
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.nativeLooseRock then
          grid.drawNativeLooseRock(c)
          rockCells = rockCells + 1
        elseif c and c.boulderC then
          -- M14: a loose rock: floor + a low tapered rock
          local x0, z0, x1, z1 = x + 0.0, y + 0.0, x + 1.0, y + 1.0
          local g = c.hgt
          local fr = underRect(c.caveRingProp and 641 or c.nearMid or c.mid)
          if fr then hQuad(opaque, x0, z0, x1, z1, g, fr) end
          local r = underRect(c.caveCleanMid or c.mid)
          local swr = c.boulderC.sw
          if c.caveCleanMid==642 then swr=(shapes[642] and shapes[642].sw) or {4,4,12,12} end
          if r then
