            local t = { { x0 + ti, z0 + ti }, { x1 - ti, z0 + ti }, { x1 - ti, z1 - ti }, { x0 + ti, z1 - ti } }
            local yt = g + h
            for _, e in ipairs({ { 4, 3 }, { 3, 2 }, { 2, 1 }, { 1, 4 } }) do
              local A, B, TA, TB = b[e[1]], b[e[2]], t[e[1]], t[e[2]]
              local nn = faceNormal3({ A[1], g, A[2] }, { B[1], g, B[2] }, { TB[1], yt, TB[2] })
              quadN(opaque, A[1], g, A[2], rr[1], rr[4], B[1], g, B[2], rr[3], rr[4],
                TB[1], yt, TB[2], rr[3], rr[2], TA[1], yt, TA[2], rr[1], rr[2], nn[1], nn[2], nn[3])
            end
