              local order = { "nw", "ne", "se", "sw" }
              local fl, rk = {}, {}
              for i, k in ipairs(order) do
                if k ~= opposite[ch] then fl[#fl + 1] = cs[k] end
                if k ~= ch then rk[#rk + 1] = cs[k] end
              end
              local function tri(list, pts, yv, rr, n)
                local q = {}
                for i = 1, #pts do
                  local p = pts[i]
                  q[i] = { { p[1], yv, p[2] }, { rr[1] + (rr[3] - rr[1]) * (p[1] - x0), rr[2] + (rr[4] - rr[2]) * (p[2] - z0) } }
                end
                fanN(list, q, n)
              end
              tri(opaque, fl, c.hgt, r, UP)
              tri(opaque, rk, top, r, UP)
              if ovTop then
                tri(cutoutOver, fl, c.hgt + C.OVER_LIFT, ovTop, UP)
                tri(cutoutOver, rk, top + C.FACADE_OVER_LIFT, ovTop, UP)
              end
              -- the diagonal, left -> right as seen from the floor corner
              local A, B
              if ch == "nw" then A, B = cs.ne, cs.sw
              elseif ch == "ne" then A, B = cs.se, cs.nw
              elseif ch == "se" then A, B = cs.sw, cs.ne
              else A, B = cs.nw, cs.se end
              local nn = faceNormal3({ A[1], c.hgt, A[2] }, { B[1], c.hgt, B[2] }, { B[1], top, B[2] })
              if fr then
                local mid = math.max(c.hgt, top - 1.0)
                local r1 = subRectV(fr, 1 - (top - mid), 1)
