      local uv={{r[1]+(r[3]-r[1])*u0/16,r[2]+(r[4]-r[2])*v0/16},{r[1]+(r[3]-r[1])*u1/16,r[2]+(r[4]-r[2])*v0/16},{r[1]+(r[3]-r[1])*u1/16,r[2]+(r[4]-r[2])*v1/16},{r[1]+(r[3]-r[1])*u0/16,r[2]+(r[4]-r[2])*v1/16}}
