  -- ---------------------------------------------------------------
  -- Pass 3a: buildings (M5 facade/doors/signs, M7 eaves, M8 side walls,
  -- M12 roof tiling, M13 north reach, M14 facade base).
  -- ---------------------------------------------------------------
  -- r11 (refs 14, v15-v17): a HIP roof over the rectangle x0..x1 / z0..z1
  -- at height wy -- planar tiles ~1 unit along the ridge axis, courses
  -- ~ROOF_COURSE_LEN up the slopes (the shingle rows run along the ridge),
  -- clipped at the hips; the hip ends reach endExt in from the short
  -- edges (the art's sloped-end strips: a long ridge), 45 degree hips
  -- without it. Returns the rise and the roof height at a plan point.
  -- Audited top-row UNDER art is terrain behind the native OVER roof.
  -- Substitute only its opaque backing, retaining the original OVER/UVs.
  -- Deliberately limited to these three verified footprints and donor tiles.
  grid.roofTerrainUnder = function(comp, c)
    if not comp or not c or not c.hasOver or c.y ~= comp.minY then return nil end
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.name=='pewter-museum-main'
        and c.y==0 and (c.mid==640 or c.mid==641 or c.mid==642 or c.mid==646) then
      local donor=at(13,1)
      if donor and donor.mid==649 and isCompCell(donor,comp) then
        local uv=underRect(comp.nativeBuildingProfile.museumUniformRoof and 657 or 649)
        return uv and subRect(uv,.5/16,.5/16,15.5/16,15.5/16)
      end
      return nil
    end
    local donorMid, source
    local ox, oy = input.mapId == "FR_SAFFRON_CITY_CONNECTION" and 10 or 0, input.mapId == "FR_SAFFRON_CITY_CONNECTION" and 7 or 0
    if (input.mapId == "FR_SAFFRON_CITY" or input.mapId == "FR_SAFFRON_CITY_CONNECTION") and input.pair == "general__rom_082d4b9c" then
      if comp.minX + ox == 37 and comp.maxX + ox == 42 and comp.minY + oy == 8 and comp.maxY + oy == 11 then
        donorMid, source = 825, { [816]=true, [817]=true, [799]=true, [818]=true }
      elseif comp.minX + ox == 43 and comp.maxX + ox == 49 and comp.minY + oy == 8 and comp.maxY + oy == 11 then
        donorMid, source = 322, { [768]=true, [769]=true, [770]=true, [771]=true }
      end
    elseif input.mapId == "FR_FUCHSIA_CITY" and input.pair == "general__rom_082d4b54"
        and comp.minX + ox == 6 and comp.maxX + ox == 12 and comp.minY + oy == 28 and comp.maxY + oy == 31 then
      donorMid, source = 322, { [645]=true, [646]=true, [647]=true }
    end
    if not donorMid or not source[c.mid] then return nil end
    local donor = at(comp.minX + 1, comp.minY + 1)
    if not donor or donor.mid ~= donorMid or not isCompCell(donor, comp) then return nil end
    local uv = underRect(donorMid)
    -- Keep bilinear contributors inside the verified opaque donor tile.
    return uv and subRect(uv, .5/16, .5/16, 15.5/16, 15.5/16)
  end

  -- Only the exact native blue end tiles: UNDER is grass, OVER owns roof.
  -- Reuse that native roof at the base plane; preserve its raised copy and
  -- transparent exterior silhouette rather than repainting background.
  grid.nativeBlueBacking=function(comp,c,layers,ov,normal)
    if comp and comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeThreeIsland
        and c and c.y==comp.nativeRoofStart and normal and normal[2]>.01
        and ov and layers[1] and layers[1][1]==opaque then
      -- Ridge OVER contains transparent native background between its ribs.
      -- Back it with a clean purple pixel from this exact guarded roof; leave
      -- original OVER and all ground UNDER ownership untouched.
      local r=overRect(647)
      layers[1]={cutoutOver,subRect(r,1.5/16,7.5/16,1.5/16,7.5/16),0}
      return
    end
    -- Native roof OVER is separate from grass UNDER in these guarded units.
    if comp and comp.nativeBuildingProfile and comp.nativeBuildingProfile.roofOverBacking
        and ov and layers[1] and layers[1][1]==opaque then
      local s=comp.nativeBuildingProfile.nativeSideSample
      if s and (comp.nativeBuildingProfile.nativeLabRoof or (normal and normal[2]<.01)) then
        local r=overRect(s.mid)
        layers[1]={cutoutOver,subRect(r,(s.x+.5)/16,(s.y+.5)/16,(s.x+.5)/16,(s.y+.5)/16),0}
      else layers[1]={cutoutOver,ov,0} end
      return
    end
    if comp and comp.nativeBlueRoof and (c.mid==44 or c.mid==47) and ov
        and layers[1] and layers[1][1]==opaque then layers[1]={cutoutOver,ov,0} end
  end
  grid.networkRoofFirst={55,51,49,46,44,42,40,39,38,37,36,35,35,34,34,34,34,34,34,35,35,36,37,38,39,40,42,44,46,49,51,55,55}
