  grid.networkRoofAlpha={[1008]=true,[1009]=true,[1010]=true,[1011]=true,[1012]=true,[1013]=true,[1014]=true,[1015]=true,[1016]=true,[1111]=true,[1112]=true,[1113]=true,[1114]=true,[1115]=true,[1116]=true,[1117]=true,[1118]=true,[1119]=true,[1120]=true,[1121]=true,[1122]=true,[1123]=true,[1124]=true,[1125]=true,[1226]=true,[1227]=true,[1228]=true,[1229]=true,[1230]=true,[1231]=true,[1232]=true,[1233]=true,[1234]=true,[1235]=true,[1340]=true,[1341]=true,[1342]=true,[1343]=true,[1344]=true,[1345]=true,[1346]=true,[1453]=true,[1454]=true,[1455]=true,[1456]=true,[1457]=true,[1566]=true,[1567]=true,[1568]=true,[1679]=true}
