  grid.networkRoofBuild=function(comp,wy)
    local R=.35
    local function clip(poly,axis,edge,sign)
      local out={}
      for i,a in ipairs(poly)do local b=poly[i%#poly+1];local da=(a[axis]-edge)*sign;local db=(b[axis]-edge)*sign
        if da>=-1e-9 then out[#out+1]=a end
