{60,61,22,23,663,109,true,'dormerFront',56,13},
{83,84,22,23,663,100,true,'dormerFront',88,13},
{84,92,22,23,663,101,true,'dormerFront',88,12},
{92,93,22,23,663,109,true,'dormerFront',88,13},
{16,32,23,24,663,113,true,'roof',0,0},
{48,64,23,24,663,113,true,'roof',0,0},
{80,96,23,24,663,113,true,'roof',0,0},
{0,1,24,30,664,129,true,'fascia',0,0},
{1,2,24,25,664,130,true,'fascia',0,0},
{2,110,24,25,664,131,true,'fascia',0,0},
{110,111,24,25,666,143,true,'fascia',0,0},
{111,112,24,30,666,144,true,'fascia',0,0},
{1,111,25,26,664,146,true,'fascia',0,0},
{1,111,26,27,664,162,true,'fascia',0,0},
{1,111,27,28,664,178,true,'fascia',0,0},
{1,111,28,29,664,194,true,'fascia',0,0},
{1,111,29,30,664,210,true,'fascia',0,0},
{0,1,30,31,664,225,true,'fascia',0,0},
{1,111,30,31,664,226,true,'fascia',0,0},
{111,112,30,31,666,240,true,'fascia',0,0},
{0,1,31,32,664,241,false,'fascia',0,0},
{1,2,31,32,664,242,true,'fascia',0,0},
{2,3,31,32,664,243,true,'fascia',0,0},
{3,109,31,32,664,244,true,'fascia',0,0},
{109,110,31,32,666,254,true,'fascia',0,0},
{110,112,31,32,666,255,true,'fascia',0,0},
}
    local startO,startV=#opaque,#cutoutOver
    local edges={}
    local function capY(x,z,center)
      local zBack,zFront=Z(2),Z(23)
      local cut=12+math.max(0,center-4-x,x-center-4)
      return H(zBack)+(H(zFront)+(23-cut)/16-H(zBack))*(z-zBack)/(zFront-zBack)
    end
    local function edge(a,b,center,n)
      local axis=math.abs(a[1]-b[1])<1e-8 and 1 or 3
      local other=axis==1 and 3 or 1
      local key=axis..':'..string.format('%.10f',a[axis])
      local g=edges[key];if not g then g={axis=axis,other=other,fixed=a[axis],segs={}};edges[key]=g end
      g.segs[#g.segs+1]={math.min(a[other],b[other]),math.max(a[other],b[other]),center,n}
    end
    for _,q in ipairs(commands)do
      local xa,xb,ya,yb,m,i,over,role,center,cut=unpack(q)
      local list,t=over and cutoutOver or opaque,uv(m,i,over)
      if role=='fascia'then
        for _,sd in ipairs{{ez1,N_S},{ez0,N_N}}do
          face(list,{{X(xa),eave-(ya-24)/16,sd[1]},{X(xb),eave-(ya-24)/16,sd[1]},{X(xb),eave-(yb-24)/16,sd[1]},{X(xa),eave-(yb-24)/16,sd[1]}},t,sd[2])
        end
      else
        -- All old decorative pixels leave both roof slopes. The clean backing
        -- is sampled at the same source row, never from terrain UNDER.
        local baseList,baseUv=list,t
        if role~='roof'then baseList,baseUv=source(8,ya)end
        face(baseList,{point(xa,ya,false),point(xb,ya,false),point(xb,yb,false),point(xa,yb,false)},baseUv)
        -- The source shows only front dormers, including their cast shadows.
        -- Hidden rear uses clean roof by source row; keep the two edge columns.
        local cuts={xa,xb};for _,x in ipairs{2,110}do if x>xa and x<xb then cuts[#cuts+1]=x end end;table.sort(cuts)
        for k=1,#cuts-1 do local l,r=cuts[k],cuts[k+1];local ml,mt=baseList,baseUv
          if l>=2 and r<=110 then ml,mt=source(8,ya)end
          face(ml,{point(l,ya,true),point(r,ya,true),point(r,yb,true),point(l,yb,true)},mt)
        end
        if role=='dormerCap'then
          local zBack,zFront=Z(2),Z(23)
          local bottom=H(zFront)
          local high=bottom+(23-cut)/16
          local function cap(x,y)
            local v=(y-2)/(cut-2)
            local z=zBack+(zFront-zBack)*v
            return {X(x),capY(x,z,center),z}
          end
          local ps={cap(xa,ya),cap(xb,ya),cap(xb,yb),cap(xa,yb)}
          face(list,ps,t)
          for k=1,4 do edge(ps[k],ps[k%4+1],center,k==1 and N_N or k==2 and N_E or k==3 and N_S or N_W)end
        elseif role=='dormerFront'then
          local z=Z(23);local low=H(z)
          local function frontY(x,y)return y==cut and capY(x,z,center)or low+(23-y)/16 end
          face(list,{{X(xa),frontY(xa,ya),z},{X(xb),frontY(xb,ya),z},{X(xb),frontY(xb,yb),z},{X(xa),frontY(xa,yb),z}},t,N_S)
        end
      end
    end
    -- Split collinear edges at every endpoint before cancellation. Adjacent
    -- columns use different source-row stations but ONE continuous cap height.
    local perimeter,internal=0,0
    for _,g in pairs(edges)do
      local cuts={};for _,e in ipairs(g.segs)do cuts[#cuts+1]=e[1];cuts[#cuts+1]=e[2]end
      table.sort(cuts)
      for k=1,#cuts-1 do local lo,hi=cuts[k],cuts[k+1]
        if hi-lo>1e-8 then
          local mid=(lo+hi)/2;local count,owner=0,nil
          for _,e in ipairs(g.segs)do if mid>e[1]-1e-8 and mid<e[2]+1e-8 then count=count+1;owner=e end end
          assert(count<=2,'Mansion cap overlapping topology')
          if count==2 then internal=internal+1
          elseif count==1 then
            local a,b={0,0,0},{0,0,0};a[g.axis],b[g.axis]=g.fixed,g.fixed;a[g.other],b[g.other]=lo,hi
            a[2]=capY((a[1]-ex0)*112/(ex1-ex0),a[3],owner[3]);b[2]=capY((b[1]-ex0)*112/(ex1-ex0),b[3],owner[3])
            -- Upright native front closes this edge; no overlapping gray pane.
            if not(g.axis==3 and math.abs(g.fixed-Z(23))<1e-8)then
              face(grayList,{a,b,{b[1],H(b[3]),b[3]},{a[1],H(a[3]),a[3]}},gray,owner[4]);perimeter=perimeter+1
            end
          end
        end
      end
    end
    -- Clean native brown material backs the front outline where the source
    -- silhouette narrows below the cap. It is behind the preserved front art.
    for _,center in ipairs{24,56,88}do for x=center-8,center+7 do
      local cut=12+math.max(0,center-4-x,x-(center+3))
      local z=Z(23)-1/4096;local low=H(Z(23));local l,t=source(8,18)
      face(l,{{X(x),capY(x,Z(23),center),z},{X(x+1),capY(x+1,Z(23),center),z},{X(x+1),low,z},{X(x),low,z}},t,N_S)
    end end
    -- Native fascia side edges, then the clean brown gable end above them.
    for _,edge in ipairs{{ex0,0,N_W},{ex1,111,N_E}}do
      for row=24,31 do local l,t=source(edge[2],row)
        face(l,{{edge[1],eave-(row-24)/16,ez0},{edge[1],eave-(row-24)/16,ez1},{edge[1],eave-(row-23)/16,ez1},{edge[1],eave-(row-23)/16,ez0}},t,edge[3])
      end
      local l,t=source(8,0)
      face(l,{{edge[1],eave,ez0},{edge[1],eave+rise,mid},{edge[1],eave,ez1}},t,edge[3])
    end
    comp.mansionRoof={dormers=3,eaveY=eave,ridgeY=eave+rise,sourceFront=396,sourceCap=456,perimeterReturns=perimeter,internalEdgesCancelled=internal,triangles=(#opaque-startO+#cutoutOver-startV)/3}
    comp.roofAt=function(_,z)return H(z)end
  end

  local function roofChimneys(comp, flatTop, roofAt, zlo, zhi, dry)
    local covered, boxes = {}, 0
    if comp.greenUnit or (comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeMansionRoof) then return covered,0 end
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.name=='silph-native-core' then return covered,0 end
    if type(atlas.texels) ~= "function" then return covered, 0 end
    local r0 = comp.nativeRoofStart or (comp.overhang and comp.minY - 1 or comp.roofTop)
    local r1 = comp.roofBottom
    if r1 < r0 then return covered, 0 end
    local function roofCell(x, y)
      if x < comp.minX or x > comp.maxX or y < r0 or y > r1 then return nil end
      local c = at(x, y)
      if c and (isCompCell(c, comp) or c.overhangOf == comp) then return c end
      return nil
    end
    local terrainBacking = {}
    local function vis(c, i)
      local ymin=comp.nativeBuildingProfile and comp.nativeBuildingProfile.roofSourceYMin
      if ymin and c.y+math.floor((i-1)/16)/16<ymin then return -1 end
      local o = c.hasOver and atlas.texels(c.mid, "over")
      if o and o[i] and o[i] >= 0 then return o[i] end
      -- Native opaque roof OVER remains eligible. Only the audited terrain
      -- UNDER backing is excluded from fixture detection; never all foliage.
      if terrainBacking[c] == nil then terrainBacking[c] = grid.roofTerrainUnder(comp, c) ~= nil end
      if terrainBacking[c] then return -1 end
      local u = atlas.texels(c.mid, "under")
      return u and u[i] or -1
    end
    -- (a column counts for a colour with >= 16 texels of it -- not the
    -- sliver of a chimney's shadow in the next column; the inner columns
    -- only -- the edge trim may share the chimney's colours -- unless there
    -- are fewer than 3)
    -- (and the rows above the bottom roof row: that row carries the
    -- facade's top -- window frames share a vent's greys: Celadon)
    local colsOf = {}
    local cx0, cx1 = comp.minX + 1, comp.maxX - 1
    if cx1 - cx0 < 2 then cx0, cx1 = comp.minX, comp.maxX end
    local rs1 = r1 > r0 and r1 - 1 or r1
    for xx = cx0, cx1 do
      local cntC = {}
      for yy = r0, rs1 do
        local c = roofCell(xx, yy)
        if c then
          for i = 1, 256 do
            local v = vis(c, i)
            if v >= 0 then
              cntC[v] = (cntC[v] or 0) + 1
              if cntC[v] == 16 then colsOf[v] = (colsOf[v] or 0) + 1 end
            end
          end
        end
      end
    end
    local need = math.max(2, math.ceil((cx1 - cx0 + 1) * 0.5))
    local function foreign(X, Y)
      local x, y = math.floor(X / 16), math.floor(Y / 16)
      local c = roofCell(x, y)
      if not c then return false end
      local v = vis(c, (Y - y * 16) * 16 + (X - x * 16) + 1)
      return v >= 0 and (colsOf[v] or 0) < need
    end
    -- one face: art rect a (map units; a zero-wide rect stretches one
    -- texel column) onto the corners TL TR BR BL, split per cell
    local function artFace(a, TL, TR, BR, BL, n)
      local function Pt(tx,ty)
        local p={};for k=1,3 do p[k]=(TL[k]*(1-tx)+TR[k]*tx)*(1-ty)+(BL[k]*(1-tx)+BR[k]*tx)*ty end;return p
      end
      local function cuts(p, q)
        local t = { p }
        for k = math.floor(p) + 1, math.ceil(q) - 1 do t[#t + 1] = k end
        t[#t + 1] = q
        return t
      end
      local xs, ys = cuts(a[1], a[3]), cuts(a[2], a[4])
    local w, h = a[3] - a[1], a[4] - a[2]
      for i = 1, #xs - 1 do
        for j = 1, #ys - 1 do
          local px0, px1, py0, py1 = xs[i], xs[i + 1], ys[j], ys[j + 1]
          local tx0 = w > 0 and (px0 - a[1]) / w or 0
          local tx1 = w > 0 and (px1 - a[1]) / w or 1
          local ty0, ty1 = (py0 - a[2]) / h, (py1 - a[2]) / h
          local cx, cy = math.floor((px0 + px1) / 2), math.floor((py0 + py1) / 2)
          local c = roofCell(cx, cy)
          if c and py1 > py0 then
            local ov = c.hasOver and overRect(c.mid) or nil
            local solid = ov and (overCoverage(c.mid) or 0) >= C.ROOF_SOLID_MIN
            local function put(list, r, lift)
              local uv = subRect(r, px0 - cx, py0 - cy, px1 - cx, py1 - cy)
              local d = { n[1] * lift, n[2] * lift, n[3] * lift }
              local p1, p2, p3, p4 = Pt(tx0, ty0), Pt(tx1, ty0), Pt(tx1, ty1), Pt(tx0, ty1)
              for _, p in ipairs({ p1, p2, p3, p4 }) do p[1], p[2], p[3] = p[1] + d[1], p[2] + d[2], p[3] + d[3] end
              quad(list, p1, p2, p3, p4, uv, n)
            end
            if solid then
              put(cutoutOver, ov, 0)
            else
              local ur = underRect(c.mid)
              if ur then put(opaque, ur, 0) end
              if ov then put(cutoutOver, ov, C.FACADE_OVER_LIFT) end
            end
          end
        end
      end
    end
    -- flood every foreign blob seeded in an inner column, then merge the
    -- blobs whose boxes come within 2 texels (a chimney's outline row --
    -- a roof colour -- cuts it in two: Oak's lab)
    local done, blobs = {}, {}
    local bottomRow = r1 * 16 + 15
    for yy = r0, rs1 do
      for xx = comp.minX + 1, comp.maxX - 1 do
        for ty = 0, 15 do
          for tx = 0, 15 do
            local X0, Y0 = xx * 16 + tx, yy * 16 + ty
            local k0 = Y0 * 65536 + X0
            if not done[k0] and foreign(X0, Y0) then
              local stack, bl = { { X0, Y0 } }, { n = 0, cells = {}, x0 = X0, y0 = Y0, x1 = X0, y1 = Y0 }
              done[k0] = true
              while #stack > 0 do
                local p = stack[#stack]
                stack[#stack] = nil
                bl.n = bl.n + 1
                bl.cells[math.floor(p[2] / 16) * 65536 + math.floor(p[1] / 16)] = true
                if p[1] < bl.x0 then bl.x0 = p[1] end
                if p[1] > bl.x1 then bl.x1 = p[1] end
                if p[2] < bl.y0 then bl.y0 = p[2] end
                if p[2] > bl.y1 then bl.y1 = p[2] end
                for dy = -1, 1 do
                  for dx = -1, 1 do
                    local X, Y = p[1] + dx, p[2] + dy
                    local k = Y * 65536 + X
                    if not done[k] and foreign(X, Y) then
                      done[k] = true
                      stack[#stack + 1] = { X, Y }
                    end
                  end
                end
              end
              if bl.n >= 4 then blobs[#blobs + 1] = bl end
            end
          end
        end
      end
    end
    local merged = true
    while merged do
      merged = false
      for i = 1, #blobs do
        for j = i + 1, #blobs do
          local A, B = blobs[i], blobs[j]
          if A and B and A.x0 <= B.x1 + 2 and B.x0 <= A.x1 + 2 and A.y0 <= B.y1 + 2 and B.y0 <= A.y1 + 2 then
            A.x0, A.y0 = math.min(A.x0, B.x0), math.min(A.y0, B.y0)
            A.x1, A.y1 = math.max(A.x1, B.x1), math.max(A.y1, B.y1)
            A.n = A.n + B.n
            for key in pairs(B.cells) do A.cells[key] = true end
            table.remove(blobs, j)
            merged = true
            break
          end
        end
        if merged then break end
      end
    end
    table.sort(blobs, function(p, q) return p.n > q.n end)
    for _, bl in ipairs(blobs) do
      local n, tx0, ty0, tx1, ty1 = bl.n, bl.x0, bl.y0, bl.x1, bl.y1
              -- (not a tree crown lying in the overhang row -- Five Island;
              -- not a tall thin strip -- two attached houses' hip ends)
              if boxes < 2 and n >= 60 and tx1 - tx0 >= 5 and ty1 - ty0 >= 5 and tx1 - tx0 < 32 and ty1 < bottomRow
                  and ty1 >= comp.roofTop * 16 and (ty1 - ty0) <= 2.5 * (tx1 - tx0 + 1) then
                boxes = boxes + 1
                for key in pairs(bl.cells) do
                  local c = at(key % 65536, math.floor(key / 65536))
                  if c then covered[c] = true end
                end
                if not dry then
                local ax0, ax1, ay0, ay1 = tx0 / 16, (tx1 + 1) / 16, ty0 / 16, (ty1 + 1) / 16
                local z0, z1, yb, yt, am
                if flatTop then
                  local H = C.CHIMNEY_H
                  if ay1 - ay0 < H * 1.3 then H = (ay1 - ay0) * 0.55 end
                  local dTop = (ay1 - ay0) - H
                  z0, z1, yb, yt = ay1 - dTop, ay1, flatTop, flatTop + H
                  am = ay0 + dTop
                else
                  local d = math.min(ax1 - ax0, C.CHIMNEY_D_MAX)
                  local zc = math.max(zlo + d, math.min(zhi - d, ay1 - d * 0.5))
                  z0, z1 = zc - d * 0.5, zc + d * 0.5
                  -- (the roof under the footprint, 3 x 9 samples: a ridge
                  -- line inside it is found)
                  local lo, hi = math.huge, -math.huge
                  for i = 0, 2 do
                    for j = 0, 8 do
                      local hy = roofAt(ax0 + (ax1 - ax0) * i / 2, z0 + (z1 - z0) * j / 8)
                      if hy < lo then lo = hy end
                      if hy > hi then hi = hy end
                    end
                  end
                  yb, yt = lo - 0.02, hi + C.CHIMNEY_ABOVE
                  -- (the front shows the art's lower rows over its height)
                  am = math.max(ay0 + (ay1 - ay0) * 0.3, ay1 - (yt - yb))
                  if comp.viridianGreenR2 then
                    -- The native cap/body boundary is row 23, its front foot
                    -- row 39. Solve source projection V=Z-Y on the actual
                    -- front slope, without the generic behind-ridge offset.
                    local target=comp.viridianGreenR2+39/16
                    local low,high=zlo,zhi
                    for _=1,36 do
                      local mid=(low+high)*.5
                      local projection=mid-(roofAt((ax0+ax1)*.5,mid)-comp.groundY)
                      if projection<target then low=mid else high=mid end
                    end
                    z1=(low+high)*.5;z0=z1-14/16
                    yb=roofAt((ax0+ax1)*.5,z1)-.005
                    yt=comp.groundY+z1-(comp.viridianGreenR2+23/16)
                    am=comp.viridianGreenR2+23/16
                  end
                end
                artFace({ ax0, ay0, ax1, am }, { ax0, yt, z0 }, { ax1, yt, z0 }, { ax1, yt, z1 }, { ax0, yt, z1 }, UP)
                artFace({ ax0, am, ax1, ay1 }, { ax0, yt, z1 }, { ax1, yt, z1 }, { ax1, yb, z1 }, { ax0, yb, z1 }, N_S)
                artFace({ ax0, am, ax1, ay1 }, { ax1, yt, z0 }, { ax0, yt, z0 }, { ax0, yb, z0 }, { ax1, yb, z0 }, N_N)
                comp.chimneyBoxes = comp.chimneyBoxes or {}
                comp.chimneyBoxes[#comp.chimneyBoxes + 1] = { x0 = ax0, x1 = ax1, z0 = z0, z1 = z1, y0 = yb, y1 = yt,
                  artY0 = ay0, artY1 = ay1, texels = n }
                local cw, ce = ax0 + 0.5 / 16, ax1 - 0.5 / 16
                artFace({ cw, am, cw, ay1 }, { ax0, yt, z0 }, { ax0, yt, z1 }, { ax0, yb, z1 }, { ax0, yb, z0 }, N_W)
                artFace({ ce, am, ce, ay1 }, { ax1, yt, z1 }, { ax1, yt, z0 }, { ax1, yb, z0 }, { ax1, yb, z1 }, N_E)
                end
              end
    end
    return covered, boxes
  end

  -- r12 (USER: "Can't we just use the original roof?"): ONE roof face with
  -- the building's own ROOF ART, 1:1. a = { X0, Y0, X1, Y1 } is an art
  -- rectangle in map units (cells; X0 == X1 / Y0 == Y1 = one texel column /
  -- row stretched) laid onto the corners TL TR BR BL (TL = art (X0, Y0));
  -- split at the art's cell boundaries, each piece drawn in its own cell's
  -- layers (under opaque, over cutout lifted ROOF_OVER_LIFT along n). A
  -- `covered` cell (under a chimney / emblem box) draws the mirrored
  -- opposite edge cell, the nearest free inner cell of its row, or the
  -- roof's pattern cell instead -- never the flat picture of the box.
  -- nrms = per-corner normals (smooth), else n. Returns the triangle count.
  -- (25d: clip = optional plan half-planes { nx, nz, d } keeping nx * x + nz * z >= d --
  -- the hip's front slope / ends around a folded corner; each triangle clipped exactly)
  -- Dept side parapets: the outer native column is background grass.
  -- Use the building's own inner trim column, preserving its shaded end.
  -- Exact art/footprint fallback; roof OVER and front faces stay unchanged.
  grid.deptParapetTrim = function(comp, side, covered)
    if not comp.deptBays or input.mapId ~= "FR_CELADON_CITY"
        or input.pair ~= "general__rom_082d4b3c" or comp.minY ~= 6 or comp.maxY ~= 14
        or comp.roofBottom ~= 8 or type(atlas.texels) ~= "function"
        or type(atlas.w) ~= "number" or type(atlas.h) ~= "number" or atlas.w <= 0 or atlas.h <= 0 then return nil end
    local x, col, mids
    if side == "left" and comp.minX == 9 and comp.maxX == 12 then x,col,mids=9,2,{641,649,649,657}
    elseif side == "right" and comp.minX == 13 and comp.maxX == 17 then x,col,mids=17,13,{643,651,651,659}
    else return nil end
    local expected = {
      [641]={-1,-1,-1,-1,5395051,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239},
      [649]={15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239},
      [657]={15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,15722239,14599679,14599679,14599679,14599679},
      [643]={-1,-1,-1,-1,5395051,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679},
      [651]={14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679},
      [659]={14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,14599679,11900126,8678317,8678317,8678317},
    }
    local hashes={[641]={1832243108,920777028},[649]={1832243108,1707336366},[657]={1832243108,1536660607},[643]={556348727,1833272871},[651]={556348727,1849536589},[659]={556348727,958189826}}
    local function hash(t)
      if not t then return nil end
      local h=0
