      for py=sy0,sy1-1 do
        local px=sx0
        while px<sx1 do
          local list,r,tx,ty,color,constant=source(px,py,deck)
          local stop=px+1
          -- Runs join only identical source layer/tile and adjacent texels.
          while stop<sx1 do
            local ll,rr,xx,yy,_,cc=source(stop,py,deck)
            if ll~=list or rr[1]~=r[1]or rr[2]~=r[2]or yy~=ty or cc~=constant
                or xx~=(constant and tx or tx+stop-px) then break end
            stop=stop+1
          end
          local ulo=(math.floor(r[1]*atlas.w)+tx+.5)/atlas.w
          local uhi=constant and ulo or (math.floor(r[1]*atlas.w)+tx+stop-px-.5)/atlas.w
          local v=(math.floor(r[2]*atlas.h)+ty+.5)/atlas.h
          local cuts={px,stop}
          if not constant then cuts={px,px+.5};if stop-px>1 then cuts[#cuts+1]=stop-.5 end;cuts[#cuts+1]=stop end
          for k=1,#cuts-1 do
            local xa,xb=cuts[k],cuts[k+1]
