      local function q(c,n,p1,p2,p3,p4)fanN(c[1],{{p1,c[2]},{p2,c[2]},{p3,c[2]},{p4,c[2]}},n)end
      q(pale,UP,{x0,y1,z0},{x1,y1,z0},{x1,y1,z1},{x0,y1,z1})
      q(dark,{0,-1,0},{x0,y0,z1},{x1,y0,z1},{x1,y0,z0},{x0,y0,z0})
