  -- Exact native Game Corner upper assembly; lower brick and doors retain
  -- their original geometry. This is independent of generic chamfer rules.
  grid.gameCorniceGuard=function(comp)
    if C.FOLD_25D==false or input.mapId~="FR_CELADON_CITY" or input.pair~="general__rom_082d4b3c"
        or type(atlas.texels)~="function" or atlas.w~=256 or atlas.h~=480
        or not(comp.minX==31 and comp.maxX==37 and comp.minY==17 and comp.maxY==21 or comp.minX==38 and comp.maxX==40 and comp.minY==17 and comp.maxY==20)
        or comp.groundY~=.75 or comp.wallTopY~=2.75 or not comp.flatRoof
        or comp.partialFacade or comp.deptBays or comp.ov1 or comp.chamfer
        or C.EAVE_OVERHANG~=.2 or C.ROOF_OVERHANG_PUSH~=.6 or C.FLAT_ROOF_PARAPET~=.25
        or C.ROOF_OVER_LIFT~=.02 or C.FACADE_OVER_LIFT~=.004 or C.WALL_ROW_UNIT~=1 then return false end
    -- Reject both halves if adjacency changes either component. A surviving
    -- native rectangle alone must not lower just one side of the shared roof.
    local partners={compOf(at(31,17)),compOf(at(38,17))}
    if not partners[1] or not partners[2] then return false end
    local bounds={{31,37,21,19},{38,40,20,18}}
    for i,owner in ipairs(partners)do local b=bounds[i]
      if not owner or owner.minX~=b[1] or owner.maxX~=b[2] or owner.minY~=17 or owner.maxY~=b[3]
          or owner.roofTop~=17 or owner.roofBottom~=b[4] or owner.groundY~=.75 or owner.wallTopY~=2.75
          or not owner.flatRoof or owner.partialFacade or owner.deptBays or owner.ov1 or owner.chamfer or owner.flatHouse then return false end
    end
    if #partners~=2 or comp~=partners[1] and comp~=partners[2] then return false end
    local expected={{688,689,689,689,689,689,690,688,689,690},{696,691,691,697,699,699,698,704,697,706},{704,691,692,705,700,699,706,712,711,714},{712,695,693,713,694,695,714,707,347,708},{707,703,701,347,702,703,708}}
    for y=17,21 do for x=31,(y==21 and 37 or 40)do
      local c=at(x,y);local raw=input.cellAt(x,y)
      local owner=compOf(at(x<38 and 31 or 38,17))
      if not c or c.mid~=expected[y-16][x-30] or not owner or not (isCompCell(c,owner) or c.doorOf==owner) or not raw or raw.elevation~=0 then return false end
      local u,o=underRect(c.mid),overRect(c.mid)
      local nativeOver=atlas.texels(c.mid,"over")~=nil
      if c.hasOver~=nativeOver then return false end
      if not u or c.hasOver and not o then return false end
    end end
    local function hash(t)
      if not t then return 0 end
