      for i=1,256 do local v=t[i];if type(v)~="number"then return -1 end;h=(h*31+(v>=0 and v+2 or 1))%2147483647 end
      return h
    end
    for mid,h in pairs({[347]={140855211,0},[688]={735885038,287503987},[689]={735885038,126622201},[690]={735885038,2076847310},[691]={556348727,782477853},[692]={1657699438,1023628488},[693]={274183292,661957133},[694]={274183292,1444624683},[695]={556348727,274183292},[696]={1832243108,1886765519},[697]={556348727,752727638},[698]={1418352247,1428402888},[699]={556348727,276160392},[700]={1657699438,866193057},[701]={1319300926,0},[702]={80076264,0},[703]={534602844,0},[704]={1847008231,902694922},[705]={873566166,501030334},[706]={540951295,1900651401},[707]={14622537,0},[708]={1953858280,0},[711]={800680042,274183292},[712]={1832243108,1369723489},[713]={556348727,507929426},[714]={1832243108,768451372}})do
      if hash(atlas.texels(mid,"under"))~=h[1] or hash(atlas.texels(mid,"over"))~=h[2]then return false end
    end
    return true
  end
  -- Four source-owned rows complete the Game Corner arch above the deck.
  -- The outline is also the material for its one-native-pixel back/edges.
  grid.gameArch=function(comp,starts)
    if comp.minX~=31 then return end -- paired native guard already passed
    local masks={{44,52,59},{45,49,62},{46,47,64},{47,45,66}}
    local function source(px,py)
      local c=at(31+math.floor(px/16),17+math.floor(py/16));local tx,ty=px%16,py%16
      local o=c.hasOver and atlas.texels(c.mid,'over');local over=o and o[ty*16+tx+1]and o[ty*16+tx+1]>=0
      local r=over and overRect(c.mid)or underRect(c.mid)
