        local out=ia and yes or no;out[#out+1]=a
        if ia~=ib then local q={};local f=da/(da-db);for k=1,8 do q[k]=a[k]+(b[k]-a[k])*f end;yes[#yes+1]=q;no[#no+1]=q end
      end
      return yes,no
    end
    local function append(l,p,uv)
      for i=2,#p-1 do local tri={p[1],p[i],p[i+1]};local cross=cross3(sub3(tri[2],tri[1]),sub3(tri[3],tri[1]))
        if dot3(cross,cross)>1e-18 then for _,v in ipairs(tri)do
          if uv then v={v[1],v[2],v[3],uv[1],uv[2],v[6],v[7],v[8]}end
          l[#l+1]=v
        end end
      end
    end
