      local keep={}
      for i=starts[li]+1,#list,3 do if i%6144<3 then deps.yieldSafe() end  local a,b,c=list[i],list[i+1],list[i+2]
        if list==cutoutOver and a[7]>.99 and math.min(a[2],b[2],c[2])>=2.749999 and math.max(a[2],b[2],c[2])<=2.770001 then
          local parts={{a,b,c}}
          local slotX=math.floor((a[4]+b[4]+c[4])*atlas.w/48)
          local slotY=math.floor((a[5]+b[5]+c[5])*atlas.h/48)
          for _,r in ipairs(rects)do if slotX==r[5] and slotY==r[6]then
            local nextParts={}
            for _,poly in ipairs(parts)do
              local inside=poly
              for _,edge in ipairs({{4,r[1],false},{4,r[3],true},{5,r[2],false},{5,r[4],true}})do
                if #inside<3 then break end
                local outside;inside,outside=split(inside,edge[1],edge[2],edge[3]);if #outside>=3 then nextParts[#nextParts+1]=outside end
              end
              if #inside>=3 then removed=removed+1 end
            end
            parts=nextParts
          end end
          for _,poly in ipairs(parts)do append(keep,poly)end
        else keep[#keep+1]=a;keep[#keep+1]=b;keep[#keep+1]=c end
      end
      for i=#list,starts[li]+1,-1 do list[i]=nil;if i%4096==0 then deps.yieldSafe() end end
      for ki,v in ipairs(keep)do list[#list+1]=v;if ki%4096==0 then deps.yieldSafe() end end
    end
    -- Every owned OVER pixel has verified native cream UNDER. Leave that
    -- layer exactly intact, then clear only the lip in front of the arch.
    local front,back=22.004,22.004-1/16
    local nx0,nx1=31+39/16,31+73/16
    for li,list in ipairs({opaque,cutoutUnder,cutoutOver,cutoutKeyed})do
      local keep={}
      for i=starts[li]+1,#list,3 do if i%6144<3 then deps.yieldSafe() end  local a,b,c=list[i],list[i+1],list[i+2]
        if a[7]>.99 and math.min(a[2],b[2],c[2])>=2.749999 and math.max(a[2],b[2],c[2])<=2.770001
            and math.max(a[1],b[1],c[1])>nx0 and math.min(a[1],b[1],c[1])<nx1
            and math.max(a[3],b[3],c[3])>back and math.min(a[3],b[3],c[3])<22.21 then
          local inside={a,b,c}
          for _,edge in ipairs({{1,nx0,false},{1,nx1,true},{3,back,false},{3,22.21,true}})do
            if #inside<3 then break end
            local outside;inside,outside=split(inside,edge[1],edge[2],edge[3]);append(keep,outside)
          end
        else keep[#keep+1]=a;keep[#keep+1]=b;keep[#keep+1]=c end
      end
      for i=#list,starts[li]+1,-1 do list[i]=nil;if i%4096==0 then deps.yieldSafe() end end
      for ki,v in ipairs(keep)do list[#list+1]=v;if ki%4096==0 then deps.yieldSafe() end end
    end
    local owned={}
    for _,m in ipairs(masks)do for x=m[2],m[3]do owned[m[1]*128+x]=true end end
    local function has(x,y)return owned[y*128+x]end
    local function quad(l,t,p1,p2,p3,p4,n)fanN(l,{{p1,t},{p2,t},{p3,t},{p4,t}},n)end
    for _,m in ipairs(masks)do for px=m[2],m[3]do
      local py=m[1];local xa,xb=31+px/16,31+(px+1)/16
      local ya,yb=2.75+(48-py)/16,2.75+(47-py)/16
      local l,t=source(px,py)
      quad(l,t,{xa,ya,front},{xb,ya,front},{xb,yb,front},{xa,yb,front},N_S)
      quad(gray,gt,{xa,ya,back},{xb,ya,back},{xb,yb,back},{xa,yb,back},N_N)
      if not has(px-1,py)then quad(gray,gt,{xa,ya,back},{xa,ya,front},{xa,yb,front},{xa,yb,back},N_W)end
      if not has(px+1,py)then quad(gray,gt,{xb,ya,back},{xb,ya,front},{xb,yb,front},{xb,yb,back},N_E)end
      if not has(px,py-1)then quad(gray,gt,{xa,ya,back},{xb,ya,back},{xb,ya,front},{xa,ya,front},UP)end
      -- The notch exposes the one-pixel underside; native gray closes it
      -- while the front edge joins the unchanged row48 arch atY2.75.
      if py==47 then quad(gray,gt,{xa,yb,back},{xb,yb,back},{xb,yb,front},{xa,yb,front},DOWN)end
    end end
    for _,px in ipairs({39,40,41,42,43,44,67,68,69,70,71,72})do
      local l,t=source(px,48);local xa,xb=31+px/16,31+(px+1)/16
      quad(l,t,{xa,2.75,back},{xb,2.75,back},{xb,2.75,front},{xa,2.75,front},UP)
    end
    comp.gameArch={notchX0=nx0,notchX1=nx1,nativePixels=62,firstRow=44,lastRow=47,topY=3,frontZ=front,backZ=back,removedPieces=removed}
  end



  -- The native rear fence belongs on the ground behind the building.
  -- Its top-down overlap with the roof is not a rooftop railing.
  -- Called only after the exact paired native-art guard has passed.
  grid.gameFenceRun=function(comp,starts)
    if grid.gameFenceUnified then return true end
    if comp.minX~=31 then return false end
    for y=17,23 do local c=at(30,y);if not c or not c.nativeBlueFence then return false end end
    for x=31,40 do local c=at(x,23);if not c or c.mid~=((x==33 or x==38)and 2 or 231)then return false end end
    local ft=atlas.texels(231,'under');local fh=0
    if not ft then return false end
    for i=1,256 do local v=ft[i];if type(v)~='number'then return false end;fh=(fh*31+(v>=0 and v+2 or 1))%2147483647 end
    if fh~=982508660 then return false end
    if not grid.gameFenceRanges then return false end
    local lists={opaque,cutoutUnder,cutoutOver,cutoutKeyed}
    -- Remove only ranges recorded while rendering these native fence cells.
    -- Signs, ground, and the adjacent blue house are not in these ranges.
    for li,list in ipairs(lists)do
      local keep={};local shifted=0
      for i=1,#list do
        if i%2048==0 then deps.yieldSafe() end
        local remove=false
        for _,range in ipairs(grid.gameFenceRanges)do if i>range[1][li]and i<=range[2][li]then remove=true;break end end
        if remove then if i<=starts[li]then shifted=shifted+1 end else keep[#keep+1]=list[i]end
      end
      for i=#list,1,-1 do list[i]=nil;if i%4096==0 then deps.yieldSafe() end end
      for ki,v in ipairs(keep)do list[#list+1]=v;if ki%4096==0 then deps.yieldSafe() end end
      starts[li]=starts[li]-shifted
    end
    local r=underRect(689);local tex=atlas.texels(689,'under')
    local function has(x,y)return y>=2 and y<=12 and tex[y*16+x%16+1]~=0x73cea5 end
    local function uv(x,y)return {(math.floor(r[1]*atlas.w)+x%16+.5)/atlas.w,(math.floor(r[2]*atlas.h)+y+.5)/atlas.h}end
    local function run(sx,sz,dx,dz,length)
      local count=math.floor(length*16+.5)
      local function p(t,y,d)return {sx+t*dx-d*dz,y,sz+t*dz+d*dx}end
      local function quad(t,a,b,c,d,n)
        fanN(opaque,{{a,t},{b,t},{c,t},{d,t}},{n[1]*dx-n[3]*dz,n[2],n[1]*dz+n[3]*dx})
      end
      for py=2,12 do for px=0,count-1 do if has(px,py)then
        local xa,xb=px/16,(px+1)/16;local ya,yb=comp.groundY+(13-py)/16,comp.groundY+(12-py)/16
        local t=uv(px,py);local back,front=-1/32,1/32
        quad(t,p(xa,ya,front),p(xb,ya,front),p(xb,yb,front),p(xa,yb,front),N_S)
        quad(t,p(xb,ya,back),p(xa,ya,back),p(xa,yb,back),p(xb,yb,back),N_N)
        if px==0 or not has(px-1,py)then quad(t,p(xa,ya,back),p(xa,ya,front),p(xa,yb,front),p(xa,yb,back),N_W)end
        if px==count-1 or not has(px+1,py)then quad(t,p(xb,ya,front),p(xb,ya,back),p(xb,yb,back),p(xb,yb,front),N_E)end
        if not has(px,py-1)then quad(t,p(xa,ya,back),p(xb,ya,back),p(xb,ya,front),p(xa,ya,front),UP)end
        if not has(px,py+1)then quad(t,p(xa,yb,front),p(xb,yb,front),p(xb,yb,back),p(xa,yb,back),DOWN)end
      end end end
    end
    run(30.5,16.5,1,0,10.5)
    run(30.5,16.5,0,1,7)
    run(30.5,23.5,1,0,10.5)
    for _,z in ipairs({16.5,23.5})do
      local t=uv(3,2);local x=30.5;local y0,y1=comp.groundY,comp.groundY+11/16
      local sx,sy=math.floor(r[1]*atlas.w),math.floor(r[2]*atlas.h)
      -- The rounded sprite's top-row outer pixels are grass. A square
      -- corner post needs a solid cap band, with the native face below.
      for row=2,12 do
        local rect=row==2 and {t[1],t[2],t[1],t[2]} or {(sx+1.5)/atlas.w,(sy+row+.5)/atlas.h,(sx+6.5)/atlas.w,(sy+row+.5)/atlas.h}
        local lo,hi=y0+(12-row)/16,y0+(13-row)/16
        for _,edge in ipairs({'up','down','left','right'})do faceQuad(opaque,edge,x-.1875,x+.1875,z-.1875,z+.1875,lo,hi,rect)end
      end
      hQuad(opaque,x-.1875,z-.1875,x+.1875,z+.1875,y1,{t[1],t[2],t[1],t[2]})
    end
    grid.gameFenceUnified=true
    return true
  end

  grid.gameRim=function(comp,starts)
    local ox,front=comp.minX,comp.maxY+1
    local first=ox==31 and 48 or 32
    -- The projected diagonal shade belongs to the old 2D corner. The
    -- actual miter is already geometry; keep its top plain native cream.
    local cream=overRect(689)
    local ct={(math.floor(cream[1]*atlas.w)+8.5)/atlas.w,(math.floor(cream[2]*atlas.h)+12.5)/atlas.h}
    local function split(poly,axis,value,less)
      local yes,no={},{}
      for i,a in ipairs(poly)do local b=poly[i%#poly+1];local da,db=a[axis]-value,b[axis]-value
        if not less then da,db=-da,-db end
        local ia,ib=da<=1e-10,db<=1e-10
        local out=ia and yes or no;out[#out+1]=a
        if ia~=ib then local v={};local f=da/(da-db);for k=1,8 do v[k]=a[k]+(b[k]-a[k])*f end;yes[#yes+1]=v;no[#no+1]=v end
      end
      return yes,no
    end
    local function append(list,poly,paint)
      for i=2,#poly-1 do local cr=cross3(sub3(poly[i],poly[1]),sub3(poly[i+1],poly[1]))
      if dot3(cr,cr)>1e-18 then for _,v in ipairs({poly[1],poly[i],poly[i+1]})do
        list[#list+1]=paint and {v[1],v[2],v[3],ct[1],ct[2],v[6],v[7],v[8]}or v
      end end end
    end
    local masks={{{1,comp.maxX+1-8/16,false},{3,front-1,false}}}
    if ox==31 then masks[#masks+1]={{1,ox+8/16,true},{3,front-1,false}}end
    local keep={}
    for i=starts[3]+1,#cutoutOver,3 do local a,b,c=cutoutOver[i],cutoutOver[i+1],cutoutOver[i+2]
      local parts={{a,b,c}}
      if a[7]>.99 and math.min(a[2],b[2],c[2])>=2.749999 and math.max(a[2],b[2],c[2])<=2.770001 then
        for _,mask in ipairs(masks)do local nextParts={}
          for _,poly in ipairs(parts)do local inside=poly
            for _,edge in ipairs(mask)do
              local outside;inside,outside=split(inside,edge[1],edge[2],edge[3]);if #outside>=3 then nextParts[#nextParts+1]=outside end
              if #inside<3 then break end
            end
            if #inside>=3 then append(keep,inside,true)end
          end
          parts=nextParts
        end
      end
      for _,poly in ipairs(parts)do append(keep,poly)end
    end
    for i=#cutoutOver,starts[3]+1,-1 do cutoutOver[i]=nil end
    for _,v in ipairs(keep)do cutoutOver[#cutoutOver+1]=v end
    local function sample(py)
      local c=at(ox+1,17+math.floor(py/16));local r=overRect(c.mid)
      local t=atlas.texels(c.mid,'over');local ix=(py%16)*16+9
      local list=cutoutOver
      if not t or t[ix]<0 then r=underRect(c.mid);list=opaque end
      return list,{(math.floor(r[1]*atlas.w)+8.5)/atlas.w,(math.floor(r[2]*atlas.h)+py%16+.5)/atlas.h}
    end
    local function strip(x0,z0,x1,z1,n)
      for row=0,8 do local list,t=sample(first+row)
        local ya,yb=row==0 and 2.77 or 2.75-row/16,2.75-(row+1)/16
        fanN(list,{{{x0,ya,z0},t},{{x1,ya,z1},t},{{x1,yb,z1},t},{{x0,yb,z0},t}},n)
      end
    end
    local xl,xr=ox==31 and 30.996 or ox,ox==38 and 41.004 or comp.maxX+1
    strip(xl,16.796,xr,16.796,N_N)
    if ox==31 then
      strip(30.996,16.796,30.996,front+.004-7/16,N_W)
      strip(38.004,21.004,38.004,front+.004-7/16,N_E)
    else strip(41.004,16.796,41.004,front+.004-7/16,N_E)end
    -- Narrow horizontal returns meet the lifted deck without a wall-colored slit.
    hQuad(cutoutOver,xl,16.796,xr,16.8,2.77,{ct[1],ct[2],ct[1],ct[2]})
    if ox==31 then hQuad(cutoutOver,30.996,16.8,31,front+.004-7/16,2.77,{ct[1],ct[2],ct[1],ct[2]})
    else hQuad(cutoutOver,41,16.8,41.004,front+.004-7/16,2.77,{ct[1],ct[2],ct[1],ct[2]})end
    local list,t=sample(first+8)
    fanN(list,{{{ox,2.1875,16.796},t},{{comp.maxX+1,2.1875,16.796},t},{{comp.maxX+1,2.1875,17},t},{{ox,2.1875,17},t}},DOWN)
  end


  grid.gameRearRails=function(comp,starts)
    local ox,cols=comp.minX,(comp.maxX-comp.minX+1)*16
    local railColors={[0x7b7b84]=true,[0xadbdce]=true,[0xf7f7ff]=true,
      [0xcedeef]=true,[0x94a5b5]=true,[0x5a5a73]=true,[0x52526b]=true}
    local function sample(px,py)
      local c=at(ox+math.floor(px/16),17);local ix=py*16+px%16+1
      local o=atlas.texels(c.mid,'over');local over=o and o[ix]>=0
      local r=over and overRect(c.mid)or underRect(c.mid)
      local t=over and o or atlas.texels(c.mid,'under')
      return t[ix],over and cutoutOver or opaque,
        {(math.floor(r[1]*atlas.w)+px%16+.5)/atlas.w,(math.floor(r[2]*atlas.h)+py+.5)/atlas.h}
    end
    -- Both layers of the rear source row contain fence pixels. Replace
    -- their upward-facing deck projection with the native cream material;
    -- no skylight or front/side wall source slots are in this row.
    local cream=overRect(689)
    local slots={}
    for x=comp.minX,comp.maxX do local c=at(x,17)
      for _,r in ipairs({underRect(c.mid),overRect(c.mid)})do
        slots[math.floor(r[1]*atlas.w/16)..':'..math.floor(r[2]*atlas.h/16)]=true
      end
    end
    local underCream=underRect(691)
    for li,list in ipairs({opaque,cutoutUnder,cutoutOver,cutoutKeyed})do
      local r=list==cutoutOver and cream or underCream
      local u,v=(math.floor(r[1]*atlas.w)+8.5)/atlas.w,(math.floor(r[2]*atlas.h)+12.5)/atlas.h
      for i=starts[li]+1,#list,3 do if i%6144<3 then deps.yieldSafe() end  local a,b,c=list[i],list[i+1],list[i+2]
        local slot=math.floor((a[4]+b[4]+c[4])*atlas.w/48)..':'..math.floor((a[5]+b[5]+c[5])*atlas.h/48)
        if a[7]>.99 and math.min(a[2],b[2],c[2])>=2.749999 and math.max(a[2],b[2],c[2])<=2.770001 and slots[slot]then
          for j=0,2 do local p=list[i+j];list[i+j]={p[1],p[2],p[3],u,v,p[6],p[7],p[8]}end
        end
      end
    end
    if grid.gameFenceRun(comp,starts)then return end
    local function has(x,y)
      if x<0 or x>=cols or y<2 or y>8 then return false end
      return railColors[sample(x,y)]==true
    end
    local function face(l,t,a,b,c,d,n)fanN(l,{{a,t},{b,t},{c,t},{d,t}},n)end
    local count=0
    for py=2,8 do for px=0,cols-1 do if has(px,py)then
      local _,l,t=sample(px,py);local xa,xb=ox+px/16,ox+(px+1)/16
      local ya,yb=comp.groundY+(9-py)/16,comp.groundY+(8-py)/16
      local back,front=16.4375,16.5
      face(l,t,{xa,ya,front},{xb,ya,front},{xb,yb,front},{xa,yb,front},N_S)
      face(l,t,{xb,ya,back},{xa,ya,back},{xa,yb,back},{xb,yb,back},N_N)
      if not has(px-1,py)then face(l,t,{xa,ya,back},{xa,ya,front},{xa,yb,front},{xa,yb,back},N_W)end
      if not has(px+1,py)then face(l,t,{xb,ya,front},{xb,ya,back},{xb,yb,back},{xb,yb,front},N_E)end
      if not has(px,py-1)then face(l,t,{xa,ya,back},{xb,ya,back},{xb,ya,front},{xa,ya,front},UP)end
      if not has(px,py+1)then face(l,t,{xa,yb,front},{xb,yb,front},{xb,yb,back},{xa,yb,back},DOWN)end
      count=count+1
    end end end
    comp.gameRearRails={nativePixels=count,baseY=comp.groundY,topY=comp.groundY+7/16,frontZ=16.5}
  end

  grid.gameCorniceFinish=function(comp,starts)
    local lists={opaque,cutoutUnder,cutoutOver,cutoutKeyed}
    local ox,oy,front=comp.minX,comp.minY,comp.maxY+1
    local cols=(comp.maxX-comp.minX+1)*16
    local first=ox==31 and 48 or 32
    local leftCorner=ox==31
    local function corners(p,plane,offset)
      if leftCorner then p=plane(p,-1,1,front+offset-ox-7/16)end
      return plane(p,1,1,comp.maxX+1+front+offset-7/16)
    end
    local function clip(p,axis,value,less)
      local out={}
      for i,a in ipairs(p)do local b=p[i%#p+1];local da=a[axis]-value;local db=b[axis]-value
        if not less then da,db=-da,-db end
        if da<=1e-9 then out[#out+1]=a end
        if (da<=1e-9)~=(db<=1e-9)then local q={};local f=da/(da-db);for k=1,8 do q[k]=a[k]+(b[k]-a[k])*f end;out[#out+1]=q end
      end
      return out
    end
    local function plane(p,nx,nz,value)
      local out={}
      for i,a in ipairs(p)do local b=p[i%#p+1];local da=nx*a[1]+nz*a[3]-value;local db=nx*b[1]+nz*b[3]-value
        if da<=1e-9 then out[#out+1]=a end
        if (da<=1e-9)~=(db<=1e-9)then local q={};local f=da/(da-db);for k=1,8 do q[k]=a[k]+(b[k]-a[k])*f end;out[#out+1]=q end
      end
      return out
    end
    local function append(l,p)
      for i=2,#p-1 do local a,b,c=p[1],p[i],p[i+1];local cr=cross3(sub3(b,a),sub3(c,a))
        if dot3(cr,cr)>1e-18 then l[#l+1]=a;l[#l+1]=b;l[#l+1]=c end
      end
    end
    -- Classify immutable triangle copies. Shared quad vertices must never
    -- have their already shifted heights used to classify a later triangle.
    for li,list in ipairs(lists)do
      local keep={}
      for i=starts[li]+1,#list,3 do if i%6144<3 then deps.yieldSafe() end 
        local p={};for j=0,2 do local q={};for k=1,8 do q[k]=list[i+j][k]end;p[#p+1]=q end
        local a,b,c=p[1],p[2],p[3]
        local lo,hi=math.min(a[2],b[2],c[2]),math.max(a[2],b[2],c[2])
        if lo>=2.75-1e-8 then
          -- The original constant-height parapet is the duplicated edge.
          -- Roof boxes and horizontal roof art move together, with UVs intact.
          if hi<=2.750001 or hi<=3.020001 and math.abs(a[7])<.01 then p={}
          else
            for _,v in ipairs(p)do v[2]=v[2]-.25 end
            if a[7]>.99 then p=corners(p,plane,.2)end
          end
        elseif hi>2.1875+1e-8 and a[8]>.99 then
          -- Upper facade source48..56 is emitted once below, pixel-owned.
          p=clip(p,2,2.1875,true)
        elseif hi>2.1875+1e-8 and math.abs(a[6])>.99 then
          local low=clip(p,2,2.1875,true);append(keep,low)
          p=clip(p,2,2.1875,false)
          p=corners(p,plane,.004)
        end
        append(keep,p)
      end
      for i=#list,starts[li]+1,-1 do list[i]=nil;if i%4096==0 then deps.yieldSafe() end end
      for ki,v in ipairs(keep)do list[#list+1]=v;if ki%4096==0 then deps.yieldSafe() end end
    end
    local function source(px,py)
      if px==0 or px==cols-1 then py=first-6 end
      py=math.floor(py)
      local c=at(ox+math.floor(px/16),oy+math.floor(py/16));local tx,ty=px%16,py%16
      local o=c.hasOver and atlas.texels(c.mid,'over');local over=o and o[ty*16+tx+1]and o[ty*16+tx+1]>=0
      local r=over and overRect(c.mid)or underRect(c.mid)
      local t=over and o or atlas.texels(c.mid,'under')
      return over and cutoutOver or opaque,{(math.floor(r[1]*atlas.w)+tx+.5)/atlas.w,(math.floor(r[2]*atlas.h)+ty+.5)/atlas.h},t[ty*16+tx+1]
    end
    local corniceColors={[0xf7efbd]=true,[0xded69c]=true,[0xc5b56b]=true,[0x52526b]=true,[0x7b7b84]=true}
    local function depth(px)return math.max(0,leftCorner and 7-px or 0,px-(cols-7))/16 end
    local function emit(l,t,p1,p2,p3,p4,n)
      if n=="bevel"then n=cross3(sub3(p2,p1),sub3(p3,p1));if n[2]<0 then n={-n[1],-n[2],-n[3]}end;local len=math.sqrt(dot3(n,n));n={n[1]/len,n[2]/len,n[3]/len}end
      fanN(l,{{p1,t},{p2,t},{p3,t},{p4,t}},n)
    end
    local entranceRows={}
    for py=first,first+8 do
      local first,last
      for px=32,(ox==31 and 79 or 31)do local _,_,v=source(px,py)
        if not corniceColors[v]then first=first or px;last=px end
      end
      if first then entranceRows[py]={first-1,last+1}end
    end
    -- The native entrance widens to outline39..72 by row54. Retract
    -- this lip to the same front plane so it cannot cover those shoulders.
    if ox==31 then entranceRows[first]={39,72}end
    for px=0,cols-1 do
      local xa,xb=ox+px/16,ox+(px+1)/16
      local da,db=depth(px),depth(px+1)
      local samplePx=math.max(1,math.min(cols-2,px))
      local shift=math.max(0,7-samplePx,samplePx-(cols-8))
      local za,zb=front+.004-da,front+.004-db
      for py=first,first+8 do
        local l,t,v=source((px<=7 or px>=cols-8)and 16 or px,py)
        local ya,yb=2.75-(py-first)/16,2.75-(py-first+1)/16
        local arch=entranceRows[py]
        local entrance=arch and px>=arch[1] and px<=arch[2]
        if entrance then
          -- The purple entrance stays on its original front wall, never
          -- borrowed as generic cornice material or stretched over the lip.
          emit(l,t,{xa,ya,front+.004},{xb,ya,front+.004},{xb,yb,front+.004},{xa,yb,front+.004},N_S)
        elseif py==first then
          -- Native cream lip is the bevel from the lowered deck to row49.
          emit(l,t,{xa,ya,za+.196},{xb,ya,zb+.196},{xb,yb,zb},{xa,yb,za},"bevel")
        else
          local nx,nz=-(zb-za),xb-xa;local len=math.sqrt(nx*nx+nz*nz)
          emit(l,t,{xa,ya,za},{xb,ya,zb},{xb,yb,zb},{xa,yb,za},{nx/len,0,nz/len})
        end
        -- The angled wall now meets this rim directly; no square-front return.
      end
    end
    -- End triangles close the native one-row bevel against the clipped
    -- side wall. Use each endpoint's own gray outline, not the grass below.
    local ends={{comp.maxX+1,cols-1,N_E}};if leftCorner then ends[#ends+1]={ox,0,N_W}end
    for _,edge in ipairs(ends)do
      local l,t=source(16,first)
      fanN(l,{{{edge[1]+edge[3][1]*.004,2.77,front+.004-7/16},t},{{edge[1]+edge[3][1]*.004,2.77,front+.2-7/16},t},{{edge[1]+edge[3][1]*.004,2.6875,front+.004-7/16},t}},edge[3])
    end
    -- The entrance's native gray outline owns the side of the top lip.
    -- All rows below the lip share the original OVER front plane, so no
    -- hidden .004 crossing connectors or invented trim are required.
    local arch=entranceRows[first]
    if arch then for _,e in ipairs({{arch[1],arch[1],N_E},{arch[2]+1,arch[2],N_W}})do
      local x=ox+e[1]/16;local l,t=source(e[2],first)
      fanN(l,{{{x,2.75,front+.004},t},{{x,2.75,front+.2},t},{{x,2.6875,front+.004},t}},e[3])
    end end
    -- Continue the roof's native seven-pixel corner down to the ground.
    -- The source brick/base artwork rises toward the outer edge because
    -- it depicts depth in 2D; unskew those rows on the actual angled face.
    for li,list in ipairs(lists)do
      local keep={}
      for i=starts[li]+1,#list,3 do if i%6144<3 then deps.yieldSafe() end 
        local p={list[i],list[i+1],list[i+2]};local a=p[1]
        local hi=math.max(p[1][2],p[2][2],p[3][2])
        if hi<=2.187501 and hi>comp.groundY and a[8]>.99 then
          if leftCorner then p=clip(p,1,ox+8/16,false)end
          p=clip(p,1,comp.maxX+1-8/16,true)
        elseif hi<=2.187501 and hi>comp.groundY and math.abs(a[6])>.99 then
          p=corners(p,plane,.004)
        end
        append(keep,p)
      end
      for i=#list,starts[li]+1,-1 do list[i]=nil;if i%4096==0 then deps.yieldSafe() end end
      for ki,v in ipairs(keep)do list[#list+1]=v;if ki%4096==0 then deps.yieldSafe() end end
    end
    for px=0,cols-1 do
      local da,db=depth(px),depth(px+1)
      if (leftCorner and px<8)or px>=cols-8 then
        local xa,xb=ox+px/16,ox+(px+1)/16
        local za,zb=front+.004-da,front+.004-db
        local nx,nz=-(zb-za),xb-xa;local len=math.sqrt(nx*nx+nz*nz)
        -- Wrap native front brickwork around the actual facet. The old
        -- edge columns contain baked 2D highlights, shadows and outlines,
        -- which must not become broad painted stripes on a lit 3D wall.
        local samplePx=px<8 and 8+px or cols-15+(px-(cols-7))
        for row=0,22 do
          local py=first+9+row
          local c=at(ox+math.floor(samplePx/16),oy+math.floor(py/16));local tx,ty=samplePx%16,py%16
          local o=c.hasOver and atlas.texels(c.mid,'over');local over=o and o[ty*16+tx+1]and o[ty*16+tx+1]>=0
          local r=over and overRect(c.mid)or underRect(c.mid)
          local t={(math.floor(r[1]*atlas.w)+tx+.5)/atlas.w,(math.floor(r[2]*atlas.h)+ty+.5)/atlas.h}
          local ya,yb=2.1875-row/16,2.1875-(row+1)/16
          emit(over and cutoutOver or opaque,t,{xa,ya,za},{xb,ya,zb},{xb,yb,zb},{xa,yb,za},{nx/len,0,nz/len})
        end
      end
    end



    grid.gameRim(comp,starts)
    grid.gameArch(comp,starts)
    grid.gameRearRails(comp,starts)
    for _,box in ipairs(comp.chimneyBoxes or {})do box.y0=box.y0-.25;box.y1=box.y1-.25 end
    local upper=0
    for li,list in ipairs(lists)do for i=starts[li]+1,#list,3 do if i%6144<3 then deps.yieldSafe() end 
      if math.min(list[i][2],list[i+1][2],list[i+2][2])>=2.1875-1e-8 then upper=upper+1 end
    end end
    comp.gameCorniceGeometry={deckY=2.75,brickTopY=2.1875,cornerPixels=7,nativeFirstRow=first,upperAssemblyTriangles=upper}
  end







  -- Dept-specific native wrap strips; ordinary fold/post emitters are unchanged.
  grid.deptFront = function(comp, x, bi, band, gy)
    if not comp.deptBays then return false end
    local front = comp.maxY + 1
    local function profile(px)
      for _,r in ipairs({{11,16,24,29},{51,56,88,93},{115,120,128,133}}) do
        if px >= r[1] and px <= r[4] then
          return math.max(0, r[2] - px, px - r[3]), true
        end
      end
      return 5, false
    end
    local function source(px, py)
      py = math.floor(py + .5)
      local c = at(9 + math.floor(px / 16), 6 + math.floor(py / 16))
      local tx, ty = px % 16, py % 16
      local idx = ty * 16 + tx + 1
      local o = c.hasOver and atlas.texels(c.mid, "over")
      local over = o and o[idx] and o[idx] >= 0
      local r = over and overRect(c.mid) or underRect(c.mid)
      -- One native texel column. Row runs are joined only inside one tile/layer.
      return over and cutoutOver or opaque, r, c.mid, tx, ty
    end
    local h0, h1 = band.y0 * 16, band.y1 * 16
    for px = (x - 9) * 16, (x - 9) * 16 + 15 do
      local d, bay = profile(px + .5)
      local da, db = profile(px), profile(px + 1)
      -- Outside a bay, both ends belong to the recessed main wall.
      if not bay then da, db = 5, 5 end
      local xa, xb = 9 + px / 16, 9 + (px + 1) / 16
      local function strips(a, b, above)
        if above and comp.deptUnitStarts then b=math.min(b,92) end
        local run
        local function flush()
          if not run then return end
          local uv = subRect(run.r, (run.tx + .5) / 16, (run.ty1 + .5) / 16,
            (run.tx + .5) / 16, (run.ty0 + .5) / 16)
          local za, zb = front - (above and 5 or da) / 16, front - (above and 5 or db) / 16
          if above and comp.deptUnitStarts then za,zb=run.za,run.zb end
          local nx, nz = (zb - za), (xb - xa)
          local len = math.sqrt(nx * nx + nz * nz)
          local first = #run.list + 1
          wallQuad(run.list, xa, za, xb, zb, gy + run.a / 16, gy + run.b / 16, uv, { -nx / len, 0, nz / len })
          -- Exact native glass ownership follows the emitted facet, not a
          -- stale planar window box. References are local to this mesh build.
          local tex = atlas.texels(run.mid, run.list == cutoutOver and "over" or "under")
          local palette, seen = {}, {}
          for ty = run.ty1, run.ty0 do
            local colour = tex and tex[ty * 16 + run.tx + 1]
            if type(colour) == "number" and colour >= 0 then
              local r, g, b = math.floor(colour / 65536) % 256, math.floor(colour / 256) % 256, colour % 256
              if b >= 170 and b - r >= 60 and g >= r and not seen[colour] then
                seen[colour] = true; palette[#palette + 1] = colour
              end
            end
          end
          if #palette > 0 then
            comp.nativeWindowTriangles = comp.nativeWindowTriangles or {}
            for i = first, #run.list, 3 do
              comp.nativeWindowTriangles[#comp.nativeWindowTriangles + 1] = {
                vertices = {run.list[i], run.list[i+1], run.list[i+2]},
                glassColors = palette, layer = run.list == cutoutOver and "over" or "under",
              }
            end
          end
        end
        for h = a, b - 1 do
          local py
          if above then
            -- Preserve r1's roof height: nine native rows48..56 occupy the
            -- twelve texels above the cap (4/3 vertical stretch, explicit).
            py = comp.deptUnitStarts and (55-(h-84)) or (56 - (h - 84) * 8 / 11)
          elseif bay then py = 146 - (h + .5) - d
          else py = 143 - h end
          local samplePx,samplePy=px,py
          if above and comp.deptUnitStarts then
            samplePx=math.max(2,math.min(141,px))
            samplePy=py-math.max(0,7-samplePx,samplePx-136)
          end
          local list,r,mid,tx,ty = source(samplePx,samplePy)
          local za,zb
          if above and comp.deptUnitStarts then
            za,zb=grid.deptCorniceDepth(px,py,px+.5),grid.deptCorniceDepth(px+1,py,px+.5)
          end
          if run and run.list == list and run.mid == mid and ty == run.ty1 - 1 and run.za==za and run.zb==zb then
            run.b, run.ty1 = h + 1, ty
          else
            flush(); run = {list=list,r=r,mid=mid,tx=tx,ty0=ty,ty1=ty,a=h,b=h+1,za=za,zb=zb}
          end
        end
        flush()
      end
      if bay then
        if h0 < 84 then strips(h0, math.min(h1,84), false) end
        if h1 > 84 then strips(math.max(h0,84), h1, true) end
        if h0 <= 84 and h1 > 84 then
          -- A complete trapezoid lid, including the diagonal partial cells.
          -- Its back joins the recessed wall, never clipped to an eave line.
          for dep = 0,4 do
            local a,b = math.max(dep,da), math.max(dep,db)
            local aa,bb = math.min(dep+1,a), math.min(dep+1,b)
            if aa < dep+1 or bb < dep+1 then
              local list,r,mid,tx,ty = source(px,62-(dep+.5))
              local uv=subRect(r,(tx+.5)/16,(ty+.5)/16,(tx+.5)/16,(ty+.5)/16)
              local p1={xa,gy+84/16,front-(dep+1)/16}
              local p2={xb,gy+84/16,front-(dep+1)/16}
              local p3={xb,gy+84/16,front-bb/16}
              local p4={xa,gy+84/16,front-aa/16}
              local t={uv[1],uv[2]}
              if bb < dep+1 then tri3(list,p1,t,UP,p2,t,UP,p3,t,UP) end
              if aa < dep+1 then
                if bb < dep+1 then tri3(list,p1,t,UP,p3,t,UP,p4,t,UP)
                else tri3(list,p1,t,UP,p2,t,UP,p4,t,UP) end
              end
            end
          end
        end
      elseif comp.deptUnitStarts then
        if h0<84 then strips(h0,math.min(h1,84),false) end
        if h1>84 then strips(math.max(h0,84),h1,true) end
      else strips(h0,h1,false) end
    end
    return true
  end


