  -- Unique Network facade adapter. No global PC/Mart fold state survives setup.
  grid.networkSetup=function(comp,bands,sideArt,facesOther)
    if not(comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeNetworkRoof)
      or comp.minX~=11 or comp.maxX~=17 or comp.minY~=0 or comp.maxY~=5
      or comp.groundY~=1.45 or comp.wallHeight~=2 or #bands~=2 then return end
    local cfg={FOLD_25D=true,WALL_ROW_UNIT=1,DOOR_INSET=0.12,FACADE_OVER_LIFT=0.004,FOLD_DARK_LUMA=100,FOLD_WALL_SHARE=0.02,FOLD_MIN_COLS=3,FOLD_SLOPE_MIN=0.5,FOLD_SLOPE_MAX=2,FOLD_C_MIN=0.2,FOLD_C_MAX=0.75,FOLD_EAVE_MARGIN=0.02,FOLD_LINE_CHROMA=64,FOLD_V_INSET=0.0625}
    for k,v in pairs(cfg)do if C[k]~=v then return end end
    local roles=grid.networkLiteralRoles
    local function finite(v)return type(v)=='number'and v==v and math.abs(v)<math.huge end
    local function rect(r)
      if type(r)~='table'then return false end
      for i=1,4 do if not finite(r[i])or r[i]<0 or r[i]>1 then return false end end
      return r[3]>r[1]and r[4]>r[2]
    end
    if atlas.w~=256 or atlas.h~=592 then return end
    for mid,slot in pairs({[721]=385,[736]=400,[738]=402,[739]=403,[740]=404,[742]=406,[744]=408,[745]=409,[746]=410,[748]=412,[750]=414})do
      local expected={(slot%16*16+.03125)/256,(math.floor(slot/16)*16+.03125)/592,
        (slot%16*16+16-.03125)/256,(math.floor(slot/16)*16+16-.03125)/592}
      local u,o=underRect(mid),overRect(mid)
      if not rect(u)then return end
      for i=1,4 do if math.abs(u[i]-expected[i])>1e-12 or(o and(not finite(o[i])or math.abs(o[i]-expected[i])>1e-12))then return end end
    end
    local mask={}
    for _,r in ipairs(roles)do
      local mid,px,py,rgb=r[3],r[4],r[5],r[6]
      local t=atlas.texels(mid,'under');local o=atlas.texels(mid,'over')
      if type(t)~='table'or not rect(underRect(mid))then return end
      for i=1,256 do if not finite(t[i])or(o and not finite(o[i]))then return end end
      local i=py*16+px+1
      if t[i]~=rgb or(o and o[i]>=0)then return end
      local k=r[1]+r[2]*112;if mask[k]then return end;mask[k]=r
    end
    local grey,grass=underRect(745),underRect(721)
    if not(rect(grey)and rect(grass))or atlas.texels(745,'under')[57]~=0xc5cede
      or atlas.texels(721,'under')[1]~=0x73cea5 then return end
    local foot=at(13,6)
    if not(foot and foot.mid==721 and foot.walkable and foot.hgt==comp.groundY
      and grid.networkFootOriginal and #grid.networkFootOriginal==6)then return end
    local oldFold,oldChamfer,oldWhy=comp.fold,comp.chamfer,comp.foldWhy
    comp.chamfer=.25
    local ok,err=pcall(grid.foldSetup,comp,bands,sideArt,facesOther,true)
    local fold=comp.fold
    comp.fold,comp.chamfer,comp.foldWhy=oldFold,oldChamfer,oldWhy
    if not ok then error(err)end
    if not(fold and fold.L and fold.R and fold.pro.L and fold.pro.R)then return end
    for _,key in ipairs({'L','R'})do
      local f=fold[key]
      if f.c~=.375 or f.d~=.375 or f.s~=1 then return end
      if (key=='L'and f.col>=6)or(key=='R'and f.col<=9)then return end
      if not(fold.pro[key][1]and fold.pro[key][2])then return end
      f.c,f.d=.375,.25
      local len=math.sqrt(f.c*f.c+f.d*f.d)
      f.n={(key=='L'and -1 or 1)*f.d/len,0,f.c/len}
    end
    local function texel(r,x,y)return subRect(r,(x+.5)/16,(y+.5)/16,(x+.5)/16,(y+.5)/16)end
    comp.networkFacade={fold=fold,mask=mask,grey=texel(grey,8,3),grass=texel(grass,0,0),ground=comp.groundY}
    grid.networkFacadeOwner=comp
  end

  grid.networkFront=function(comp,x,bi,base,ov,y0,y1)
    local q=comp.networkFacade;if not q then return false end
    if x==11 or x==17 then
      if bi==2 then
        local key=x==11 and'L'or'R';local f=q.fold[key];local yc=y1-5/16
        -- These five rows are native orange eave, not wall siding.
        wallQuad(opaque,x,6,x+1,6,yc,y1,subRect(base,0,0,1,5/16),N_S)
        if ov then wallQuad(cutoutOver,x,6+C.FACADE_OVER_LIFT,x+1,6+C.FACADE_OVER_LIFT,yc,y1,subRect(ov,0,0,1,5/16),N_S)end
        local a,b=x==11 and x+f.c or x,x==11 and x+1 or x+1-f.c
        local ua,ub=x==11 and f.c or 0,x==11 and 1 or 1-f.c
        wallQuad(opaque,a,6,b,6,y0,yc,subRect(base,ua,5/16,ub,1),N_S)
        if ov then wallQuad(cutoutOver,a,6+C.FACADE_OVER_LIFT,b,6+C.FACADE_OVER_LIFT,y0,yc,subRect(ov,ua,5/16,ub,1),N_S)end
        local pieces={};for _,p in ipairs(q.fold.pro[key][bi])do
          assert(p.r1<5 or p.r0>=5,'Network upper role boundary changed')
          if p.r0>=5 then pieces[#pieces+1]=p end
        end
        local xs,xe=x==11 and x or x+1,x==11 and x+f.c or x+1-f.c
        if x==11 then grid.foldWall(pieces,x,6-f.d,x+f.c,6,y0,y1,f.n)
        else grid.foldWall(pieces,x+1-f.c,6,x+1,6-f.d,y0,y1,f.n)end
        local t={q.grey[1],q.grey[2]}
        fanN(opaque,{{{xs,yc,6-f.d},t},{{xs,yc,6},t},{{xe,yc,6},t}},DOWN)
        return true
      end
      local oldFold,oldFloor=comp.fold,grid.foldFloor
      comp.fold=q.fold
      grid.foldFloor=function(c,xx,key,f)
        local xs,xe=key=='L'and xx or xx+1,key=='L'and xx+f.c or xx+1-f.c
        local t={q.grass[1],q.grass[2]}
        fanN(opaque,{{{xs,q.ground,6-f.d},t},{{xs,q.ground,6},t},{{xe,q.ground,6},t}},UP)
      end
      local ok,result=pcall(grid.foldFront,comp,x,bi,base,ov,y0,y1)
      comp.fold,grid.foldFloor=oldFold,oldFloor
      if not ok then error(result)end
      return result
    end
    if not((bi==2 and x>=13 and x<=15)or(bi==1 and(x==13 or x==15)))then return false end
    -- Retain the original unclaimed atlas regions; remove only the literal motif.
    local sy=bi==2 and 64 or 80
    for py=0,15 do
      local px=0
      while px<16 do
        local claimed=q.mask[(x-11)*16+px+(sy+py)*112]~=nil
        local stop=px+1
        while stop<16 and(q.mask[(x-11)*16+stop+(sy+py)*112]~=nil)==claimed do stop=stop+1 end
        local rr=claimed and q.grey or subRect(base,px/16,py/16,stop/16,(py+1)/16)
        wallQuad(opaque,x+px/16,6,x+stop/16,6,y1-(py+1)/16,y1-py/16,rr,N_S)
        if ov then wallQuad(cutoutOver,x+px/16,6+C.FACADE_OVER_LIFT,x+stop/16,6+C.FACADE_OVER_LIFT,
          y1-(py+1)/16,y1-py/16,subRect(ov,px/16,py/16,stop/16,(py+1)/16),N_S)end
        px=stop
      end
    end
    return true
  end

