  grid.networkSideSetup=function(comp)
    if not comp.networkFacade or not(comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeNetworkRoof)
      or comp.minX~=11 or comp.maxX~=17 or comp.minY~=0 or comp.maxY~=5 or math.abs(comp.wallTopY-comp.groundY-2)>1e-9
      or atlas.w~=256 or atlas.h~=592 then return end
    for _,d in ipairs(grid.networkSideData.donors)do
      local t=atlas.texels(d[1],d[2]);local r=d[2]=='over'and overRect(d[1])or underRect(d[1]);if not t or not r then return end
      local h=0;for i=1,256 do local v=t[i];if type(v)~='number'or v~=v or v==math.huge or v==-math.huge then return end;h=(h*31+(v>=0 and v+2 or 1))%2147483647 end
      if h~=d[3]then return end;for i=1,4 do if type(r[i])~='number'or r[i]~=r[i]or math.abs(r[i]-d[4][i])>1e-10 then return end end
    end
    comp.nativeNetworkSides=true
  end
  grid.networkSideWall=function(comp,ax,az,bx,bz,y0,y1,n)
    if not comp.nativeNetworkSides or n[3]>0 or y1<=y0 then return false end
    local side=n[1]~=0
    if side and not(math.abs(ax-bx)<1e-9 and(ax==11 or ax==18))then return false end
    if not side and not(az==0 and bz==0 and n[3]==-1)then return false end
    local function clip(p,k,b,less)
      local out={};for i,a in ipairs(p)do local z=p[i%#p+1];local ia=less and a[k]<=b+1e-10 or not less and a[k]>=b-1e-10;local ib=less and z[k]<=b+1e-10 or not less and z[k]>=b-1e-10
        if ia then out[#out+1]=a end;if ia~=ib then local t=(b-a[k])/(z[k]-a[k]);local v={};for j=1,8 do v[j]=a[j]+t*(z[j]-a[j])end;v[k]=b;out[#out+1]=v end
      end;return out
    end
    local axis=side and 3 or 1;local lo=side and math.min(az,bz)or math.min(ax,bx);local hi=side and math.max(az,bz)or math.max(ax,bx)
    for _,q in ipairs(grid.networkSideData.parts)do if q.n[1]==n[1]and q.n[3]==n[3]then
      local r=q.layer=='over'and overRect(q.mid)or underRect(q.mid);local p={}
      for _,v in ipairs(q.p)do p[#p+1]={v[1],comp.groundY+v[2],v[3],r[1]+v[4]*(r[3]-r[1]),r[2]+v[5]*(r[4]-r[2]),n[1],n[2],n[3]}end
      p=clip(clip(clip(clip(p,axis,lo,false),axis,hi,true),2,y0,false),2,math.min(y1,comp.wallTopY),true)
      local list=q.layer=='over'and cutoutOver or opaque
      for j=2,#p-1 do local a,b,c=p[1],p[j],p[j+1];local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3];local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        if(uy*vz-uz*vy)*n[1]+(uz*vx-ux*vz)*n[2]+(ux*vy-uy*vx)*n[3]>1e-12 then
          for _,v in ipairs{a,b,c}do local z={};for k=1,8 do z[k]=v[k]end;z.nativeNetworkSide=true;list[#list+1]=z end
        end
      end
    end end
    return true
  end

  grid.networkSide=function(comp,emit)
    local lists={opaque,cutoutUnder,cutoutOver,cutoutKeyed};local starts={}
    for i,l in ipairs(lists)do starts[i]=#l end
    emit()
    local yc=comp.groundY+27/16
    local function clip(poly,axis,bound,less)
      local out={}
      local function inside(v)return less and v[axis]<=bound+1e-12 or not less and v[axis]>=bound-1e-12 end
      for i,a in ipairs(poly)do local b=poly[i%#poly+1];local ia,ib=inside(a),inside(b)
        if ia then out[#out+1]=a end
        if ia~=ib then local t=(bound-a[axis])/(b[axis]-a[axis]);local v={}
          for k,val in pairs(a)do v[k]=val end
          for k=1,8 do v[k]=a[k]+t*(b[k]-a[k])end;v[axis]=bound;out[#out+1]=v
        end
      end
      return out
    end
    for li,l in ipairs(lists)do local old={};for i=starts[li]+1,#l do old[#old+1]=l[i]end
      for i=#l,starts[li]+1,-1 do l[i]=nil end
      for i=1,#old,3 do local p={old[i],old[i+1],old[i+2]}
        local regions={clip(clip(p,2,yc,true),3,5.75,true),clip(p,2,yc,false)}
        for _,poly in ipairs(regions)do for j=2,#poly-1 do
          local a,b,c=poly[1],poly[j],poly[j+1]
          local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3];local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
          local area=(uy*vz-uz*vy)^2+(uz*vx-ux*vz)^2+(ux*vy-uy*vx)^2
          if area>1e-24 then l[#l+1]=a;l[#l+1]=b;l[#l+1]=c end
        end end
      end
    end
  end

  grid.networkFinish=function()
    local comp=grid.networkFacadeOwner;if not comp then return end
    local q=comp.networkFacade
    local function draw(points,uv,n,tag)
      local function crossOf(order)
        local a,b,c=points[order[1]],points[order[2]],points[order[3]]
        local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
        local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
        return {uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx}
      end
      local orders={{1,2,3},{1,3,4}}
      local crosses={crossOf(orders[1]),crossOf(orders[2])}
      if not n then
        for _,c in ipairs(crosses)do
          local len=math.sqrt(c[1]^2+c[2]^2+c[3]^2)
          if len>1e-12 then n={c[1]/len,c[2]/len,c[3]/len};break end
        end
      end
      if not n then return end
      local ts={{uv[1],uv[2]},{uv[3],uv[2]},{uv[3],uv[4]},{uv[1],uv[4]}}
      for ti,order in ipairs(orders)do
        local c=crosses[ti];local dot=c[1]*n[1]+c[2]*n[2]+c[3]*n[3]
        if math.abs(dot)>1e-12 then
          if dot<0 then order={order[1],order[3],order[2]}end
          for _,i in ipairs(order)do vtx(opaque,points[i],ts[i],n);opaque[#opaque].networkRole=tag end
        end
      end
    end
    local function depth(v)return math.max(0,math.min(.20,(v-69)/40))end
    local function rise(v)return math.max(0,math.min(.25,(v-69)/32))end
    local function point(u,v)return{11+u/16,q.ground+(96-v)/16+rise(v),6+depth(v)}end
    local function old(u,v)return{11+u/16,math.max(q.ground,q.ground+(96-v)/16),6}end
    -- Affine native row runs preserve the complete motif without a stretched atlas.
    for v=69,99 do
      local u=0
      while u<112 do
        local r=q.mask[u+v*112]
        if r then
          local stop=u+1
          while stop<112 do local t=q.mask[stop+v*112]
            if not t or t[3]~=r[3]or t[7]~=r[7]then break end;stop=stop+1
          end
          local rr=subRect(underRect(r[3]),r[4]/16,r[5]/16,(r[4]+stop-u)/16,(r[5]+1)/16)
          local dv=depth(v+1)-depth(v);local dy=rise(v+1)-rise(v)
          local ny,nz=dv,1/16-dy;local len=math.sqrt(ny*ny+nz*nz)
          draw({point(u,v),point(stop,v),point(stop,v+1),point(u,v+1)},rr,{0,ny/len,nz/len},r[7])
          u=stop
        else u=u+1 end
      end
    end
    -- Only the true union perimeter gets returns; adjacent motif pixels share faces.
    for _,r in ipairs(grid.networkLiteralRoles)do
      local u,v=r[1],r[2]
      local edges={{u,v,u+1,v,0,-1},{u+1,v,u+1,v+1,1,0},{u+1,v+1,u,v+1,0,1},{u,v+1,u,v,-1,0}}
      for _,e in ipairs(edges)do
        if not q.mask[u+e[5]+(v+e[6])*112]then
          local a,b=point(e[1],e[2]),point(e[3],e[4])
          local oa,ob=old(e[1],e[2]),old(e[3],e[4])
          -- Right pillar's hidden foot is plain structure, never mirrored art.
          if v==95 and u>=64 and u<72 and e[6]==1 then
            oa={a[1],q.ground,a[3]};ob={b[1],q.ground,b[3]}
          end
          if not(a[2]==q.ground and b[2]==q.ground and oa[2]==q.ground and ob[2]==q.ground)then
            draw({a,b,ob,oa},q.grey,nil,'perimeter-return')
          end
        end
      end
    end
    -- Side triangles of the plain right foot meet its front, rear and ground.
    for _,x in ipairs{15,15.5}do
      local t={q.grey[1],q.grey[2]};local first=#opaque
      fanN(opaque,{{{x,q.ground,6},t},{{x,q.ground+.25,6.20},t},{{x,q.ground,6.20},t}},x==15 and N_W or N_E)
      for i=first+1,#opaque do opaque[i].networkRole='right-foot-closure'end
    end
    -- Replace only the recorded original M1 ground producer, by vertex identity.
    local remove={};for _,v in ipairs(grid.networkFootOriginal)do remove[v]=true end
    local dst=1;for i=1,#opaque do local v=opaque[i];if not remove[v]then opaque[dst]=v;dst=dst+1 end end
    for i=#opaque,dst,-1 do opaque[i]=nil end
    local rr=underRect(721)
    for py=0,15 do local px=0;while px<16 do
      local claimed=q.mask[32+px+(96+py)*112]~=nil
      local stop=px+1
      while stop<16 and(q.mask[32+stop+(96+py)*112]~=nil)==claimed do stop=stop+1 end
      local uv=claimed and q.grass or subRect(rr,px/16,py/16,stop/16,(py+1)/16)
      draw({{13+px/16,q.ground,6+py/16},{13+stop/16,q.ground,6+py/16},
        {13+stop/16,q.ground,6+(py+1)/16},{13+px/16,q.ground,6+(py+1)/16}},uv,UP,'apron-grass')
      px=stop
    end end
  end

  grid.foldSetup = function(comp, bands, sideArt, facesOther, networkPartition)
    comp.fold = nil
    if C.FOLD_25D == false or type(atlas.texels) ~= "function" or not sideArt.plain or #bands == 0 then return end
    local post = not comp.chamfer and grid.foldPost(comp) or nil
    if not comp.chamfer and not post then return end
    -- the FOLDED BANDS: every band of a PC / Mart; the gym's post only in
    -- the bottom band (the band above it is the roof's front art)
    local fb = {}
    if post then
      fb[1] = true
    else
      if not comp.roofBottom or not comp.roofTop or comp.roofBottom < comp.roofTop then return end
      for bi, b in ipairs(bands) do
        if b.filler then return end
        fb[bi] = true
      end
    end
    local tex = atlas.texels
    local _, gpal0 = groundTaint(comp.minX, comp.minY, comp.maxX, comp.maxY)
    local function rgb(v) return math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256 end
    local function luma(v) local r, g, b = rgb(v) return 0.299 * r + 0.587 * g + 0.114 * b end
    -- (the composite texel -- over art where it is opaque -- and its layer)
    local function vis(c, i)
      local o = c.hasOver and tex(c.mid, "over") or nil
      if o and o[i] and o[i] >= 0 then return o[i], "over" end
      local u = tex(c.mid, "under")
      return u and u[i] or nil, "under"
    end
    -- r3 (skeptic N2: the same gym / PC art got different stripes per town): the fold's GROUND palette
    -- is the paving round the building MINUS the colours its own ground-floor facade uses (>=
    -- FOLD_WALL_SHARE of the inner cells -- not the corner cells, whose corner triangles draw grass):
    -- Pewter's grey paving adbdce, Viridian's cedeef are also the facade's band colours
    local gpal
    if gpal0 then
      local own, nOwn = {}, 0
      for x = comp.minX + 1, comp.maxX - 1 do
        local c = at(x, comp.maxY)
        if c and isCompCell(c, comp) then
          for i = 1, 256 do
            local v = vis(c, i)
            if v and v >= 0 then own[v] = (own[v] or 0) + 1; nOwn = nOwn + 1 end
          end
        end
      end
      gpal = {}
      for v in pairs(gpal0) do
        if (own[v] or 0) < C.FOLD_WALL_SHARE * nOwn or nOwn == 0 then gpal[v] = true end
      end
    end
    -- WALL colours: >= FOLD_WALL_SHARE of the ground-floor facade (doors and
    -- signs out), not an outline (dark), not ground, not glass
    local share, tot = {}, 0
    for x = comp.minX, comp.maxX do
      local c = at(x, comp.maxY)
      if c and isCompCell(c, comp) and not c.isDoor and not c.isSign then
        for i = 1, 256 do
          local v = vis(c, i)
          if v and v >= 0 then share[v] = (share[v] or 0) + 1; tot = tot + 1 end
        end
      end
    end
    if tot == 0 then return end
    local function dark(v) return v ~= nil and v >= 0 and luma(v) < C.FOLD_DARK_LUMA and not (gpal and gpal[v]) end
    -- a LINE texel: dark and near-neutral (the outline navy 424a6b, 5a5a73) --
    -- not a dark roof colour (the PC eave's red ad2129 is as dark)
    local function line(v)
      if not dark(v) then return false end
      local r, g, b = rgb(v)
      return math.max(r, g, b) - math.min(r, g, b) <= C.FOLD_LINE_CHROMA
    end
    -- (glass: blue-dominant -- windows, the Mart's blue roof -- is never wall)
    local function glass(v) local r, g, b = rgb(v) return b >= r + 60 and b >= g + 10 end
    local function wall(v)
      return v ~= nil and v >= 0 and not dark(v) and not (gpal and gpal[v]) and not glass(v)
        and (share[v] or 0) >= C.FOLD_WALL_SHARE * tot
    end
    -- (the building's own art cells: its cells, its overhang row, its facade signs -- the PC's "P.C" and
    -- the Mart's "MART" signs start in the corner cell)
    local function roofish(cc) return cc ~= nil and (isCompCell(cc, comp) or cc.overhangOf == comp or cc.facadeOf == comp) end
    local fold = { pro = {}, side = {}, flat = {}, src = {}, bands = fb, nb = #bands, top = 0 }
    for bi = 1, #bands do if fb[bi] then fold.top = bi end end
    -- runs of one cell / layer / column with consecutive texel rows ->
    -- pieces (a FILL row: one texel stretched). r2 (the skeptic's seam
    -- dots, 6a7682 along the grey band under the eave): a piece of ONE
    -- texel row samples its row's centre, like u -- never its edges
    local function pieces(rows, bi, key)
      local out, r = {}, 0
      while r <= 15 do
        local s0, r1 = rows[r], r
        while r1 < 15 do
          local q = rows[r1 + 1]
          if q[1] == s0[1] and q[2] == s0[2] and q[3] == s0[3] and ((s0.fill and q.fill and q[4] == s0[4])
              or (not s0.fill and not q.fill and q[4] == s0[4] + (r1 + 1 - r))) then r1 = r1 + 1 else break end
        end
        local mid = s0[1].mid
        local rect = s0[2] == "over" and overRect(mid) or underRect(mid)
        if rect then
          local ty0, ty1 = s0[4], s0.fill and s0[4] or s0[4] + (r1 - r)
          -- r3 (skeptic N1, the Mart's roof blue as a broken line over the navy base line): a piece of
          -- several rows keeps its v range FOLD_V_INSET texel inside its own first / last row -- through
          -- the atlas rect's inset a texel edge inside a tile landed 0.016 px into the row beyond
          local e = C.FOLD_V_INSET or 0
          local v0, v1 = (ty0 + e) / 16, (ty1 + 1 - e) / 16
          if s0.fill or ty0 == ty1 then v0, v1 = (ty0 + 0.5) / 16, (ty0 + 0.5) / 16 end
          local u = rect[1] + (rect[3] - rect[1]) * (s0[3] + 0.5) / 16
          local vb = rect[2] + (rect[4] - rect[2]) * (ty1 + 0.5) / 16
          local pc = { r0 = r, r1 = r1, list = s0[2] == "over" and cutoutOver or opaque,
            uv = { u, rect[2] + (rect[4] - rect[2]) * v0, u, rect[2] + (rect[4] - rect[2]) * v1 },
            bottom = { u, vb, u, vb } }
          -- (over art that is not solid: its under art behind it)
          if s0[2] == "over" and (overCoverage(mid) or 0) < C.ROOF_SOLID_MIN then
            local ur = underRect(mid)
            if ur then
              local uu = ur[1] + (ur[3] - ur[1]) * (s0[3] + 0.5) / 16
              pc.back = { uu, ur[2] + (ur[4] - ur[2]) * v0, uu, ur[2] + (ur[4] - ur[2]) * v1 }
            end
          end
          out[#out + 1] = pc
          fold.src[#fold.src + 1] = { mid = mid, layer = s0[2], x0 = s0[3], x1 = s0[3], y0 = ty0, y1 = ty1, side = key, band = bi }
        end
        r = r1 + 1
      end
      return out
    end
    local any = false
    local why = {} -- (per corner: why it does not fold -- buildingInfo.foldWhy)
    comp.foldWhy = why
    for _, sd in ipairs({ { "L", comp.minX, comp.minX - 1 }, { "R", comp.maxX, comp.maxX + 1 } }) do
      local key, x = sd[1], sd[2]
      local c = at(x, comp.maxY)
      -- (an ATTACHED corner is read too: it is flattened, never folded)
      local attached = facesOther(sd[3], comp.maxY)
      why[key] = not roofish(c) and "not own art" or c.isDoor and "door" or nil
      -- (k counts the edge cell's columns from the building's outer edge)
      local function tx(k) return key == "L" and k or 15 - k end
      local kc, s, ncol, gF
      local ks = {}
      if not why[key] and post then
        -- the gym's post: its own 45-degree line (one colour on the
        -- diagonal ending one row above the front's line row r0)
        local d0 = vis(c, (post.r0 - 1) * 16 + tx(post.kc - 1) + 1)
        local okP = d0 ~= nil and d0 >= 0
        for j = 2, 3 do if vis(c, (post.r0 - j) * 16 + tx(post.kc - j) + 1) ~= d0 then okP = false end end
        if okP then
          kc, s, ncol = post.kc, post.s, #post.cols
          for _, k in ipairs(post.cols) do ks[#ks + 1] = k end
        else
          why[key] = "post art differs"
        end
      elseif not why[key] then
        why[key] = "no ground line"
        -- the art's GROUND LINE: per column the lowest outline texel
        local g = {}
        for k = 0, 15 do
          for ty = 15, 0, -1 do
            if dark((vis(c, ty * 16 + tx(k) + 1))) then g[k] = ty break end
          end
        end
        local cnt, gn = {}, 0
        for k = 8, 15 do
          local v = g[k]
          if v then
            cnt[v] = (cnt[v] or 0) + 1
            if cnt[v] > gn or (cnt[v] == gn and v > gF) then gF, gn = v, cnt[v] end
          end
        end
        if gF and gF >= 12 and gn >= 5 then
          why[key] = "no diagonal"
          -- the CREASE: the outermost column still on the front's ground row;
          -- outward of it the line rises steadily (the receding corner)
          local k0 = 15
          while k0 > 0 and g[k0 - 1] == gF do k0 = k0 - 1 end
          local pts, rise = {}, 0
          for k = k0 - 1, 0, -1 do
            local v = g[k]
            if not v or v >= gF or gF - v < rise then break end
            rise = gF - v
            pts[#pts + 1] = { k0 - k, rise }
          end
          if #pts >= C.FOLD_MIN_COLS then
            local sxy, sxx = 0, 0
            for _, p in ipairs(pts) do sxy, sxx = sxy + p[1] * p[2], sxx + p[1] * p[1] end
            local s0 = sxy / sxx
            local dev = 0
            for _, p in ipairs(pts) do dev = math.max(dev, math.abs(p[2] - s0 * p[1])) end
            why[key] = string.format("slope %.2f dev %.2f c %.3f", s0, dev, k0 / 16)
            -- plan: the angled wall spans the crease's width c across and
            -- c * slope back (2.5D: a texel up = a texel back)
            if s0 >= C.FOLD_SLOPE_MIN and s0 <= C.FOLD_SLOPE_MAX and dev <= 1.01 and k0 / 16 >= C.FOLD_C_MIN
                and k0 / 16 <= C.FOLD_C_MAX and k0 / 16 * s0 <= 0.9 then
              kc, s, ncol = k0, s0, #pts
              for k = kc - ncol + 1, kc - 1 do ks[#ks + 1] = k end
            end
          end
        end
      end
      -- Network-only source partition: six native outside columns, independent
      -- of the generic detector's seven-column outline. Ordinary calls pass nil.
      if networkPartition and comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeNetworkRoof then
        if kc~=7 or s~=1 then return end
        kc,ncol,ks=6,5,{1,2,3,4,5}
      end
      -- the folded bands' edge cells must be the building's own art
      local fcells = {}
      if kc then
        for bi = 1, #bands do
          if fb[bi] then
            fcells[bi] = at(x, bands[bi].rowY)
            if not roofish(fcells[bi]) then kc = nil; why[key] = "band " .. bi .. " not own art" end
          end
        end
      end
      if kc then
        -- the un-skewed texel of column k (shift sh) at band row r: { cell,
        -- layer, tx, ty, v = colour } (own art only)
        local function srcAt(k, sh, bi, r)
          local Yg = bands[bi].rowY * 16 + r - sh
          local cc = at(x, math.floor(Yg / 16))
          if not roofish(cc) then return nil end
          local ty = Yg % 16
          local v, layer = vis(cc, ty * 16 + tx(k) + 1)
          if v == nil or v < 0 then return nil end
          return { cc, layer, tx(k), ty, v = v }
        end
        -- the PATTERN COLUMN: a column inside the diagonal (not its outline
        -- column) whose un-skewed rows are most often wall
        local best, bestN, bestD
        for _, k in ipairs(ks) do
          local sh = math.floor(s * (kc - k) + 0.5)
          local nw = 0
          for bi = 1, #bands do
            if fb[bi] then
              for r = 0, 15 do
                local q = srcAt(k, sh, bi, r)
                if q and wall(q.v) then nw = nw + 1 end
              end
            end
          end
          local dm = math.abs(k - (kc - ncol * 0.5))
          if not best or nw > bestN or (nw == bestN and dm < bestD) then best, bestN, bestD = k, nw, dm end
        end
        local sh = best and math.floor(s * (kc - best) + 0.5)
        -- per band: the un-skewed WALL and LINE rows (nil where the corner
        -- draws roof, glass or ground)
        local rowsW, mains, mostB = {}, {}, nil
        for bi = 1, best and #bands or 0 do
          if fb[bi] then
            local rows, cnt, bestC, nw = {}, {}, nil, 0
            for r = 0, 15 do
              local q = srcAt(best, sh, bi, r)
              -- (ground under the base line: the same row one column toward the crease)
              if q and gpal and gpal[q.v] then
                local q2
                for k2 = best + 1, kc do
                  q2 = srcAt(k2, sh, bi, r)
                  if q2 and not gpal[q2.v] then break end
                  q2 = nil
                end
                q = q2
              end
              if q and wall(q.v) then
                rows[r] = q
                nw = nw + 1
                cnt[q.v] = (cnt[q.v] or 0) + 1
                if not bestC or cnt[q.v] > cnt[bestC] then bestC = q.v end
              elseif q and line(q.v) then
                rows[r] = q
              end
            end
            -- the band's MAIN wall colour: the middle texel of its longest
            -- run in the pattern column (the plain plaster)
            local runB, runL, r = nil, 0, 0
            while r <= 15 do
              if rows[r] and rows[r].v == bestC then
                local r1 = r
                while r1 < 15 and rows[r1 + 1] and rows[r1 + 1].v == bestC do r1 = r1 + 1 end
                if r1 - r + 1 > runL then runB, runL = rows[math.floor((r + r1) / 2)], r1 - r + 1 end
                r = r1 + 1
              else
                r = r + 1
              end
            end
            rowsW[bi], mains[bi], mains[-bi] = rows, runB, nw
            if not mostB or nw > mains[-mostB] then mostB = bi end
          end
        end
        -- (a band the corner draws mostly as roof -- the Mart's awning row --
        -- takes the plaster of the band with the most wall rows)
        for bi = 1, #bands do
          if fb[bi] and rowsW[bi] and mains[-bi] < 8 then mains[bi] = mains[mostB] end
        end
        if best and mostB then
          local angP, flatP = {}, {}
          for bi = 1, #bands do
            if fb[bi] then
              local rows, main = rowsW[bi], mains[bi]
              local ra, rf = {}, {}
              for r = 0, 15 do
                -- the front's own texel beside the crease, same height
                local fc = fcells[bi]
                local _, layer = vis(fc, r * 16 + tx(kc) + 1)
                local front = { fc, layer, tx(kc), r }
                if rows[r] then
                  ra[r], rf[r] = rows[r], rows[r]
                else
                  -- ANGLED / SIDE / BACK walls: the band's plaster; an
                  -- ATTACHED corner (flat): the front beside it (the eave,
                  -- the awning continue to the neighbour)
                  ra[r] = main and { main[1], main[2], main[3], main[4], fill = true } or front
                  rf[r] = front
                end
              end
              angP[bi] = pieces(ra, bi, key)
              if attached then flatP[bi] = pieces(rf, bi, key) end
            end
          end
          local cU, dU = kc / 16, kc / 16 * s
          local len = math.sqrt(cU * cU + dU * dU)
          fold.side[key] = angP
          if attached then
            fold.flat[key] = { c = cU, pro = flatP, kc = tx(kc), col = tx(best), shift = sh }
            why[key] = "attached"
          else
            local rec = { c = cU, d = dU, s = s, kc = tx(kc), cols = ncol, col = tx(best), shift = sh, gF = gF,
              n = { (key == "L" and -dU or dU) / len, 0, cU / len }, bands = fb, post = post and true or nil }
            -- (the cap under an unfolded band above: the top folded band's plaster texel)
            local mt = mains[fold.top]
            local r = mt and (mt[2] == "over" and overRect(mt[1].mid) or underRect(mt[1].mid))
            if r then
              local u, v = r[1] + (r[3] - r[1]) * (mt[3] + 0.5) / 16, r[2] + (r[4] - r[2]) * (mt[4] + 0.5) / 16
              rec.cap = { mt[2] == "over" and cutoutOver or opaque, { u, v, u, v } }
            end
            fold[key], fold.pro[key] = rec, angP
            why[key] = nil
          end
          any = true
        end
      end
    end
    if any then comp.fold = fold end
  end
  -- the pattern pieces on one vertical wall a -> b (the band y0 .. y1)
  grid.foldWall = function(pieces, ax, az, bx, bz, y0, y1, n, flatOver)
    for i, p in ipairs(pieces or {}) do
      local ya, yb = y1 - (p.r1 + 1) / 16 * (y1 - y0), y1 - p.r0 / 16 * (y1 - y0)
      local lx, lz = 0, 0
      if p.back then
        wallQuad(opaque, ax, az, bx, bz, ya, yb, p.back, n)
      end
      -- Attached corner art meets the lifted front over-layer on one plane.
      -- Keep opaque backing in place and apply the existing lift only once.
      if p.back or (flatOver and p.list == cutoutOver) then
        lx, lz = n[1] * C.FACADE_OVER_LIFT, n[3] * C.FACADE_OVER_LIFT
      end
      -- At an attached span's under/over row transition, the lifted over
      -- face and unlifted wall meet through this thin horizontal return.
      -- Sample the unlifted neighbour's boundary texel, never a new colour.
      local prev = flatOver and pieces[i - 1]
      if prev and prev.r1 + 1 == p.r0 then
        local pl = (prev.back or prev.list == cutoutOver) and C.FACADE_OVER_LIFT or 0
        if pl ~= lz then
          local uv = pl > lz and { p.uv[1], p.uv[2], p.uv[1], p.uv[2] } or prev.bottom
          hQuad(opaque, ax, az + math.min(pl, lz), bx, bz + math.max(pl, lz), yb, uv,
            pl > lz and DOWN or UP)
        end
      end
      wallQuad(p.list, ax + lx, az + lz, bx + lx, bz + lz, ya, yb, p.uv, n)
    end
  end
  -- an edge cell of the front, band bi: a FOLDED corner = the flat front
  -- (art from the crease on) and the angled corner wall with the un-skewed
  -- corner pattern; an ATTACHED corner = the flat front with the corner
  -- columns showing the same rows. false = neither (the caller's old code)
  grid.foldFront = function(comp, x, bi, base, ov, y0, y1)
    local F = comp.fold
    local key = (x == comp.minX and "L") or (x == comp.maxX and "R") or nil
    if not F or not key then return false end
    local f, fl = F[key], F.flat[key]
    local pcs = f and F.pro[key] and F.pro[key][bi]
    local flat = not pcs and fl and fl.pro[bi]
    if not pcs and not flat then return false end
    local z = comp.maxY + 1
    local zf = z + C.FACADE_OVER_LIFT
    local c = pcs and f.c or fl.c
    if key == "L" then
      wallQuad(opaque, x + c, z, x + 1, z, y0, y1, subRect(base, c, 0, 1, 1), N_S)
      if ov then wallQuad(cutoutOver, x + c, zf, x + 1, zf, y0, y1, subRect(ov, c, 0, 1, 1), N_S) end
      if pcs then grid.foldWall(pcs, x, z - f.d, x + c, z, y0, y1, f.n)
      else grid.foldWall(flat, x, z, x + c, z, y0, y1, N_S, true) end
    else
      wallQuad(opaque, x, z, x + 1 - c, z, y0, y1, subRect(base, 0, 0, 1 - c, 1), N_S)
      if ov then wallQuad(cutoutOver, x, zf, x + 1 - c, zf, y0, y1, subRect(ov, 0, 0, 1 - c, 1), N_S) end
      if pcs then grid.foldWall(pcs, x + 1 - c, z, x + 1, z - f.d, y0, y1, f.n)
      else grid.foldWall(flat, x + 1 - c, z, x + 1, z, y0, y1, N_S, true) end
    end
    -- (the bottom band: the notch's FLOOR -- a building cell draws no ground,
    -- so under the angled wall the void showed through)
    if pcs and bi == 1 then grid.foldFloor(comp, x, key, f) end
    -- (the top folded band under an unfolded one -- the gym's post under its
    -- roof-front band: a cap closes the notch from below)
    if pcs and f.cap and bi == F.top and F.top < F.nb then
      local xs, xe = key == "L" and x or x + 1, key == "L" and x + c or x + 1 - c
      local t = { f.cap[2][1], f.cap[2][2] }
      fanN(f.cap[1], { { { xs, y1, z - f.d }, t }, { { xs, y1, z }, t }, { { xe, y1, z }, t } }, DOWN)
    end
    return true
  end
  -- the floor of a folded corner's notch (between the angled wall and the
  -- old square corner) when the corner cell is a building cell (whose ground
  -- is hidden): the ground tile beside it (else in front; else the art of a
  -- non-volume cell beside / in front -- a cliff edge; else the plinth's
  -- base texel), at the building's ground height. A sign / door corner
  -- cell keeps its own ground.
  grid.foldFloor = function(comp, x, key, f)
    local c = at(x, comp.maxY)
    if not (c and isCompCell(c, comp)) then return end
    local function plain(q) return q ~= nil and q.walkable and not q.isDoor and not q.isSign and not q.hasOver and compOf(q) == nil end
    local nb, fr = at(key == "L" and x - 1 or x + 1, comp.maxY), at(x, comp.maxY + 1)
    local g = plain(nb) and nb or (plain(fr) and fr) or (nb and compOf(nb) == nil and nb) or (fr and compOf(fr) == nil and fr) or nil
    local r = g and underRect(g.groundMid or g.mid)
    local list = opaque
    if not r then
      local uv, pl = grid.foldPlinth(comp)
      if not uv then return end
      r, list = { uv[1], uv[2], uv[1], uv[2] }, pl
    end
    local y, z = comp.groundY, comp.maxY + 1
    local function pt(px, pz) return { { px, y, pz }, { r[1] + (px - x) * (r[3] - r[1]), r[2] + (pz - comp.maxY) * (r[4] - r[2]) } } end
    local xs, xe = key == "L" and x or x + 1, key == "L" and x + f.c or x + 1 - f.c
    fanN(list, { pt(xs, z - f.d), pt(xs, z), pt(xe, z) }, UP)
  end
  -- side / back walls: the corner's pattern (east wall: the east corner's)
  grid.foldSideFn = function(comp, old, gy)
    return function(ax, az, bx, bz, y0, y1, n, bottom)
      -- (east wall: the east corner's rows, west: the west's; the back wall:
      -- a FOLDED corner's rows, west first -- an attached corner has no
      -- angled wall for it to continue)
      local F = comp.fold
      local pro = F.side
      local back = (F.L and "L") or (F.R and "R") or (pro.L and "L") or "R"
      local key = (n[1] > 0.5 and pro.R and "R") or (n[1] < -0.5 and pro.L and "L") or back
      local bi = math.floor((y0 - gy) / C.WALL_ROW_UNIT + 0.5) + 1
      local pcs = pro[key] and pro[key][bi]
      if pcs and math.abs((y1 - y0) - C.WALL_ROW_UNIT) < 1e-6 then
        grid.foldWall(pcs, ax, az, bx, bz, y0, y1, n)
      else
        old(ax, az, bx, bz, y0, y1, n, bottom)
      end
    end
  end
  -- the plinth under a folded building's walls: its side pattern's bottom
  -- texel row (the base line), stretched down
  grid.foldPlinth = function(comp)
    local sd = comp.fold.side
    local band1 = (sd.L or sd.R)[1]
    local p = band1 and band1[#band1]
    if p then return p.bottom, p.list end
    return nil
  end
  -- (the side walls' / plinths' front row stops at a folded corner; key
  -- "L" / "R" or side 1 / 2; bi = the band, nil = any)
  grid.foldD = function(comp, key, bi)
    if key == 1 or key == 2 then key = key == 1 and "L" or "R" end
    local f = comp.fold and comp.fold[key]
    return f and (not bi or f.bands[bi]) and f.d or 0
  end
  -- a folded corner cell's front plinth: the flat part, and under the angled
  -- wall from the lower of the ground in front / beside it; false = not one
  grid.foldPlinthFront = function(comp, x, plinth, z, groundY)
    local key = comp.fold and ((x == comp.minX and comp.fold.L and "L") or (x == comp.maxX and comp.fold.R and "R")) or nil
    if not key then return false end
    local f = comp.fold[key]
    if key == "L" then
      plinth(x, comp.maxY, x, comp.maxY + 1, x + f.c, z, x + 1, z, N_S)
    else
      plinth(x, comp.maxY, x, comp.maxY + 1, x, z, x + 1 - f.c, z, N_S)
    end
    local sx = key == "L" and x - 1 or x + 1
    local a, b = at(x, comp.maxY + 1), at(sx, comp.maxY)
    local ox, oy = x, comp.maxY + 1
    if b and b.hgt and (not (a and a.hgt) or b.hgt < a.hgt) then ox, oy = sx, comp.maxY end
    if key == "L" then plinth(x, comp.maxY, ox, oy, x, z - f.d, x + f.c, z, f.n)
    else plinth(x, comp.maxY, ox, oy, x + 1 - f.c, z, x + 1, z - f.d, f.n) end
    return true
  end
  grid.foldDepth = function(comp, side, bi)
    local f = comp.fold and comp.fold[side == 1 and "L" or "R"]
    if f then return (not bi or f.bands[bi]) and f.d or 0 end
    return comp.chamfer or 0
  end
  -- ROOF: the rounded eave's plan follows the angled walls. Its lip runs
  -- parallel to each angled wall, at least EAVE_OVERHANG out and past the
  -- old square corner (the roof still covers the whole footprint), so the
  -- inner outline (the hip's base, `inset` inside the lip) is cut at A (on
  -- the front edge) and B (on the side edge). -> comp.fold.cut
  grid.foldRoofCut = function(comp, touch, ix0, ix1, iz0, iz1, inset, bx0, bx1, bz1)
    local out
    for _, key in ipairs({ "L", "R" }) do
      local f = comp.fold[key]
      if f and not touch[key == "L" and "left" or "right"] then
        local mx, mz = f.n[1], f.n[3]
        local Px, Pz = key == "L" and bx0 or bx1, bz1 - f.d
        local od = comp.ov1 and (math.abs(mx)*comp.ov1.ds+math.abs(mz)*comp.ov1.df) or math.max(C.EAVE_OVERHANG, f.c * f.d / math.sqrt(f.c * f.c + f.d * f.d) + C.FOLD_EAVE_MARGIN)
        local lipK = mx * Px + mz * Pz + od
        local k = lipK - inset
        local xe = key == "L" and ix0 or ix1
        local Ax, Bz = (k - mz * iz1) / mx, (k - mx * xe) / mz
        local okA = key == "L" and (Ax > ix0 + 0.02 and Ax < (ix0 + ix1) / 2) or (Ax < ix1 - 0.02 and Ax > (ix0 + ix1) / 2)
        if okA and Bz < iz1 - 0.02 and Bz > (iz0 + iz1) / 2 then
          local th = math.atan2(mx, mz)
          if th < 0 then th = th + 2 * math.pi end
          out = out or {}
          out[key] = { A = { Ax, iz1 }, B = { xe, Bz }, m = { mx, mz }, th = th, od = od, lip = { mx, mz, lipK } }
        end
      end
    end
    comp.fold.cut = out
    return out
  end
  -- a plan half-plane through p1 -> p2 keeping the side of q: { nx, nz, d }
  grid.halfPlane = function(p1, p2, q)
    local nx, nz = -(p2[2] - p1[2]), p2[1] - p1[1]
    if nx * (q[1] - p1[1]) + nz * (q[2] - p1[2]) < 0 then nx, nz = -nx, -nz end
    return { nx, nz, nx * p1[1] + nz * p1[2] }
  end
  grid.clipAll = function(poly, planes)
    for _, pl in ipairs(planes) do
      local out, m = {}, #poly
      for i = 1, m do
        local P, Q = poly[i], poly[i % m + 1]
        local dp = pl[1] * P[1][1] + pl[2] * P[1][3] - pl[3]
        local dq = pl[1] * Q[1][1] + pl[2] * Q[1][3] - pl[3]
        if dp >= 0 then out[#out + 1] = P end
        if (dp >= 0) ~= (dq >= 0) then
          local t = dp / (dp - dq)
          local v = {}
          for j = 1, #P do
            local a, b = P[j], Q[j]
            local r = {}
            for jj = 1, #a do r[jj] = a[jj] + (b[jj] - a[jj]) * t end
            v[j] = r
          end
          if v[3] then v[3] = norm3(v[3]) end
          out[#out + 1] = v
        end
      end
      poly = out
      if #poly < 3 then return poly end
    end
    return poly
  end
  -- one triangle { p, t, n } x3 clipped to the half-planes, fanned (same
  -- winding); returns the triangle count
  grid.clipTri = function(list, planes, p1, t1, n1, p2, t2, n2, p3, t3, n3)
    local poly = grid.clipAll({ { p1, t1, n1 }, { p2, t2, n2 }, { p3, t3, n3 } }, planes)
    if #poly < 3 then return 0 end
    for i = 2, #poly - 1 do
      tri3(list, poly[1][1], poly[1][2], poly[1][3], poly[i][1], poly[i][2], poly[i][3], poly[i + 1][1], poly[i + 1][2], poly[i + 1][3])
    end
    return #poly - 2
  end
  -- a convex polygon { { p, t }, ... } with one normal, clipped, fanned
  grid.clipFan = function(list, pts, n, planes)
    local poly = grid.clipAll(pts, planes)
    if #poly >= 3 then fanN(list, poly, n) end
  end
  -- the hip's corner cut: H on the hip line where a CORNER FACE through
  -- A and B (at the eave) meets it, pitched between the front slope and the
  -- end (the geometric mean, at least 1.25x the hip line's own rise across
  -- the cut); the front slope keeps the side of A-H away from the corner,
  -- the end the side of B-H
  grid.foldHipCut = function(cut, L0, L1, S0, S1, ridgeA, ridgeB, shortMid, wy, rise)
    local hc = { front = {}, faces = {} }
    for _, key in ipairs({ "L", "R" }) do
      local ct = cut[key]
      if ct then
        local Lc, Lr = key == "L" and L0 or L1, key == "L" and ridgeA or ridgeB
        local e, half = math.abs(Lr - Lc), math.abs(S1 - shortMid)
        local ix, iz = -ct.m[1], -ct.m[2]
        local A, B = ct.A, ct.B
        local D0 = ix * (Lc - A[1]) + iz * (S1 - A[2])
        local Dv = ix * (Lr - Lc) + iz * (shortMid - S1)
        if D0 < 0 and Dv > 1e-6 and e > 1e-6 and half > 1e-6 then
          local pc = math.max(math.sqrt((rise / half) * (rise / e)), 1.25 * rise / Dv)
          local t = pc * D0 / (rise - pc * Dv)
          if t > 0.01 and t < 0.95 then
            local H = { Lc + (Lr - Lc) * t, wy + rise * t, S1 + (shortMid - S1) * t }
            hc.front[#hc.front + 1] = grid.halfPlane(A, { H[1], H[3] }, { (ridgeA + ridgeB) / 2, shortMid })
            hc[key == "L" and "endL" or "endR"] = { grid.halfPlane(B, { H[1], H[3] }, { Lc, S0 }) }
            hc.faces[#hc.faces + 1] = { A = { A[1], wy, A[2] }, H = H, B = { B[1], wy, B[2] }, key = key }
          end
        end
      end
    end
    if #hc.front == 0 then hc.front = nil end
    return hc
  end
  -- a triangle of roof art: P3 = 3 world points, X3 = their art points
  -- (map units); split at the art's cells, each piece in its cell's layers
  -- (as roofArtFace)
  grid.artTri = function(comp, P3, X3, n)
    local xmin, xmax = math.min(X3[1][1], X3[2][1], X3[3][1]), math.max(X3[1][1], X3[2][1], X3[3][1])
    local ymin, ymax = math.min(X3[1][2], X3[2][2], X3[3][2]), math.max(X3[1][2], X3[2][2], X3[3][2])
    for cy = math.floor(ymin), math.ceil(ymax) - 1 do
      for cx = math.floor(xmin), math.ceil(xmax) - 1 do
        -- (art-space polygon; x, y, then the three barycentric weights)
        local poly = { { X3[1][1], X3[1][2], 1, 0, 0 }, { X3[2][1], X3[2][2], 0, 1, 0 }, { X3[3][1], X3[3][2], 0, 0, 1 } }
        for _, lim in ipairs({ { 1, cx, 1 }, { 1, cx + 1, -1 }, { 2, cy, 1 }, { 2, cy + 1, -1 } }) do
          local out, m = {}, #poly
          for i = 1, m do
            local P, Q = poly[i], poly[i % m + 1]
            local dp, dq = (P[lim[1]] - lim[2]) * lim[3], (Q[lim[1]] - lim[2]) * lim[3]
            if dp >= 0 then out[#out + 1] = P end
            if (dp >= 0) ~= (dq >= 0) then
              local t = dp / (dp - dq)
              local v = {}
              for j = 1, 5 do v[j] = P[j] + (Q[j] - P[j]) * t end
              out[#out + 1] = v
            end
          end
          poly = out
          if #poly < 3 then break end
        end
        local c = at(cx, cy)
        if #poly >= 3 and c and (isCompCell(c, comp) or c.overhangOf == comp) then
          local ov = c.hasOver and overRect(c.mid) or nil
          local layers = {}
          if ov and (overCoverage(c.mid) or 0) >= C.ROOF_SOLID_MIN then
            layers[1] = { cutoutOver, ov, 0 }
          else
            local ur = underRect(c.mid)
            if ur then layers[#layers + 1] = { opaque, ur, 0 } end
            if ov then layers[#layers + 1] = { cutoutOver, ov, C.ROOF_OVER_LIFT } end
          end
          for _, ly in ipairs(layers) do
            local r, lift = ly[2], ly[3]
            local pts = {}
            for i, q in ipairs(poly) do
              local w1, w2, w3 = q[3], q[4], q[5]
              pts[i] = { { w1 * P3[1][1] + w2 * P3[2][1] + w3 * P3[3][1], w1 * P3[1][2] + w2 * P3[2][2] + w3 * P3[3][2] + lift,
                w1 * P3[1][3] + w2 * P3[2][3] + w3 * P3[3][3] },
                { r[1] + (q[1] - cx) * (r[3] - r[1]), r[2] + (q[2] - cy) * (r[4] - r[2]) } }
            end
            fanN(ly[1], pts, n)
          end
        end
      end
    end
  end
  -- the corner faces: the roof art where the front slope's own mapping,
  -- carried past its hip line, puts them (the art's rounded corner)
  grid.foldCornerFaces = function(hc, artMap, L0, L1, S1, ridgeA, ridgeB, shortMid)
    for _, f in ipairs(hc.faces) do
      local P3 = { f.A, f.H, f.B }
      local X3 = {}
      for i, p in ipairs(P3) do
        local ty = (p[3] - shortMid) / (S1 - shortMid)
        local xl, xr = ridgeA + (L0 - ridgeA) * ty, ridgeB + (L1 - ridgeB) * ty
        local txx = (p[1] - xl) / (xr - xl)
        X3[i] = { artMap.X0 + txx * (artMap.X1 - artMap.X0), artMap.Y0 + ty * (artMap.Y1 - artMap.Y0) }
      end
      local nrm = faceNormal3(f.A, f.H, f.B)
      if nrm[2] < 0 then nrm = { -nrm[1], -nrm[2], -nrm[3] } end
      grid.artTri(artMap.comp, P3, X3, nrm)
    end
  end
  -- PC / Mart back corners (USER, image 27_mart_roof_back_corners: "the roof
  -- texture is slightly off" at the BACK corners). The hip put the art
  -- rectangle bilinearly onto trapezoids (the grid columns converged toward
  -- the short ridge: bent, sheared cells at the back corners), mirrored the
  -- whole art onto the back slope (a second copy, folded at the ridge) and
  -- backed the overhang row's OVER with its terrain UNDER, lifted: grass
  -- showed along the ridge, the hip lines and the art's transparent rounded
  -- corners. The art draws ONE flat panel (back outline, grid, the light /
  -- dark side strips) ending in the band: on an OV-1 roof (the eave arc
  -- starts level, a0 = 0) the panel is one level surface at the arc's top,
  -- inside the arc's inner outline (the folded front corners cut it).
  -- Across 1:1 (art x = world x); rows back -> front evenly over the depth
  -- from the art's first drawn row (fully transparent OVER rows above it are
  -- not roof: the 5-row PCs' top row) to the front band's first row.
  -- Returns roofAt.
  grid.martpcFlatRoof = function(comp, A, y, ix0, ix1, iz0, iz1)
    local clip
    if A.cut then
      clip = {}
      for _, key in ipairs({ "L", "R" }) do
        local ct = A.cut[key]
        if ct then clip[#clip + 1] = grid.halfPlane(ct.A, ct.B, { (ix0 + ix1) / 2, (iz0 + iz1) / 2 }) end
      end
      if comp.centerPaint and A.cut.rear then for _,key in ipairs({"L","R"})do local ct=A.cut.rear[key];if ct then clip[#clip+1]=grid.halfPlane(ct.A,ct.B,{(ix0+ix1)/2,(iz0+iz1)/2})end end end
      if #clip == 0 then clip = nil end
    end
    local Yt, Ye = math.floor(A.Y0 * 16 + 0.5), math.floor(A.Y1 * 16 + 0.5)
    if type(atlas.texels) == "function" then
      while Yt < Ye - 1 do
        local yy, ty, clear = math.floor(Yt / 16), Yt % 16, true
        for x = comp.minX + 1, comp.maxX - 1 do
          local c = at(x, yy)
          local o = c and c.hasOver and atlas.texels(c.mid, "over")
          if not o then clear = false break end
          for tx = 0, 15 do if o[ty * 16 + tx + 1] >= 0 then clear = false break end end
          if not clear then break end
        end
        if not clear then break end
        Yt = Yt + 1
      end
    end
    local Y0 = Yt / 16
    comp.martpcFlat = { y = y, Y0 = Y0, Y1 = A.Y1, z0 = iz0, z1 = iz1, clip = clip, uv = comp.ov1.soffit }
    roofArtFace(comp, { ix0, Y0, ix1, A.Y1 }, { ix0, y, iz0 }, { ix1, y, iz0 }, { ix1, y, iz1 }, { ix0, y, iz1 }, UP, A.covered, nil, clip)
    comp.martpcFlat = nil
    return function() return y end
  end
  -- one piece of the panel in a cell with OVER, emitted here, all at the
  -- panel itself (no lift: no lifted edge to see through) as texel-exact
  -- runs per texel row: the OVER's opaque texels and, in its transparent
  -- texels (the art's rounded back corners) over terrain UNDER (the
  -- walkable overhang row, the ground palette, or any colour the roof's art
  -- never uses), the eave's own colour (ov1.soffit) -- side by side in one
  -- plane, never the terrain. Returns {} (no default layers); nil keeps the
  -- default layers (a transparent texel over real roof UNDER).
  grid.martpcLayers = function(comp, c, ov, px0, px1, py0, py1, cx, cy, flip)
    local F = comp.martpcFlat
    local o = type(atlas.texels) == "function" and atlas.texels(c.mid, "over")
    if not o or not F.uv then return nil end
    local u = atlas.texels(c.mid, "under")
    if F.gpal == nil then
      local _, gp = groundTaint(comp.minX, comp.minY, comp.maxX, comp.maxY)
      F.gpal = gp or false
      -- (the roof's own colours: every opaque OVER texel, and the UNDER of
      -- cells without OVER, over the panel's rows -- an UNDER colour outside
      -- them is terrain, even where no walkable ground of it lies near)
      F.roofPal = {}
      for yy = math.floor(F.Y0), math.floor(F.Y1 - 1e-9) do
        for xx = comp.minX, comp.maxX do
          local q = at(xx, yy)
          local qo = q and q.hasOver and atlas.texels(q.mid, "over")
          local qu = q and not qo and atlas.texels(q.mid, "under")
          for i = 1, 256 do
            if qo and qo[i] >= 0 then F.roofPal[qo[i]] = true end
            if qu and qu[i] >= 0 then F.roofPal[qu[i]] = true end
          end
        end
      end
    end
    local tx0, tx1 = math.max(0, math.floor((px0 - cx) * 16 + 1e-6)), math.min(15, math.ceil((px1 - cx) * 16 - 1e-6) - 1)
    local ty0, ty1 = math.max(0, math.floor((py0 - cy) * 16 + 1e-6)), math.min(15, math.ceil((py1 - cy) * 16 - 1e-6) - 1)
    -- per texel row: its runs { first, last + 1, hole } and their signature
    local rows = {}
    for ty = ty0, ty1 do
      local runs, sig = {}, {}
      for tx = tx0, tx1 do
        local i = ty * 16 + (flip and 15 - tx or tx) + 1
