    local out = { src = f.src, bands = {}, flat = {} }
    for bi = 1, f.nb do if f.bands[bi] then out.bands[#out.bands + 1] = bi end end
    for _, key in ipairs({ "L", "R" }) do
      local s, fl = f[key], f.flat[key]
