  grid.ov1Profile = function(comp)
    if comp._ov1Profile~=nil then return comp._ov1Profile or nil end
    comp._ov1Profile=false
    if C.FOLD_25D==false or type(atlas.texels) ~= "function" then return end
    local width, depth = comp.maxX-comp.minX+1, comp.maxY-comp.minY+1
    local b0,b1,R,color,kind,offset
    if width==5 and (depth==4 or depth==5) then b0,b1,R,color,kind,offset=29,36,62,0xad2129,"K01",(depth-4)*16
