  grid.ov1Setup = function(comp)
    if not comp.chamfer or not comp.fold then return end
    local ov=grid.ov1Profile(comp)
    if not ov then return end
    local width=comp.maxX-comp.minX+1
    local b0,b1,offset,color,kind=ov.b0,ov.b1,ov.artOffset,ov.kind=="K01" and 0xad2129 or 0x3163a5,ov.kind
