        {0,32},{0,32},{0,32},{0,32},{0,32},{0,32},{1,31},{9,23},{10,22},{11,21},{12,20}}
      ov.logoProjectionSpans={}
      for i,span in ipairs(ov.logoSpans) do ov.logoProjectionSpans[i]=span end
      -- Two cast-shadow pixels on the fascia belong to the old flat logo,
      -- not its solid silhouette: source row28, columns24 and39.
      ov.logoProjectionSpans[15]={8,24}
      for i,span in ipairs(ov.logoSpans) do
        for x=16+span[1],16+span[2]-1 do ov.fw[x]=math.max(ov.fw[x],i+14+offset) end
      end
    end
    for yy=comp.minY,comp.maxY do for xx=comp.minX,comp.maxX do
      local c=at(xx,yy)
      if c then for _,layer in ipairs({"under","over"}) do
        local uv=layer=="under" and underRect(c.mid) or c.hasOver and overRect(c.mid)
        local tex=uv and atlas.texels(c.mid,layer)
        if uv and tex then
          ov.sources[#ov.sources+1]={uv=uv,x=(xx-comp.minX)*16,y=(yy-comp.minY)*16,over=layer=="over"}
          for i=1,256 do
            local v=tex[i]
            local artY=(yy-comp.minY)*16+math.floor((i-1)/16)
            if (v==0x7b7b84 and layer=="under" and artY>b1 and not ov.hidden)
                or (v==color and layer=="under" and artY>=b0 and artY<=b1 and not ov.soffit) then
              local px,py=(i-1)%16,math.floor((i-1)/16)
              local t=subRect(uv,(px+.5)/16,(py+.5)/16,(px+.5)/16,(py+.5)/16)
