      -- Source x27..28/y25..26 is a proven 2x2 UNDER-blue patch; sampling
      -- its centre keeps all four bilinear contributors the same color.
      local c=at(comp.minX+1,comp.minY+math.floor((b0+4)/16))
      local uv=c and underRect(c.mid)
      local tex=c and atlas.texels(c.mid,"under")
      if not uv or not tex then return end
