      wallQuad(opaque,xb,zb,xa,zb,yb,yt,comp.ov1.hidden,N_N)
      wallQuad(opaque,xa,zb,xa,zf,yb,yt,subRect(art,(a+.5)/16,(ty+.5)/16,(a+.5)/16,(ty+.5)/16),N_W)
      wallQuad(opaque,xb,zf,xb,zb,yb,yt,subRect(art,(b-.5)/16,(ty+.5)/16,(b-.5)/16,(ty+.5)/16),N_E)
