          local lo=py==2 and first or(sh.left and first or last-1)
          local hi=py==2 and last or(sh.left and first+1 or last)
          hQuad(opaque,sh.cell+lo/16,z0,sh.cell+hi/16,front,y1,subRect(uv,(lo+.5)/16,(py+.5)/16,(hi-.5)/16,(py+.5)/16),UP)
        end
      end
    end
  end
  grid.ov1FinishWalls = function(comp)
    local ov=comp.ov1
    if not ov then return end
    -- Shared native Mart entrance. Match the K02 layout and source art,
    -- rather than a city name, atlas size, or absolute terrain elevation.
    -- Keep the square post upright; the sign half still follows the fascia.
    local squareMartPost=false
    if ov.kind=="K02" and not input.isBorder and C.WALL_ROW_UNIT==1
      and C.FACADE_OVER_LIFT==.004 and comp.maxX-comp.minX==3
      and (comp.maxY-comp.minY==2 or comp.maxY-comp.minY==3) then
      local sign,door,right=at(comp.minX+1,comp.maxY),at(comp.minX+2,comp.maxY),at(comp.minX+3,comp.maxY)
      local left=at(comp.minX,comp.maxY)
      local nativeRows=true
      for ry,row in ipairs({{48,49,50,51},{56,57,58,59}}) do
        for rx,mid in ipairs(row) do
          local c=at(comp.minX+rx-1,comp.maxY-3+ry)
          nativeRows=nativeRows and c and c.mid==mid
        end
      end
      -- Saffron's attached facade has native outer returns in place of the
      -- freestanding corner tiles. Its sign, post, door and roof are shared.
      local nativeCorners=left and right and
        ((left.mid==64 and right.mid==99) or (left.mid==758 and right.mid==759))
      local t=sign and sign.mid==65 and atlas.texels(65,"under")
      if t and door and door.mid==98 and door.doorOf==comp and nativeRows and nativeCorners
        and atlas.texels(65,"over")==nil then
        local h=0
        for i=1,256 do local v=t[i]
          if type(v)~="number" or v~=v or v<0 or v>0xffffff or v%1~=0 then h=-1;break end
          h=(h*31+v+2)%2147483647
        end
        squareMartPost=h==1488463074 and underRect(65)~=nil
      end
    end
    local postRect=squareMartPost and underRect(65)
    local squareMartDoor=false
    if squareMartPost and atlas.texels(98,"over")==nil then
      local t=atlas.texels(98,"under")
      if t then
        local h=0
        for i=1,256 do local v=t[i]
          if type(v)~="number" or v~=v or v<0 or v>0xffffff or v%1~=0 then h=-1;break end
          h=(h*31+v+2)%2147483647
        end
        squareMartDoor=h==922411429 and underRect(98)~=nil
      end
    end
    local doorRect=squareMartDoor and underRect(98)
    -- K02's old logo silhouette was being used as a solid gray front wall.
    -- The closed wall remains, but only its actual one-texel roof trim stays
    -- gray. Continue the native MID65 pale wall material below that trim.
    local martWall=squareMartDoor and postRect and atlas.texels(65,"under")
      and atlas.texels(65,"under")[3*16+12+1]==0xcedeef
      and subRect(postRect,12.5/16,3.5/16,12.5/16,3.5/16)
    local function clip(poly,k,a,sign)
      local out={}
      for i,p in ipairs(poly) do
        local q=poly[i%#poly+1];local dp,dq=(p[k]-a)*sign,(q[k]-a)*sign
        if dp>=-1e-10 then out[#out+1]=p end
        if (dp>=0)~=(dq>=0) then
          local t=dp/(dp-dq);local v={}
          for j=1,8 do v[j]=p[j]+(q[j]-p[j])*t end
          out[#out+1]=v
        end
      end
      return out
    end
    local function emitPiece(list,poly,hidden,paint)
      if #poly<3 then return end
      for i=2,#poly-1 do
       local a,b,c=poly[1],poly[i],poly[i+1]
       local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
       local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
       local nx,ny,nz=uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx
       if nx*nx+ny*ny+nz*nz>1e-20 then for _,p in ipairs({a,b,c}) do
        local v={};for j=1,8 do v[j]=p[j] end
        if v[2]>comp.groundY then v[2]=math.max(comp.groundY,v[2]-1/16) end
        if paint then v[4],v[5]=paint[1],paint[2]
        elseif hidden then v[4],v[5]=ov.hidden[1],ov.hidden[2] end
        list[#list+1]=v
       end end
      end
    end
    local function emit(list,poly,hidden)
      local front=martWall and hidden and list==opaque
      if front then
        for _,p in ipairs(poly) do
          local dz=p[3]-(comp.maxY+1)
          front=front and (math.abs(dz)<1e-8 or math.abs(dz-C.FACADE_OVER_LIFT)<1e-8) and p[8]>.99
        end
      end
      if not front then return emitPiece(list,poly,hidden) end
      -- The wall's upper edge is output Y=ground+22/16; keep its final
      -- 1/16 course as gray trim. emitPiece applies the inherited 1/16
      -- vertical lowering, so the source split is at ground+22/16.
      local seam=comp.groundY+22/16
      emitPiece(list,clip(poly,2,seam,-1),hidden,martWall)
      emitPiece(list,clip(poly,2,seam,1),hidden)
    end
    local function keepClipped(list,poly)
      if #poly<3 then return end
      for j=2,#poly-1 do
        local a,b,c=poly[1],poly[j],poly[j+1]
        local ux,uy=b[1]-a[1],b[2]-a[2]
        local vx,vy=c[1]-a[1],c[2]-a[2]
        if math.abs(ux*vy-uy*vx)>1e-12 then
          for _,p in ipairs({a,b,c})do list[#list+1]=p end
        end
      end
    end
    local postTouched=false
    for _,entry in ipairs({{opaque,ov.startO,false},{cutoutOver,ov.startC,true}}) do
      local list,start,over=entry[1],entry[2],entry[3];local old={}
      for i=start+1,#list do old[#old+1]=list[i] end
      for i=#list,start+1,-1 do list[i]=nil end
      for i=1,#old,3 do
        local poly={old[i],old[i+1],old[i+2]}
        local emblem=ov.emblem and ov.emblem[over and 2 or 1]
        local index=start+i
        local firstNew=#list
        local nativePost=squareMartPost and not over and postRect~=nil
        if nativePost then
          for _,p in ipairs(poly)do
            nativePost=nativePost and p[1]>=comp.minX+1-1e-8 and p[1]<=comp.minX+2+1e-8
              and p[2]>=comp.groundY-1e-8 and p[2]<=comp.groundY+1+1e-8
              and math.abs(p[3]-(comp.maxY+1))<1e-8 and p[8]>.99
              and p[4]>=postRect[1]-1e-8 and p[4]<=postRect[3]+1e-8
              and p[5]>=postRect[2]-1e-8 and p[5]<=postRect[4]+1e-8
          end
        end
        local nativeDoor=false
        if ov.kind=="K01" and not over then
          local door=at(comp.minX+2,comp.maxY)
          local r=door and door.mid==98 and door.doorOf==comp and underRect(door.mid)
          if r and not comp.centerPaint then
            local t=atlas.texels(98,"under");local h=17
            for j=1,256 do h=(h*131+(t and t[j] or -1)+1)%2147483647 end
            if h~=280254180 then r=nil end
            t=atlas.texels(98,"over");h=17
            for j=1,256 do h=(h*131+(t and t[j] or -1)+1)%2147483647 end
            if h~=1384987556 then r=nil end
          end
          if r then
            nativeDoor=true
            for _,p in ipairs(poly)do
              nativeDoor=nativeDoor and p[1]>=comp.minX+2-1e-8 and p[1]<=comp.minX+3+1e-8
                and math.abs(p[3]-(comp.maxY+1-C.DOOR_INSET))<1e-8 and p[8]>.99
                and p[4]>=r[1]-1e-8 and p[4]<=r[3]+1e-8 and p[5]>=r[2]-1e-8 and p[5]<=r[4]+1e-8
            end
          end
        end
        if squareMartDoor and not over and doorRect then
          nativeDoor=true
          for _,p in ipairs(poly)do
            nativeDoor=nativeDoor and p[1]>=comp.minX+2-1e-8 and p[1]<=comp.minX+3+1e-8
              and p[2]>=comp.groundY-1e-8 and p[2]<=comp.groundY+1+1e-8
              and math.abs(p[3]-(comp.maxY+1-C.DOOR_INSET))<1e-8 and p[8]>.99
              and p[4]>=doorRect[1]-1e-8 and p[4]<=doorRect[3]+1e-8
              and p[5]>=doorRect[2]-1e-8 and p[5]<=doorRect[4]+1e-8
          end
        end
        if emblem and index>emblem[1] and index<=emblem[2] then
          for _,v in ipairs(poly) do list[#list+1]=v end
        elseif nativeDoor then
          -- The guarded native door is a recessed wall, not rooftop paint.
          -- Keep its complete art; the roof silhouette must not recolor it.
          emit(list,poly,false)
        else
          poly=clip(poly,2,comp.groundY+ov.Hs+1/16,-1)
          if #poly>=3 then
            local u,v=0,0;for _,p in ipairs(poly) do u=u+p[4]/#poly;v=v+p[5]/#poly end
            local src
            for _,s in ipairs(ov.sources) do local r=s.uv
              if s.over==over and u>=r[1]-1e-8 and u<=r[3]+1e-8 and v>=r[2]-1e-8 and v<=r[4]+1e-8 then
                if not src or s.y>src.y then src=s end
              end
            end
            if not src then emit(list,poly,false) else
              local r=src.uv
              -- Split only where the per-column boundary changes. Constant
              -- source columns (native side patterns) are handled once.
              local lo,hi=16,0
              for _,p in ipairs(poly) do local x=(p[4]-r[1])/(r[3]-r[1])*16;lo=math.min(lo,x);hi=math.max(hi,x) end
              local x0,x1=math.max(0,math.floor(lo+1e-7)),math.min(15,math.floor(hi-1e-7))
              if x1<x0 then x1=x0 end
              local x=x0
              while x<=x1 do
                local xe=x;local fw=ov.fw[src.x+x] or ov.b1+1
                while xe<x1 and ov.fw[src.x+xe+1]==fw do xe=xe+1 end
                local part=poly
                if x>x0 then part=clip(part,4,r[1]+(r[3]-r[1])*x/16,1) end
                if xe<x1 then part=clip(part,4,r[1]+(r[3]-r[1])*(xe+1)/16,-1) end
                local vy=r[2]+(r[4]-r[2])*(fw-src.y)/16
                emit(list,clip(part,5,vy,1),false)
                emit(over and opaque or list,clip(part,5,vy,-1),true)
                x=xe+1
              end
            end
          end
        end
        if nativePost then
          postTouched=true
          local emitted={};for k=firstNew+1,#list do emitted[#emitted+1]=list[k]end
          for k=#list,firstNew+1,-1 do list[k]=nil end
          local split=comp.minX+1.5
          for k=1,#emitted,3 do
            local a,b,c=emitted[k],emitted[k+1],emitted[k+2]
            if math.max(a[1],b[1],c[1])<=split+1e-8 then
              list[#list+1]=a;list[#list+1]=b;list[#list+1]=c
            else keepClipped(list,clip({a,b,c},1,split,-1)) end
          end
        end
      end
    end
    if postTouched then
      local x=comp.minX+1.5;local z=comp.maxY+1
      wallQuad(opaque,x,z,x+.5,z,comp.groundY,comp.groundY+15/16,
        subRect(postRect,.5,0,1,1),N_S)
    end
  end

  -- (gym flat, Claude 2026-10-01) the gym marked by grid.gymRule, built from
  -- its art in 2.5D; replaces the generic walls, porch boxes, door box, hip
  -- roof, eave and fascia this building got in this pass (the lists are cut
  -- back to comp.gymMark). Heights in texels above the ground (SPEC_OVERHANGS
  -- 2.1, K03: R 54, fw 32, front eave 4): the wall art 0-23 (row = 23 - h:
  -- C rows 0-15, P rows 0-6), a hidden strip in the band's 7b7b84 up to the
  -- soffit HS = 27 (one level soffit all round), the band on the eave's edge
  -- 27-33 (row = 27 - h: B rows 15-10), the FLAT top at HT = 33 and the side
  -- strips' SLOPES (down 0.5 per column over the outer 6 columns: 30 at the
  -- side walls, 29 at a 2-texel side eave). The eave rectangle is the one the
  -- overhangs work gave the gyms (4 texels front, 2 sides, the back's M13
  -- push; none into a touching building). ONE roof surface: per texel column
  -- the art from its back outline (T row OVER) to the band's top row runs
  -- back -> front over the top (past a side wall the edge column is
  -- clamped). The front wall shows the art 1:1 (no roof or band row on it);
  -- side / back walls and the corner's small angled bevel (45 degrees, 6
  -- texels: C.FOLD_POSTS) show the post's un-skewed column (column 5 / 10,
  -- one row up), the hidden strip above. The ENTRANCE (SPEC 2.5 D8, 8 texels
  -- deep): the door on the wall in the door cell's column at ground level
  -- (P rows 0-14, row = 31 - h, as the art's entrance front), the two jamb
  -- posts on the blocked porch cells (h 0-20), over the door cell the canopy
  -- -- the emblem panel, C rows 6-14 (row = 35 - h) -- from h 20 (1.25 cells:
  -- OV13 >= 1.2 over the door cell) to HC 29, with only the ball of C
  -- rows 0-5 standing above it as a cut-out (canopy cut-out); its top and its
  -- underside the hidden grey. The soffit, the canopy's sides above the
  -- soffit and the band stop at each other: one closed solid. Beside a
  -- touching building only what that building leaves open is drawn (its
  -- cover, as grid.heightStep), plus the strip between the slope's edge and
  -- the height that building expects this gym to cover (its wall stops at
  -- this gym's wallTopY, unchanged). Returns roofMode and the eave rectangle.
  grid.gymBuild=function(comp,faces,ex0,ex1,ez0,ez1,wins)
    local G,mk=comp.gymFlat,comp.gymMark
    for li,list in ipairs({opaque,cutoutUnder,cutoutOver,cutoutKeyed}) do
      for i=#list,mk[li]+1,-1 do list[i]=nil end
    end
    for i=#grid.ov1Deferred,mk[5]+1,-1 do grid.ov1Deferred[i]=nil end
    local gy,tv=comp.groundY,C.WALL_ROW_UNIT/16
    local x0,x1,z0,z1=comp.minX,comp.maxX+1,comp.minY,comp.maxY+1
    local cy,py,T,xd=comp.maxY,comp.maxY+1,G.T,G.xd
    local W=(x1-x0)*16
    local dL,dR=(x0-ex0)*16,(ex1-x1)*16
    local zB,zF=ez0,ez1
    local U=(xd-x0)*16
    local v0,v1=U-7,U+23
    local zV=z1+0.5
    local HS,HT,D,HC=27,33,6/16,29 -- ((canopy cut-out) HC: the canopy's flat top, at the panel's mid lines)
    local function hT(u) return HT-0.5*math.max(0,6-u,u-(W-6)) end
    local AW,AH=atlas.w,atlas.h
    local exact=type(AW)=="number" and AW>0 and type(AH)=="number" and AH>0
    local function own(c)
      if c and c.y==T then return G.tOwn[c]==true end
      return c~=nil and c.x>=comp.minX and c.x<=comp.maxX and c.y>T and c.y<=py
        and (isCompCell(c,comp) or c.y==py)
    end
    local function overSolid(c,tx0,tx1,ty0,ty1)
      local o=atlas.texels(c.mid,"over")
      if not o then return false end
      for ty=math.max(0,ty0),math.min(15,ty1) do for tx=math.max(0,tx0),math.min(15,tx1) do
        local v=o[ty*16+tx+1]
        if type(v)~="number" or v<0 then return false end
      end end
      return true
    end
    -- one planar convex face { {x,y,z,X,Y}, ... } (X, Y: art in map units,
    -- affine on the face), split at the art's cell lines (as grid.flatTopRoof)
    local function face(pts,n)
      local polys={pts}
      for k=4,5 do
        local lo,hi=math.huge,-math.huge
        for _,p in ipairs(pts) do lo,hi=math.min(lo,p[k]),math.max(hi,p[k]) end
        for cut=math.floor(lo)+1,math.ceil(hi)-1 do
          local out={}
          for _,poly in ipairs(polys) do
            for _,s in ipairs({1,-1}) do
              local q={}
              for i=1,#poly do
                local A,B=poly[i],poly[i%#poly+1]
                local da,db=s*(A[k]-cut),s*(B[k]-cut)
                if da>=0 then q[#q+1]=A end
                if da*db<0 then
                  local t,v=da/(da-db),{}
                  for j=1,5 do v[j]=A[j]+(B[j]-A[j])*t end
                  v[k]=cut
                  q[#q+1]=v
                end
              end
              if #q>=3 then out[#out+1]=q end
            end
          end
          polys=out
        end
      end
      for _,poly in ipairs(polys) do
        local q={}
        for _,p in ipairs(poly) do
          local l=q[#q]
          if not l or math.abs(l[1]-p[1])+math.abs(l[2]-p[2])+math.abs(l[3]-p[3])>1e-9 then q[#q+1]=p end
        end
        if #q>1 and math.abs(q[1][1]-q[#q][1])+math.abs(q[1][2]-q[#q][2])+math.abs(q[1][3]-q[#q][3])<=1e-9 then q[#q]=nil end
        local ar,mx,my={0,0,0},0,0
        for i=1,#q do
          local c3=cross3(sub3(q[i],q[1]),sub3(q[i%#q+1],q[1]))
          ar={ar[1]+c3[1],ar[2]+c3[2],ar[3]+c3[3]}
          mx,my=mx+q[i][4],my+q[i][5]
        end
        local cx,cz=math.floor(mx/#q),math.floor(my/#q)
        local c=at(cx,cz)
        if #q>=3 and dot3(ar,ar)>1e-16 and own(c) then
          local t0,t1,s0,s1=16,-1,16,-1
          for _,p in ipairs(q) do
            local tx,ty=(p[4]-cx)*16,(p[5]-cz)*16
            t0,t1=math.min(t0,math.floor(tx+1e-6)),math.max(t1,math.ceil(tx-1e-6)-1)
            s0,s1=math.min(s0,math.floor(ty+1e-6)),math.max(s1,math.ceil(ty-1e-6)-1)
          end
          local layers={}
          if c.hasOver and ((c.y==T and not isCompCell(c,comp)) or overSolid(c,t0,t1,s0,s1)) then
            layers[1]={cutoutOver,overRect(c.mid),0}
          else
            layers[1]={opaque,underRect(c.mid),0}
            if c.hasOver then layers[2]={cutoutOver,overRect(c.mid),C.FACADE_OVER_LIFT} end
          end
          for _,ly in ipairs(layers) do
            local r=ly[2]
            if r then
              local au,av=exact and (16-(r[3]-r[1])*AW)/2,exact and (16-(r[4]-r[2])*AH)/2
              local f={}
              for i,p in ipairs(q) do
                local tx,ty=(p[4]-cx)*16,(p[5]-cz)*16
                f[i]={{p[1]+n[1]*ly[3],p[2]+n[2]*ly[3],p[3]+n[3]*ly[3]},exact and {r[1]+(math.max(au,math.min(16-au,tx))-au)/AW,r[2]+(math.max(av,math.min(16-av,ty))-av)/AH}
                  or {r[1]+tx/16*(r[3]-r[1]),r[2]+ty/16*(r[4]-r[2])}}
              end
              fanN(ly[1],f,n)
            end
          end
        end
      end
    end
    -- one texel of a cell as a plain colour { list, uv, v = colour }
    local function texel(c,tx,ty,layer)
      local over=layer=="over"
      local r=c and (over and overRect(c.mid) or underRect(c.mid))
      if not r then return nil end
      local u,v=r[1]+(r[3]-r[1])*(tx+0.5)/16,r[2]+(r[4]-r[2])*(ty+0.5)/16
      return {over and cutoutOver or opaque,{u,v}}
    end
    local function vis(c,tx,ty)
      if not c then return nil end
      local i=ty*16+tx+1
      local o=c.hasOver and atlas.texels(c.mid,"over")
      if o and type(o[i])=="number" and o[i]>=0 then return o[i],"over" end
      local u=atlas.texels(c.mid,"under")
      local v=u and u[i]
      if type(v)=="number" and v>=0 then return v,"under" end
      return nil
    end
    -- the plain grey 7b7b84: on walls a facade-row texel (the entrance's top
    -- row), on the soffit and the canopy's top / underside a band texel
    local HID=texel(G.hid[1],G.hid[3],G.hid[4],G.hid[2])
    local HIDB=texel(at(comp.minX+1,cy-1),8,11,G.bandL)
    HID.v,HIDB.v=0x7b7b84,0x7b7b84
    -- Viridian's entrance return used the outer gray silhouette texel all the
    -- way through its depth. The native post interiors have the actual pale
    -- face and red two-row stripe. Admit only the exact immutable art/context.
    local function viridianPostArt()
      if input.mapId~='FR_VIRIDIAN_CITY' or input.pair~='viridian_outdoor' or input.isBorder
        or input.width~=48 or input.height~=40 or atlas.w~=256 or atlas.h~=320
        or comp.minX~=33 or comp.maxX~=38 or comp.minY~=7 or comp.maxY~=9
        or comp.groundY~=.75 or comp.wallTopY~=2.75 or G.xd~=36 or T~=6
        or C.WALL_ROW_UNIT~=1 then return false end
      for _,s in ipairs{{32,9,352},{35,9,338},{37,9,340},{35,10,346},{36,10,347},{37,10,348}} do
        local c=at(s[1],s[2]);if not c or c.mid~=s[3] then return false end
      end
      local art={
        {338,1470629889,{.8751220703125,.45009765625,.9373779296875,.49990234375}},
        {340,73303032,{.0001220703125,.50009765625,.0623779296875,.54990234375}},
        {346,1073801389,{.2501220703125,.50009765625,.3123779296875,.54990234375}},
        {348,719161017,{.3751220703125,.50009765625,.4373779296875,.54990234375}},
      }
      for _,s in ipairs(art) do
        local t=atlas.texels(s[1],'under');if type(t)~='table' or atlas.texels(s[1],'over')~=nil then return false end
        local h=0;for i=1,256 do local v=t[i]
          if type(v)~='number' or v~=v or (v~=-1 and (v<0 or v>0xffffff or v%1~=0)) then return false end
          h=(h*31+(v>=0 and v+2 or 1))%2147483647
        end
        if h~=s[2] then return false end
        local r=underRect(s[1]);if type(r)~='table' or #r~=4 then return false end
        for i=1,4 do if r[i]~=s[3][i] then return false end end
      end
      -- The adjacent native source tile's OVER layer contains a pale, solid
      -- texel. Keep the original cutoutOver list/geometry for the hidden
      -- five-pixel connector; only its sampled material changes.
      local over=atlas.texels(352,'over');if type(over)~='table' or HID[1]~=cutoutOver then return false end
      local h=0;for i=1,256 do local v=over[i]
        if type(v)~='number' or v~=v or (v~=-1 and (v<0 or v>0xffffff or v%1~=0)) then return false end
        h=(h*31+(v>=0 and v+2 or 1))%2147483647
      end
      local r=overRect(352);local expected={.5001220703125,.50009765625,.5623779296875,.54990234375}
      if h~=2145987619 or type(r)~='table' or #r~=4 then return false end
      for i=1,4 do if r[i]~=expected[i] then return false end end
      return vis(at(32,9),5,10)==0xcedeef
        and vis(at(35,10),13,3)==0xcedeef and vis(at(37,10),2,3)==0xcedeef
        and vis(at(35,10),13,9)==0xce524a and vis(at(37,10),2,9)==0xce524a
    end
    local viridianSides=viridianPostArt()
    local postL=viridianSides and texel(at(32,9),5,10,'over') or HID
    local postR=postL
    -- a plain polygon (wound to its normal by fanN)
    local function pq(m,n,...)
      local pts={}
      for i,p in ipairs({...}) do pts[i]={p,m[2]} end
      fanN(m[1],pts,n)
    end
    local function P(u,h,z,X,Y) return {x0+u/16,gy+h*tv,z,X or x0+u/16,Y} end
    local function Q(u,h,z) return {x0+u/16,gy+h*tv,z} end
    -- the post's un-skewed column per texel row h (one row up: the angled
    -- wall stands a texel behind the crease); the hidden strip above row 23
    local function pattern(xc,tx)
      local out={}
      for h=0,HS-1 do
        local m=HID
        if h<23 then
          local r=math.max(0,21-h)
          local c=r>=16 and at(xc,py) or r>=0 and at(xc,cy) or at(xc,cy-1)
          local v,layer=vis(c,tx,r%16)
          local t=v and texel(c,tx,r%16,layer)
          if t then t.v=v;m=t end
        end
        out[h]=m
      end
      return out
    end
    local patL,patR=pattern(comp.minX,5),pattern(comp.maxX,10)
    -- runs of one colour between texel heights lo and hi
    local function runs(pat,lo,hi,fn)
      local h=0
      while h<HS do
        local m,e=pat[h],h+1
        while e<HS and pat[e].v==m.v and pat[e][1]==m[1] do e=e+1 end
        local a,b=math.max(h,lo),math.min(e,hi)
        if b>a+1e-9 then fn(a,b,m) end
        h=e
      end
    end
    -- how high (texels) a touching building / block hides this gym's side
    -- at a neighbour cell (0: not touching), and that building. A building
    -- beside the gym's own rows draws its wall there only above this gym's
    -- wallTopY (grid.heightStep), so the gym closes its side itself -- except
    -- below a flat-top house's walls (the house draws them) or a PC / Mart's
    -- eave (OV-1); past the gym's rows the neighbour's wall is whole
    local function cover(nx,ny)
      if not faces(nx,ny) then return 0,nil end
      if ny<z0 or ny>=z1 then return math.huge,nil end
      local nc=at(nx,ny)
      local o=compOf(nc)
      if not o and nc then o=nc.facadeOf or nc.doorOf end
      if o and o~=comp and o.kind=="building" and o.wallTopY then
        if o.flatHouse then return (o.wallTopY-gy)/tv,o end
        if o.ov1 then return (o.groundY+o.ov1.Hs-gy)/tv,o end
        return 0,o
      end
      return math.huge,nil
    end
    local bev={L=not faces(comp.minX-1,cy),R=not faces(comp.maxX+1,cy)}
    local nL,nR=norm3({-1,0,1}),norm3({1,0,1})
    -- side walls (a bevelled corner stops D short of the front) and back wall
    for _,s in ipairs({{bev.L,x0,N_W,comp.minX-1,patL},{bev.R,x1,N_E,comp.maxX+1,patR}}) do
      local bv,xw,n,nx,pat=s[1],s[2],s[3],s[4],s[5]
      for yy=z0,z1-1 do
        local za,zb=yy,yy+1
        if yy==z1-1 and bv then zb=zb-D end
        runs(pat,(cover(nx,yy)),HS,function(a,b,m) pq(m,n,{xw,gy+a*tv,za},{xw,gy+a*tv,zb},{xw,gy+b*tv,zb},{xw,gy+b*tv,za}) end)
      end
    end
    for x=comp.minX,comp.maxX do
      runs(patL,(cover(x,z0-1)),HS,function(a,b,m) pq(m,N_N,{x,gy+a*tv,z0},{x+1,gy+a*tv,z0},{x+1,gy+b*tv,z0},{x,gy+b*tv,z0}) end)
    end
    -- the corners: the small angled bevel (an attached corner: flat, on the front)
    runs(patL,0,HS,function(a,b,m)
      if bev.L then pq(m,nL,{x0,gy+a*tv,z1-D},{x0+D,gy+a*tv,z1},{x0+D,gy+b*tv,z1},{x0,gy+b*tv,z1-D})
      else pq(m,N_S,{x0,gy+a*tv,z1},{x0+D,gy+a*tv,z1},{x0+D,gy+b*tv,z1},{x0,gy+b*tv,z1}) end
    end)
    runs(patR,0,HS,function(a,b,m)
      if bev.R then pq(m,nR,{x1-D,gy+a*tv,z1},{x1,gy+a*tv,z1-D},{x1,gy+b*tv,z1-D},{x1-D,gy+b*tv,z1})
      else pq(m,N_S,{x1-D,gy+a*tv,z1},{x1,gy+a*tv,z1},{x1,gy+b*tv,z1},{x1-D,gy+b*tv,z1}) end
    end)
    -- the front wall: the art 1:1 (row = 23 - h), the hidden strip to the soffit
    local function wallY(h) return cy+(23-h)/16 end
    for _,r in ipairs({{6,v0},{v1,W-6}}) do
      local ua,ub=r[1],r[2]
      if ub>ua then
        face({P(ua,0,z1,nil,wallY(0)),P(ub,0,z1,nil,wallY(0)),P(ub,23,z1,nil,wallY(23)),P(ua,23,z1,nil,wallY(23))},N_S)
        pq(HID,N_S,Q(ua,23,z1),Q(ub,23,z1),Q(ub,HS,z1),Q(ua,HS,z1))
      end
    end
    -- the entrance: the door on the wall (row = 31 - h: P rows 14..0), the
    -- jamb posts (h 0-20), the canopy (row = 35 - h: C rows 14..6, h 20-29;
    -- the ball's cut-out above, C rows 5..0 up to 35)
    local function vestY(h) return cy+(31-h)/16 end
    local function canY(h) return cy+(35-h)/16 end
    face({P(U,0,z1,nil,vestY(0)),P(U+16,0,z1,nil,vestY(0)),P(U+16,15,z1,nil,vestY(15)),P(U,15,z1,nil,vestY(15))},N_S)
    pq(HID,N_S,Q(U,15,z1),Q(U+16,15,z1),Q(U+16,20,z1),Q(U,20,z1))
    for pi,p in ipairs({{v0,U},{U+16,v1}}) do
      local ua,ub=p[1],p[2]
      local postFill=pi==1 and postL or postR
      face({P(ua,0,zV,nil,vestY(0)),P(ub,0,zV,nil,vestY(0)),P(ub,15,zV,nil,vestY(15)),P(ua,15,zV,nil,vestY(15))},N_S)
      pq(postFill,N_S,Q(ua,15,zV),Q(ub,15,zV),Q(ub,20,zV),Q(ua,20,zV))
      for _,sd in ipairs({{ua,N_W,x0+(ua+0.5)/16},{ub,N_E,x0+(ub-0.5)/16}}) do
        local u,n,X=sd[1],sd[2],sd[3]
        if viridianSides then X=pi==1 and (35+13.5/16) or (37+2.5/16) end
        face({P(u,0,z1,X,vestY(0)),P(u,0,zV,X,vestY(0)),P(u,15,zV,X,vestY(15)),P(u,15,z1,X,vestY(15))},n)
        pq(postFill,n,Q(u,15,z1),Q(u,15,zV),Q(u,20,zV),Q(u,20,z1))
      end
    end
    -- (canopy cut-out, Claude 2026-10-01 r2; USER: "gym canopy the pokeball
    -- should be sticking up with no backing on the top half the roof stopped
    -- and went back half way up") The emblem panel's dark mid lines (C rows
    -- 6-8) are the canopy's front TOP EDGE: the canopy's upright front shows
    -- C rows 6-14 1:1 (row = 35 - h, h 20 up to HC = 29) and its flat top
    -- (the hidden grey, as the old top) runs at HC straight back to the
    -- front eave's band (zF), the band showing from HC up. Above the lines
    -- (C rows 0-5, h 29-33) only the EMBLEM stands up, a cut-out on the
    -- canopy's front edge: the texels of the ball (light, cool colours)
    -- 4-connected to the panel's centre columns, each 1:1 at its own place,
    -- as a 1-texel slab (front at zV, the same texels on its back, its
    -- edges in each edge texel's own colour; it rests on the top at HC, so
    -- no bottom there). The panel's gold, its outline / bevel columns and
    -- the grey above it get no geometry: the eave shows around the ball.
    face({P(v0,20,zV,nil,canY(20)),P(v1,20,zV,nil,canY(20)),P(v1,HC,zV,nil,canY(HC)),P(v0,HC,zV,nil,canY(HC))},N_S)
    for _,sd in ipairs({{v0,N_W,x0+(v0+0.5)/16},{v1,N_E,x0+(v1-0.5)/16}}) do
      local u,n,X=sd[1],sd[2],sd[3]
      if viridianSides and u==v1 then
        -- The right native outline was stretched through the hidden return,
        -- reading as an open seam above the pale post. Continue its material
        -- across the same closed face; the original canopy edge stays above.
        pq(postR,n,Q(u,20,z1),Q(u,20,zV),Q(u,HS,zV),Q(u,HS,z1))
      else
        face({P(u,20,z1,X,canY(20)),P(u,20,zV,X,canY(20)),P(u,HS,zV,X,canY(HS)),P(u,HS,z1,X,canY(HS))},n)
      end
      face({P(u,HS,zF,X,canY(HS)),P(u,HS,zV,X,canY(HS)),P(u,HC,zV,X,canY(HC)),P(u,HC,zF,X,canY(HC))},n)
    end
    pq(HIDB,UP,Q(v0,HC,zF),Q(v1,HC,zF),Q(v1,HC,zV),Q(v0,HC,zV))
    pq(HIDB,DOWN,Q(U,20,z1),Q(U+16,20,z1),Q(U+16,20,zV),Q(U,20,zV))
    -- (cap white, Claude 2026-10-02 r3b; USER: "i just wanted the grey strip
    -- at the top of the pokeball gone") The cut-out's grey-blue cap texels
    -- (the emblem texels not of the panel's white) show the panel's OWN
    -- white: the UV of its brightest emblem texel, sampled at its centre, no
    -- new colour -- on the front, the back face and the edges. Every other
    -- texel is shown exactly as r2 (its own art, 1:1).
    do
      local RL,NC,zK=35-HC,v1-v0,zV-1/16
      local em,cl={},{}
      for r=0,RL-1 do
        em[r],cl[r]={},{}
        for i=0,NC-1 do
          local u=v0+i
          local v=vis(at(x0+math.floor(u/16),cy),u%16,r)
          cl[r][i]=v
          if v then
            local cr,cg,cb=math.floor(v/65536),math.floor(v/256)%256,v%256
            em[r][i]=(cr+cg+cb>=432 and cr-cb<32) and 0 or nil
          end
        end
      end
      local st={}
      for r=0,RL-1 do for i=math.floor(NC/2)-1,math.floor(NC/2) do if em[r][i]==0 then em[r][i]=1;st[#st+1]={r,i} end end end
      while #st>0 do
        local s=table.remove(st)
        for _,dd in ipairs({{-1,0},{1,0},{0,-1},{0,1}}) do
          local r,i=s[1]+dd[1],s[2]+dd[2]
          if em[r] and em[r][i]==0 then em[r][i]=1;st[#st+1]={r,i} end
        end
      end
      local function on(r,i) return em[r]~=nil and em[r][i]==1 end
      -- (r3b) the panel's white = its brightest emblem texel; a cap texel is
      -- an emblem texel of any other colour
      local wr,wi,wv,wl=nil,nil,nil,-1
      for r=0,RL-1 do for i=0,NC-1 do
        if on(r,i) then
          local v=cl[r][i]
          local l=math.floor(v/65536)+math.floor(v/256)%256+v%256
          if l>wl then wr,wi,wv,wl=r,i,v,l end
        end
      end end
      local WX,WY=wv and x0+(v0+wi+0.5)/16,wv and cy+(wr+0.5)/16
      local function cap(r,i) return wv~=nil and on(r,i) and cl[r][i]~=wv end
      -- runs of columns a..b of row r split where cap() changes (fn(c, ua, ub))
      local function cruns(r,a,b,fn)
        local i=a
        while i<=b do
          local c,j=cap(r,i),i
          while j+1<=b and cap(r,j+1)==c do j=j+1 end
          fn(c,v0+i,v0+j+1)
          i=j+1
        end
      end
      -- per texel row: runs of emblem texels (front, back, ends); runs of
      -- exposed top / bottom edges
      for r=0,RL-1 do
        local ht,hb,Yt,Yb,Ym=35-r,34-r,cy+r/16,cy+(r+1)/16,cy+(r+0.5)/16
        local i=0
        while i<NC do
          if on(r,i) then
            local j=i
            while j+1<NC and on(r,j+1) do j=j+1 end
            cruns(r,i,j,function(c,ua,ub)
              if c then
                face({P(ua,hb,zV,WX,WY),P(ub,hb,zV,WX,WY),P(ub,ht,zV,WX,WY),P(ua,ht,zV,WX,WY)},N_S)
                face({P(ua,hb,zK,WX,WY),P(ub,hb,zK,WX,WY),P(ub,ht,zK,WX,WY),P(ua,ht,zK,WX,WY)},N_N)
              else
                face({P(ua,hb,zV,nil,Yb),P(ub,hb,zV,nil,Yb),P(ub,ht,zV,nil,Yt),P(ua,ht,zV,nil,Yt)},N_S)
                face({P(ua,hb,zK,nil,Yb),P(ub,hb,zK,nil,Yb),P(ub,ht,zK,nil,Yt),P(ua,ht,zK,nil,Yt)},N_N)
              end
            end)
            for _,sd in ipairs({{v0+i,N_W,i},{v0+j+1,N_E,j}}) do
              local u,n,e=sd[1],sd[2],sd[3]
              if cap(r,e) then face({P(u,hb,zK,WX,WY),P(u,hb,zV,WX,WY),P(u,ht,zV,WX,WY),P(u,ht,zK,WX,WY)},n)
              else
                local X=x0+(v0+e+0.5)/16
                face({P(u,hb,zK,X,Yb),P(u,hb,zV,X,Yb),P(u,ht,zV,X,Yt),P(u,ht,zK,X,Yt)},n)
              end
            end
            i=j+1
          else i=i+1 end
        end
        for _,ed in ipairs({{r-1,ht,UP},{r<RL-1 and r+1 or nil,hb,DOWN}}) do
          local rr,h,n=ed[1],ed[2],ed[3]
          if rr~=nil then
            i=0
            while i<NC do
              if on(r,i) and not on(rr,i) then
                local j=i
                while j+1<NC and on(r,j+1) and not on(rr,j+1) do j=j+1 end
                cruns(r,i,j,function(c,ua,ub)
                  if c then face({P(ua,h,zK,WX,WY),P(ub,h,zK,WX,WY),P(ub,h,zV,WX,WY),P(ua,h,zV,WX,WY)},n)
                  else face({P(ua,h,zK,nil,Ym),P(ub,h,zK,nil,Ym),P(ub,h,zV,nil,Ym),P(ua,h,zV,nil,Ym)},n) end
                end)
                i=j+1
              else i=i+1 end
            end
          end
        end
      end
    end
    -- the roof: per texel column its back outline row (T row OVER)
    local back={}
    for u=0,W-1 do
      local c=at(x0+math.floor(u/16),T)
      local o=c and atlas.texels(c.mid,"over")
      back[u]=1
      if o then for r=0,15 do local v=o[r*16+u%16+1] if type(v)=="number" and v>=0 then back[u]=r break end end end
    end
    -- (eave colour) the side eaves' top past each side wall: the roof's own
    -- colour beside that side (grid.eaveFill; the 4 columns inside the
    -- outline column, back outline -> fold)
    local fill={}
    for i,sd in ipairs({{1,4,dL},{W-5,W-2,dR}}) do
      if sd[3]>0 then
        local t={}
        for u=sd[1],sd[2] do t[#t+1]={x0*16+u,T*16+back[u],cy*16+math.floor(27-hT(u+0.5))} end
        fill[i]=grid.eaveFill(own,t)
      end
    end
    -- runs of one plane, one outline row, one column rule (clamped past a
    -- side wall), split at the entrance block's edges
    local segs={}
    for u=-dL,W+dR-1 do
      local cl=u<0 and -1 or u>=W and 1 or 0
      local bk=back[math.max(0,math.min(W-1,u))]
      local part=(hT(u)==HT and hT(u+1)==HT) and 0 or (u<W/2 and -1 or 1)
      local l=segs[#segs]
      if l and l.part==part and l.back==bk and l.cl==cl and u~=v0 and u~=v1 then l.ub=u+1
      else segs[#segs+1]={ua=u,ub=u+1,part=part,back=bk,cl=cl} end
    end
    -- a plain band column (B row, the first inner cell) and the band's art row at h
    local XB=x0+1+8.5/16
    local function bandY(h) return cy+(27-h)/16 end
    for _,s in ipairs(segs) do
      local ua,ub=s.ua,s.ub
      local ha,hb=hT(ua),hT(ub)
      local Xc=s.cl<0 and x0+0.5/16 or s.cl>0 and x1-0.5/16 or nil
      local fold=27-hT((ua+ub)/2)
      local Yb,Yf=T+s.back/16,cy+fold/16
      -- (eave colour) past a side wall: the roof's own colour
      local fl=s.cl~=0 and fill[s.cl<0 and 1 or 2]
      if fl then Xc,Yb,Yf=fl[1],fl[2],fl[2] end
      local dy=(hb-ha)*tv*16/(ub-ua)
      face({P(ua,ha,zB,Xc,Yb),P(ub,hb,zB,Xc,Yb),P(ub,hb,zF,Xc,Yf),P(ua,ha,zF,Xc,Yf)},norm3({-dy,1,0}))
      -- the band on the front eave's edge (the outermost columns: the plain band)
      -- ((canopy cut-out) over the entrance block: from the canopy's top HC up)
      do
        local lo=(ua>=v0 and ub<=v1) and HC or HS
        local Xf=(ua<1 or ub>W-1) and XB or nil
        face({P(ua,lo,zF,Xf,bandY(lo)),P(ub,lo,zF,Xf,bandY(lo)),P(ub,hb,zF,Xf,bandY(hb)),P(ua,ha,zF,Xf,bandY(ha))},N_S)
      end
      face({P(ub,HS,zB,XB,bandY(HS)),P(ua,HS,zB,XB,bandY(HS)),P(ua,ha,zB,XB,bandY(ha)),P(ub,hb,zB,XB,bandY(hb))},N_N)
    end
    -- the side ends of the slab (beside a touching building: above its
    -- cover, plus -- beside the gym's own rows -- the strip between the
    -- slope's edge and this gym's wallTopY, where that building's wall stops)
    for _,s in ipairs({{-dL,N_W,N_E,comp.minX-1,dL},{W+dR,N_E,N_W,comp.maxX+1,dR}}) do
      local u,n,nb,nx,d=s[1],s[2],s[3],s[4],s[5]
      local h=hT(u)
      local xw=x0+u/16
      local zs={zB}
      for yy=z0,z1 do if yy>zB+1e-9 and yy<zF-1e-9 then zs[#zs+1]=yy end end
      zs[#zs+1]=zF
      for i=1,#zs-1 do
        local a,b=zs[i],zs[i+1]
        local cv,o=0,nil
        if d<=0 then cv,o=cover(nx,math.floor((a+b)/2)) end
        local lo=math.max(HS,cv)
        if h>lo+1e-9 then
          face({{xw,gy+lo*tv,a,XB,bandY(lo)},{xw,gy+lo*tv,b,XB,bandY(lo)},{xw,gy+h*tv,b,XB,bandY(h)},{xw,gy+h*tv,a,XB,bandY(h)}},n)
        end
        local top=o and a>=z0-1e-9 and b<=z1+1e-9 and (math.min(comp.wallTopY,o.wallTopY)-gy)/tv
        if top and top>h+1e-9 then pq(HID,nb,{xw,gy+h*tv,a},{xw,gy+h*tv,b},{xw,gy+top*tv,b},{xw,gy+top*tv,a}) end
      end
    end
    -- the soffit: one level ring at HS outside the walls (the bevel's corner
    -- triangles included; none inside the canopy)
    local xa,xb,sy=x0-dL/16,x1+dR/16,gy+HS*tv
    local function sq(ax,az,bx,bz)
      if bx-ax>1e-9 and bz-az>1e-9 then pq(HIDB,DOWN,{ax,sy,az},{bx,sy,az},{bx,sy,bz},{ax,sy,bz}) end
    end
    sq(xa,z1,x0+v0/16,zF);sq(x0+v1/16,z1,xb,zF)
    sq(xa,zB,xb,z0)
    sq(xa,z0,x0,z1);sq(x1,z0,xb,z1)
    if bev.L then pq(HIDB,DOWN,{x0,sy,z1-D},{x0,sy,z1},{x0+D,sy,z1}) end
    if bev.R then pq(HIDB,DOWN,{x1-D,sy,z1},{x1,sy,z1},{x1,sy,z1-D}) end
    -- grounds: the bevel's notch (as grid.foldFloor) and the porch row's own
    -- cells (the posts' feet excluded); another porch cell keeps its box
    local function plainG(q) return q~=nil and q.walkable and not q.isDoor and not q.isSign and not q.hasOver and compOf(q)==nil end
    for _,k in ipairs({"L","R"}) do
      if bev[k] then
        local x=k=="L" and comp.minX or comp.maxX
        local nb,fr=at(k=="L" and x-1 or x+1,cy),at(x,py)
        local g=plainG(nb) and nb or plainG(fr) and fr or nil
        local r=g and underRect(g.groundMid or g.mid)
        if r then
          local function pt(px,pz) return {{px,gy,pz},{r[1]+(px-x)*(r[3]-r[1]),r[2]+(pz-cy)*(r[4]-r[2])}} end
          local xs,xe=k=="L" and x or x+1,k=="L" and x+D or x+1-D
          fanN(opaque,{pt(xs,z1-D),pt(xs,z1),pt(xe,z1)},UP)
        end
      end
    end
    local _,gpal=groundTaint(comp.minX,comp.minY,comp.maxX,comp.maxY+1)
    for x=comp.minX,comp.maxX do
      local c=at(x,py)
      if c and isCompCell(c,comp) then
        local rects
        if x==xd-1 then rects={{x,z1,x0+v0/16,z1+1},{x0+v0/16,zV,x+1,z1+1}}
        elseif x==xd+1 then rects={{x,zV,x0+v1/16,z1+1},{x0+v1/16,z1,x+1,z1+1}}
        elseif x==xd then rects={{x,z1,x+1,z1+1}}
        else
          -- (the old porch box, as built before: r11 v15)
          local c0,c1=0,15
          local u=atlas.texels(c.mid,"under")
          local vr={}
          if u and gpal then
            local o=c.hasOver and atlas.texels(c.mid,"over") or nil
            local solid={}
            for tx=0,15 do
              local g=0
              for ty=0,15 do
                local i=ty*16+tx+1
                local v=(o and o[i] and o[i]>=0) and o[i] or u[i]
                if gpal[v] then g=g+1 end
              end
              solid[tx]=g<=4
            end
            c0,c1=nil,nil
            for tx=0,15 do if solid[tx] then c0=c0 or tx;c1=tx end end
            for _,tx in ipairs({c0,c1}) do
              local function gr(ty)
                local i=ty*16+tx+1
                local v=(o and o[i] and o[i]>=0) and o[i] or u[i]
                return gpal[v]
              end
              local a,b=0,15
              while a<b and gr(a) do a=a+1 end
              while b>a and gr(b) do b=b-1 end
              vr[tx]={a/16,(b+1)/16}
            end
          end
          rects={}
          local base0=underRect(c.mid)
          if c0 and base0 then
            local bx0,bx1=x+c0/16,x+(c1+1)/16
            local y0,y1=gy,gy+C.WALL_ROW_UNIT
            local base=subRect(base0,c0/16,0,(c1+1)/16,1)
            local ov=c.hasOver and overRect(c.mid) or nil
            wallQuad(opaque,bx0,z1+1,bx1,z1+1,y0,y1,base,N_S)
            if ov then wallQuad(cutoutOver,bx0,z1+1+C.FACADE_OVER_LIFT,bx1,z1+1+C.FACADE_OVER_LIFT,y0,y1,subRect(ov,c0/16,0,(c1+1)/16,1),N_S) end
            hQuad(opaque,bx0,z1,bx1,z1+1,y1,subRect(base0,c0/16,0.5/16,(c1+1)/16,0.5/16))
            for _,sd in ipairs({{-1,bx0,N_W,(c0+0.5)/16,c0},{1,bx1,N_E,(c1+0.5)/16,c1}}) do
              local rv=vr[sd[5]] or {0,1}
              local col=subRect(base0,sd[4],rv[1],sd[4],rv[2])
              if sd[1]<0 then wallQuad(opaque,sd[2],z1,sd[2],z1+1,y0,y1,col,sd[3])
              else wallQuad(opaque,sd[2],z1+1,sd[2],z1,y0,y1,col,sd[3]) end
            end
            rects={{x,z1,bx0,z1+1},{bx1,z1,x+1,z1+1}}
          end
        end
        local r=G.donor[x] and underRect(G.donor[x])
        if r then
          for _,q in ipairs(rects) do
            if q[3]-q[1]>1e-9 and q[4]-q[2]>1e-9 then
              local function pt(px,pz) return {{px,gy,pz},{r[1]+(px-x)*(r[3]-r[1]),r[2]+(pz-py)*(r[4]-r[2])}} end
              fanN(opaque,{pt(q[1],q[2]),pt(q[3],q[2]),pt(q[3],q[4]),pt(q[1],q[4])},UP)
            end
          end
        end
      end
    end
    -- the night window rects follow the facade row up (it starts 7 rows up)
    for _,w in ipairs(wins or {}) do w.wy0,w.wy1=w.wy0+7*tv,w.wy1+7*tv end
    comp.roofAt=function(px) return gy+hT(math.max(-dL,math.min(W+dR,(px-x0)*16)))*tv end
    return "gym-flat",ex0,ex1,ez0,ez1
  end

  -- Tanoby desktop prototype: exact source facade, native blocked footprint body.
  -- Existing local rock height is retained independently of stone height.
  grid.nativeStonePortal=function(comp,marks)
    local left,right=at(comp.minX-1,comp.minY),at(comp.maxX+1,comp.minY)
    assert(left and right and left.rock and right.rock and left.rockTop==right.rockTop,'native portal local rock ownership')
    local top=left.rockTop
    assert(top and top>comp.groundY,'native portal local rock height')
    for k,list in ipairs({opaque,cutoutUnder,cutoutOver,cutoutKeyed})do for i=#list,marks[k]+1,-1 do list[i]=nil end end
    local rockColors={}
    for _,mid in ipairs({713,160,162})do for _,v in ipairs(atlas.texels(mid,'under') or {})do if v>=0 then rockColors[v]=true end end end
    -- Stone gray is shared with rock; preserve exact masonry ownership.
    for _,v in ipairs(atlas.texels(721,'over') or {})do rockColors[v]=nil end
    local sand=atlas.texels(277,'under');local sandColor=sand and sand[1]
    local pixels={}
    for py=0,63 do pixels[py]={};for px=0,47 do
      local c=at(comp.minX+math.floor(px/16),comp.minY+math.floor(py/16))
      local index=(py%16)*16+(px%16)+1
      local under=atlas.texels(c.mid,'under');local over=c.hasOver and atlas.texels(c.mid,'over') or nil
      local layer,value='under',under and under[index]
      if over and over[index]>=0 then layer,value='over',over[index] end
      if value and value>=0 and not rockColors[value] and value~=sandColor then
        pixels[py][px]={mid=c.mid,layer=layer,px=px%16,py=py%16}
      end
    end end
    local zf,zb,gy=comp.maxY+1,comp.minY,comp.groundY
    local plain=overRect(721)
    local function exists(x,y)return pixels[y] and pixels[y][x] end
    -- Merge only contiguous source rectangles with identical material/UV tile.
    local used={};for y=0,63 do used[y]={}end
    for py=0,63 do Y();local px=0;while px<48 do local p=pixels[py][px]
      if not p or used[py][px] then px=px+1 else
        local stop=px+1
        while stop<48 do local q=pixels[py][stop];if used[py][stop]or not q or q.mid~=p.mid or q.layer~=p.layer or q.px~=p.px+stop-px then break end;stop=stop+1 end
        local endY=py+1
        while endY<64 and p.py+endY-py<16 do
          local ok=true;for x=px,stop-1 do local q=pixels[endY][x];if used[endY][x]or not q or q.mid~=p.mid or q.layer~=p.layer or q.px~=p.px+x-px or q.py~=p.py+endY-py then ok=false;break end end
          if not ok then break end;endY=endY+1
        end
        for y=py,endY-1 do for x=px,stop-1 do used[y][x]=true end end
        local r=p.layer=='over' and overRect(p.mid) or underRect(p.mid)
        local uv=subRect(r,p.px/16,p.py/16,(p.px+stop-px)/16,(p.py+endY-py)/16)
        local list=p.layer=='over' and cutoutOver or opaque
        local x0,x1=comp.minX+px/16,comp.minX+stop/16
        local y0,y1=gy+(64-endY)/16,gy+(64-py)/16
        wallQuad(list,x0,zf,x1,zf,y0,y1,uv,{0,0,1})
        px=stop
      end
    end end
    -- A plain masonry body uses the original blocked footprint, capped
    -- below the native stepped crown. Unpictured depth is reconstruction.
    local x0,x1=comp.minX,comp.maxX+1
    for y=0,2 do Y()
      for z=zb,zf-1 do
        quad(cutoutOver,{x0,gy+y,z+1},{x0,gy+y,z},{x0,gy+y+1,z},{x0,gy+y+1,z+1},plain,{-1,0,0})
        quad(cutoutOver,{x1,gy+y,z},{x1,gy+y,z+1},{x1,gy+y+1,z+1},{x1,gy+y+1,z},plain,{1,0,0})
      end
      for x=x0,x1-1 do quad(cutoutOver,{x+1,gy+y,zb},{x,gy+y,zb},{x,gy+y+1,zb},{x+1,gy+y+1,zb},plain,{0,0,-1})end
    end
    for z=zb,zf-1 do for x=x0,x1-1 do
      local endZ=math.min(z+1,zf-.25)
      if endZ>z then hQuad(cutoutOver,x,z,x+1,endZ,gy+3,plain,UP)end
    end end
    -- Crown thickness is 0.25 only above the flat cap; rear is plain stone,
    -- never mirrored doorway artwork. Runs coalesce its horizontal extent.
    local crownBack=zf-.25
    local crownUv=subRect(plain,.5,.5,.5,.5)
    for py=0,15 do local px=0;while px<48 do
      if not exists(px,py)then px=px+1 else
        local stop=px+1;while stop<48 and exists(stop,py)do stop=stop+1 end
        local a,b=x0+px/16,x0+stop/16;local lo,hi=gy+(63-py)/16,gy+(64-py)/16
        quad(cutoutOver,{b,lo,crownBack},{a,lo,crownBack},{a,hi,crownBack},{b,hi,crownBack},crownUv,{0,0,-1})
        px=stop
      end
    end end
    -- Exact silhouette edge closure. Only boundary texels create walls.
    for py=0,15 do for px=0,47 do if exists(px,py)then
      local a,b=x0+px/16,x0+(px+1)/16;local lo,hi=gy+(63-py)/16,gy+(64-py)/16
      if not exists(px-1,py)then quad(cutoutOver,{a,lo,crownBack},{a,lo,zf},{a,hi,zf},{a,hi,crownBack},crownUv,{-1,0,0})end
      if not exists(px+1,py)then quad(cutoutOver,{b,lo,zf},{b,lo,crownBack},{b,hi,crownBack},{b,hi,zf},crownUv,{1,0,0})end
      if not exists(px,py-1)then hQuad(cutoutOver,a,crownBack,b,zf,hi,crownUv,UP)end
      if not exists(px,py+1)then quad(cutoutOver,{a,lo,crownBack},{b,lo,crownBack},{b,lo,zf},{a,lo,zf},crownUv,DOWN)end
    end end end
    -- Fill the crown-foot cap only where no raised front crown exists.
    for px=0,47 do if not exists(px,15)then hQuad(cutoutOver,x0+px/16,crownBack,x0+(px+1)/16,zf,gy+3,crownUv,UP)end end
    local count=0;for k,list in ipairs({opaque,cutoutUnder,cutoutOver,cutoutKeyed})do count=count+(#list-marks[k])/3 end
    assert(count<=1000,'native portal triangle budget '..count)
    comp.nativePortalTriangles=count
  end


  local buildingInfo, roofless = {}, 0
  grid.emitNativeMemorial=function(comp)
    local gy=comp.groundY
    local source={{704,705},{712,713},{720,721},{728,729}}
    local edges={
{14,17},
{13,18},
{12,19},
{12,19},
{11,20},
{10,20},
{9,21},
{9,21},
{9,21},
{9,21},
{10,21},
{9,22},
{8,22},
{8,23},
{7,24},
{6,25},
{6,25},
{6,25},
{5,26},
{5,27},
{4,27},
{3,28},
{3,28},
{3,29},
{3,29},
{2,29},
{2,29},
{2,29},
{3,29},
{4,29},
{4,28},
{5,28},
{6,26},
{5,25},
{5,25},
{5,25},
{5,26},
{5,26},
{4,26},
{4,26},
{3,27},
{3,27},
{3,28},
{3,28},
{2,29},
{1,30},
{1,30},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{0,31},
{1,30},
{3,28},
{5,26},
{8,24},

    }
    local function ring(row,t,back)
      local e=edges[math.min(64,math.max(1,row+1))]
      local cx=8+(e[1]+e[2]+1)/32
      local radius=(e[2]-e[1]+1)/32
      local s=t*2-1
      return {cx+radius*s,gy+(64-row)/16,43+(back and 1 or -1)*radius*math.sqrt(math.max(0,1-s*s))}
    end
    for row=0,63 do
      local tileRow=math.floor(row/16)+1
      for part=0,7 do
        local xa,xb=part*4,(part+1)*4
        local edge=edges[row+1]
        local sx0=edge[1]+(edge[2]-edge[1]+1)*xa/32
        local sx1=edge[1]+(edge[2]-edge[1]+1)*xb/32
        local col=math.min(2,math.floor((sx0+sx1)*.5/16)+1)
        local mid=source[tileRow][col]
        local r=(tileRow<=2 and overRect(mid)or underRect(mid))
        local u0=r[1]+math.max(.5,math.min(15.5,sx0-(col-1)*16+.5))/16*(r[3]-r[1])
        local u1=r[1]+math.max(.5,math.min(15.5,sx1-(col-1)*16-.5))/16*(r[3]-r[1])
        local v0=r[2]+(row%16+.5)/16*(r[4]-r[2])
        local v1=r[2]+math.min(15.5,row%16+1.5)/16*(r[4]-r[2])
        for _,back in ipairs{false,true}do
          local a,b,c,d=ring(row,xa/32,back),ring(row,xb/32,back),ring(row+1,xb/32,back),ring(row+1,xa/32,back)
          if back then a,b,c,d=b,a,d,c end
          local n=faceNormal3(a,b,c)
          local list=tileRow<=2 and cutoutOver or opaque
          tri3(list,a,{u0,v0},n,b,{u1,v0},n,c,{u1,v1},n)
          tri3(list,a,{u0,v0},n,c,{u1,v1},n,d,{u0,v1},n)
        end
      end
    end
    local top=overRect(704)
    local uv={(math.floor(top[1]*atlas.w)+edges[1][1]+.5)/atlas.w,(math.floor(top[2]*atlas.h)+.5)/atlas.h}
    for part=0,7 do
      local a,b=ring(0,part/8,false),ring(0,(part+1)/8,false)
      local c,d=ring(0,part/8,true),ring(0,(part+1)/8,true)
      if part<7 then tri3(cutoutOver,a,uv,UP,b,uv,UP,d,uv,UP)end
      if part>0 then tri3(cutoutOver,a,uv,UP,d,uv,UP,c,uv,UP)end
    end
    -- Path reconstructed beneath the vacated architectural rectangle only.
    for yy=comp.minY,comp.maxY do for xx=comp.minX,comp.maxX do
      hQuad(opaque,xx,yy,xx+1,yy+1,gy,underRect(225))
      for _,dir in ipairs(DIRS)do
        local nx,ny=xx+dir.dx,yy+dir.dy
        if nx<comp.minX or nx>comp.maxX or ny<comp.minY or ny>comp.maxY then
          local q=at(nx,ny)
          if q and q.walkable and not q.isWater and q.hgt<gy-EPS then
            faceQuad(opaque,dir.name,xx,xx+1,yy,yy+1,q.hgt,gy,
              subRectV(underRect(225),math.max(0,1-(gy-q.hgt)),1))
          end
        end
      end
    end end
    buildingInfo[#buildingInfo+1]={minX=8,maxX=9,minY=41,maxY=43,cells=6,
      groundY=gy,wallTopY=gy+4,wallHeight=4,wallRows=4,roofMode='native-stone-memorial',roofMid=713,
      windows={},doors={},roofTris=0,flatRoof=false,gable=false,depthReconstruction='symmetric native silhouette'}
  end
  grid.seviiPurpleFinish=function(comp,info)
    local data=comp.nativeBuildingProfile.nativeSeviiPurple
    local lists={opaque,cutoutUnder,cutoutOver,cutoutKeyed}
    local front=comp.maxY+1
    -- Keep the original actual front/header/door emitter only. This range is
    -- the exact current building producer tail, never a whole-map ROI filter.
    for li,list in ipairs(lists)do
      local first=comp.seviiPurpleStart[li]+1;local keep={}
      for i=first,#list,3 do
        local retain=true;local south=true;local door=true
        for j=i,i+2 do local v=list[j]
          if v[3]<front-.13 or v[2]>comp.wallTopY+1e-8 then retain=false end
          if v[8]<.999999 or v[3]>front+.02000001 then south=false end
          if v[1]<data.x+1-1e-8 or v[1]>data.x+2+1e-8 or v[2]>comp.groundY+1+1e-8 or v[3]>front+.02000001 then door=false end
        end
        retain=retain and(south or door)
        if retain then for j=i,i+2 do keep[#keep+1]=list[j]end end
      end
      for i=#list,first,-1 do list[i]=nil end
      for _,v in ipairs(keep)do list[#list+1]=v end
    end
    local function clip(poly,k,bound,sign)
      local out={};local a=poly[#poly]
      for _,b in ipairs(poly)do
        local da=(a[k]-bound)*sign;local db=(b[k]-bound)*sign
        if (da>=-1e-9)~=(db>=-1e-9)then
          local t=da/(da-db);local q={};for j=1,5 do q[j]=a[j]+(b[j]-a[j])*t end
          out[#out+1]=q
        end
        if db>=-1e-9 then out[#out+1]=b end;a=b
      end
      return out
    end
    local emitted=0
    local function emit(t)
      local minU,minV,maxU,maxV=math.huge,math.huge,-math.huge,-math.huge
      for _,p in ipairs(t.p)do minU=math.min(minU,p[4]);maxU=math.max(maxU,p[4]);minV=math.min(minV,p[5]);maxV=math.max(maxV,p[5])end
      local ux0,ux1=math.floor((minU+1e-8)/16),math.floor((maxU-1e-8)/16)
      local vy0,vy1=math.floor((minV+1e-8)/16),math.floor((maxV-1e-8)/16)
      if ux1<ux0 then ux1=ux0 end;if vy1<vy0 then vy1=vy0 end
      for cy=vy0,vy1 do for cx=ux0,ux1 do
        local p=t.p
        for _,h in ipairs{{4,cx*16,1},{4,(cx+1)*16,-1},{5,cy*16,1},{5,(cy+1)*16,-1}}do if #p>0 then p=clip(p,h[1],h[2],h[3])end end
        if #p>=3 then
          local cell=data.cells and data.cells[(data.x+cx)..','..(data.z+cy)]or at(data.x+cx,data.z+cy);assert(cell,'native purple source cell')
          local over=t.material=='roof' or cy<3
          local r=over and overRect(cell.mid)or underRect(cell.mid);assert(r,'native purple source layer')
          local list=over and cutoutOver or opaque
          local vs={}
          for _,v in ipairs(p)do
            vs[#vs+1]={data.x+v[1]/16,comp.groundY+v[2]/16,data.z+v[3]/16,
              r[1]+(r[3]-r[1])*(v[4]-cx*16)/16,r[2]+(r[4]-r[2])*(v[5]-cy*16)/16,t.n[1],t.n[2],t.n[3]}
          end
          for j=2,#vs-1 do
            local a,b,c=vs[1],vs[j],vs[j+1]
            local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3];local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
            local dot=(uy*vz-uz*vy)*t.n[1]+(uz*vx-ux*vz)*t.n[2]+(ux*vy-uy*vx)*t.n[3]
            if math.abs(dot)>1e-12 then
              if dot<0 then b,c=c,b end
              for _,v in ipairs{a,b,c}do vN(list,v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8]);list[#list].seviiPurplePart=t.tag end
              emitted=emitted+1
            end
          end
        end
      end end
    end
    for _,group in ipairs{data.roof or data.triangles,data.walls or{}}do for _,t in ipairs(group)do emit(t)end end
    local function quadPart(points,uv,n,tag)
      local p={};for i,v in ipairs(points)do p[i]={v[1],v[2],v[3],uv[i][1],uv[i][2]}end
      emit{p=p,n=n,tag=tag,material='roof'}
    end
    -- The shared r6 projection has front wall V45 at Z64/Y19, whereas
    -- eave V45 lies at Z66/Y21. Close that two-pixel hidden continuation.
    quadPart({{0,19,64},{80,19,64},{80,21,64},{0,21,64}},{{2,45.5},{7,45.5},{7,45.5},{2,45.5}},{0,0,1},'body.hidden-front-header')
    for _,r in ipairs{{-2,82,-2,data.bodyBack or 0},{-2,82,64,66},{-2,0,data.bodyBack or 0,64},{80,82,data.bodyBack or 0,64}}do
      quadPart({{r[1],21,r[3]},{r[2],21,r[3]},{r[2],21,r[4]},{r[1],21,r[4]}},{{8,44.5},{9,44.5},{9,44.5},{8,44.5}},{0,-1,0},'roof.soffit')
    end
    info.nativeSeviiPurple=true;info.roofMode='native-sevii-spined-hip';info.gable=false;info.flatRoof=false
    info.wallHeight=data.wallTop/16;info.wallTopY=comp.groundY+info.wallHeight;info.bodyTopY=info.wallTopY;info.crownTopY=comp.groundY+data.ridge/16
    info.nativeFacadeTopY=comp.groundY+data.sourceHeaderTop/16
    info.nativeFacadeHeight=data.sourceHeaderTop/16
    info.nativeSeviiTriangles=emitted
    info.roofTris=nil;info.roofSolidTris=nil;info.roofOpaqueTris=nil;info.roofOverTris=nil;info.capTris=nil
    info.eave={x0=data.x-2/16,x1=data.x+82/16,z0=data.z-2/16,z1=data.z+66/16}
    info.ridgeZ=data.z+data.ridgeZ/16
