  or not((rr[1]==bx1 and rr[2]==29.2)or(rr[1]==23.8 and rr[2]==bx0))then return false end
 local zm=comp.gableZm
 local function y(z)return comp.roofAt((rr[1]+rr[2])*.5,z)-C.FASCIA_H end
 local function tex(x,z)return {uv[1]+(uv[3]-uv[1])*(z-bz0)/(bz1-bz0),uv[2]+(uv[4]-uv[2])*(x-rr[1])/(rr[2]-rr[1])}end
 local function face(points,n)local pts={};for _,p in ipairs(points)do pts[#pts+1]={p,tex(p[1],p[3])}end;fanN(list,pts,n)end
 -- End underside follows the existing bargeboard's lower edge, not a level
 -- plate cutting across the cream gable. Keep native trim coordinates.
 for _,r in ipairs{{bz0,zm},{zm,bz1}}do local za,zb=r[1],r[2];local ya,yb=y(za),y(zb)
  local slope=(yb-ya)/(zb-za);local n=norm3({0,-1,slope})
  face({{rr[1],ya,za},{rr[1],yb,zb},{rr[2],yb,zb},{rr[2],ya,za}},n)
 end
 -- The old front/back horizontal ring stays exactly fixed. Close the two
 -- small endpoint differences rather than leaving an exposed step/slit.
 for _,q in ipairs{{bz0,1},{bz1,-1}}do local z,inside=q[1],q[2];local h=y(z)
  if math.abs(h-sy)>1e-9 then local n={0,0,(h>sy and 1 or-1)*inside}
   face({{rr[1],sy,z},{rr[2],sy,z},{rr[2],h,z},{rr[1],h,z}},n)
  end
 end
 return true
end

