 for _,s in ipairs({{24,17,656,7,0,0,0,0,-1,"BUILDING"},{25,17,657,7,0,0,0,0,-1,"BUILDING"},{26,17,658,7,0,0,0,0,-1,"BUILDING"},{27,17,659,7,0,0,0,0,-1,"BUILDING"},{28,17,660,7,0,0,0,0,-1,"BUILDING"},{24,18,664,7,0,0,1,0,-1,"BUILDING"},{25,18,665,113,0,105,1,1,-1,"DOOR"},{26,18,666,7,0,0,1,0,-1,"BUILDING"},{27,18,667,7,0,0,1,0,-1,"BUILDING"},{28,18,668,7,0,0,1,0,-1,"BUILDING"},{24,19,672,0,3,0,1,1,-1,"TOWN_PATH"},{25,19,206,0,3,0,1,1,-1,"TOWN_PATH"},{26,19,674,0,3,0,1,1,-1,"TOWN_PATH"},{27,19,675,0,3,0,1,1,-1,"TOWN_PATH"},{28,19,676,0,3,0,1,1,-1,"TOWN_PATH"},{24,20,358,0,3,0,1,1,-1,"TOWN_PATH"},{25,20,358,0,3,0,1,1,-1,"TOWN_PATH"},{26,20,358,0,3,0,1,1,-1,"TOWN_PATH"},{27,20,358,0,3,0,1,1,-1,"TOWN_PATH"},{28,20,358,0,3,0,1,1,-1,"TOWN_PATH"}})do local c=input.cellAt(s[1],s[2])
