grid.viridianGardenFront=function(comp,x,band,base,ov,y0,y1,z)
 if comp.nativeViridianGarden and band.rowY==18 and band.filler and (x==24 or x==28) and not ov then
  local hi,lo=x==24 and 2 or 0,x==28 and 14 or 16
  wallQuad(opaque,x+hi/16,z,x+lo/16,z,y0,y1,subRect(base,hi/16,0,lo/16,1),N_S)
  if hi>0 then wallQuad(opaque,x,z,x+hi/16,z,y0,y1,subRect(base,(hi+.5)/16,0,(hi+.5)/16,1),N_S)end
  if lo<16 then wallQuad(opaque,x+lo/16,z,x+1,z,y0,y1,subRect(base,(lo-.5)/16,0,(lo-.5)/16,1),N_S)end
  return true
 end
 if not comp.nativeViridianGarden or band.rowY~=18 or band.filler or not(x==24 or x==26 or x==27 or x==28)or ov then return false end
 local hi,lo=x==24 and 2 or 0,x==28 and 14 or 16
 local mid=at(x,18).mid;local apron=at(x,19).mid
 local remove=comp.nativeViridianGarden.ground[x];local last,write=#opaque,1
