 for i=write,last do opaque[i]=nil end
 local function uv(m,px,py)local r=underRect(m);return {(math.floor(r[1]*atlas.w)+px+.5)/atlas.w,(math.floor(r[2]*atlas.h)+py+.5)/atlas.h}end
 local function face(points,n,t)local first=#opaque+1;local pts={};for _,p in ipairs(points)do pts[#pts+1]={p,t}end;fanN(opaque,pts,n);for i=first,#opaque do opaque[i].viridianGardenPart=true end end
 local function rect(ax,bx,ya,yb,zz,t)face({{ax,ya,zz},{bx,ya,zz},{bx,yb,zz},{ax,yb,zz}},N_S,t)end
