{756,"under",128911717},
{752,"under",1685036516},
{760,"under",709939829},
{738,"under",1868114301},
}
for _,s in ipairs(sourceCells)do local c=input.cellAt(s[1],s[2]);if not c or c.mid~=s[3]or c.collision~=s[4]or c.elevation~=s[5]or(c.behavior or -1)~=s[6]or c.layerType~=s[7]or c.walkable~=s[8]then return end end
for _,s in ipairs(sourceArt)do local t=atlas.texels(s[1],s[2]);local h=0;for i=1,256 do local v=t and t[i] or -1;h=(h*31+(v>=0 and v+2 or 1))%2147483647 end;if h~=s[3]then return end end
local targets={};for _,s in ipairs(sourceCells)do if s[2]==comp.maxY and s[1]>=comp.minX and s[1]<=comp.maxX then targets[#targets+1]=s end end
