   if not west then emit({{xa,gy,z},{xa,gy+.375,z},{xa,gy+.375,z+.625},{xa,gy,z+.625}},N_W,soil)end
   if not east then emit({{xb,gy,z+.625},{xb,gy+.375,z+.625},{xb,gy+.375,z},{xb,gy,z}},N_E,soil)end
  end end
  for py=8,15 do for px=lo,hi-1 do if plantPalette[t[py*16+px+1]]then
