end

grid.museumCleanCanopyWall=function(comp,x,band)
 local p=comp.nativeBuildingProfile
 if not(type(p)=='table'and p.name=='pewter-museum-main'and p.wallRows==2 and p.flatRoof==false and x>=16 and x<=18 and (band.rowY==4 or band.rowY==5))then return nil end
 if input.mapId~='FR_PEWTER_CITY'or input.pair~='pewter_outdoor'or input.isBorder or comp.minX~=12 or comp.maxX~=22 or comp.minY~=0 or comp.maxY~=5 then return nil end
 local c=at(x,band.rowY);local owner=compOf(c)
 if isCompCell(c,comp)or not owner or not grid.museumEntryBegin(owner)then return nil end
 local donor=at(16,4);if not donor or donor.mid~=674 then return nil end
 local t=atlas.texels(674,'under');if type(t)~='table'or t[9*16+3+1]~=0xd6c5bd then return nil end
 local r=underRect(674);if type(r)~='table'then return nil end
 for _,v in ipairs(r)do if type(v)~='number'or v~=v or math.abs(v)==math.huge then return nil end end
 if #r~=4 or r[1]>=r[3]or r[2]>=r[4]then return nil end
 local u,v=r[1]+(r[3]-r[1])*3.5/16,r[2]+(r[4]-r[2])*9.5/16
 grid.museumCleanCanopyWallCount=(grid.museumCleanCanopyWallCount or 0)+1
 return{u,v,u,v}
end

