  local greenRoof={x0=-2,x1=82,zf=66,zb=6,ye=23,yr=34.918773662137127,yt=35.918773662137127,zrf=36.5,zrb=35.5}
  local function greenHash(t)
    if not t then return 0 end
    if type(t)~='table' then return nil end
    local h=0
    for i=1,256 do
      local v=t[i]
      if type(v)~='number' or v~=v or v==math.huge or v==-math.huge
        or (v~=-1 and (v<0 or v>16777215 or v%1~=0)) then return nil end
      h=(h*31+(v>=0 and v+2 or 1))%2147483647
    end
    return h
  end
  local function greenRect(fn,mid)
    local r={fn(mid)}
    if #r~=4 then return nil end
    for i=1,4 do if type(r[i])~='number' or r[i]~=r[i] or math.abs(r[i])==math.huge or r[i]<0 or r[i]>1 then return nil end end
    if r[1]>=r[3] or r[2]>=r[4] then return nil end
    return r
  end
  grid.viridianGreenGuard=function(comp)
    if input.mapId~='FR_VIRIDIAN_CITY' or input.pair~='viridian_outdoor' or input.isBorder
      or input.width~=48 or input.height~=40 or atlas.w~=256 or atlas.h~=320
      or type(atlas.texels)~='function' or type(atlas.hasOver)~='function'
      or type(atlas.overCoverage)~='function' or type(atlas.underRect)~='function'
      or type(atlas.overRect)~='function' or comp.minX~=24 or comp.maxX~=28
      or comp.groundY~=.75 or comp.wallTopY~=2 or comp.wallRows~=1
      or C.WALL_ROW_UNIT~=1 or C.WALL_HEIGHT_MIN~=1.25
      or C.EAVE_OVERHANG~=.2 or C.ROOF_OVERHANG_PUSH~=.6 then return nil end
    local site
    for _,s in ipairs(greenSites)do if comp.minY==s.native.minY and comp.maxY==s.native.maxY then site=s end end
    if not site then return nil end
    -- The northern house supplies the clean native panel/post source for
    -- BOTH hidden shells. Its facade pixels remain literal on its own front.
    for _,s in ipairs(greenSites)do
      local n=s.native
      for yi,row in ipairs(n.cells)do for xi,raw in ipairs(row)do
        local c=input.cellAt(n.x+xi-1,n.z+yi-1)
        if not c or c.mid~=raw[1] or c.collision~=raw[2] or c.elevation~=raw[3]
          or c.behavior~=(raw[4]~=-1 and raw[4] or nil)
          or c.layerType~=raw[5] or c.walkable~=(raw[6]==1)
          or c.category~=raw[8] then return nil end
      end end
      for mid,h in pairs(n.art)do
        if atlas.hasOver(mid)~=n.over[mid] or atlas.overCoverage(mid)~=n.coverage[mid] then return nil end
        local ur=greenRect(atlas.underRect,mid)
        local vr=n.over[mid] and greenRect(atlas.overRect,mid) or nil
        if not ur or (n.over[mid] and not vr) then return nil end
        for i=1,4 do
          if ur[i]~=n.rects[mid][1][i] or (vr and vr[i]~=n.rects[mid][2][i]) then return nil end
        end
        if greenHash(atlas.texels(mid,'under'))~=h[1]
          or greenHash(atlas.texels(mid,'over'))~=h[2] then return nil end
      end
    end
    return site
  end
  local function greenClip(poly,k,bound,sign)
    local out={};local a=poly[#poly]
    for _,b in ipairs(poly)do
      local da=(a[k]-bound)*sign;local db=(b[k]-bound)*sign
      if (da>=-1e-9)~=(db>=-1e-9)then
        local t=da/(da-db);local q={}
        for j=1,5 do q[j]=a[j]+(b[j]-a[j])*t end
        out[#out+1]=q
      end
      if db>=-1e-9 then out[#out+1]=b end
      a=b
    end
    return out
  end
  grid.viridianGreenFinish=function(comp,info)
    local site=comp.viridianGreenSite
    if not site then return end
    local lists={opaque,cutoutUnder,cutoutOver,cutoutKeyed}
    -- A front producer may prune its own tail before this finish hook. The
    -- saved pre-building vertex identity stays stable when earlier indices
    -- shift, whereas a saved list length does not.
    local firsts={}
    for li,list in ipairs(lists)do
      local sentinel=comp.viridianGreenSentinel[li]
      if sentinel then
        local found
        for i=#list,1,-1 do if list[i]==sentinel then found=i;break end end
        if not found then return end
        firsts[li]=found+1
      else firsts[li]=1 end
    end
    local front=comp.maxY+1
    -- Keep the old front, door and separately owned porch/garden work.
    -- Remove only this component's generic body/roof/chimney producer tail.
    local retained=0
    for li,list in ipairs(lists)do
      local first=firsts[li];local keep={}
      for i=first,#list,3 do
        local frontFace=true;local door=true;local foreground=true
        for j=i,i+2 do
          local v=list[j]
          if math.abs(v[3]-front)>.02001 or v[2]>comp.wallTopY+1e-8 or v[8]<.999999 then frontFace=false end
          if v[1]<comp.minX+1-1e-8 or v[1]>comp.minX+2+1e-8
            or v[2]>comp.groundY+1+1e-8 or v[3]<front-.13 or v[3]>front+.02001 then door=false end
          if v[3]<front+.02001 or v[2]>comp.groundY+1+1e-8 then foreground=false end
        end
        if frontFace or door or foreground or (list[i].viridianGardenPart and list[i+1].viridianGardenPart and list[i+2].viridianGardenPart) then
          for j=i,i+2 do keep[#keep+1]=list[j] end
          retained=retained+1
        end
      end
      for i=#list,first,-1 do list[i]=nil end
      for _,v in ipairs(keep)do list[#list+1]=v end
    end
    local emitted={roof=0,wall=0,chimney=0,soffit=0}
    local function emit(t)
      local minU,minV,maxU,maxV=math.huge,math.huge,-math.huge,-math.huge
      for _,p in ipairs(t.p)do
        minU=math.min(minU,p[4]);maxU=math.max(maxU,p[4]);minV=math.min(minV,p[5]);maxV=math.max(maxV,p[5])
      end
      local ux0,ux1=math.floor((minU+1e-8)/16),math.floor((maxU-1e-8)/16)
      local vy0,vy1=math.floor((minV+1e-8)/16),math.floor((maxV-1e-8)/16)
      if ux1<ux0 then ux1=ux0 end;if vy1<vy0 then vy1=vy0 end
      for cy=vy0,vy1 do for cx=ux0,ux1 do
        local poly=t.p
