          if #poly>0 then poly=greenClip(poly,h[1],h[2],h[3]) end
        end
        if #poly>=3 then
          local srcZ=t.material=='wall' and 8 or site.native.z
          local cell=at(24+cx,srcZ+cy)
          local over=t.material=='roof' or cy<3
          local r=cell and (over and overRect(cell.mid) or underRect(cell.mid))
          local list=over and cutoutOver or opaque
          if r then
            local vs={}
            for _,v in ipairs(poly)do
              vs[#vs+1]={24+v[1]/16,comp.groundY+v[2]/16,site.native.z+v[3]/16,
                r[1]+(r[3]-r[1])*(v[4]-cx*16)/16,
                r[2]+(r[4]-r[2])*(v[5]-cy*16)/16,t.n[1],t.n[2],t.n[3]}
            end
            for j=2,#vs-1 do
              local a,b,c=vs[1],vs[j],vs[j+1]
              local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
              local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
              local dot=(uy*vz-uz*vy)*t.n[1]+(uz*vx-ux*vz)*t.n[2]+(ux*vy-uy*vx)*t.n[3]
              if math.abs(dot)>1e-12 then
                if dot<0 then b,c=c,b end
                for _,v in ipairs{a,b,c}do
                  vN(list,v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8])
                  list[#list].viridianGreenPart=t.tag
                end
                emitted[t.material]=emitted[t.material]+1
              end
            end
          end
        end
      end end
    end
    for _,t in ipairs(greenParts)do
      if t.material=='roof' and (t.tag=='green.slope_n' or t.tag=='green.hip_w_north'
          or t.tag=='green.hip_e_north' or t.tag=='green.cap' or t.tag=='green.ridge_end') then
        -- User-approved uniform green: rear slope/spine reuse the front's
        -- clean native rib strip, with identical shape and horizontal phase.
        local q={p={},n=t.n,tag=t.tag,material=t.material}
        for _,v in ipairs(t.p)do q.p[#q.p+1]={v[1],v[2],v[3],v[4],v[5]+15}end
        emit(q)
      else emit(t) end
    end
    -- Same physical roof shell used for chimney footing and consumer query.
    local R=greenRoof
    comp.roofAt=function(px,pz)
      local x,z=(px-24)*16,(pz-site.native.z)*16
      local s=math.min((x-R.x0)/8,(R.x1-x)/8,
        (z-R.zb)/(R.zrb-R.zb),(R.zf-z)/(R.zf-R.zrf))
      local y=R.ye+(R.yr-R.ye)*math.max(0,math.min(1,s))
      if x>=R.x0+8 and x<=R.x1-8 and z>=R.zrb and z<=R.zrf then y=R.yt end
      return comp.groundY+y/16
    end
    comp.chimneyBoxes=nil
    local co0,cv0=#opaque,#cutoutOver
    comp.viridianGreenR2=site.native.z
    local _,chimneys=roofChimneys(comp,nil,comp.roofAt,
      site.native.z+R.zb/16,site.native.z+R.zf/16)
    comp.viridianGreenR2=nil
    -- The native roof only exposes the chimney front and grille. Remove both
    -- generic hidden-return layers (the gray UNDER and partial OVER) and
    -- replace them with ONE clean brown skin from the chimney's own opaque
    -- body rows 32..38. The original top and front triangles remain exact.
    local box=comp.chimneyBoxes and comp.chimneyBoxes[1]
    if box then
      local dc=at(27,site.native.z+1)
      local dr=dc and overRect(dc.mid)
      if dr then
        local function hidden(v) return v[8]<-.9 or math.abs(v[6])>.9 end
        local function prune(list,first)
          local keep={}
          for i=first,#list,3 do
            if not hidden(list[i]) then
              for j=i,i+2 do keep[#keep+1]=list[j] end
            end
          end
          for i=#list,first,-1 do list[i]=nil end
          for _,v in ipairs(keep)do list[#list+1]=v end
        end
        prune(opaque,co0+1);prune(cutoutOver,cv0+1)
        local uv=subRect(dr,2/16,7/16,14/16,15/16)
        local x0,x1,z0,z1,y0,y1=box.x0,box.x1,box.z0,box.z1,box.y0,box.y1
        quad(cutoutOver,{x1,y1,z0},{x0,y1,z0},{x0,y0,z0},{x1,y0,z0},uv,N_N)
        quad(cutoutOver,{x0,y1,z0},{x0,y1,z1},{x0,y0,z1},{x0,y0,z0},uv,N_W)
        quad(cutoutOver,{x1,y1,z1},{x1,y1,z0},{x1,y0,z0},{x1,y0,z1},uv,N_E)
      end
    end
    local opaqueChimney=(#opaque-co0)/3
    local overChimney=(#cutoutOver-cv0)/3
    emitted.chimney=opaqueChimney+overChimney
    local chimneyTop=comp.groundY+R.yt/16
    for i=co0+1,#opaque do chimneyTop=math.max(chimneyTop,opaque[i][2]) end
    for i=cv0+1,#cutoutOver do chimneyTop=math.max(chimneyTop,cutoutOver[i][2]) end
    -- Narrow native gray-header soffit, only under the 2/3 pixel overhang.
    local soffitCell=at(24,site.native.z+2)
    local sr=soffitCell and overRect(soffitCell.mid)
    if sr then
      local uv=subRect(sr,5/16,14.5/16,6/16,14.5/16)
      local x0,x1=24-2/16,24+82/16
      local z0,z1=site.native.z+R.zb/16,site.native.z+R.zf/16
      local y=comp.groundY+20/16
      local back,front=site.native.z+1,site.native.z+4
      for _,q in ipairs{{x0,x1,z0,back},{x0,x1,front,z1},{x0,24,back,front},{29,x1,back,front}}do
        local a,b,c,d=q[1],q[2],q[3],q[4]
        if b>a and d>c then
