            local b, l, r = at(x, yy + 1), at(comp.minX, yy + 1), at(comp.maxX, yy + 1)
            return b ~= nil and b.walkable and l ~= nil and not l.walkable and r ~= nil and not r.walkable
          end
          for pass = 1, wtier <= 2 and 2 or 0 do
            local pc = {}
            for i = 1, #bands do
              local b = bands[i]
              if (pass == 1) == (i == 1) and not b.filler then
                for x = comp.minX, comp.maxX do
                  local c = at(x, b.rowY)
                  if c and (isCompCell(c, comp) or (c.isSign and not c.blocksForBlob)) and not c.isDoor
                      and not (wide and (x == comp.minX or x == comp.maxX)) and not (i == 1 and lintel(x, b.rowY)) then
                    local u = tex(c.mid, "under")
                    if u then
                      pc[#pc + 1] = { { c = c, u = u, o = c.hasOver and tex(c.mid, "over") or nil },
                        i == topI and eave or 0, i == 1 and 12 or 15, pass == 1 and doorMask(x, b.rowY) or nil }
                    end
                  end
                end
              end
            end
            if #pc > 0 then P, flat = plainPatch(pc, W, okP) end
            if P or flat then break end
          end
          local Pt
          local pr = P and (P.over and overRect(P.rec.c.mid) or underRect(P.rec.c.mid))
          if pr then
            local u0, u1 = P.x0 / 16, (P.x1 + 1) / 16
            local v0, v1 = P.y0 / 16, (P.y1 + 1) / 16
            if P.cu then u0 = (P.x0 + 0.5) / 16; u1 = u0 end
            if P.cv then v0 = (P.y0 + 0.5) / 16; v1 = v0 end
            Pt = { P.over and cutoutOver or opaque, subRect(pr, u0, v0, u1, v1),
              tw = (P.x1 - P.x0 + 1) / 16, th = (P.y1 - P.y0 + 1) / 16, cu = P.cu, cv = P.cv,
              info = { mid = P.rec.c.mid, layer = P.over and "over" or "under", x0 = P.x0, x1 = P.x1,
                y0 = P.y0, y1 = P.y1, cu = P.cu, cv = P.cv, colors = P.colors, brick = P.brick or nil } }
            if P.brick then IN.wallA.stats.brick = IN.wallA.stats.brick + 1 end
          end
          -- (roofs-sides A: how W was found -- tier 1 the ground floor's wall,
          -- 2 an upper band, 3 any row, 4 a roof / rock colour, 5 a flat
          -- last resort -- and the colour the filter turned down, if any)
          local note = "tier" .. wtier .. (wnote and (" " .. wnote) or "")
          if wnote then IN.wallA.stats.notes = IN.wallA.stats.notes + 1 end
          local Ss = skirt and sampleOf(skirt.color, { 1 })
          if Ss then
            Ss.lo, Ss.hi, Ss.color = skirt.lo, skirt.hi, skirt.color
            Ss.trim = {}
            for _, t in ipairs(skirt.trim) do
              local r = t.over and overRect(t.rec.c.mid) or underRect(t.rec.c.mid)
              if r then Ss.trim[#Ss.trim + 1] = { t.over and cutoutOver or opaque,
                subRect(r, (t.x + 0.5) / 16, (t.y + 0.5) / 16, (t.x + 0.5) / 16, (t.y + 0.5) / 16),
                lo = (15 - t.y) / 16, hi = (16 - t.y) / 16 } end
            end
            if #Ss.trim ~= #skirt.trim then Ss = nil end
          end
          return { W = Ws, T = Ts, P = Pt, S = Ss, eave = eave, wColor = W, tColor = Ts and tb or nil, note = note, tier = wtier }
        end)()
        -- (posts: the eave rows cropped off the top band's corner posts)
        if out.plain and out.plain.eave > 0 then
          for i, b in ipairs(bands) do
            if not b.filler and out.posts[i] and i == #bands then
              for k, pst in pairs(out.posts[i]) do
                if not pst.copied then pst[2] = subRectV(pst[2], out.plain.eave / 16, 1) end
              end
            end
          end
        end
      end
      local function pickRow(yy)
        local cnt, pick = {}, nil
        for x = xa, xb do
          local c = plainAt(x, yy)
          if c and not c.isDoor and not c.isSign and groundFree(c) then
            cnt[c.mid] = (cnt[c.mid] or 0) + 1
            if not pick or cnt[c.mid] > cnt[pick.mid]
                or (cnt[c.mid] == cnt[pick.mid] and math.abs(x - midX) < math.abs(pick.x - midX)) then
              pick = c
            end
          end
        end
        return pick
      end
      local best, any = {}, nil
      for i, b in ipairs(bands) do best[i] = pickRow(b.rowY) end
      for yy = comp.maxY, comp.minY, -1 do
        any = any or pickRow(yy)
      end
      local overCell
      for yy = comp.maxY, comp.minY, -1 do
        for x = xa, xb do
          local c = at(x, yy)
          if not overCell and isCompCell(c, comp) and c.hasOver and (overCoverage(c.mid) or 0) >= 0.5 then overCell = c end
        end
      end
      for i = 1, #bands do
        local v = best[i]
        if not v then
          for dist = 1, #bands do
            v = best[i - dist] or best[i + dist]
            if v then break end
          end
        end
        v = v or any
        if out[i] then
          -- (the plaster slice above)
        elseif v then
          local r = tileUv(v)
          out[i] = { opaque, plainCrop(r), r }
        elseif overCell and overRect(overCell.mid) then
          -- the facade's own over art (harbour walls), never water
          local r = overRect(overCell.mid)
          out[i] = { cutoutOver, plainCrop(r), r }
        elseif comp.roofCell and underRect(comp.roofCell.mid) then
          -- the roof trim: its top texel row, stretched
          local r = subRect(underRect(comp.roofCell.mid), 0, 0, 1, 1 / 16)
          out[i] = { opaque, r, r }
        else
          -- a neutral wall colour: one texel of the building's middle cell
          local c = at(math.floor(midX), comp.maxY) or comp.cells[1]
          local r = subRect(tileUv(isCompCell(c, comp) and c or comp.cells[1]), 0.5, 0.25, 0.5 + 1 / 16, 0.25 + 1 / 16)
          out[i] = { opaque, r, r }
        end
      end
      return out
    end)()
    do
      local p=comp.nativeBuildingProfile
      local s=p and p.nativeSideSample
      if s then
        local r=s.layer=="over" and overRect(s.mid) or underRect(s.mid)
        local t=atlas.texels(s.mid,s.layer)
        assert(r and t and t[s.y*16+s.x+1]>=0,"guarded side sample missing")
        local uv=subRect(r,(s.x+.5)/16,(s.y+.5)/16,(s.x+.5)/16,(s.y+.5)/16)
        sideArt.plain={W={s.layer=="over" and cutoutOver or opaque,uv},wColor=t[s.y*16+s.x+1],eave=0,note="native-blank-facade",tier=1}
      end
    end
    local function bandUv(r, band)
      if band.filler then return subRectV(r, 0, (band.y1 - band.y0) / C.WALL_ROW_UNIT) end
      return r
    end

    -- M14: a facade cell whose art is (almost) all over art has ground as
    -- its under art: its base comes from the nearest plain cell in the row.
    local function nearestPlainInRow(x, yy)
      for dist = 1, comp.maxX - comp.minX do
        local c = plainAt(x - dist, yy) or plainAt(x + dist, yy)
        if c then return c end
      end
      return nil
    end
    local function facadeArt(x, band)
      local c = at(x, band.rowY)
      if isCompCell(c, comp) then
        local ov = c.hasOver and overRect(c.mid) or nil
        local cov = c.hasOver and (overCoverage(c.mid) or 1) or 0
        local base
        if ov and cov >= C.FACADE_ROOF_COVERAGE then
          local p = nearestPlainInRow(x, band.rowY)
          base = p and tileUv(p) or plainCrop(tileUv(westT[1]))
        else
          base = tileUv(c)
        end
        return base, ov
      elseif c and c.facadeOf == comp and band.rowY == comp.maxY then
        return underRect(c.mid), c.hasOver and overRect(c.mid) or nil
      end
      return nil
    end

    local function facesOtherBuilding(nx, ny)
      local nc = at(nx, ny)
      local ncomp = compOf(nc)
      if ncomp and ncomp.kind == "building" and ncomp ~= comp
        and ((ncomp.nativeBuildingProfile and ncomp.nativeBuildingProfile.name=='celadon-native-green-slab') or not (ncomp.fromBlock and not comp.flatHouse)) then return true end
      -- 25d r2 (the Cinnabar PC | Mart join): a neighbour's facade SIGN / DOOR
      -- cell is that building (the Mart's "MART" sign cell beside the PC)
      if C.FOLD_25D ~= false and nc and not ncomp then
        local oc = nc.facadeOf or nc.doorOf
        if oc and oc ~= comp and oc.kind == "building" then return true end
      end
      -- r11 (review M1): a block column at least as tall hides this wall
      local nrun = nc and blockRunOf[nc]
      return nrun ~= nil and nrun.top >= comp.wallTopY - EPS
    end

    -- A touching building still controls fold/eave attachment. Its lower
    -- top only hides the wall below that height, not the exposed upper band.
    grid.heightStep = function(nx, ny, lo, hi, owner)
      local self=owner or comp
      local nc = at(nx, ny)
      local other = compOf(nc)
      if not other and C.FOLD_25D ~= false and nc then other = nc.facadeOf or nc.doorOf end
      if other and other ~= self and other.kind == "building" and other.wallTopY then
        local profile=other.ov1
        local cover=profile and other.groundY+profile.Hs+(self.flatHouse and C.BULLNOSE_LIP or 0) or (other.nativeBuildingProfile and other.nativeBuildingProfile.nativeSeviiPurple and other.groundY+other.nativeBuildingProfile.nativeSeviiPurple.legacyWallHeight or other.wallTopY)
        -- OV wall postprocessing shifts positive rows down one source texel.
        local cut=cover+(self.ov1 and 1/16 or 0)
        if cut < hi-EPS then return math.max(lo,cut) end
      end
    end
    -- Clip only the new full-band triangles. Running the original emitter
    -- first preserves posts, folded side rows and native texture coordinates.
    grid.clipWallAbove = function(low, starts)
      for li, list in ipairs({ opaque, cutoutUnder, cutoutOver, cutoutKeyed }) do
        local out = {}
        for i = starts[li] + 1, #list, 3 do
          local poly = { list[i], list[i + 1], list[i + 2] }
          local cut = {}
          for j = 1, 3 do
            local a, b = poly[j], poly[j % 3 + 1]
            local ia, ib = a[2] >= low, b[2] >= low
            if ia then cut[#cut + 1] = a end
            if ia ~= ib then
              local t, v = (low - a[2]) / (b[2] - a[2]), {}
              for k = 1, 8 do v[k] = a[k] + t * (b[k] - a[k]) end
              v[2] = low
              cut[#cut + 1] = v
            end
          end
          for j = 2, #cut - 1 do
            local a, b, c = cut[1], cut[j], cut[j + 1]
            local ux, uy, uz = b[1] - a[1], b[2] - a[2], b[3] - a[3]
            local vx, vy, vz = c[1] - a[1], c[2] - a[2], c[3] - a[3]
            local nx, ny, nz = uy * vz - uz * vy, uz * vx - ux * vz, ux * vy - uy * vx
            if nx * nx + ny * ny + nz * nz > 1e-20 then
              out[#out + 1], out[#out + 2], out[#out + 3] = a, b, c
            end
          end
        end
        for i = #list, starts[li] + 1, -1 do list[i] = nil end
        for _, v in ipairs(out) do list[#list + 1] = v end
      end
    end

    -- r11 (USER REPORT, roofs): GABLE or hip, from the roof art's side
    -- profile (roofEdgeShape on both edge columns of the roof rows, the
    -- overhang row included): hip where the rows vote hip, gable where they
    -- vote gable; with no side strips a house is a gable and PC / Mart art
    -- a hip. The gable end is plastered with one texel of the
    -- side wall's plaster column (sideArt.gable).
    comp.gable = (function()
      if type(atlas.texels) ~= "function" or (comp.flatRoof and comp.tall) or (comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeClippedNorth) then return false end
      if comp.maxX - comp.minX < 2 then return false end
      local _, gpal = groundTaint(comp.minX, comp.minY, comp.maxX, comp.maxY)
      local function rec(x, yy)
        local c = at(x, yy)
        local u = c and (isCompCell(c, comp) or c.overhangOf == comp) and atlas.texels(c.mid, "under")
        return u and { u = u, o = c.hasOver and atlas.texels(c.mid, "over") or nil, walk = c.walkable } or nil
      end
      -- every roof row votes (the overhang row too); a gable needs a
      -- gable vote and no hip vote
      local votes = {}
      -- (refs 14, v15-v17) the END STRIPS' art -- per side the texel rows
      -- with a strip, its mean start and width -- for the hip ends, and
      -- ROOF BREAKS: an inner cell boundary with an end strip on both sides
      -- (two attached houses drawn with two roofs: Saffron (41,35))
      local acc = { L = { s = 0, w = 0, n = 0 }, R = { s = 0, w = 0, n = 0 } }
      local brk = {}
      local function add(a, rows, yy)
        for y = 0, 15 do
          local r = rows[y]
          if r and r[2] >= 1 then
            a.s, a.w, a.n = a.s + r[1], a.w + r[2], a.n + 1
            local Y = yy * 16 + y
            if not a.y0 or Y < a.y0 then a.y0 = Y end
            if not a.y1 or Y > a.y1 then a.y1 = Y end
          end
        end
      end
      for yy = comp.nativeRoofStart or (comp.overhang and comp.minY - 1 or comp.roofTop), comp.roofBottom do
        local l, r = rec(comp.minX, yy), rec(comp.maxX, yy)
        local f = {}
        for x = comp.minX + 1, comp.maxX - 1 do f[#f + 1] = rec(x, yy) end
        if l and r and #f > 0 then
          local sh, sw = roofEdgeShape(l, r, f, gpal)
          if sh then
            votes[sh] = (votes[sh] or 0) + 1
            if sh == "hip" then comp.hipStrip = math.max(comp.hipStrip or 0, sw) end
            comp.endStrip = math.max(comp.endStrip or 0, sw)
          end
          local fc = roofFrontColours(f)
          add(acc.L, roofStripRows(l, fc, gpal, true), yy)
          add(acc.R, roofStripRows(r, fc, gpal, false), yy)
          for b = comp.minX + 2, comp.maxX - 1 do
            local ca, cb = rec(b - 1, yy), rec(b, yy)
            if ca and cb then
              local bk = brk[b] or { L = { s = 0, w = 0, n = 0 }, R = { s = 0, w = 0, n = 0 } }
              brk[b] = bk
              local ra, rb = roofStripRows(ca, fc, nil, false), roofStripRows(cb, fc, nil, true)
              local pa, pb = {}, {}
              for y = 0, 15 do
                if ra[y] and ra[y][2] >= 3 then pa[y] = ra[y] end
                if rb[y] and rb[y][2] >= 3 then pb[y] = rb[y] end
              end
              add(bk.L, pa, yy)
              add(bk.R, pb, yy)
            end
          end
        end
      end
      local function strip(a, outer, dir)
        if a.n < 4 then return nil end
        local st, w = a.s / a.n, math.min(a.w / a.n, 16 - a.s / a.n)
        if w < 1 then return nil end
        local xo = outer + dir * st
        return { xo = xo, xi = xo + dir * w, y0 = a.y0, y1 = a.y1, w = w }
      end
      comp.endArt = { L = strip(acc.L, comp.minX * 16, 1), R = strip(acc.R, comp.maxX * 16 + 16, -1) }
      comp.roofBreaks = nil
      -- (a break: both houses >= 3 cells wide, both strips as tall as the
      -- outer end strips -- not a logo in the roof (One Island), not a
      -- gate's pillars (Route 23))
      local need = math.max(4, 0.75 * math.min(acc.L.n, acc.R.n))
      local lastB = comp.minX
      for b = comp.minX + 3, comp.maxX - 2 do
        local bk = brk[b]
        if bk and bk.L.n >= need and bk.R.n >= need and b - lastB >= 3 then
          lastB = b
          comp.roofBreaks = comp.roofBreaks or {}
          comp.roofBreaks[#comp.roofBreaks + 1] = { x = b, L = strip(bk.L, b * 16, -1), R = strip(bk.R, b * 16, 1) }
        end
      end
      comp.hipVotes, comp.gableVotes = votes.hip or 0, votes.gable or 0
      -- r11 (v15: the gyms; ref 14): a long low roof whose art shades its
      -- sloped ends light / dark on >= 2 rows (Pewter's, Viridian's,
      -- Celadon's gyms, Cerulean's long houses) is a long HIP, not a slab;
      -- alike end strips (Oak's lab, Celadon's framed slabs) stay flat
      if comp.flatRoof then
        if (votes.gable or 0) >= 2 and (votes.hip or 0) == 0 then comp.flatRoof = false else return false end
      end
      -- r11 (refs 14, v15-v17): side strips ARE the roof's sloped ends --
      -- light on one side, dark on the other (Pallet's houses, the gyms)
      -- or alike (the PC, the Mart): a HIP roof whose ends reach in as far
      -- as the strips are wide (a long ridge)
      if (votes.hip or 0) + (votes.gable or 0) > 0 then return false end
      -- no side strips drawn (Viridian's green houses): a house is a gable,
      -- the general tileset's PC / Mart art keeps its hip
      return not (comp.roofCell and famOf(comp.roofCell.mid) == 1)
    end)()
    -- r11 (USER REPORT 2): a HIP roof whose art draws its sloping ends as
    -- side strips (the PC, the Mart) stands on ANGLED front corners: 45
    -- degree facets as wide as those strips (the chamfered corner tiles
    -- become real diagonal walls)
    -- (the PC / Mart only: their art family -- refs 05-07, v15 / v16)
    if comp.nativeBuildingProfile and (comp.nativeBuildingProfile.nativeSafariNorth
        or comp.nativeBuildingProfile.name=='safari-east' and comp.nativeBuildingProfile.flatRoof==true)then
      comp.flatRoof=true;comp.gable=false -- explicit native flat-deck correction, never infer pitch from end shading
    end
    if comp.flatHouse then comp.gable = false end -- (flat-top rollout: grid.flatTopRoof)
    comp.chamfer = nil
    if not comp.gable and not comp.flatRoof and (comp.hipVotes or 0) > 0 and comp.hipStrip
        and sideArt.posts and comp.maxX - comp.minX >= 2 and comp.roofCell and famOf(comp.roofCell.mid) == 1 then
      comp.chamfer = math.max(C.CHAMFER_MIN, math.min(C.CHAMFER_MAX, comp.hipStrip / 16))
    end
    grid.foldSetup(comp, bands, sideArt, facesOtherBuilding) -- 25d: the folded corners (or comp.fold = nil)
    grid.networkSetup(comp,bands,sideArt,facesOtherBuilding)
    grid.networkSideSetup(comp)
    comp.nativeViridianGarden=grid.viridianGardenGuard(comp,bands)
    -- r11 (refs 05 / 06): the EMBLEM BOX -- on a chamfered hip building
    -- (the PC, the Mart) the band above the door, in the door's column(s),
    -- holds a logo (a tile with no twin in its row, same or mirrored); it
    -- becomes a box EMBLEM_D proud of the eave, rising EMBLEM_RISE over the
    -- wall top into the roof row above (whose bottom rows draw its top)
    comp.emblem = nil
    if comp.chamfer and #bands == 2 and not bands[2].filler and type(atlas.texels) == "function" then
      comp.emblem = (function()
        local rowY = bands[2].rowY
        local function rec(c)
          local u = c and atlas.texels(c.mid, "under")
          return u and { u = u, o = c.hasOver and atlas.texels(c.mid, "over") or nil } or nil
        end
        local function doorColumn(x)
          local f = at(x, comp.maxY)
          return f and f.doorOf == comp
        end
        -- (a logo split over two tiles -- the Mart's 57 | 58 -- has its
        -- mirror half right beside the door column: that half joins it;
        -- a twin anywhere else makes the tile a window, not a logo)
        local set = {}
        for x = comp.minX + 1, comp.maxX - 1 do
          local c = at(x, rowY)
          if doorColumn(x) and isCompCell(c, comp) and not c.isDoor and not c.isSign then
            local r, far, near = rec(c), false, nil
            for xx = comp.minX, comp.maxX do
              local q = at(xx, rowY)
              if xx ~= x and not doorColumn(xx) and isCompCell(q, comp) then
                local rq = q.mid ~= c.mid and rec(q) or nil
                if q.mid == c.mid or (r and rq and mirrorOf(r, rq)) then
                  if math.abs(xx - x) == 1 and not near then near = xx else far = true end
                end
              end
            end
            if r and not far then
              set[x] = true
              if near and near > comp.minX and near < comp.maxX then set[near] = true end
            end
          end
        end
        local cols = {}
        for x = comp.minX + 1, comp.maxX - 1 do
          if set[x] then cols[#cols + 1] = x end
        end
        if #cols == 0 then return nil end
        local runs = {}
        for _, x in ipairs(cols) do
          local last = runs[#runs]
          if last and last[2] == x - 1 then last[2] = x else runs[#runs + 1] = { x, x } end
        end
        return { runs = runs, at = set }
      end)()
    end

    grid.ov1Setup(comp)
    if comp.projectEntrance then comp.entranceStarts={#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed}end
    -- (gym flat) the list lengths before this gym's generic walls: grid.gymBuild cuts back to them
    if comp.gymFlat then comp.gymMark={#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed,#grid.ov1Deferred} end
    -- Front (south) wall.
    local trimUv
    do
    local bz1 = comp.deptBays and bz1 - 5/16 or bz1
    for x = comp.minX, comp.maxX do
      local fc = at(x, comp.maxY)
      local doorCol = fc and fc.doorOf == comp
      local below = at(x, comp.maxY + 1)
      local legacyDoor = below and below.isDoor
      for bi, band in ipairs(bands) do
        local y0, y1 = groundY + band.y0, groundY + band.y1
        if bi == 1 and doorCol then
          -- M5: door art recessed DOOR_INSET into the footprint, with jambs
          -- and a lintel underside.
          local zr = bz1 - C.DOOR_INSET
          local duv = underRect(fc.mid) or tileUv(westT[1])
          wallQuad(opaque, x, zr, x + 1, zr, y0, y1, duv, { 0, 0, 1 })
          if fc.hasOver then
            local dov = overRect(fc.mid)
            if dov then wallQuad(cutoutOver, x, zr + C.FACADE_OVER_LIFT, x + 1, zr + C.FACADE_OVER_LIFT, y0, y1, dov, { 0, 0, 1 }) end
          end
          -- (r11 review M6: the jamb shows the ground-free side art)
          local sa1 = sideArt[1]
          local jamb = sa1 and sa1[2] or subRect(tileUv(westT[1]), 0.3, 0, 0.3 + C.DOOR_INSET, 1)
          -- r9 (review 9): a door in a corner column has the side wall on
          -- that jamb's plane: skip the jamb there (the wall closes it)
          local sideW = x == comp.minX and not facesOtherBuilding(comp.minX - 1, comp.maxY)
          local sideE = x == comp.maxX and not facesOtherBuilding(comp.maxX + 1, comp.maxY)
          -- r11 (review R3): a double door (Saffron (34..35,5)) has one
          -- opening: no jamb between its two door cells
          local dW, dE = at(x - 1, comp.maxY), at(x + 1, comp.maxY)
          if dW and dW.doorOf == comp then sideW = true end
          if dE and dE.doorOf == comp then sideE = true end
          local jl = sa1 and sa1[1] or opaque
          if not sideW then wallQuad(jl, x, zr, x, bz1, y0, y1, jamb, { 1, 0, 0 }) end
          if not sideE then wallQuad(jl, x + 1, bz1, x + 1, zr, y0, y1, jamb, { -1, 0, 0 }) end
          quad(jl, { x, y1, zr }, { x, y1, bz1 }, { x + 1, y1, bz1 }, { x + 1, y1, zr }, jamb, DOWN)
        elseif comp.deptBays and grid.deptFront(comp, x, bi, band, groundY) then
        elseif not (bi == 1 and legacyDoor) and not (bi == 2 and comp.emblem and comp.emblem.at[x] and not comp.ov1) then
          local base, ov = facadeArt(x, band)
          base = base or grid.museumCleanCanopyWall(comp,x,band) or plainCrop(tileUv(westT[bi]))
          if band.filler then base, ov = bandUv(base, band), nil end
          local cw = comp.chamfer
          if comp.nativeDoorless==2 and comp.partialFacade and sideArt.plain then
            -- Occluded rear body: use the existing native stucco enclosure,
            -- leaving the only visible window-top pixels in the partial strip.
            -- Emitted after sideArt.wallFn is prepared below.
          elseif grid.viridianGardenFront(comp,x,band,base,ov,y0,y1,bz1) then
          elseif grid.networkFront(comp,x,bi,base,ov,y0,y1) then
          elseif comp.fold and grid.foldFront(comp, x, bi, base, ov, y0, y1) then -- 25d: a folded / attached corner
          elseif cw and (x == comp.minX or x == comp.maxX) and not facesOtherBuilding(x == comp.minX and x - 1 or x + 1, comp.maxY) then
            -- r11 (USER REPORT 2): the corner's first cw of art on a 45
            -- degree facet, the rest flat
            local lf = C.FACADE_OVER_LIFT * 0.7071
            if x == comp.minX then
              wallQuad(opaque, x + cw, bz1, x + 1, bz1, y0, y1, subRect(base, cw, 0, 1, 1), { 0, 0, 1 })
              wallQuad(opaque, x, bz1 - cw, x + cw, bz1, y0, y1, subRect(base, 0, 0, cw, 1), { -0.7071, 0, 0.7071 })
              if ov then
                local zf = bz1 + C.FACADE_OVER_LIFT
                wallQuad(cutoutOver, x + cw, zf, x + 1, zf, y0, y1, subRect(ov, cw, 0, 1, 1), { 0, 0, 1 })
                wallQuad(cutoutOver, x - lf, bz1 - cw + lf, x + cw - lf, bz1 + lf, y0, y1, subRect(ov, 0, 0, cw, 1), { -0.7071, 0, 0.7071 })
              end
            else
              wallQuad(opaque, x, bz1, x + 1 - cw, bz1, y0, y1, subRect(base, 0, 0, 1 - cw, 1), { 0, 0, 1 })
              wallQuad(opaque, x + 1 - cw, bz1, x + 1, bz1 - cw, y0, y1, subRect(base, 1 - cw, 0, 1, 1), { 0.7071, 0, 0.7071 })
              if ov then
                local zf = bz1 + C.FACADE_OVER_LIFT
                wallQuad(cutoutOver, x, zf, x + 1 - cw, zf, y0, y1, subRect(ov, 0, 0, 1 - cw, 1), { 0, 0, 1 })
                wallQuad(cutoutOver, x + 1 - cw + lf, bz1 + lf, x + 1 + lf, bz1 - cw + lf, y0, y1, subRect(ov, 1 - cw, 0, 1, 1), { 0.7071, 0, 0.7071 })
              end
            end
          else
            wallQuad(opaque, x, bz1, x + 1, bz1, y0, y1, base, { 0, 0, 1 })
            if ov then
              local zf = bz1 + C.FACADE_OVER_LIFT
              wallQuad(cutoutOver, x, zf, x + 1, zf, y0, y1, ov, { 0, 0, 1 })
            end
          end
        end
      end
    end
    end -- scoped Dept front plane
    -- (refs 05 / 06) the emblem box (comp.emblem): its front shows the
    -- logo tile over the band and the roof cell's bottom EMBLEM_RISE above
    -- the wall top; sides and top one texel row / column of that art; an
    -- underside over the door; a back above the wall top (inner function:
    -- locals limit)
    if comp.ov1 then comp.ov1.emblem={{#opaque},{#cutoutOver}} end
    if comp.ov1 and comp.ov1.kind=="K02" then grid.ov1Logo(comp)
    elseif comp.emblem then (function()
      local band = bands[2]
      local y0, y1 = groundY + band.y0, groundY + band.y1
      if comp.ov1 then y1=groundY+comp.ov1.Hs+C.BULLNOSE_LIP+comp.ov1.r;y0=y1-1 end
      -- Source34..47 keeps its native 14-pixel height, aligned with the
      -- ordinary facade. Connected stepped rows30..33 complete the peak.
      if comp.centerPaint then y1=groundY+29/16;y0=groundY+15/16 end
      local rise=comp.centerPaint and 2/16 or C.EMBLEM_RISE
      local yT = y1 + rise
      local zf = bz1 + (comp.ov1 and comp.ov1.df or C.EAVE_OVERHANG) + (comp.projectEntrance and 0 or C.EMBLEM_D)
      -- r12 (review: "the emblem top showing on the slope above the box"):
      -- above the wall top the box stands in FRONT of the eave only -- its
      -- top, back and upper sides from the eave's front line zb to zf; the
      -- part behind zb (under the overhang) poked through the slope
      local zb = bz1 + (comp.ov1 and comp.ov1.df or C.EAVE_OVERHANG) - (comp.projectEntrance and C.EMBLEM_D or 0)
      local vr = rise / C.WALL_ROW_UNIT
      local lift = C.FACADE_OVER_LIFT
      for _, run in ipairs(comp.emblem.runs) do
        local xa, xb = run[1], run[2] + 1
        for x = run[1], run[2] do
          local base, ov = facadeArt(x, band)
          base = base or plainCrop(tileUv(westT[#westT]))
          local up = at(x, band.rowY - 1)
          local ua = artOf(isCompCell(up, comp) and up or nil, base)
          -- the upper art: its list and rect (over art when solid)
          local ul, ur = opaque, ua.base
          if ua.mode == "over-solid" then ul, ur = cutoutOver, ua.over end
          ur = ur or base
          local uov = ua.mode == "composite" and ua.over or nil
          wallQuad(opaque, x, zf, x + 1, zf, y0, y1, comp.centerPaint and subRectV(base,2/16,1) or base, N_S)
          if ov then wallQuad(cutoutOver, x, zf + lift, x + 1, zf + lift, y0, y1, comp.centerPaint and subRectV(ov,2/16,1) or ov, N_S) end
          if comp.centerPaint then grid.centerPeak(comp,x,zf,zb,y1+2/16,ur,base) else
          wallQuad(ul, x, zf, x + 1, zf, y1, yT, subRectV(ur, 1 - vr, 1), N_S)
          if uov then wallQuad(cutoutOver, x, zf + lift, x + 1, zf + lift, y1, yT, subRectV(uov, 1 - vr, 1), N_S) end
          end
          if comp.ov1 then wallQuad(opaque,x+1,zb,x,zb,y0,y1,comp.ov1.hidden,N_N) end
          -- back above the wall top, on the eave's front line (seen over
          -- the eave)
          if not comp.centerPaint then wallQuad(ul, x + 1, zb, x, zb, y1, yT, subRectV(ur, 1 - vr, 1), N_N) end
          -- top: the upper art's first used row; underside: the logo
          -- tile's bottom row
          -- (one texel of the upper art: a flat roof-coloured top, not a
          -- pale grid row across the eave -- review of the side-by-sides)
          local tv = 1 - vr * 0.5
          if not comp.centerPaint then hQuad(ul, x, zb, x + 1, zf, yT, subRect(ur, 0.5, tv, 0.5, tv)) end
          quad(opaque, { x, y0, bz1 }, { x, y0, zf }, { x + 1, y0, zf }, { x + 1, y0, bz1 },
            subRect(base, 0, 15.5 / 16, 1, 15.5 / 16), DOWN)
          -- sides: the edge texel column of each part
          -- (no side against a neighbour's wall in front of the facade:
          -- Saffron's Mart beside the block at (38,22))
          if x == run[1] and not facesOtherBuilding(xa - 1, comp.maxY + 1) then
            local cu = 0.5 / 16
            wallQuad(opaque, xa, bz1, xa, zf, y0, y1, subRect(base, cu, comp.centerPaint and 2/16 or 0, cu, 1), N_W)
            if not comp.centerPaint then wallQuad(ul, xa, zb, xa, zf, y1, yT, subRect(ur, cu, 1 - vr, cu, 1), N_W) end
          end
          if x == run[2] and not facesOtherBuilding(xb, comp.maxY + 1) then
            local cu = 15.5 / 16
            wallQuad(opaque, xb, zf, xb, bz1, y0, y1, subRect(base, cu, comp.centerPaint and 2/16 or 0, cu, 1), N_E)
            if not comp.centerPaint then wallQuad(ul, xb, zf, xb, zb, y1, yT, subRect(ur, cu, 1 - vr, cu, 1), N_E) end
          end
        end
      end
    end)() end

    if comp.ov1 then comp.ov1.emblem[1][2]=#opaque;comp.ov1.emblem[2][2]=#cutoutOver end
    -- Legacy: a door cell just south of the footprint gets jambs + lintel
    -- (Rev 2 pattern; used only when the door is outside the footprint).
    for x = comp.minX, comp.maxX do
      local outCell = at(x, comp.maxY + 1)
      local dk = outCell and ((comp.maxY + 1) * 100000 + x)
      if outCell and outCell.isDoor and not doorEmitted[dk] then
        doorEmitted[dk] = true
        local dUv = underRect(outCell.mid) or tileUv(westT[1])
        local dGround = outCell.hgt
        local jH, inset = C.WALL_ROW_UNIT, C.DOOR_INSET
        local dx0, dx1, dz0, dz1 = x + 0.0, x + 1.0, bz1, bz1 + 1.0
        wallQuad(cutoutUnder, dx0, dz0 + inset, dx0, dz1 - inset, dGround, dGround + jH, dUv, { -1, 0, 0 })
        wallQuad(cutoutUnder, dx1, dz1 - inset, dx1, dz0 + inset, dGround, dGround + jH, dUv, { 1, 0, 0 })
        hQuad(cutoutUnder, dx0 + inset, dz0 + inset, dx1 - inset, dz1 - inset, dGround + jH, dUv)
      end
    end

    -- r11 (v15: Pewter's gym): PORCH boxes -- each porch cell (see the
    -- classification) is a box one row tall in front of the facade with
    -- its own art in front, its edge columns on the sides and its top row
    -- on the top; no face toward the door (the door's jambs) or another
    -- porch cell (inner function: locals limit)
    if comp.porch then (function()
      local set = {}
      for _, c in ipairs(comp.porch) do set[c] = true end
      local _, gpal = groundTaint(comp.minX, comp.minY, comp.maxX, comp.maxY + 1)
      for _, c in ipairs(comp.porch) do
        -- the porch's own columns of the tile: at most 4 ground texels
        -- (the rest of the tile is the street each side of the porch)
        local c0, c1 = 0, 15
        local vr = {} -- per side column: its rows without the ground at its ends
        local u = type(atlas.texels) == "function" and atlas.texels(c.mid, "under") or nil
        if u and gpal then
          local o = c.hasOver and atlas.texels(c.mid, "over") or nil
          local solid = {}
          for tx = 0, 15 do
            local g = 0
            for ty = 0, 15 do
              local i = ty * 16 + tx + 1
              local v = (o and o[i] and o[i] >= 0) and o[i] or u[i]
              if gpal[v] then g = g + 1 end
            end
            solid[tx] = g <= 4
          end
          c0, c1 = nil, nil
          for tx = 0, 15 do
            if solid[tx] then
              c0 = c0 or tx
              c1 = tx
            end
          end
          -- (a side column's ground rows at its top / bottom end -- the
          -- street drawn below the porch base -- are cut off)
          for _, tx in ipairs({ c0, c1 }) do
            if tx then
              local function gr(ty)
                local i = ty * 16 + tx + 1
                local v = (o and o[i] and o[i] >= 0) and o[i] or u[i]
                return gpal[v]
              end
              local a, b = 0, 15
              while a < b and gr(a) do a = a + 1 end
              while b > a and gr(b) do b = b - 1 end
              vr[tx] = { a / 16, (b + 1) / 16 }
            end
          end
        end
        if c0 then
          local x0, x1, z0, z1 = c.x + c0 / 16, c.x + (c1 + 1) / 16, c.y + 0.0, c.y + 1.0
          local y0, y1 = groundY, groundY + C.WALL_ROW_UNIT
          local base0 = underRect(c.mid) or tileUv(westT[1])
          local base = subRect(base0, c0 / 16, 0, (c1 + 1) / 16, 1)
          local ov = c.hasOver and overRect(c.mid) or nil
          wallQuad(opaque, x0, z1, x1, z1, y0, y1, base, N_S)
          if ov then wallQuad(cutoutOver, x0, z1 + C.FACADE_OVER_LIFT, x1, z1 + C.FACADE_OVER_LIFT, y0, y1, subRect(ov, c0 / 16, 0, (c1 + 1) / 16, 1), N_S) end
          hQuad(opaque, x0, z0, x1, z1, y1, subRect(base0, c0 / 16, 0.5 / 16, (c1 + 1) / 16, 0.5 / 16))
          -- sides: the solid edge columns; none against the door cell (its
          -- jambs) or another porch cell when the box reaches the cell edge
          for _, sd in ipairs({ { -1, x0, N_W, (c0 + 0.5) / 16, c0 == 0 }, { 1, x1, N_E, (c1 + 0.5) / 16, c1 == 15 } }) do
            local nb = at(c.x + sd[1], c.y)
            if not (sd[5] and nb and (nb.isDoor or set[nb])) then
              local ci = sd[1] < 0 and c0 or c1
              local rv = vr[ci] or { 0, 1 }
              local col = subRect(base0, sd[4], rv[1], sd[4], rv[2])
              if sd[1] < 0 then wallQuad(opaque, sd[2], z0, sd[2], z1, y0, y1, col, sd[3])
              else wallQuad(opaque, sd[2], z1, sd[2], z0, y0, y1, col, sd[3]) end
            end
          end
        end
      end
    end)() end

    -- Side + back walls (M8). Front-corner segments show the full edge
    -- tile (mirrored so its outline sits at the corner); every other
    -- segment shows the tile's plain middle.
    if comp.route12Saved then
      local r=underRect(437)
      local q={opaque,subRect(r,0,12/16,1,1),tw=1,th=.25}
      sideArt.plain={W={opaque,subRect(r,.5,14.5/16,.5,14.5/16)},P=q,wColor=atlas.texels(437,'under')[14*16+9],tier=1,note='native Route12 brick repeat'}
      sideArt.posts=nil
    end
    -- r12: a plain wall segment -- W over the base trim T (bottom band)
    -- (on sideArt: M.build is at LuaJIT's local-variable limit)
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.museumSideParts then
      local r=underRect(comp.nativeBuildingProfile.name=='pewter-museum-main' and 681 or 667)
      sideArt.plain={W={opaque,subRect(r,12.5/16,8.5/16,12.5/16,8.5/16)},tier=1,eave=0,wColor=14075325,note="native museum siding"}
      sideArt.posts=nil -- generator owns the original clean corner-post strips
    end
    grid.ceruleanSidingPatch(comp,sideArt)
    grid.saffronSidingPatch(comp,sideArt)
    sideArt.wallFn = function(ax, az, bx, bz, y0, y1, n, bottom)
      if comp.nativeBuildingProfile and comp.nativeBuildingProfile.museumSideParts and y0<comp.wallTopY then
        -- Reuse the existing Emerald Tile/Prism/Band wall generator and the
        -- Network interval adapter. Only Museum-native material donors enter.
        local function clip(p,k,b,less)
          local out={};for i,a in ipairs(p)do local z=p[i%#p+1];local ia=less and a[k]<=b+1e-10 or not less and a[k]>=b-1e-10;local ib=less and z[k]<=b+1e-10 or not less and z[k]>=b-1e-10
            if ia then out[#out+1]=a end;if ia~=ib then local t=(b-a[k])/(z[k]-a[k]);local v={};for j=1,8 do v[j]=a[j]+t*(z[j]-a[j])end;v[k]=b;out[#out+1]=v end
          end;return out
        end
        local axis=n[1]~=0 and 3 or 1;local lo=axis==3 and math.min(az,bz)or math.min(ax,bx);local hi=axis==3 and math.max(az,bz)or math.max(ax,bx)
        for _,q in ipairs(comp.nativeBuildingProfile.museumSideParts)do if q.n[1]==n[1]and q.n[3]==n[3]then
          local r=underRect(q.mid);local p={}
          local minU,minV,maxV=1,1,0
          for _,v in ipairs(q.p)do minU=math.min(minU,v[4]);minV=math.min(minV,v[5]);maxV=math.max(maxV,v[5])end
          local main=comp.nativeBuildingProfile.name=='pewter-museum-main'
          local ulo,uhi=main and(minU>=11/16-1e-8 and 11.5/16 or 8.5/16)or(q.mid==667 and 8.5/16 or .5/16),main and(minU>=11/16-1e-8 and 12.5/16 or 10.5/16)or(q.mid==667 and 13.5/16 or 6.5/16)
          local vlo,vhi=.5/16,15.5/16
          if main and q.mid==673 then if minV<8/16-1e-8 and maxV<=9/16+1e-8 then vlo,vhi=7.5/16,8.5/16 else vlo=8.5/16 end end
          for _,v in ipairs(q.p)do
            local u=math.max(ulo,math.min(uhi,v[4]));local vv=math.max(vlo,math.min(vhi,v[5]))
            p[#p+1]={v[1],groundY+v[2],v[3],r[1]+u*(r[3]-r[1]),r[2]+vv*(r[4]-r[2]),n[1],n[2],n[3]}
          end
          p=clip(clip(clip(clip(p,axis,lo,false),axis,hi,true),2,y0,false),2,math.min(y1,comp.wallTopY),true)
          for j=2,#p-1 do local a,b,c=p[1],p[j],p[j+1];local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3];local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
            if(uy*vz-uz*vy)*n[1]+(uz*vx-ux*vz)*n[2]+(ux*vy-uy*vx)*n[3]>1e-12 then
              for _,v in ipairs{a,b,c}do local z={};for k=1,8 do z[k]=v[k]end;z[1]=z[1]+n[1]/4096;z[3]=z[3]+n[3]/4096;z.museumSideBand=true;opaque[#opaque+1]=z end
            end
          end
        end end
        if y1<=comp.wallTopY then return end;y0=comp.wallTopY;bottom=false
      end
      if comp.nativeNetworkSides and y0<comp.groundY+27/16 and grid.networkSideWall(comp,ax,az,bx,bz,y0,math.min(y1,comp.groundY+27/16),n)then
        if y1<=comp.groundY+27/16 then return end;y0=comp.groundY+27/16;bottom=false
      end
      local PW = sideArt.plain
      if comp.route12Saved then
        if n[1]~=0 and math.min(az,bz)==16 and math.max(az,bz)==17 then return end
        if n[3]==-1 and (ax==13 and bx==12 or ax==17 and bx==16) then az,bz=17,17 end
      end
      if comp.route12Saved and n[3]==-1 and ax==15 and bx==14 then
        y0=math.max(y0,groundY+2)
        if y1<=y0 then return end
      end
      local yt = y0
      if bottom and PW.S and PW.S.trim then
        yt = math.min(y1, groundY + PW.S.lo)
        for _, t in ipairs(PW.S.trim) do
          local lo, hi = math.max(y0, groundY + t.lo), math.min(y1, groundY + t.hi)
          if hi > lo then wallQuad(t[1], ax, az, bx, bz, lo, hi, t[2], n) end
        end
      elseif bottom and PW.T then
        yt = math.min(y1, y0 + C.SIDE_TRIM_H)
        wallQuad(PW.T[1], ax, az, bx, bz, y0, yt, PW.T[2], n)
      end
      local function body(lo, hi)
        if hi <= lo + 1e-6 then return end
        if PW.P then grid.tiledWall(PW.P, ax, az, bx, bz, lo, hi, n, groundY)
        else wallQuad(PW.W[1], ax, az, bx, bz, lo, hi, PW.W[2], n) end
      end
      local S = bottom and PW.S
      if S then
        local lo, hi = math.max(yt, groundY + S.lo), math.min(y1, groundY + S.hi)
        if hi > lo then
          body(yt, lo)
          wallQuad(S[1], ax, az, bx, bz, lo, hi, S[2], n)
          body(hi, y1)
        else body(yt, y1) end
      else body(yt, y1) end
    end
    -- 25d: a folded PC / Mart's side and back walls continue its corner's wall pattern
    if comp.fold and sideArt.plain then sideArt.wallFn = grid.foldSideFn(comp, sideArt.wallFn, groundY) end
    for bi, band in ipairs(bands) do
      local y0, y1 = groundY + band.y0, groundY + band.y1
      local wr = bandUv(tileUv(westT[bi]), band)
      local er = bandUv(tileUv(eastT[bi]), band)
      local wc, ec = plainCrop(wr), plainCrop(er)
      -- r11 (review M6): the ground-free side art on every segment
      local sa = sideArt[bi]
      local sl = sa and sa[1] or opaque
      if sa then wc, ec = bandUv(sa[2], band), bandUv(sa[2], band) end
      -- (the front corner too: the edge tile is corner art -- review M6)
      local wFront = { sl, wc }
      local eFront = { sl, ec }
      for x = comp.minX, comp.maxX do
        local blocked = facesOtherBuilding(x, comp.minY - 1)
        if blocked then
          grid.ov1EmitHeight(comp,x, comp.minY - 1,y0,y1,function(clipY)
          if sideArt.plain then sideArt.wallFn(x + 1, bz0, x, bz0, y0, y1, { 0, 0, -1 }, bi == 1)
          else wallQuad(sl, x + 1, bz0, x, bz0, y0, y1, wc, { 0, 0, -1 }) end
          end)
        else
          if sideArt.plain then sideArt.wallFn(x + 1, bz0, x, bz0, y0, y1, { 0, 0, -1 }, bi == 1)
          else wallQuad(sl, x + 1, bz0, x, bz0, y0, y1, wc, { 0, 0, -1 }) end
        end
      end
      -- (USER REPORT) the corner posts at both ends of each side wall:
      -- the post art mirrored so its outer edge is at the corner
      local posts = sideArt.posts and sideArt.posts[bi] or {}
      local function sideRowOriginal(xw, side, yy, n, heightStep)
        local za, zb = yy + 0.0, yy + 1.0
        if comp.deptBays and yy == comp.maxY then zb = zb - 5/16 end
        local post = posts[side]
        local fz0, fz1 = za, zb -- the plaster span
        -- An attached flat corner has no diagonal to meet. Newly exposed
        -- upper walls must reach its flat front, not the legacy chamfer cut.
        if ((comp.chamfer and not heightStep) or grid.foldD(comp, side, bi) > 0) and yy == comp.maxY then fz1, post = zb - grid.foldDepth(comp, side, bi), nil end
        if post and yy == comp.maxY then fz1 = zb - post[3] end
        if post and yy == comp.minY then fz0 = za + post[3] end
        if fz1 - fz0 < 0.05 then post = nil; fz0, fz1 = za, zb end
        local pr = post and bandUv(post[2], band)
        if sideArt.plain then
          -- (r12: the plain wall between the posts)
          if fz1 > fz0 then
            if side == 1 then sideArt.wallFn(xw, fz0, xw, fz1, y0, y1, n, bi == 1)
            else sideArt.wallFn(xw, fz1, xw, fz0, y0, y1, n, bi == 1) end
          end
          if post and yy == comp.maxY then
            if side == 1 then wallQuad(post[1], xw, fz1, xw, zb, y0, y1, mirror(pr), n)
            else wallQuad(post[1], xw, zb, xw, fz1, y0, y1, mirror(pr), n) end
          end
          if post and yy == comp.minY then
            if side == 1 then wallQuad(post[1], xw, za, xw, fz0, y0, y1, pr, n)
            else wallQuad(post[1], xw, fz0, xw, za, y0, y1, pr, n) end
          end
          return
        end
        if side == 1 then
          if fz1 > fz0 then wallQuad(sl, xw, fz0, xw, fz1, y0, y1, wc, n) end
          if post and yy == comp.maxY then wallQuad(post[1], xw, fz1, xw, zb, y0, y1, mirror(pr), n) end
          if post and yy == comp.minY then wallQuad(post[1], xw, za, xw, fz0, y0, y1, pr, n) end
        else
          if fz1 > fz0 then wallQuad(sl, xw, fz1, xw, fz0, y0, y1, ec, n) end
          if post and yy == comp.maxY then wallQuad(post[1], xw, zb, xw, fz1, y0, y1, mirror(pr), n) end
          if post and yy == comp.minY then wallQuad(post[1], xw, fz0, xw, za, y0, y1, pr, n) end
        end
      end
      local function sideRow(xw,side,yy,n,heightStep)
        if comp.networkFacade and yy==comp.maxY then
          grid.networkSide(comp,function()sideRowOriginal(xw,side,yy,n,heightStep)end)
        else sideRowOriginal(xw,side,yy,n,heightStep)end
      end
      for yy = comp.minY, comp.maxY do
        local front = yy == comp.maxY
        local blocked = facesOtherBuilding(comp.minX - 1, yy)
        if blocked then
          grid.ov1EmitHeight(comp,comp.minX - 1, yy,y0,y1,function(clipY)
          if sideArt.posts and sideArt[bi] then sideRow(bx0, 1, yy, { -1, 0, 0 }, clipY)
          elseif sideArt.plain then sideArt.wallFn(bx0, yy, bx0, yy + 1 - (yy == comp.maxY and grid.foldD(comp, "L", bi) or 0), y0, y1, { -1, 0, 0 }, bi == 1)
          elseif front then wallQuad(wFront[1], bx0, yy, bx0, yy + 1, y0, y1, wFront[2], { -1, 0, 0 })
          else wallQuad(sl, bx0, yy, bx0, yy + 1, y0, y1, wc, { -1, 0, 0 }) end
          end)
        else
          if sideArt.posts and sideArt[bi] then sideRow(bx0, 1, yy, { -1, 0, 0 }, nil)
          elseif sideArt.plain then sideArt.wallFn(bx0, yy, bx0, yy + 1 - (yy == comp.maxY and grid.foldD(comp, "L", bi) or 0), y0, y1, { -1, 0, 0 }, bi == 1)
          elseif front then wallQuad(wFront[1], bx0, yy, bx0, yy + 1, y0, y1, wFront[2], { -1, 0, 0 })
          else wallQuad(sl, bx0, yy, bx0, yy + 1, y0, y1, wc, { -1, 0, 0 }) end
        end
        local blocked = facesOtherBuilding(comp.maxX + 1, yy)
        if blocked then
          grid.ov1EmitHeight(comp,comp.maxX + 1, yy,y0,y1,function(clipY)
          if sideArt.posts and sideArt[bi] then sideRow(bx1, 2, yy, { 1, 0, 0 }, clipY)
          elseif sideArt.plain then sideArt.wallFn(bx1, yy + 1 - (yy == comp.maxY and grid.foldD(comp, "R", bi) or 0), bx1, yy, y0, y1, { 1, 0, 0 }, bi == 1)
          elseif front then wallQuad(eFront[1], bx1, yy + 1, bx1, yy, y0, y1, eFront[2], { 1, 0, 0 })
          else wallQuad(sl, bx1, yy + 1, bx1, yy, y0, y1, ec, { 1, 0, 0 }) end
          end)
        else
          if sideArt.posts and sideArt[bi] then sideRow(bx1, 2, yy, { 1, 0, 0 }, nil)
          elseif sideArt.plain then sideArt.wallFn(bx1, yy + 1 - (yy == comp.maxY and grid.foldD(comp, "R", bi) or 0), bx1, yy, y0, y1, { 1, 0, 0 }, bi == 1)
          elseif front then wallQuad(eFront[1], bx1, yy + 1, bx1, yy, y0, y1, eFront[2], { 1, 0, 0 })
          else wallQuad(sl, bx1, yy + 1, bx1, yy, y0, y1, ec, { 1, 0, 0 }) end
        end
      end
    end

    -- The mixed native cell's bottom four rows are facade, not another
    -- full storey. Keep them out of the full-band material/post inference.
    if comp.partialFacade then (function()
      local P = comp.partialFacade
      local firstRow=math.floor(P.v0*16+.5)
      local y0, y1 = wallTopY - P.height, wallTopY
      if comp.nativeDoorless==2 and sideArt.plain then
        for x=comp.minX,comp.maxX do sideArt.wallFn(x,bz1,x+1,bz1,groundY,y0,N_S,false) end
      end
      local function crop(uv)
        if not uv then return nil end
        local px, py = math.floor(uv[1] * atlas.w), math.floor(uv[2] * atlas.h)
        return { (px + .500001) / atlas.w, (py + firstRow + .500001) / atlas.h,
          (px + 15.499999) / atlas.w, (py + 15.499999) / atlas.h }
      end
      for x = comp.minX, comp.maxX do
        local c = at(x, P.row)
        local u, o = underRect(c.mid), c.hasOver and overRect(c.mid)
        -- One native pixel row per 1/16 wall unit keeps the full-width
        -- window UV phase identical to the existing facade below. Sampling
        -- row centers prevents a roof texel bleeding into the new strip.
        for row = firstRow, 15 do
          local lo = y1 - (row - firstRow + 1) * C.WALL_ROW_UNIT / 16
          local hi = lo + C.WALL_ROW_UNIT / 16
          local function rowRect(uv)
            if not uv then return nil end
            local v = (math.floor(uv[2] * atlas.h) + row + .5 + (row == 15 and -1e-6 or 1e-6)) / atlas.h
            return {uv[1], v, uv[3], v}
          end
          if u then wallQuad(opaque, x, bz1, x + 1, bz1, lo, hi, rowRect(u), N_S) end
          if o then wallQuad(cutoutOver, x, bz1 + C.FACADE_OVER_LIFT, x + 1, bz1 + C.FACADE_OVER_LIFT, lo, hi, rowRect(o), N_S) end
        end
      end
      if P.lowerRow then
        -- The upper half of 784..787 exactly matches native facade
        -- 752/753/755/756: it completes the rear window, not the front roof.
        for x=comp.minX,comp.maxX do
          local c=at(x,P.lowerRow)
          local function rows(list,uv,z)
            if not uv then return end
            for row=0,7 do
              local v=(math.floor(uv[2]*atlas.h)+row+.5)/atlas.h
              local hi=y1-(4+row)*C.WALL_ROW_UNIT/16
              wallQuad(list,x,z,x+1,z,hi-C.WALL_ROW_UNIT/16,hi,{uv[1],v,uv[3],v},N_S)
            end
          end
          rows(opaque,underRect(c.mid),bz1)
          if c.hasOver then rows(cutoutOver,overRect(c.mid),bz1+C.FACADE_OVER_LIFT) end
        end
      end
      local function body(ax, az, bx, bz, n, nx, ny, post, atFront, atBack)
        local blocked = facesOtherBuilding(nx, ny)
        local clipY = blocked and grid.heightStep(nx, ny, y0, y1)
        if not blocked or clipY then
          local starts = clipY and { #opaque, #cutoutUnder, #cutoutOver, #cutoutKeyed }
          local firstPost = post and ((n[1] < 0 and atBack) or (n[1] > 0 and atFront))
          local lastPost = post and ((n[1] < 0 and atFront) or (n[1] > 0 and atBack))
          local t0, t1 = firstPost and post[3] or 0, 1 - (lastPost and post[3] or 0)
          local function segment(t0, t1, material, rect)
            local xa, za = ax + (bx - ax) * t0, az + (bz - az) * t0
            local xb, zb = ax + (bx - ax) * t1, az + (bz - az) * t1
            if material then wallQuad(material, xa, za, xb, zb, y0, y1, rect, n)
            elseif sideArt.plain then sideArt.wallFn(xa, za, xb, zb, y0, y1, n, false)
            else wallQuad(opaque, xa, za, xb, zb, y0, y1, subRect(crop(underRect(745)), .5, 0, 1, 1), n) end
          end
          if t1 > t0 then segment(t0, t1) end
          if firstPost or lastPost then
            local pr = subRectV(post[2], P.v0, 1)
            if firstPost then segment(0, t0, post[1], atFront and mirror(pr) or pr) end
            if lastPost then segment(t1, 1, post[1], atFront and mirror(pr) or pr) end
          end
          if starts then grid.clipWallAbove(clipY, starts) end
        end
      end
      for x = comp.minX, comp.maxX do body(x + 1, bz0, x, bz0, N_N, x, comp.minY - 1) end
      for yy = comp.minY, comp.maxY do
        body(bx0, yy, bx0, yy + 1, N_W, comp.minX - 1, yy, sideArt.posts and sideArt.posts[#bands] and sideArt.posts[#bands][1], yy == comp.maxY, yy == comp.minY)
        body(bx1, yy + 1, bx1, yy, N_E, comp.maxX + 1, yy, sideArt.posts and sideArt.posts[#bands] and sideArt.posts[#bands][2], yy == comp.maxY, yy == comp.minY)
      end
    end)() end

    if comp.route12Saved then
      -- Native row16 outer cells are walkable eave owners. The body starts
      -- at row17 there; close its two inward step walls without enclosing them.
      grid.tiledWall(sideArt.plain.P,13,16,13,17,groundY,wallTopY,N_W,groundY)
      grid.tiledWall(sideArt.plain.P,16,17,16,16,groundY,wallTopY,N_E,groundY)
      for _,q in ipairs{{12,13},{16,17}}do
        local r=overRect(77)
        quad(cutoutOver,{q[1],wallTopY,16},{q[1],wallTopY,17},{q[2],wallTopY,17},{q[2],wallTopY,16},subRect(r,.5,.5,.5,.5),DOWN)
      end
      wallQuad(sideArt.plain.W[1],13,16,13,17,at(12,16).hgt,groundY,sideArt.plain.W[2],N_W)
      wallQuad(sideArt.plain.W[1],16,17,16,16,at(16,16).hgt,groundY,sideArt.plain.W[2],N_E)
    end
    -- r9 (review 4): walls start at groundY (the street in front). Where
    -- the ground behind / beside the house (or a front column) is lower, a
    -- plinth closes the slit from m = max(edge cell, outside cell) up to
    -- groundY -- below m the ground skirts already close it. Door columns
    -- and edges against another building get none.
    do
      -- r11 (review M6): the plinth shows the side art and reaches down to
      -- the LOWEST adjacent ground (the building's own cells draw no ground
      -- or skirts now), closing the Cerulean slit
      local pl0 = sideArt[1]
      local pr, plist = pl0 and pl0[2] or plainCrop(tileUv(westT[1])), pl0 and pl0[1] or opaque
      -- (r12: the plain wall's trim -- else W -- below a plain wall)
      if sideArt.plain then
        local q = sideArt.plain.T or sideArt.plain.W
        pr, plist = q[2], q[1]
      end
      if comp.fold and grid.foldPlinth(comp) then pr, plist = grid.foldPlinth(comp) end -- 25d
      local function plinth(ix, iy, ox, oy, ax, az, bx, bz, n)
        if comp.route12Saved then
          if n[1]~=0 and iy==16 then return end
          if n[3]==-1 and (ix==12 or ix==16)then iy,oy,az,bz=17,16,17,17 end
        end
        local ic, oc = at(ix, iy), at(ox, oy)
        local m = ic and ic.hgt or nil
        if oc and oc.hgt and (m == nil or oc.hgt < m) then m = oc.hgt end
        if m and m < groundY - 1e-4 then
          wallQuad(plist, ax, az, bx, bz, m, groundY,
            subRectV(pr, math.max(0, 1 - (groundY - m) / C.WALL_ROW_UNIT), 1), n)
        end
      end
      for x = comp.minX, comp.maxX do
        if not facesOtherBuilding(x, comp.minY - 1) then
          plinth(x, comp.minY, x, comp.minY - 1, x + 1, bz0, x, bz0, N_N)
        end
        local fc, below = at(x, comp.maxY), at(x, comp.maxY + 1)
        if not (fc and fc.doorOf == comp) and not (below and below.isDoor)
            and not facesOtherBuilding(x, comp.maxY + 1) then
          if not grid.foldPlinthFront(comp, x, plinth, bz1) then -- 25d
            plinth(x, comp.maxY, x, comp.maxY + 1, x, bz1, x + 1, bz1, N_S)
          end
        end
      end
      for yy = comp.minY, comp.maxY do
        if not facesOtherBuilding(comp.minX - 1, yy) then
          plinth(comp.minX, yy, comp.minX - 1, yy, bx0, yy, bx0, yy + 1 - (yy == comp.maxY and grid.foldD(comp, 'L') or 0), N_W)
        end
        if not facesOtherBuilding(comp.maxX + 1, yy) then
          plinth(comp.maxX, yy, comp.maxX + 1, yy, bx1, yy + 1 - (yy == comp.maxY and grid.foldD(comp, 'R') or 0), bx1, yy, N_E)
        end
      end
    end

    grid.ov1FinishWalls(comp)
    if comp.projectEntrance then grid.centerEntrance(comp,bz1)end
    if comp.ov1 then wallTopY=groundY+comp.ov1.Hs+C.BULLNOSE_LIP end
    -- M7 trim: the top texel row of the upper facade row's plain tile.
    do
      local topRow = comp.maxY - wallRows + 1
      local tc
      local mx = math.floor((comp.minX + comp.maxX) / 2)
      for dist = 0, comp.maxX - comp.minX do
        tc = plainAt(mx - dist, topRow) or plainAt(mx + dist, topRow)
        if tc then break end
      end
      tc = tc or westT[#westT]
      trimUv = subRect(tileUv(tc), 0, 0, 1, 1 / 16)
    end

    -- Eave rectangle (M13: reach further north over the walkable row that
    -- carries the roof's top art).
    local ex0, ex1 = bx0 - C.EAVE_OVERHANG, bx1 + C.EAVE_OVERHANG
    local ez0 = bz0 - (comp.overhang and math.max(C.EAVE_OVERHANG, C.ROOF_OVERHANG_PUSH) or C.EAVE_OVERHANG) - (comp.nativeRoofStart and 1 or 0)
    local ez1 = bz1 + C.EAVE_OVERHANG
    -- r11 (review R3): no overhang over a side that touches another
    -- building / block (attached houses: the two eaves were coplanar)
    local touch = {}
    for yy = comp.minY, comp.maxY do
      if facesOtherBuilding(comp.minX - 1, yy) then touch.left = true end
      -- The verified native fence is the Game Corner's roof-plan boundary,
      -- even after its false building ownership is removed. Keep the native
      -- roof/skylight mapping; the wall pass still sees an exposed side.
      local edge=at(comp.minX-1,yy)
      if comp.nativeBlueFenceRoofBoundary and edge and edge.nativeBlueFence then touch.left=true end
      if facesOtherBuilding(comp.maxX + 1, yy) then touch.right = true end
    end
    for xx = comp.minX, comp.maxX do
      if facesOtherBuilding(xx, comp.minY - 1) then touch.up = true end
    end
    if comp.ov1 then
      ex0,ex1=bx0-comp.ov1.ds,bx1+comp.ov1.ds
      ez0=bz0-(comp.centerPaint and comp.ov1.df or comp.overhang and C.ROOF_OVERHANG_PUSH or comp.ov1.df)
      ez1=bz1+comp.ov1.df
      if comp.ov1.lavenderRefinement and comp.overhang then ez0=ez0+1/16 end
      for xx=comp.minX,comp.maxX do if facesOtherBuilding(xx,comp.maxY+1) then touch.down=true end end
      if touch.down then ez1=bz1 end
    end
    -- (overhangs, Claude 2026-10-01; USER: "use your suggestion") the
    -- gyms (the corner-post art of C.FOLD_POSTS): the eave 4 texels out at
    -- the front and the back (the M13 push where it reaches further), 2 at
    -- the sides as drawn; none into a touching building
    if not comp.ov1 and not comp.k32 and grid.foldPost(comp) then
      ex0,ex1=bx0-2/16,bx1+2/16
      ez0=bz0-(comp.overhang and math.max(4/16,C.ROOF_OVERHANG_PUSH) or 4/16)
      ez1=bz1+4/16
      for xx=comp.minX,comp.maxX do if facesOtherBuilding(xx,comp.maxY+1) then touch.down=true end end
      if touch.down then ez1=bz1 end
    end
    if comp.gameCornice then ex0,ex1=comp.minX,comp.maxX+1 end
    if touch.left then ex0 = bx0 end
    if touch.right then ex1 = bx1 end
    if touch.up then ez0 = bz0 end
    -- (K32 r3) flush on all four sides: no eave until the user decides (OV-2)
    if comp.k32 then ex0, ex1, ez0, ez1 = bx0, bx1, bz0, bz1 end
    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeBikeShop then
      ex0,ex1,ez0,ez1=bx0,bx1,bz0,bz1
    end

    local roofSurface, roofSolid = 0, 0
    local function emitArt(art, fn)
      local o0, c0 = #opaque, #cutoutOver
      if art.mode == "over-solid" and art.over then
        fn(cutoutOver, art.over, 0)
        roofSolid = roofSolid + (#cutoutOver - c0) / 3
        roofSurface = roofSurface + (#cutoutOver - c0) / 3
      elseif art.mode == "composite" and art.over then
        if art.base then fn(opaque, art.base, 0) end
        local o1 = #opaque
        fn(cutoutOver, art.over, C.ROOF_OVER_LIFT)
        roofSolid = roofSolid + (o1 - o0) / 3
        roofSurface = roofSurface + math.max(o1 - o0, #cutoutOver - c0) / 3
      elseif art.base then
        fn(opaque, art.base, 0)
        roofSolid = roofSolid + (#opaque - o0) / 3
        roofSurface = roofSurface + (#opaque - o0) / 3
      end
    end

    local sideFallback = tileUv(westT[1])
    local roofArt = artOf(comp.roofCell, sideFallback)
    local roofMode = roofArt.mode
    -- r11 (USER: "roofs and sides"): a pitched roof's tile is CROPPED to
    -- its clean pattern rows -- edge rows holding rare colours (< 1.5% of
    -- the roof rows' texels: the Mart's emblem top in its roof tiles) go,
    -- then edge rows of one flat colour (Viridian's green trim) when at
    -- least 8 patterned rows stay -- so no band repeats at every course
    if not comp.flatRoof and comp.roofCell and type(atlas.texels) == "function" then (function()
      local function vis(c, i)
        local o = c.hasOver and atlas.texels(c.mid, "over")
        if o and o[i] and o[i] >= 0 then return o[i] end
        local u = atlas.texels(c.mid, "under")
        return u and u[i] or -1
      end
      local hist, tot = {}, 0
      for yy = comp.nativeRoofStart or (comp.overhang and comp.minY - 1 or comp.roofTop), comp.roofBottom do
        for xx = comp.minX, comp.maxX do
          local c = at(xx, yy)
          if c and (isCompCell(c, comp) or c.overhangOf == comp) then
            for i = 1, 256 do
              local v = vis(c, i)
              if v >= 0 then hist[v] = (hist[v] or 0) + 1; tot = tot + 1 end
            end
          end
        end
      end
      local rc = comp.roofCell
      local rare, flat = {}, {}
      for y = 0, 15 do
        local first, uni = nil, true
        for x = 0, 15 do
          local v = vis(rc, y * 16 + x + 1)
          if v >= 0 and (hist[v] or 0) < 0.015 * tot then rare[y] = true end
          if first == nil then first = v elseif v ~= first then uni = false end
        end
        flat[y] = uni
      end
      local r0, r1 = 0, 15
      while r0 < r1 and rare[r0] do r0 = r0 + 1 end
      while r1 > r0 and rare[r1] do r1 = r1 - 1 end
      local p0, p1 = r0, r1
      while p0 < p1 and flat[p0] do p0 = p0 + 1 end
      while p1 > p0 and flat[p1] do p1 = p1 - 1 end
      local patterned = 0
      for y = p0, p1 do if not flat[y] then patterned = patterned + 1 end end
      if patterned >= 8 then r0, r1 = p0, p1 end
      if r0 > 0 or r1 < 15 then
        local v0, v1 = r0 / 16, (r1 + 1) / 16
        roofArt = { mode = roofArt.mode, mid = roofArt.mid,
          base = roofArt.base and subRectV(roofArt.base, v0, v1), over = roofArt.over and subRectV(roofArt.over, v0, v1) }
        comp.roofCrop = { r0, r1 }
      end
    end)() end

    -- r12 (USER: "use the original roof art, 1:1"): the roof's ART
    -- RECTANGLE -- columns minX .. maxX + 1 (the front slope between the end
    -- strips' inner edges), rows from the first texel row that is mostly
    -- roof (not the ground / transparent top of the overhang row) to the
    -- bottom of the last roof row -- and the cells under a chimney / emblem
    -- box (drawn with a neighbour's art: the box is the 3D version)
    local artMap = (function()
      if comp.roofBottom < comp.roofTop then return nil end
      local r0 = comp.nativeRoofStart or (comp.overhang and comp.minY - 1 or comp.roofTop)
      local Y0 = comp.overhang and comp.roofTop or r0
      if type(atlas.texels) == "function" then
        local _, gpal = groundTaint(comp.minX, comp.minY, comp.maxX, comp.maxY)
        local xa, xb = comp.minX + 1, comp.maxX - 1
        if xb < xa then xa, xb = comp.minX, comp.maxX end
        for Yt = r0 * 16, (comp.roofBottom + 1) * 16 - 1 do
          local yy, ty = math.floor(Yt / 16), Yt % 16
          local n, g = 0, 0
          for x = xa, xb do
            local c = at(x, yy)
            if c and (isCompCell(c, comp) or c.overhangOf == comp) then
              local u = atlas.texels(c.mid, "under")
              local o = c.hasOver and atlas.texels(c.mid, "over") or nil
              for tx = 0, 15 do
                local i = ty * 16 + tx + 1
                local ov = o and o[i]
                local v = (ov and ov >= 0) and ov or (u and u[i] or -1)
                n = n + 1
                if (ov and ov < 0 and c.walkable) or (gpal and gpal[v]) then g = g + 1 end
              end
            end
          end
          if n > 0 and g <= 0.5 * n then Y0 = Yt / 16 break end
        end
      end
      if comp.nativeDoorless==3 then Y0=math.max(Y0,comp.minY+8/16) end
      -- Native C040 mixes UNDER trees with a serrated OVER roof in row17.
      -- Preserve that rim; only its verified roof pixels belong on the slope.
      comp.nativeMeadowRoof=nativeMeadowRoof(input,comp,atlas)
      if comp.nativeMeadowRoof then Y0=math.max(Y0,17+8/16) end
      if comp.nativeBuildingProfile and comp.nativeBuildingProfile.roofSourceYMin then
        Y0=math.max(Y0,comp.nativeBuildingProfile.roofSourceYMin)
      end
      -- Native C171 mixes UNDER trees with a serrated OVER roof in row3.
      -- Preserve that rim; only its verified roof pixels belong on the slope.
      comp.nativeVermilionRoof=nativeVermilionRoof(input,comp,atlas)
      if comp.nativeVermilionRoof then Y0=math.max(Y0,3+8/16) end
      if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeRoofSourceTop then Y0=math.max(Y0,comp.nativeBuildingProfile.nativeRoofSourceTop) end
