        roofArtFace(comp, { col, A.Y0, col, A.Y1 }, { ex1, ptop, ez0 }, { ex1, wallTopY, ez0 }, { ex1, wallTopY, ez1 }, { ex1, ptop, ez1 }, N_E, A.covered, nil, nil, nativeTrim)
      end
      end
      if comp.nativeBuildingProfile and comp.nativeBuildingProfile.name=='safari-east' then
        -- Native rows8..11 are the baked shadow below the gold edge, not
        -- roof-rim material. Keep the top above row5 and wrap only the
        -- verified gold rim rows5..7 vertically on this guarded building.
        for li,list in ipairs{opaque,cutoutOver}do for i=#list,fasciaStarts[li]+1,-1 do list[i]=nil end end
        local r=subRect(overRect(709),8.5/16,5.5/16,8.5/16,7.5/16)
        local first=#cutoutOver
        if not touch.down then quad(cutoutOver,{ex0,ptop,ez1},{ex1,ptop,ez1},{ex1,wallTopY,ez1},{ex0,wallTopY,ez1},r,N_S)end
        if not touch.up then quad(cutoutOver,{ex1,ptop,ez0},{ex0,ptop,ez0},{ex0,wallTopY,ez0},{ex1,wallTopY,ez0},r,N_N)end
        if not touch.left then quad(cutoutOver,{ex0,ptop,ez0},{ex0,ptop,ez1},{ex0,wallTopY,ez1},{ex0,wallTopY,ez0},r,N_W)end
        if not touch.right then quad(cutoutOver,{ex1,ptop,ez1},{ex1,ptop,ez0},{ex1,wallTopY,ez0},{ex1,wallTopY,ez1},r,N_E)end
        for i=first+1,#cutoutOver,3 do local a,b,c=cutoutOver[i],cutoutOver[i+1],cutoutOver[i+2]
          if dot3(cross3(sub3(b,a),sub3(c,a)),{a[6],a[7],a[8]})<0 then cutoutOver[i+1],cutoutOver[i+2]=c,b end
          for j=i,i+2 do cutoutOver[j].nativeSafariGoldRim=true end
        end
      end
      grid.celadonRoofFascia(comp,ex0,ex1,ez0,ez1,wallTopY,ptop,touch,fasciaStarts)
      grid.palletOakRimUV(comp,ex0,ex1,ez0,ez1,wallTopY,ptop)
    elseif comp.flatRoof then
      -- M5 9-slice flat roof: corner / edge / interior tiles taken from the
      -- building's own roof rows; each tile drawn in its own art's layer.
      roofMode = "nine-slice"
      local ptop = wallTopY + C.FLAT_ROOF_PARAPET
      local nx = math.max(1, round(ex1 - ex0))
      local nz = math.max(1, round(ez1 - ez0))
      local wx, wz = (ex1 - ex0) / nx, (ez1 - ez0) / nz
      local haveRows = comp.roofBottom >= comp.roofTop
      -- (review of the side-by-sides, v17: with no true middle roof row the
      -- middle rows are the plain pattern tile edge to edge -- no bottom-row
      -- band repeated per row; a chimney-covered edge cell shows the row's
      -- common tile, not the chimney flat on the slab)
      local covered0 = haveRows and roofChimneys(comp, ptop, nil, nil, nil, true) or {}
      local noMid = comp.roofBottom - comp.roofTop < 2
      local function nineCell(i, j)
        if not haveRows then return comp.roofCell end
        if noMid and j > 0 and j < nz - 1 then return comp.roofCell end
        local rowY = (j == 0) and comp.roofTop or ((j == nz - 1) and comp.roofBottom or comp.nineMidRow)
        local colX = (i == 0) and comp.minX or ((i == nx - 1) and comp.maxX or nil)
        if colX then
          local c = at(colX, rowY)
          if isCompCell(c, comp) and not covered0[c] then return c end
        end
        return comp.nineInterior[rowY] or comp.roofCell
      end
      for j = 0, nz - 1 do
        for i = 0, nx - 1 do
          local qx0, qz0 = ex0 + i * wx, ez0 + j * wz
          local art = artOf(nineCell(i, j), sideFallback)
          emitArt(art, function(list, uvr, lift)
            hQuad(list, qx0, qz0, qx0 + wx, qz0 + wz, ptop + lift, uvr)
          end)
        end
      end
      -- r11 (review M13): a VENT / chimney -- an interior roof cell whose
      -- tile appears once on the whole roof, in a row whose common tile
      -- covers at least 3 cells -- is a small box on the slab with its own
      -- art (Oak's lab, Viridian); at most 2 per roof; not roof surface
      -- (an inner function: M.build is at LuaJIT's 200-locals limit here)
      if haveRows then (function()
        local all = {}
        for yy = comp.roofTop, comp.roofBottom do
          for xx = comp.minX, comp.maxX do
            local c = at(xx, yy)
            if isCompCell(c, comp) then all[c.mid] = (all[c.mid] or 0) + 1 end
          end
        end
        local cands = {}
        for yy = comp.roofTop, comp.roofBottom do
          local common = comp.nineInterior[yy]
          for xx = comp.minX + 1, comp.maxX - 1 do
            local c = at(xx, yy)
            if isCompCell(c, comp) and common and c.mid ~= common.mid and all[c.mid] == 1
                and (all[common.mid] or 0) >= 3 then
              cands[#cands + 1] = { xx, yy, c }
            end
          end
        end
        -- r11 (USER REPORT, roofs): CHIMNEYS -- roofChimneys (above); the
        -- vent cells its boxes cover draw no small vent
        local covered, boxes = roofChimneys(comp, ptop, nil)
        comp.chimneys = boxes
        -- the rest: small vent boxes (at most 2 boxes per roof in all)
        for _, cd in ipairs(cands) do
          local xx, yy, c = cd[1], cd[2], cd[3]
          if boxes < 2 and not covered[c] then
            boxes = boxes + 1
            local ov = c.hasOver and overRect(c.mid) or nil
            local list, uvr = opaque, underRect(c.mid)
            if ov and (overCoverage(c.mid) or 0) >= C.ROOF_SOLID_MIN then list, uvr = cutoutOver, ov end
            if uvr then
              local vx, vz, hw = xx + 0.5, yy + 0.5, C.VENT_W * 0.5
              local vy0, vy1 = ptop, ptop + C.VENT_H
              for _, e in ipairs({ "down", "up", "left", "right" }) do
                faceQuad(list, e, vx - hw, vx + hw, vz - hw, vz + hw, vy0, vy1, subRectV(uvr, 0.3, 0.7))
              end
              hQuad(list, vx - hw, vz - hw, vx + hw, vz + hw, vy1, subRect(uvr, 0.25, 0.25, 0.75, 0.75))
            end
          end
        end
      end)() end
      -- parapet (slab sides): the frame band = bottom rows of the bottom
      -- row's interior tile.
      local frameArt = artOf(haveRows and (comp.nineInterior[comp.roofBottom] or comp.roofCell) or comp.roofCell, sideFallback)
      emitArt(frameArt, function(list, uvr, lift)
        local strip = subRectV(uvr, 0.7, 1)
        for _, e in ipairs({ "down", "up", "left", "right" }) do
          if not touch[e] then -- (none against an attached building: R3)
            faceQuad(list, e, ex0 - lift, ex1 + lift, ez0 - lift, ez1 + lift, wallTopY, ptop, strip)
          end
        end
      end)
    elseif comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeMansionRoof then
      roofMode="native-mansion-front-dormers"
      artCount(function()grid.mansionRoof(comp,ex0,ex1,ez0,ez1)end)
    elseif comp.gable then
      -- r11 (USER REPORT): GABLE roof -- one ridge left to right over the
      -- eave rectangle's middle, the front and back slopes tiled like the
      -- hip roof (tiles ~1 unit along the ridge, courses ~ROOF_COURSE_LEN
      -- up the slope, planar UVs), pitch GABLE_PITCH (rise clamped to
      -- GABLE_RISE_MIN..MAX); gable ends and barge boards below
      roofMode = roofMode .. "-gable"
      if artMap then
        -- r12: the roof art 1:1 on the front slope, mirrored on the back
        local zm, half = (ez0 + ez1) / 2, (ez1 - ez0) / 2
        local rise = math.max(C.GABLE_RISE_MIN, math.min(C.GABLE_RISE_MAX, comp.wallHeight * C.GABLE_RISE_WALL,
          half * math.tan(math.rad(C.GABLE_PITCH))))
        local ry = wallTopY + rise
        local A = artMap
        artCount(function()
          for _, sd in ipairs({ { ez1, { 0, ez1 - zm, rise } }, { ez0, { 0, zm - ez0, -rise } } }) do
            local ze, n = sd[1], norm3(sd[2])
            roofArtFace(comp, { A.XL, A.Y0, A.XR, A.Y1 }, { ex0, ry, zm }, { ex1, ry, zm }, { ex1, wallTopY, ze }, { ex0, wallTopY, ze },
              n, A.covered)
          end
        end)
        comp.gableRise, comp.gableZm = rise, zm
        comp.roofAt = function(_, z) return wallTopY + rise * math.max(0, 1 - math.abs(z - zm) / half) end
      end
      if not artMap then emitArt(roofArt, function(list, uvr, lift)
        local wy = wallTopY + lift
        local zm, half = (ez0 + ez1) / 2, (ez1 - ez0) / 2
        -- (v16: the wall stays visible under a low roof -- the rise is at
        -- most GABLE_RISE_WALL x the wall height)
        local rise = math.max(C.GABLE_RISE_MIN, math.min(C.GABLE_RISE_MAX, comp.wallHeight * C.GABLE_RISE_WALL,
          half * math.tan(math.rad(C.GABLE_PITCH))))
        local nL = math.max(1, round(ex1 - ex0))
        local wL = (ex1 - ex0) / nL
        local nC = math.max(1, round(math.sqrt(half * half + rise * rise) / C.ROOF_COURSE_LEN))
        for _, sd in ipairs({ { ez1, { 0, ez1 - zm, rise } }, { ez0, { 0, zm - ez0, -rise } } }) do
          local ze, n = sd[1], norm3(sd[2])
          for cI = 0, nC - 1 do
            local ta, tb = cI / nC, (cI + 1) / nC
            local ya, yb = wy + rise * ta, wy + rise * tb
            local za, zb = ze + (zm - ze) * ta, ze + (zm - ze) * tb
            for k = 0, nL - 1 do
              local xa, xb = ex0 + k * wL, ex0 + (k + 1) * wL
              local pts = { { { xa, ya, za }, { uvr[1], uvr[4] } }, { { xb, ya, za }, { uvr[3], uvr[4] } },
                { { xb, yb, zb }, { uvr[3], uvr[2] } }, { { xa, yb, zb }, { uvr[1], uvr[2] } } }
              fanN(list, pts, n)
            end
          end
        end
        comp.gableRise, comp.gableZm = rise, zm
        if lift == 0 or not comp.roofAt then
          comp.roofAt = function(_, z) return wy + rise * math.max(0, 1 - math.abs(z - zm) / half) end
        end
      end) end
    elseif comp.chamfer and artMap then
      -- r12: the PC / Mart -- the hip with the roof art 1:1 (hipRoof art
      -- mode) on the ROUNDED eave, whose arc and lip show the art's edge
      -- rows: its bottom row on the front and back, the end strips' outer
      -- columns on the sides, the corner texels on the plan corners
      roofMode = roofMode .. "-round"
      local A = artMap
      artCount(function()
        local R, L, S, K = C.BULLNOSE_R, C.BULLNOSE_LIP, C.BULLNOSE_SEGS, C.BULLNOSE_CORNER_SEGS
        if comp.ov1 then R=comp.ov1.r end
        local wy = wallTopY
        local T = comp.ov1 and 0 or C.BULLNOSE_TOUCH_INSET
        local rx0, rx1 = touch.left and bx0 + T or ex0, touch.right and bx1 - T or ex1
        local rz0, rz1 = touch.up and bz0 + T or ez0, ez1
        local sd = math.min(rx1 - rx0, rz1 - rz0)
        local rise0 = math.max(C.ROOF_RISE_MIN, math.min(C.ROOF_RISE_MAX, sd * C.ROOF_PITCH))
        local a0 = comp.ov1 and 0 or math.atan(rise0 / (sd * 0.5))
        local inset = R * (1 - math.sin(a0))
        local ix0, ix1, iz0, iz1 = rx0 + inset, rx1 - inset, rz0 + inset, rz1 - inset
        -- 25d: the folded corners cut the inner outline (A.cut -> hipRoof)
        A.cut = comp.fold and grid.foldRoofCut(comp, touch, ix0, ix1, iz0, iz1, inset, bx0, bx1, bz1) or nil
        -- The front wall has native chamfers; the rear body is square.
        -- A shallower rear45-degree tangent facet keeps that body covered,
        -- while using the same eave profile and angular corner sweeps.
        if comp.centerPaint and A.cut then
          A.cut.rear={}
          for _,key in ipairs({"L","R"})do
            local mx,mz=(key=="L" and -1 or 1)/math.sqrt(2),-1/math.sqrt(2)
            local xe=key=="L" and ix0 or ix1;local wx=key=="L" and bx0 or bx1
            local lipK=mx*wx+mz*bz0;local v=lipK-inset
            local ax,bz=(v-mz*iz0)/mx,(v-mx*xe)/mz
            A.cut.rear[key]={A={ax,iz0},B={xe,bz},m={mx,mz},th=key=="L" and 1.25*math.pi or .75*math.pi,lip={mx,mz,lipK}}
          end
        end
        -- (PC / Mart back corners: one level panel on an OV-1 eave, not the hip)
        local _, hf
        if comp.ov1 then hf = grid.martpcFlatRoof(comp, A, wy + R * math.cos(a0), ix0, ix1, iz0, iz1)
        else _, hf = hipRoof(nil, nil, wy + R * math.cos(a0), ix0, ix1, iz0, iz1, comp.hipStrip and comp.hipStrip / 16,
          comp.endArt, true, A) end
        local cut = A.cut
        A.cut = nil
        comp.roofAt = hf
        local prof = {}
        for k = 0, S do
          local a = a0 + (math.pi / 2 - a0) * k / S
          prof[#prof + 1] = { R * (math.sin(a) - math.sin(a0)), wy + R * math.cos(a), math.sin(a), math.cos(a), (8/16-L)*k/S }
        end
        prof[#prof + 1] = { inset, wy - L, 1, 0, 8/16 }
        local function ring(px, pz, hx, hz, k)
          local pr = prof[k]
          local z=pz+hz*pr[1]
          -- The final native row37 boundary meets the front wall/window
          -- plane; the higher four-pixel overhang and true badge stay proud.
          if comp.centerPaint and k==#prof and pz>(iz0+iz1)/2 then z=z-comp.ov1.df end
          return { px + hx * pr[1], pr[2], z }, { hx * pr[3], pr[4], hz * pr[3] }
        end
        local eL, eR = comp.endArt and comp.endArt.L, comp.endArt and comp.endArt.R
        local yb = A.Y1 - 0.5 / 16
        local cl = eL and (eL.xo / 16 + 0.5 / 16) or (A.XL + 0.5 / 16)
        local cr = eR and (eR.xo / 16 - 0.5 / 16) or (A.XR - 0.5 / 16)
        -- a band of the profile (k -> k + 1) between stations a and b with
        -- the art rect `art` running from a to b
        local function band(pa, ha, pb, hb, art, k)
          local a1, na1 = ring(pa[1], pa[2], ha[1], ha[2], k)
          local b1, nb1 = ring(pb[1], pb[2], hb[1], hb[2], k)
          local a2, na2 = ring(pa[1], pa[2], ha[1], ha[2], k + 1)
          local b2, nb2 = ring(pb[1], pb[2], hb[1], hb[2], k + 1)
          -- (the band's mean normal: the lip band is vertical -- its over
          -- layer lifts along it, not up)
          local nm = { na1[1] + nb1[1] + na2[1] + nb2[1], na1[2] + nb1[2] + na2[2] + nb2[2], na1[3] + nb1[3] + na2[3] + nb2[3] }
          local nl = math.sqrt(nm[1] * nm[1] + nm[2] * nm[2] + nm[3] * nm[3])
          nm = nl > 1e-9 and { nm[1] / nl, nm[2] / nl, nm[3] / nl } or { 0, 1, 0 }
          if comp.centerPaint and k==#prof-1 and (pa[2]>(iz0+iz1)/2 or pb[2]>(iz0+iz1)/2) then
            nm=faceNormal3(a1,b1,b2)
            if nm[1]*(ha[1]+hb[1])+nm[3]*(ha[2]+hb[2])<0 then nm={-nm[1],-nm[2],-nm[3]}end
            na1,nb1,nb2,na2=nm,nm,nm,nm
          end
          if comp.ov1 then
            local by=comp.minY+comp.ov1.b0/16
            local xa,xb=art[1],art[3]
            if xa==xb then xa=comp.minX+12.5/16;xb=xa end
            local rearStarts=comp.centerPaint and ha[2]<-.99 and hb[2]<-.99 and {#opaque,#cutoutUnder,#cutoutOver,#cutoutKeyed}
            roofArtFace(comp,{xa,by+prof[k][5]+(k==1 and 1/512 or 0),xb,by+prof[k+1][5]},a1,b1,b2,a2,nm,A.covered,{na1,nb1,nb2,na2})
            if rearStarts then
              -- The curved rear band reused the front logo source rows.
              -- Retain its precise positions/smooth normals, but use only
              -- verified opaque native red; lower rear wall is untouched.
              for li,list in ipairs({opaque,cutoutUnder,cutoutOver,cutoutKeyed})do
                local last=#list
                for i=rearStarts[li]+1,last do local v=list[i]
                  v[4],v[5]=comp.centerRed[1],comp.centerRed[2]
                  if list~=opaque then opaque[#opaque+1]=v end
                end
                if list~=opaque then for i=last,rearStarts[li]+1,-1 do list[i]=nil end end
              end
            end
          elseif art[1] == art[3] then
            -- a column along the edge (the side arcs): art y runs a -> b
            roofArtFace(comp, art, a1, a2, b2, b1, nm, A.covered, { na1, na2, nb2, nb1 })
          else
            roofArtFace(comp, art, a1, b1, b2, a2, nm, A.covered, { na1, nb1, nb2, na2 })
          end
        end
        for k = 1, #prof - 1 do
          if cut then grid.foldRing(cut, band, k, K, ix0, ix1, iz0, iz1, A, eL, eR, yb, cl, cr, comp) else
          band({ ix0, iz1 }, { 0, 1 }, { ix1, iz1 }, { 0, 1 }, { A.X0, yb, A.X1, yb }, k)
          band({ ix0, iz0 }, { 0, -1 }, { ix1, iz0 }, { 0, -1 }, { A.X0, yb, A.X1, yb }, k)
          band({ ix0, iz0 }, { -1, 0 }, { ix0, iz1 }, { -1, 0 }, { cl, eL and eL.y0 / 16 or A.Y0, cl, eL and (eL.y1 + 1) / 16 or A.Y1 }, k)
          band({ ix1, iz0 }, { 1, 0 }, { ix1, iz1 }, { 1, 0 }, { cr, eR and eR.y0 / 16 or A.Y0, cr, eR and (eR.y1 + 1) / 16 or A.Y1 }, k)
          -- plan corners: the corner texels of the art
          local corners = { { ix1, iz1, 0, cr }, { ix1, iz0, 0.5, cr }, { ix0, iz0, 1, cl }, { ix0, iz1, 1.5, cl } }
          for _, co in ipairs(corners) do
            for q = 0, K - 1 do
              local c0 = (co[3] + q / K * 0.5) * math.pi
              local c1 = (co[3] + (q + 1) / K * 0.5) * math.pi
              band({ co[1], co[2] }, { math.sin(c0), math.cos(c0) }, { co[1], co[2] }, { math.sin(c1), math.cos(c1) },
                { co[4], yb, co[4], yb }, k)
            end
          end
          end -- (25d: not cut)
        end
        -- At a flush front a square attached wall reaches the outer plan
        -- corner. Close the part outside the plan fillet; folded notches
        -- retain their existing angled outline.
        if comp.ov1 and touch.down then
          for _,co in ipairs({{"L",rx0,ix0,1.5},{"R",rx1,ix1,0}}) do
            if not (cut and cut[co[1]]) then
              local uv=comp.ov1.soffit
              local pts={{{co[2],wy,rz1},{uv[1],uv[2]}}}
              for q=0,K do
                local a=(co[4]+q/K*.5)*math.pi
                pts[#pts+1]={ {co[3]+inset*math.sin(a),wy,iz1+inset*math.cos(a)}, {uv[1],uv[2]} }
              end
              fanN(opaque,pts,UP)
              wallQuad(opaque,co[2],rz1,co[3],rz1,wy-L,wy,uv,N_S)
              wallQuad(opaque,co[2],iz1,co[2],rz1,wy-L,wy,uv,co[1]=="L" and N_W or N_E)
            end
          end
        end
      end)
    elseif comp.chamfer then
      -- r11 (USER REPORT; refs 07 / 12, v15 / v16): the PC / Mart roof -- a
      -- HIP (hipRoof, ends as wide as the art's end strips) on a ROUNDED
      -- eave: an arc of radius BULLNOSE_R from the slope's own angle down
      -- to vertical, swept round the eave rectangle (plan corners rounded)
      -- in BULLNOSE_SEGS segments with smooth normals, ending in a
      -- BULLNOSE_LIP lip; the roof art runs on over the curve (the tile's
      -- lower rows at the slope's scale)
      roofMode = roofMode .. "-round"
      emitArt(roofArt, function(list, uvr, lift)
        local R, L, S, K = C.BULLNOSE_R, C.BULLNOSE_LIP, C.BULLNOSE_SEGS, C.BULLNOSE_CORNER_SEGS
        local wy = wallTopY + lift
        -- (a side against another building: the edge stops just inside
        -- the shared wall plane -- review R3)
        local T = C.BULLNOSE_TOUCH_INSET
        local rx0, rx1 = touch.left and bx0 + T or ex0, touch.right and bx1 - T or ex1
        local rz0, rz1 = touch.up and bz0 + T or ez0, ez1
        local sd = math.min(rx1 - rx0, rz1 - rz0)
        local rise0 = math.max(C.ROOF_RISE_MIN, math.min(C.ROOF_RISE_MAX, sd * C.ROOF_PITCH))
        local a0 = math.atan(rise0 / (sd * 0.5))
        local inset = R * (1 - math.sin(a0))
        local ix0, ix1, iz0, iz1 = rx0 + inset, rx1 - inset, rz0 + inset, rz1 - inset
        local _, hf = hipRoof(list, uvr, wy + R * math.cos(a0), ix0, ix1, iz0, iz1, comp.hipStrip and comp.hipStrip / 16,
          comp.endArt, lift == 0)
        if lift == 0 or not comp.roofAt then comp.roofAt = hf end
        -- the profile: the arc from the slope's angle to vertical, then the
        -- lip; v is arc length (1 unit = one tile) ending at the tile's
        -- bottom row
        local arc = R * (math.pi / 2 - a0)
        local total = arc + L
        local prof = {}
        for k = 0, S do
          local a = a0 + (math.pi / 2 - a0) * k / S
          prof[#prof + 1] = { R * (math.sin(a) - math.sin(a0)), wy + R * math.cos(a), math.sin(a), math.cos(a), arc * k / S }
        end
        prof[#prof + 1] = { inset, wy - L, 1, 0, total }
        -- (the tile's top rows: its bottom rows may meet the facade)
        local v0 = uvr[2]
        local function vAt(sv) return v0 + (uvr[4] - uvr[2]) * math.min(1, sv) end
        local function ring(px, pz, hx, hz, k)
          local pr = prof[k]
          return { px + hx * pr[1], pr[2], pz + hz * pr[1] }, { hx * pr[3], pr[4], hz * pr[3] }
        end
        -- a strip between two stations (base points + outward directions)
        local function strip(pa, ha, ua, pb, hb, ub)
          for k = 1, #prof - 1 do
            local a1, na1 = ring(pa[1], pa[2], ha[1], ha[2], k)
            local b1, nb1 = ring(pb[1], pb[2], hb[1], hb[2], k)
            local a2, na2 = ring(pa[1], pa[2], ha[1], ha[2], k + 1)
            local b2, nb2 = ring(pb[1], pb[2], hb[1], hb[2], k + 1)
            local va, vb = vAt(prof[k][5]), vAt(prof[k + 1][5])
            local t1, t2, t3, t4 = { ua, va }, { ub, va }, { ub, vb }, { ua, vb }
            if not (k == 1 and a1[1] == b1[1] and a1[3] == b1[3]) then
              tri3(list, a1, t1, na1, b1, t2, nb1, b2, t3, nb2)
            end
            tri3(list, a1, t1, na1, b2, t3, nb2, a2, t4, na2)
          end
        end
        local U0, U1 = uvr[1], uvr[3]
        local nx, nz = math.max(1, round(ix1 - ix0)), math.max(1, round(iz1 - iz0))
        local wx, wz = (ix1 - ix0) / nx, (iz1 - iz0) / nz
        -- straight edges: tiles ~1 unit
        local edges = {
          { ix0, iz1, 1, 0, 0, 1, nx, wx }, -- south: west -> east
          { ix1, iz0, -1, 0, 0, -1, nx, wx }, -- north: east -> west
          { ix0, iz0, 0, 1, -1, 0, nz, wz }, -- west: north -> south
          { ix1, iz1, 0, -1, 1, 0, nz, wz }, -- east: south -> north
        }
        for _, e in ipairs(edges) do
          for i = 0, e[7] - 1 do
            local pa = { e[1] + e[3] * i * e[8], e[2] + e[4] * i * e[8] }
            local pb = { e[1] + e[3] * (i + 1) * e[8], e[2] + e[4] * (i + 1) * e[8] }
            strip(pa, { e[5], e[6] }, U0, pb, { e[5], e[6] }, U1)
          end
        end
        -- corners: the profile swept a quarter turn about the corner
        -- (outward direction (sin a, cos a): south at a = 0, east at pi / 2,
        -- north at pi, west at 3 pi / 2)
        local corners = { { ix1, iz1, 0 }, { ix1, iz0, 0.5 }, { ix0, iz0, 1 }, { ix0, iz1, 1.5 } }
        for _, cr in ipairs(corners) do
          for k = 0, K - 1 do
            local c0 = (cr[3] + k / K * 0.5) * math.pi
            local c1 = (cr[3] + (k + 1) / K * 0.5) * math.pi
            local ha = { math.sin(c0), math.cos(c0) }
            local hb = { math.sin(c1), math.cos(c1) }
            local du = (U1 - U0) * math.min(1, inset * math.pi / 2)
            strip({ cr[1], cr[2] }, ha, U0 + du * k / K, { cr[1], cr[2] }, hb, U0 + du * (k + 1) / K)
          end
        end
      end)
    elseif comp.k32 then
      -- (K32 r3) a flat top sloping down at both ends, its band and the
      -- wall tops, from the art in 2.5D (grid.k32Roof)
      if comp.flatHouse then -- (flat-top rollout: the other house kinds)
        roofMode = roofMode .. "-flattop"
        artCount(function() comp.roofAt = grid.flatTopRoof(comp, sideArt) end)
      else
      roofMode = roofMode .. "-k32flat"
      artCount(function() comp.roofAt = grid.k32Roof(comp, sideArt) end)
      end
    else
      -- M12 hip roof (hipRoof). r11 (refs 14, v15 / v17): the ends reach in
      -- as far as the art's end strips are wide -- a long ridge, sloped
      -- ends (Pallet's houses, the gyms)
      roofMode = roofMode .. "-hip"
      -- (refs 14, v15-v17: the ends in the art's end strips; a roof BREAK
      -- -- two attached houses with two roofs -- gives one hip per house)
      if artMap then
        -- r12: each house's hip with the roof art 1:1 over its own columns
        local A = artMap
        local segs, x = {}, ex0
        local endsL = comp.endArt and comp.endArt.L
        local xl = A.X0
        for _, b in ipairs(comp.roofBreaks or {}) do
          segs[#segs + 1] = { x, b.x, { L = endsL, R = b.L }, xl, b.L and b.L.xi / 16 or b.x }
          x, endsL, xl = b.x, b.R, b.R and b.R.xi / 16 or b.x
        end
        segs[#segs + 1] = { x, ex1, { L = endsL, R = comp.endArt and comp.endArt.R }, xl, A.X1 }
        local fns = {}
        artCount(function()
          for _, sg in ipairs(segs) do
            local e = sg[3]
            local ext = ((e.L and e.L.w or comp.endStrip or 0) + (e.R and e.R.w or comp.endStrip or 0)) / 32
            local am = { comp = comp, X0 = sg[4], X1 = sg[5], Y0 = A.Y0, Y1 = A.Y1, covered = A.covered }
            local _, hf = hipRoof(nil, nil, wallTopY, sg[1], sg[2], ez0, ez1, ext > 0 and ext or nil, e, true, am)
            fns[#fns + 1] = { sg[1], sg[2], hf }
          end
        end)
        comp.roofAt = function(px, pz)
          for _, f in ipairs(fns) do
            if px >= f[1] - 1e-6 and px <= f[2] + 1e-6 then return f[3](px, pz) end
          end
          return fns[1][3](px, pz)
        end
      end
      if not artMap then emitArt(roofArt, function(list, uvr, lift)
        local segs, x = {}, ex0
        local endsL = comp.endArt and comp.endArt.L
        for _, b in ipairs(comp.roofBreaks or {}) do
          segs[#segs + 1] = { x, b.x, { L = endsL, R = b.L } }
          x, endsL = b.x, b.R
        end
        segs[#segs + 1] = { x, ex1, { L = endsL, R = comp.endArt and comp.endArt.R } }
        local fns = {}
        for _, sg in ipairs(segs) do
          local e = sg[3]
          local ext = ((e.L and e.L.w or comp.endStrip or 0) + (e.R and e.R.w or comp.endStrip or 0)) / 32
          local _, hf = hipRoof(list, uvr, wallTopY + lift, sg[1], sg[2], ez0, ez1, ext > 0 and ext or nil, e, lift == 0)
          fns[#fns + 1] = { sg[1], sg[2], hf }
        end
        if lift == 0 or not comp.roofAt then
          comp.roofAt = function(px, pz)
            for _, f in ipairs(fns) do
              if px >= f[1] - 1e-6 and px <= f[2] + 1e-6 then return f[3](px, pz) end
            end
            return fns[1][3](px, pz)
          end
        end
      end) end
      if comp.roofBreaks then roofMode = roofMode .. "-split" end
    end

    if grid.dojoSpineRoof(comp,ro0,rc0)then roofMode='native-dojo-sevii-spined-hip';roofSurface=comp.nativeDojoSpine.triangles;roofSolid=roofSurface end
    local ro1, rc1 = #opaque, #cutoutOver
    -- r11 (v16): a pitched roof's chimney (Viridian's green houses); none
    -- on the PC / Mart (their emblem is the box over the door)
    if not comp.museumFreshRoof and not comp.networkRoofShape and not comp.flatRoof and comp.roofAt and not comp.chamfer then
      local _, n = roofChimneys(comp, nil, comp.roofAt, ez0, ez1)
      comp.chimneys = n
    end
    -- M7 soffit (every mode, replaces the W3 footprint cap) + fascia.
    local capStart = #opaque
    comp.viridianSlopedSoffit=grid.viridianSoffitGuard(comp)
    -- (the bullnose's soffit is under its lip)
    local round_ = comp.chamfer and not comp.gable and not comp.flatRoof
    local sy = round_ and wallTopY - C.BULLNOSE_LIP or wallTopY
    if comp.ov1 then trimUv=comp.ov1.soffit end
    -- r12 (USER: "double / triple rendering the roof"): the soffit covers
    -- only the overhang RING outside the walls -- no second surface under
    -- the whole roof (with culling off it showed through the roof art)
    if comp.fold and round_ then grid.foldSoffit(comp, ex0, ex1, ez0, ez1, bx0, bx1, bz0, bz1, sy, trimUv) else -- 25d
    do
    local bz1 = comp.deptBays and bz1 - 5/16 or bz1
    for _, rr in ipairs({ { ex0, ex1, ez0, bz0 }, { ex0, ex1, bz1, ez1 }, { ex0, bx0, bz0, bz1 }, { bx1, ex1, bz0, bz1 } }) do
      if rr[2] - rr[1] > 1e-4 and rr[4] - rr[3] > 1e-4 then
        local soffitList,soffitUv=opaque,trimUv
        local p=comp.nativeBuildingProfile
        local s=p and p.nativeSoffitSample
        if s then
          local r=overRect(s.mid)
          soffitList=cutoutOver
          soffitUv=subRect(r,(s.x+.5)/16,(s.y+.5)/16,(s.x+.5)/16,(s.y+.5)/16)
        end
        if not grid.viridianSlopedSoffit(comp,rr,sy,soffitList,soffitUv,bx0,bx1,bz0,bz1)then
        quad(soffitList, { rr[1], sy, rr[3] }, { rr[1], sy, rr[4] }, { rr[2], sy, rr[4] }, { rr[2], sy, rr[3] }, soffitUv, DOWN)
        end
      end
    end
    end
    end -- scoped Dept soffit inner boundary
    if comp.networkRoofShape then grid.networkRoofSoffit(capStart) end
    -- Native Mart underside must follow the already emitted rounded lip.
    -- Clip only cap triangles; the roof, walls, UVs and collision stay fixed.
    if comp.ov1 and comp.ov1.kind=="K02" and round_ then (function()
      local pts={}
      for _,range in ipairs({{opaque,ro0+1,ro1},{cutoutOver,rc0+1,rc1}})do
        for i=range[2],range[3] do local v=range[1][i]
          if math.abs(v[2]-sy)<1e-7 then pts[#pts+1]={v[1],v[3]} end
        end
      end
      table.sort(pts,function(a,b)return a[1]<b[1] or a[1]==b[1] and a[2]<b[2]end)
      local function cross(a,b,c)return (b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1])end
      local hull={}
      for _,p in ipairs(pts)do
        while #hull>=2 and cross(hull[#hull-1],hull[#hull],p)<=1e-10 do hull[#hull]=nil end
        hull[#hull+1]=p
      end
      local lower=#hull
      for i=#pts-1,1,-1 do local p=pts[i]
        while #hull>lower and cross(hull[#hull-1],hull[#hull],p)<=1e-10 do hull[#hull]=nil end
        hull[#hull+1]=p
      end
      hull[#hull]=nil
      if #hull>=3 then
        local planes={}
        for i,a in ipairs(hull)do local b=hull[i%#hull+1]
          planes[#planes+1]=grid.halfPlane(a,b,{(bx0+bx1)/2,(bz0+bz1)/2})
        end
        local old={}
        for i=capStart+1,#opaque do old[#old+1]=opaque[i] end
        for i=#opaque,capStart+1,-1 do opaque[i]=nil end
        for i=1,#old,3 do
          local p={}
          for j=0,2 do local v=old[i+j];p[#p+1]={{v[1],v[2],v[3]},{v[4],v[5]}}end
          grid.clipFan(opaque,p,DOWN,planes)
        end
        -- Edge-coincident clips can leave zero-area fan triangles.
        local write=capStart+1
        local last=#opaque
        for i=capStart+1,last,3 do local a,b,c=opaque[i],opaque[i+1],opaque[i+2]
          if math.abs((b[1]-a[1])*(c[3]-a[3])-(b[3]-a[3])*(c[1]-a[1]))>1e-10 then
            opaque[write],opaque[write+1],opaque[write+2]=a,b,c;write=write+3
          end
        end
        for i=write,last do opaque[i]=nil end
      end
    end)() end
    if not comp.museumFreshRoof and not comp.networkRoofShape and not comp.flatRoof and not round_ and not comp.k32 and not (comp.nativeBuildingProfile and (comp.nativeBuildingProfile.nativeMansionRoof or comp.nativeBuildingProfile.nativeSeviiPurple)) then
      for _, e in ipairs({ "down", "up", "left", "right" }) do
        if not touch[e] and not (comp.gable and (e == "left" or e == "right")) then
          if artMap then
            -- r12: the fascia shows the art's edge row / column
            local A = artMap
            local yb = A.Y1 - 0.5 / 16
            local eL, eR = comp.endArt and comp.endArt.L, comp.endArt and comp.endArt.R
            local y0, y1 = wallTopY - C.FASCIA_H, wallTopY
            if e == "down" or e == "up" then
              local z = e == "down" and ez1 or ez0
              roofArtFace(comp, { A.XL, yb, A.XR, yb }, { ex0, y1, z }, { ex1, y1, z }, { ex1, y0, z }, { ex0, y0, z },
                e == "down" and N_S or N_N, A.covered)
            else
              local xw = e == "left" and ex0 or ex1
              local col = e == "left" and (eL and eL.xo / 16 + 0.5 / 16 or A.XL + 0.5 / 16) or (eR and eR.xo / 16 - 0.5 / 16 or A.XR - 0.5 / 16)
              roofArtFace(comp, { col, A.Y0, col, A.Y1 }, { xw, y1, ez0 }, { xw, y0, ez0 }, { xw, y0, ez1 }, { xw, y1, ez1 },
                e == "left" and N_W or N_E, A.covered)
            end
          else
            faceQuad(opaque, e, ex0, ex1, ez0, ez1, wallTopY - C.FASCIA_H, wallTopY, trimUv)
          end
        end
      end
    end
    -- r11 (USER REPORT): the GABLE ENDS -- a pentagon on each side wall's
    -- plane from the wall top up under the slopes to the ridge, plastered
    -- with one texel of the plaster column -- and the BARGE BOARDS along
    -- the slopes' side edges (trim art, FASCIA_H deep)
    if comp.gable and comp.gableRise then (function() -- (inner function: locals limit)
      local rise, zm = comp.gableRise, comp.gableZm
      local half = (ez1 - ez0) / 2
      local function roofY(z) return wallTopY + rise * (1 - math.abs(z - zm) / half) end
      -- (the top band's plaster texel; else any band's; else the side
      -- wall art itself -- never a tile the walls would not use)
      local sa = sideArt[#sideArt] or sideArt[1]
      for i = #sideArt, 1, -1 do
        if sideArt[i] and sideArt[i].gable then sa = sideArt[i] break end
      end
      local guv = sa and (sa.gable or sa[2]) or trimUv
      local glist = sa and sa[1] or opaque
      -- (r12: the plain wall colour on the gable ends too)
      if sideArt.plain then guv, glist = sideArt.plain.W[2], sideArt.plain.W[1] end
      for _, g in ipairs({ { bx0, "left", N_W, ex0 }, { bx1, "right", N_E, ex1 } }) do
        local xw, side, n, xe = g[1], g[2], g[3], g[4]
        if not touch[side] then
          local pts = { { { xw, wallTopY, bz0 }, { guv[1], guv[4] } }, { { xw, wallTopY, bz1 }, { guv[3], guv[4] } },
            { { xw, roofY(bz1), bz1 }, { guv[3], guv[2] } }, { { xw, wallTopY + rise, zm }, { guv[1], guv[2] } },
            { { xw, roofY(bz0), bz0 }, { guv[1], guv[2] } } }
          if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeThreeIsland then
            -- The two roof-only courses extend beyond the physical body. Close
            -- their upper gable envelope at wallTop, without a wall below it.
            pts={{{xw,wallTopY,ez0},{guv[1],guv[4]}},
                 {{xw,wallTopY,ez1},{guv[3],guv[4]}},
                 {{xw,wallTopY+rise,zm},{guv[1],guv[2]}}}
          end
          -- (r12b: the side walls' clean wall patch continues up the gable;
          -- the tile runs toward +z on the west end, -z on the east: as
          -- the side walls below)
          if sideArt.plain and sideArt.plain.P then
            local zy = {}
            for i, p in ipairs(pts) do zy[i] = { p[1][3], p[1][2] } end
            grid.tiledPoly(sideArt.plain.P, xw, zy, side == "left" and 1 or -1, n, groundY)
          else
            fanN(glist, pts, n)
          end
          for _, seg in ipairs({ { ez0, zm }, { zm, ez1 } }) do
            local za, zb = seg[1], seg[2]
            local pb = { { { xe, roofY(za), za }, { trimUv[1], trimUv[2] } }, { { xe, roofY(zb), zb }, { trimUv[3], trimUv[2] } },
              { { xe, roofY(zb) - C.FASCIA_H, zb }, { trimUv[3], trimUv[4] } }, { { xe, roofY(za) - C.FASCIA_H, za }, { trimUv[1], trimUv[4] } } }
            local trimList=opaque
            local s=comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeRoofTrimSample
            if s then
              local r=overRect(s.mid);local u=r[1]+(r[3]-r[1])*(s.x+.5)/16;local v=r[2]+(r[4]-r[2])*(s.y+.5)/16
              for _,p in ipairs(pb)do p[2]={u,v}end
              trimList=cutoutOver
            end
            fanN(trimList, pb, n)
          end
        end
      end
    end)() end
      if comp.nativeSafariStarts then (function()
        -- roofArtFace's legacy UP order is inward; repair only this new roof producer.
        for li,list in ipairs({opaque,cutoutOver})do for i=comp.nativeSafariStarts[li]+1,#list,3 do
          local a,b,c=list[i],list[i+1],list[i+2]
          local ux,uy,uz=b[1]-a[1],b[2]-a[2],b[3]-a[3]
          local vx,vy,vz=c[1]-a[1],c[2]-a[2],c[3]-a[3]
          if (uy*vz-uz*vy)*a[6]+(uz*vx-ux*vz)*a[7]+(ux*vy-uy*vx)*a[8]<0 then list[i+1],list[i+2]=c,b end
        end end
        comp.nativeSafariStarts=nil
      end)() end
    local capTris = (#opaque - capStart) / 3

    grid.bikeShopAwning(comp)
    grid.bikeRoundRoof(comp,ro0,rc0)
    grid.bikeRoundBody(comp,sideArt)
    if comp.gameCornice then grid.gameCorniceFinish(comp,comp.gameCornice) end
    if comp.deptUnitStarts then grid.deptUnit(comp,comp.deptUnitStarts); grid.deptCornice(comp,comp.deptUnitStarts) end
    -- r12 (night-readiness, read-only data for W8's LightPools / Emissive):
    -- the building's DOORS and front WINDOWS in world space. doors = the
    -- front-row door columns (and a legacy door just south of the box):
    -- { x, z = the door cell, wx = its centre x, wz = the front wall's plane,
    -- y = the ground, w = 1, h = WALL_ROW_UNIT, face = "south", legacy };
    -- windows = facade cells (one per band and column, not a door column or
    -- the emblem logo) with >= 12 window-glass texels in its under art not
    -- covered by over art (over art there = the roof / awning) -- the three FRLG
    -- glass blues (within 24 per channel) or any bright blue-dominant texel
    -- (b >= 170, b - r >= 60, g >= r) -- as the glass texels' bounding box
    -- on the facade: { x, z = the cell, band, wx0, wx1, wy0, wy1, wz, face =
    -- "south", glass = the texel count }. (inner function: locals limit)
    local nightDoors, nightWindows = (function()
      local doors, wins = {}, {}
      for x = comp.minX, comp.maxX do
        local fc = at(x, comp.maxY)
        local below = at(x, comp.maxY + 1)
        if fc and fc.doorOf == comp then
          doors[#doors + 1] = { x = x, z = comp.maxY, wx = x + 0.5, wz = bz1, y = groundY, w = 1, h = C.WALL_ROW_UNIT, face = "south" }
        elseif below and below.isDoor then
          doors[#doors + 1] = { x = x, z = comp.maxY + 1, wx = x + 0.5, wz = bz1, y = groundY, w = 1, h = C.WALL_ROW_UNIT, face = "south", legacy = true }
        end
      end
      if type(atlas.texels) ~= "function" then return doors, wins end
      local KEYS = { { 99, 165, 222 }, { 115, 189, 247 }, { 156, 214, 255 } }
      local function glass(v)
        if not v or v < 0 then return false end
        local r, g, b = math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256
        for _, k in ipairs(KEYS) do
          if math.abs(r - k[1]) <= 24 and math.abs(g - k[2]) <= 24 and math.abs(b - k[3]) <= 24 then return true end
        end
        return b >= 170 and b - r >= 60 and g >= r
      end
      for bi, band in ipairs(bands) do
        if not band.filler then
          for x = comp.minX, comp.maxX do
            deps.yieldSafe() -- Lab 59 checkpoint (per facade cell: a glass scan of 256 texels)
            local c = at(x, band.rowY)
            local fc = at(x, comp.maxY)
            local doorCol = fc and fc.doorOf == comp
            local logo = bi == 2 and comp.emblem and comp.emblem.at[x]
            if c and (isCompCell(c, comp) or c.facadeOf == comp) and not c.isDoor and not (doorCol and bi == 1) and not logo then
              local u = atlas.texels(c.mid, "under")
              local o = c.hasOver and atlas.texels(c.mid, "over") or nil
              if u then
                local n, c0, c1, r0, r1 = 0, 16, -1, 16, -1
                for row = 0, 15 do
                  for col = 0, 15 do
                    local i = row * 16 + col + 1
                    -- (the under art only, and not where the over art covers
                    -- it: over art on a facade row is the roof / awning
                    -- hanging over it -- the Mart's blue awning tiles)
                    local v = not (o and o[i] and o[i] >= 0) and u[i] or nil
                    if glass(v) then
                      n = n + 1
                      if col < c0 then c0 = col end
                      if col > c1 then c1 = col end
                      if row < r0 then r0 = row end
                      if row > r1 then r1 = row end
                    end
                  end
                end
                if n >= 12 then
                  local y0, y1 = groundY + band.y0, groundY + band.y1
                  wins[#wins + 1] = { x = x, z = band.rowY, band = bi, face = "south", glass = n,
                    wx0 = x + c0 / 16, wx1 = x + (c1 + 1) / 16,
                    wy0 = y0 + (1 - (r1 + 1) / 16) * (y1 - y0), wy1 = y0 + (1 - r0 / 16) * (y1 - y0), wz = bz1 }
                end
              end
            end
          end
        end
      end
      return doors, wins
    end)()

    if comp.nativeBuildingProfile and comp.nativeBuildingProfile.nativeLabRoof then
      (function()
      -- The native small windows live in OVER on y8's partial facade. The
      -- generic UNDER/full-band scanner cannot see them. Bind actual emitted
      -- facade triangles and exact native blue palette; add no geometry.
      local windows={}
      for _,mid in ipairs{689,690}do
        local r,t=overRect(mid),atlas.texels(mid,'over')
        local palette,seen={},{}
        for row=8,15 do for col=0,15 do
          local v=t[row*16+col+1]
          if v>=0 then local red,green,blue=math.floor(v/65536)%256,math.floor(v/256)%256,v%256
            if blue>=170 and blue-red>=60 and green>=red and not seen[v]then palette[#palette+1]=v;seen[v]=true end
          end
        end end
        assert(#palette>0,'guarded native laboratory glass missing')
        for i=1,#cutoutOver,3 do
          local matches=true
