    local gy,top=.75,3.25
    local function uv(mid,ly,x0,y0,x1,y1)
      local r=ly==1 and overRect(mid)or underRect(mid)
      local ax,ay=math.floor(r[1]*atlas.w),math.floor(r[2]*atlas.h)
      return {(ax+x0+.5)/atlas.w,(ay+y0+.5)/atlas.h,
        (ax+x1-.5)/atlas.w,(ay+y1-.5)/atlas.h}
    end
    local nativeWindows={}
    for _,q in ipairs(commands)do
      local kind,x0,x1,row,mid,tx,ty,ly,topY,z,span=unpack(q)
      local list=ly==1 and cutoutOver or opaque
      local r=uv(mid,ly,tx,ty,tx+x1-x0,ty+span)
      local lo,hi=topY-(row+span)/16,topY-row/16
      wallQuad(list,6+x0/16,z,6+x1/16,z,lo,hi,r,N_S)
      -- Foreground cards are source-owned separate objects. Matching reversed
      -- cards preserve their native silhouette when seen from behind.
      if kind>=2 then wallQuad(list,6+x1/16,z-.002,6+x0/16,z-.002,lo,hi,{r[3],r[2],r[1],r[4]},N_N)end
    end
    -- The source roof reaches the north map boundary; no unseen ridge/pitch
    -- or extra north cell is invented. Four native rows have one common plane.
    for yy=0,3 do for xx=6,16 do
      local c=at(xx,yy)
      hQuad(cutoutOver,xx,yy*6.5/4,xx+1,(yy+1)*6.5/4,top,overRect(c.mid))
    end end
    -- Source-native orange side/back closure, at the same texel density as
    -- the vertical front. Hidden backs/depth are explicit reconstruction.
    for z=0,6 do local z1=math.min(6.5,z+1)
      for iy=0,2 do local y0=gy+iy;local y1=math.min(top,y0+1)
        if y1>y0 then
          faceQuad(opaque,'left',6,17,z,z1,y0,y1,subRect(underRect(785),0,0,z1-z,y1-y0))
          faceQuad(opaque,'right',6,17,z,z1,y0,y1,subRect(underRect(785),0,0,z1-z,y1-y0))
        end
      end
    end
    for x=6,16 do for iy=0,2 do local y0=gy+iy;local y1=math.min(top,y0+1)
      if y1>y0 then faceQuad(opaque,'up',x,x+1,0,6.5,y0,y1,subRect(underRect(785),0,0,1,y1-y0))end
    end end
    -- Entry backing connects its projecting source front to the main volume.
    -- Native gray silhouette row endpoints determine each strip, not a box cap.
    local profile={{87,88},{85,90},{83,92},{81,94},{79,96},{77,98},{75,100},{74,101},{74,101},{74,101},{74,101},{75,100},{75,100},{74,101},{74,101},{74,101},{74,101},{74,101},{74,101},{72,103},{70,105},{68,107},{66,109},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111},{64,111}}
    for row,e in ipairs(profile)do
      local y1=3.75-(row-1)/16;local y0=y1-1/16
      local xa,xb=6+e[1]/16,6+(e[2]+1)/16
      local c=at(6+math.floor(e[1]/16),4+math.floor((row-1)/16))
      local t=atlas.texels(c.mid,'over');local vi=(row-1)%16*16+e[1]%16+1
      local layer=c.hasOver and t and t[vi]and t[vi]>=0 and 1 or 0
      local r=uv(c.mid,layer,e[1]%16,(row-1)%16,e[1]%16+1,(row-1)%16+1)
      local list=layer==1 and cutoutOver or opaque
      faceQuad(list,'left',xa,xb,6.5,7.002,y0,y1,r)
      faceQuad(list,'right',xa,xb,6.5,7.002,y0,y1,r)
      if y1>top then wallQuad(cutoutOver,xb,6.5,xa,6.5,math.max(y0,top),y1,uv(780,1,7,0,8,1),N_N)end
      if row==1 then hQuad(list,xa,6.5,xb,7.002,y1,r)
      else local a=profile[row-1]
        if e[1]<a[1]then hQuad(list,xa,6.5,6+a[1]/16,7.002,y1,r)end
        if e[2]>a[2]then hQuad(list,6+(a[2]+1)/16,6.5,xb,7.002,y1,r)end
      end
    end
    -- Restore only floor that was hidden by the admitted structural blocks.
    -- Door/apron cells remain their original producer and support.
    for yy=6,7 do for xx=6,16 do local c=at(xx,yy)
      if c and c.blocksForBlob and grid.indigoOwners[compOf(c)]then
        hQuad(opaque,xx,math.max(6.5,yy),xx+1,yy+1,gy,underRect(1))
      end
    end end
    buildingInfo[#buildingInfo+1]={minX=6,minY=0,maxX=16,maxY=6,cells=74,
      groundY=gy,wallTopY=top,wallHeight=2.5,wallRows=3,sourceFacadePixels=40,
      roofMode='native-indigo-cropped-roof',roofMid=761,flatRoof=true,gable=false,
      roofTris=88,windows={},doors={{x=11,z=6,wx=11.5,wz=7.002,y=gy,w=1,h=1,face='south'}},
      depthReconstruction='north clipped; 40px main wall,48px projecting entry',nativeIndigo=true}
  end



  do
    local function isBlockCell(c, bc) return not bc.nativeRail and not bc.nativeDecorativeRest and c and not c.nativeSaffronThin and ((c.blocksForBlob and components[c.compId] == bc) or c.nativeRoute2GateOwner==bc) end
    local function crop(r) return subRect(r, 0.3, 0, 0.7, 1) end
    -- a cell's art: list, rect pairs, back to front
    local function layers(c)
      -- The guarded yellow roof corner keeps its original block volume,
      -- but its roof OVER is emitted by the yellow owner exactly once.
      -- Render the adjoining native Silph side-wall art on this old face.
      c=c.nativeStructuralArt or c
      local out = {}
      local ov = c.hasOver and overRect(c.mid) or nil
      local cov = ov and (overCoverage(c.mid) or 1) or 0
      local base = underRect(c.mid)
      if not (ov and cov >= C.ROOF_SOLID_MIN) and base then out[#out + 1] = { opaque, base } end
      if ov then out[#out + 1] = { cutoutOver, ov } end
      return out
    end
    -- plain wall art for sides / backs: the column's lowest facade cell,
    -- from its over art when that is mostly opaque
    -- r11 (review M6): one side / back tile per block -- the most common
    -- facade tile without over art and without ground texels
    -- (atlas.leafFrac <= SIDE_GROUND_MAX), from the facade rows of the
    -- block's inner columns (the edge columns carry corner art); else a
    -- facade cell's opaque over art; else the column's own facade cell
    local function blockSide(bc)
      if bc.sideArt ~= nil then return bc.sideArt end
      if bc.nativeResidualSideSample then
        local s=bc.nativeResidualSideSample;local r=overRect(s.mid)
        local t=atlas.texels(s.mid,"over")
        assert(r and t and t[s.y*16+s.x+1]>=0,"guarded residual material missing")
        bc.sideArt={cutoutOver,subRect(r,(s.x+.5)/16,(s.y+.5)/16,(s.x+.5)/16,(s.y+.5)/16)}
        bc.plainW=t[s.y*16+s.x+1];bc.sideSrc="plain";return bc.sideArt
      end
      local leafFrac = atlas.leafFrac
      local taint = groundTaint(bc.minX, bc.minY, bc.maxX, bc.maxY)
      local function clean(c)
        if taint then return taint(c.mid) <= C.SIDE_GROUND_MAX end
        return not leafFrac or (leafFrac(c.mid) or 0) <= C.SIDE_GROUND_MAX
      end
      local xa, xb = bc.minX, bc.maxX
      if xb - xa >= 2 then xa, xb = xa + 1, xb - 1 end
      -- search: inner columns' facade rows, then inner columns' any row,
      -- then every column; plain (no over art), clean tiles only
      local function search(x0, x1, facadeOnly)
        local cnt, pick = {}, nil
        for _, run in ipairs(bc.runs) do
          if run.x >= x0 and run.x <= x1 then
            local n = facadeOnly and math.min(run.nf, 2) or (run.yB - run.yT + 1)
            for i = 0, n - 1 do
              local c = at(run.x, run.yB - i)
              if c and c ~= run.fill and not c.isDoor and not c.isSign and not c.hasOver and clean(c) then
                cnt[c.mid] = (cnt[c.mid] or 0) + 1
                if not pick or cnt[c.mid] > cnt[pick.mid] then pick = c end
              end
            end
          end
        end
        return pick
      end
      -- (USER REPORT) the clean plaster column of the bottom facade row's
      -- inner cells, when texels are known
      local tex = type(atlas.texels) == "function" and atlas.texels or nil
      if tex then
        local _, gpal = groundTaint(bc.minX, bc.minY, bc.maxX, bc.maxY)
        local cands, stats = {}, {}
        -- (roofs-sides A: the map's rock palette -- wallRockPalette)
        wallAStats(IN)
        if IN.wallA.rock == nil then IN.wallA.rock = wallRockPalette(at, W, H, atlas.colors, compOf) end
        for _, run in ipairs(bc.runs) do
          local c = at(run.x, run.yB)
          if c == run.fill then c = run.yB - 1 >= run.yT and at(run.x, run.yB - 1) or nil end
          local u = c and tex(c.mid, "under")
          if u then
            local rec = { c = c, u = u, o = c.hasOver and tex(c.mid, "over") or nil,
              d = math.min(run.x - bc.minX, bc.maxX - run.x), edge = run.x == bc.minX or run.x == bc.maxX }
            stats[#stats + 1] = rec
            -- (roofs-sides A, group 3: never a ROCK cell -- a prop rock or a
            -- tile >= half in the rock palette: r4-02, Route 8 K1's rock
            -- column. Not the BUILDING category: the gates are BLOCKED /
            -- CLIFF; not atlas.isRock: it takes Saffron's yellow plaster)
            if run.x >= xa and run.x <= xb and not c.isDoor and not c.isSign and clean(c)
                and not c.rock and wallRockShare(atlas.colors, c.mid, IN.wallA.rock) < 0.5 then
              cands[#cands + 1] = rec
            end
          end
        end
        table.sort(cands, function(p, q)
          if p.d ~= q.d then return p.d < q.d end
          return p.c.x < q.c.x
        end)
        -- r12 (USER: "Pay close attention to roofs and SIDES"): the PLAIN
        -- wall colour of the bottom facade row's inner cells (rows 0-12:
        -- not the base) -- a solid texel, no stripes from the facade
        -- roofs-sides A (CONSOLIDATED groups 2 + 3): through the SHARED WALL
        -- FILTER (wallReject; the roof palette = the run tops' art), with
        -- the buildings' tiers: 2 = every facade row, 3 = every BUILDING
        -- cell (+ the facade row below), 4 = every cell, ground / rock
        -- colours too (never the roof's), 5 = any opaque texel -- a FLAT
        -- colour, never a facade crop (their cut-out art made the holes)
        local bt = { own = {}, roof = {}, n = 0 }
        for _, cd in ipairs(cands) do
          for i = 1, 256 do
            local o = cd.o and cd.o[i]
            if not (o and o >= 0) then bt.own[cd.u[i]] = (bt.own[cd.u[i]] or 0) + 1 end
            bt.n = bt.n + 1
          end
        end
        -- (the roof palette: the TOP cell of each run with roof rows -- a tall
        -- block's upper storeys, drawn in its roof rows, are wall)
