    end
    local windows={}
    for _,w in ipairs(shape.nativeWindowTriangles or{})do windows[#windows+1]={vertices={mapped[w.vertices[1]],mapped[w.vertices[2]],mapped[w.vertices[3]]},glassColors=w.glassColors,layer=w.layer}end
    grid.nativeConnectedHouse.geometry=shape.stats;buildingCount=buildingCount+1
    buildingInfo[#buildingInfo+1]={minX=21,minY=7,maxX=25,maxY=9,cells=15,wallRows=1.25,wallHeight=1.25,
      groundY=base,wallTopY=shape.stats.bodyTop,roofMode="native-connected-gable",nativeBuildingProfile="five-island-connected-house",
      sourceRows={6,9},reconstruction=shape.stats.reconstruction,
      doors={{x=22,z=9,wx=22.5,wz=10,y=base,w=1,h=1,face="south"}},windows={},nativeWindowTriangles=windows,
      eave={x0=20.8,x1=26.2,z0=6.8,z1=10.2}}
    if sevii then
      local info=buildingInfo[#buildingInfo]
      grid.seviiPurpleFinish({maxY=9,groundY=base,wallTopY=base+19/16,nativeBuildingProfile={nativeSeviiPurple=sevii},seviiPurpleStart=seviiStart},info)
      shape.stats.wallRows=1;shape.stats.nativeFacadeHeight=info.nativeFacadeHeight;shape.stats.bodyTop=info.bodyTopY;shape.stats.roofTop=info.crownTopY;shape.stats.nativeSeviiPurple=true
      shape.stats.reconstruction='shared native spined hip and clean hidden siding; original connected lowerfront/door retained'
      info.reconstruction=shape.stats.reconstruction;info.roofMode='native-sevii-connected-spined-hip';info.wallRows=1
    end
  end
  -- One connected landmark owner. Route10 consumes projected source art
  -- but the physical7x7 body belongs only to Lavender's native footprint.
  if grid.nativeTower and input.mapId==grid.nativeTower.source.owner then
    local q,T=grid.nativeTower.source,grid.nativeTower.module
    local c=at(18,6)
    local base=c and c.hgt or 0
    local shape=T.geometry(q,atlas,base,deps.yieldSafe)
    local mapped={}
    for _,entry in ipairs{{"opaque",opaque},{"cutoutUnder",cutoutUnder},{"cutoutOver",cutoutOver},{"cutoutKeyed",cutoutKeyed}}do
      for _,v in ipairs(shape[entry[1]])do vN(entry[2],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8]);mapped[v]=entry[2][#entry[2]]end
    end
    grid.nativeTower.geometry=shape.stats
    local windows={}
    for _,w in ipairs(shape.nativeWindowTriangles or{})do windows[#windows+1]={vertices={mapped[w.vertices[1]],mapped[w.vertices[2]],mapped[w.vertices[3]]},glassColors=w.glassColors,layer=w.layer}end
    buildingCount=buildingCount+1
    buildingInfo[#buildingInfo+1]={minX=15,minY=0,maxX=21,maxY=6,cells=49,
      wallRows=9.25,wallHeight=9.25,groundY=base,wallTopY=shape.stats.bodyTop,
      roofMode="native-connected-dome-spire",nativeBuildingProfile="pokemon-tower-connected-native",
      sourceRows={-8,6},reconstruction=shape.stats.reconstruction,
      doors={{x=18,z=6,wx=18.5,wz=7,y=base,w=1,h=1,face="south"}},windows={},nativeWindowTriangles=windows,eave={x0=15,x1=22,z0=0,z1=7}}
  end
  -- Admitted missing banks reuse the one pre-M1 native descriptor.
  (function()
    local profile=grid.nativeNuggetBankProfile;if not profile then return end
    grid.nativeNuggetBankFaces={}
    for _,q in ipairs(profile.faces)do
      local x,z,dir,donor=q[1],q[2],q[3],q[4]
      local r=underRect(donor);local ax=math.floor(r[1]*atlas.w);local ay=math.floor(r[2]*atlas.h)
      local function u(col)return(ax+col+.5)/atlas.w end
      local function v(row)return(ay+row+.5)/atlas.h end
      local first=#opaque+1
      if dir=='W'then
        quadN(opaque,x,.6,z,u(15),v(0),x,.6,z+1,u(15),v(15),x,.75,z+1,u(13),v(15),x,.75,z,u(13),v(0),-1,0,0)
      else
        quadN(opaque,x+1,.6,z,u(15),v(1),x,.6,z,u(0),v(1),x,.75,z,u(0),v(0),x+1,.75,z,u(15),v(0),0,0,-1)
      end
      grid.nativeNuggetBankFaces[#grid.nativeNuggetBankFaces+1]={x=x,z=z,dir=dir,donor=donor,first=first,last=#opaque}
    end
  end)()

  grid.networkFinish()
  grid.emitBikeShopBikes()
  grid.saffronGateFinish()
  grid.dojoFrontFinish(buildingInfo)
  grid.saffronHouseFinal(buildings)

  if grid.saffronHouseReady and grid.saffronHiddenTemplate then
    local template=grid.saffronHiddenTemplate
    for li,list in ipairs{opaque,cutoutUnder,cutoutOver,cutoutKeyed}do for _,v in ipairs(template.lists[li])do local q={};for k,val in pairs(v)do q[k]=val end;q[1]=q[1]-20;q.nativeObscuredSaffronHouse=true;q.nativeSaffronHouseOwner='26,18';q.nativeSaffronHouseSide=v.nativeSaffronHouseSide and '26,18'or nil;list[#list+1]=q end end
    local src=template.info
    buildingInfo[#buildingInfo+1]={id='SAFFRON_MIDDLE_WEST_GREEN_3',minX=26,maxX=29,minY=18,maxY=21,groundY=src.groundY,wallTopY=src.wallTopY,wallHeight=src.wallHeight,wallRows=src.wallRows,roofMode=src.roofMode,roofMid=src.roofMid,roofTris=src.roofTris,
      sideSrc='native-emerald-panel-post-course',nativeSaffronHouseSides=true,nativeObscuredHouse=true,doors={{x=27,z=21,wx=27.5,wz=22,y=.75,w=1,h=1,face='south'}},windows={}}
  end

  local tris = (#opaque + #cutoutUnder + #cutoutOver + #cutoutKeyed + #IN.southWalls) / 3
  local ms
  local t1 = clock()
  if t0 and t1 then ms = (t1 - t0) * 1000 end
  if minX == math.huge then minX, maxX, minY, maxY, minZ, maxZ = 0, 0, 0, 0, 0, 0 end

  local minWallHeight, maxWallHeight
  for _, comp in ipairs(buildings) do
    deps.yieldSafe()
    if not minWallHeight or comp.wallHeight < minWallHeight then minWallHeight = comp.wallHeight end
    if not maxWallHeight or comp.wallHeight > maxWallHeight then maxWallHeight = comp.wallHeight end
  end

  -- M1: per-cell ground heights (compact copy; the closure keeps no grid).
  local hgts = {}
  for y = 0, H - 1 do
    for x = 0, W - 1 do
      local c = grid[y][x]
      if c then hgts[y * W + x + 1] = c.hgt end
    end
  end
  local function heightAt(cx, cy)
    if grid.caveRamps then for _,ci in ipairs(grid.caveRamps)do
      if cx>=ci.x and cx<ci.x+1 and cy>=ci.z and cy<ci.z+1 then
        if ci.northEdge then local q=ci.northEdge;local t=(cy-ci.z)/q.width;if t>=1 then return ci.south end;local f=t*4;local i=math.min(4,math.floor(f)+1);return q.samples[i]+(q.samples[i+1]-q.samples[i])*(f-i+1)end
        if ci.shore16 then local i=math.floor((cy-ci.z)*16)*16+math.floor((cx-ci.x)*16)+1;return ci.shore16:sub(i,i)=="1" and ci.north or ci.south end
        return ci.north+(ci.south-ci.north)*(cy-ci.z)
      end
    end end
    cx, cy = math.floor(cx), math.floor(cy)
    if cx < 0 or cy < 0 or cx >= W or cy >= H then return nil end
    return hgts[cy * W + cx + 1]
  end

  -- ---------------------------------------------------------------
  -- r12 (DS-hook report 3, "per-vertex AO ... costs nothing at draw time"):
  -- GROUND-CONTACT AMBIENT OCCLUSION baked per vertex (a light
  -- multiplier, 1 = open) -- in geom.ao.opaque[i] / geom.ao.cutoutUnder[i],
  -- one per entry of those lists (the vertex contract stays 8 fields; other
  -- lists are open: 1). Steep faces (walls, ledge fronts, rock slopes;
  -- ny < 0.7) darken toward their foot: 1 - AO_WALL x (1 - height above
  -- the lowest ground touching the point / AO_WALL_H)^2. Upward ground
  -- darkens beside a solid or a step AO_FLOOR_STEP up (wall bases, ledge
  -- feet, rock crevices): 1 - AO_FLOOR x (1 - distance to that edge)^2.
  -- A renderer attribute can read it (Mesh:attachAttribute); the renderer
  -- ignores it until it does.
  -- (inner function: locals limit)
  -- (OFF by default -- ~15 ms JIT-off on Berry Forest for data no
  -- renderer reads yet: C.AO_BAKE or deps.aoBake turns it on)
  grid.aoStats = (C.AO_BAKE or deps.aoBake) and (function()
    local n, dark, minAo = 0, 0, 1
    -- per cell: blk = bit flags of the sides with a solid / a step up
    -- (1 W, 2 E, 4 N, 8 S), for the floor term
    -- g9 = the lowest ground of a cell and its 8 neighbours: a steep
    -- vertex AO_WALL_H above it is open (the exact foot test is skipped)
    local blk, g9 = {}, {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        local k = y * W + x + 1
        local best
        for qy = mmax(0, y - 1), mmin(H - 1, y + 1) do
          for qx = mmax(0, x - 1), mmin(W - 1, x + 1) do
            local h = hgts[qy * W + qx + 1]
            if h and (not best or h < best) then best = h end
          end
        end
        g9[k] = best
        local f = 0
        if c and c.hgt then
          for _, d in ipairs(DIRS) do
            local nc = at(x + d.dx, y + d.dy)
            if nc and ((not nc.walkable and not nc.isWater) or (nc.hgt or 0) > c.hgt + C.AO_FLOOR_STEP) then
              f = f + (d.dx < 0 and 1 or d.dx > 0 and 2 or d.dy < 0 and 4 or 8)
            end
          end
        end
        blk[k] = f
      end
    end
    local AW, AWH, AF = C.AO_WALL, C.AO_WALL_H, C.AO_FLOOR
    local function floorAo(t, a)
      if t > 0 then
        local o = 1 - AF * t * t
        if o < a then return o end
      end
      return a
    end
    local out = {}
    for _, nm in ipairs({ "opaque", "cutoutUnder" }) do
      local L = nm == "opaque" and opaque or cutoutUnder
      local A = {}
      out[nm] = A
      for i = 1, #L do
        local v = L[i]
        do
          local x, z = v[1], v[3]
          local cx, cz = mfloor(x), mfloor(z)
          local a = 1
          if cx >= 0 and cz >= 0 and cx < W and cz < H then
            local k = cz * W + cx + 1
            if v[7] < 0.7 and g9[k] and v[2] - g9[k] < AWH then
              -- (the lowest ground of the cells touching the point: a face's
              -- foot on an upper terrace measures from that terrace)
              local g
              local xa, xb, za, zb = mfloor(x - 1e-4), mfloor(x + 1e-4), mfloor(z - 1e-4), mfloor(z + 1e-4)
              for qz = za, zb do
                if qz >= 0 and qz < H then
                  for qx = xa, xb do
                    if qx >= 0 and qx < W then
                      local h = hgts[qz * W + qx + 1]
                      if h and (not g or h < g) then g = h end
                    end
                  end
                end
              end
              if g then
                local t = 1 - (v[2] - g) / AWH
                if t > 0 then
                  if t > 1 then t = 1 end
                  a = 1 - AW * t * t
                end
              end
            elseif v[7] >= 0.7 then
              local f = blk[k]
              if f > 0 then
                if f % 2 == 1 then a = floorAo(1 - (x - cx), a) end
                if f % 4 >= 2 then a = floorAo(x - cx, a) end
                if f % 8 >= 4 then a = floorAo(1 - (z - cz), a) end
                if f >= 8 then a = floorAo(z - cz, a) end
              end
            end
          end
          A[i] = a
          n = n + 1
          if a < 0.999 then dark = dark + 1 end
          if a < minAo then minAo = a end
        end
      end
    end
    return { verts = n, darkened = dark, min = minAo, lists = out }
  end)()

  -- debug (w3/tools/bld_map.lua): every blocking component as detected
  local componentInfo, cellComp
  if deps.debugComponents then
    cellComp = {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        local comp = c and c.blocksForBlob and components[c.compId]
        if comp then cellComp[y * W + x + 1] = tostring(comp.kind) .. comp.id end
      end
    end
    componentInfo = {}
    for _, comp in ipairs(compList) do
      local nm, cats = 0, {}
      for _ in pairs(comp.mids) do nm = nm + 1 end
      for _, c in ipairs(comp.cells) do
        local k = tostring(c.category)
        cats[k] = (cats[k] or 0) + 1
      end
      local cs = {}
      for k, v in pairs(cats) do cs[#cs + 1] = k .. ":" .. v end
      table.sort(cs)
      componentInfo[#componentInfo + 1] = { minX = comp.minX, minY = comp.minY, maxX = comp.maxX, maxY = comp.maxY,
        count = comp.count, mids = nm, diversity = comp.diversity or 0, kind = comp.kind, treeArt = comp.treeArt,
        cats = table.concat(cs, ",") }
    end
  end

  local propShapes
  if deps.debugProps then
    propShapes = {}
    for y = 0, H - 1 do
      for x = 0, W - 1 do
        local c = grid[y][x]
        if c and c.propShape then propShapes[y * W + x + 1] = c.propShape end
      end
    end
  end

  return {
    signFaces = IN.signFaces or {}, -- Readable native board planes whose textures were prepared
    opaque = opaque,
    cutoutUnder = cutoutUnder,
    cutoutOver = cutoutOver,
    cutoutKeyed = cutoutKeyed,
    southWalls = IN.southWalls, -- r12 (R6): synthetic interior south walls, opaque shader
    retroGrassCells = IN.flora and IN.flora.retroGrassCells or {},
    roomShell = IN.interiors and IN.interiors.out or nil, -- interiors-team (contract V2.14, build/core/API.md)
    ao = grid.aoStats and grid.aoStats.lists, -- r12: ground-contact AO per list entry (opaque, cutoutUnder)
    heightAt = heightAt,
    supportRamps = grid.caveRamps,
    shrubCards = grid.nativeShrubCards,
    shadowOpaque = grid.shrubShadowOpaque,
    treeOccluders = treeOccluders,
    frVoxelTrees = IN.voxelTrees and IN.voxelTrees:output() or nil,
    bounds = { minX = minX, minY = minY, minZ = minZ, maxX = maxX, maxY = maxY, maxZ = maxZ },
    stats = {
      tris = tris, ms = ms, buildings = buildingCount, props = propCount,
      minWallHeight = minWallHeight, maxWallHeight = maxWallHeight,
      buildingInfo = buildingInfo, roofless = roofless,
      nativeIndigoArches = grid.nativeIndigoArches,
      saffronGateEntries=grid.saffronGateEntries,
      nativeGrayGate = grid.nativeGrayGate and {claimed=grid.nativeGrayGate.claimed,geometry=grid.nativeGrayGate.geometry}or nil,
      nativeConnectedHouse = grid.nativeConnectedHouse and {claimed=grid.nativeConnectedHouse.claimed,owner=grid.nativeConnectedHouse.source.owner,emitted=grid.nativeConnectedHouse.geometry~=nil,geometry=grid.nativeConnectedHouse.geometry} or nil,
      nativeTower = grid.nativeTower and {claimed=grid.nativeTower.claimed,owner=grid.nativeTower.source.owner,emitted=grid.nativeTower.geometry~=nil,geometry=grid.nativeTower.geometry} or nil,
      propShapes = propShapes, componentInfo = componentInfo, cellComp = cellComp,
      grid = deps.debugGrid and grid or nil, -- (debug: w3 probes read the cell grid)
      blocks = #blocks, blockInfo = blockInfo, -- r11
      rockColumns = rockOut, rampCells = grid.rampCells, boulders = grid.boulders or 0, hillBase = grid.hillBase, rampInfo = grid.rampInfo, ledgeEnds = grid.ledgeEnds, hillBands = grid.bandStat, bandCells = grid.bandCells, bandEnds = grid.bandEnds, weldMiss = grid.weldMiss or 0, ao = grid.aoStats and { verts = grid.aoStats.verts, darkened = grid.aoStats.darkened, min = grid.aoStats.min }, ledgeCensus = grid.census, ledgeLip = grid.ledgeLipStat, splitPieces = splitPieces, blobTrunks = blobTrunks, fencePosts = fencePosts, flowerCells = flowerCells, -- r11
      treeUnits = #units - singleCount, singleTrees = singleCount, treeTris = treeTris,
      seamUnits = seamUnits, seamNoCrown = seamNoCrown, -- r9 (review 5)
      treeUnitMaxTris = treeUnitMaxTris, edgeUnits = edgeUnits, trunks = trunks, -- r9 Part B
      grassCells = keyedGrass, fenceCells = fenceCells, signs = signCount,
      compiledShrubs = grid.compiledShrubs and grid.compiledShrubs.stats or nil,
      nativeFoliage = IN.nativeFoliage and IN.nativeFoliage.stats or nil,
      flora = IN.flora and IN.flora.stats or nil, -- W7
      -- r8
      kind = input.kind, voidCells = voidCount, indoorBorderCleared = indoorBorderCleared,
      indoor = indoor and indoorStats or nil, rockCells = rockCells, farTrees = farTrees,
      cave = cave and IN.caveStats or nil, -- r12 (W3-I): boulders, chamfers, quarterCells, faceBottoms
      wallA = IN.wallA and IN.wallA.stats or nil, -- roofs-sides A: side-wall filter record (sideFallback = 0)
      lists = { opaque = #opaque / 3, cutoutUnder = #cutoutUnder / 3,
                cutoutOver = #cutoutOver / 3, cutoutKeyed = #cutoutKeyed / 3, southWalls = #IN.southWalls / 3 },
    },
  }
end

return M


